window.SCHOOL_LISTENING={"../assets/media/d446229289b24c085594bf52a62b534178518782fcfc56f8bdcd622f4428010d.mp3":[{"id":"PPT_d446229289b24c08","audioId":"PPT_d446229289b24c08","title":"Book 3 · Unit 7 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 236","duration":77.87,"cues":[{"start":0.0,"end":3.08,"text":"seven point three one","coverage":1.0},{"start":3.62,"end":4.54,"text":"a","coverage":1.0},{"start":5.12,"end":6.62,"text":"That's amazing","coverage":1.0},{"start":8.02,"end":8.9,"text":"B","coverage":1.0},{"start":9.56,"end":11.92,"text":"That is amazing","coverage":1.0},{"start":13.22,"end":19.36,"text":"two a You've asked me that before you know","coverage":1.0},{"start":20.1,"end":21.5,"text":"B","coverage":1.0},{"start":22.08,"end":26.64,"text":"You have asked me that before you know","coverage":1.0},{"start":27.46,"end":29.68,"text":"three a","coverage":1.0},{"start":30.5,"end":32.78,"text":"I agree that it's not very practical","coverage":1.0},{"start":34.58,"end":35.46,"text":"B","coverage":1.0},{"start":35.98,"end":39.12,"text":"I do agree that it's not very practical","coverage":1.0},{"start":41.56,"end":46.18,"text":"four a I think it'll be interesting","coverage":1.0},{"start":47.6,"end":48.48,"text":"B","coverage":1.0},{"start":49.48,"end":51.86,"text":"I do think it'll be interesting.","coverage":1.0},{"start":52.34,"end":55.4,"text":"I think it will be interesting","coverage":1.0},{"start":57.74,"end":59.5,"text":"five a","coverage":1.0},{"start":60.0,"end":64.26,"text":"I know I look tired, but I've been working very hard","coverage":1.0},{"start":65.44,"end":71.06,"text":"B I know I look tired, but I have been working very hard.","coverage":1.0},{"start":72.52,"end":74.02,"text":"I do know I look tired,","coverage":1.0},{"start":74.44,"end":76.12,"text":"but I've been working very hard","coverage":1.0}],"file":"007ad4900def5d8bf354.js","track":0,"media":"../assets/media/d446229289b24c085594bf52a62b534178518782fcfc56f8bdcd622f4428010d.mp3"}],"../assets/media/b3c6be0b8da06b6266cae7ee916cff735d4946b32885a484b934d5c72411c757.mp3":[{"id":"PPT_b3c6be0b8da06b62","audioId":"PPT_b3c6be0b8da06b62","title":"Book 3 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 29","duration":68.34,"cues":[{"start":0.0,"end":2.28,"text":"three .two","coverage":1.0},{"start":2.28,"end":3.14,"text":"one.","coverage":1.0},{"start":3.92,"end":8.42,"text":"The town hall keeps a record of how many vehicles use this road.","coverage":1.0},{"start":10.44,"end":11.12,"text":"two.","coverage":1.0},{"start":11.92,"end":16.22,"text":"His mum bought him a new car as a present for passing his exams.","coverage":1.0},{"start":18.44,"end":19.12,"text":"three.","coverage":1.0},{"start":20.02,"end":23.58,"text":"I went back to the shop to get a refund on my bus pass.","coverage":1.0},{"start":25.62,"end":26.24,"text":"four.","coverage":1.0},{"start":27.24,"end":32.6,"text":"Each year, the taxi company presents an award to its most careful driver.","coverage":1.0},{"start":34.8,"end":35.42,"text":"five.","coverage":1.0},{"start":36.44,"end":39.74,"text":"Will you promise me that you'll call as soon as your flight lands?","coverage":1.0},{"start":42.37,"end":42.68,"text":"six.","coverage":1.0},{"start":43.8,"end":48.78,"text":"The train company are going to refund the cost of my ticket because of the delays.","coverage":1.0},{"start":50.66,"end":51.38,"text":"seven.","coverage":1.0},{"start":52.52,"end":58.28,"text":"We want to record the traffic noise around the city to see how high it actually is.","coverage":1.0},{"start":59.78,"end":60.5,"text":"eight.","coverage":1.0},{"start":61.4,"end":64.82,"text":"This car is the most comfortable you will ever drive.","coverage":1.0},{"start":65.26,"end":66.38,"text":"That's a promise.","coverage":1.0}],"file":"02ee0fcf1d9bd90d7055.js","track":0,"media":"../assets/media/b3c6be0b8da06b6266cae7ee916cff735d4946b32885a484b934d5c72411c757.mp3"}],"../assets/media/782fa5de91b03488cc8092ca2233806402e311ad70445e53ce867ed41069aab8.mp3":[{"id":"PPT_782fa5de91b03488","audioId":"PPT_782fa5de91b03488","title":"Book 3 · Unit 5 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 92","duration":241.45,"cues":[{"start":0.0,"end":1.62,"text":"five .six","coverage":1.0},{"start":1.62,"end":4.98,"text":"Do you have problems focusing on your work?","coverage":1.0},{"start":5.58,"end":7.16,"text":"Are you under a lot of stress?","coverage":1.0},{"start":8.06,"end":12.38,"text":"Do you want to get more exercise while trying something new and exciting?","coverage":1.0},{"start":13.04,"end":15.92,"text":"If so, it's time to take up taekwondo.","coverage":1.0},{"start":16.46,"end":22.04,"text":"Taekwondo is great exercise and as we all know exercise is good for your health.","coverage":1.0},{"start":22.74,"end":25.34,"text":"Taekwondo also has mental benefits.","coverage":1.0},{"start":25.76,"end":28.66,"text":"It has been shown to improve your concentration.","coverage":1.0},{"start":28.66,"end":30.12,"text":"In addition,","coverage":1.0},{"start":30.48,"end":32.62,"text":"it makes you feel good about yourself.","coverage":1.0},{"start":33.7,"end":38.78,"text":"This martial art was developed in Korea and is now popular around the world.","coverage":1.0},{"start":39.56,"end":41.82,"text":"Whether you are looking for physical well -being,","coverage":1.0},{"start":42.5,"end":45.46,"text":"increased confidence or a life with less stress,","coverage":1.0},{"start":45.92,"end":47.9,"text":"Black Belt Taekwondo has it all.","coverage":1.0},{"start":48.44,"end":53.66,"text":"Sign up now for a free introductory class starting on January the 15th.","coverage":1.0},{"start":54.52,"end":59.08,"text":"Would you like to improve your social life,","coverage":1.0},{"start":59.48,"end":60.94,"text":"your intellectual performance,","coverage":1.0},{"start":61.48,"end":64.82,"text":"your physical fitness and your team building skills?","coverage":1.0},{"start":65.86,"end":70.92,"text":"Scientific research has proven that team sports offer all of these benefits.","coverage":1.0},{"start":71.8,"end":75.9,"text":"Join us and take advantage of the many benefits of team sports.","coverage":1.0},{"start":76.7,"end":83.64,"text":"We're a group of energetic adults of all ages who get together on Sunday afternoons to play football.","coverage":1.0},{"start":83.64,"end":88.22,"text":"And we're always looking for new players to join in the fun.","coverage":1.0},{"start":89.54,"end":93.98,"text":"Whether you've been playing football for years or want to take up a new sport,","coverage":1.0},{"start":94.58,"end":95.94,"text":"you're welcome to participate.","coverage":1.0},{"start":97.38,"end":98.44,"text":"Everyone can play.","coverage":1.0},{"start":98.8,"end":100.7,"text":"You don't even need to try out.","coverage":1.0},{"start":101.64,"end":104.3,"text":"If you're interested in learning more about our group,","coverage":1.0},{"start":104.74,"end":106.42,"text":"check out our website at","coverage":1.0},{"start":109.18,"end":110.46,"text":"www .footballsundays","coverage":1.0},{"start":110.46,"end":111.76,"text":".cup","coverage":1.0},{"start":111.76,"end":113.02,"text":".com","coverage":1.0},{"start":113.64,"end":118.64,"text":"Sign up today and you can be part of a team as early as this weekend.","coverage":1.0},{"start":119.56,"end":121.76,"text":"Hope to see you on the field soon.","coverage":1.0},{"start":124.62,"end":125.12,"text":"Hi,","coverage":1.0},{"start":125.48,"end":129.68,"text":"my name's Angie Stratton and I'm the director of Culture Cycle.","coverage":1.0},{"start":130.54,"end":133.26,"text":"Culture Cycle is a new concept in travel,","coverage":1.0},{"start":134.08,"end":135.78,"text":"educational fitness touring.","coverage":1.0},{"start":136.98,"end":143.04,"text":"We offer courses all over the world which combine learning with exercise and travel.","coverage":1.0},{"start":143.64,"end":150.48,"text":"Each course has an educational theme such as Brazilian cooking or the history of Turkey.","coverage":1.0},{"start":151.44,"end":152.46,"text":"As a small group,","coverage":1.0},{"start":152.98,"end":155.08,"text":"we cycle from place to place,","coverage":1.0},{"start":155.42,"end":158.9,"text":"stopping for several days in each location to rest,","coverage":1.0},{"start":159.36,"end":162.26,"text":"relax and do some hands -on learning.","coverage":1.0},{"start":163.24,"end":169.34,"text":"Not only does this trip provide terrific exercise and a fascinating cultural experience,","coverage":1.0},{"start":169.68,"end":171.5,"text":"it's the best way to learn.","coverage":1.0},{"start":172.16,"end":172.58,"text":"There's","coverage":1.0},{"start":172.58,"end":173.0,"text":"no","coverage":1.0},{"start":173.0,"end":178.12,"text":"question that physical activity improves our memory and thinking skills.","coverage":1.0},{"start":178.72,"end":181.08,"text":"So, after a few days of cycling,","coverage":1.0},{"start":181.7,"end":184.02,"text":"your brain will be ready to learn.","coverage":1.0},{"start":184.76,"end":193.32,"text":"So, be kind to your body and your mind and come with us on an amazing adventure you'll never forget.","coverage":1.0},{"start":195.78,"end":198.54,"text":"Are you interested in alternative treatments?","coverage":1.0},{"start":199.14,"end":203.88,"text":"Have you ever wanted to explore the secrets of traditional Chinese medicine?","coverage":1.0},{"start":204.96,"end":208.88,"text":"This spring, join our six -month course in acupuncture,","coverage":1.0},{"start":209.6,"end":215.94,"text":"a treatment for pain or illness which involves putting needles under the skin at special points on the body.","coverage":1.0},{"start":216.7,"end":222.08,"text":"The course covers the theory of acupuncture and practical skills in using needles.","coverage":1.0},{"start":223.16,"end":225.38,"text":"Acupuncture is known to reduce pain,","coverage":1.0},{"start":226.08,"end":231.82,"text":"but it's also a great alternative for people who want to lose weight in an easy way.","coverage":1.0},{"start":232.62,"end":239.48,"text":"Learn more about the course and visit us on our Open House Days on the first Saturday of every month.","coverage":1.0}],"file":"03d907e01ecf289fb835.js","track":0,"media":"../assets/media/782fa5de91b03488cc8092ca2233806402e311ad70445e53ce867ed41069aab8.mp3"}],"../assets/media/5b663c982b56b04bba763c0c71c244deae17684f8401278c0fa21a97531895d7.mp3":[{"id":"PPT_5b663c982b56b04b","audioId":"PPT_5b663c982b56b04b","title":"Book 3 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 45","duration":251.22,"cues":[{"start":0.0,"end":1.5,"text":"two .two","coverage":1.0},{"start":1.5,"end":2.96,"text":"Good morning.","coverage":1.0},{"start":3.46,"end":11.26,"text":"Today I want to explain some alternative solutions which may help reduce some of the problems related to climate change.","coverage":1.0},{"start":12.28,"end":16.54,"text":"The first solution uses solar energy to grow food in the desert.","coverage":1.0},{"start":17.62,"end":20.86,"text":"First of all I'll explain how farming in the desert works.","coverage":1.0},{"start":21.52,"end":28.76,"text":"Then we'll briefly discuss how this type of farming could solve some of the environmental problems we are facing.","coverage":1.0},{"start":29.32,"end":32.12,"text":"We'll discuss some possible problems with this system.","coverage":1.0},{"start":33.02,"end":33.46,"text":"So,","coverage":1.0},{"start":34.32,"end":35.26,"text":"how does it work?","coverage":1.0},{"start":36.3,"end":37.34,"text":"As we all know,","coverage":1.0},{"start":37.74,"end":40.92,"text":"in order to grow plants we need water and sunlight.","coverage":1.0},{"start":41.58,"end":43.4,"text":"There's a lot of sunlight in the desert,","coverage":1.0},{"start":43.7,"end":44.98,"text":"but very little water.","coverage":1.0},{"start":45.84,"end":51.78,"text":"Scientists have combined solar energy with a farming technology called hydroponics.","coverage":1.0},{"start":52.8,"end":55.72,"text":"Hydroponics means growing plants in water.","coverage":1.0},{"start":56.66,"end":58.76,"text":"Plants don't need to grow in the ground,","coverage":1.0},{"start":59.36,"end":61.96,"text":"but they do need nutrients to help them grow.","coverage":1.0},{"start":63.0,"end":65.26,"text":"Nutrients are like food for the plants.","coverage":1.0},{"start":66.02,"end":66.54,"text":"So,","coverage":1.0},{"start":66.88,"end":69.02,"text":"if you add the nutrients to water,","coverage":1.0},{"start":69.5,"end":71.86,"text":"you can grow fruit and vegetables in water.","coverage":1.0},{"start":72.9,"end":82.04,"text":"NASA scientists have been developing this method of growing food because it could allow us to grow food in any climate – in Antarctica,","coverage":1.0},{"start":82.72,"end":83.9,"text":"the Sahara desert,","coverage":1.0},{"start":84.28,"end":85.6,"text":"or even on Mars.","coverage":1.0},{"start":86.8,"end":91.76,"text":"You might ask how this method of growing plants helps with the problem of climate change.","coverage":1.0},{"start":92.2,"end":96.6,"text":"I mean, after all it uses fresh water, which is a limited resource.","coverage":1.0},{"start":97.78,"end":99.08,"text":"An Australian company,","coverage":1.0},{"start":99.42,"end":100.46,"text":"Sun Drop Farms,","coverage":1.0},{"start":101.06,"end":103.96,"text":"combined hydroponics with solar energy.","coverage":1.0},{"start":104.7,"end":110.04,"text":"Traditional farming uses between 60 and 80 % of our planet's fresh water.","coverage":1.0},{"start":110.52,"end":111.08,"text":"However,","coverage":1.0},{"start":111.52,"end":114.52,"text":"Sun Drop Farms doesn't use fresh water.","coverage":1.0},{"start":114.96,"end":116.88,"text":"It uses seawater.","coverage":1.0},{"start":117.4,"end":121.26,"text":"Sun Drop Farms is only 100 metres from the shore.","coverage":1.0},{"start":122.26,"end":128.0,"text":"A line of mirrors reflects heat from the sun onto a pipe which has oil inside.","coverage":1.0},{"start":129.04,"end":132.1,"text":"The hot oil in the pipe heats up seawater,","coverage":1.0},{"start":132.52,"end":134.56,"text":"which is kept in special containers.","coverage":1.0},{"start":135.78,"end":139.24,"text":"When the seawater reaches 160 degrees Celsius,","coverage":1.0},{"start":139.84,"end":141.78,"text":"the steam provides electricity.","coverage":1.0},{"start":142.72,"end":147.54,"text":"Some of the hot water is used to heat the greenhouse during the cold desert nights.","coverage":1.0},{"start":148.38,"end":150.22,"text":"The plants grow in the greenhouse,","coverage":1.0},{"start":150.76,"end":153.56,"text":"a building with glass walls and a glass ceiling.","coverage":1.0},{"start":154.72,"end":158.74,"text":"The rest of the heated water goes to a desalination plant.","coverage":1.0},{"start":160.08,"end":166.24,"text":"Desalination is when we remove the salt from seawater to create drinkable water.","coverage":1.0},{"start":166.62,"end":170.28,"text":"That is water which is clean and safe to drink.","coverage":1.0},{"start":171.46,"end":178.26,"text":"The desalination plant can produce up to ten ,000 litres of fresh water every day.","coverage":1.0},{"start":179.14,"end":184.5,"text":"The farmer adds nutrients to this fresh water and then grows fruit and vegetables.","coverage":1.0},{"start":185.56,"end":186.74,"text":"To summarise,","coverage":1.0},{"start":187.14,"end":195.58,"text":"solar energy removes the salt from the seawater and the fresh water is then used inside the greenhouse where the plants are growing.","coverage":1.0},{"start":197.1,"end":201.0,"text":"Many people around the world are really excited about this technology.","coverage":1.0},{"start":201.72,"end":202.54,"text":"So far,","coverage":1.0},{"start":203.14,"end":205.14,"text":"Australian farms have grown tomatoes,","coverage":1.0},{"start":205.56,"end":209.28,"text":"peppers and cucumbers using hydroponics.","coverage":1.0},{"start":210.54,"end":217.34,"text":"Many supermarkets are interested in buying these vegetables because they are grown without pesticides or other chemicals.","coverage":1.0},{"start":218.3,"end":224.24,"text":"Some people think hydroponics is the perfect solution to the world food crisis.","coverage":1.0},{"start":225.24,"end":225.72,"text":"Finally,","coverage":1.0},{"start":226.48,"end":231.2,"text":"the desert farms use solar energy and not fossil fuels.","coverage":1.0},{"start":231.86,"end":234.98,"text":"Thus, their negative effect on the environment is minimal.","coverage":1.0},{"start":236.02,"end":236.8,"text":"Now, of course,","coverage":1.0},{"start":237.16,"end":239.3,"text":"the future of hydroponics is unknown.","coverage":1.0},{"start":239.78,"end":245.42,"text":"But I think the desert farms might be a very interesting way to farm in the future.","coverage":1.0},{"start":246.46,"end":249.24,"text":"Now, let's discuss some of the problems.","coverage":1.0}],"file":"040a0fedb951ed89722b.js","track":0,"media":"../assets/media/5b663c982b56b04bba763c0c71c244deae17684f8401278c0fa21a97531895d7.mp3"}],"../assets/media/7fdb1cf59e68d8e2407318387798adc08cc8cabf92e18667ce7ce92397c2c96f.wav":[{"id":"B2_U01_T1.3_LONG_L02_v01","audioId":"B2_U01_T1.3_LONG_L02_v01","title":"Book 2 · Unit 1 · 课后听力材料","subtitle":"Homework listening material","duration":73.49657596371883,"cues":[{"start":0,"end":3.64,"text":"First of all, let’s look at some of the positives.","coverage":1.0},{"start":4.83,"end":7.91,"text":"Obviously, Stanley Park is a large park.","coverage":1.0},{"start":8.27,"end":17.46,"text":"In fact, because it is located in the city of Vancouver, it is the third largest urban park in North America.","coverage":1.0},{"start":17.9,"end":29.25,"text":"It has many gardens, walking paths, trees and even animals, such as bald eagles, coyotes and seals.","coverage":0.882},{"start":29.95,"end":34.45,"text":"As we know, lots of trees help clean the city air.","coverage":1.0},{"start":35.12,"end":42.32,"text":"Also, lots of parks give people many places to walk, so they’re healthier.","coverage":1.0},{"start":42.68,"end":52.29,"text":"Since Vancouver is near the mountains and the ocean, people can enjoy the outdoors easily during the warm, sunny summers.","coverage":1.0},{"start":52.62,"end":72.31,"text":"When people go to Stanley Park, they can enjoy ancient trees as they walk near the ocean or they can have fun by Beaver Lake, which, like Stanley Park, helps make Vancouver one of the healthiest and cleanest cities in the world.","coverage":0.952}],"file":"052692bffcbae9029652.js","track":0,"media":"../assets/media/7fdb1cf59e68d8e2407318387798adc08cc8cabf92e18667ce7ce92397c2c96f.wav"}],"../assets/media/ce15e50632d93ec015711411fcefb7d65bd2040ec1877f30ae5b6bd5a051bfe0.mp3":[{"id":"B2_U02_T2.1_SHORT_S01_v01","audioId":"B2_U02_T2.1_SHORT_S01_v01","title":"Book 2 · Unit 2 · 课后听力材料","subtitle":"Homework listening material","duration":56.4778,"cues":[{"start":0.22,"end":4.0,"text":"Unit 2, 2.1","coverage":1.0},{"start":5.22,"end":13.09,"text":"Reporter 1: Today I’m at the Vivid Sydney festival, which has been held in Australia every year since 2009.","coverage":0.85},{"start":14.24,"end":17.71,"text":"It’s held for three weeks during May and June.","coverage":1.0},{"start":18.0,"end":23.6,"text":"It has loads of activities with music, food, art and learning.","coverage":1.0},{"start":24.51,"end":29.57,"text":"Anybody can go to the lectures, see the lights and eat interesting food.","coverage":0.923},{"start":30.0,"end":31.59,"text":"Many activities are free.","coverage":1.0},{"start":31.99,"end":38.69,"text":"The festival gets bigger every year; sometimes over two million people come.","coverage":1.0},{"start":39.11,"end":42.68,"text":"We asked one of the visitors about the festival.","coverage":0.889},{"start":43.0,"end":44.52,"text":"Hello, there.","coverage":1.0},{"start":45.0,"end":51.57,"text":"Can you introduce yourself and tell me, is this your first time at the festival here in Sydney?","coverage":1.0},{"start":52.22,"end":55.8,"text":"Olivia: My name is Olivia, and no, I come here every year!","coverage":0.917}],"file":"05c757cc5b6769aabe03.js","track":0,"media":"../assets/media/ce15e50632d93ec015711411fcefb7d65bd2040ec1877f30ae5b6bd5a051bfe0.mp3"}],"../assets/media/70bd8eca843802fecbb95b1b68119e1006c56d81d5d7997d66101a9e2dd7ef05.wav":[{"id":"B2_U05_T5.2_LONG_L01_v01","audioId":"B2_U05_T5.2_LONG_L01_v01","title":"Book 2 · Unit 5 · H3 · 听力材料 1","subtitle":"H3 · L01","duration":94.35535147392291,"cues":[{"start":0.22,"end":9.66,"text":"Amina: For my project I looked at some unusual sports that people play around the world.","coverage":0.938},{"start":10.12,"end":15.0,"text":"I’d like to start by talking about ‘chess boxing’.","coverage":1.0},{"start":15.26,"end":18.0,"text":"You may already know about the two sports.","coverage":1.0},{"start":18.28,"end":23.0,"text":"Chess is a game played with a board and different chess pieces.","coverage":1.0},{"start":23.28,"end":31.47,"text":"Very intelligent people often play this game because players need to think very carefully.","coverage":1.0},{"start":32.28,"end":36.4,"text":"Boxing is a totally different kind of sport, though.","coverage":1.0},{"start":37.28,"end":42.6,"text":"Being strong is more important because boxers have to hit each other.","coverage":0.917},{"start":43.28,"end":48.6,"text":"They wear gloves and helmets in the ring, but it’s still difficult.","coverage":1.0},{"start":49.28,"end":57.71,"text":"Now, chess boxing is a new type of sport, where the players do both activities.","coverage":1.0},{"start":58.28,"end":71.61,"text":"They start with boxing, sorry, I mean chess, and then do some boxing, and they continue doing each activity back and forth – alternating.","coverage":1.0},{"start":72.28,"end":79.53,"text":"The person who wins the boxing match or the chess game first is the champion.","coverage":1.0},{"start":80.28,"end":87.54,"text":"One benefit of this sport is that it gives people a chance to compete physically and mentally.","coverage":0.941},{"start":88.28,"end":94.355,"text":"It isn’t just thinking or physical activity; it’s both.","coverage":1.0}],"file":"0729ffac210b05f5084d.js","track":0,"media":"../assets/media/70bd8eca843802fecbb95b1b68119e1006c56d81d5d7997d66101a9e2dd7ef05.wav"}],"../assets/media/2a080748d381205b942c1e85a8ce0e9189fa171570f5ba4c4edde289069c3453.wav":[{"id":"B2_U05_T5.2_LONG_L02_v01","audioId":"B2_U05_T5.2_LONG_L02_v01","title":"Book 2 · Unit 5 · H3 · 听力材料 2","subtitle":"H3 · L02","duration":99.12269841269841,"cues":[{"start":0,"end":4.78,"text":"Another sport that challenges people is urban golf.","coverage":1.0},{"start":5.83,"end":13.52,"text":"Urban golf is similar to normal golf, but you don’t need to go to a golf course.","coverage":1.0},{"start":13.98,"end":23.29,"text":"You get clubs and a golf ball – well, actually, it’s a soft tennis ball instead of a hard golf ball.","coverage":1.0},{"start":23.68,"end":30.03,"text":"Then you can play in the street, which is why it’s called ‘urban’.","coverage":1.0},{"start":30.56,"end":36.9,"text":"If you play urban golf, you don’t need to go anywhere special or need much money to play.","coverage":1.0},{"start":37.21,"end":45.56,"text":"You just agree where you want to hit the ball, for example, at a sign in the street or a rubbish bin.","coverage":1.0},{"start":46.11,"end":57.46,"text":"On the other hand, intelligent players know that you may break something if you hit the ball too hard, so they try to play fairly carefully.","coverage":1.0},{"start":58.14,"end":70.88,"text":"Next, I’d like to talk about the Moroccan desert footrace, which is also called the Marathon des Sables or the Sahara Marathon.","coverage":0.826},{"start":72.16,"end":79.56,"text":"This race is held every year over a week or rather over six days.","coverage":1.0},{"start":80.11,"end":82.53,"text":"The runners have to be really strong.","coverage":1.0},{"start":82.84,"end":88.78,"text":"On the longest day, the runners have to run 92 kilometres.","coverage":0.909},{"start":90.31,"end":98.11,"text":"The best thing about it is that the champion can say he, or she, has won the hardest marathon in the world.","coverage":1.0}],"file":"0729ffac210b05f5084d.js","track":1,"media":"../assets/media/2a080748d381205b942c1e85a8ce0e9189fa171570f5ba4c4edde289069c3453.wav"}],"../assets/media/ad3dd7f86df49ff1ac68b0751d2f3c7a5866640f7387f4ca78784dd2330e3481.mp3":[{"id":"PPT_ad3dd7f86df49ff1","audioId":"PPT_ad3dd7f86df49ff1","title":"Book 2 · Unit 3 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 93","duration":20.24,"cues":[{"start":0.0,"end":2.0,"text":"three .four","coverage":1.0},{"start":3.42,"end":4.38,"text":"one","coverage":1.0},{"start":5.58,"end":10.36,"text":"You will hear the main ideas and some additional information","coverage":1.0},{"start":12.2,"end":13.16,"text":"two","coverage":1.0},{"start":13.84,"end":18.32,"text":"You will hear the main ideas as well as some additional information","coverage":1.0}],"file":"073e0c29f3919ddd9143.js","track":0,"media":"../assets/media/ad3dd7f86df49ff1ac68b0751d2f3c7a5866640f7387f4ca78784dd2330e3481.mp3"}],"../assets/media/4a6acc4209ab338f712c6ceec4d357ccc58dc2b88e454324e7ff578d2dfbc390.mp3":[{"id":"B2_U06_T6.3_SHORT_S01_v01","audioId":"B2_U06_T6.3_SHORT_S01_v01","title":"Book 2 · Unit 6 · 课后听力材料","subtitle":"Homework listening material","duration":37.068821,"cues":[{"start":0.0,"end":4.44,"text":"Narrator: 6.3 Professor Gould: OK, Alika."},{"start":5.02,"end":6.76,"text":"Should we look at your project now?","coverage":1.0},{"start":7.22,"end":7.42,"text":"Alika: Yes, OK.","coverage":0.333},{"start":9.18,"end":12.58,"text":"Professor Gould: You’ve done a lot of reading for this, which is great.","coverage":0.857},{"start":13.0,"end":15.73,"text":"I can see you wrote a lot of information down.","coverage":1.0},{"start":16.22,"end":20.43,"text":"Alika: Yes, but I haven’t finished yet - I ran out of time.","coverage":0.923},{"start":21.22,"end":26.67,"text":"But I read as much as I could - about 103 different reports.","coverage":1.0},{"start":27.09,"end":32.0,"text":"I took part in the discussions on this with students from my study group.","coverage":1.0},{"start":32.11,"end":34.64,"text":"I studied the way people work.","coverage":1.0},{"start":35.23,"end":36.09,"text":"Professor Gould: Good.","coverage":0.333}],"file":"07f287fd97955e61dd73.js","track":0,"media":"../assets/media/4a6acc4209ab338f712c6ceec4d357ccc58dc2b88e454324e7ff578d2dfbc390.mp3"}],"../assets/media/464b406179d1a7b42b95959dd64c71701f2b51389ff0153a2756dc7a726fb0c9.mp3":[{"id":"PPT_464b406179d1a7b4","audioId":"PPT_464b406179d1a7b4","title":"Book 3 · Unit 4 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 87","duration":67.16,"cues":[{"start":0.0,"end":1.42,"text":"four .nine","coverage":1.0},{"start":1.42,"end":2.64,"text":"one","coverage":1.0},{"start":3.55,"end":5.38,"text":"I couldn't agree more.","coverage":1.0},{"start":7.78,"end":8.64,"text":"two","coverage":1.0},{"start":9.53,"end":14.6,"text":"How did this whole gift -giving -for -every -holiday tradition get started anyway?","coverage":1.0},{"start":15.02,"end":16.5,"text":"It seems silly to me.","coverage":1.0},{"start":18.84,"end":19.7,"text":"three","coverage":1.0},{"start":20.79,"end":21.66,"text":"I agree.","coverage":1.0},{"start":21.96,"end":24.26,"text":"I get tired of shopping for gifts.","coverage":1.0},{"start":26.64,"end":27.5,"text":"four","coverage":1.0},{"start":28.4,"end":29.72,"text":"I disagree.","coverage":1.0},{"start":30.38,"end":32.86,"text":"I like giving gifts.","coverage":1.0},{"start":36.26,"end":40.92,"text":"But I'm not convinced because then you have to spend money,","coverage":1.0},{"start":41.34,"end":45.02,"text":"money which could be spent on more important things.","coverage":1.0},{"start":47.94,"end":48.66,"text":"six","coverage":1.0},{"start":49.46,"end":50.18,"text":"Instead,","coverage":1.0},{"start":50.5,"end":53.04,"text":"why not write letters of advice for the future?","coverage":1.0},{"start":53.2,"end":54.78,"text":"That would be more special.","coverage":1.0},{"start":57.22,"end":57.86,"text":"seven","coverage":1.0},{"start":59.32,"end":59.96,"text":"Sorry,","coverage":1.0},{"start":60.46,"end":61.4,"text":"I don't agree.","coverage":1.0},{"start":61.86,"end":65.24,"text":"I doubt that graduates will be happy if we change that custom.","coverage":1.0}],"file":"096c8153d18a6ca9dfd9.js","track":0,"media":"../assets/media/464b406179d1a7b42b95959dd64c71701f2b51389ff0153a2756dc7a726fb0c9.mp3"}],"../assets/media/6fd93a8c4baaf5d14e28bce8b3a1ec1e2d99eb57f241e04d230e333302e56647.mp3":[{"id":"PPT_6fd93a8c4baaf5d1","audioId":"PPT_6fd93a8c4baaf5d1","title":"Book 2 · Unit 5 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 32","duration":48.09,"cues":[{"start":0.0,"end":1.48,"text":"Unit five,","coverage":1.0},{"start":2.1,"end":3.12,"text":"five .one","coverage":1.0},{"start":4.78,"end":5.64,"text":"one","coverage":1.0},{"start":6.51,"end":9.42,"text":"The teacher's name isn't Mr Rosso,","coverage":1.0},{"start":9.84,"end":11.46,"text":"it's Mr Rosson.","coverage":1.0},{"start":13.66,"end":14.52,"text":"two","coverage":1.0},{"start":15.41,"end":17.12,"text":"I had a golf lesson,","coverage":1.0},{"start":17.62,"end":19.0,"text":"not a tennis lesson.","coverage":1.0},{"start":21.3,"end":22.16,"text":"three","coverage":1.0},{"start":23.12,"end":26.86,"text":"The match is at six tonight, not six .30,","coverage":1.0},{"start":27.04,"end":28.22,"text":"so don't be late.","coverage":1.0},{"start":30.38,"end":31.4,"text":"four","coverage":1.0},{"start":32.56,"end":34.98,"text":"Yasmin doesn't do drama classes,","coverage":1.0},{"start":35.6,"end":37.86,"text":"she does gymnastics classes.","coverage":1.0},{"start":40.4,"end":41.42,"text":"five","coverage":1.0},{"start":42.11,"end":44.52,"text":"The competition will be in Colombia,","coverage":1.0},{"start":45.12,"end":46.16,"text":"not in Brazil.","coverage":1.0}],"file":"09f85c3b100bf4e7dd30.js","track":0,"media":"../assets/media/6fd93a8c4baaf5d14e28bce8b3a1ec1e2d99eb57f241e04d230e333302e56647.mp3"}],"../assets/media/80b5a0e44a3811115a7edea7d561031e0ba00b23b8fa31a825d0c6c3824a84b3.wav":[{"id":"B3_U06_T6.1_LONG_L01_v01","audioId":"B3_U06_T6.1_LONG_L01_v01","title":"Book 3 · Unit 6 · 课后听力材料","subtitle":"Homework listening material","duration":133.93086167800453,"cues":[{"start":3.87,"end":6.3,"text":"Man: Welcome to the Museum of Science!","coverage":0.857},{"start":7.22,"end":13.52,"text":"The exhibition that we’re about to see is called Discovering Medieval Science.","coverage":0.923},{"start":14.2,"end":20.5,"text":"As some of you may know, the Middle Ages have often been called the ‘Dark Ages’.","coverage":1.0},{"start":21.22,"end":25.62,"text":"During this tour, you will find out that they were not.","coverage":1.0},{"start":26.23,"end":33.68,"text":"The Middle Ages were an interesting time and they were full of scientific discoveries.","coverage":1.0},{"start":34.22,"end":45.67,"text":"During this time, inventions and technology from India, China, North Africa and the Middle East were brought to Europe.","coverage":1.0},{"start":47.15,"end":58.0,"text":"Inventions and machines designed by medieval scholars made a great contribution to society and many are still in use today.","coverage":0.95},{"start":58.23,"end":62.59,"text":"And some of these inventions are very common.","coverage":1.0},{"start":63.23,"end":70.53,"text":"For example, the first fountain pen was made in 953 in Africa.","coverage":0.917},{"start":71.22,"end":76.61,"text":"Before then, people used bird feathers and ink to write with.","coverage":1.0},{"start":77.23,"end":83.64,"text":"This method would often leave your fingers and clothes covered with black ink.","coverage":1.0},{"start":84.22,"end":97.34,"text":"So the first fountain pen had a small container with ink inside and did not stain people’s clothes or fingers while the user was writing.","coverage":1.0},{"start":98.23,"end":103.57,"text":"You can see a model of this fountain pen in Room 11B.","coverage":1.0},{"start":104.2,"end":108.66,"text":"In the same room, you’ll find early examples of glasses.","coverage":1.0},{"start":109.71,"end":113.65,"text":"Glasses were invented in Italy in the thirteenth century.","coverage":0.778},{"start":114.21,"end":116.62,"text":"No one knows who invented them.","coverage":1.0},{"start":117.23,"end":123.59,"text":"The first glasses were held in front of the eyes or balanced on the nose.","coverage":1.0},{"start":124.23,"end":128.66,"text":"They were developed to help people with bad vision to read.","coverage":1.0},{"start":129.23,"end":133.57,"text":"But let’s now move on to some other inventions.","coverage":1.0}],"file":"0ad0a0513e3bdb037c31.js","track":0,"media":"../assets/media/80b5a0e44a3811115a7edea7d561031e0ba00b23b8fa31a825d0c6c3824a84b3.wav"}],"../assets/media/df2101bb5ff4a52abc966a61deb5a93bc5f6f72a6909a82ae7452e6caa8c0d71.mp3":[{"id":"PPT_df2101bb5ff4a52a","audioId":"PPT_df2101bb5ff4a52a","title":"Book 2 · Unit 7 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 194","duration":108.72,"cues":[{"start":0.0,"end":1.64,"text":"seven .four","coverage":1.0},{"start":3.18,"end":6.98,"text":"My presentation is about Thomas Edison.","coverage":1.0},{"start":8.22,"end":13.9,"text":"He was an American inventor and he was born in 1847.","coverage":1.0},{"start":15.2,"end":23.21,"text":"He is a remarkable person because he invented a lot of the things we know and use every day,","coverage":1.0},{"start":23.94,"end":26.06,"text":"such as the electric light bulb.","coverage":1.0},{"start":26.62,"end":27.08,"text":"Well,","coverage":1.0},{"start":27.76,"end":30.28,"text":"he wasn't the first to invent one,","coverage":1.0},{"start":30.82,"end":36.64,"text":"but he was the first person to invent one that could last a long time.","coverage":1.0},{"start":37.5,"end":48.06,"text":"This was in 1879 while he was working in his research lab in Menlo Park, New Jersey in the US.","coverage":1.0},{"start":49.06,"end":51.84,"text":"It lasted 13 .five","coverage":1.0},{"start":51.84,"end":52.54,"text":"hours.","coverage":1.0},{"start":53.54,"end":62.34,"text":"Another important example of Edison's amazing inventions is the motion picture camera.","coverage":1.0},{"start":63.68,"end":67.68,"text":"We all know this today as the video camera.","coverage":1.0},{"start":68.88,"end":77.78,"text":"Edison and his team invented it in 1891 and they showed short six -minute films.","coverage":1.0},{"start":78.78,"end":83.68,"text":"Equally important was Edison's work with Henry Ford,","coverage":1.0},{"start":84.3,"end":87.12,"text":"who started the Ford Motor Company.","coverage":1.0},{"start":88.28,"end":94.54,"text":"Edison was worried about America's dependence on foreign rubber for tires.","coverage":1.0},{"start":95.66,"end":101.78,"text":"So while he was working at a lab in Florida in 1927,","coverage":1.0},{"start":102.52,"end":106.86,"text":"he found a new source of rubber in local plants.","coverage":1.0}],"file":"0c5b57a69d8dc198e0f9.js","track":0,"media":"../assets/media/df2101bb5ff4a52abc966a61deb5a93bc5f6f72a6909a82ae7452e6caa8c0d71.mp3"}],"../assets/media/ba137d8e003fb543d6d94368f4b284cd762ea3bacb3dfc117c802224534ece67.mp3":[{"id":"PPT_ba137d8e003fb543","audioId":"PPT_ba137d8e003fb543","title":"Book 2 · Unit 6 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 102","duration":79.8,"cues":[{"start":0.0,"end":1.94,"text":"six .four","coverage":1.0},{"start":3.02,"end":3.41,"text":"Hi","coverage":1.0},{"start":3.41,"end":4.42,"text":"Sam,","coverage":1.0},{"start":4.82,"end":6.14,"text":"good to see you again.","coverage":1.0},{"start":6.4,"end":6.48,"text":"Hello","coverage":1.0},{"start":6.48,"end":6.96,"text":"Joe.","coverage":1.0},{"start":8.14,"end":8.4,"text":"So,","coverage":1.0},{"start":9.08,"end":13.4,"text":"last time we met we talked about your business goals.","coverage":1.0},{"start":14.04,"end":15.04,"text":"Was it useful?","coverage":1.0},{"start":15.72,"end":16.5,"text":"Useful?","coverage":1.0},{"start":16.92,"end":18.12,"text":"Yeah, it was.","coverage":1.0},{"start":18.86,"end":20.74,"text":"You really made me think.","coverage":1.0},{"start":21.32,"end":25.26,"text":"But now I have a lot of stress about losing money.","coverage":1.0},{"start":25.96,"end":26.62,"text":"Oh, yes.","coverage":1.0},{"start":27.18,"end":29.44,"text":"What is making you stressed about that?","coverage":1.0},{"start":29.44,"end":34.4,"text":"Well, I realized how many weaknesses a business can have.","coverage":1.0},{"start":35.06,"end":38.9,"text":"One careless mistake and I could lose a lot of money.","coverage":1.0},{"start":39.78,"end":40.22,"text":"Exactly.","coverage":1.0},{"start":41.22,"end":44.78,"text":"But there are things you think will cause you to lose money?","coverage":1.0},{"start":45.54,"end":49.74,"text":"Well, when we looked at the company's strengths and weaknesses,","coverage":1.0},{"start":50.36,"end":54.22,"text":"we talked about the quality and happiness of my workers,","coverage":1.0},{"start":54.8,"end":60.8,"text":"the costs of running the business and reaching new customers to help grow the business.","coverage":1.0},{"start":61.78,"end":70.06,"text":"Each of these areas could be a way to help make money or a way to lose money if you don't have a good plan.","coverage":1.0},{"start":70.84,"end":71.34,"text":"Wow,","coverage":1.0},{"start":71.7,"end":72.48,"text":"that's great.","coverage":1.0},{"start":73.1,"end":75.54,"text":"Those are all important to think about.","coverage":1.0},{"start":76.56,"end":77.9,"text":"Is there anything else?","coverage":1.0}],"file":"0c6127183027529468f5.js","track":0,"media":"../assets/media/ba137d8e003fb543d6d94368f4b284cd762ea3bacb3dfc117c802224534ece67.mp3"}],"../assets/media/a34b388b6c905fa88676eba0260c718abab02231c8561a6166c6a3c5434eaad0.wav":[{"id":"B3_U05_T5.2_LONG_L01_v01","audioId":"B3_U05_T5.2_LONG_L01_v01","title":"Book 3 · Unit 5 · H3 · 听力材料 1","subtitle":"H3 · 5.2-L01","duration":105.92759637188209,"cues":[{"start":0.24,"end":9.76,"text":"Host: So, new research shows that having a healthy lifestyle is not the most important thing if you want to live a long life.","coverage":0.958},{"start":10.19,"end":13.99,"text":"We asked four people on the street for their reactions to this news.","coverage":1.0},{"start":14.39,"end":16.83,"text":"Man (A): I think it’s great news!","coverage":0.75},{"start":17.55,"end":22.6,"text":"Most people think that if they eat healthy food and exercise a lot, they’ll live forever.","coverage":1.0},{"start":23.19,"end":26.48,"text":"These people never drink coffee or sugary drinks.","coverage":0.875},{"start":27.09,"end":30.8,"text":"They spend hours working out in the gym or doing yoga.","coverage":1.0},{"start":31.04,"end":34.14,"text":"And none of this matters if you have the wrong genes.","coverage":1.0},{"start":34.74,"end":38.63,"text":"I think that the key to a healthy life is to enjoy yourself.","coverage":1.0},{"start":39.12,"end":44.65,"text":"If you focus all your energy on what to do and what not to do, you’ll be unhappy eventually.","coverage":1.0},{"start":45.77,"end":48.61,"text":"There’s no question that happy people live longer.","coverage":1.0},{"start":48.93,"end":53.72,"text":"I’d much rather go out and have a pizza with friends than spend time in the gym.","coverage":1.0},{"start":54.19,"end":58.08,"text":"I’m really happy about this new research!","coverage":1.0},{"start":58.77,"end":61.81,"text":"Woman (B): This research proves what I’ve known for a long time.","coverage":0.846},{"start":62.3,"end":67.52,"text":"It’s ridiculous to get too worried about healthy eating and exercise!","coverage":1.0},{"start":68.08,"end":73.96,"text":"My grandfather lived until he was 95, even though he never exercised.","coverage":1.0},{"start":74.54,"end":78.44,"text":"He ate lots of sugar and never ate vegetables.","coverage":1.0},{"start":79.0,"end":81.29,"text":"He was brought up in a different world.","coverage":1.0},{"start":81.72,"end":82.79,"text":"He had different habits.","coverage":1.0},{"start":83.68,"end":85.84,"text":"He certainly never went to a gym.","coverage":1.0},{"start":86.42,"end":91.14,"text":"Yes, I’m sure that genes are more important than our lifestyle.","coverage":1.0},{"start":91.65,"end":97.17,"text":"Of course, I’m not going to give up exercising or start eating fast food every day.","coverage":1.0},{"start":97.99,"end":105.17,"text":"The research shows I should stay in shape because it makes me feel better – but I won’t allow fitness to take over my whole life.","coverage":1.0}],"file":"0cf7da8a6de57a6442ab.js","track":0,"media":"../assets/media/a34b388b6c905fa88676eba0260c718abab02231c8561a6166c6a3c5434eaad0.wav"}],"../assets/media/a5cb4b37090a84d390801c8b32576c4bb455d72f336bd726520f9461452f8bba.wav":[{"id":"B3_U05_T5.2_LONG_L02_v01","audioId":"B3_U05_T5.2_LONG_L02_v01","title":"Book 3 · Unit 5 · H3 · 听力材料 2","subtitle":"H3 · 5.2-L02","duration":70.83548752834467,"cues":[{"start":0.38,"end":4.83,"text":"Man (C): Well, first of all, I prefer to exercise and eat well.","coverage":0.846},{"start":5.35,"end":6.98,"text":"What’s wrong with being healthy?","coverage":1.0},{"start":7.72,"end":12.88,"text":"I also think that you won’t know whether or not you have the right genes until you get sick.","coverage":1.0},{"start":13.36,"end":16.2,"text":"So why take the risk and be unhealthy?","coverage":1.0},{"start":16.29,"end":24.78,"text":"Also, don’t forget that you might get the flu or a cold much more easily when you don’t eat healthy food or exercise.","coverage":1.0},{"start":25.16,"end":28.99,"text":"I’d say that it’s always better to have a healthy lifestyle.","coverage":1.0},{"start":29.22,"end":34.38,"text":"There’s no doubt that bad health habits increase the chances of getting a serious illness.","coverage":1.0},{"start":34.6,"end":36.07,"text":"Woman (D): Oh, that’s great.","coverage":0.667},{"start":36.4,"end":40.22,"text":"So now we should all eat fast food and stop exercising?","coverage":1.0},{"start":40.56,"end":44.11,"text":"I mean I look around and I see overweight children everywhere.","coverage":1.0},{"start":44.28,"end":68.71,"text":"No matter how good their genes are, I’m sure that these children won’t be able to enjoy a long and healthy life unless they give up crisps, chocolate bars, sugary drinks … Well, it’s great that some people can live to be 100 and do whatever they want in their lives, but I prefer to be careful and take care of myself because I don’t know if I have good genes!","coverage":0.959}],"file":"0cf7da8a6de57a6442ab.js","track":1,"media":"../assets/media/a5cb4b37090a84d390801c8b32576c4bb455d72f336bd726520f9461452f8bba.wav"}],"../assets/media/2626f1c674f2d61d19052c3e5b7ff50ca8c86275bf4483e2b6d51f7182863abc.mp3":[{"id":"PPT_2626f1c674f2d61d","audioId":"PPT_2626f1c674f2d61d","title":"Book 3 · Unit 6 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 243","duration":62.48,"cues":[{"start":0.0,"end":1.52,"text":"six .four","coverage":1.0},{"start":1.52,"end":3.16,"text":"Good morning.","coverage":1.0},{"start":3.82,"end":9.64,"text":"In today's lecture, I want to discuss an invention which has changed our lives.","coverage":1.0},{"start":10.4,"end":14.66,"text":"This product has made a huge difference in the way we work,","coverage":1.0},{"start":15.04,"end":15.54,"text":"travel,","coverage":1.0},{"start":15.96,"end":16.58,"text":"communicate,","coverage":1.0},{"start":16.94,"end":18.74,"text":"and socialize with friends.","coverage":1.0},{"start":19.44,"end":21.02,"text":"Can you guess what it is?","coverage":1.0},{"start":21.64,"end":25.06,"text":"I'm talking here about mobile phone apps.","coverage":1.0},{"start":25.84,"end":29.18,"text":"The word app comes from application.","coverage":1.0},{"start":29.82,"end":30.54,"text":"Traditionally,","coverage":1.0},{"start":31.4,"end":35.14,"text":"applications were used in computers to help them perform better.","coverage":1.0},{"start":35.72,"end":36.22,"text":"However,","coverage":1.0},{"start":36.68,"end":38.58,"text":"with the invention of smartphones,","coverage":1.0},{"start":38.98,"end":43.06,"text":"the word app is used to refer to phone applications.","coverage":1.0},{"start":43.88,"end":49.48,"text":"In this lecture, we'll start by discussing the very first apps and their development.","coverage":1.0},{"start":49.98,"end":53.88,"text":"We will then discuss how apps have changed our lives.","coverage":1.0},{"start":53.88,"end":55.2,"text":"Finally,","coverage":1.0},{"start":55.66,"end":60.52,"text":"we'll focus on some of the most popular apps used by people today.","coverage":1.0}],"file":"0e0e70a126851b50fd87.js","track":0,"media":"../assets/media/2626f1c674f2d61d19052c3e5b7ff50ca8c86275bf4483e2b6d51f7182863abc.mp3"}],"../assets/media/85aacc1a165933d0de800c88c681674161621dcc6fc27bdf9a253966f7692831.mp3":[{"id":"PPT_85aacc1a165933d0","audioId":"PPT_85aacc1a165933d0","title":"Book 2 · Unit 1 · RW · READING 1","subtitle":"READING 1 · source slide 46","duration":191.95,"cues":[{"start":0.0,"end":2.08,"text":"Rise of the Mega Cities","coverage":1.0},{"start":2.86,"end":4.0,"text":"Mega City,","coverage":1.0},{"start":4.42,"end":7.42,"text":"a city with more than ten million people.","coverage":1.0},{"start":8.32,"end":11.72,"text":"The number of Mega Cities is growing very quickly.","coverage":1.0},{"start":12.5,"end":17.04,"text":"In the 1950s, there were only two Mega Cities in the world.","coverage":1.0},{"start":17.52,"end":18.04,"text":"Today,","coverage":1.0},{"start":18.52,"end":23.54,"text":"12 % of the world's urban population lives in Mega Cities.","coverage":1.0},{"start":24.18,"end":27.46,"text":"Studies show that there will be eight .five","coverage":1.0},{"start":27.46,"end":30.5,"text":"billion people in the world in 2030.","coverage":1.0},{"start":31.54,"end":34.66,"text":"Experts say that there will be 40 Mega Cities.","coverage":1.0},{"start":35.92,"end":40.72,"text":"Today, more than 35 cities in the world are Mega Cities.","coverage":1.0},{"start":41.38,"end":43.3,"text":"The majority are in Asia,","coverage":1.0},{"start":43.8,"end":45.76,"text":"South America and Africa.","coverage":1.0},{"start":46.64,"end":53.64,"text":"More and more people around the world are leaving their homes in the countryside and moving to the city.","coverage":1.0},{"start":54.82,"end":57.64,"text":"Many Mega Cities have better opportunities,","coverage":1.0},{"start":58.12,"end":62.16,"text":"such as more jobs and a choice of schools and universities.","coverage":1.0},{"start":63.14,"end":66.58,"text":"Mega Cities are also exciting places to live.","coverage":1.0},{"start":67.0,"end":69.14,"text":"There are lots of different people,","coverage":1.0},{"start":69.62,"end":71.12,"text":"languages and restaurants,","coverage":1.0},{"start":71.52,"end":74.64,"text":"and there are many interesting things to do.","coverage":1.0},{"start":75.68,"end":76.3,"text":"However,","coverage":1.0},{"start":76.84,"end":78.44,"text":"Mega Cities have problems,","coverage":1.0},{"start":78.88,"end":78.96,"text":"too.","coverage":1.0},{"start":79.54,"end":85.86,"text":"The cities are very big, and this can cause problems like pollution or poor housing.","coverage":1.0},{"start":87.88,"end":88.66,"text":"Tokyo, Japan,","coverage":1.0},{"start":89.24,"end":90.76,"text":"37 .four","coverage":1.0},{"start":90.76,"end":91.4,"text":"million.","coverage":1.0},{"start":92.38,"end":96.2,"text":"Tokyo is an exciting modern city in the east of Japan.","coverage":1.0},{"start":96.74,"end":101.94,"text":"There are lots of jobs because most big companies in Japan are in Tokyo.","coverage":1.0},{"start":102.84,"end":105.76,"text":"It is also an excellent place to study.","coverage":1.0},{"start":105.76,"end":110.46,"text":"18 % of Japan's universities are in the city.","coverage":1.0},{"start":111.26,"end":111.78,"text":"However,","coverage":1.0},{"start":112.32,"end":116.52,"text":"Tokyo is very busy and the traffic is very bad.","coverage":1.0},{"start":117.22,"end":119.24,"text":"More than seven .five","coverage":1.0},{"start":119.24,"end":123.0,"text":"million people use the Tokyo Metro every day.","coverage":1.0},{"start":125.24,"end":126.14,"text":"Delhi, India,","coverage":1.0},{"start":126.9,"end":128.28,"text":"29 .four","coverage":1.0},{"start":128.28,"end":128.82,"text":"million.","coverage":1.0},{"start":129.82,"end":132.46,"text":"Delhi is in the north of India.","coverage":1.0},{"start":132.96,"end":135.58,"text":"It has many beautiful monuments,","coverage":1.0},{"start":136.06,"end":139.24,"text":"interesting museums and modern restaurants.","coverage":1.0},{"start":140.42,"end":144.1,"text":"There is an exciting mix of different cultures in the city,","coverage":1.0},{"start":144.52,"end":147.08,"text":"and there are four official languages,","coverage":1.0},{"start":147.76,"end":148.3,"text":"Hindi,","coverage":1.0},{"start":148.92,"end":149.4,"text":"Urdu,","coverage":1.0},{"start":149.88,"end":151.98,"text":"Punjabi and English.","coverage":1.0},{"start":152.9,"end":157.16,"text":"However, there are not enough houses in some parts of Delhi.","coverage":1.0},{"start":157.86,"end":162.44,"text":"This means that many people live in large slums in the city.","coverage":1.0},{"start":164.2,"end":165.6,"text":"Cairo, Egypt,","coverage":1.0},{"start":166.44,"end":167.52,"text":"20 .five","coverage":1.0},{"start":167.52,"end":168.24,"text":"million.","coverage":1.0},{"start":169.2,"end":174.74,"text":"Cairo is the capital of Egypt and is the second largest city in Africa.","coverage":1.0},{"start":175.72,"end":178.78,"text":"Cairo has important car and film industries.","coverage":1.0},{"start":179.7,"end":184.74,"text":"The city is the center of many government offices and has many universities,","coverage":1.0},{"start":185.74,"end":190.1,"text":"one of which is over one ,200 years old.","coverage":1.0}],"file":"0e5581564b0cfa040307.js","track":0,"media":"../assets/media/85aacc1a165933d0de800c88c681674161621dcc6fc27bdf9a253966f7692831.mp3"}],"../assets/media/feec86c28a9580206188e16defb71aaa695da8a25aa18301a244522002857b13.mp3":[{"id":"B3_U03_T3.3_SHORT_S01_v01","audioId":"B3_U03_T3.3_SHORT_S01_v01","title":"Book 3 · Unit 3 · 课后听力材料","subtitle":"Homework listening material","duration":47.5178,"cues":[{"start":2.25,"end":5.74,"text":"Host: Do you live, study or work in a large city?","coverage":0.909},{"start":6.2,"end":10.59,"text":"Are the traffic problems so serious they often cause you to be late?","coverage":1.0},{"start":11.29,"end":14.0,"text":"If so, you’re not alone.","coverage":1.0},{"start":14.29,"end":20.99,"text":"Over the past century, there’s been a huge increase in the traffic that moves through our cities.","coverage":1.0},{"start":21.27,"end":35.61,"text":"And if, as the United Nations predicts, 70% of the world’s population will be living in cities by the year 2050, what will we do when the amount of traffic increases even more?","coverage":1.0},{"start":36.29,"end":37.23,"text":"How will we cope?","coverage":1.0},{"start":38.0,"end":39.71,"text":"Can we do anything to control it?","coverage":1.0},{"start":40.29,"end":46.74,"text":"With me in today’s podcast is Mark Knowling, an expert in transport and traffic management.","coverage":0.938}],"file":"0f43c6fac8b8b2d22c23.js","track":0,"media":"../assets/media/feec86c28a9580206188e16defb71aaa695da8a25aa18301a244522002857b13.mp3"}],"../assets/media/0c813a5574f9da9b896a2341826da334efda1fcd264d8db7fce3e4f8ce9b4c1c.mp3":[{"id":"B3_U03_T3.3_SHORT_S03_v01","audioId":"B3_U03_T3.3_SHORT_S03_v01","title":"Book 3 · Unit 3 · 课后听力材料","subtitle":"Homework listening material","duration":34.339025,"cues":[{"start":0.37,"end":3.9,"text":"Host: What other factors influence how well traffic flows?","coverage":0.889},{"start":4.77,"end":12.07,"text":"Mark: Well, a crash on a busy city centre road can have a huge impact on all the other roads close by.","coverage":0.909},{"start":12.58,"end":24.13,"text":"Or someone parking their vehicle so that it blocks the traffic, even if only for a minute or so – a delivery driver, for example – can cause trouble for everyone behind them.","coverage":1.0},{"start":24.72,"end":30.47,"text":"Even something small like that means everyone’s journey suddenly becomes more difficult than they expected.","coverage":1.0},{"start":30.68,"end":33.59,"text":"It’s the most annoying thing in the world!","coverage":1.0}],"file":"0f4dae2d5d71afb3f6c1.js","track":0,"media":"../assets/media/0c813a5574f9da9b896a2341826da334efda1fcd264d8db7fce3e4f8ce9b4c1c.mp3"}],"../assets/media/bbb37b93b139cebfff3986e9fa4417b076a094a0cf930685781b9d582408c564.mp3":[{"id":"PPT_bbb37b93b139cebf","audioId":"PPT_bbb37b93b139cebf","title":"Book 2 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 58","duration":178.73,"cues":[{"start":0.0,"end":2.0,"text":"six .three","coverage":1.0},{"start":3.26,"end":4.44,"text":"Okay, Alika.","coverage":1.0},{"start":5.02,"end":6.56,"text":"Should we look at your project now?","coverage":1.0},{"start":7.28,"end":8.46,"text":"Yes, okay.","coverage":1.0},{"start":9.46,"end":12.58,"text":"You've done a lot of reading for this, which is great.","coverage":1.0},{"start":13.14,"end":15.96,"text":"I can see you wrote a lot of information down.","coverage":1.0},{"start":16.86,"end":19.5,"text":"Yes, but I haven't finished yet.","coverage":1.0},{"start":19.7,"end":24.78,"text":"I ran out of time, but I read as much as I could about","coverage":1.0},{"start":25.42,"end":27.38,"text":"103 different reports.","coverage":1.0},{"start":27.96,"end":32.52,"text":"I took part in the discussions on this with students from my study group.","coverage":1.0},{"start":33.0,"end":35.32,"text":"I studied the way people work.","coverage":1.0},{"start":36.26,"end":36.64,"text":"Good.","coverage":1.0},{"start":37.28,"end":38.76,"text":"Can you tell me what you learned?","coverage":1.0},{"start":39.84,"end":40.36,"text":"Well,","coverage":1.0},{"start":40.72,"end":44.02,"text":"I looked at how people spend time at work.","coverage":1.0},{"start":44.34,"end":50.42,"text":"I was interested in how people wasted time and why they didn't work hard at their jobs.","coverage":1.0},{"start":51.02,"end":55.66,"text":"I mean the reasons why they didn't focus on their work.","coverage":1.0},{"start":56.38,"end":59.2,"text":"I found out a lot of interesting information.","coverage":1.0},{"start":60.28,"end":61.14,"text":"For example,","coverage":1.0},{"start":61.78,"end":65.58,"text":"almost half of the workers wasted time on the internet.","coverage":1.0},{"start":66.2,"end":70.2,"text":"They were surfing the internet or writing personal emails.","coverage":1.0},{"start":70.88,"end":74.5,"text":"It was 48 % of workers, in fact.","coverage":1.0},{"start":75.34,"end":76.96,"text":"31 .five","coverage":1.0},{"start":76.96,"end":82.04,"text":"% also said they spent time talking to colleagues instead of working.","coverage":1.0},{"start":82.94,"end":85.14,"text":"And a little under half that amount,","coverage":1.0},{"start":86.1,"end":90.58,"text":"15%, said they took longer coffee and lunch breaks than they should.","coverage":1.0},{"start":91.4,"end":98.06,"text":"Only five % said they spent time texting friends and making plans for after work.","coverage":1.0},{"start":98.88,"end":99.44,"text":"Good.","coverage":1.0},{"start":100.24,"end":102.56,"text":"And did you find out the reasons why?","coverage":1.0},{"start":103.08,"end":103.76,"text":"Yes.","coverage":1.0},{"start":104.72,"end":110.02,"text":"Approximately half said they didn't work hard because they weren't happy in their jobs.","coverage":1.0},{"start":111.02,"end":111.78,"text":"I see.","coverage":1.0},{"start":112.6,"end":114.2,"text":"And about a third,","coverage":1.0},{"start":114.54,"end":116.92,"text":"33 .five%,","coverage":1.0},{"start":116.92,"end":119.72,"text":"thought they didn't earn a good enough salary.","coverage":1.0},{"start":120.4,"end":125.42,"text":"They said they didn't have enough money for holidays or nice clothes.","coverage":1.0},{"start":126.06,"end":128.94,"text":"They had just enough money to get by,","coverage":1.0},{"start":129.32,"end":132.2,"text":"so they didn't work as hard as they could.","coverage":1.0},{"start":132.56,"end":139.26,"text":"Some people, about 19%, said they had to work too many hours.","coverage":1.0},{"start":139.9,"end":143.92,"text":"So what are some effects of people not working very hard?","coverage":1.0},{"start":144.72,"end":145.4,"text":"Hmm.","coverage":1.0},{"start":146.06,"end":148.88,"text":"If people aren't working hard,","coverage":1.0},{"start":149.28,"end":151.98,"text":"companies don't get what they are paying for.","coverage":1.0},{"start":152.92,"end":154.36,"text":"Can you give me some examples?","coverage":1.0},{"start":155.46,"end":158.24,"text":"Well, when people don't work hard,","coverage":1.0},{"start":158.8,"end":160.54,"text":"productivity goes down.","coverage":1.0},{"start":160.94,"end":167.38,"text":"Because productivity depends on how fast workers make things or provide services,","coverage":1.0},{"start":168.08,"end":170.32,"text":"if workers are not working hard,","coverage":1.0},{"start":170.82,"end":172.86,"text":"the company doesn't make a profit.","coverage":1.0},{"start":173.6,"end":176.74,"text":"Then they can't pay higher salaries.","coverage":1.0}],"file":"1030ce1d156812df2b7e.js","track":0,"media":"../assets/media/bbb37b93b139cebfff3986e9fa4417b076a094a0cf930685781b9d582408c564.mp3"}],"../assets/media/d71ce3a7747e8905a840d8a19a5d1a5f34b80f185177007e2fcf5a20963e3fa9.mp3":[{"id":"PPT_d71ce3a7747e8905","audioId":"PPT_d71ce3a7747e8905","title":"Book 2 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 63","duration":93.99,"cues":[{"start":0.0,"end":1.52,"text":"eight .three","coverage":1.0},{"start":3.42,"end":5.74,"text":"Welcome to Outer Space Today.","coverage":1.0},{"start":6.58,"end":6.98,"text":"Normally,","coverage":1.0},{"start":7.3,"end":10.12,"text":"this program discusses going into space.","coverage":1.0},{"start":10.76,"end":17.94,"text":"We talk about making long journeys into outer space, traveling well beyond our moon and the planets near us.","coverage":1.0},{"start":18.56,"end":19.04,"text":"However,","coverage":1.0},{"start":19.6,"end":20.66,"text":"in this episode,","coverage":1.0},{"start":21.12,"end":24.08,"text":"we're looking at the issue of space debris,","coverage":1.0},{"start":24.48,"end":25.44,"text":"or space junk.","coverage":1.0},{"start":26.06,"end":27.56,"text":"How did it first start?","coverage":1.0},{"start":28.2,"end":32.02,"text":"And what happens to all the things that people put into space?","coverage":1.0},{"start":33.4,"end":37.96,"text":"Humans first began to explore near space in 1957,","coverage":1.0},{"start":38.52,"end":41.74,"text":"when the Soviets sent the first human -made satellite,","coverage":1.0},{"start":42.18,"end":44.12,"text":"Sputnik one, into space.","coverage":1.0},{"start":44.9,"end":45.92,"text":"Three months later,","coverage":1.0},{"start":46.3,"end":49.64,"text":"the satellite stopped working and fell back to Earth.","coverage":1.0},{"start":50.26,"end":54.48,"text":"It didn't hit the ground because it burned up on the way to Earth.","coverage":1.0},{"start":55.24,"end":57.24,"text":"This was the first rubbish,","coverage":1.0},{"start":57.56,"end":58.26,"text":"or junk,","coverage":1.0},{"start":58.7,"end":59.5,"text":"from space.","coverage":1.0},{"start":60.38,"end":64.24,"text":"But when Karabi Sputnik one, or Sputnik four,","coverage":1.0},{"start":64.92,"end":67.06,"text":"fell to Earth in 1962,","coverage":1.0},{"start":67.98,"end":73.98,"text":"a piece of it fell in the middle of a street in the central part of the U .S.","coverage":1.0},{"start":74.58,"end":75.22,"text":"Fortunately,","coverage":1.0},{"start":75.86,"end":76.94,"text":"it didn't hit anybody.","coverage":1.0},{"start":77.78,"end":78.54,"text":"Nowadays,","coverage":1.0},{"start":79.32,"end":86.18,"text":"there are many pieces of space junk from many countries going around the Earth and falling to Earth.","coverage":1.0},{"start":86.82,"end":92.02,"text":"This has many effects on our space programs and causes space accidents.","coverage":1.0}],"file":"116b80c0ce26b9801010.js","track":0,"media":"../assets/media/d71ce3a7747e8905a840d8a19a5d1a5f34b80f185177007e2fcf5a20963e3fa9.mp3"}],"../assets/media/17fcd3c9595ec95fe1a6a79feef4875749a495a918b9d579913c679a85f4913f.mp3":[{"id":"PPT_17fcd3c9595ec95f","audioId":"PPT_17fcd3c9595ec95f","title":"Book 3 · Unit 3 · RW · READING 2","subtitle":"READING 2 · source slide 100","duration":239.91,"cues":[{"start":0.0,"end":3.98,"text":"Traffic congestion is a serious problem in cities worldwide.","coverage":1.0},{"start":4.82,"end":8.84,"text":"There are simply too many vehicles competing for too little space.","coverage":1.0},{"start":9.82,"end":11.0,"text":"The company TomTom,","coverage":1.0},{"start":11.34,"end":14.3,"text":"which does research on traffic in cities worldwide,","coverage":1.0},{"start":15.06,"end":21.96,"text":"estimated that in 2015 the average commuter wasted 100 hours during the evening rush hour alone.","coverage":1.0},{"start":22.88,"end":25.04,"text":"In addition to wasting people's time,","coverage":1.0},{"start":25.5,"end":28.02,"text":"traffic jams have many other negative effects.","coverage":1.0},{"start":28.02,"end":29.22,"text":"Therefore,","coverage":1.0},{"start":30.06,"end":34.36,"text":"governments everywhere are working hard to find solutions to this problem.","coverage":1.0},{"start":35.58,"end":38.1,"text":"Traffic jams have negative effects on drivers,","coverage":1.0},{"start":38.48,"end":38.78,"text":"cities,","coverage":1.0},{"start":39.2,"end":40.02,"text":"and the environment.","coverage":1.0},{"start":40.72,"end":41.44,"text":"To begin with,","coverage":1.0},{"start":41.78,"end":43.34,"text":"they cause stress to drivers,","coverage":1.0},{"start":43.74,"end":46.52,"text":"which may lead to health problems or road rage.","coverage":1.0},{"start":47.3,"end":55.8,"text":"Traffic jams can also lead to economic losses because products cannot be delivered on time, and employees arrive late for work or meetings.","coverage":1.0},{"start":55.8,"end":65.44,"text":"Another negative effect is that emergency services can become caught in traffic and are therefore unable to get to an emergency in time.","coverage":1.0},{"start":66.58,"end":70.2,"text":"Finally, traffic congestion negatively affects the environment.","coverage":1.0},{"start":71.04,"end":72.92,"text":"Traffic congestion wastes fuel,","coverage":1.0},{"start":73.26,"end":79.06,"text":"which in turn produces more carbon dioxide through car exhaust and contributes to the greenhouse effect.","coverage":1.0},{"start":79.86,"end":80.62,"text":"Taken together,","coverage":1.0},{"start":81.04,"end":85.54,"text":"all these effects have a serious negative impact on the quality of people's lives.","coverage":1.0},{"start":86.58,"end":88.7,"text":"Because of these serious effects,","coverage":1.0},{"start":89.14,"end":94.7,"text":"it is important for cities and governments everywhere to take steps to reduce road congestion.","coverage":1.0},{"start":95.66,"end":98.18,"text":"The most obvious solutions involve engineering.","coverage":1.0},{"start":98.96,"end":110.72,"text":"This means building more roads with wider lanes so that more cars can travel at the same time, as well as constructing tunnels and bridges to guide drivers around congested areas.","coverage":1.0},{"start":111.32,"end":112.02,"text":"However,","coverage":1.0},{"start":112.54,"end":116.0,"text":"the costs for engineering solutions are extremely high.","coverage":1.0},{"start":116.66,"end":121.26,"text":"Another problem is that more roads may actually result in more traffic.","coverage":1.0},{"start":122.0,"end":122.62,"text":"In short,","coverage":1.0},{"start":123.52,"end":126.84,"text":"engineering solutions have both advantages and disadvantages.","coverage":1.0},{"start":128.68,"end":138.92,"text":"Other more creative solutions to the congestion problem are to increase the tax on fuel or to make people pay to travel in the center of a city or on a motorway.","coverage":1.0},{"start":139.52,"end":141.94,"text":"If governments increase the cost of driving,","coverage":1.0},{"start":142.46,"end":145.44,"text":"people will think more carefully about using their cars.","coverage":1.0},{"start":146.1,"end":146.74,"text":"However,","coverage":1.0},{"start":147.44,"end":152.98,"text":"taxing fuel and roads may mean that some people cannot afford to drive their cars,","coverage":1.0},{"start":153.38,"end":155.36,"text":"and they may have to give up their jobs.","coverage":1.0},{"start":156.14,"end":156.68,"text":"Also,","coverage":1.0},{"start":157.18,"end":162.54,"text":"governments may not want to increase the fuel tax too much if the tax is unpopular with voters.","coverage":1.0},{"start":163.74,"end":170.3,"text":"A more popular solution, therefore, would be to promote other forms of transport, like ferries, cycling,","coverage":1.0},{"start":170.7,"end":172.04,"text":"and underground trains.","coverage":1.0},{"start":172.9,"end":175.98,"text":"One suggestion is to encourage people to cycle more.","coverage":1.0},{"start":176.74,"end":180.42,"text":"Although cycling has obvious health benefits and does not pollute the air,","coverage":1.0},{"start":180.9,"end":185.68,"text":"it is not practical in every climate and can prove dangerous in heavy traffic.","coverage":1.0},{"start":187.02,"end":190.58,"text":"Another possibility is to persuade people to use buses,","coverage":1.0},{"start":191.12,"end":193.64,"text":"although they are inconvenient for some people.","coverage":1.0},{"start":193.64,"end":197.24,"text":"A related option is a park and ride system,","coverage":1.0},{"start":197.58,"end":200.6,"text":"which allows people to drive to the outskirts of cities,","coverage":1.0},{"start":201.04,"end":201.44,"text":"park,","coverage":1.0},{"start":201.86,"end":204.02,"text":"and then take a bus to the city center.","coverage":1.0},{"start":204.78,"end":210.14,"text":"This allows some flexibility for car drivers and reduces congestion in the center of the city.","coverage":1.0},{"start":211.12,"end":216.62,"text":"A disadvantage for people who work late shifts is that many buses do not run at night.","coverage":1.0},{"start":217.76,"end":218.44,"text":"Overall,","coverage":1.0},{"start":218.92,"end":223.44,"text":"cities are using a variety of methods to tackle the problem of traffic congestion.","coverage":1.0},{"start":224.38,"end":227.98,"text":"Most of the methods have advantages as well as disadvantages.","coverage":1.0},{"start":228.94,"end":237.98,"text":"We should encourage alternative forms of transport because they reduce the amount of traffic on the roads and also have a positive effect on the environment.","coverage":1.0}],"file":"11afb984a7eb9f33a0db.js","track":0,"media":"../assets/media/17fcd3c9595ec95fe1a6a79feef4875749a495a918b9d579913c679a85f4913f.mp3"}],"../assets/media/5345c2f20f46e003350874154179c027e3241eb34df307e31cd52fc05dc41e07.wav":[{"id":"B2_U02_T2.1_LONG_L03_v01","audioId":"B2_U02_T2.1_LONG_L03_v01","title":"Book 2 · Unit 2 · 课后听力材料","subtitle":"Homework listening material","duration":102.10555555555555,"cues":[{"start":0.86,"end":11.71,"text":"Reporter 1: Visiting such festivals is not just for entertainment; it’s also a fantastic way to find out about the culture of a different country.","coverage":0.885},{"start":12.0,"end":17.52,"text":"I went to Oman in the Middle East recently to do just that.","coverage":1.0},{"start":18.0,"end":23.92,"text":"I’m here in Muscat at the festival of culture and heritage, talking to Nasrra.","coverage":0.867},{"start":25.0,"end":29.63,"text":"She is visiting the festival, Muscat Nights, with her family.","coverage":0.9},{"start":30.0,"end":39.68,"text":"The event is held in January and February each year in Oman, and Nasrra has been coming for the last couple of years.","coverage":0.957},{"start":40.0,"end":40.33,"text":"Hi, Nasrra.","coverage":0.5},{"start":42.0,"end":43.68,"text":"Are you enjoying the festival?","coverage":1.0},{"start":44.0,"end":44.5,"text":"Nasrra: Yes!","coverage":0.5},{"start":45.03,"end":47.3,"text":"It’s wonderful!","coverage":1.0},{"start":48.0,"end":50.59,"text":"Reporter 1: Can you tell us something about the festival?","coverage":0.8},{"start":51.0,"end":51.58,"text":"Nasrra: Of course.","coverage":0.667},{"start":51.82,"end":56.43,"text":"It’s a chance for people to learn about the heritage and culture of Oman.","coverage":1.0},{"start":57.0,"end":59.54,"text":"Reporter 1: So, why are you here?","coverage":0.714},{"start":60.0,"end":66.68,"text":"Nasrra: My mother and father want to watch some of the sports; there was basketball last year and also a car race.","coverage":0.955},{"start":67.0,"end":69.79,"text":"You can listen to traditional music.","coverage":1.0},{"start":70.0,"end":72.43,"text":"But I decided to go to the fashion show.","coverage":1.0},{"start":73.0,"end":74.65,"text":"Reporter 1: That sounds great.","coverage":0.6},{"start":75.57,"end":75.65,"text":"Nasrra: Yeah.","coverage":0.5},{"start":76.03,"end":81.59,"text":"And after we finish watching the races and shows, we’ll go and eat some traditional food.","coverage":1.0},{"start":82.69,"end":83.62,"text":"Reporter 1: Sounds amazing!","coverage":0.5},{"start":84.0,"end":86.6,"text":"I hope you all have a great time.","coverage":1.0},{"start":87.0,"end":96.68,"text":"So these international festivals, with lots of music, food and fashion, are providing a different type of experience for people.","coverage":1.0},{"start":97.0,"end":100.0,"text":"Next week, we’ll be looking at …","coverage":1.0}],"file":"11c656003d6dd62acc72.js","track":0,"media":"../assets/media/5345c2f20f46e003350874154179c027e3241eb34df307e31cd52fc05dc41e07.wav"}],"../assets/media/ec16535a4c134bb097704188258191fdf8cf015418f2b819d601d346f2feb75f.mp3":[{"id":"PPT_ec16535a4c134bb0","audioId":"PPT_ec16535a4c134bb0","title":"Book 2 · Unit 6 · RW · READING 2","subtitle":"READING 2 · source slide 120","duration":255.56,"cues":[{"start":0.0,"end":4.38,"text":"The story of ChatGPT and OpenAI","coverage":1.0},{"start":5.86,"end":9.32,"text":"ChatGPT is an artificial intelligence, AI,","coverage":1.0},{"start":9.74,"end":10.26,"text":"technology.","coverage":1.0},{"start":11.06,"end":15.14,"text":"It can have an online conversation with the person using it.","coverage":1.0},{"start":15.6,"end":20.34,"text":"It can understand questions and answer them in a way that sounds human,","coverage":1.0},{"start":20.8,"end":24.38,"text":"and it can even say sorry when it makes a mistake.","coverage":1.0},{"start":25.8,"end":30.74,"text":"ChatGPT is owned by a technology company called OpenAI.","coverage":1.0},{"start":31.76,"end":34.48,"text":"The company was set up by Elon Musk,","coverage":1.0},{"start":34.96,"end":35.8,"text":"Sam Altman,","coverage":1.0},{"start":36.14,"end":38.12,"text":"and others in 2015.","coverage":1.0},{"start":39.16,"end":45.1,"text":"Their goal was to build safe AI technology that could be used by everyone.","coverage":1.0},{"start":45.86,"end":46.4,"text":"Today,","coverage":1.0},{"start":46.82,"end":50.82,"text":"OpenAI employs 375 people.","coverage":1.0},{"start":50.82,"end":57.6,"text":"The partners started a company that created the fastest growing application of all time.","coverage":1.0},{"start":58.36,"end":58.9,"text":"Now,","coverage":1.0},{"start":59.26,"end":63.66,"text":"OpenAI wants to make more powerful AI technology.","coverage":1.0},{"start":64.56,"end":69.14,"text":"They believe that more use of AI in the world is a good thing.","coverage":1.0},{"start":70.62,"end":72.88,"text":"OpenAI grew very quickly.","coverage":1.0},{"start":73.42,"end":76.78,"text":"The company started with investments of $one billion,","coverage":1.0},{"start":77.4,"end":83.58,"text":"and in 2016, less than a year later, it developed its first AI program,","coverage":1.0},{"start":84.2,"end":85.5,"text":"OpenAI Gym.","coverage":1.0},{"start":86.6,"end":91.82,"text":"In 2018, the company introduced the first version of GPT,","coverage":1.0},{"start":92.2,"end":99.1,"text":"which was the first time that a machine could make sentences that sounded like they were written by a real person.","coverage":1.0},{"start":100.0,"end":109.0,"text":"This was the same year that Elon Musk left OpenAI, and the company announced it was going to partner with Microsoft Corporation.","coverage":1.0},{"start":110.16,"end":116.32,"text":"The partnership meant OpenAI could do more research and share the results with the world.","coverage":1.0},{"start":117.16,"end":118.24,"text":"In 2020,","coverage":1.0},{"start":118.8,"end":121.66,"text":"OpenAI opened its office in San Francisco.","coverage":1.0},{"start":122.6,"end":126.74,"text":"It shares the building with another business started by Elon Musk.","coverage":1.0},{"start":126.74,"end":131.5,"text":"ChatGPT was introduced in November 2022,","coverage":1.0},{"start":132.28,"end":135.7,"text":"and it grew faster than any other application.","coverage":1.0},{"start":136.48,"end":138.04,"text":"In only two months,","coverage":1.0},{"start":138.52,"end":141.12,"text":"100 million people used it.","coverage":1.0},{"start":141.64,"end":148.9,"text":"About 13 million people used ChatGPT every day in January 2023,","coverage":1.0},{"start":149.58,"end":152.92,"text":"which is double the number who used it in December.","coverage":1.0},{"start":153.88,"end":155.84,"text":"Compare this to TikTok,","coverage":1.0},{"start":156.24,"end":164.2,"text":"which took about nine months to get about 100 million users, and Instagram, which took about two .five","coverage":1.0},{"start":164.2,"end":164.84,"text":"years.","coverage":1.0},{"start":166.28,"end":168.52,"text":"ChatGPT is free to use.","coverage":1.0},{"start":168.76,"end":169.38,"text":"However,","coverage":1.0},{"start":169.84,"end":171.98,"text":"in February 2023,","coverage":1.0},{"start":172.56,"end":175.7,"text":"OpenAI started to advertise a subscription.","coverage":1.0},{"start":176.5,"end":182.9,"text":"People who choose to pay $20 every month get faster answers to their questions.","coverage":1.0},{"start":183.48,"end":190.12,"text":"Some schools and teachers worry about students using ChatGPT to do their coursework.","coverage":1.0},{"start":191.02,"end":198.56,"text":"A number of schools in America stopped teachers and students from using the application while they were at school.","coverage":1.0},{"start":199.2,"end":205.98,"text":"This shows that not everyone is happy about AI technology and how fast it is growing.","coverage":1.0},{"start":206.68,"end":215.2,"text":"Some people think businesses like OpenAI are not thinking about the possible bad results of the things they are doing.","coverage":1.0},{"start":216.36,"end":222.86,"text":"OpenAI is still working hard to make amazing AI that can help all people.","coverage":1.0},{"start":223.46,"end":231.14,"text":"In the future, they want to make AI programs that can do things like help doctors find cures for diseases,","coverage":1.0},{"start":231.74,"end":238.6,"text":"find answers to difficult problems like climate change, or help people to run their businesses better.","coverage":1.0},{"start":239.44,"end":243.86,"text":"Although some people worry that in the future AI will hurt people,","coverage":1.0},{"start":244.42,"end":253.6,"text":"OpenAI wants to make sure that AI will be safe for everyone to use and will make our lives easier and more enjoyable.","coverage":1.0}],"file":"126535065b1eefbfae94.js","track":0,"media":"../assets/media/ec16535a4c134bb097704188258191fdf8cf015418f2b819d601d346f2feb75f.mp3"}],"../assets/media/6a096d02b1d67ea78b88d19a44fa825708d86cf7f14d2794fb43bc5d1568f384.wav":[{"id":"B3_U07_T7.1_LONG_L01_v01","audioId":"B3_U07_T7.1_LONG_L01_v01","title":"Book 3 · Unit 7 · H3 · 听力材料 1","subtitle":"H3 · 7.1-L01","duration":124.86637188208617,"cues":[{"start":4.11,"end":8.75,"text":"Yoriko: So, Hamed, shall we continue working on our group presentation?","coverage":0.818},{"start":9.29,"end":9.84,"text":"Hamed: Good idea, Yoriko.","coverage":0.5},{"start":11.29,"end":19.65,"text":"Now, Danial and Samia are focusing on the environmental issues of fast fashion – so we’ll be talking about copyright infringement.","coverage":0.905},{"start":20.28,"end":24.26,"text":"Yoriko: Danial said they’ve already written their part of the presentation, you know ...","coverage":0.857},{"start":24.79,"end":25.67,"text":"Hamed: Wow, really?","coverage":0.667},{"start":26.48,"end":28.91,"text":"We’ve only just got started on ours!","coverage":1.0},{"start":29.49,"end":40.33,"text":"Anyway, we’re focusing on the way that fast fashion companies lift unknown artists’ designs and put them onto their products, which they then sell in huge numbers.","coverage":1.0},{"start":40.89,"end":41.52,"text":"Yoriko: That’s right.","coverage":0.75},{"start":41.97,"end":46.97,"text":"So, first, I think we should talk about what happened to Vanessa Bowman.","coverage":1.0},{"start":47.48,"end":50.8,"text":"Hamed: The artist from the south of England who paints the world around her?","coverage":0.929},{"start":51.29,"end":56.38,"text":"Yoriko: Yes, views out onto her garden, natural scenes, that sort of thing.","coverage":0.923},{"start":56.78,"end":64.41,"text":"A fast fashion company lifted images of her paintings they found on her website and used them on a clothing range.","coverage":1.0},{"start":64.79,"end":70.02,"text":"I’m sure they made loads a lot of money, and I don’t think she got anything in return.","coverage":0.95},{"start":70.49,"end":72.57,"text":"Hamed: No, she didn’t get anything.","coverage":0.857},{"start":73.06,"end":75.97,"text":"No payment, no credit for her work, nothing.","coverage":1.0},{"start":76.5,"end":77.49,"text":"She’s not alone, though.","coverage":1.0},{"start":78.1,"end":78.18,"text":"Yoriko: No.","coverage":0.5},{"start":78.3,"end":80.99,"text":"We should also use the example of Kirstie Moran.","coverage":0.778},{"start":82.75,"end":86.43,"text":"She creates interesting, unusual designs of animals.","coverage":1.0},{"start":86.97,"end":93.73,"text":"Her artwork was also used by a fast fashion company and again, she got nothing from them.","coverage":1.0},{"start":94.19,"end":103.39,"text":"Hamed: I mean, this is a perfect example of a company taking an artist’s designs without permission and using them to sell clothes and make a profit.","coverage":0.964},{"start":103.99,"end":105.19,"text":"What can anyone do?","coverage":1.0},{"start":105.79,"end":113.19,"text":"Yoriko: Some large fashion companies take legal action when their designs are copied, but it takes money and power to do that.","coverage":0.955},{"start":113.68,"end":124.2,"text":"It’s just not practical for an independent artist like Kirstie Moran to say, ‘if you don’t pay me for my hard work and talent, I’ll be contacting my lawyer’.","coverage":0.938}],"file":"14d116c77d0ba63089b8.js","track":0,"media":"../assets/media/6a096d02b1d67ea78b88d19a44fa825708d86cf7f14d2794fb43bc5d1568f384.wav"}],"../assets/media/5558b9214064164159fa1942d8e08a7c5316577d9aa2afde79a726a219af7eb2.wav":[{"id":"B3_U07_T7.1_LONG_L02_v01","audioId":"B3_U07_T7.1_LONG_L02_v01","title":"Book 3 · Unit 7 · H3 · 听力材料 2","subtitle":"H3 · 7.1-L02","duration":112.59777777777778,"cues":[{"start":0.41,"end":6.85,"text":"Hamed: Well, I have seen some examples of artists defending their intellectual property, but not many.","coverage":0.938},{"start":8.51,"end":9.35,"text":"Elora Pautrat, for example.","coverage":0.5},{"start":9.68,"end":11.55,"text":"Yoriko: I haven’t read about her yet.","coverage":0.875},{"start":11.84,"end":21.2,"text":"Hamed: She did do something about it, after she discovered that a fast fashion company was converting her designs into images and putting them on clothing and bags.","coverage":0.964},{"start":21.5,"end":28.38,"text":"At first, Elora decided it wasn’t worth complaining to them by email, so she tried a different approach.","coverage":0.947},{"start":28.64,"end":32.79,"text":"She posted her complaint on social media, and it went viral.","coverage":1.0},{"start":33.54,"end":40.15,"text":"Thousands of people from all over the world criticized the company and promised never to buy anything from them again.","coverage":1.0},{"start":40.84,"end":43.89,"text":"Finally, the company wrote to her offering an apology.","coverage":1.0},{"start":44.16,"end":49.54,"text":"They actually paid her something for using her work and promised it would never happen again.","coverage":1.0},{"start":50.35,"end":53.0,"text":"Yoriko: That’s one happy ending, at least.","coverage":0.875},{"start":53.78,"end":54.41,"text":"Hamed: Not quite.","coverage":0.667},{"start":54.8,"end":61.27,"text":"The same company’s lifted her work several times since then and used it on all sorts of products.","coverage":0.895},{"start":62.14,"end":66.89,"text":"Although they’ve accepted it was their fault again, she still hasn’t received a second payment.","coverage":1.0},{"start":67.2,"end":70.36,"text":"She’s going to be disappointed this time, I imagine.","coverage":1.0},{"start":70.64,"end":82.77,"text":"Yoriko: The thing is, these companies do have the ability and the resources to collaborate with artists, pay them for their designs and still make a lot of money – but they choose not to.","coverage":0.971},{"start":83.52,"end":83.93,"text":"Hamed: I know.","coverage":0.667},{"start":84.09,"end":85.99,"text":"It’s plagiarism, basically.","coverage":0.75},{"start":86.18,"end":87.55,"text":"And it’s not ethical.","coverage":1.0},{"start":88.31,"end":90.45,"text":"Yoriko: Oh, I do agree.","coverage":0.8},{"start":91.56,"end":94.92,"text":"Imagine doing that sort of thing on our university course!","coverage":0.8},{"start":95.24,"end":98.41,"text":"Can you see the situation changing any time soon?","coverage":0.778},{"start":98.68,"end":101.76,"text":"Hamed: No, I don’t think it will change.","coverage":0.889},{"start":102.16,"end":110.59,"text":"In a few years, these companies will be ignoring copyright law just like they do now, and artists still won’t be getting anything.","coverage":1.0}],"file":"14d116c77d0ba63089b8.js","track":1,"media":"../assets/media/5558b9214064164159fa1942d8e08a7c5316577d9aa2afde79a726a219af7eb2.wav"}],"../assets/media/2b82f902d364dc2bc408836dfef919e3aba6fb90650eb39fc3c377fa1c0d6f92.mp3":[{"id":"PPT_2b82f902d364dc2b","audioId":"PPT_2b82f902d364dc2b","title":"Book 2 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 30","duration":60.87,"cues":[{"start":0.0,"end":1.38,"text":"Unit eight,","coverage":1.0},{"start":1.74,"end":3.0,"text":"eight .one","coverage":1.0},{"start":4.6,"end":8.7,"text":"one weather, weather","coverage":1.0},{"start":9.88,"end":10.88,"text":"two","coverage":1.0},{"start":11.48,"end":12.3,"text":"hour,","coverage":1.0},{"start":15.48,"end":17.78,"text":"three sun,","coverage":1.0},{"start":20.92,"end":23.3,"text":"four red,","coverage":1.0},{"start":24.08,"end":24.92,"text":"red","coverage":1.0},{"start":26.36,"end":27.44,"text":"five","coverage":1.0},{"start":28.04,"end":29.26,"text":"there,","coverage":1.0},{"start":33.6,"end":34.74,"text":"cent,","coverage":1.0},{"start":38.08,"end":42.04,"text":"seven eight eight","coverage":1.0},{"start":43.54,"end":46.12,"text":"eight mind,","coverage":1.0},{"start":49.4,"end":50.62,"text":"nine","coverage":1.0},{"start":51.16,"end":53.98,"text":"four four","coverage":1.0},{"start":55.14,"end":55.84,"text":"ten","coverage":1.0},{"start":56.64,"end":57.42,"text":"two","coverage":1.0},{"start":58.32,"end":59.1,"text":"two","coverage":1.0}],"file":"1681cb2ebce851dff29b.js","track":0,"media":"../assets/media/2b82f902d364dc2bc408836dfef919e3aba6fb90650eb39fc3c377fa1c0d6f92.mp3"}],"../assets/media/69ddeaa8cf80e1e3c08e4c10d4393abc7e2a1b92dc25554f2b6c4275ea987f5f.mp3":[{"id":"PPT_69ddeaa8cf80e1e3","audioId":"PPT_69ddeaa8cf80e1e3","title":"Book 2 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 177","duration":45.51,"cues":[{"start":0.0,"end":1.94,"text":"one .five","coverage":1.0},{"start":3.0,"end":3.8,"text":"one.","coverage":1.0},{"start":5.38,"end":10.08,"text":"I'd like to talk about the city of Vancouver in British Columbia,","coverage":1.0},{"start":10.48,"end":11.0,"text":"Canada.","coverage":1.0},{"start":13.52,"end":14.32,"text":"two.","coverage":1.0},{"start":15.58,"end":16.54,"text":"First of all,","coverage":1.0},{"start":16.94,"end":18.98,"text":"let's look at some of the positives.","coverage":1.0},{"start":21.38,"end":22.18,"text":"three.","coverage":1.0},{"start":23.56,"end":28.06,"text":"I'd also like to talk about some disadvantages of parks in Vancouver.","coverage":1.0},{"start":30.62,"end":31.42,"text":"four.","coverage":1.0},{"start":32.66,"end":33.18,"text":"Finally,","coverage":1.0},{"start":33.62,"end":38.94,"text":"while I think these disadvantages mean that some people would not want to visit Vancouver,","coverage":1.0},{"start":39.62,"end":43.66,"text":"I personally feel that most people would enjoy Vancouver.","coverage":1.0}],"file":"176a4c9f056567227e25.js","track":0,"media":"../assets/media/69ddeaa8cf80e1e3c08e4c10d4393abc7e2a1b92dc25554f2b6c4275ea987f5f.mp3"}],"../assets/media/0b5b23d090a98a5fd096b0b7f135dfd2319854e51346fe90046473a502b465f5.mp3":[{"id":"PPT_0b5b23d090a98a5f","audioId":"PPT_0b5b23d090a98a5f","title":"Book 3 · Unit 1 · RW · READING 1","subtitle":"READING 1 · source slide 37","duration":206.65,"cues":[{"start":0.0,"end":1.58,"text":"Endangered species.","coverage":1.0},{"start":2.78,"end":8.54,"text":"An endangered species is a group of animals or plants which could soon become extinct.","coverage":1.0},{"start":9.44,"end":14.86,"text":"Extinction happens when the last animal of the species has died out and there will be","coverage":1.0},{"start":14.86,"end":15.16,"text":"no","coverage":1.0},{"start":15.16,"end":15.6,"text":"more.","coverage":1.0},{"start":16.28,"end":24.16,"text":"Many species are nearly extinct and could disappear from the Earth very soon if we don't do anything to save them.","coverage":1.0},{"start":24.16,"end":28.4,"text":"There are many reasons why species become endangered,","coverage":1.0},{"start":29.02,"end":34.96,"text":"but most harm to species is due to human activities such as habitat destruction,","coverage":1.0},{"start":35.4,"end":37.16,"text":"hunting and overfishing.","coverage":1.0},{"start":38.58,"end":43.48,"text":"Habitat destruction is the main reason why animals become endangered.","coverage":1.0},{"start":44.26,"end":46.24,"text":"This happens in two ways.","coverage":1.0},{"start":46.24,"end":47.32,"text":"First,","coverage":1.0},{"start":47.82,"end":50.2,"text":"when humans move into a new area,","coverage":1.0},{"start":50.56,"end":53.88,"text":"they cut down trees to build houses and farms.","coverage":1.0},{"start":54.68,"end":57.0,"text":"This destroys the animal's habitat,","coverage":1.0},{"start":57.48,"end":61.66,"text":"the natural environment where plants or animals usually live,","coverage":1.0},{"start":62.26,"end":64.24,"text":"and leaves them without food.","coverage":1.0},{"start":65.18,"end":69.02,"text":"Animal habitats are also destroyed because of pollution.","coverage":1.0},{"start":69.02,"end":71.88,"text":"Dirty water from factories,","coverage":1.0},{"start":72.32,"end":73.72,"text":"which contains chemicals,","coverage":1.0},{"start":74.36,"end":75.32,"text":"ends up in rivers,","coverage":1.0},{"start":75.94,"end":82.42,"text":"and poisons used on farmland may even kill animals which live in the area.","coverage":1.0},{"start":83.92,"end":88.2,"text":"Endangered species are also the result of hunting and fishing.","coverage":1.0},{"start":89.2,"end":95.8,"text":"Animals such as the Arabian Oryx are nearly extinct because of the high price of their meat.","coverage":1.0},{"start":95.8,"end":99.96,"text":"Other animals are killed for their fur, bones,","coverage":1.0},{"start":100.32,"end":101.02,"text":"or skin,","coverage":1.0},{"start":101.5,"end":103.1,"text":"or just for sport.","coverage":1.0},{"start":104.08,"end":104.98,"text":"For example,","coverage":1.0},{"start":105.3,"end":112.46,"text":"some seal species are now almost extinct because they are killed for their fur to make coats.","coverage":1.0},{"start":113.36,"end":117.36,"text":"Tigers are shot to make medicine and tea from their bones,","coverage":1.0},{"start":118.12,"end":121.62,"text":"and crocodiles are caught to make bags and shoes.","coverage":1.0},{"start":121.62,"end":125.12,"text":"Large sea creatures like whales,","coverage":1.0},{"start":125.48,"end":125.72,"text":"tuna,","coverage":1.0},{"start":126.08,"end":131.3,"text":"and sharks have all become endangered species because of overfishing.","coverage":1.0},{"start":132.08,"end":136.54,"text":"Too many are caught to make special dishes that people like to eat,","coverage":1.0},{"start":137.06,"end":139.74,"text":"such as shark's fin soup or sushi.","coverage":1.0},{"start":141.28,"end":148.86,"text":"What steps can individuals and governments take to protect more animal and plant species from becoming endangered?","coverage":1.0},{"start":148.86,"end":153.16,"text":"We should try not to pollute natural areas,","coverage":1.0},{"start":154.02,"end":159.9,"text":"and farmers or companies who destroy animal habitats should face a financial penalty.","coverage":1.0},{"start":161.04,"end":165.94,"text":"The public can help out by refusing to buy products made from animals'","coverage":1.0},{"start":166.28,"end":167.08,"text":"body parts,","coverage":1.0},{"start":167.48,"end":170.84,"text":"such as seal fur coats or crocodile bags.","coverage":1.0},{"start":170.84,"end":172.94,"text":"Governments can help,","coverage":1.0},{"start":173.34,"end":173.36,"text":"too,","coverage":1.0},{"start":173.72,"end":176.3,"text":"by making it against the law to hunt,","coverage":1.0},{"start":176.68,"end":179.62,"text":"fish, or trade in endangered species.","coverage":1.0},{"start":180.46,"end":184.84,"text":"They can also provide funding for animal sanctuaries and zoos.","coverage":1.0},{"start":185.76,"end":190.84,"text":"These protect animals from extinction by breeding more endangered animals,","coverage":1.0},{"start":191.36,"end":193.98,"text":"which can later be released into the wild.","coverage":1.0},{"start":193.98,"end":197.98,"text":"If we all cooperate by taking these steps,","coverage":1.0},{"start":198.48,"end":204.82,"text":"we will protect our planet so that our children and their children can enjoy it, too.","coverage":1.0}],"file":"17e2bfde0cdaf9a1db5b.js","track":0,"media":"../assets/media/0b5b23d090a98a5fd096b0b7f135dfd2319854e51346fe90046473a502b465f5.mp3"}],"../assets/media/aa2f30af804e3c9cd614d55500b4cb01f27c2ac3cef470feda4b890aa0f881a1.wav":[{"id":"B2_U07_T7.1_LONG_L02_v01","audioId":"B2_U07_T7.1_LONG_L02_v01","title":"Book 2 · Unit 7 · 课后听力材料","subtitle":"Homework listening material","duration":134.91045351473923,"cues":[{"start":0.5,"end":5.11,"text":"Next, I’d like to talk about an inventor, James Dyson.","coverage":0.909},{"start":6.16,"end":12.42,"text":"Can anyone think of something you often use that might have his last name, Dyson, on it?","coverage":0.941},{"start":12.84,"end":15.25,"text":"Razia: I know, a vacuum cleaner!","coverage":0.833},{"start":15.51,"end":15.85,"text":"Ebru: Or a hand dryer?","coverage":0.4},{"start":17.1,"end":19.57,"text":"Student presenter: Both of those things are correct.","coverage":0.75},{"start":20.25,"end":24.62,"text":"Dyson’s designs and inventions are made to solve problems.","coverage":0.9},{"start":25.26,"end":31.92,"text":"His ideas come because he sees things that could work better, like the vacuum cleaner and hand dryer.","coverage":0.944},{"start":32.71,"end":34.96,"text":"But how did he start?","coverage":1.0},{"start":35.51,"end":40.19,"text":"Well, Dyson was born in England in 1947.","coverage":0.875},{"start":40.51,"end":43.95,"text":"His father died when he was only nine.","coverage":1.0},{"start":44.48,"end":49.43,"text":"As a result, Dyson ended up becoming someone who never gave up.","coverage":0.917},{"start":49.94,"end":53.91,"text":"He studied Art and Design before he studied Engineering.","coverage":1.0},{"start":54.26,"end":60.99,"text":"When he saw something that didn’t work well, he got frustrated and worked to improve it.","coverage":1.0},{"start":61.44,"end":66.96,"text":"For example, his first invention was a wheelbarrow with a ball for a wheel.","coverage":0.929},{"start":67.21,"end":73.23,"text":"This made it easier to carry heavy things in the garden and over rough ground.","coverage":1.0},{"start":73.55,"end":76.71,"text":"It was an interesting new use for a ball.","coverage":1.0},{"start":77.04,"end":84.06,"text":"Also, even though he changed subjects, he was still interested in art as well as designing.","coverage":1.0},{"start":84.66,"end":85.89,"text":"Take a look at this photo.","coverage":1.0},{"start":86.58,"end":87.37,"text":"What do you see?","coverage":1.0},{"start":87.68,"end":93.94,"text":"Ebru: It looks like a waterfall made from glass and water, with the water running up instead of falling down.","coverage":0.95},{"start":94.24,"end":95.47,"text":"That’s surprising.","coverage":1.0},{"start":96.1,"end":96.84,"text":"Student presenter: That’s right.","coverage":0.6},{"start":97.15,"end":103.52,"text":"This was a piece of art that Dyson made in 2003, called Wrong Garden.","coverage":0.929},{"start":104.02,"end":105.65,"text":"It tricks the eye.","coverage":1.0},{"start":106.09,"end":111.02,"text":"This shows Dyson’s love of good design as well as being an inventor.","coverage":0.929},{"start":111.92,"end":114.31,"text":"Dyson is still inventing new things.","coverage":0.667},{"start":114.53,"end":125.56,"text":"But he is also interested in supporting education for students and gives money to schools to help students study so they might become inventors, too.","coverage":0.96},{"start":125.92,"end":134.27,"text":"He has even donated money to the University of Cambridge to support students and research there, with a focus on technology.","coverage":1.0}],"file":"1b6fa64d01b9f23a2205.js","track":0,"media":"../assets/media/aa2f30af804e3c9cd614d55500b4cb01f27c2ac3cef470feda4b890aa0f881a1.wav"}],"../assets/media/5b8d0c8544211fb9d6bc12c80234eeef403d5fe063cdf54b9f4be03fd4c8f3d1.mp3":[{"id":"PPT_5b8d0c8544211fb9","audioId":"PPT_5b8d0c8544211fb9","title":"Book 2 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 47","duration":378.23,"cues":[{"start":0.0,"end":1.84,"text":"Unit two,","coverage":1.0},{"start":2.16,"end":3.6,"text":"two .one","coverage":1.0},{"start":4.88,"end":13.82,"text":"Today, I'm at the Vivid Sydney Festival, which has been held in Australia every year since 2009.","coverage":1.0},{"start":14.06,"end":18.0,"text":"It's held for three weeks during May and June.","coverage":1.0},{"start":18.46,"end":23.24,"text":"It has loads of activities with music, food, art and learning.","coverage":1.0},{"start":23.98,"end":26.08,"text":"Anybody can go to the lectures,","coverage":1.0},{"start":26.46,"end":29.28,"text":"see the lights and eat interesting food.","coverage":1.0},{"start":29.28,"end":31.86,"text":"Many activities are free.","coverage":1.0},{"start":32.5,"end":35.16,"text":"The festival gets bigger every year.","coverage":1.0},{"start":35.6,"end":38.88,"text":"Sometimes over two million people come.","coverage":1.0},{"start":39.64,"end":42.88,"text":"We asked one of the visitors about the festival.","coverage":1.0},{"start":43.72,"end":43.84,"text":"Hello","coverage":1.0},{"start":43.84,"end":44.44,"text":"there.","coverage":1.0},{"start":44.86,"end":51.36,"text":"Can you introduce yourself and tell me, is this your first time at the festival here in Sydney?","coverage":1.0},{"start":52.4,"end":54.34,"text":"My name is Olivia and no,","coverage":1.0},{"start":54.74,"end":56.04,"text":"I come here every year.","coverage":1.0},{"start":56.72,"end":59.22,"text":"Why do you like coming to the festival?","coverage":1.0},{"start":60.26,"end":62.82,"text":"Well, it's an interesting event to come to.","coverage":1.0},{"start":63.16,"end":65.84,"text":"It's great for children and adults.","coverage":1.0},{"start":66.86,"end":71.72,"text":"I enjoy learning about all the new ideas people have on important topics.","coverage":1.0},{"start":72.54,"end":81.12,"text":"We don't get much time to really think or learn about new things in everyday life, but you can do exactly that at this festival.","coverage":1.0},{"start":81.92,"end":85.8,"text":"So what kinds of things do people learn and do here?","coverage":1.0},{"start":86.18,"end":88.96,"text":"Do people try mainly one type of thing?","coverage":1.0},{"start":89.88,"end":90.36,"text":"No,","coverage":1.0},{"start":90.7,"end":93.08,"text":"most people plan on going to several events.","coverage":1.0},{"start":93.72,"end":96.36,"text":"For example, today I learned about nature.","coverage":1.0},{"start":97.12,"end":100.8,"text":"I went to a lecture about the sea and new ways to clean it.","coverage":1.0},{"start":101.36,"end":102.54,"text":"It's quite interesting.","coverage":1.0},{"start":103.42,"end":106.2,"text":"Yesterday, I walked around a 3D art show.","coverage":1.0},{"start":106.86,"end":109.38,"text":"The entire room was covered in pictures.","coverage":1.0},{"start":109.38,"end":111.64,"text":"It was an exciting activity.","coverage":1.0},{"start":112.42,"end":115.24,"text":"It felt like flying over the trees and mountains.","coverage":1.0},{"start":116.12,"end":121.26,"text":"And tomorrow, I'm going to a talk on how food can help people live better lives,","coverage":1.0},{"start":121.7,"end":124.0,"text":"which I'm sure will really make me think.","coverage":1.0},{"start":125.28,"end":128.1,"text":"Are there any things you don't like about it?","coverage":1.0},{"start":128.56,"end":129.68,"text":"Are you ever bored?","coverage":1.0},{"start":130.66,"end":131.4,"text":"Not really.","coverage":1.0},{"start":132.1,"end":134.74,"text":"The only problem is that it's really crowded.","coverage":1.0},{"start":135.84,"end":138.0,"text":"Olivia, like many others,","coverage":1.0},{"start":138.38,"end":141.5,"text":"is really enjoying the Vivid Sydney Festival.","coverage":1.0},{"start":142.1,"end":142.72,"text":"Nowadays,","coverage":1.0},{"start":143.06,"end":146.0,"text":"around the world, there are many festivals,","coverage":1.0},{"start":146.5,"end":148.3,"text":"often based on nature,","coverage":1.0},{"start":148.66,"end":149.92,"text":"food, or culture.","coverage":1.0},{"start":150.64,"end":154.58,"text":"Take the Cherry Blossom Festival in Japan, for example.","coverage":1.0},{"start":155.22,"end":156.08,"text":"In Tokyo,","coverage":1.0},{"start":156.44,"end":157.72,"text":"the capital of Japan,","coverage":1.0},{"start":158.16,"end":161.68,"text":"the Cherry Blossom Festival is held in early April.","coverage":1.0},{"start":161.68,"end":165.46,"text":"It is an important festival celebrating nature.","coverage":1.0},{"start":166.16,"end":173.7,"text":"The actual dates change every year because the celebration happens only when the trees have cherry blossoms.","coverage":1.0},{"start":174.18,"end":184.38,"text":"So it is a little different from a festival that has the same date every year, and it's not organized in the same way as many other festivals.","coverage":1.0},{"start":185.2,"end":189.42,"text":"Our reporter, Mike Pearce, went to Tokyo to find out.","coverage":1.0},{"start":190.24,"end":192.48,"text":"Today I am talking with Yuki.","coverage":1.0},{"start":193.24,"end":197.74,"text":"She sells food during the Cherry Blossom Festival in Ueno Park in Tokyo.","coverage":1.0},{"start":198.46,"end":199.6,"text":"Hi, Yuki.","coverage":1.0},{"start":200.5,"end":200.82,"text":"Hi.","coverage":1.0},{"start":201.38,"end":203.94,"text":"Welcome to the Cherry Blossom Festival.","coverage":1.0},{"start":204.94,"end":205.4,"text":"Thanks.","coverage":1.0},{"start":206.16,"end":207.9,"text":"So what happens here?","coverage":1.0},{"start":208.82,"end":210.9,"text":"Well, as you can see,","coverage":1.0},{"start":211.22,"end":213.22,"text":"it's a cherry blossom festival.","coverage":1.0},{"start":213.88,"end":217.88,"text":"It is a celebration of spring and the cherry flowers.","coverage":1.0},{"start":217.88,"end":223.08,"text":"So it doesn't have specific activities that people do.","coverage":1.0},{"start":223.82,"end":224.2,"text":"Instead,","coverage":1.0},{"start":224.64,"end":230.24,"text":"people come to enjoy the cherry blossoms and have a picnic under the trees.","coverage":1.0},{"start":231.12,"end":236.4,"text":"We have about a thousand trees full of beautiful flowers.","coverage":1.0},{"start":237.76,"end":240.62,"text":"Do you have many people here from other countries?","coverage":1.0},{"start":241.66,"end":242.26,"text":"Yes.","coverage":1.0},{"start":242.74,"end":246.08,"text":"Our visitors are from all over the world.","coverage":1.0},{"start":246.64,"end":248.98,"text":"In addition to the cherry blossoms,","coverage":1.0},{"start":249.28,"end":251.42,"text":"there are lots of food stalls,","coverage":1.0},{"start":251.92,"end":255.42,"text":"and people can hire a boat to go around the lake,","coverage":1.0},{"start":255.92,"end":255.96,"text":"too.","coverage":1.0},{"start":256.62,"end":260.36,"text":"There are many beautiful natural places here.","coverage":1.0},{"start":260.84,"end":264.9,"text":"Some people prefer to visit some of the park's many museums,","coverage":1.0},{"start":265.28,"end":271.8,"text":"but I think Tokyo is one of the best places to come for the Cherry Blossom Festival.","coverage":1.0},{"start":272.82,"end":275.32,"text":"Well, I hope you enjoy the rest of the event.","coverage":1.0},{"start":276.82,"end":281.0,"text":"Visiting such festivals is not just for entertainment.","coverage":1.0},{"start":281.42,"end":287.76,"text":"It's also a fantastic way to find out about the culture of a different country.","coverage":1.0},{"start":288.46,"end":293.54,"text":"I went to Oman in the Middle East recently to do just that.","coverage":1.0},{"start":294.42,"end":300.4,"text":"I'm here in Muscat at the Festival of Culture and Heritage talking to Nasra.","coverage":1.0},{"start":300.4,"end":305.66,"text":"She is visiting the festival Muscat Nights with her family.","coverage":1.0},{"start":306.64,"end":311.68,"text":"The event is held in January and February each year in Oman,","coverage":1.0},{"start":312.34,"end":316.12,"text":"and Nasra has been coming for the last couple of years.","coverage":1.0},{"start":316.7,"end":317.62,"text":"Hi, Nasra.","coverage":1.0},{"start":317.9,"end":319.78,"text":"Are you enjoying the festival?","coverage":1.0},{"start":320.82,"end":322.8,"text":"Yes, it's wonderful.","coverage":1.0},{"start":324.02,"end":326.78,"text":"Can you tell us something about the festival?","coverage":1.0},{"start":326.78,"end":328.58,"text":"Of course.","coverage":1.0},{"start":329.12,"end":333.14,"text":"It's a chance for people to learn about the heritage and culture of Oman.","coverage":1.0},{"start":334.26,"end":335.92,"text":"So why are you here?","coverage":1.0},{"start":336.78,"end":339.36,"text":"My mother and father want to watch some of the sports.","coverage":1.0},{"start":339.98,"end":343.1,"text":"There was basketball last year and also a car race.","coverage":1.0},{"start":343.82,"end":345.82,"text":"You can listen to traditional music,","coverage":1.0},{"start":346.6,"end":348.96,"text":"but I decided to go to the fashion show.","coverage":1.0},{"start":349.68,"end":351.02,"text":"That sounds great.","coverage":1.0},{"start":351.02,"end":352.1,"text":"Yeah.","coverage":1.0},{"start":352.98,"end":355.62,"text":"And after we finish watching the races and shows,","coverage":1.0},{"start":356.0,"end":358.0,"text":"we'll go and eat some traditional food.","coverage":1.0},{"start":358.96,"end":360.32,"text":"Sounds amazing.","coverage":1.0},{"start":360.86,"end":363.1,"text":"I hope you all have a great time.","coverage":1.0},{"start":364.2,"end":368.12,"text":"So these international festivals with lots of music,","coverage":1.0},{"start":368.44,"end":373.54,"text":"food and fashion are providing a different type of experience for people.","coverage":1.0},{"start":374.3,"end":377.78,"text":"Next week, we'll be looking at...","coverage":1.0}],"file":"1e9fda57179879062c9a.js","track":0,"media":"../assets/media/5b8d0c8544211fb9d6bc12c80234eeef403d5fe063cdf54b9f4be03fd4c8f3d1.mp3"}],"../assets/media/daecdec49254ef5c34b49d701e6b3e25ca3f0b2e11f7a46d8276903fe41cbbfb.wav":[{"id":"B2_U04_T4.4_LONG_L01_v01","audioId":"B2_U04_T4.4_LONG_L01_v01","title":"Book 2 · Unit 4 · 课后听力材料","subtitle":"Homework listening material","duration":89.13086167800454,"cues":[{"start":0.35,"end":7.8,"text":"Reporter: Global warming is an important issue around the world.","coverage":0.9},{"start":9.03,"end":14.0,"text":"Recently it has created problems in the Western Ghats rainforests of India.","coverage":0.833},{"start":15.83,"end":21.81,"text":"Forests are important for slowing down global warming because of the work that trees do for us.","coverage":0.941},{"start":22.87,"end":23.98,"text":"Trees are global cleaners.","coverage":1.0},{"start":25.39,"end":31.12,"text":"They take in carbon dioxide (CO2), the gas that heats the atmosphere.","coverage":1.0},{"start":31.72,"end":37.26,"text":"So, we keep making global warming worse every time we cut down trees.","coverage":1.0},{"start":38.01,"end":42.12,"text":"Then global warming continues to damage the forest.","coverage":1.0},{"start":42.8,"end":49.06,"text":"More trees disappear because the changes in temperature stop the normal growth of the forest.","coverage":1.0},{"start":51.65,"end":56.68,"text":"Nowadays, rainforests get less rain and this is changing the way they work.","coverage":0.846},{"start":57.43,"end":60.75,"text":"Governments around the world are beginning to work on the problem.","coverage":1.0},{"start":61.35,"end":69.87,"text":"Although governments say they will stop people damaging the forests, scientists don’t think the work is happening quickly enough.","coverage":1.0},{"start":70.45,"end":73.78,"text":"The scientists say the forests are changing.","coverage":1.0},{"start":74.39,"end":78.48,"text":"The animals, and the plants that animals need, are changing.","coverage":1.0},{"start":79.0,"end":88.34,"text":"In fact, scientists believe 45% of the forest areas are going to change completely in the next 80 years.","coverage":1.0}],"file":"22a0f8df72189e40955b.js","track":0,"media":"../assets/media/daecdec49254ef5c34b49d701e6b3e25ca3f0b2e11f7a46d8276903fe41cbbfb.wav"}],"../assets/media/e7380da7a415df4c33813aef96214be3d68f00897d393d9f5db2033375524f4d.mp3":[{"id":"PPT_e7380da7a415df4c","audioId":"PPT_e7380da7a415df4c","title":"Book 3 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 52","duration":306.99,"cues":[{"start":0.0,"end":2.22,"text":"eight .two","coverage":1.0},{"start":2.22,"end":3.4,"text":"Part two","coverage":1.0},{"start":4.34,"end":6.9,"text":"When you think of someone who is very rich,","coverage":1.0},{"start":7.34,"end":8.7,"text":"what comes to mind?","coverage":1.0},{"start":9.22,"end":13.74,"text":"Most people think that rich people live lavish lifestyles.","coverage":1.0},{"start":14.04,"end":17.26,"text":"That is, they drive very expensive cars,","coverage":1.0},{"start":17.82,"end":19.78,"text":"eat in expensive restaurants,","coverage":1.0},{"start":20.5,"end":23.36,"text":"own a yacht or live in big houses.","coverage":1.0},{"start":24.08,"end":26.56,"text":"But as John Home discovered,","coverage":1.0},{"start":27.16,"end":30.96,"text":"people who have money don't actually do these things.","coverage":1.0},{"start":31.76,"end":36.16,"text":"Most millionaires actually seem to have ordinary lifestyles.","coverage":1.0},{"start":36.88,"end":37.88,"text":"In other words,","coverage":1.0},{"start":38.28,"end":39.94,"text":"they have normal cars,","coverage":1.0},{"start":40.84,"end":43.0,"text":"average houses and so on.","coverage":1.0},{"start":43.52,"end":44.76,"text":"On the other hand,","coverage":1.0},{"start":45.14,"end":46.48,"text":"people who look rich,","coverage":1.0},{"start":46.98,"end":54.94,"text":"the people who drive the latest Ferrari or only wear designer clothes may not actually be rich at all.","coverage":1.0},{"start":55.84,"end":56.36,"text":"Instead,","coverage":1.0},{"start":56.72,"end":60.16,"text":"they have spent all their money trying to show off,","coverage":1.0},{"start":60.46,"end":63.3,"text":"showing other people that they might be wealthy.","coverage":1.0},{"start":64.06,"end":65.0,"text":"In other words,","coverage":1.0},{"start":65.32,"end":70.56,"text":"having expensive things is not always a sign that someone is rich.","coverage":1.0},{"start":71.64,"end":75.62,"text":"So what do millionaires do and what can we learn from them?","coverage":1.0},{"start":76.5,"end":77.04,"text":"Well,","coverage":1.0},{"start":77.46,"end":79.9,"text":"millionaires are often financially savvy.","coverage":1.0},{"start":80.72,"end":82.08,"text":"To put it another way,","coverage":1.0},{"start":82.56,"end":86.06,"text":"they're smart about how to save and spend money.","coverage":1.0},{"start":86.96,"end":92.9,"text":"The first important thing is that millionaires always have a good handle on their budget.","coverage":1.0},{"start":93.94,"end":94.94,"text":"In other words,","coverage":1.0},{"start":95.42,"end":97.42,"text":"they know how much they're spending.","coverage":1.0},{"start":98.24,"end":99.52,"text":"According to Home,","coverage":1.0},{"start":99.98,"end":109.46,"text":"around 75 % of millionaires know exactly how much money they have and they know exactly how much they spend on food,","coverage":1.0},{"start":109.82,"end":110.3,"text":"bills,","coverage":1.0},{"start":110.66,"end":111.18,"text":"clothes,","coverage":1.0},{"start":111.58,"end":111.94,"text":"etc.","coverage":1.0},{"start":112.8,"end":113.68,"text":"As a result,","coverage":1.0},{"start":114.08,"end":117.86,"text":"they don't spend too much and they don't get into debt.","coverage":1.0},{"start":118.82,"end":122.38,"text":"They can plan for the future and save their money.","coverage":1.0},{"start":123.22,"end":123.96,"text":"To sum up,","coverage":1.0},{"start":124.34,"end":128.62,"text":"the lesson here is that you should never spend more money than you have.","coverage":1.0},{"start":130.28,"end":135.54,"text":"Another surprising fact is that millionaires usually have simple lifestyles.","coverage":1.0},{"start":136.02,"end":142.7,"text":"They have nice houses and nice cars, but they don't spend all their money on these things.","coverage":1.0},{"start":143.48,"end":144.2,"text":"In fact,","coverage":1.0},{"start":144.7,"end":153.06,"text":"most rich people stay in the same place for a very long time and don't live in big expensive palaces.","coverage":1.0},{"start":153.68,"end":154.04,"text":"Indeed,","coverage":1.0},{"start":154.62,"end":155.96,"text":"according to John Home,","coverage":1.0},{"start":156.4,"end":161.02,"text":"half of millionaires have lived in the same house for 20 years.","coverage":1.0},{"start":161.86,"end":168.52,"text":"Also, around 65 % of millionaires live in homes which cost around the national average.","coverage":1.0},{"start":169.84,"end":170.24,"text":"Again,","coverage":1.0},{"start":170.66,"end":174.0,"text":"the important lesson here is to live within your means.","coverage":1.0},{"start":174.0,"end":177.94,"text":"That is, don't spend more money than you have.","coverage":1.0},{"start":178.78,"end":182.06,"text":"If you spend all your savings on a luxury BMW,","coverage":1.0},{"start":182.86,"end":184.7,"text":"then you probably aren't rich.","coverage":1.0},{"start":185.02,"end":186.94,"text":"You just want to look rich.","coverage":1.0},{"start":187.66,"end":188.32,"text":"In fact,","coverage":1.0},{"start":188.72,"end":190.95,"text":"the study reveals that 86 %","coverage":1.0},{"start":191.4,"end":195.46,"text":"of luxury cars are bought by people who can't afford them.","coverage":1.0},{"start":196.42,"end":199.08,"text":"Most rich people don't have bank loans.","coverage":1.0},{"start":199.6,"end":205.9,"text":"They only spend a small percentage of what they have and they save or invest the rest.","coverage":1.0},{"start":207.36,"end":209.16,"text":"Now here is an interesting fact.","coverage":1.0},{"start":209.86,"end":214.22,"text":"The study shows that most millionaires have very happy relationships.","coverage":1.0},{"start":215.26,"end":216.78,"text":"Not only are they married,","coverage":1.0},{"start":217.2,"end":219.84,"text":"but they stay married for a long time.","coverage":1.0},{"start":220.48,"end":222.0,"text":"In John Holmes' opinion,","coverage":1.0},{"start":222.42,"end":227.16,"text":"this is very important because of the golden rule about saving money.","coverage":1.0},{"start":227.94,"end":228.42,"text":"There is","coverage":1.0},{"start":228.42,"end":228.68,"text":"no","coverage":1.0},{"start":228.68,"end":232.5,"text":"doubt that it's more difficult to save money if you are single.","coverage":1.0},{"start":233.3,"end":237.64,"text":"One effect of being a couple is that it's easier to save money.","coverage":1.0},{"start":238.44,"end":244.96,"text":"If there are two of you, it's easier to pay attention to what money you have and what you're spending.","coverage":1.0},{"start":246.02,"end":251.5,"text":"And of course, people who don't have huge bank loans and debts are happier.","coverage":1.0},{"start":252.82,"end":256.42,"text":"If you don't have to worry about the monthly credit card payments,","coverage":1.0},{"start":256.84,"end":260.32,"text":"you're less likely to buy things to make you feel better.","coverage":1.0},{"start":261.5,"end":270.86,"text":"People with debt often spend more time shopping just to make themselves feel happier, but real millionaires don't need to do this.","coverage":1.0},{"start":271.66,"end":273.98,"text":"So what can we learn from the idea of being wealthy?","coverage":1.0},{"start":274.74,"end":277.34,"text":"The answer is surprisingly simple.","coverage":1.0},{"start":278.22,"end":280.42,"text":"Don't spend more money than you have.","coverage":1.0},{"start":281.06,"end":284.18,"text":"Don't get into debt or take out bank loans.","coverage":1.0},{"start":285.02,"end":291.46,"text":"Pay close attention to your money and don't spend time trying to show other people that you're rich.","coverage":1.0},{"start":292.64,"end":294.12,"text":"In John Holmes' opinion,","coverage":1.0},{"start":294.5,"end":296.44,"text":"being wealthy is a feeling.","coverage":1.0},{"start":296.44,"end":297.74,"text":"That is,","coverage":1.0},{"start":298.12,"end":301.1,"text":"it doesn't mean being rich or having millions.","coverage":1.0},{"start":301.92,"end":305.08,"text":"It means being happy with what you have.","coverage":1.0}],"file":"23e6be9fc88a4363d613.js","track":0,"media":"../assets/media/e7380da7a415df4c33813aef96214be3d68f00897d393d9f5db2033375524f4d.mp3"}],"../assets/media/e0c1d2783bb4a6ee91d0dd0a2dcffcf352f036048b02011b9881dae750580d26.mp3":[{"id":"B2_U04_T4.4_SHORT_S01_v01","audioId":"B2_U04_T4.4_SHORT_S01_v01","title":"Book 2 · Unit 4 · 课后听力材料","subtitle":"Homework listening material","duration":56.294943,"cues":[{"start":0.35,"end":7.8,"text":"Reporter: Global warming is an important issue around the world.","coverage":0.9},{"start":9.03,"end":14.0,"text":"Recently it has created problems in the Western Ghats rainforests of India.","coverage":0.833},{"start":15.83,"end":21.81,"text":"Forests are important for slowing down global warming because of the work that trees do for us.","coverage":0.941},{"start":22.87,"end":23.98,"text":"Trees are global cleaners.","coverage":1.0},{"start":25.39,"end":31.12,"text":"They take in carbon dioxide (CO2), the gas that heats the atmosphere.","coverage":1.0},{"start":31.72,"end":37.26,"text":"So, we keep making global warming worse every time we cut down trees.","coverage":1.0},{"start":38.01,"end":42.12,"text":"Then global warming continues to damage the forest.","coverage":1.0},{"start":42.8,"end":49.06,"text":"More trees disappear because the changes in temperature stop the normal growth of the forest.","coverage":1.0},{"start":51.38,"end":55.84,"text":"Nowadays, rainforests get less rain and this is changing the way they work.","coverage":0.846}],"file":"25209bba6b86cb9240b2.js","track":0,"media":"../assets/media/e0c1d2783bb4a6ee91d0dd0a2dcffcf352f036048b02011b9881dae750580d26.mp3"}],"../assets/media/6f87606941725525fceb11227e29216f90eaf9585817d7004df8a4c6cb279646.wav":[{"id":"B3_U08_T8.2_LONG_L01_v01","audioId":"B3_U08_T8.2_LONG_L01_v01","title":"Book 3 · Unit 8 · H3 · 听力材料 1","subtitle":"H3 · 8.2-L01","duration":129.46392290249432,"cues":[{"start":2.38,"end":2.56,"text":"Part 2","coverage":0.5},{"start":4.95,"end":9.11,"text":"Woman: When you think of someone who is very rich, what comes to mind?","coverage":0.929},{"start":9.52,"end":24.28,"text":"Most people think that rich people live lavish lifestyles – that is, they drive very expensive cars, eat in expensive restaurants, own a yacht or live in big houses.","coverage":1.0},{"start":24.76,"end":30.94,"text":"But, as John Holm discovered, people who have money don’t actually do these things.","coverage":0.933},{"start":32.34,"end":36.06,"text":"Most millionaires actually seem to have ordinary lifestyles.","coverage":1.0},{"start":37.19,"end":43.17,"text":"In other words, they have normal cars, average houses and so on.","coverage":1.0},{"start":43.67,"end":54.13,"text":"On the other hand, people who look rich – the people who drive the latest Ferrari or only wear designer clothes – may not actually be rich at all.","coverage":1.0},{"start":54.73,"end":63.8,"text":"Instead, they have spent all their money trying to show off – showing other people that they might be wealthy.","coverage":1.0},{"start":64.16,"end":71.28,"text":"In other words, having expensive things is not always a sign that someone is rich.","coverage":1.0},{"start":71.76,"end":75.6,"text":"So, what do millionaires do and what can we learn from them?","coverage":1.0},{"start":76.62,"end":80.39,"text":"Well, millionaires are often financially savvy.","coverage":1.0},{"start":80.76,"end":86.62,"text":"To put it another way, they’re smart about how to save and spend money.","coverage":1.0},{"start":87.04,"end":93.39,"text":"The first important thing is that millionaires always have a good handle on their budget.","coverage":1.0},{"start":93.66,"end":98.04,"text":"In other words, they know how much they’re spending.","coverage":1.0},{"start":98.42,"end":111.41,"text":"According to Holm, around 75 percent of millionaires know exactly how much money they have and they know exactly how much they spend on food, bills, clothes, etc.","coverage":0.929},{"start":111.81,"end":117.93,"text":"As a result, they don’t spend too much and they don’t get into debt.","coverage":1.0},{"start":118.4,"end":122.63,"text":"They can plan for the future and save their money.","coverage":1.0},{"start":123.28,"end":128.26,"text":"To sum up, the lesson here is that you should never spend more money than you have!","coverage":1.0}],"file":"267c0853aa5d17560d49.js","track":0,"media":"../assets/media/6f87606941725525fceb11227e29216f90eaf9585817d7004df8a4c6cb279646.wav"}],"../assets/media/af4ea175c7261f1c673b26fb6a66c6879ac8ba2400ba07065ca36e01b9b73a00.wav":[{"id":"B3_U08_T8.2_LONG_L02_v01","audioId":"B3_U08_T8.2_LONG_L02_v01","title":"Book 3 · Unit 8 · H3 · 听力材料 2","subtitle":"H3 · 8.2-L02","duration":77.3626984126984,"cues":[{"start":0.8,"end":6.0,"text":"Another surprising fact is that millionaires usually have simple lifestyles.","coverage":1.0},{"start":6.76,"end":13.9,"text":"They have nice houses and nice cars, but they don’t spend all their money on these things.","coverage":1.0},{"start":14.32,"end":22.7,"text":"In fact, most rich people stay in the same place for a very long time and don’t live in big, expensive palaces.","coverage":0.957},{"start":23.88,"end":31.96,"text":"Indeed, according to John Holm, half of millionaires have lived in the same house for 20 years.","coverage":0.882},{"start":32.36,"end":39.33,"text":"Also, around 65 percent of millionaires live in homes which cost around the national average.","coverage":0.933},{"start":40.06,"end":49.14,"text":"Again, the important lesson here is to live within your means – that is, don’t spend more money than you have.","coverage":1.0},{"start":49.56,"end":57.67,"text":"If you spend all your savings on a luxury BMW, then you probably aren’t rich – you just want to look rich.","coverage":1.0},{"start":58.44,"end":66.02,"text":"In fact, the study reveals that 86 percent of luxury cars are bought by people who can’t afford them.","coverage":0.95},{"start":66.5,"end":76.25,"text":"Most rich people don’t have bank loans – they only spend a small percentage of what they have and they save or invest the rest.","coverage":1.0}],"file":"267c0853aa5d17560d49.js","track":1,"media":"../assets/media/af4ea175c7261f1c673b26fb6a66c6879ac8ba2400ba07065ca36e01b9b73a00.wav"}],"../assets/media/e3319013a7595e5f2c632e7c3fab1b5b32be6730ffde4e20c7794c0cf3e9f8e4.wav":[{"id":"B3_U08_T8.2_LONG_L03_v01","audioId":"B3_U08_T8.2_LONG_L03_v01","title":"Book 3 · Unit 8 · H3 · 听力材料 3","subtitle":"H3 · 8.2-L03","duration":100.38950113378685,"cues":[{"start":0,"end":2.6,"text":"Now here is an interesting fact.","coverage":1.0},{"start":3.28,"end":8.49,"text":"The study shows that most millionaires have very happy relationships.","coverage":1.0},{"start":8.92,"end":13.75,"text":"Not only are they married, but they stay married for a long time.","coverage":1.0},{"start":14.21,"end":21.18,"text":"In John Holm’s opinion, this is very important because of the golden rule about saving money.","coverage":0.882},{"start":21.52,"end":26.52,"text":"There is no doubt that it’s more difficult to save money if you are single.","coverage":1.0},{"start":26.88,"end":31.69,"text":"One effect of being a couple is that it’s easier to save money.","coverage":1.0},{"start":32.08,"end":39.32,"text":"If there are two of you, it’s easier to pay attention to what money you have and what you’re spending.","coverage":1.0},{"start":39.7,"end":45.98,"text":"And of course, people who don’t have huge bank loans and debts are happier.","coverage":1.0},{"start":46.4,"end":54.72,"text":"If you don’t have to worry about the monthly credit card payments, you’re less likely to buy things to make you feel better.","coverage":1.0},{"start":55.16,"end":65.07,"text":"People with debt often spend more time shopping, just to make themselves feel happier, but real millionaires don’t need to do this.","coverage":1.0},{"start":65.44,"end":68.25,"text":"So, what can we learn from the wealthy?","coverage":1.0},{"start":68.6,"end":70.94,"text":"The answer is surprisingly simple.","coverage":1.0},{"start":71.25,"end":73.99,"text":"Don’t spend more money than you have.","coverage":1.0},{"start":74.32,"end":77.48,"text":"Don’t get into debt or take out bank loans.","coverage":1.0},{"start":77.81,"end":85.51,"text":"Pay close attention to your money and don’t spend time trying to show other people that you’re rich.","coverage":1.0},{"start":86.21,"end":90.04,"text":"In John Holm’s opinion, being ‘wealthy’ is a feeling.","coverage":0.8},{"start":90.39,"end":94.9,"text":"That is, it doesn’t mean being rich or having millions.","coverage":1.0},{"start":95.2,"end":98.28,"text":"It means being happy with what you have.","coverage":1.0}],"file":"267c0853aa5d17560d49.js","track":2,"media":"../assets/media/e3319013a7595e5f2c632e7c3fab1b5b32be6730ffde4e20c7794c0cf3e9f8e4.wav"}],"../assets/media/119e4981d152a50e5d659570f40817ccc8837a7d8d02fd456587256ffe25280d.mp3":[{"id":"B2_U01_T1.3_SHORT_S01_v01","audioId":"B2_U01_T1.3_SHORT_S01_v01","title":"Book 2 · Unit 1 · H2 · 听力材料 1","subtitle":"H2 · S01","duration":62.8778,"cues":[{"start":0.2,"end":4.46,"text":"OK, everyone.","coverage":1.0},{"start":5.24,"end":8.79,"text":"Today we are talking about interesting places.","coverage":1.0},{"start":9.49,"end":16.03,"text":"I’d like to talk about the city of Vancouver, in British Columbia, Canada.","coverage":1.0},{"start":16.4,"end":20.8,"text":"It’s one of the most beautiful cities in the world.","coverage":1.0},{"start":21.88,"end":28.5,"text":"We often think cities are urban areas, with traffic and modern buildings.","coverage":1.0},{"start":29.03,"end":34.15,"text":"We don’t usually think cities have woods, lakes and fields.","coverage":1.0},{"start":34.86,"end":44.42,"text":"But Vancouver is a ‘green city’ - a place that’s good to live in because it has clean air, water and land.","coverage":1.0},{"start":45.08,"end":51.23,"text":"Vancouver has the best parts of green forests and city life.","coverage":1.0},{"start":51.72,"end":61.76,"text":"I would like to talk about some of the history of Vancouver as well as some of the advantages and disadvantages of this ‘green’ city.","coverage":1.0}],"file":"27574ab895f16778a3d8.js","track":0,"media":"../assets/media/119e4981d152a50e5d659570f40817ccc8837a7d8d02fd456587256ffe25280d.mp3"}],"../assets/media/baf7d6202c79a08250ca92e5790d3306ad7dbe03fa247fa84605e668d9f8195c.mp3":[{"id":"B2_U01_T1.3_SHORT_S02_v01","audioId":"B2_U01_T1.3_SHORT_S02_v01","title":"Book 2 · Unit 1 · H2 · 听力材料 2","subtitle":"H2 · S02","duration":52.572494,"cues":[{"start":0.78,"end":15.02,"text":"Vancouver originally was a place where the native people of the area lived and traded for thousands of years before Europeans came to live there in the 1800s.","coverage":1.0},{"start":15.43,"end":30.76,"text":"Then in 1886, at the first city meeting, the people of Vancouver asked the national government to give the city 1,000 acres to use as a park.","coverage":1.0},{"start":31.27,"end":36.62,"text":"They got the land from the government and started Stanley Park.","coverage":1.0},{"start":37.01,"end":44.89,"text":"This was the start of Vancouver becoming a green city with many parks and beautiful views.","coverage":1.0},{"start":45.67,"end":51.88,"text":"But being a green city with lots of parks has both advantages and disadvantages.","coverage":1.0}],"file":"27574ab895f16778a3d8.js","track":1,"media":"../assets/media/baf7d6202c79a08250ca92e5790d3306ad7dbe03fa247fa84605e668d9f8195c.mp3"}],"../assets/media/320c959a1822278796248a183cbe739d11248c22e3caaf6f37a94fbeedad30c3.mp3":[{"id":"B2_U01_T1.3_SHORT_S03_v01","audioId":"B2_U01_T1.3_SHORT_S03_v01","title":"Book 2 · Unit 1 · H2 · 听力材料 3","subtitle":"H2 · S03","duration":73.496576,"cues":[{"start":0.04,"end":3.64,"text":"First of all, let’s look at some of the positives.","coverage":1.0},{"start":4.83,"end":7.91,"text":"Obviously, Stanley Park is a large park.","coverage":1.0},{"start":8.27,"end":17.46,"text":"In fact, because it is located in the city of Vancouver, it is the third largest urban park in North America.","coverage":1.0},{"start":17.9,"end":29.25,"text":"It has many gardens, walking paths, trees and even animals, such as bald eagles, coyotes and seals.","coverage":0.882},{"start":29.95,"end":34.45,"text":"As we know, lots of trees help clean the city air.","coverage":1.0},{"start":35.12,"end":42.28,"text":"Also, lots of parks give people many places to walk, so they’re healthier.","coverage":1.0},{"start":42.74,"end":52.29,"text":"Since Vancouver is near the mountains and the ocean, people can enjoy the outdoors easily during the warm, sunny summers.","coverage":1.0},{"start":52.62,"end":72.31,"text":"When people go to Stanley Park, they can enjoy ancient trees as they walk near the ocean or they can have fun by Beaver Lake, which, like Stanley Park, helps make Vancouver one of the healthiest and cleanest cities in the world.","coverage":0.952}],"file":"27574ab895f16778a3d8.js","track":2,"media":"../assets/media/320c959a1822278796248a183cbe739d11248c22e3caaf6f37a94fbeedad30c3.mp3"}],"../assets/media/2a571b9dabbff49c8609974dcdc44061efb34bdace038518ebb07b3e6dc2e697.mp3":[{"id":"B2_U01_T1.3_SHORT_S04_v01","audioId":"B2_U01_T1.3_SHORT_S04_v01","title":"Book 2 · Unit 1 · H2 · 听力材料 4","subtitle":"H2 · S04","duration":66.0778,"cues":[{"start":0.04,"end":5.57,"text":"I’d also like to talk about some disadvantages of parks in Vancouver.","coverage":1.0},{"start":6.73,"end":9.9,"text":"Space in a city is very important.","coverage":1.0},{"start":10.19,"end":17.96,"text":"Having many parks means that people have less space to build houses and apartments.","coverage":1.0},{"start":18.48,"end":26.07,"text":"Because Vancouver is located between the mountains and the ocean, there’s not much room for new buildings.","coverage":1.0},{"start":26.39,"end":29.6,"text":"This makes Vancouver an expensive city.","coverage":1.0},{"start":30.73,"end":36.72,"text":"Also, when you have a beautiful place to live, a lot of people want to go there.","coverage":1.0},{"start":37.04,"end":39.48,"text":"This makes the city crowded.","coverage":1.0},{"start":39.94,"end":43.78,"text":"Actually, Vancouver has very bad traffic.","coverage":1.0},{"start":44.13,"end":52.47,"text":"Lastly, when you have a lot of parks, wild animals in the parks can sometimes be a problem.","coverage":1.0},{"start":52.78,"end":59.77,"text":"For example, Stanley Park gives information to people about what to do if they see a coyote.","coverage":0.941},{"start":60.73,"end":65.12,"text":"In my opinion, having coyotes in a city park is bad.","coverage":0.909}],"file":"27574ab895f16778a3d8.js","track":3,"media":"../assets/media/2a571b9dabbff49c8609974dcdc44061efb34bdace038518ebb07b3e6dc2e697.mp3"}],"../assets/media/d6115ad75c886a1ee2afaf592e36af4cb1cdd2940b18de295dbf48a82c53e420.mp3":[{"id":"B2_U01_T1.3_SHORT_S05_v01","audioId":"B2_U01_T1.3_SHORT_S05_v01","title":"Book 2 · Unit 1 · H2 · 听力材料 5","subtitle":"H2 · S05","duration":44.562971,"cues":[{"start":0.56,"end":14.07,"text":"Finally, while I think these disadvantages might mean that some people would not want to visit Vancouver, I personally feel that most people would enjoy Vancouver.","coverage":1.0},{"start":14.48,"end":22.7,"text":"In my opinion, being close to nature and having a healthy city are worth paying a little more money for.","coverage":1.0},{"start":23.56,"end":32.5,"text":"And a lot of people agree with this idea because Vancouver is a very popular place to visit and live in.","coverage":1.0},{"start":33.08,"end":42.24,"text":"So I would recommend that people visit Vancouver and enjoy the many parks, the clean, healthy city and the interesting sights.","coverage":0.952}],"file":"27574ab895f16778a3d8.js","track":4,"media":"../assets/media/d6115ad75c886a1ee2afaf592e36af4cb1cdd2940b18de295dbf48a82c53e420.mp3"}],"../assets/media/3ffb075c009f5992ffb729bf24d6132a2e9884bbdbe50dbfee6c35a23e958043.wav":[{"id":"B3_U06_T6.1_SHORT_S01_v01","audioId":"B3_U06_T6.1_SHORT_S01_v01","title":"Book 3 · Unit 6 · 课后听力材料","subtitle":"Homework listening material","duration":103.64195011337868,"cues":[{"start":3.87,"end":6.3,"text":"Man: Welcome to the Museum of Science!","coverage":0.857},{"start":7.22,"end":13.52,"text":"The exhibition that we’re about to see is called Discovering Medieval Science.","coverage":0.923},{"start":14.2,"end":20.5,"text":"As some of you may know, the Middle Ages have often been called the ‘Dark Ages’.","coverage":1.0},{"start":21.22,"end":25.62,"text":"During this tour, you will find out that they were not.","coverage":1.0},{"start":26.23,"end":33.68,"text":"The Middle Ages were an interesting time and they were full of scientific discoveries.","coverage":1.0},{"start":34.22,"end":45.67,"text":"During this time, inventions and technology from India, China, North Africa and the Middle East were brought to Europe.","coverage":1.0},{"start":47.15,"end":57.66,"text":"Inventions and machines designed by medieval scholars made a great contribution to society and many are still in use today.","coverage":0.95},{"start":58.23,"end":62.59,"text":"And some of these inventions are very common.","coverage":1.0},{"start":63.23,"end":70.53,"text":"For example, the first fountain pen was made in 953 in Africa.","coverage":0.917},{"start":71.22,"end":76.61,"text":"Before then, people used bird feathers and ink to write with.","coverage":1.0},{"start":77.23,"end":83.64,"text":"This method would often leave your fingers and clothes covered with black ink.","coverage":1.0},{"start":84.22,"end":97.34,"text":"So the first fountain pen had a small container with ink inside and did not stain people’s clothes or fingers while the user was writing.","coverage":1.0},{"start":98.23,"end":103.57,"text":"You can see a model of this fountain pen in Room 11B.","coverage":1.0}],"file":"2870e156f3d1a74b06df.js","track":0,"media":"../assets/media/3ffb075c009f5992ffb729bf24d6132a2e9884bbdbe50dbfee6c35a23e958043.wav"}],"../assets/media/e811cb835a43f346a88a9fa5bf50fdd126bbd1033834d9a5e38ca5f673a6c9a6.mp3":[{"id":"B3_U07_T7.1_SHORT_S01_v01","audioId":"B3_U07_T7.1_SHORT_S01_v01","title":"Book 3 · Unit 7 · 课后听力材料","subtitle":"Homework listening material","duration":47.230454,"cues":[{"start":4.07,"end":8.78,"text":"Yoriko: So, Hamed, shall we continue working on our group presentation?","coverage":0.818},{"start":9.35,"end":9.9,"text":"Hamed: Good idea, Yoriko.","coverage":0.5},{"start":11.35,"end":19.64,"text":"Now, Danial and Samia are focusing on the environmental issues of fast fashion – so we’ll be talking about copyright infringement.","coverage":0.905},{"start":20.29,"end":24.22,"text":"Yoriko: Danial said they’ve already written their part of the presentation, you know ...","coverage":0.857},{"start":24.79,"end":25.67,"text":"Hamed: Wow, really?","coverage":0.667},{"start":26.48,"end":28.95,"text":"We’ve only just got started on ours!","coverage":1.0},{"start":29.59,"end":40.38,"text":"Anyway, we’re focusing on the way that fast fashion companies lift unknown artists’ designs and put them onto their products, which they then sell in huge numbers.","coverage":1.0},{"start":40.95,"end":41.68,"text":"Yoriko: That’s right.","coverage":0.75},{"start":42.13,"end":46.47,"text":"So, first, I think we should talk about what happened to Vanessa Bowman.","coverage":1.0}],"file":"29a7a715e718e7559677.js","track":0,"media":"../assets/media/e811cb835a43f346a88a9fa5bf50fdd126bbd1033834d9a5e38ca5f673a6c9a6.mp3"}],"../assets/media/871ce69611556a6430fcfe65b2ba57b291bd173da19d2dbbed18a5f4c9e8ffd5.mp3":[{"id":"PPT_871ce69611556a64","audioId":"PPT_871ce69611556a64","title":"Book 2 · Unit 1 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 59","duration":230.4,"cues":[{"start":0.0,"end":2.3,"text":"one .two","coverage":1.0},{"start":3.02,"end":5.46,"text":"Welcome to the Travel Podcast.","coverage":1.0},{"start":5.96,"end":6.74,"text":"I'm James.","coverage":1.0},{"start":7.44,"end":12.86,"text":"I'm here with Susie and today we're looking at unusual places where people actually live.","coverage":1.0},{"start":13.52,"end":14.98,"text":"Susie, when you travelled,","coverage":1.0},{"start":15.44,"end":19.18,"text":"did you see any interesting or strange homes around the world?","coverage":1.0},{"start":20.18,"end":23.06,"text":"Well, it depends what you mean by strange.","coverage":1.0},{"start":23.06,"end":25.38,"text":"I live in a detached house,","coverage":1.0},{"start":25.98,"end":29.0,"text":"so the apartment buildings in New York, for example,","coverage":1.0},{"start":29.54,"end":31.34,"text":"seem pretty strange to me.","coverage":1.0},{"start":32.28,"end":35.76,"text":"I really mean places that very few people know about.","coverage":1.0},{"start":36.76,"end":38.04,"text":"Oh, I see.","coverage":1.0},{"start":38.64,"end":39.9,"text":"Um, well,","coverage":1.0},{"start":40.34,"end":42.74,"text":"when I was on holiday last year in Peru,","coverage":1.0},{"start":43.12,"end":46.48,"text":"I saw a really old city made out of mud.","coverage":1.0},{"start":47.58,"end":49.88,"text":"You could say that is interesting.","coverage":1.0},{"start":51.12,"end":53.5,"text":"Yes, that is very interesting.","coverage":1.0},{"start":54.44,"end":58.3,"text":"And so are the cave houses in the lowest part of China.","coverage":1.0},{"start":59.64,"end":60.24,"text":"Lowest?","coverage":1.0},{"start":60.78,"end":62.04,"text":"Where is that in China?","coverage":1.0},{"start":63.1,"end":64.5,"text":"It's in the north part.","coverage":1.0},{"start":65.14,"end":66.18,"text":"Take a look at the picture.","coverage":1.0},{"start":66.96,"end":68.08,"text":"Do you see these caves?","coverage":1.0},{"start":68.96,"end":70.54,"text":"Well, they're actually houses.","coverage":1.0},{"start":71.44,"end":74.12,"text":"Some people think the cave houses look strange.","coverage":1.0},{"start":74.96,"end":77.38,"text":"But millions of people live in these houses.","coverage":1.0},{"start":78.1,"end":79.98,"text":"Many houses are below the ground.","coverage":1.0},{"start":80.92,"end":83.38,"text":"Other houses are caves in the side of hills.","coverage":1.0},{"start":84.0,"end":86.48,"text":"They made them out of the soil and rock.","coverage":1.0},{"start":87.24,"end":90.32,"text":"People started to live in them four ,000 years ago.","coverage":1.0},{"start":90.94,"end":92.88,"text":"Wow, that's ancient.","coverage":1.0},{"start":93.52,"end":94.68,"text":"Where is it exactly?","coverage":1.0},{"start":95.7,"end":99.28,"text":"It's about one ,000 kilometres west of the capital, Beijing.","coverage":1.0},{"start":99.9,"end":101.24,"text":"I'd love to go there.","coverage":1.0},{"start":102.0,"end":105.52,"text":"Actually, when I was younger, I went to Cappadocia in Turkey.","coverage":1.0},{"start":105.52,"end":107.38,"text":"It was fantastic.","coverage":1.0},{"start":108.14,"end":109.8,"text":"There are cave houses there too.","coverage":1.0},{"start":110.4,"end":112.84,"text":"It's in Anatolia in the centre of Turkey.","coverage":1.0},{"start":113.4,"end":114.08,"text":"Take a look.","coverage":1.0},{"start":114.74,"end":116.68,"text":"The buildings look like mushrooms.","coverage":1.0},{"start":117.96,"end":119.58,"text":"Interesting place, isn't it?","coverage":1.0},{"start":119.92,"end":123.86,"text":"The caves formed from rock more than eight ,000 years ago.","coverage":1.0},{"start":124.74,"end":127.84,"text":"People changed them into homes during the Roman period.","coverage":1.0},{"start":128.54,"end":130.46,"text":"Some people still live there now.","coverage":1.0},{"start":131.2,"end":131.68,"text":"Now?","coverage":1.0},{"start":132.26,"end":133.28,"text":"That's amazing.","coverage":1.0},{"start":133.92,"end":136.68,"text":"But did you know that some people live on bridges?","coverage":1.0},{"start":137.38,"end":138.78,"text":"Look at these two photos.","coverage":1.0},{"start":139.72,"end":139.85,"text":"Oh","coverage":1.0},{"start":139.85,"end":140.44,"text":"yeah,","coverage":1.0},{"start":141.1,"end":143.08,"text":"I think I recognise this bridge.","coverage":1.0},{"start":143.82,"end":146.16,"text":"It's beautiful and it looks very old.","coverage":1.0},{"start":147.0,"end":149.06,"text":"It's in Italy, isn't it?","coverage":1.0},{"start":149.92,"end":151.12,"text":"Is it in Rome?","coverage":1.0},{"start":152.14,"end":153.48,"text":"Well, it is in Italy.","coverage":1.0},{"start":154.02,"end":155.8,"text":"It's called the Ponte Vecchio,","coverage":1.0},{"start":156.32,"end":158.88,"text":"but it's actually in Florence, north of Rome.","coverage":1.0},{"start":159.56,"end":162.18,"text":"They built the bridge in 1345.","coverage":1.0},{"start":162.5,"end":166.74,"text":"There was another bridge there before, but an accident destroyed it.","coverage":1.0},{"start":167.18,"end":170.4,"text":"So they made this one and people started to live there.","coverage":1.0},{"start":171.06,"end":172.86,"text":"It's amazing, isn't it?","coverage":1.0},{"start":173.86,"end":175.48,"text":"Yes, it is.","coverage":1.0},{"start":176.4,"end":179.3,"text":"But the houses in the other picture look newer.","coverage":1.0},{"start":180.22,"end":182.48,"text":"Yeah, those are Palafitos,","coverage":1.0},{"start":182.92,"end":184.38,"text":"stilt houses in Chile.","coverage":1.0},{"start":185.04,"end":185.38,"text":"Where?","coverage":1.0},{"start":186.06,"end":187.3,"text":"You know, Chile,","coverage":1.0},{"start":187.78,"end":188.74,"text":"in South America.","coverage":1.0},{"start":189.74,"end":190.82,"text":"Oh, of course.","coverage":1.0},{"start":191.5,"end":193.14,"text":"Are they on a bridge too?","coverage":1.0},{"start":194.24,"end":200.44,"text":"No, they build these houses over lakes or over the edge of the sea, not over rivers.","coverage":1.0},{"start":201.04,"end":202.1,"text":"They're on stilts.","coverage":1.0},{"start":203.2,"end":206.82,"text":"People started to build these over 100 years ago.","coverage":1.0},{"start":207.54,"end":210.98,"text":"The people fish in the lake or the sea near their houses.","coverage":1.0},{"start":212.42,"end":212.86,"text":"Really?","coverage":1.0},{"start":213.52,"end":215.62,"text":"So these houses aren't ancient.","coverage":1.0},{"start":216.7,"end":217.96,"text":"Do many people live there?","coverage":1.0},{"start":218.92,"end":219.44,"text":"Yes,","coverage":1.0},{"start":219.88,"end":222.14,"text":"hundreds of people still live like this.","coverage":1.0},{"start":223.16,"end":223.64,"text":"Well,","coverage":1.0},{"start":224.04,"end":226.4,"text":"they make my house look really boring.","coverage":1.0},{"start":227.82,"end":228.54,"text":"Mine too.","coverage":1.0}],"file":"2a60d18ed7691fd3eb57.js","track":0,"media":"../assets/media/871ce69611556a6430fcfe65b2ba57b291bd173da19d2dbbed18a5f4c9e8ffd5.mp3"}],"../assets/media/2eb6fdcb2760c4275faa44cc2634b666e7bbaa8eef13dd75d87b863f34ecf66d.mp3":[{"id":"PPT_2eb6fdcb2760c427","audioId":"PPT_2eb6fdcb2760c427","title":"Book 3 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 23","duration":33.72,"cues":[{"start":0.0,"end":1.84,"text":"Unit three,","coverage":1.0},{"start":2.5,"end":4.14,"text":"three .one.","coverage":1.0},{"start":4.56,"end":5.36,"text":"one.","coverage":1.0},{"start":6.22,"end":10.0,"text":"There has been a decrease in the number of bus passengers this year.","coverage":1.0},{"start":11.86,"end":12.54,"text":"two.","coverage":1.0},{"start":13.48,"end":17.36,"text":"The traffic will decrease after they have finished repairing the road.","coverage":1.0},{"start":19.46,"end":20.26,"text":"three.","coverage":1.0},{"start":21.26,"end":24.92,"text":"Most cities don't permit cyclists to ride on the pavement.","coverage":1.0},{"start":26.86,"end":27.66,"text":"four.","coverage":1.0},{"start":27.66,"end":31.8,"text":"You need a special permit to park in the city centre.","coverage":1.0}],"file":"2bcb306ae4467434255e.js","track":0,"media":"../assets/media/2eb6fdcb2760c4275faa44cc2634b666e7bbaa8eef13dd75d87b863f34ecf66d.mp3"}],"../assets/media/8a51f03a204efb0c83b9e8ff6fba679f57fd2ea4c59414540ab733feb95a9d97.mp3":[{"id":"PPT_8a51f03a204efb0c","audioId":"PPT_8a51f03a204efb0c","title":"Book 2 · Unit 8 · RW · READING 2","subtitle":"READING 2 · source slide 146","duration":176.01,"cues":[{"start":0.0,"end":2.08,"text":"Life on other planets.","coverage":1.0},{"start":3.2,"end":8.3,"text":"For many years, people have wondered whether we are the only living things in the universe.","coverage":1.0},{"start":9.34,"end":15.8,"text":"Some scientists believe that there must be life on other planets because the universe is so big.","coverage":1.0},{"start":16.5,"end":16.96,"text":"However,","coverage":1.0},{"start":17.46,"end":24.84,"text":"it is unlikely that there is life on other planets because planets need a very specific environment for life to start.","coverage":1.0},{"start":25.52,"end":27.06,"text":"In the end, there are","coverage":1.0},{"start":27.06,"end":27.34,"text":"no","coverage":1.0},{"start":27.34,"end":30.72,"text":"facts that support the idea of life on other planets.","coverage":1.0},{"start":32.12,"end":35.6,"text":"It is true that the universe has thousands of solar systems,","coverage":1.0},{"start":36.02,"end":38.02,"text":"and there are planets similar to Earth.","coverage":1.0},{"start":38.76,"end":40.74,"text":"During its nine years in space,","coverage":1.0},{"start":41.2,"end":48.94,"text":"the very powerful Kepler telescope found more than two ,600 planets in orbit around stars.","coverage":1.0},{"start":49.66,"end":50.3,"text":"In fact,","coverage":1.0},{"start":50.62,"end":56.36,"text":"a number of scientists think that one of these planets, named Kepler -22b,","coverage":1.0},{"start":56.78,"end":58.14,"text":"has the right conditions,","coverage":1.0},{"start":58.58,"end":60.52,"text":"the right atmosphere and temperature,","coverage":1.0},{"start":60.9,"end":61.96,"text":"to support life.","coverage":1.0},{"start":62.78,"end":63.34,"text":"However,","coverage":1.0},{"start":63.68,"end":64.02,"text":"there is","coverage":1.0},{"start":64.02,"end":64.36,"text":"no","coverage":1.0},{"start":64.36,"end":67.48,"text":"evidence that there is life on Kepler -22b.","coverage":1.0},{"start":68.58,"end":71.78,"text":"Experts argue that even with the best technology,","coverage":1.0},{"start":72.16,"end":72.78,"text":"we can see","coverage":1.0},{"start":72.78,"end":73.1,"text":"no","coverage":1.0},{"start":73.1,"end":74.32,"text":"signs of life there.","coverage":1.0},{"start":75.04,"end":77.2,"text":"Until research shows us hard evidence,","coverage":1.0},{"start":77.66,"end":83.24,"text":"we cannot use Kepler -22b to support the idea of life on other planets.","coverage":1.0},{"start":84.2,"end":88.26,"text":"A planet needs very particular conditions to support life.","coverage":1.0},{"start":89.02,"end":91.22,"text":"A planet with life would need to have water,","coverage":1.0},{"start":91.54,"end":92.46,"text":"the right temperature,","coverage":1.0},{"start":93.02,"end":95.64,"text":"and the right mix of chemicals in the atmosphere.","coverage":1.0},{"start":96.54,"end":99.22,"text":"Earth has the perfect conditions for life,","coverage":1.0},{"start":99.8,"end":105.3,"text":"and it is very unlikely that another planet has exactly the same environment as Earth.","coverage":1.0},{"start":105.96,"end":106.98,"text":"In addition,","coverage":1.0},{"start":107.62,"end":114.92,"text":"although some experts argue that life might exist on other planets, they have never found evidence to prove it.","coverage":1.0},{"start":115.36,"end":121.92,"text":"A report from Princeton University suggests that it is highly unlikely that there is life on other planets.","coverage":1.0},{"start":122.68,"end":129.2,"text":"The researchers believe that we don't have enough scientific evidence to decide if there is life on other planets.","coverage":1.0},{"start":129.92,"end":134.9,"text":"They say that just because conditions similar to Earth exist on other planets,","coverage":1.0},{"start":135.48,"end":137.86,"text":"it doesn't mean that life exists there.","coverage":1.0},{"start":138.81,"end":139.8,"text":"In conclusion,","coverage":1.0},{"start":140.44,"end":143.74,"text":"I do not believe that there is life on other planets.","coverage":1.0},{"start":144.68,"end":146.76,"text":"Although the universe is very big,","coverage":1.0},{"start":147.26,"end":150.84,"text":"a planet with life needs very special conditions.","coverage":1.0},{"start":151.74,"end":155.14,"text":"Earth has exactly the right conditions for life.","coverage":1.0},{"start":155.74,"end":158.6,"text":"It is not too hot or too cold.","coverage":1.0},{"start":159.22,"end":160.16,"text":"It has water,","coverage":1.0},{"start":160.58,"end":160.98,"text":"air,","coverage":1.0},{"start":161.32,"end":162.38,"text":"and the right chemicals.","coverage":1.0},{"start":163.1,"end":168.66,"text":"I do not think that any other planets could have exactly the same conditions as Earth.","coverage":1.0},{"start":169.44,"end":169.96,"text":"Therefore,","coverage":1.0},{"start":170.5,"end":174.08,"text":"I do not think that there could be life on other planets.","coverage":1.0}],"file":"2f620357bbc134792c46.js","track":0,"media":"../assets/media/8a51f03a204efb0c83b9e8ff6fba679f57fd2ea4c59414540ab733feb95a9d97.mp3"}],"../assets/media/b3b6b705449e7b968bf2584acb0e86e26aaf134a19105e5e4251ddfea07fa0d0.mp3":[{"id":"PPT_b3b6b705449e7b96","audioId":"PPT_b3b6b705449e7b96","title":"Book 2 · Unit 8 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 92","duration":55.43,"cues":[{"start":0.0,"end":2.0,"text":"eight .five","coverage":1.0},{"start":3.76,"end":5.36,"text":"Part one","coverage":1.0},{"start":5.36,"end":5.98,"text":"Hello","coverage":1.0},{"start":5.98,"end":6.64,"text":"everyone.","coverage":1.0},{"start":7.34,"end":13.06,"text":"We'll begin today's discussion with a look at how to pay for space exploration.","coverage":1.0},{"start":13.98,"end":21.58,"text":"We'll also evaluate the benefits of space exploration and whether the money we spend is worth it.","coverage":1.0},{"start":22.32,"end":26.34,"text":"We will first look at the options for paying for space exploration.","coverage":1.0},{"start":26.96,"end":29.38,"text":"I have three experts with me today.","coverage":1.0},{"start":30.22,"end":30.98,"text":"Dorota Loy,","coverage":1.0},{"start":31.58,"end":34.14,"text":"an engineer from the Space Development Project.","coverage":1.0},{"start":34.84,"end":37.5,"text":"Raj Paddow, a researcher in economics.","coverage":1.0},{"start":38.5,"end":39.82,"text":"And Dr Jun Wu,","coverage":1.0},{"start":40.22,"end":42.08,"text":"who is a professor of astrophysics.","coverage":1.0},{"start":42.84,"end":53.68,"text":"Let me ask Dr Wu to start us off by giving us a little information about the impact of space exploration and the importance of spending money on it.","coverage":1.0}],"file":"30ba5c11b2a46e1e5ca1.js","track":0,"media":"../assets/media/b3b6b705449e7b968bf2584acb0e86e26aaf134a19105e5e4251ddfea07fa0d0.mp3"}],"../assets/media/ba5b4d24e4beb60e5704cfd9876bab3348f4aa33a766df0b93785cc4fc939d6f.mp3":[{"id":"PPT_ba5b4d24e4beb60e","audioId":"PPT_ba5b4d24e4beb60e","title":"Book 3 · Unit 7 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 53","duration":237.35,"cues":[{"start":0.0,"end":1.42,"text":"Unit seven,","coverage":1.0},{"start":2.16,"end":3.4,"text":"seven .one.","coverage":1.0},{"start":4.58,"end":8.76,"text":"So, Hamad, shall we continue working on our group presentation?","coverage":1.0},{"start":9.26,"end":10.42,"text":"Good idea, Yuriko.","coverage":1.0},{"start":11.34,"end":11.8,"text":"Now,","coverage":1.0},{"start":12.28,"end":16.3,"text":"Daniel and Samia are focusing on the environmental issues of fast fashion,","coverage":1.0},{"start":16.8,"end":19.7,"text":"so we'll be talking about copyright infringement.","coverage":1.0},{"start":20.06,"end":24.14,"text":"Daniel said they've already written their part of the presentation, you know.","coverage":1.0},{"start":24.74,"end":25.86,"text":"Wow, really?","coverage":1.0},{"start":26.52,"end":28.5,"text":"We've only just got started on ours.","coverage":1.0},{"start":29.26,"end":29.86,"text":"Anyway,","coverage":1.0},{"start":30.36,"end":37.72,"text":"we're focusing on the way that fast fashion companies lift unknown artists' designs and put them onto their products,","coverage":1.0},{"start":38.06,"end":40.14,"text":"which they then sell in huge numbers.","coverage":1.0},{"start":40.9,"end":41.54,"text":"That's right.","coverage":1.0},{"start":42.06,"end":46.84,"text":"So, first, I think we should talk about what happened to Vanessa Bowman.","coverage":1.0},{"start":47.54,"end":50.78,"text":"The artist from the south of England who paints the world around her?","coverage":1.0},{"start":51.24,"end":51.76,"text":"Yes.","coverage":1.0},{"start":52.16,"end":54.02,"text":"Views out onto her garden,","coverage":1.0},{"start":54.44,"end":56.42,"text":"natural scenes, that sort of thing.","coverage":1.0},{"start":56.42,"end":64.44,"text":"A fast fashion company lifted images of her paintings they found on her website and used them on a clothing range.","coverage":1.0},{"start":64.98,"end":69.74,"text":"I'm sure they made a lot of money, and I don't think she got anything in return.","coverage":1.0},{"start":70.6,"end":72.5,"text":"No, she didn't get anything.","coverage":1.0},{"start":73.14,"end":73.27,"text":"No","coverage":1.0},{"start":73.27,"end":73.82,"text":"payment,","coverage":1.0},{"start":74.24,"end":74.33,"text":"no","coverage":1.0},{"start":74.33,"end":75.76,"text":"credit for her work, nothing.","coverage":1.0},{"start":76.52,"end":77.32,"text":"She's not alone,","coverage":1.0},{"start":78.24,"end":78.64,"text":"No.","coverage":1.0},{"start":78.88,"end":82.16,"text":"We should also use the example of Kirsty Morin.","coverage":1.0},{"start":82.16,"end":84.32,"text":"She creates interesting,","coverage":1.0},{"start":84.66,"end":86.42,"text":"unusual designs of animals.","coverage":1.0},{"start":86.92,"end":93.62,"text":"Her artwork was also used by a fast fashion company, and again, she got nothing from them.","coverage":1.0},{"start":94.32,"end":103.26,"text":"I mean, this is a perfect example of a company taking an artist's designs without permission and using them to sell clothes and make a profit.","coverage":1.0},{"start":103.9,"end":105.12,"text":"What can anyone do?","coverage":1.0},{"start":105.7,"end":113.48,"text":"Some large fashion companies take legal action when their designs are copied, but it takes money and power to do that.","coverage":1.0},{"start":113.94,"end":119.38,"text":"It's just not practical for an independent artist like Kirsty Morin to say,","coverage":1.0},{"start":120.0,"end":124.44,"text":"if you don't pay me for my hard work and talent, I'll be contacting my lawyer.","coverage":1.0},{"start":125.16,"end":131.58,"text":"Well, I have seen some examples of artists defending their intellectual property, but not many.","coverage":1.0},{"start":132.34,"end":133.78,"text":"Elora Petra, for example.","coverage":1.0},{"start":134.28,"end":135.86,"text":"I haven't read about her yet.","coverage":1.0},{"start":135.86,"end":145.78,"text":"She did do something about it after she discovered that a fast fashion company was converting her designs into images and putting them on clothing and bags.","coverage":1.0},{"start":146.7,"end":147.28,"text":"At first,","coverage":1.0},{"start":147.64,"end":150.52,"text":"Elora decided it wasn't worth complaining to them by email,","coverage":1.0},{"start":150.86,"end":152.52,"text":"so she tried a different approach.","coverage":1.0},{"start":153.16,"end":157.06,"text":"She posted her complaint on social media, and it went viral.","coverage":1.0},{"start":157.84,"end":164.62,"text":"Thousands of people from all over the world criticized the company and promised never to buy anything from them again.","coverage":1.0},{"start":165.32,"end":165.86,"text":"Finally,","coverage":1.0},{"start":166.3,"end":168.54,"text":"the company wrote to her offering an apology.","coverage":1.0},{"start":169.24,"end":174.14,"text":"They actually paid her something for using her work and promised it would never happen again.","coverage":1.0},{"start":174.88,"end":177.1,"text":"That's one happy ending, at least.","coverage":1.0},{"start":177.72,"end":178.72,"text":"Not quite.","coverage":1.0},{"start":179.46,"end":185.44,"text":"The same companies lifted her work several times since then and used it on all sorts of products.","coverage":1.0},{"start":186.3,"end":188.6,"text":"Although they've accepted it was their fault again,","coverage":1.0},{"start":189.0,"end":191.24,"text":"she still hasn't received a second payment.","coverage":1.0},{"start":191.94,"end":194.72,"text":"She's going to be disappointed this time, I imagine.","coverage":1.0},{"start":195.38,"end":207.54,"text":"The thing is, these companies do have the ability and the resources to collaborate with artists, pay them for their designs, and still make a lot of money, but they choose not to.","coverage":1.0},{"start":208.22,"end":208.76,"text":"I know.","coverage":1.0},{"start":209.04,"end":212.24,"text":"It's plagiarism, basically, and it's not ethical.","coverage":1.0},{"start":212.8,"end":214.72,"text":"Oh, I do agree.","coverage":1.0},{"start":215.26,"end":218.74,"text":"Imagine doing that sort of thing at our university.","coverage":1.0},{"start":219.69,"end":223.12,"text":"Can you see the situation changing anytime soon?","coverage":1.0},{"start":223.94,"end":226.12,"text":"No, I don't think it will change.","coverage":1.0},{"start":226.8,"end":227.78,"text":"In a few years,","coverage":1.0},{"start":228.3,"end":232.2,"text":"these companies will be ignoring copyright law just like they do now,","coverage":1.0},{"start":232.74,"end":235.42,"text":"and artists still won't be getting anything.","coverage":1.0}],"file":"327b611448e54353a27c.js","track":0,"media":"../assets/media/ba5b4d24e4beb60e5704cfd9876bab3348f4aa33a766df0b93785cc4fc939d6f.mp3"}],"../assets/media/3cbfe001f3a8f9a67e70a2e6c8d1e5c79ef3e6375b9404723daab9aac85433fa.mp3":[{"id":"B3_U08_T8.1_SHORT_S01_v01","audioId":"B3_U08_T8.1_SHORT_S01_v01","title":"Book 3 · Unit 8 · 课后听力材料","subtitle":"Homework listening material","duration":40.326599,"cues":[{"start":3.6,"end":4.6,"text":"Part 1"},{"start":5.72,"end":12.22,"text":"Woman: In this week’s programme, I’d like to talk about a book that has changed the way I think about money.","coverage":0.957},{"start":12.47,"end":15.58,"text":"It’s called The Secret of Being Wealthy.","coverage":0.875},{"start":16.8,"end":25.54,"text":"It was written by a business school graduate named John Holm who decided to study the behaviour of wealthy people.","coverage":0.95},{"start":25.9,"end":35.29,"text":"He paid close attention to what rich people do: checking where they eat, what they buy, how they live and so on.","coverage":1.0},{"start":35.96,"end":38.44,"text":"The results of his study were pretty surprising.","coverage":1.0}],"file":"3322ba172bdde3890626.js","track":0,"media":"../assets/media/3cbfe001f3a8f9a67e70a2e6c8d1e5c79ef3e6375b9404723daab9aac85433fa.mp3"}],"../assets/media/55e838b536f7d70ebaa932475b27451ac3a10b87267b3748ec10f5d82c0311fd.mp3":[{"id":"PPT_55e838b536f7d70e","audioId":"PPT_55e838b536f7d70e","title":"Book 3 · Unit 4 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 213","duration":23.41,"cues":[{"start":0.0,"end":1.48,"text":"Unit four,","coverage":1.0},{"start":2.1,"end":3.22,"text":"four .one","coverage":1.0},{"start":4.0,"end":8.36,"text":"This Sunday on Book of the Week we interview Dr Kevin Lee,","coverage":1.0},{"start":8.84,"end":11.24,"text":"the well -known anthropologist and author.","coverage":1.0},{"start":11.8,"end":16.22,"text":"In this podcast he will tell us of his love for cultural anthropology,","coverage":1.0},{"start":16.74,"end":21.54,"text":"and we'll discuss whether traditions are adapting to the modern world or dying out.","coverage":1.0}],"file":"3509fd5a6e01b34fba97.js","track":0,"media":"../assets/media/55e838b536f7d70ebaa932475b27451ac3a10b87267b3748ec10f5d82c0311fd.mp3"}],"../assets/media/5f2e61a1971ada35235e5eea528da3655146430517a73889bc970693db2786de.wav":[{"id":"B3_U02_T2.2_LONG_L01_v01","audioId":"B3_U02_T2.2_LONG_L01_v01","title":"Book 3 · Unit 2 · H3 · 听力材料 1","subtitle":"H3 · 2.2-L01","duration":97.2549433106576,"cues":[{"start":0.22,"end":2.35,"text":"Man: Good morning.","coverage":0.667},{"start":3.48,"end":11.91,"text":"Today I want to explain some alternative solutions which may help reduce some of the problems related to climate change.","coverage":1.0},{"start":12.24,"end":17.38,"text":"The first solution uses solar energy to grow food in the desert.","coverage":1.0},{"start":17.84,"end":20.9,"text":"First of all, I’ll explain how farming in the desert works.","coverage":1.0},{"start":21.32,"end":28.72,"text":"Then, we’ll briefly discuss how this type of farming could solve some of the environmental problems we are now facing.","coverage":1.0},{"start":28.95,"end":32.46,"text":"We’ll discuss some possible problems with this system.","coverage":1.0},{"start":32.98,"end":35.57,"text":"So, how does it work?","coverage":1.0},{"start":36.38,"end":40.84,"text":"As we all know, in order to grow plants we need water and sunlight.","coverage":1.0},{"start":41.3,"end":45.61,"text":"There’s a lot of sunlight in the desert, but very little water.","coverage":1.0},{"start":45.96,"end":50.77,"text":"Scientists have combined solar energy with a farming technology called hydroponics.","coverage":0.909},{"start":53.1,"end":55.44,"text":"Hydroponics means growing plants in water.","coverage":0.833},{"start":55.7,"end":61.92,"text":"Plants don’t need to grow in the ground, but they do need nutrients to help them grow.","coverage":1.0},{"start":63.37,"end":65.29,"text":"Nutrients are like food for the plants.","coverage":0.857},{"start":65.65,"end":72.21,"text":"So, if you add the nutrients to water, you can grow fruit and vegetables in water.","coverage":1.0},{"start":72.9,"end":86.4,"text":"NASA scientists have been developing this method of growing food because it could allow us to grow food in any climate – in Antarctica, the Sahara desert or even on Mars.","coverage":1.0},{"start":86.9,"end":91.95,"text":"You might ask how this method of growing plants helps with the problem of climate change.","coverage":1.0},{"start":92.17,"end":96.39,"text":"I mean, after all, it uses fresh water, which is a limited resource.","coverage":1.0}],"file":"360bed45a09a08ee05f6.js","track":0,"media":"../assets/media/5f2e61a1971ada35235e5eea528da3655146430517a73889bc970693db2786de.wav"}],"../assets/media/b56ce098d82d38f2aa6f78e09197ad5938e3b75c9febaa187aeee6deefdb864d.wav":[{"id":"B3_U02_T2.2_LONG_L02_v01","audioId":"B3_U02_T2.2_LONG_L02_v01","title":"Book 3 · Unit 2 · H3 · 听力材料 2","subtitle":"H3 · 2.2-L02","duration":127.51780045351474,"cues":[{"start":0,"end":6.62,"text":"An Australian company, Sundrop Farms, combined hydroponics with solar energy.","coverage":0.8},{"start":8.13,"end":12.77,"text":"Traditional farming uses between 60 and 80 percent of our planet’s fresh water.","coverage":0.929},{"start":13.97,"end":17.55,"text":"However, Sundrop Farms doesn’t use fresh water.","coverage":0.875},{"start":17.8,"end":18.61,"text":"It uses seawater.","coverage":0.667},{"start":21.04,"end":24.76,"text":"Sundrop Farms is only 100 metres from the shore.","coverage":0.778},{"start":25.12,"end":31.48,"text":"A line of mirrors reflects heat from the sun onto a pipe which has oil inside.","coverage":1.0},{"start":31.92,"end":38.43,"text":"The hot oil in the pipe heats up seawater, which is kept in special containers.","coverage":0.933},{"start":38.8,"end":45.35,"text":"When the seawater reaches 160 degrees Celsius, the steam provides electricity.","coverage":0.909},{"start":45.68,"end":50.87,"text":"Some of the hot water is used to heat the greenhouse during the cold desert nights.","coverage":1.0},{"start":51.2,"end":57.21,"text":"The plants grow in the greenhouse – a building with glass walls and a glass ceiling.","coverage":1.0},{"start":57.56,"end":62.13,"text":"The rest of the heated water goes to a desalination plant.","coverage":0.909},{"start":63.73,"end":73.86,"text":"Desalination is when we remove the salt from seawater to create drinkable water – that is, water which is clean and safe to drink.","coverage":0.87},{"start":74.28,"end":81.61,"text":"The desalination plant can produce up to 10,000 litres of fresh water every day.","coverage":0.933},{"start":82.0,"end":88.12,"text":"The farmer adds nutrients to this fresh water and then grows fruit and vegetables.","coverage":1.0},{"start":88.44,"end":99.69,"text":"To summarize, solar energy removes the salt from the seawater and the fresh water is then used inside the greenhouse, where the plants are growing.","coverage":0.92},{"start":100.08,"end":104.32,"text":"Many people around the world are really excited about this technology.","coverage":1.0},{"start":104.6,"end":111.86,"text":"So far, Australian farms have grown tomatoes, peppers and cucumbers using hydroponics.","coverage":0.833},{"start":113.52,"end":121.22,"text":"Many supermarkets are interested in buying these vegetables because they’re grown without pesticides or other chemicals.","coverage":0.941},{"start":122.16,"end":127.518,"text":"Some people think hydroponics is the perfect solution to the world food crisis.","coverage":0.923}],"file":"360bed45a09a08ee05f6.js","track":1,"media":"../assets/media/b56ce098d82d38f2aa6f78e09197ad5938e3b75c9febaa187aeee6deefdb864d.wav"}],"../assets/media/78b080912c38e386bf3d14e6a3ae54a345fcf5adec1b9d98d81219c2703652e5.mp3":[{"id":"PPT_78b080912c38e386","audioId":"PPT_78b080912c38e386","title":"Book 3 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 95","duration":36.41,"cues":[{"start":0.0,"end":2.26,"text":"one .six","coverage":1.0},{"start":2.26,"end":3.14,"text":"one","coverage":1.0},{"start":3.98,"end":4.68,"text":"Large,","coverage":1.0},{"start":5.52,"end":6.08,"text":"white,","coverage":1.0},{"start":7.08,"end":7.44,"text":"strong","coverage":1.0},{"start":8.98,"end":10.38,"text":"two","coverage":1.0},{"start":11.0,"end":12.12,"text":"Pandas,","coverage":1.0},{"start":12.78,"end":13.76,"text":"sea turtles,","coverage":1.0},{"start":14.52,"end":15.54,"text":"chimpanzees,","coverage":1.0},{"start":16.28,"end":16.86,"text":"tigers","coverage":1.0},{"start":18.7,"end":20.1,"text":"three","coverage":1.0},{"start":21.0,"end":21.76,"text":"Poachers,","coverage":1.0},{"start":22.34,"end":23.3,"text":"loss of habitat,","coverage":1.0},{"start":24.74,"end":25.74,"text":"human contact","coverage":1.0},{"start":27.0,"end":30.18,"text":"four More guards,","coverage":1.0},{"start":30.9,"end":32.48,"text":"a ban on selling ivory,","coverage":1.0},{"start":33.6,"end":34.26,"text":"building fences","coverage":1.0}],"file":"3635ef9f464e8b99763c.js","track":0,"media":"../assets/media/78b080912c38e386bf3d14e6a3ae54a345fcf5adec1b9d98d81219c2703652e5.mp3"}],"../assets/media/ca887c04460f0cdfbf33dd1cb4ab699b0dc712a654e4409bb144a8fb0e34b72a.wav":[{"id":"B3_U03_T3.3_LONG_L01_v01","audioId":"B3_U03_T3.3_LONG_L01_v01","title":"Book 3 · Unit 3 · 课后听力材料","subtitle":"Homework listening material","duration":83.22718820861678,"cues":[{"start":2.25,"end":5.74,"text":"Host: Do you live, study or work in a large city?","coverage":0.909},{"start":6.2,"end":10.59,"text":"Are the traffic problems so serious they often cause you to be late?","coverage":1.0},{"start":11.29,"end":14.0,"text":"If so, you’re not alone.","coverage":1.0},{"start":14.29,"end":20.99,"text":"Over the past century, there’s been a huge increase in the traffic that moves through our cities.","coverage":1.0},{"start":21.27,"end":35.61,"text":"And if, as the United Nations predicts, 70% of the world’s population will be living in cities by the year 2050, what will we do when the amount of traffic increases even more?","coverage":1.0},{"start":36.29,"end":37.23,"text":"How will we cope?","coverage":1.0},{"start":38.2,"end":39.75,"text":"Can we do anything to control it?","coverage":1.0},{"start":40.29,"end":47.69,"text":"With me in today’s podcast is Mark Knowling, an expert in transport and traffic management.","coverage":0.938},{"start":48.29,"end":50.72,"text":"Mark, what’s happening in our cities?","coverage":1.0},{"start":51.17,"end":57.67,"text":"Mark: It’s a fact that, in a great many cities, the traffic is more extreme than ever before.","coverage":0.947},{"start":58.25,"end":64.7,"text":"The primary cause is that there are so many private vehicles on the roads carrying only one or two people.","coverage":1.0},{"start":65.3,"end":76.59,"text":"Compare this to buses, which are by far the most efficient option for reducing traffic, as they can transport huge numbers of passengers at the same time.","coverage":1.0},{"start":77.21,"end":82.72,"text":"But people don’t seem to want to leave their expensive cars at home and take the bus instead.","coverage":1.0}],"file":"3659c555150847c11883.js","track":0,"media":"../assets/media/ca887c04460f0cdfbf33dd1cb4ab699b0dc712a654e4409bb144a8fb0e34b72a.wav"}],"../assets/media/25455e2aa0d888995b95e5767ae2edc2edb36b5f6a2ffecf850985eb856af6b2.mp3":[{"id":"PPT_25455e2aa0d88899","audioId":"PPT_25455e2aa0d88899","title":"Book 3 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 64","duration":176.12,"cues":[{"start":0.0,"end":1.54,"text":"three .four","coverage":1.0},{"start":1.54,"end":4.98,"text":"And how can we solve these problems?","coverage":1.0},{"start":5.64,"end":7.88,"text":"Let's think again about traffic lights.","coverage":1.0},{"start":8.72,"end":10.58,"text":"Because of improvements in technology,","coverage":1.0},{"start":11.24,"end":16.08,"text":"modern traffic signals can measure how quickly the vehicles are moving along the roads,","coverage":1.0},{"start":16.7,"end":18.46,"text":"or see whether there's been a crash,","coverage":1.0},{"start":18.84,"end":22.0,"text":"and send this information back to a control center.","coverage":1.0},{"start":22.0,"end":23.94,"text":"I've heard about this.","coverage":1.0},{"start":24.44,"end":26.54,"text":"It means that the traffic controllers,","coverage":1.0},{"start":26.9,"end":28.7,"text":"either human or computer,","coverage":1.0},{"start":29.12,"end":32.42,"text":"can check for changes in traffic throughout the day,","coverage":1.0},{"start":32.78,"end":37.5,"text":"and figure out the best way to organize the signals to keep everything moving.","coverage":1.0},{"start":38.24,"end":38.66,"text":"Yes.","coverage":1.0},{"start":39.18,"end":45.34,"text":"They don't have to follow the same fixed timings for the lights all day long, like signals used to do.","coverage":1.0},{"start":45.34,"end":49.82,"text":"And although it's expensive to put in these signals across a whole city,","coverage":1.0},{"start":50.36,"end":52.28,"text":"it's far better than doing nothing.","coverage":1.0},{"start":53.62,"end":53.64,"text":"Technology,","coverage":1.0},{"start":54.08,"end":55.66,"text":"where would we be without it?","coverage":1.0},{"start":56.3,"end":56.94,"text":"Exactly.","coverage":1.0},{"start":58.0,"end":60.92,"text":"Which reminds me of another way to reduce traffic.","coverage":1.0},{"start":61.76,"end":64.44,"text":"Businesses replacing their vehicles with drones.","coverage":1.0},{"start":65.16,"end":65.66,"text":"Okay,","coverage":1.0},{"start":66.14,"end":66.86,"text":"tell me more.","coverage":1.0},{"start":66.86,"end":72.58,"text":"Some tasks city governments need to do, such as checking electricity lines,","coverage":1.0},{"start":73.18,"end":78.06,"text":"don't necessarily need to be carried out by a single person arriving in a big vehicle.","coverage":1.0},{"start":78.9,"end":83.0,"text":"A drone with a camera could send this information to engineers,","coverage":1.0},{"start":83.48,"end":85.74,"text":"who only need to go out if there is a problem.","coverage":1.0},{"start":86.6,"end":90.36,"text":"Think of how many work vans this could take off the roads every day.","coverage":1.0},{"start":90.72,"end":92.6,"text":"And delivery vans.","coverage":1.0},{"start":92.6,"end":94.78,"text":"That's another good example.","coverage":1.0},{"start":95.52,"end":96.56,"text":"In some cities,","coverage":1.0},{"start":97.1,"end":101.8,"text":"businesses can use drones to deliver small parcels, which is fantastic.","coverage":1.0},{"start":102.32,"end":104.96,"text":"It means even fewer vehicles on the roads.","coverage":1.0},{"start":105.7,"end":110.04,"text":"What would you say to people who refuse to give up driving their cars ever?","coverage":1.0},{"start":110.5,"end":114.84,"text":"I honestly think people should try to avoid driving as much as possible.","coverage":1.0},{"start":115.36,"end":118.64,"text":"But if they can't, they should consider their behavior.","coverage":1.0},{"start":118.64,"end":122.42,"text":"It's not just bad parking that causes traffic issues.","coverage":1.0},{"start":123.14,"end":126.08,"text":"Everyone needs to be a lot more responsible as drivers.","coverage":1.0},{"start":126.9,"end":127.54,"text":"In what way?","coverage":1.0},{"start":128.24,"end":130.26,"text":"When people get behind the steering wheel,","coverage":1.0},{"start":130.62,"end":132.98,"text":"they often become less helpful than normal.","coverage":1.0},{"start":133.68,"end":136.3,"text":"Like when someone is turning into a side street,","coverage":1.0},{"start":136.88,"end":142.22,"text":"that often means driving across the other lane, past vehicles going in the opposite direction.","coverage":1.0},{"start":142.22,"end":143.12,"text":"If","coverage":1.0},{"start":143.12,"end":143.4,"text":"no","coverage":1.0},{"start":143.4,"end":146.7,"text":"one slows down to let in the person who wants to turn,","coverage":1.0},{"start":147.14,"end":149.74,"text":"the traffic gets worse and worse behind them.","coverage":1.0},{"start":150.16,"end":157.48,"text":"Even more so if someone stops in traffic with their car across the side street that person wants to turn into.","coverage":1.0},{"start":158.16,"end":158.48,"text":"Ah!","coverage":1.0},{"start":159.06,"end":163.42,"text":"Listeners, if that doesn't annoy you as well, you're a better person than me.","coverage":1.0},{"start":164.28,"end":165.12,"text":"Me too!","coverage":1.0},{"start":165.6,"end":170.62,"text":"Please, everyone, stop and give people enough space to turn into side streets!","coverage":1.0},{"start":170.62,"end":171.58,"text":"Mark,","coverage":1.0},{"start":171.98,"end":173.32,"text":"thanks for joining me.","coverage":1.0},{"start":173.7,"end":174.24,"text":"Thank you.","coverage":1.0}],"file":"37461c2c02bda6a5ba14.js","track":0,"media":"../assets/media/25455e2aa0d888995b95e5767ae2edc2edb36b5f6a2ffecf850985eb856af6b2.mp3"}],"../assets/media/a12270f2c89eeb1e3b478a591a8b2ee1dd801c81b28822298cffc5aff912b764.mp3":[{"id":"B3_U01_T1.1_SHORT_S01_v01","audioId":"B3_U01_T1.1_SHORT_S01_v01","title":"Book 3 · Unit 1 · 课后听力材料","subtitle":"Homework listening material","duration":89.078617,"cues":[{"start":4.32,"end":5.16,"text":"Host: Hello and welcome.","coverage":0.75},{"start":6.32,"end":9.19,"text":"Today’s debate is on using animals for work.","coverage":1.0},{"start":10.17,"end":14.32,"text":"The first animal that was domesticated by humans is the dog.","coverage":0.909},{"start":14.88,"end":20.08,"text":"Even now, dogs are still used to protect our houses and keep us safe.","coverage":1.0},{"start":20.64,"end":26.83,"text":"Other domesticated animals – used for food – include sheep, cows and goats.","coverage":0.909},{"start":27.43,"end":33.17,"text":"The first donkeys were used by humans approximately 6,000 years ago in Egypt.","coverage":0.929},{"start":33.92,"end":38.86,"text":"Horses were domesticated 5,000 years ago in Europe and Asia.","coverage":0.909},{"start":39.48,"end":48.29,"text":"All these animals have been used to help human beings survive, either by providing food or by working for us.","coverage":1.0},{"start":48.92,"end":58.69,"text":"Horses, camels, elephants – they have all helped humans explore their land and transport goods from one place to another.","coverage":0.947},{"start":59.28,"end":60.11,"text":"But is this fair?","coverage":1.0},{"start":61.15,"end":62.22,"text":"What about animal rights?","coverage":1.0},{"start":63.04,"end":69.38,"text":"To argue for this issue today we have Amy Johnson, an animal rights activist and writer.","coverage":1.0},{"start":69.88,"end":84.07,"text":"To argue against the issue is Dr Jacob Kuryan Dr Kuryan is a professor of zoology, which is the scientific study of animals, and a writer of several books on animal welfare.","coverage":0.906},{"start":85.27,"end":89.04,"text":"You both have two minutes to introduce your point of view.","coverage":1.0}],"file":"390eba636d3a810ffd97.js","track":0,"media":"../assets/media/a12270f2c89eeb1e3b478a591a8b2ee1dd801c81b28822298cffc5aff912b764.mp3"}],"../assets/media/e43b343e0ba1fd58bafa3dd1a9b85bc95069c0e6c07b49753797321177c6baa7.mp3":[{"id":"B2_U04_T4.4_SHORT_S02_v01","audioId":"B2_U04_T4.4_SHORT_S02_v01","title":"Book 2 · Unit 4 · H1 · 听力材料 2","subtitle":"H1 · S02","duration":32.980658,"cues":[{"start":0.44,"end":3.94,"text":"Reporter: Governments around the world are beginning to work on the problem.","coverage":0.917},{"start":4.84,"end":12.95,"text":"Although governments say they will stop people damaging the forests, scientists don’t think the work is happening quickly enough.","coverage":1.0},{"start":13.63,"end":17.27,"text":"The scientists say the forests are changing.","coverage":1.0},{"start":17.63,"end":21.54,"text":"The animals, and the plants that animals need, are changing.","coverage":1.0},{"start":22.23,"end":31.95,"text":"In fact, scientists believe 45% of the forest areas are going to change completely in the next 80 years.","coverage":1.0}],"file":"396f909ecc86ccf896ef.js","track":1,"media":"../assets/media/e43b343e0ba1fd58bafa3dd1a9b85bc95069c0e6c07b49753797321177c6baa7.mp3"}],"../assets/media/c843f41738cc1234f3910c27f6c1f3da11e57a45519696ba21a3847b3f6f1fb7.mp3":[{"id":"B2_U04_T4.4_SHORT_S03_v01","audioId":"B2_U04_T4.4_SHORT_S03_v01","title":"Book 2 · Unit 4 · H1 · 听力材料 3","subtitle":"H1 · S03","duration":52.363515,"cues":[{"start":0.03,"end":3.95,"text":"Reporter: This is where the purple frog becomes important.","coverage":0.889},{"start":5.09,"end":9.16,"text":"A report tells us that the frog is in danger of disappearing forever.","coverage":1.0},{"start":10.41,"end":19.81,"text":"The frog can run very fast, makes a noise like a small chicken and is one of the most unusual animals in the world.","coverage":1.0},{"start":20.27,"end":26.24,"text":"Of course, for some people, the end of one type of frog is not important.","coverage":1.0},{"start":26.44,"end":35.71,"text":"But it is for Sathyabhama Das Biju, a researcher from Delhi University who discovered it in 2003.","coverage":0.824},{"start":36.13,"end":42.48,"text":"For him, the problems of the purple frog show what global warming is doing to the Indian rainforests.","coverage":0.944},{"start":44.49,"end":51.53,"text":"He explains that this interesting animal won’t be around much longer if we don’t look after the forests.","coverage":1.0}],"file":"396f909ecc86ccf896ef.js","track":2,"media":"../assets/media/c843f41738cc1234f3910c27f6c1f3da11e57a45519696ba21a3847b3f6f1fb7.mp3"}],"../assets/media/25c54bca8d7d4d84f8375ad81d1dadf92fb24868ac8bdd6e10bc2fe238f1ed5d.mp3":[{"id":"B2_U04_T4.4_SHORT_S04_v01","audioId":"B2_U04_T4.4_SHORT_S04_v01","title":"Book 2 · Unit 4 · H1 · 听力材料 4","subtitle":"H1 · S04","duration":41.091837,"cues":[{"start":0.47,"end":4.99,"text":"Reporter: Biju is going to present information about the forests next week.","coverage":0.833},{"start":5.8,"end":11.48,"text":"He hopes to get people interested in saving this frog and other animals that live in rainforests.","coverage":0.941},{"start":13.9,"end":19.55,"text":"During the next week, many people are meeting to talk about the climate and saving the rainforests.","coverage":0.941},{"start":21.82,"end":28.69,"text":"According to Biju, we need to plan now or we will probably lose some species completely.","coverage":0.938},{"start":29.04,"end":37.01,"text":"If we don’t think carefully about the climate of the forests, the purple frog possibly won’t be around for much longer.","coverage":1.0},{"start":37.78,"end":39.29,"text":"On to the weather report now …","coverage":0.667}],"file":"396f909ecc86ccf896ef.js","track":3,"media":"../assets/media/25c54bca8d7d4d84f8375ad81d1dadf92fb24868ac8bdd6e10bc2fe238f1ed5d.mp3"}],"../assets/media/1a9ea938d86d0f1181fcbf8991b1677f1431921fc476582956b8de30656b9b83.mp3":[{"id":"B3_U05_T5.1_SHORT_S01_v01","audioId":"B3_U05_T5.1_SHORT_S01_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 1","subtitle":"H1 · 5.1-S01","duration":41.720091,"cues":[{"start":4.17,"end":7.96,"text":"Host: Today we’re talking about the key to a long and happy life.","coverage":0.929},{"start":8.49,"end":16.01,"text":"Recent studies of people who live to be 100 years old have shown that a healthy diet and exercise may not be enough.","coverage":0.957},{"start":16.41,"end":24.88,"text":"In fact, many of the people who celebrate their hundredth birthday have not eaten a healthy diet and have never exercised regularly.","coverage":0.955},{"start":25.41,"end":29.87,"text":"This has led many people to believe that our lifestyles are not important.","coverage":1.0},{"start":30.41,"end":33.31,"text":"What’s most important is that we have good genes.","coverage":1.0},{"start":34.13,"end":39.7,"text":"It seems that if you have the right genes, then you’ll live for a long time, whatever you do.","coverage":1.0}],"file":"39bb4ab981b6857c8716.js","track":0,"media":"../assets/media/1a9ea938d86d0f1181fcbf8991b1677f1431921fc476582956b8de30656b9b83.mp3"}],"../assets/media/1d72318824b942f76607887be5aff882f6162e0298cd1e4ba0b9391a2c3f20a8.mp3":[{"id":"B3_U05_T5.2_SHORT_S01_v01","audioId":"B3_U05_T5.2_SHORT_S01_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 2","subtitle":"H1 · 5.2-S01","duration":57.470454,"cues":[{"start":0.24,"end":9.76,"text":"Host: So, new research shows that having a healthy lifestyle is not the most important thing if you want to live a long life.","coverage":0.958},{"start":10.19,"end":13.99,"text":"We asked four people on the street for their reactions to this news.","coverage":1.0},{"start":14.39,"end":16.83,"text":"Man (A): I think it’s great news!","coverage":0.75},{"start":17.55,"end":22.6,"text":"Most people think that if they eat healthy food and exercise a lot, they’ll live forever.","coverage":1.0},{"start":23.19,"end":26.48,"text":"These people never drink coffee or sugary drinks.","coverage":0.875},{"start":27.09,"end":30.8,"text":"They spend hours working out in the gym or doing yoga.","coverage":1.0},{"start":31.04,"end":34.14,"text":"And none of this matters if you have the wrong genes.","coverage":1.0},{"start":34.74,"end":38.63,"text":"I think that the key to a healthy life is to enjoy yourself.","coverage":1.0},{"start":39.12,"end":44.65,"text":"If you focus all your energy on what to do and what not to do, you’ll be unhappy eventually.","coverage":1.0},{"start":45.77,"end":48.61,"text":"There’s no question that happy people live longer.","coverage":1.0},{"start":48.93,"end":53.72,"text":"I’d much rather go out and have a pizza with friends than spend time in the gym.","coverage":1.0},{"start":54.08,"end":56.08,"text":"I’m really happy about this new research!","coverage":1.0}],"file":"39bb4ab981b6857c8716.js","track":1,"media":"../assets/media/1d72318824b942f76607887be5aff882f6162e0298cd1e4ba0b9391a2c3f20a8.mp3"}],"../assets/media/04fe6701e220961377654006c846b5c5064d90cecbbe5ae271c8aecca03c76b1.mp3":[{"id":"B3_U05_T5.2_SHORT_S02_v01","audioId":"B3_U05_T5.2_SHORT_S02_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 3","subtitle":"H1 · 5.2-S02","duration":48.601882,"cues":[{"start":0.11,"end":4.51,"text":"Woman (B): This research proves what I’ve known for a long time.","coverage":0.846},{"start":5.31,"end":9.78,"text":"It’s ridiculous to get too worried about healthy eating and exercise!","coverage":1.0},{"start":10.59,"end":16.61,"text":"My grandfather lived until he was 95, even though he never exercised.","coverage":1.0},{"start":17.03,"end":21.06,"text":"He ate lots of sugar and never ate vegetables.","coverage":1.0},{"start":21.55,"end":23.96,"text":"He was brought up in a different world.","coverage":1.0},{"start":24.31,"end":25.94,"text":"He had different habits.","coverage":1.0},{"start":26.23,"end":28.4,"text":"He certainly never went to a gym.","coverage":1.0},{"start":28.85,"end":33.26,"text":"Yes, I’m sure that genes are more important than our lifestyle.","coverage":1.0},{"start":34.19,"end":40.1,"text":"Of course, I’m not going to give up exercising or start eating fast food every day.","coverage":1.0},{"start":40.47,"end":47.7,"text":"The research shows I should stay in shape because it makes me feel better – but I won’t allow fitness to take over my whole life.","coverage":1.0}],"file":"39bb4ab981b6857c8716.js","track":2,"media":"../assets/media/04fe6701e220961377654006c846b5c5064d90cecbbe5ae271c8aecca03c76b1.mp3"}],"../assets/media/0281dd24acbeb3bc03144a4ac98314f71158d293b461acf55042c47d7d35ecb0.mp3":[{"id":"B3_U05_T5.2_SHORT_S03_v01","audioId":"B3_U05_T5.2_SHORT_S03_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 4","subtitle":"H1 · 5.2-S03","duration":34.756984,"cues":[{"start":0.38,"end":4.83,"text":"Man (C): Well, first of all, I prefer to exercise and eat well.","coverage":0.846},{"start":5.35,"end":6.98,"text":"What’s wrong with being healthy?","coverage":1.0},{"start":7.75,"end":12.88,"text":"I also think that you won’t know whether or not you have the right genes until you get sick.","coverage":1.0},{"start":13.36,"end":16.2,"text":"So why take the risk and be unhealthy?","coverage":1.0},{"start":16.29,"end":24.78,"text":"Also, don’t forget that you might get the flu or a cold much more easily when you don’t eat healthy food or exercise.","coverage":1.0},{"start":25.16,"end":28.99,"text":"I’d say that it’s always better to have a healthy lifestyle.","coverage":1.0},{"start":29.22,"end":34.17,"text":"There’s no doubt that bad health habits increase the chances of getting a serious illness.","coverage":1.0}],"file":"39bb4ab981b6857c8716.js","track":3,"media":"../assets/media/0281dd24acbeb3bc03144a4ac98314f71158d293b461acf55042c47d7d35ecb0.mp3"}],"../assets/media/40334c0c6b8f90f7891d8975cb5b6ac259e07556a383df37f177eba6b6ee41fe.mp3":[{"id":"B3_U05_T5.2_SHORT_S04_v01","audioId":"B3_U05_T5.2_SHORT_S04_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 5","subtitle":"H1 · 5.2-S04","duration":36.142358,"cues":[{"start":0.12,"end":1.16,"text":"Woman (D): Oh, that’s great.","coverage":0.667},{"start":1.68,"end":4.67,"text":"So now we should all eat fast food and stop exercising?","coverage":1.0},{"start":5.76,"end":9.37,"text":"I mean I look around and I see overweight children everywhere.","coverage":1.0},{"start":10.08,"end":34.15,"text":"No matter how good their genes are, I’m sure that these children won’t be able to enjoy a long and healthy life unless they give up crisps, chocolate bars, sugary drinks … Well, it’s great that some people can live to be 100 and do whatever they want in their lives, but I prefer to be careful and take care of myself because I don’t know if I have good genes!","coverage":0.973}],"file":"39bb4ab981b6857c8716.js","track":4,"media":"../assets/media/40334c0c6b8f90f7891d8975cb5b6ac259e07556a383df37f177eba6b6ee41fe.mp3"}],"../assets/media/21cba7b7a83dc36468305761b70f534a96470330fd1bca97966f4c27a4614e35.mp3":[{"id":"B3_U05_T5.6_SHORT_S01_v01","audioId":"B3_U05_T5.6_SHORT_S01_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 6","subtitle":"H1 · 5.6-S01","duration":55.145556,"cues":[{"start":0.22,"end":4.57,"text":"Presenter 1: Do you have problems focusing on your work?","coverage":0.8},{"start":5.0,"end":7.16,"text":"Are you under a lot of stress?","coverage":1.0},{"start":8.12,"end":12.84,"text":"Do you want to get more exercise while trying something new and exciting?","coverage":1.0},{"start":13.16,"end":14.9,"text":"If so, it’s time to take up taekwondo!","coverage":0.889},{"start":16.79,"end":18.14,"text":"Taekwondo is great exercise.","coverage":0.75},{"start":18.32,"end":22.19,"text":"And as we all know, exercise is good for your health.","coverage":1.0},{"start":23.22,"end":28.45,"text":"Taekwondo also has mental benefits – it has been shown to improve your concentration.","coverage":0.923},{"start":29.7,"end":33.37,"text":"In addition, it makes you feel good about yourself.","coverage":1.0},{"start":33.76,"end":39.27,"text":"This martial art was developed in Korea and is now popular around the world.","coverage":1.0},{"start":39.64,"end":48.04,"text":"Whether you are looking for physical well-being, increased confidence or a life with less stress, Black Belt Taekwondo has it all.","coverage":0.955},{"start":48.36,"end":53.57,"text":"Sign up now for a free introductory class, starting on January the 15th.","coverage":1.0}],"file":"39bb4ab981b6857c8716.js","track":5,"media":"../assets/media/21cba7b7a83dc36468305761b70f534a96470330fd1bca97966f4c27a4614e35.mp3"}],"../assets/media/80d9b4c1b89ee6ad51ac282c77f9e64848664e71d7c548b11f20d6449ac63747.mp3":[{"id":"B3_U05_T5.6_SHORT_S02_v01","audioId":"B3_U05_T5.6_SHORT_S02_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 7","subtitle":"H1 · 5.6-S02","duration":68.193719,"cues":[{"start":0,"end":10.88,"text":"Presenter 2: Would you like to improve your social life, your intellectual performance, your physical fitness and your team-building skills?","coverage":0.905},{"start":11.36,"end":16.59,"text":"Scientific research has proven that team sports offer all of these benefits.","coverage":1.0},{"start":16.96,"end":21.03,"text":"Join us and take advantage of the many benefits of team sports.","coverage":1.0},{"start":21.44,"end":33.77,"text":"We’re a group of energetic adults of all ages who get together on Sunday afternoons to play football and we’re always looking for new players to join in the fun.","coverage":0.969},{"start":34.48,"end":42.1,"text":"Whether you’ve been playing football for years or want to take up a new sport, you’re welcome to participate.","coverage":1.0},{"start":42.62,"end":46.4,"text":"Everyone can play – you don’t even need to try out!","coverage":1.0},{"start":46.73,"end":58.84,"text":"If you’re interested in learning more about our group, check out our website at www.footballsundays.cup.com.","coverage":0.895},{"start":58.88,"end":64.22,"text":"Sign up today and you can be part of a team as early as this weekend!","coverage":1.0},{"start":64.6,"end":66.52,"text":"Hope to see you on the field soon!","coverage":1.0}],"file":"39bb4ab981b6857c8716.js","track":6,"media":"../assets/media/80d9b4c1b89ee6ad51ac282c77f9e64848664e71d7c548b11f20d6449ac63747.mp3"}],"../assets/media/5a6730fc54033085b74dc956eea9784bd93020bd238c8d77f8059970c1fc7460.mp3":[{"id":"B3_U05_T5.6_SHORT_S03_v01","audioId":"B3_U05_T5.6_SHORT_S03_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 8","subtitle":"H1 · 5.6-S03","duration":71.694127,"cues":[{"start":0,"end":6.41,"text":"Presenter 3: Hi, my name’s Angie Stratton and I’m the director of Culture Cycle.","coverage":0.75},{"start":7.81,"end":13.69,"text":"Culture Cycle is a new concept in travel: educational fitness touring!","coverage":1.0},{"start":14.11,"end":20.25,"text":"We offer courses all over the world which combine learning with exercise and travel.","coverage":1.0},{"start":20.53,"end":27.25,"text":"Each course has an educational theme, such as Brazilian cooking or the history of Türkiye.","coverage":0.875},{"start":28.21,"end":39.86,"text":"As a small group, we cycle from place to place, stopping for several days in each location to rest, relax and do some hands-on learning.","coverage":1.0},{"start":40.28,"end":48.41,"text":"Not only does this trip provide terrific exercise and a fascinating cultural experience, it’s the best way to learn.","coverage":1.0},{"start":48.68,"end":61.4,"text":"There’s no question that physical activity improves our memory and thinking skills – so after a few days of cycling, your brain will be ready to learn.","coverage":1.0},{"start":61.82,"end":70.0,"text":"So, be kind to your body and your mind and come with us on an amazing adventure you’ll never forget!","coverage":1.0}],"file":"39bb4ab981b6857c8716.js","track":7,"media":"../assets/media/5a6730fc54033085b74dc956eea9784bd93020bd238c8d77f8059970c1fc7460.mp3"}],"../assets/media/0829a39a6b0f5304a010acc626a52d91362d277a47aac82c268ebdddd386b567.mp3":[{"id":"B3_U05_T5.6_SHORT_S04_v01","audioId":"B3_U05_T5.6_SHORT_S04_v01","title":"Book 3 · Unit 5 · H1 · 听力材料 9","subtitle":"H1 · 5.6-S04","duration":46.669116,"cues":[{"start":0,"end":3.87,"text":"Presenter 4: Are you interested in alternative treatments?","coverage":0.75},{"start":4.78,"end":9.99,"text":"Have you ever wanted to explore the secrets of traditional Chinese medicine?","coverage":1.0},{"start":10.32,"end":21.66,"text":"This spring, join our six-month course in acupuncture – a treatment for pain or illness which involves putting needles under the skin at special points on the body.","coverage":1.0},{"start":21.94,"end":28.61,"text":"The course covers the theory of acupuncture and practical skills in using needles.","coverage":1.0},{"start":29.76,"end":37.54,"text":"Acupuncture is known to reduce pain, but it’s also a great alternative for people who want to lose weight in an easy way.","coverage":0.958},{"start":37.94,"end":44.42,"text":"Learn more about the course and visit us on our open house days on the first Saturday of every month.","coverage":1.0}],"file":"39bb4ab981b6857c8716.js","track":8,"media":"../assets/media/0829a39a6b0f5304a010acc626a52d91362d277a47aac82c268ebdddd386b567.mp3"}],"../assets/media/c99077099c40dd8045b421f0e9010d4743085504f44d971826ea142d66f2488d.mp3":[{"id":"B2_U03_T3.3_SHORT_S01_v01","audioId":"B2_U03_T3.3_SHORT_S01_v01","title":"Book 2 · Unit 3 · 课后听力材料","subtitle":"Homework listening material","duration":61.179841,"cues":[{"start":0.35,"end":9.08,"text":"Host: Welcome to University Podcasts, programmes made by students for students.","coverage":0.727},{"start":9.75,"end":14.3,"text":"I’m Chen Hu [who] and this is Science with a Professor.","coverage":0.917},{"start":14.93,"end":22.75,"text":"Our subject is technology development, and our guest is Professor Joanne Kent, expert in robotics.","coverage":0.933},{"start":23.46,"end":25.37,"text":"Thanks for coming, Professor.","coverage":1.0},{"start":25.95,"end":34.36,"text":"When we think of robots, we generally think of simple robots that clean the floor in our home or build a car in a factory.","coverage":1.0},{"start":34.97,"end":38.85,"text":"But how close are we to having robots that are like people?","coverage":1.0},{"start":39.52,"end":48.12,"text":"Professor: Well, we already have some robots that look like people, and technology is developing more every day.","coverage":0.944},{"start":49.06,"end":54.21,"text":"Robots weren’t used very much in the past, since they were always really expensive.","coverage":1.0},{"start":54.48,"end":60.26,"text":"But because they’re cheaper now, they’re being used in new and interesting ways.","coverage":1.0}],"file":"3a746dd9a3a4a4c9012c.js","track":0,"media":"../assets/media/c99077099c40dd8045b421f0e9010d4743085504f44d971826ea142d66f2488d.mp3"}],"../assets/media/7c41bea54a17a35660542add14b0e52db33404c67a4fe487d9791f58eb46224f.mp3":[{"id":"PPT_7c41bea54a17a356","audioId":"PPT_7c41bea54a17a356","title":"Book 3 · Unit 6 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 184","duration":52.06,"cues":[{"start":0.0,"end":1.5,"text":"six .six","coverage":1.0},{"start":1.5,"end":8.1,"text":"I would like to present an invention which has made the way we organise our work easier.","coverage":1.0},{"start":9.18,"end":12.84,"text":"It's a simple invention and most of you have used it.","coverage":1.0},{"start":13.32,"end":17.94,"text":"It's a small yellow piece of paper which is known all over the world.","coverage":1.0},{"start":18.42,"end":19.88,"text":"It's the Post -It Note.","coverage":1.0},{"start":20.8,"end":25.52,"text":"A Post -It Note is a piece of paper with special glue on the back.","coverage":1.0},{"start":26.16,"end":30.06,"text":"Modern Post -It Notes can be any colour or shape.","coverage":1.0},{"start":31.1,"end":32.98,"text":"Post -It Notes are simple to use.","coverage":1.0},{"start":33.52,"end":37.54,"text":"You can stick them on anything and the note will stay in place.","coverage":1.0},{"start":38.4,"end":41.5,"text":"The notes can be easily removed from any surface.","coverage":1.0},{"start":42.6,"end":46.14,"text":"First I am going to talk about the history of this invention.","coverage":1.0},{"start":46.72,"end":50.18,"text":"Then I will explain how it has made a difference in our lives.","coverage":1.0}],"file":"3aac822b69a905562c18.js","track":0,"media":"../assets/media/7c41bea54a17a35660542add14b0e52db33404c67a4fe487d9791f58eb46224f.mp3"}],"../assets/media/e1fae6e42cbed46169bdb85fa7160ae164fb1f1e0e8fbf0427e7e2958b73041f.mp3":[{"id":"PPT_e1fae6e42cbed461","audioId":"PPT_e1fae6e42cbed461","title":"Book 3 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 60","duration":157.81,"cues":[{"start":0.0,"end":1.84,"text":"three .three","coverage":1.0},{"start":1.84,"end":5.84,"text":"Do you live, study, or work in a large city?","coverage":1.0},{"start":6.44,"end":10.58,"text":"Are the traffic problems so serious they often cause you to be late?","coverage":1.0},{"start":11.1,"end":13.6,"text":"If so, you're not alone.","coverage":1.0},{"start":14.78,"end":20.42,"text":"Over the past century, there's been a huge increase in the traffic that moves through our cities.","coverage":1.0},{"start":20.42,"end":30.02,"text":"And if, as the United Nations predicts, 70 % of the world's population will be living in cities by the year 2050,","coverage":1.0},{"start":30.84,"end":35.42,"text":"what will we do when the amount of traffic increases even more?","coverage":1.0},{"start":36.04,"end":37.14,"text":"How will we cope?","coverage":1.0},{"start":37.72,"end":39.82,"text":"Can we do anything to control it?","coverage":1.0},{"start":40.66,"end":43.68,"text":"With me in today's podcast is Mark Knowling,","coverage":1.0},{"start":44.04,"end":47.14,"text":"an expert in transport and traffic management.","coverage":1.0},{"start":47.14,"end":48.18,"text":"Mark,","coverage":1.0},{"start":48.5,"end":50.38,"text":"what's happening in our cities?","coverage":1.0},{"start":51.24,"end":54.06,"text":"It's a fact that, in a great many cities,","coverage":1.0},{"start":54.4,"end":57.64,"text":"the traffic is more extreme than ever before.","coverage":1.0},{"start":58.52,"end":65.04,"text":"The primary cause is that there are so many private vehicles on the roads carrying only one or two people.","coverage":1.0},{"start":65.84,"end":71.58,"text":"Compare this to buses, which are by far the most efficient option for reducing traffic,","coverage":1.0},{"start":72.0,"end":76.32,"text":"as they can transport huge numbers of passengers at the same time.","coverage":1.0},{"start":76.32,"end":82.62,"text":"But people don't seem to want to leave their expensive cars at home and take the bus instead.","coverage":1.0},{"start":83.68,"end":86.96,"text":"What other factors influence how well traffic flows?","coverage":1.0},{"start":87.82,"end":88.22,"text":"Well,","coverage":1.0},{"start":88.56,"end":94.84,"text":"a crash on a busy city center road can have a huge impact on all the other roads close by.","coverage":1.0},{"start":95.54,"end":101.32,"text":"Or someone parking their vehicle so that it blocks the traffic, even if only for a minute or so.","coverage":1.0},{"start":101.32,"end":103.44,"text":"A delivery driver, for example,","coverage":1.0},{"start":103.88,"end":106.36,"text":"can cause trouble for everyone behind them.","coverage":1.0},{"start":107.42,"end":113.56,"text":"Even something small like that means everyone's journey suddenly becomes more difficult than they expected.","coverage":1.0},{"start":114.2,"end":117.04,"text":"It's the most annoying thing in the world.","coverage":1.0},{"start":117.74,"end":120.2,"text":"Should we blame car drivers for all this,","coverage":1.0},{"start":121.06,"end":122.6,"text":"It's not always their fault.","coverage":1.0},{"start":123.38,"end":128.06,"text":"Traditional traffic signals in so many of our cities are years old now.","coverage":1.0},{"start":128.06,"end":131.96,"text":"They always change color after a certain number of seconds.","coverage":1.0},{"start":132.66,"end":137.74,"text":"That's not a sensible idea when we consider the number of vehicles driving today.","coverage":1.0},{"start":138.32,"end":139.02,"text":"For instance,","coverage":1.0},{"start":139.38,"end":142.06,"text":"a driver might see a green light and continue,","coverage":1.0},{"start":142.46,"end":146.24,"text":"but immediately join a long line of vehicles that isn't moving.","coverage":1.0},{"start":147.06,"end":149.34,"text":"Then, when the lights turn back to red,","coverage":1.0},{"start":149.76,"end":152.08,"text":"they are parked across a busy junction.","coverage":1.0},{"start":152.78,"end":156.0,"text":"That usually leads to all sorts of delays over the day.","coverage":1.0}],"file":"3af3057e400a7001c964.js","track":0,"media":"../assets/media/e1fae6e42cbed46169bdb85fa7160ae164fb1f1e0e8fbf0427e7e2958b73041f.mp3"}],"../assets/media/2bc1571c16175f77c84196fde84016072bd863dc9af91a56594cb5cd5716eb71.mp3":[{"id":"PPT_2bc1571c16175f77","audioId":"PPT_2bc1571c16175f77","title":"Book 3 · Unit 3 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 104","duration":93.15,"cues":[{"start":0.0,"end":1.52,"text":"three .seven","coverage":1.0},{"start":2.1,"end":5.54,"text":"Now I'd like to share some possible solutions.","coverage":1.0},{"start":6.56,"end":8.1,"text":"First, to improve safety,","coverage":1.0},{"start":8.7,"end":15.82,"text":"I'd suggest that police officers give big fines to drivers who break the law by driving in a cycle lane.","coverage":1.0},{"start":16.86,"end":23.54,"text":"Also, I'd like to see wider cycle lanes to allow more bicycles to pass at the same time.","coverage":1.0},{"start":24.4,"end":29.94,"text":"We should also add cycle lanes to busy streets which don't have them yet.","coverage":1.0},{"start":30.8,"end":36.64,"text":"These proposals would prevent cars from hitting cyclists and would save lives.","coverage":1.0},{"start":37.56,"end":39.28,"text":"As for the issue of storage,","coverage":1.0},{"start":39.82,"end":45.46,"text":"I think that city parking garages ought to create special parking sections for bicycles.","coverage":1.0},{"start":46.68,"end":51.1,"text":"This would keep bicycles safe and dry while people are working.","coverage":1.0},{"start":52.38,"end":52.92,"text":"Finally,","coverage":1.0},{"start":53.4,"end":53.98,"text":"convenience.","coverage":1.0},{"start":53.98,"end":55.52,"text":"In my opinion,","coverage":1.0},{"start":55.86,"end":59.64,"text":"we should make it easier to take bicycles on public transport.","coverage":1.0},{"start":60.18,"end":64.2,"text":"For example, we could put cycle racks on the outside of buses.","coverage":1.0},{"start":64.62,"end":68.7,"text":"That way, people wouldn't have to cycle at night or in bad weather.","coverage":1.0},{"start":69.42,"end":76.18,"text":"And people who live far from work could cycle part of the way to work and take public transport the rest of the way.","coverage":1.0},{"start":76.76,"end":77.6,"text":"As a result,","coverage":1.0},{"start":77.92,"end":80.08,"text":"more people could cycle to work.","coverage":1.0},{"start":80.96,"end":81.54,"text":"Well,","coverage":1.0},{"start":81.92,"end":84.16,"text":"thank you again for listening to my ideas.","coverage":1.0},{"start":84.96,"end":91.24,"text":"I hope this is the beginning of a conversation about how we can make this a great city for cyclists.","coverage":1.0}],"file":"3c86541ace40f4e6d1eb.js","track":0,"media":"../assets/media/2bc1571c16175f77c84196fde84016072bd863dc9af91a56594cb5cd5716eb71.mp3"}],"../assets/media/bb41ebac44f4df5e7f357aea7026df07c6f452e048e2ae8b05f56b4d5a564bf2.mp3":[{"id":"PPT_bb41ebac44f4df5e","audioId":"PPT_bb41ebac44f4df5e","title":"Book 3 · Unit 5 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 60","duration":33.07,"cues":[{"start":0.0,"end":2.24,"text":"five .five","coverage":1.0},{"start":2.24,"end":5.7,"text":"one I think it's great news!","coverage":1.0},{"start":8.06,"end":10.4,"text":"two Oh, that's great!","coverage":1.0},{"start":12.4,"end":13.36,"text":"three","coverage":1.0},{"start":13.98,"end":15.88,"text":"What's wrong with being healthy?","coverage":1.0},{"start":17.7,"end":18.66,"text":"four","coverage":1.0},{"start":19.24,"end":24.04,"text":"So now we should all eat fast food and stop exercising?","coverage":1.0},{"start":26.0,"end":26.96,"text":"five","coverage":1.0},{"start":27.92,"end":31.14,"text":"I'd say that it's always better to have a healthy lifestyle","coverage":1.0}],"file":"3cc05f5161d8f7aae668.js","track":0,"media":"../assets/media/bb41ebac44f4df5e7f357aea7026df07c6f452e048e2ae8b05f56b4d5a564bf2.mp3"}],"../assets/media/b1241793fac38474f0202765963e67ff468ac1721d1b5130e1bc282d559f6110.mp3":[{"id":"PPT_b1241793fac38474","audioId":"PPT_b1241793fac38474","title":"Book 3 · Unit 4 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 56","duration":40.7,"cues":[{"start":0.0,"end":2.06,"text":"four .five","coverage":1.0},{"start":2.06,"end":3.24,"text":"one","coverage":1.0},{"start":4.0,"end":9.52,"text":"My book is about the effect of modern technology on traditions around the world.","coverage":1.0},{"start":11.92,"end":18.12,"text":"two People spent a lot of time and effort preparing special meals.","coverage":1.0},{"start":20.74,"end":28.76,"text":"three Growing up in different cultures helps you realise that customs and traditions are often local.","coverage":1.0},{"start":31.3,"end":31.7,"text":"four","coverage":1.0},{"start":32.52,"end":35.92,"text":"We still spend time interacting with other people,","coverage":1.0},{"start":36.44,"end":38.74,"text":"but it's not always face to face.","coverage":1.0}],"file":"3d71480aa3e17dabfe70.js","track":0,"media":"../assets/media/b1241793fac38474f0202765963e67ff468ac1721d1b5130e1bc282d559f6110.mp3"}],"../assets/media/4b39243ffe92aeae63121a8b3dfbdb6b01245620671e2572c8ec43bb30438b79.mp3":[{"id":"PPT_4b39243ffe92aeae","audioId":"PPT_4b39243ffe92aeae","title":"Book 3 · Unit 4 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 239","duration":11.23,"cues":[{"start":0.0,"end":1.58,"text":"four .four","coverage":1.0},{"start":2.28,"end":9.26,"text":"I study different cultures around the world and how social and political changes affect these cultures.","coverage":1.0}],"file":"3dbd007ab5721855e14e.js","track":0,"media":"../assets/media/4b39243ffe92aeae63121a8b3dfbdb6b01245620671e2572c8ec43bb30438b79.mp3"}],"../assets/media/6f42171301964649b084cefeb9126b068fee2cf77917508eac6dfd5affae6d39.mp3":[{"id":"PPT_6f42171301964649","audioId":"PPT_6f42171301964649","title":"Book 2 · Unit 6 · RW · READING 1","subtitle":"READING 1 · source slide 54","duration":225.57,"cues":[{"start":0.0,"end":1.28,"text":"Home.","coverage":1.0},{"start":2.04,"end":3.16,"text":"About us.","coverage":1.0},{"start":4.06,"end":4.56,"text":"News.","coverage":1.0},{"start":5.54,"end":5.94,"text":"Quiz.","coverage":1.0},{"start":7.22,"end":8.32,"text":"Contact us.","coverage":1.0},{"start":9.08,"end":9.52,"text":"More.","coverage":1.0},{"start":10.58,"end":12.72,"text":"Are you ready for the world of work?","coverage":1.0},{"start":13.78,"end":15.68,"text":"Do you know what kind of job you want?","coverage":1.0},{"start":16.82,"end":18.84,"text":"Before you apply for a job,","coverage":1.0},{"start":19.3,"end":22.34,"text":"think about the different types of jobs that people do.","coverage":1.0},{"start":22.98,"end":25.38,"text":"There are four main types of jobs.","coverage":1.0},{"start":26.48,"end":28.22,"text":"One, jobs with people.","coverage":1.0},{"start":28.92,"end":29.56,"text":"Two,","coverage":1.0},{"start":30.04,"end":31.3,"text":"jobs with information.","coverage":1.0},{"start":32.4,"end":32.98,"text":"Three,","coverage":1.0},{"start":33.36,"end":34.44,"text":"jobs with things.","coverage":1.0},{"start":35.48,"end":36.12,"text":"Four,","coverage":1.0},{"start":36.72,"end":37.98,"text":"jobs with ideas.","coverage":1.0},{"start":39.06,"end":41.6,"text":"What kind of work would be best for you?","coverage":1.0},{"start":42.2,"end":46.08,"text":"Take our quiz and find out about the kind of work you would enjoy.","coverage":1.0},{"start":46.94,"end":48.0,"text":"For each question,","coverage":1.0},{"start":48.46,"end":50.48,"text":"choose the best answer for you.","coverage":1.0},{"start":50.74,"end":51.9,"text":"A, B,","coverage":1.0},{"start":52.2,"end":53.58,"text":"C, or D.","coverage":1.0},{"start":53.58,"end":59.36,"text":"Check your results and read the advice to find occupations you would like.","coverage":1.0},{"start":84.3,"end":85.1,"text":"Two,","coverage":1.0},{"start":86.06,"end":89.68,"text":"which sections of a news website do you look at first?","coverage":1.0},{"start":90.66,"end":91.12,"text":"A,","coverage":1.0},{"start":91.7,"end":94.22,"text":"advice page or letters to the editor.","coverage":1.0},{"start":95.14,"end":95.72,"text":"B,","coverage":1.0},{"start":96.2,"end":96.68,"text":"news.","coverage":1.0},{"start":97.2,"end":97.94,"text":"C,","coverage":1.0},{"start":98.38,"end":98.82,"text":"sport.","coverage":1.0},{"start":99.84,"end":100.2,"text":"D,","coverage":1.0},{"start":100.94,"end":101.22,"text":"TV,","coverage":1.0},{"start":101.62,"end":103.56,"text":"music, books, and art.","coverage":1.0},{"start":105.38,"end":106.18,"text":"Three,","coverage":1.0},{"start":107.0,"end":109.4,"text":"what do you like to do at an event?","coverage":1.0},{"start":110.5,"end":111.04,"text":"A,","coverage":1.0},{"start":111.44,"end":112.66,"text":"meet new people.","coverage":1.0},{"start":112.66,"end":113.92,"text":"B,","coverage":1.0},{"start":114.34,"end":116.42,"text":"discuss the latest news.","coverage":1.0},{"start":117.22,"end":117.66,"text":"C,","coverage":1.0},{"start":118.12,"end":120.12,"text":"help with the food and drinks.","coverage":1.0},{"start":120.9,"end":121.26,"text":"D,","coverage":1.0},{"start":121.68,"end":123.94,"text":"sing songs and tell jokes.","coverage":1.0},{"start":126.02,"end":129.5,"text":"Four, what do you prefer to do on a day off?","coverage":1.0},{"start":130.54,"end":131.06,"text":"A,","coverage":1.0},{"start":131.48,"end":133.14,"text":"have coffee with friends.","coverage":1.0},{"start":134.24,"end":134.72,"text":"B,","coverage":1.0},{"start":135.28,"end":137.4,"text":"organize your books and cupboards.","coverage":1.0},{"start":138.18,"end":138.62,"text":"C,","coverage":1.0},{"start":139.12,"end":141.58,"text":"work in the garden or clean the house.","coverage":1.0},{"start":141.58,"end":142.62,"text":"D,","coverage":1.0},{"start":143.14,"end":147.02,"text":"write poetry, make music, or draw pictures.","coverage":1.0},{"start":148.94,"end":150.5,"text":"Mostly A answers.","coverage":1.0},{"start":151.74,"end":152.76,"text":"You are friendly,","coverage":1.0},{"start":153.14,"end":155.22,"text":"kind, and interested in other people.","coverage":1.0},{"start":155.8,"end":158.16,"text":"You would enjoy a job working with children,","coverage":1.0},{"start":158.6,"end":161.84,"text":"with customers in a shop, or on a team with colleagues.","coverage":1.0},{"start":162.6,"end":164.52,"text":"Possible jobs are teacher,","coverage":1.0},{"start":165.1,"end":165.42,"text":"waiter,","coverage":1.0},{"start":165.94,"end":166.92,"text":"police officer.","coverage":1.0},{"start":168.92,"end":170.48,"text":"Mostly B answers.","coverage":1.0},{"start":170.48,"end":176.08,"text":"You are neat, you are good at planning, and you like learning new things.","coverage":1.0},{"start":176.76,"end":179.72,"text":"You would enjoy a job working with information.","coverage":1.0},{"start":180.46,"end":183.3,"text":"Possible jobs are university professor,","coverage":1.0},{"start":183.66,"end":184.68,"text":"computer programmer,","coverage":1.0},{"start":185.3,"end":185.88,"text":"librarian.","coverage":1.0},{"start":188.06,"end":189.88,"text":"Mostly C answers.","coverage":1.0},{"start":190.82,"end":192.04,"text":"You are practical,","coverage":1.0},{"start":192.46,"end":193.76,"text":"you are good at sports,","coverage":1.0},{"start":194.12,"end":196.14,"text":"and you like working with your hands.","coverage":1.0},{"start":196.72,"end":199.42,"text":"You would enjoy a job working with things.","coverage":1.0},{"start":199.42,"end":202.96,"text":"Possible jobs are construction worker,","coverage":1.0},{"start":203.3,"end":203.86,"text":"engineer,","coverage":1.0},{"start":204.48,"end":204.92,"text":"farmer.","coverage":1.0},{"start":207.1,"end":208.62,"text":"Mostly D answers.","coverage":1.0},{"start":209.84,"end":211.04,"text":"You are creative,","coverage":1.0},{"start":211.54,"end":214.68,"text":"you are good at music and art, and you like books.","coverage":1.0},{"start":215.48,"end":218.44,"text":"You would enjoy a job working with ideas.","coverage":1.0},{"start":219.36,"end":221.64,"text":"Possible jobs are artist,","coverage":1.0},{"start":222.22,"end":222.58,"text":"writer,","coverage":1.0},{"start":223.34,"end":223.66,"text":"singer.","coverage":1.0}],"file":"400277081942bfb8419e.js","track":0,"media":"../assets/media/6f42171301964649b084cefeb9126b068fee2cf77917508eac6dfd5affae6d39.mp3"}],"../assets/media/7dcec7a89cc57252cb604ddf36251f44dee4d30c7ed149d62414037e2d905129.mp3":[{"id":"PPT_7dcec7a89cc57252","audioId":"PPT_7dcec7a89cc57252","title":"Book 3 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 61","duration":44.59,"cues":[{"start":0.0,"end":1.56,"text":"six .three","coverage":1.0},{"start":2.9,"end":11.44,"text":"one The Middle Ages were an interesting time and they were full of scientific discoveries","coverage":1.0},{"start":14.64,"end":27.38,"text":"two Inventions and machines designed by medieval scholars made a great contribution to society and many are still in use today and","coverage":1.0},{"start":28.0,"end":31.52,"text":"Some of these inventions are very common","coverage":1.0},{"start":33.58,"end":34.7,"text":"three","coverage":1.0},{"start":35.78,"end":42.7,"text":"Many people think gunpowder is the most important invention in history","coverage":1.0}],"file":"41a9e62f5233ce0c9379.js","track":0,"media":"../assets/media/7dcec7a89cc57252cb604ddf36251f44dee4d30c7ed149d62414037e2d905129.mp3"}],"../assets/media/9f9f680c5151456a23db7de153ad762820ad9b77531669ae961a2d06bd4af076.wav":[{"id":"B2_U07_T7.1_LONG_L01_v01","audioId":"B2_U07_T7.1_LONG_L01_v01","title":"Book 2 · Unit 7 · 课后听力材料","subtitle":"Homework listening material","duration":91.76922902494331,"cues":[{"start":0.23,"end":3.96,"text":"Unit 7, 7.1","coverage":1.0},{"start":5.24,"end":6.43,"text":"Student presenter: Hello, everyone.","coverage":0.5},{"start":7.0,"end":19.0,"text":"So, in this presentation I’d like to discuss the designers of some everyday objects: Arne Jacobsen, Sir James Dyson and Sir Jonathan Ive.","coverage":0.833},{"start":21.48,"end":29.37,"text":"These people designed simple things that have changed our lives and how we do everyday things.","coverage":1.0},{"start":30.36,"end":40.4,"text":"Today we are going to think about these inventors and designers, their achievements and how their inventions and designs have helped us.","coverage":0.955},{"start":40.96,"end":47.45,"text":"I would like to start with Arne Jacobsen, who was born in Denmark in 1902.","coverage":0.867},{"start":48.6,"end":56.49,"text":"When he was a child, he loved to paint, but his father thought being an artist wasn’t a good career.","coverage":1.0},{"start":57.41,"end":64.28,"text":"So, Jacobsen became a designer of many things, including buildings and furniture.","coverage":0.917},{"start":65.0,"end":70.99,"text":"For example, here is a chair he designed in 1958.","coverage":1.0},{"start":71.17,"end":73.38,"text":"It’s called the ‘Egg Chair’.","coverage":1.0},{"start":74.16,"end":76.92,"text":"Have any of you seen this kind of chair before?","coverage":1.0},{"start":77.29,"end":77.58,"text":"Razia: I have.","coverage":0.667},{"start":78.98,"end":81.89,"text":"Did they call it the Egg Chair because of its shape?","coverage":1.0},{"start":82.2,"end":84.4,"text":"It’s an interesting design.","coverage":1.0},{"start":84.95,"end":87.32,"text":"Student presenter: Yes, you have a good point.","coverage":0.75},{"start":87.55,"end":91.08,"text":"I think it was called that because of the egg-like shape.","coverage":1.0}],"file":"420c9efc7bba4bd9cd4d.js","track":0,"media":"../assets/media/9f9f680c5151456a23db7de153ad762820ad9b77531669ae961a2d06bd4af076.wav"}],"../assets/media/7b63f2f18c4d382b5876c35a945f43f924b2dc7a62e4b2ebfd3c0430f536eb27.mp3":[{"id":"PPT_7b63f2f18c4d382b","audioId":"PPT_7b63f2f18c4d382b","title":"Book 3 · Unit 7 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 226","duration":45.95,"cues":[{"start":0.0,"end":1.68,"text":"seven .two","coverage":1.0},{"start":2.26,"end":7.8,"text":"I've seen some examples of artists defending their intellectual property, but not many.","coverage":1.0},{"start":9.08,"end":13.58,"text":"I have seen some examples of artists defending their intellectual property,","coverage":1.0},{"start":14.08,"end":14.92,"text":"but not many.","coverage":1.0},{"start":15.48,"end":19.0,"text":"Can you see the situation changing anytime soon?","coverage":1.0},{"start":19.88,"end":22.46,"text":"No, I don't think it will change.","coverage":1.0},{"start":23.14,"end":23.94,"text":"I agree.","coverage":1.0},{"start":25.02,"end":26.38,"text":"I do agree.","coverage":1.0},{"start":27.12,"end":28.6,"text":"She did something about it.","coverage":1.0},{"start":29.6,"end":32.36,"text":"She did do something about it.","coverage":1.0},{"start":32.88,"end":37.34,"text":"These companies have the ability and the resources to collaborate with artists.","coverage":1.0},{"start":38.52,"end":44.04,"text":"These companies do have the ability and the resources to collaborate with artists.","coverage":1.0}],"file":"441348ba8a413fa349e5.js","track":0,"media":"../assets/media/7b63f2f18c4d382b5876c35a945f43f924b2dc7a62e4b2ebfd3c0430f536eb27.mp3"}],"../assets/media/27725422344c6c5404870729cd3b30698ce40e84570c35d5548c33791e06c769.wav":[{"id":"B2_U02_T2.1_LONG_L01_v01","audioId":"B2_U02_T2.1_LONG_L01_v01","title":"Book 2 · Unit 2 · 课后听力材料","subtitle":"Homework listening material","duration":135.49820861678003,"cues":[{"start":0.22,"end":4.0,"text":"Unit 2, 2.1","coverage":1.0},{"start":5.22,"end":13.09,"text":"Reporter 1: Today I’m at the Vivid Sydney festival, which has been held in Australia every year since 2009.","coverage":0.85},{"start":14.24,"end":17.71,"text":"It’s held for three weeks during May and June.","coverage":1.0},{"start":18.0,"end":23.6,"text":"It has loads of activities with music, food, art and learning.","coverage":1.0},{"start":24.51,"end":29.57,"text":"Anybody can go to the lectures, see the lights and eat interesting food.","coverage":0.923},{"start":30.0,"end":31.59,"text":"Many activities are free.","coverage":1.0},{"start":31.99,"end":38.69,"text":"The festival gets bigger every year; sometimes over two million people come.","coverage":1.0},{"start":39.11,"end":42.68,"text":"We asked one of the visitors about the festival.","coverage":0.889},{"start":43.0,"end":44.52,"text":"Hello, there.","coverage":1.0},{"start":45.0,"end":51.57,"text":"Can you introduce yourself and tell me, is this your first time at the festival here in Sydney?","coverage":1.0},{"start":52.22,"end":57.53,"text":"Olivia: My name is Olivia, and no, I come here every year!","coverage":0.917},{"start":58.0,"end":59.7,"text":"Reporter 1: Why do you like coming to the festival?","coverage":0.8},{"start":60.22,"end":62.96,"text":"Olivia: Well, it’s an interesting event to come to.","coverage":0.9},{"start":63.21,"end":65.62,"text":"It’s great for children and adults.","coverage":1.0},{"start":66.0,"end":71.68,"text":"I enjoy learning about all the new ideas people have on important topics.","coverage":1.0},{"start":72.14,"end":81.09,"text":"We don’t get much time to really think or learn about new things in everyday life, but you can do exactly that at this festival.","coverage":1.0},{"start":82.11,"end":85.71,"text":"Reporter 1: So, what kinds of things do people learn and do here?","coverage":0.846},{"start":85.98,"end":88.72,"text":"Do people try mainly one type of thing?","coverage":1.0},{"start":89.11,"end":93.31,"text":"Olivia: No, most people plan on going to several events.","coverage":0.9},{"start":93.48,"end":97.02,"text":"For example, today I learned about nature.","coverage":1.0},{"start":97.27,"end":101.13,"text":"I went to a lecture about the sea and new ways to clean it.","coverage":1.0},{"start":101.33,"end":102.1,"text":"It was quite interesting!","coverage":1.0},{"start":103.11,"end":105.92,"text":"Yesterday, I walked around a 3D art show.","coverage":1.0},{"start":106.28,"end":109.09,"text":"The entire room was covered in pictures.","coverage":1.0},{"start":109.6,"end":111.02,"text":"It was an exciting activity.","coverage":1.0},{"start":111.68,"end":115.0,"text":"It felt like flying over the trees and mountains.","coverage":1.0},{"start":115.22,"end":124.59,"text":"And tomorrow, I’m going to a talk on how food can help people live better lives, which I’m sure will really make me think!","coverage":1.0},{"start":124.99,"end":128.18,"text":"Reporter 1: Are there any things you don’t like about it?","coverage":0.833},{"start":128.49,"end":129.93,"text":"Are you ever bored?","coverage":1.0},{"start":130.55,"end":131.17,"text":"Olivia: Not really.","coverage":0.667},{"start":131.48,"end":134.73,"text":"The only problem is that it’s really crowded.","coverage":1.0}],"file":"4435297f4a6e42165400.js","track":0,"media":"../assets/media/27725422344c6c5404870729cd3b30698ce40e84570c35d5548c33791e06c769.wav"}],"../assets/media/8cec9fab36e9003b6cea8dc8fe91adcd0f3d6b738ad7fd65729828aa26ee5edb.mp3":[{"id":"PPT_8cec9fab36e9003b","audioId":"PPT_8cec9fab36e9003b","title":"Book 3 · Unit 4 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 281","duration":20.92,"cues":[{"start":0.0,"end":1.52,"text":"four .ten","coverage":1.0},{"start":1.52,"end":6.46,"text":"I completely agree that holidays have become too commercial.","coverage":1.0},{"start":9.26,"end":13.86,"text":"I absolutely disagree that we should stop giving gifts on Mother's Day.","coverage":1.0},{"start":15.88,"end":18.98,"text":"I really think that we should give fewer gifts.","coverage":1.0}],"file":"470b0dc7e6e05e98d6f3.js","track":0,"media":"../assets/media/8cec9fab36e9003b6cea8dc8fe91adcd0f3d6b738ad7fd65729828aa26ee5edb.mp3"}],"../assets/media/ec22923bcd1d5dbaa38ff63e68d7cd88f6fb2045a010b9700b895353506b8fe8.mp3":[{"id":"PPT_ec22923bcd1d5dba","audioId":"PPT_ec22923bcd1d5dba","title":"Book 2 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 54","duration":7.5,"cues":[{"start":0.0,"end":1.74,"text":"two .two","coverage":1.0},{"start":2.68,"end":5.64,"text":"I went to a lecture about the sea.","coverage":1.0}],"file":"48d4524ee486e54cf53c.js","track":0,"media":"../assets/media/ec22923bcd1d5dbaa38ff63e68d7cd88f6fb2045a010b9700b895353506b8fe8.mp3"}],"../assets/media/7bacfa6e1cb4e12b3072f19f201a8d867112b09676211fd78f5a5f550b62ed68.mp3":[{"id":"PPT_7bacfa6e1cb4e12b","audioId":"PPT_7bacfa6e1cb4e12b","title":"Book 3 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 48","duration":40.36,"cues":[{"start":0.0,"end":3.0,"text":"Unit eight, eight .one","coverage":1.0},{"start":3.6,"end":4.6,"text":"Part one","coverage":1.0},{"start":5.72,"end":7.34,"text":"In this week's programme,","coverage":1.0},{"start":7.76,"end":12.34,"text":"I'd like to talk about a book that has changed the way I think about money.","coverage":1.0},{"start":12.94,"end":16.48,"text":"It's called The Secret of Being Wealthy.","coverage":1.0},{"start":16.7,"end":21.08,"text":"It was written by a business school graduate named John Home,","coverage":1.0},{"start":21.72,"end":25.34,"text":"who decided to study the behaviour of wealthy people.","coverage":1.0},{"start":25.34,"end":29.58,"text":"He paid close attention to what rich people do,","coverage":1.0},{"start":30.14,"end":31.38,"text":"checking where they eat,","coverage":1.0},{"start":31.74,"end":32.66,"text":"what they buy,","coverage":1.0},{"start":33.08,"end":35.04,"text":"how they live and so on.","coverage":1.0},{"start":35.78,"end":38.42,"text":"The results of his study were pretty surprising.","coverage":1.0}],"file":"49c4f6d18134b6677a9c.js","track":0,"media":"../assets/media/7bacfa6e1cb4e12b3072f19f201a8d867112b09676211fd78f5a5f550b62ed68.mp3"}],"../assets/media/d7d40bf5985e4eed388a86371a8d70b5bf9eda02a5eede4c64cc9d718f4f85b7.mp3":[{"id":"PPT_d7d40bf5985e4eed","audioId":"PPT_d7d40bf5985e4eed","title":"Book 2 · Unit 5 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 54","duration":244.92,"cues":[{"start":0.0,"end":1.7,"text":"five .two","coverage":1.0},{"start":2.74,"end":4.56,"text":"For my project,","coverage":1.0},{"start":4.96,"end":9.8,"text":"I looked at some unusual sports that people play around the world.","coverage":1.0},{"start":10.42,"end":14.48,"text":"I'd like to start by talking about chess boxing.","coverage":1.0},{"start":15.42,"end":18.02,"text":"You may already know about the two sports.","coverage":1.0},{"start":18.7,"end":23.18,"text":"Chess is a game played with a board and different chess pieces.","coverage":1.0},{"start":23.18,"end":31.57,"text":"Very intelligent people often play this game because players need to think very carefully.","coverage":1.0},{"start":32.92,"end":36.8,"text":"Boxing is a totally different kind of sport though.","coverage":1.0},{"start":37.76,"end":43.16,"text":"Being strong is more important because boxers have to hit each other.","coverage":1.0},{"start":43.94,"end":49.28,"text":"They wear gloves and helmets in the ring, but it's still difficult.","coverage":1.0},{"start":50.24,"end":51.16,"text":"Now,","coverage":1.0},{"start":51.6,"end":58.1,"text":"chess boxing is a new type of sport where the players do both activities.","coverage":1.0},{"start":59.08,"end":60.54,"text":"They start with boxing,","coverage":1.0},{"start":60.9,"end":61.32,"text":"sorry,","coverage":1.0},{"start":61.8,"end":63.24,"text":"I mean chess,","coverage":1.0},{"start":63.98,"end":65.6,"text":"and then do some boxing,","coverage":1.0},{"start":66.12,"end":71.32,"text":"and they continue doing each activity back and forth, alternating.","coverage":1.0},{"start":72.54,"end":78.74,"text":"The person who wins the boxing match or the chess game first is the champion.","coverage":1.0},{"start":79.28,"end":87.72,"text":"One benefit of this sport is that it gives people a chance to compete physically and mentally.","coverage":1.0},{"start":88.76,"end":91.68,"text":"It isn't just thinking or physical activity.","coverage":1.0},{"start":92.4,"end":93.32,"text":"It's both.","coverage":1.0},{"start":95.46,"end":99.44,"text":"Another sport that challenges people is urban golf.","coverage":1.0},{"start":100.12,"end":103.44,"text":"Urban golf is similar to normal golf,","coverage":1.0},{"start":103.78,"end":107.02,"text":"but you don't need to go to a golf course.","coverage":1.0},{"start":107.02,"end":110.92,"text":"You get clubs and a golf ball.","coverage":1.0},{"start":111.4,"end":111.92,"text":"Well,","coverage":1.0},{"start":112.24,"end":112.86,"text":"actually,","coverage":1.0},{"start":113.44,"end":117.46,"text":"it's a soft tennis ball instead of a hard golf ball.","coverage":1.0},{"start":118.0,"end":120.86,"text":"Then you can play in the street,","coverage":1.0},{"start":121.26,"end":123.29,"text":"which is why it's called urban.","coverage":1.0},{"start":124.64,"end":126.44,"text":"If you play urban golf,","coverage":1.0},{"start":126.92,"end":131.18,"text":"you don't need to go anywhere special or need much money to play.","coverage":1.0},{"start":131.76,"end":134.82,"text":"You just agree where you want to hit the ball.","coverage":1.0},{"start":134.82,"end":136.16,"text":"For example,","coverage":1.0},{"start":136.54,"end":139.32,"text":"at a sign in the street or a rubbish bin.","coverage":1.0},{"start":140.24,"end":141.46,"text":"On the other hand,","coverage":1.0},{"start":142.16,"end":147.84,"text":"intelligent players know that you may break something if you hit the ball too hard,","coverage":1.0},{"start":148.16,"end":150.94,"text":"so they try to play fairly carefully.","coverage":1.0},{"start":153.06,"end":153.74,"text":"Next,","coverage":1.0},{"start":154.16,"end":165.0,"text":"I'd like to talk about the Moroccan desert footrace, which is also called the Marathon des Sables or the Tahara Marathon.","coverage":1.0},{"start":166.32,"end":173.12,"text":"This race is held every year over a week or rather over six days.","coverage":1.0},{"start":174.26,"end":177.1,"text":"The runners have to be really strong.","coverage":1.0},{"start":177.86,"end":179.42,"text":"On the longest day,","coverage":1.0},{"start":179.72,"end":182.74,"text":"the runners have to run 92 kilometers.","coverage":1.0},{"start":183.76,"end":192.98,"text":"The best thing about it is that the champion can say he or she has won the hardest marathon in the world.","coverage":1.0},{"start":194.12,"end":194.44,"text":"Finally,","coverage":1.0},{"start":195.12,"end":198.38,"text":"I'd like to look at Sepak Takraw.","coverage":1.0},{"start":199.3,"end":204.83,"text":"This is a type of volleyball and is very popular in Southeast Asia.","coverage":1.0},{"start":206.28,"end":216.06,"text":"The players use a different kind of ball, and they can use their feet to kick the ball or hit it with their knees, chest or head.","coverage":1.0},{"start":217.22,"end":221.7,"text":"The sport began in Indonesia and it, no,","coverage":1.0},{"start":222.06,"end":222.94,"text":"not Indonesia,","coverage":1.0},{"start":223.58,"end":225.78,"text":"it began in Malaysia,","coverage":1.0},{"start":226.78,"end":231.26,"text":"although it is also very popular in Thailand and Indonesia.","coverage":1.0},{"start":232.18,"end":240.5,"text":"One good thing about Sepak Takraw is that it is now played in schools in many countries, including Japan,","coverage":1.0},{"start":240.9,"end":242.98,"text":"and gets children to play sport.","coverage":1.0}],"file":"4ab2ba09157118519ff9.js","track":0,"media":"../assets/media/d7d40bf5985e4eed388a86371a8d70b5bf9eda02a5eede4c64cc9d718f4f85b7.mp3"}],"../assets/media/bc369bf37a7add85b81696d5ab7fb8a1ebdb79a87ef62aa46255f220d9e154c4.mp3":[{"id":"PPT_bc369bf37a7add85","audioId":"PPT_bc369bf37a7add85","title":"Book 3 · Unit 4 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 83","duration":196.34,"cues":[{"start":0.0,"end":1.44,"text":"four .eight","coverage":1.0},{"start":2.0,"end":8.04,"text":"So our assignment is to discuss customs which have been changing recently.","coverage":1.0},{"start":8.54,"end":12.6,"text":"You know, how modern lifestyles have changed people's behaviour.","coverage":1.0},{"start":13.42,"end":14.3,"text":"Any ideas?","coverage":1.0},{"start":15.06,"end":15.54,"text":"Hmm,","coverage":1.0},{"start":15.9,"end":16.9,"text":"let me think.","coverage":1.0},{"start":18.52,"end":20.44,"text":"holidays are one kind of custom.","coverage":1.0},{"start":21.18,"end":23.98,"text":"Can you think of any holidays which have changed?","coverage":1.0},{"start":24.18,"end":26.04,"text":"Oh, don't talk about holidays.","coverage":1.0},{"start":26.04,"end":31.66,"text":"It reminds me that Mother's Day is in two days and I haven't bought a gift for my mum yet.","coverage":1.0},{"start":31.98,"end":32.44,"text":"Yeah,","coverage":1.0},{"start":32.8,"end":34.12,"text":"I haven't either.","coverage":1.0},{"start":34.82,"end":38.34,"text":"Who has time for shopping when we have so much work to do?","coverage":1.0},{"start":38.56,"end":39.26,"text":"I agree.","coverage":1.0},{"start":39.78,"end":42.0,"text":"I get tired of shopping for gifts.","coverage":1.0},{"start":42.24,"end":47.04,"text":"I actually don't know why we have to get gifts for every little holiday.","coverage":1.0},{"start":47.78,"end":51.82,"text":"Wouldn't our mothers be just as happy if we just spent time with them?","coverage":1.0},{"start":51.82,"end":57.7,"text":"You know, made it a special event, like taking them out to lunch at a nice restaurant.","coverage":1.0},{"start":58.4,"end":63.58,"text":"How did this whole gift -giving for every holiday tradition get started anyway?","coverage":1.0},{"start":64.14,"end":65.72,"text":"It seems silly to me.","coverage":1.0},{"start":66.12,"end":67.02,"text":"That's it!","coverage":1.0},{"start":67.34,"end":68.68,"text":"There's our topic.","coverage":1.0},{"start":69.24,"end":71.9,"text":"How holidays have become too commercial.","coverage":1.0},{"start":72.26,"end":72.84,"text":"Hold on.","coverage":1.0},{"start":73.36,"end":74.32,"text":"Too commercial?","coverage":1.0},{"start":74.88,"end":75.66,"text":"I disagree.","coverage":1.0},{"start":76.46,"end":77.7,"text":"I like giving gifts.","coverage":1.0},{"start":77.7,"end":81.86,"text":"I think that it shows that you were thinking of someone.","coverage":1.0},{"start":82.56,"end":89.48,"text":"Because you went out and got someone some chocolate or jewellery or a scarf or something at the last minute.","coverage":1.0},{"start":90.4,"end":94.16,"text":"Everyone knows that people usually buy gifts because it's an obligation,","coverage":1.0},{"start":94.58,"end":96.38,"text":"not because they really want to.","coverage":1.0},{"start":96.64,"end":103.18,"text":"Well, you have to spend time thinking about the gift and get something thoughtful, you know,","coverage":1.0},{"start":103.56,"end":104.1,"text":"personal.","coverage":1.0},{"start":104.1,"end":108.54,"text":"Like maybe the new book by their favourite author.","coverage":1.0},{"start":109.02,"end":110.08,"text":"I see your point.","coverage":1.0},{"start":110.62,"end":114.84,"text":"But I'm not convinced because then you have to spend money.","coverage":1.0},{"start":115.36,"end":119.0,"text":"Money which could be spent on more important things.","coverage":1.0},{"start":119.74,"end":120.22,"text":"Also,","coverage":1.0},{"start":120.76,"end":126.56,"text":"all that time you spent shopping you could have instead spent with the person you're shopping for.","coverage":1.0},{"start":126.82,"end":128.44,"text":"I couldn't agree more.","coverage":1.0},{"start":128.72,"end":131.42,"text":"And it's not just holidays which are a problem.","coverage":1.0},{"start":131.42,"end":136.7,"text":"Personally, I think we give too many gifts for other special occasions too.","coverage":1.0},{"start":137.28,"end":141.4,"text":"Like when my sister graduated from university last year,","coverage":1.0},{"start":141.78,"end":145.24,"text":"she got lots of gifts and money too.","coverage":1.0},{"start":145.88,"end":148.54,"text":"The focus was all on opening gifts.","coverage":1.0},{"start":149.28,"end":152.64,"text":"I've heard that when people receive more than a few gifts,","coverage":1.0},{"start":153.02,"end":156.96,"text":"they usually can't even remember who gave them which gift.","coverage":1.0},{"start":156.96,"end":158.32,"text":"Instead,","coverage":1.0},{"start":158.92,"end":161.66,"text":"why not write letters of advice for the future?","coverage":1.0},{"start":162.02,"end":163.28,"text":"That would be more special.","coverage":1.0},{"start":163.96,"end":165.44,"text":"That's a great idea!","coverage":1.0},{"start":166.06,"end":166.44,"text":"Sorry,","coverage":1.0},{"start":166.9,"end":167.88,"text":"I don't agree.","coverage":1.0},{"start":168.32,"end":171.7,"text":"I doubt that graduates will be happy if we change that custom.","coverage":1.0},{"start":172.38,"end":174.74,"text":"I think that graduation gifts are practical.","coverage":1.0},{"start":175.5,"end":180.7,"text":"Don't young people need some gifts and money for starting their new life?","coverage":1.0},{"start":180.7,"end":187.26,"text":"And they can always look at the gift and think of the person who gave it to them.","coverage":1.0},{"start":187.88,"end":189.9,"text":"I think it's a nice custom.","coverage":1.0},{"start":190.86,"end":193.3,"text":"I'm still really not convinced.","coverage":1.0},{"start":193.54,"end":195.22,"text":"I mean...","coverage":1.0}],"file":"4b100c6af5b261f638d6.js","track":0,"media":"../assets/media/bc369bf37a7add85b81696d5ab7fb8a1ebdb79a87ef62aa46255f220d9e154c4.mp3"}],"../assets/media/9c8ed2a7aabb1e95959da70d9c57c47b42faeadab88fa6dd25e0429f6b6970a3.mp3":[{"id":"B2_U05_T5.2_SHORT_S01_v01","audioId":"B2_U05_T5.2_SHORT_S01_v01","title":"Book 2 · Unit 5 · H1 · 听力材料 1","subtitle":"H1 · S01","duration":94.355351,"cues":[{"start":0.22,"end":9.66,"text":"Amina: For my project I looked at some unusual sports that people play around the world.","coverage":0.938},{"start":10.12,"end":15.0,"text":"I’d like to start by talking about ‘chess boxing’.","coverage":1.0},{"start":15.26,"end":18.0,"text":"You may already know about the two sports.","coverage":1.0},{"start":18.28,"end":23.0,"text":"Chess is a game played with a board and different chess pieces.","coverage":1.0},{"start":23.28,"end":31.47,"text":"Very intelligent people often play this game because players need to think very carefully.","coverage":1.0},{"start":32.28,"end":36.4,"text":"Boxing is a totally different kind of sport, though.","coverage":1.0},{"start":37.28,"end":42.6,"text":"Being strong is more important because boxers have to hit each other.","coverage":0.917},{"start":43.28,"end":48.6,"text":"They wear gloves and helmets in the ring, but it’s still difficult.","coverage":1.0},{"start":49.28,"end":57.71,"text":"Now, chess boxing is a new type of sport, where the players do both activities.","coverage":1.0},{"start":58.28,"end":71.61,"text":"They start with boxing, sorry, I mean chess, and then do some boxing, and they continue doing each activity back and forth - alternating.","coverage":1.0},{"start":72.28,"end":79.53,"text":"The person who wins the boxing match or the chess game first is the champion.","coverage":1.0},{"start":80.28,"end":87.54,"text":"One benefit of this sport is that it gives people a chance to compete physically and mentally.","coverage":0.941},{"start":88.28,"end":94.355,"text":"It isn’t just thinking or physical activity; it’s both.","coverage":1.0}],"file":"4b70972119aed0323922.js","track":0,"media":"../assets/media/9c8ed2a7aabb1e95959da70d9c57c47b42faeadab88fa6dd25e0429f6b6970a3.mp3"}],"../assets/media/70896af56840f1d2e2ca657dbfb955e27fc91479c85bdd72ba512dd67fa9c8fc.mp3":[{"id":"B2_U05_T5.2_SHORT_S02_v01","audioId":"B2_U05_T5.2_SHORT_S02_v01","title":"Book 2 · Unit 5 · H1 · 听力材料 2","subtitle":"H1 · S02","duration":57.823107,"cues":[{"start":0,"end":4.78,"text":"Amina: Another sport that challenges people is urban golf.","coverage":0.889},{"start":5.83,"end":13.52,"text":"Urban golf is similar to normal golf, but you don’t need to go to a golf course.","coverage":1.0},{"start":13.98,"end":23.29,"text":"You get clubs and a golf ball - well, actually, it’s a soft tennis ball instead of a hard golf ball.","coverage":1.0},{"start":23.68,"end":30.03,"text":"Then you can play in the street, which is why it’s called ‘urban’.","coverage":1.0},{"start":30.56,"end":36.9,"text":"If you play urban golf, you don’t need to go anywhere special or need much money to play.","coverage":1.0},{"start":37.21,"end":45.56,"text":"You just agree where you want to hit the ball, for example, at a sign in the street or a rubbish bin.","coverage":1.0},{"start":46.11,"end":56.68,"text":"On the other hand, intelligent players know that you may break something if you hit the ball too hard, so they try to play fairly carefully.","coverage":1.0}],"file":"4b70972119aed0323922.js","track":1,"media":"../assets/media/70896af56840f1d2e2ca657dbfb955e27fc91479c85bdd72ba512dd67fa9c8fc.mp3"}],"../assets/media/b2c8c871a80f34b0541f12de765685be0fcc3bd09aaeaca6b3b3f6736d191196.mp3":[{"id":"B2_U05_T5.2_SHORT_S03_v01","audioId":"B2_U05_T5.2_SHORT_S03_v01","title":"Book 2 · Unit 5 · H1 · 听力材料 3","subtitle":"H1 · S03","duration":41.444331,"cues":[{"start":0,"end":13.33,"text":"Amina: Next, I’d like to talk about the Moroccan desert footrace, which is also called the Marathon des Sables or the Sahara Marathon.","coverage":0.792},{"start":14.46,"end":21.89,"text":"This race is held every year over a week or rather over six days.","coverage":1.0},{"start":22.38,"end":25.71,"text":"The runners have to be really strong.","coverage":1.0},{"start":26.08,"end":30.96,"text":"On the longest day, the runners have to run 92 kilometres.","coverage":0.909},{"start":32.64,"end":40.63,"text":"The best thing about it is that the champion can say he, or she, has won the hardest marathon in the world.","coverage":1.0}],"file":"4b70972119aed0323922.js","track":2,"media":"../assets/media/b2c8c871a80f34b0541f12de765685be0fcc3bd09aaeaca6b3b3f6736d191196.mp3"}],"../assets/media/27f0df868c1819ff64a0a4ab03411198aa491d440e5af0f1c19aaf0f42c182ab.mp3":[{"id":"B2_U05_T5.2_SHORT_S04_v01","audioId":"B2_U05_T5.2_SHORT_S04_v01","title":"Book 2 · Unit 5 · H1 · 听力材料 4","subtitle":"H1 · S04","duration":51.562562,"cues":[{"start":0.57,"end":2.82,"text":"Amina: Finally, I’d like to look at sepak takraw.","coverage":0.7},{"start":6.63,"end":12.51,"text":"This is a type of volleyball and is very popular in Southeast Asia.","coverage":1.0},{"start":12.96,"end":23.17,"text":"The players use a different kind of ball and they can use their feet to kick the ball or hit it with their knees, chest or head.","coverage":1.0},{"start":23.88,"end":38.8,"text":"The sport began in Indonesia and it - no, not Indonesia - it began in Malaysia, although it is also very popular in Thailand and Indonesia.","coverage":1.0},{"start":39.22,"end":49.05,"text":"One good thing about sepak takraw is that it is now played in schools in many countries, including Japan and gets children to play sport.","coverage":0.92}],"file":"4b70972119aed0323922.js","track":3,"media":"../assets/media/27f0df868c1819ff64a0a4ab03411198aa491d440e5af0f1c19aaf0f42c182ab.mp3"}],"../assets/media/7079f09bb5acbf9614d0cde3df288abc84dc96c1999bbb65d860f9fe9b211fa6.mp3":[{"id":"PPT_7079f09bb5acbf96","audioId":"PPT_7079f09bb5acbf96","title":"Book 3 · Unit 2 · RW · READING 1","subtitle":"READING 1 · source slide 41","duration":277.6,"cues":[{"start":0.0,"end":1.82,"text":"Our changing planet.","coverage":1.0},{"start":3.16,"end":9.88,"text":"The Uppsala Glacier in Argentina used to be one of the biggest glaciers in South America.","coverage":1.0},{"start":10.64,"end":14.58,"text":"In 1928, it was covered in ice and snow.","coverage":1.0},{"start":15.08,"end":21.14,"text":"But now, the glacier is melting at an annual rate of about 200 meters,","coverage":1.0},{"start":21.78,"end":24.18,"text":"so the area is covered in water.","coverage":1.0},{"start":24.94,"end":27.78,"text":"This is evidence of global warming.","coverage":1.0},{"start":28.74,"end":30.34,"text":"Since 1900,","coverage":1.0},{"start":30.82,"end":35.4,"text":"the global temperature has gone up by around one degree centigrade.","coverage":1.0},{"start":36.38,"end":38.24,"text":"This may not sound like much,","coverage":1.0},{"start":38.72,"end":48.02,"text":"but such a small increase is causing sea levels to rise and threatening the habitat of many species of plants and animals.","coverage":1.0},{"start":49.14,"end":59.04,"text":"An increase of two degrees centigrade in global temperatures could result in extinction for 30 % of the world's land species.","coverage":1.0},{"start":60.5,"end":66.16,"text":"The Northwest Passage is a sea route which runs along the northern coast of Canada,","coverage":1.0},{"start":66.7,"end":69.38,"text":"between the Atlantic and Pacific Oceans.","coverage":1.0},{"start":70.38,"end":75.68,"text":"In the past, it was often difficult to use because the water was frozen.","coverage":1.0},{"start":76.58,"end":77.06,"text":"However,","coverage":1.0},{"start":77.64,"end":85.4,"text":"increasing temperatures and the subsequent deglaciation have made it easier for ships to travel through this route.","coverage":1.0},{"start":86.42,"end":95.88,"text":"The trouble is that the melting of the ice is leading to loss of habitat for the polar bears and other species which live in this area.","coverage":1.0},{"start":97.22,"end":102.38,"text":"Experts predict that global sea levels could rise by 30 .five","coverage":1.0},{"start":102.38,"end":107.06,"text":"to 122 centimeters by the end of the century.","coverage":1.0},{"start":108.18,"end":109.06,"text":"Consequently,","coverage":1.0},{"start":109.64,"end":114.88,"text":"some areas that were land a few hundred years ago are now underwater,","coverage":1.0},{"start":115.66,"end":120.08,"text":"and many low -lying islands may be underwater in the future.","coverage":1.0},{"start":121.14,"end":123.78,"text":"As a result of the changing climate,","coverage":1.0},{"start":124.34,"end":129.38,"text":"the world's ecosystems are also changing faster than ever before.","coverage":1.0},{"start":130.32,"end":141.14,"text":"More than one -third of the world's mangrove forests and around 50 % of the world's reefs have been destroyed in the last few decades.","coverage":1.0},{"start":142.08,"end":150.68,"text":"Forests are being cut down to provide land for food because human population is growing at such a rapid rate.","coverage":1.0},{"start":151.88,"end":156.84,"text":"38 % of the land on Earth is now used for growing food.","coverage":1.0},{"start":157.82,"end":167.0,"text":"As a result of the higher temperatures and higher levels of carbon dioxide in the atmosphere, plants are producing more pollen,","coverage":1.0},{"start":167.6,"end":170.32,"text":"which could lead to more cases of asthma,","coverage":1.0},{"start":170.82,"end":173.98,"text":"a medical condition which makes it hard to breathe.","coverage":1.0},{"start":175.3,"end":177.72,"text":"What is causing climate change?","coverage":1.0},{"start":178.58,"end":182.34,"text":"The main cause is the huge amount of greenhouse gases,","coverage":1.0},{"start":182.76,"end":185.46,"text":"such as methane and carbon dioxide,","coverage":1.0},{"start":185.94,"end":187.8,"text":"CO2, in the atmosphere.","coverage":1.0},{"start":188.5,"end":192.0,"text":"But the reason for this is the world's population,","coverage":1.0},{"start":192.56,"end":193.68,"text":"you and me.","coverage":1.0},{"start":194.08,"end":196.5,"text":"As the population increases,","coverage":1.0},{"start":196.82,"end":200.6,"text":"more land is needed to provide food and energy.","coverage":1.0},{"start":201.34,"end":203.68,"text":"Burning fossil fuels for heating,","coverage":1.0},{"start":204.12,"end":204.38,"text":"lighting,","coverage":1.0},{"start":205.18,"end":205.52,"text":"transport,","coverage":1.0},{"start":206.26,"end":206.7,"text":"electricity,","coverage":1.0},{"start":207.16,"end":210.66,"text":"or manufacturing produces carbon dioxide.","coverage":1.0},{"start":211.7,"end":212.26,"text":"Furthermore,","coverage":1.0},{"start":212.98,"end":215.42,"text":"humans breathe out carbon dioxide,","coverage":1.0},{"start":215.88,"end":220.7,"text":"while trees breathe in carbon dioxide and produce oxygen.","coverage":1.0},{"start":221.46,"end":223.12,"text":"So by cutting down trees,","coverage":1.0},{"start":223.52,"end":230.48,"text":"we are increasing the amount of carbon dioxide in the atmosphere and reducing the amount of oxygen.","coverage":1.0},{"start":231.58,"end":233.68,"text":"As a result of human activities,","coverage":1.0},{"start":234.36,"end":240.56,"text":"carbon dioxide levels are now at their highest in 800 ,000 years.","coverage":1.0},{"start":241.62,"end":247.18,"text":"The biggest challenge we all face is to prevent further environmental disasters.","coverage":1.0},{"start":247.7,"end":251.38,"text":"We must do something before it is too late.","coverage":1.0},{"start":252.2,"end":256.46,"text":"We need to reduce the amount of carbon dioxide in the atmosphere.","coverage":1.0},{"start":257.46,"end":262.52,"text":"We need to stop burning fossil fuels and start using renewable energy.","coverage":1.0},{"start":262.86,"end":266.54,"text":"We can get enough energy from renewable fuels,","coverage":1.0},{"start":266.94,"end":268.38,"text":"such as solar energy,","coverage":1.0},{"start":268.88,"end":270.2,"text":"hydroelectric energy,","coverage":1.0},{"start":270.5,"end":271.6,"text":"or wind power,","coverage":1.0},{"start":272.14,"end":275.72,"text":"to be able to stop using fossil fuels completely.","coverage":1.0}],"file":"4c559e8c4011b7f6055d.js","track":0,"media":"../assets/media/7079f09bb5acbf9614d0cde3df288abc84dc96c1999bbb65d860f9fe9b211fa6.mp3"}],"../assets/media/07e102b66f8fdc1715a6cd4e27bd90dd7dbdc17df489cdd721cd48fc2b5e28ec.mp3":[{"id":"PPT_07e102b66f8fdc17","audioId":"PPT_07e102b66f8fdc17","title":"Book 2 · Unit 7 · RW · READING 2","subtitle":"READING 2 · source slide 126","duration":198.5,"cues":[{"start":5.0,"end":10.64,"text":"I really admire Jack Dorsey, the former CEO of Twitter, now X.","coverage":0.833},{"start":11.44,"end":14.9,"text":"He invented a new kind of social networking site.","coverage":1.0},{"start":15.56,"end":20.26,"text":"Twitter was an intelligent way to communicate but it was also easy to use.","coverage":1.0},{"start":20.8,"end":27.51,"text":"Twitter became very popular with everyone including students, politicians, and teachers.","coverage":1.0},{"start":27.84,"end":32.42,"text":"Jack Dorsey is a good role model because he is an excellent businessman.","coverage":0.923},{"start":32.66,"end":34.58,"text":"He works hard and is very kind.","coverage":1.0},{"start":35.13,"end":40.08,"text":"In 2016 he gave almost one third of his shares in Twitter to his employees.","coverage":1.0},{"start":40.45,"end":46.29,"text":"I respect him because he changed the way people use social media all over the world.","coverage":1.0},{"start":52.32,"end":56.1,"text":"My mum, Mary Evans, is my role model.","coverage":0.875},{"start":56.96,"end":60.23,"text":"I have a very big family, with two brothers and three sisters.","coverage":1.0},{"start":60.48,"end":66.53,"text":"My mum worked very hard every day to look after us, and she was very busy.","coverage":0.938},{"start":66.84,"end":72.88,"text":"She always makes time for everyone and she always listens to me if I have a problem.","coverage":1.0},{"start":73.12,"end":75.92,"text":"She gives me advice and she is always right.","coverage":1.0},{"start":76.24,"end":81.05,"text":"I have a nephew who is sick and has to go to the hospital a lot.","coverage":1.0},{"start":81.46,"end":84.17,"text":"My mum often sleeps at the hospital with him.","coverage":0.889},{"start":85.36,"end":91.72,"text":"I really respect her because she always looks after my family and makes sure that we have everything we need.","coverage":1.0},{"start":99.6,"end":104.6,"text":"My role models are the England women's national football team, the Lionesses.","coverage":0.923},{"start":106.32,"end":110.57,"text":"In 2022 they won the European Women's Championship.","coverage":1.0},{"start":111.7,"end":119.3,"text":"The team of eleven young women were trained by Sarina Wiegman, and she helped them win the Championship.","coverage":0.833},{"start":121.2,"end":129.12,"text":"It was difficult for them because England had not won a major tournament since 1966.","coverage":1.0},{"start":130.08,"end":132.72,"text":"But in the end, they were the best team.","coverage":1.0},{"start":133.54,"end":138.9,"text":"They worked hard every day for their dream, so I really admire them.","coverage":1.0},{"start":146.4,"end":149.36,"text":"Greta Thunberg is a brave young woman from Sweden.","coverage":0.778},{"start":149.89,"end":158.78,"text":"In 2018, at the age of 15, she protested outside the Swedish parliament for climate change.","coverage":1.0},{"start":159.22,"end":170.28,"text":"She has given speeches about climate change around the world in countries like the United States, France, Spain and the United Kingdom.","coverage":1.0},{"start":171.63,"end":179.42,"text":"In 2019, 4 million people went on strike for climate change after listening to her speeches.","coverage":0.938},{"start":180.64,"end":184.8,"text":"In 2019 she was on the cover of Time magazine.","coverage":1.0},{"start":186.26,"end":193.86,"text":"Greta is a good role model because she is brave, she never gives up and she tells the truth no matter what.","coverage":0.955}],"file":"502711368a76dba9795b.js","track":0,"media":"../assets/media/07e102b66f8fdc1715a6cd4e27bd90dd7dbdc17df489cdd721cd48fc2b5e28ec.mp3"}],"../assets/media/3e40ce6e65cbb6873e9ba1935a511e539b389548a940e50c285ad0cf511eebcd.mp3":[{"id":"PPT_3e40ce6e65cbb687","audioId":"PPT_3e40ce6e65cbb687","title":"Book 3 · Unit 8 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 98","duration":224.18,"cues":[{"start":0.0,"end":1.84,"text":"eight .five","coverage":1.0},{"start":1.84,"end":3.24,"text":"Dr Burns,","coverage":1.0},{"start":3.64,"end":5.06,"text":"thank you for coming today.","coverage":1.0},{"start":5.66,"end":7.48,"text":"Can you tell us more about the project?","coverage":1.0},{"start":8.0,"end":9.66,"text":"Where does this idea come from?","coverage":1.0},{"start":9.98,"end":10.78,"text":"Thank you.","coverage":1.0},{"start":11.28,"end":15.58,"text":"Well, the idea of paying students for their work isn't new.","coverage":1.0},{"start":16.34,"end":22.92,"text":"For example, students in Denmark are paid about 760 euros a month to attend university.","coverage":1.0},{"start":23.7,"end":26.98,"text":"They receive the payments for a maximum of six years,","coverage":1.0},{"start":27.28,"end":28.7,"text":"starting at the age of 18.","coverage":1.0},{"start":29.48,"end":36.74,"text":"The goal of paying students is to encourage them to finish their education and be able to get a good job in the future.","coverage":1.0},{"start":37.38,"end":37.78,"text":"I see.","coverage":1.0},{"start":38.86,"end":40.36,"text":"Let's hear from our first caller.","coverage":1.0},{"start":41.08,"end":45.12,"text":"Mariam Hassan is the president of a medium sized university.","coverage":1.0},{"start":45.66,"end":46.82,"text":"Dr Hassan.","coverage":1.0},{"start":47.44,"end":47.72,"text":"Hello,","coverage":1.0},{"start":48.06,"end":48.3,"text":"yes.","coverage":1.0},{"start":48.7,"end":53.38,"text":"I recently read about this new program and I really don't think it's a good idea.","coverage":1.0},{"start":54.06,"end":59.64,"text":"I understand that many students drop out of university because of financial problems.","coverage":1.0},{"start":60.12,"end":61.52,"text":"At my university alone,","coverage":1.0},{"start":61.86,"end":65.14,"text":"the dropout rate is over 25%.","coverage":1.0},{"start":65.14,"end":65.68,"text":"However,","coverage":1.0},{"start":66.28,"end":69.02,"text":"will paying students really encourage them to continue?","coverage":1.0},{"start":69.6,"end":71.62,"text":"In my experience, it won't.","coverage":1.0},{"start":72.08,"end":78.52,"text":"Of course, the statistics are terrible, but I'm not confident that this program will solve the real problems.","coverage":1.0},{"start":78.84,"end":80.8,"text":"It may just cover them up.","coverage":1.0},{"start":81.52,"end":85.12,"text":"I think the money would be better spent on student services,","coverage":1.0},{"start":85.78,"end":88.66,"text":"like hiring additional professors and advisors.","coverage":1.0},{"start":89.52,"end":94.12,"text":"Two of the reasons why students drop out are stress and poor time management.","coverage":1.0},{"start":94.84,"end":98.56,"text":"Advisors can help students learn to manage their time better.","coverage":1.0},{"start":99.16,"end":100.1,"text":"As a consequence,","coverage":1.0},{"start":100.56,"end":104.46,"text":"students will do better at university and will be more likely to graduate.","coverage":1.0},{"start":105.1,"end":109.88,"text":"I can see your point, but we have already spent a lot on student services.","coverage":1.0},{"start":110.44,"end":115.14,"text":"I think that paying students to study will show them that we treat them like adults.","coverage":1.0},{"start":115.7,"end":117.62,"text":"It will give them a sense of responsibility.","coverage":1.0},{"start":118.76,"end":127.42,"text":"University students are young adults and so when they have a choice between staying at university and studying or going to work and making money,","coverage":1.0},{"start":127.74,"end":129.56,"text":"they often make the wrong choice.","coverage":1.0},{"start":130.28,"end":133.64,"text":"They want to have money so that they can buy things for themselves.","coverage":1.0},{"start":134.06,"end":134.56,"text":"Besides,","coverage":1.0},{"start":134.92,"end":136.42,"text":"we don't want to pay them a lot.","coverage":1.0},{"start":136.78,"end":138.96,"text":"I think we're simply giving them an option.","coverage":1.0},{"start":138.96,"end":144.06,"text":"Stay at university and be paid or get a minimum wage job.","coverage":1.0},{"start":144.5,"end":148.42,"text":"Christine Thorne is a parent with two children at university.","coverage":1.0},{"start":149.34,"end":149.62,"text":"Hello.","coverage":1.0},{"start":150.3,"end":154.0,"text":"I was very worried when I heard about this new program.","coverage":1.0},{"start":154.64,"end":159.26,"text":"I realize that students need encouragement to stay at university,","coverage":1.0},{"start":159.56,"end":161.82,"text":"but are we going in the right direction?","coverage":1.0},{"start":162.6,"end":163.52,"text":"First of all,","coverage":1.0},{"start":163.88,"end":167.08,"text":"I feel that we're sending the students the wrong message.","coverage":1.0},{"start":167.08,"end":172.18,"text":"Learning should be about studying new things and being responsible.","coverage":1.0},{"start":173.08,"end":173.66,"text":"Personally,","coverage":1.0},{"start":174.22,"end":183.56,"text":"I think the students who aren't interested in studying will simply take the easy courses to keep their average grade high and get the cash.","coverage":1.0},{"start":184.3,"end":187.62,"text":"I believe that we should focus more on rewarding,","coverage":1.0},{"start":188.0,"end":193.56,"text":"excellent universities and teachers and not on students who might be lazy.","coverage":1.0},{"start":194.12,"end":199.54,"text":"These are all good points, but I don't think that this view applies to all students.","coverage":1.0},{"start":200.26,"end":203.86,"text":"Not all parents are educated or interested in studying.","coverage":1.0},{"start":204.4,"end":207.78,"text":"They pass this bad attitude on to their own children.","coverage":1.0},{"start":208.48,"end":210.94,"text":"Then the children don't see the benefits of learning.","coverage":1.0},{"start":211.46,"end":212.8,"text":"To change this image,","coverage":1.0},{"start":213.24,"end":215.82,"text":"we need to show them a good reason for studying.","coverage":1.0},{"start":216.68,"end":217.38,"text":"Thank you.","coverage":1.0},{"start":217.82,"end":222.28,"text":"Let's have a look now at some of the comments we've received during the program.","coverage":1.0}],"file":"554d96fcea37e21dac88.js","track":0,"media":"../assets/media/3e40ce6e65cbb6873e9ba1935a511e539b389548a940e50c285ad0cf511eebcd.mp3"}],"../assets/media/a2240ae1b0a04b850eeb31ac7308f0d3bd44d7cee0b1d10e23e01ba012899bbb.wav":[{"id":"B3_U06_T6.1_LONG_L02_v01","audioId":"B3_U06_T6.1_LONG_L02_v01","title":"Book 3 · Unit 6 · H3 · 听力材料 2","subtitle":"H3 · 6.1-L02","duration":71.11943310657597,"cues":[{"start":0,"end":8.4,"text":"In rooms 12A and 12B we have works by the great medieval engineer, al-Jazari.","coverage":0.941},{"start":10.0,"end":13.64,"text":"Al-Jazari lived in twelfth-century Turkey.","coverage":0.714},{"start":14.0,"end":28.63,"text":"His work The Book of Knowledge of Ingenious Mechanical Devices lists one hundred different machines with instructions and diagrams explaining how to build them.","coverage":0.875},{"start":29.0,"end":36.08,"text":"In this exhibition, you can see models of some of the devices which were designed by al-Jazari.","coverage":0.944},{"start":37.0,"end":40.64,"text":"Here, you can see his mechanical clocks.","coverage":1.0},{"start":41.62,"end":45.53,"text":"Water and weights make the clocks work.","coverage":1.0},{"start":46.62,"end":49.65,"text":"However, his most important invention was the crankshaft.","coverage":0.875},{"start":51.01,"end":58.55,"text":"The crankshaft is a long arm which allows machines to move in a straight line.","coverage":0.933},{"start":59.0,"end":64.6,"text":"It was first used for watering gardens and fields on farms.","coverage":1.0},{"start":65.0,"end":70.57,"text":"In more modern times, a crankshaft is used in car engines.","coverage":0.909}],"file":"557fbd654a2c2043ee17.js","track":1,"media":"../assets/media/a2240ae1b0a04b850eeb31ac7308f0d3bd44d7cee0b1d10e23e01ba012899bbb.wav"}],"../assets/media/517da1cfb6cb03dc5597e12074cacaf267658e3cb189b2735d8cdee389c11b4a.wav":[{"id":"B3_U06_T6.1_LONG_L03_v01","audioId":"B3_U06_T6.1_LONG_L03_v01","title":"Book 3 · Unit 6 · H3 · 听力材料 3","subtitle":"H3 · 6.1-L03","duration":86.45083900226757,"cues":[{"start":0,"end":6.62,"text":"As we move along, you’ll find one of the most important inventions of medieval times.","coverage":1.0},{"start":7.52,"end":14.1,"text":"This invention has changed the history of the world in ways that we can’t even imagine.","coverage":1.0},{"start":14.56,"end":20.68,"text":"It’s one of the four great inventions of Chinese culture: gunpowder.","coverage":0.917},{"start":23.4,"end":34.06,"text":"Gunpowder was invented in the ninth century by Chinese scientists who were trying to create a powder which would make you live forever.","coverage":0.913},{"start":34.48,"end":43.68,"text":"They weren’t successful, of course, but their attempts led to the invention of fireworks and weapons.","coverage":1.0},{"start":44.3,"end":55.71,"text":"The first instructions on how to make gunpowder were written in the eleventh century by Zeng Gongliang, Ding Du and Yang Weide.","coverage":0.773},{"start":57.2,"end":62.7,"text":"The invention of gunpowder has changed the way we fight wars.","coverage":0.909},{"start":63.1,"end":71.22,"text":"It changed the outcome of many medieval battles and affected the history of the world.","coverage":1.0},{"start":71.64,"end":78.97,"text":"Many people think gunpowder is the most important invention in history.","coverage":0.909},{"start":79.4,"end":84.27,"text":"Now, let’s move to the next room, which is all about medieval medicine …","coverage":1.0}],"file":"557fbd654a2c2043ee17.js","track":2,"media":"../assets/media/517da1cfb6cb03dc5597e12074cacaf267658e3cb189b2735d8cdee389c11b4a.wav"}],"../assets/media/7ec5f240c3d212e95ee802173217d27811cb07985f68aafdd49e5092c70349df.wav":[{"id":"B2_U03_T3.3_LONG_L01_v01","audioId":"B2_U03_T3.3_LONG_L01_v01","title":"Book 2 · Unit 3 · H3 · 听力材料 1","subtitle":"H3 · L01","duration":102.81902494331065,"cues":[{"start":0.35,"end":9.08,"text":"Host: Welcome to University Podcasts, programmes made by students for students.","coverage":0.727},{"start":9.75,"end":14.3,"text":"I’m Chen Hu [who] and this is Science with a Professor.","coverage":0.917},{"start":14.93,"end":22.75,"text":"Our subject is technology development, and our guest is Professor Joanne Kent, expert in robotics.","coverage":0.933},{"start":23.46,"end":25.37,"text":"Thanks for coming, Professor.","coverage":1.0},{"start":25.95,"end":34.36,"text":"When we think of robots, we generally think of simple robots that clean the floor in our home or build a car in a factory.","coverage":1.0},{"start":34.97,"end":38.85,"text":"But how close are we to having robots that are like people?","coverage":1.0},{"start":39.52,"end":48.12,"text":"Professor: Well, we already have some robots that look like people, and technology is developing more every day.","coverage":0.944},{"start":49.06,"end":54.21,"text":"Robots weren’t used very much in the past, since they were always really expensive.","coverage":1.0},{"start":54.48,"end":61.46,"text":"But because they’re cheaper now, they’re being used in new and interesting ways.","coverage":1.0},{"start":62.22,"end":63.25,"text":"Host: What kinds of ways?","coverage":0.8},{"start":64.02,"end":76.36,"text":"Professor: Well, as you said, robots have been used in factories for years; Singapore and Korea are among the top five countries in the world with factory robots.","coverage":0.964},{"start":77.05,"end":80.65,"text":"And Japan has robots that serve food in some cafés.","coverage":0.818},{"start":81.76,"end":91.59,"text":"But now, in the US, some restaurants are testing robots which work in the kitchen and cook food, or which deliver pizza to homes.","coverage":0.958},{"start":92.3,"end":97.74,"text":"Also, robots are being developed to work on farms and help grow food.","coverage":1.0},{"start":98.78,"end":101.93,"text":"They can pick fruit, for example, or look at plant health.","coverage":1.0}],"file":"5822c28b6524e4435c7c.js","track":0,"media":"../assets/media/7ec5f240c3d212e95ee802173217d27811cb07985f68aafdd49e5092c70349df.wav"}],"../assets/media/632b9f17620720eaa5d5fb33819632269f0bed16ba44e8fa7178c049a82ea3e7.wav":[{"id":"B2_U03_T3.3_LONG_L02_v01","audioId":"B2_U03_T3.3_LONG_L02_v01","title":"Book 2 · Unit 3 · H3 · 听力材料 2","subtitle":"H3 · L02","duration":77.75453514739229,"cues":[{"start":0.57,"end":1.39,"text":"Host: Interesting.","coverage":0.5},{"start":2.23,"end":5.66,"text":"But what about robots that look after or help people?","coverage":1.0},{"start":6.4,"end":7.58,"text":"Do we have those?","coverage":1.0},{"start":8.02,"end":20.26,"text":"Professor: Well, many companies are developing robots to help people who have a disability or people who can’t always do housework or care for themselves easily.","coverage":0.926},{"start":20.66,"end":28.69,"text":"They might need help from robots that can carry things around the house or deliver medicine on time.","coverage":1.0},{"start":29.07,"end":32.36,"text":"These types of robots are becoming less expensive.","coverage":1.0},{"start":32.63,"end":37.69,"text":"Having a robot means people are able to stay in their own homes.","coverage":1.0},{"start":38.57,"end":43.54,"text":"Host: So do people have a much better quality of life thanks to these new types of robots?","coverage":0.944},{"start":43.92,"end":52.67,"text":"Professor: Yes, but at this time, it’s too expensive to have robots at home that can pick people up or feed them.","coverage":0.957},{"start":53.0,"end":61.56,"text":"Also, when robots were used in care homes, the nurses found that the robots didn’t save time.","coverage":1.0},{"start":61.96,"end":63.19,"text":"Host: Why is that?","coverage":0.75},{"start":63.62,"end":66.22,"text":"Professor: The robots had to be moved and watched.","coverage":0.889},{"start":66.88,"end":73.4,"text":"The nurses spent time looking after the robots and so they had less time to look after the people.","coverage":1.0},{"start":73.64,"end":76.86,"text":"They stopped using the robots due to the lost time.","coverage":1.0}],"file":"5822c28b6524e4435c7c.js","track":1,"media":"../assets/media/632b9f17620720eaa5d5fb33819632269f0bed16ba44e8fa7178c049a82ea3e7.wav"}],"../assets/media/33efd5ef67d9fea671d1f326ac12ad2f132f802aade0e3859711947840892396.wav":[{"id":"B2_U03_T3.3_LONG_L03_v01","audioId":"B2_U03_T3.3_LONG_L03_v01","title":"Book 2 · Unit 3 · H3 · 听力材料 3","subtitle":"H3 · L03","duration":99.97816326530612,"cues":[{"start":0.5,"end":1.33,"text":"Host: I see.","coverage":0.667},{"start":2.52,"end":4.97,"text":"What are some other ways that robots are used?","coverage":1.0},{"start":6.1,"end":14.96,"text":"Professor: These days, people use robots for science research, to repair equipment in the ocean, and as assistants to doctors and librarians.","coverage":0.864},{"start":16.84,"end":16.88,"text":"Host: Really?","coverage":0.5},{"start":17.17,"end":19.64,"text":"What kind of science research?","coverage":1.0},{"start":19.98,"end":22.77,"text":"I know about robots on the planet Mars.","coverage":1.0},{"start":23.06,"end":29.96,"text":"Professor: Yes, robots go to places that we can’t go to collect information, like on Mars.","coverage":0.941},{"start":29.96,"end":37.57,"text":"They can prevent accidents by doing dangerous things and they can go into areas with bad pollution.","coverage":1.0},{"start":38.04,"end":41.1,"text":"Host: And you also said robots could be doctors or librarians.","coverage":0.818},{"start":42.28,"end":50.65,"text":"Does that mean I shouldn’t study for a degree in library studies because a robot is going to take all the librarians’ jobs?","coverage":0.958},{"start":51.48,"end":55.66,"text":"Professor: No, robots only help with the boring parts of being a librarian.","coverage":0.846},{"start":56.76,"end":63.24,"text":"They use bar codes to look for books on the shelves or put books in the right place.","coverage":1.0},{"start":65.28,"end":67.62,"text":"But what about a robot doctor?","coverage":1.0},{"start":67.94,"end":71.83,"text":"Am I going to see a robot when I go to the doctors?","coverage":1.0},{"start":72.22,"end":73.56,"text":"Professor: No, not yet.","coverage":0.75},{"start":74.57,"end":79.19,"text":"But doctors can use robotic arms to help them do surgery.","coverage":1.0},{"start":80.21,"end":84.63,"text":"People stay in hospital for a shorter time because of fewer problems.","coverage":1.0},{"start":85.22,"end":92.73,"text":"Host: Well, we’ve heard about robots that clean your house, cook food, do research, and even help your doctor, too.","coverage":0.952},{"start":93.96,"end":96.44,"text":"Host: OK, we have some questions coming in, so let’s hear the first one …","coverage":0.929}],"file":"5822c28b6524e4435c7c.js","track":2,"media":"../assets/media/33efd5ef67d9fea671d1f326ac12ad2f132f802aade0e3859711947840892396.wav"}],"../assets/media/cd1261fe09fd46e2626e133e970547d2bf8e70d0aba6881ead110fdbecc4be2d.mp3":[{"id":"PPT_cd1261fe09fd46e2","audioId":"PPT_cd1261fe09fd46e2","title":"Book 2 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 90","duration":64.57,"cues":[{"start":0.0,"end":2.22,"text":"one .four","coverage":1.0},{"start":3.36,"end":4.16,"text":"one.","coverage":1.0},{"start":5.88,"end":8.68,"text":"Obviously Stanley Park is a large park.","coverage":1.0},{"start":10.92,"end":11.72,"text":"two.","coverage":1.0},{"start":12.96,"end":13.64,"text":"In fact,","coverage":1.0},{"start":14.0,"end":16.6,"text":"because it is located in the city of Vancouver,","coverage":1.0},{"start":17.12,"end":20.56,"text":"it is the third largest urban park in North America.","coverage":1.0},{"start":23.02,"end":23.74,"text":"three.","coverage":1.0},{"start":25.12,"end":26.14,"text":"As we know,","coverage":1.0},{"start":26.46,"end":29.58,"text":"lots of trees help clean the city air.","coverage":1.0},{"start":32.18,"end":32.9,"text":"four.","coverage":1.0},{"start":34.14,"end":34.66,"text":"Finally,","coverage":1.0},{"start":35.22,"end":42.56,"text":"while I think these disadvantages might mean that some people would not want to visit Vancouver...","coverage":1.0},{"start":43.84,"end":44.7,"text":"five.","coverage":1.0},{"start":46.08,"end":50.24,"text":"I personally feel that most people would enjoy Vancouver.","coverage":1.0},{"start":52.8,"end":53.66,"text":"six.","coverage":1.0},{"start":54.84,"end":55.9,"text":"In my opinion,","coverage":1.0},{"start":56.36,"end":62.74,"text":"being close to nature and having a healthy city are worth paying a little more money for.","coverage":1.0}],"file":"58ede0f2cfe1b5a9c388.js","track":0,"media":"../assets/media/cd1261fe09fd46e2626e133e970547d2bf8e70d0aba6881ead110fdbecc4be2d.mp3"}],"../assets/media/5bf8f7a4809ea3e1fe318be3a7371f0006a4963ec39b28d06cc8481413f0e55c.mp3":[{"id":"PPT_5bf8f7a4809ea3e1","audioId":"PPT_5bf8f7a4809ea3e1","title":"Book 3 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 92","duration":43.18,"cues":[{"start":0.0,"end":1.94,"text":"one .three","coverage":1.0},{"start":1.94,"end":3.06,"text":"one","coverage":1.0},{"start":4.08,"end":13.56,"text":"First, there needs to be an increase in the number of specially trained guards who work in the rainforests to catch the poachers.","coverage":1.0},{"start":15.5,"end":17.44,"text":"two two.","coverage":1.0},{"start":18.14,"end":25.56,"text":"Governments must introduce an immediate and complete ban on anyone buying or selling ivory,","coverage":1.0},{"start":26.14,"end":28.5,"text":"even between countries sharing a border.","coverage":1.0},{"start":30.82,"end":31.7,"text":"three","coverage":1.0},{"start":32.26,"end":33.02,"text":"So,","coverage":1.0},{"start":33.42,"end":34.34,"text":"to summarize,","coverage":1.0},{"start":35.0,"end":37.86,"text":"as well as habitat loss and human contact,","coverage":1.0},{"start":38.22,"end":41.28,"text":"the main threat to forest elephants comes from poaching.","coverage":1.0}],"file":"5abd7bd0102d2e07b5fe.js","track":0,"media":"../assets/media/5bf8f7a4809ea3e1fe318be3a7371f0006a4963ec39b28d06cc8481413f0e55c.mp3"}],"../assets/media/22b30a333f4ad3dce3ba0e0e52373515665dc9c6342cb42be553251afd25ab58.mp3":[{"id":"PPT_22b30a333f4ad3dc","audioId":"PPT_22b30a333f4ad3dc","title":"Book 2 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 57","duration":25.81,"cues":[{"start":0.0,"end":2.0,"text":"three .two","coverage":1.0},{"start":3.64,"end":7.06,"text":"one Can you wash the pan on the cooker?","coverage":1.0},{"start":9.04,"end":9.68,"text":"two","coverage":1.0},{"start":10.5,"end":12.56,"text":"Please don't sit on the sheet","coverage":1.0},{"start":14.46,"end":15.1,"text":"three","coverage":1.0},{"start":15.98,"end":18.34,"text":"Please sew me a blue dress","coverage":1.0},{"start":20.16,"end":20.8,"text":"four","coverage":1.0},{"start":21.4,"end":23.88,"text":"This cheap wool is not nice","coverage":1.0}],"file":"5b74096232f315fef20d.js","track":0,"media":"../assets/media/22b30a333f4ad3dce3ba0e0e52373515665dc9c6342cb42be553251afd25ab58.mp3"}],"../assets/media/1c2cf5ba30a7c3565ea29093d7e555239295ab7f54d0fb5278172bc89b93a5d4.mp3":[{"id":"PPT_1c2cf5ba30a7c356","audioId":"PPT_1c2cf5ba30a7c356","title":"Book 3 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 48","duration":155.79,"cues":[{"start":0.0,"end":1.74,"text":"two .three","coverage":1.0},{"start":2.02,"end":3.7,"text":"An Australian company,","coverage":1.0},{"start":4.02,"end":5.1,"text":"Sun Drop Farms,","coverage":1.0},{"start":5.66,"end":8.58,"text":"combined hydroponics with solar energy.","coverage":1.0},{"start":9.58,"end":14.66,"text":"Traditional farming uses between 60 and 80 % of our planet's fresh water.","coverage":1.0},{"start":15.16,"end":15.72,"text":"However,","coverage":1.0},{"start":16.14,"end":19.1,"text":"Sun Drop Farms doesn't use fresh water.","coverage":1.0},{"start":19.64,"end":21.38,"text":"It uses sea water.","coverage":1.0},{"start":21.98,"end":25.9,"text":"Sun Drop Farms is only 100 metres from the shore.","coverage":1.0},{"start":26.68,"end":32.7,"text":"A line of mirrors reflects heat from the sun onto a pipe which has oil inside.","coverage":1.0},{"start":33.74,"end":39.2,"text":"The hot oil in the pipe heats up sea water which is kept in special containers.","coverage":1.0},{"start":40.46,"end":43.8,"text":"When the sea water reaches 160 degrees Celsius,","coverage":1.0},{"start":44.46,"end":46.34,"text":"the steam provides electricity.","coverage":1.0},{"start":47.32,"end":52.16,"text":"Some of the hot water is used to heat the greenhouse during the cold desert nights.","coverage":1.0},{"start":52.69,"end":54.84,"text":"The plants grow in the greenhouse,","coverage":1.0},{"start":55.4,"end":58.22,"text":"a building with glass walls and a glass ceiling.","coverage":1.0},{"start":59.42,"end":63.44,"text":"The rest of the heated water goes to a desalination plant.","coverage":1.0},{"start":64.74,"end":70.88,"text":"Desalination is when we remove the salt from sea water to create drinkable water,","coverage":1.0},{"start":71.4,"end":72.04,"text":"that is,","coverage":1.0},{"start":72.36,"end":74.82,"text":"water which is clean and safe to drink.","coverage":1.0},{"start":75.72,"end":82.98,"text":"The desalination plant can produce up to ten ,000 litres of fresh water every day.","coverage":1.0},{"start":83.78,"end":89.14,"text":"The farmer adds nutrients to this fresh water and then grows fruit and vegetables.","coverage":1.0},{"start":90.2,"end":91.34,"text":"To summarise,","coverage":1.0},{"start":91.76,"end":100.06,"text":"solar energy removes the salt from the sea water and the fresh water is then used inside the greenhouse where the plants are growing.","coverage":1.0},{"start":101.18,"end":105.66,"text":"Many people around the world are really excited about this technology.","coverage":1.0},{"start":106.34,"end":107.12,"text":"So far,","coverage":1.0},{"start":107.76,"end":109.78,"text":"Australian farms have grown tomatoes,","coverage":1.0},{"start":110.18,"end":113.98,"text":"peppers and cucumbers using hydroponics.","coverage":1.0},{"start":115.18,"end":121.96,"text":"Many supermarkets are interested in buying these vegetables because they are grown without pesticides or other chemicals.","coverage":1.0},{"start":123.2,"end":128.6,"text":"Some people think hydroponics is the perfect solution to the world food crisis.","coverage":1.0},{"start":129.5,"end":130.26,"text":"Finally,","coverage":1.0},{"start":131.1,"end":135.76,"text":"the desert farms use solar energy and not fossil fuels.","coverage":1.0},{"start":136.48,"end":139.6,"text":"Thus, their negative effect on the environment is minimal.","coverage":1.0},{"start":140.64,"end":141.44,"text":"Now, of course,","coverage":1.0},{"start":141.8,"end":143.9,"text":"the future of hydroponics is unknown.","coverage":1.0},{"start":144.5,"end":150.02,"text":"But I think the desert farms might be a very interesting way to farm in the future.","coverage":1.0},{"start":151.02,"end":153.86,"text":"Now, let's discuss some of the problems.","coverage":1.0}],"file":"5c51183887cdd125d7ed.js","track":0,"media":"../assets/media/1c2cf5ba30a7c3565ea29093d7e555239295ab7f54d0fb5278172bc89b93a5d4.mp3"}],"../assets/media/eeb1271a2140049bc972bbdd994ee82a9a2af1f643d8af1c0fc85fd1a289a41a.mp3":[{"id":"B3_U07_T7.1_SHORT_S02_v01","audioId":"B3_U07_T7.1_SHORT_S02_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 2","subtitle":"H2 · 7.1-S02","duration":77.780658,"cues":[{"start":0,"end":3.58,"text":"Hamed: The artist from the south of England who paints the world around her?","coverage":0.929},{"start":4.25,"end":9.6,"text":"Yoriko: Yes, views out onto her garden, natural scenes, that sort of thing.","coverage":0.923},{"start":9.72,"end":17.37,"text":"A fast fashion company lifted images of her paintings they found on her website and used them on a clothing range.","coverage":1.0},{"start":17.68,"end":22.96,"text":"I’m sure they made loads a lot of money, and I don’t think she got anything in return.","coverage":0.95},{"start":23.24,"end":25.4,"text":"Hamed: No, she didn’t get anything.","coverage":0.857},{"start":25.84,"end":28.97,"text":"No payment, no credit for her work, nothing.","coverage":1.0},{"start":29.28,"end":30.67,"text":"She’s not alone, though.","coverage":1.0},{"start":30.92,"end":31.13,"text":"Yoriko: No.","coverage":0.5},{"start":31.35,"end":34.22,"text":"We should also use the example of Kirstie Moran.","coverage":0.778},{"start":35.52,"end":39.12,"text":"She creates interesting, unusual designs of animals.","coverage":1.0},{"start":39.91,"end":46.71,"text":"Her artwork was also used by a fast fashion company and again, she got nothing from them.","coverage":1.0},{"start":47.12,"end":56.44,"text":"Hamed: I mean, this is a perfect example of a company taking an artist’s designs without permission and using them to sell clothes and make a profit.","coverage":0.964},{"start":57.12,"end":58.23,"text":"What can anyone do?","coverage":1.0},{"start":58.86,"end":66.4,"text":"Yoriko: Some large fashion companies take legal action when their designs are copied, but it takes money and power to do that.","coverage":0.955},{"start":66.72,"end":77.15,"text":"It’s just not practical for an independent artist like Kirstie Moran to say, ‘if you don’t pay me for my hard work and talent, I’ll be contacting my lawyer’.","coverage":0.938}],"file":"5ca4d3b45fc985310b83.js","track":1,"media":"../assets/media/eeb1271a2140049bc972bbdd994ee82a9a2af1f643d8af1c0fc85fd1a289a41a.mp3"}],"../assets/media/90cc716384e900120b7a197e0828c990bdb059732af23394e1a617405e2ad765.mp3":[{"id":"B3_U07_T7.1_SHORT_S03_v01","audioId":"B3_U07_T7.1_SHORT_S03_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 3","subtitle":"H2 · 7.1-S03","duration":70.309637,"cues":[{"start":0.41,"end":6.85,"text":"Hamed: Well, I have seen some examples of artists defending their intellectual property, but not many.","coverage":0.938},{"start":8.51,"end":9.35,"text":"Elora Pautrat, for example.","coverage":0.5},{"start":9.68,"end":11.55,"text":"Yoriko: I haven’t read about her yet.","coverage":0.875},{"start":11.84,"end":21.2,"text":"Hamed: She did do something about it, after she discovered that a fast fashion company was converting her designs into images and putting them on clothing and bags.","coverage":0.964},{"start":21.5,"end":28.38,"text":"At first, Elora decided it wasn’t worth complaining to them by email, so she tried a different approach.","coverage":0.947},{"start":28.64,"end":32.79,"text":"She posted her complaint on social media, and it went viral.","coverage":1.0},{"start":33.54,"end":40.15,"text":"Thousands of people from all over the world criticized the company and promised never to buy anything from them again.","coverage":1.0},{"start":40.84,"end":43.89,"text":"Finally, the company wrote to her offering an apology.","coverage":1.0},{"start":44.16,"end":49.54,"text":"They actually paid her something for using her work and promised it would never happen again.","coverage":1.0},{"start":50.35,"end":53.0,"text":"Yoriko: That’s one happy ending, at least.","coverage":0.875},{"start":53.78,"end":54.41,"text":"Hamed: Not quite.","coverage":0.667},{"start":54.8,"end":61.25,"text":"The same company’s lifted her work several times since then and used it on all sorts of products.","coverage":0.895},{"start":62.12,"end":66.93,"text":"Although they’ve accepted it was their fault again, she still hasn’t received a second payment.","coverage":1.0},{"start":67.24,"end":69.68,"text":"She’s going to be disappointed this time, I imagine.","coverage":1.0}],"file":"5ca4d3b45fc985310b83.js","track":2,"media":"../assets/media/90cc716384e900120b7a197e0828c990bdb059732af23394e1a617405e2ad765.mp3"}],"../assets/media/7d6d18115da4be5c0f19146b64deedb84362be4037107c4859b7371295d21398.mp3":[{"id":"B3_U07_T7.1_SHORT_S04_v01","audioId":"B3_U07_T7.1_SHORT_S04_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 4","subtitle":"H2 · 7.1-S04","duration":42.325873,"cues":[{"start":0.28,"end":12.3,"text":"Yoriko: The thing is, these companies do have the ability and the resources to collaborate with artists, pay them for their designs and still make a lot of money – but they choose not to.","coverage":0.971},{"start":12.78,"end":13.4,"text":"Hamed: I know.","coverage":0.667},{"start":13.78,"end":15.94,"text":"It’s plagiarism, basically.","coverage":0.75},{"start":16.22,"end":17.31,"text":"And it’s not ethical.","coverage":1.0},{"start":17.92,"end":19.8,"text":"Yoriko: Oh, I do agree.","coverage":0.8},{"start":20.73,"end":24.63,"text":"Imagine doing that sort of thing on our university course!","coverage":0.8},{"start":25.22,"end":28.17,"text":"Can you see the situation changing any time soon?","coverage":0.778},{"start":28.72,"end":31.51,"text":"Hamed: No, I don’t think it will change.","coverage":0.889},{"start":31.9,"end":40.1,"text":"In a few years, these companies will be ignoring copyright law just like they do now, and artists still won’t be getting anything.","coverage":1.0}],"file":"5ca4d3b45fc985310b83.js","track":3,"media":"../assets/media/7d6d18115da4be5c0f19146b64deedb84362be4037107c4859b7371295d21398.mp3"}],"../assets/media/3685c7577cdbe159975858b5b3d9363c36f36302d017430a1da741ce6eafce90.mp3":[{"id":"B3_U07_T7.6_SHORT_S01_v01","audioId":"B3_U07_T7.6_SHORT_S01_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 5","subtitle":"H2 · 7.6-S01","duration":48.066372,"cues":[{"start":2.0,"end":5.51,"text":"Host: How did you feel about growing up in New York?","coverage":0.909},{"start":6.04,"end":11.41,"text":"Aysha: Well, as a teenager in New York, I had a lot of problems trying to dress in a modest way.","coverage":0.952},{"start":12.52,"end":20.87,"text":"For example, when you look at summer fashion in New York, the trend is always to wear skirts, shorts and sleeveless shirts.","coverage":0.955},{"start":21.2,"end":29.15,"text":"I didn’t feel comfortable wearing them, but at the same time my friends thought it was strange to wear long sleeves and jeans in the summer.","coverage":1.0},{"start":29.4,"end":32.85,"text":"So I’ve always tried to combine my culture with fashion.","coverage":1.0},{"start":33.78,"end":38.92,"text":"As a teenager, I would make my own clothes, like colourful skirts and scarves.","coverage":0.857},{"start":40.01,"end":42.76,"text":"I wanted my designs to be individual.","coverage":1.0},{"start":43.31,"end":47.59,"text":"They were unique and, eventually, people admired my clothes rather than laughed at me.","coverage":1.0}],"file":"5ca4d3b45fc985310b83.js","track":4,"media":"../assets/media/3685c7577cdbe159975858b5b3d9363c36f36302d017430a1da741ce6eafce90.mp3"}],"../assets/media/f553e744fcbc810ead50c4906da69b43e03d568b88d57326d9a16341dd6a1a95.mp3":[{"id":"B3_U07_T7.6_SHORT_S02_v01","audioId":"B3_U07_T7.6_SHORT_S02_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 6","subtitle":"H2 · 7.6-S02","duration":56.673719,"cues":[{"start":0,"end":0.56,"text":"Host: I see.","coverage":0.667},{"start":1.17,"end":5.2,"text":"So, do you know what ideas most people have about Muslim clothes?","coverage":1.0},{"start":6.12,"end":10.87,"text":"Aysha: Well, I think there’s a lot of misunderstanding about Muslim clothes.","coverage":0.923},{"start":11.04,"end":16.25,"text":"The thing is that when you say Muslim fashion, people in New York think of a burka.","coverage":0.941},{"start":17.0,"end":21.72,"text":"You know, like the blue or black cloaks which cover women from head to toe.","coverage":0.933},{"start":22.27,"end":25.46,"text":"Host: And could you explain what you think Muslim fashion is?","coverage":0.909},{"start":25.98,"end":27.29,"text":"Aysha: Let me give you an example.","coverage":0.857},{"start":27.51,"end":39.91,"text":"When I first started at design school, my teachers would ask me strange questions, such as how I was going to stay in the fashion business if I’m not going to design miniskirts or sleeveless shirts.","coverage":0.946},{"start":40.2,"end":45.47,"text":"But as far as I’m concerned, there is much more to fashion than showing your body.","coverage":1.0},{"start":46.04,"end":52.46,"text":"There are millions of Muslim women who live in the United States and Europe who want to wear fashionable clothes.","coverage":1.0},{"start":52.69,"end":56.1,"text":"There are also women who simply like to dress in a modest way.","coverage":1.0}],"file":"5ca4d3b45fc985310b83.js","track":5,"media":"../assets/media/f553e744fcbc810ead50c4906da69b43e03d568b88d57326d9a16341dd6a1a95.mp3"}],"../assets/media/47da636548bed09ce0dcda111137d3c343c99bdaf042092a8e63e0481bc23fec.mp3":[{"id":"B3_U07_T7.6_SHORT_S03_v01","audioId":"B3_U07_T7.6_SHORT_S03_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 7","subtitle":"H2 · 7.6-S03","duration":19.9978,"cues":[{"start":0.02,"end":4.43,"text":"Host: So, are you saying that there is a need for fashionable clothes for Muslim women?","coverage":0.938},{"start":4.93,"end":5.25,"text":"Aysha: Absolutely.","coverage":0.5},{"start":5.66,"end":9.11,"text":"We want to be fashionable and be ourselves at the same time.","coverage":1.0},{"start":9.77,"end":19.6,"text":"My feeling is this: I want to create clothes which are modest, but at the same time, give women confidence – clothes which allow women to be themselves.","coverage":1.0}],"file":"5ca4d3b45fc985310b83.js","track":6,"media":"../assets/media/47da636548bed09ce0dcda111137d3c343c99bdaf042092a8e63e0481bc23fec.mp3"}],"../assets/media/b611bc7ba3e41ed0b07e6954df81c09aed9dd1c07958c39af55086934c35248a.mp3":[{"id":"B3_U07_T7.6_SHORT_S04_v01","audioId":"B3_U07_T7.6_SHORT_S04_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 8","subtitle":"H2 · 7.6-S04","duration":79.220113,"cues":[{"start":0.08,"end":0.95,"text":"Host: I see what you mean.","coverage":0.833},{"start":1.4,"end":3.87,"text":"So, how would you describe your style?","coverage":1.0},{"start":4.34,"end":10.53,"text":"Aysha: Well, many reviewers have described my style as ‘traditional chic’, and I guess I’d agree with them.","coverage":0.947},{"start":11.14,"end":16.99,"text":"What I think is that combining traditional with chic is a huge area in fashion.","coverage":1.0},{"start":17.43,"end":20.5,"text":"I keep my eye on the fashion trends in other countries.","coverage":1.0},{"start":20.97,"end":29.92,"text":"When you look at the works of other designers in China and India, you can see that many traditional styles are being reused by young designers.","coverage":1.0},{"start":30.1,"end":37.65,"text":"Above all, people like to be individuals and show their cultural roots – they like to show where they come from.","coverage":1.0},{"start":38.09,"end":44.45,"text":"Host: As I understand it, your designs are must-haves for Muslim women outside the United States as well.","coverage":0.895},{"start":44.86,"end":46.41,"text":"Could you tell me more about that?","coverage":1.0},{"start":46.82,"end":47.16,"text":"Aysha: Yes.","coverage":0.5},{"start":47.77,"end":55.03,"text":"In addition to New York and Paris, I sell my collection in big cities like Doha, Dubai and Abu Dhabi.","coverage":0.95},{"start":55.54,"end":66.13,"text":"Another thing is that I also receive requests for my clothes from women in Pakistan, Indonesia, Singapore and Malaysia, so someday I might open stores there.","coverage":0.962},{"start":66.57,"end":68.13,"text":"Host: Well, I hope you decide to go for it!","coverage":0.9},{"start":68.65,"end":71.78,"text":"That would make a lot of women around the world very happy.","coverage":1.0},{"start":72.25,"end":75.22,"text":"So, Aysha, thank you for coming to the studio today.","coverage":0.9},{"start":75.58,"end":76.38,"text":"Aysha: It was my pleasure.","coverage":0.8},{"start":76.969,"end":77.529,"text":"Anytime!"}],"file":"5ca4d3b45fc985310b83.js","track":7,"media":"../assets/media/b611bc7ba3e41ed0b07e6954df81c09aed9dd1c07958c39af55086934c35248a.mp3"}],"../assets/media/dd146f13c4927923f79519c6430829ea38a0cf35072a6ce21292ef957daec063.mp3":[{"id":"B3_U07_T7.7_SHORT_S01_v01","audioId":"B3_U07_T7.7_SHORT_S01_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 9","subtitle":"H2 · 7.7-S01","duration":48.588821,"cues":[{"start":2.0,"end":7.62,"text":"Host: In today’s show, we’ll be interviewing the talented fashion designer Aysha Al-Husaini.","coverage":0.812},{"start":9.13,"end":13.83,"text":"Hot on the heels of her fashion week show, Aysha’s new collection is very popular in Doha.","coverage":0.889},{"start":15.23,"end":22.86,"text":"She got the attention of the fashion world with her unique designs, which combine traditional Muslim fashion with French chic.","coverage":1.0},{"start":23.65,"end":25.6,"text":"Aysha, thank you for coming to the studio.","coverage":0.875},{"start":26.12,"end":26.88,"text":"Aysha: Thank you for having me.","coverage":0.833},{"start":27.81,"end":30.93,"text":"Host: First of all, can you tell me where you get your ideas from?","coverage":0.929},{"start":31.59,"end":33.68,"text":"Aysha: Well, I come from a Muslim family.","coverage":0.875},{"start":34.0,"end":35.91,"text":"My parents are both from Qatar.","coverage":1.0},{"start":36.11,"end":39.1,"text":"I was born there, but then we travelled a lot.","coverage":1.0},{"start":39.61,"end":43.69,"text":"I went to school in New York and I went to a design school there.","coverage":1.0},{"start":44.09,"end":48.2,"text":"These days, I spend my time travelling between Qatar and the United States.","coverage":0.923}],"file":"5ca4d3b45fc985310b83.js","track":8,"media":"../assets/media/dd146f13c4927923f79519c6430829ea38a0cf35072a6ce21292ef957daec063.mp3"}],"../assets/media/17d52d638de7d608c96e0b1cbed91efbe4679e7c1568408b6cbce0efbefdc218.mp3":[{"id":"B3_U07_T7.7_SHORT_S02_v01","audioId":"B3_U07_T7.7_SHORT_S02_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 10","subtitle":"H2 · 7.7-S02","duration":45.728413,"cues":[{"start":0.27,"end":3.17,"text":"Host: How did you feel about growing up in New York?","coverage":0.909},{"start":3.91,"end":9.8,"text":"Aysha: Well, as a teenager in New York, I had a lot of problems trying to dress in a modest way.","coverage":0.952},{"start":10.19,"end":18.52,"text":"For example, when you look at summer fashion in New York, the trend is always to wear skirts, shorts and sleeveless shirts.","coverage":0.955},{"start":18.84,"end":26.91,"text":"I didn’t feel comfortable wearing them, but at the same time my friends thought it was strange to wear long sleeves and jeans in the summer.","coverage":1.0},{"start":27.58,"end":30.78,"text":"So I’ve always tried to combine my culture with fashion.","coverage":1.0},{"start":31.28,"end":36.54,"text":"As a teenager, I would make my own clothes, like colourful skirts and scarves.","coverage":0.857},{"start":37.6,"end":40.39,"text":"I wanted my designs to be individual.","coverage":1.0},{"start":40.97,"end":45.21,"text":"They were unique and eventually people admired my clothes rather than laughed at me.","coverage":1.0}],"file":"5ca4d3b45fc985310b83.js","track":9,"media":"../assets/media/17d52d638de7d608c96e0b1cbed91efbe4679e7c1568408b6cbce0efbefdc218.mp3"}],"../assets/media/8240d92dc41daa789f944524647aff5f022f2b11ff98c2b2b7ed58ea39a0a0fa.mp3":[{"id":"B3_U07_T7.7_SHORT_S04_v01","audioId":"B3_U07_T7.7_SHORT_S04_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 11","subtitle":"H2 · 7.7-S04","duration":57.979841,"cues":[{"start":0.03,"end":4.36,"text":"Host: So, are you saying that there is a need for fashionable clothes for Muslim women?","coverage":0.938},{"start":4.85,"end":5.17,"text":"Aysha: Absolutely.","coverage":0.5},{"start":5.56,"end":9.03,"text":"We want to be fashionable and be ourselves at the same time.","coverage":1.0},{"start":9.47,"end":19.54,"text":"My feeling is this: I want to create clothes which are modest, but at the same time, give women confidence – clothes which allow women to be themselves.","coverage":1.0},{"start":19.91,"end":20.93,"text":"Host: I see what you mean.","coverage":0.833},{"start":21.16,"end":23.75,"text":"So, how would you describe your style?","coverage":1.0},{"start":24.33,"end":30.69,"text":"Aysha: Well, many reviewers have described my style as ‘traditional chic’, and I guess I’d agree with them.","coverage":0.947},{"start":31.25,"end":37.01,"text":"What I think is that combining traditional with chic is a huge area in fashion.","coverage":0.933},{"start":37.39,"end":40.49,"text":"I keep my eye on the fashion trends in other countries.","coverage":1.0},{"start":40.98,"end":49.88,"text":"When you look at the works of other designers in China and India, you can see that many traditional styles are being reused by young designers.","coverage":1.0},{"start":50.45,"end":57.6,"text":"Above all, people like to be individuals and show their cultural roots – they like to show where they come from.","coverage":1.0}],"file":"5ca4d3b45fc985310b83.js","track":10,"media":"../assets/media/8240d92dc41daa789f944524647aff5f022f2b11ff98c2b2b7ed58ea39a0a0fa.mp3"}],"../assets/media/3795d0a9004323b8baec3469e241316ed0151f259e39ad95b2b1ce0afcb194bb.mp3":[{"id":"B3_U07_T7.7_SHORT_S05_v01","audioId":"B3_U07_T7.7_SHORT_S05_v01","title":"Book 3 · Unit 7 · H2 · 听力材料 12","subtitle":"H2 · 7.7-S05","duration":41.415692,"cues":[{"start":0.16,"end":6.4,"text":"Host: As I understand it, your designs are must-haves for Muslim women outside the United States as well.","coverage":0.895},{"start":6.96,"end":8.38,"text":"Could you tell me more about that?","coverage":1.0},{"start":8.96,"end":9.28,"text":"Aysha: Yes.","coverage":0.5},{"start":9.76,"end":16.43,"text":"In addition to New York and Paris, I sell my collection in big cities like Doha, Dubai and Abu Dhabi.","coverage":0.95},{"start":16.96,"end":28.02,"text":"Another thing is that I also receive requests for my clothes from women in Pakistan, Indonesia, Singapore and Malaysia, so someday I might open stores there.","coverage":0.962},{"start":28.56,"end":30.3,"text":"Host: Well, I hope you decide to go for it!","coverage":0.9},{"start":30.55,"end":33.49,"text":"That would make a lot of women around the world very happy.","coverage":1.0},{"start":34.24,"end":37.14,"text":"So, Aysha, thank you for coming to the studio today.","coverage":0.9},{"start":37.6,"end":38.61,"text":"Aysha: It was my pleasure.","coverage":0.8},{"start":38.981,"end":39.441,"text":"Anytime!"}],"file":"5ca4d3b45fc985310b83.js","track":11,"media":"../assets/media/3795d0a9004323b8baec3469e241316ed0151f259e39ad95b2b1ce0afcb194bb.mp3"}],"../assets/media/7be7557715d5ddad482e1284ae4f9c8ccd28120187a1a1770a8bd48389ed4022.wav":[{"id":"B2_U02_T2.1_SHORT_S02_v01","audioId":"B2_U02_T2.1_SHORT_S02_v01","title":"Book 2 · Unit 2 · H2 · 听力材料 2","subtitle":"H2 · S02","duration":25.180498866213153,"cues":[{"start":0,"end":2.85,"text":"Reporter 1: Why do you like coming to the festival?","coverage":0.8},{"start":3.68,"end":6.54,"text":"Olivia: Well, it’s an interesting event to come to.","coverage":0.9},{"start":6.9,"end":10.03,"text":"It’s great for children and adults.","coverage":1.0},{"start":10.52,"end":15.99,"text":"I enjoy learning about all the new ideas people have on important topics.","coverage":1.0},{"start":16.32,"end":24.35,"text":"We don’t get much time to really think or learn about new things in everyday life, but you can do exactly that at this festival.","coverage":1.0}],"file":"5d770eb735a75b3b4954.js","track":1,"media":"../assets/media/7be7557715d5ddad482e1284ae4f9c8ccd28120187a1a1770a8bd48389ed4022.wav"}],"../assets/media/cc078a79fcc63608dd76d92a8c7f38522f1c5e2302b1622e150171a019ec20d2.wav":[{"id":"B2_U02_T2.1_SHORT_S03_v01","audioId":"B2_U02_T2.1_SHORT_S03_v01","title":"Book 2 · Unit 2 · H2 · 听力材料 3","subtitle":"H2 · S03","duration":53.9585260770975,"cues":[{"start":0,"end":4.17,"text":"Reporter 1: So, what kinds of things do people learn and do here?","coverage":0.846},{"start":4.68,"end":7.7,"text":"Do people try mainly one type of thing?","coverage":1.0},{"start":8.04,"end":11.84,"text":"Olivia: No, most people plan on going to several events.","coverage":0.9},{"start":12.24,"end":15.27,"text":"For example, today I learned about nature.","coverage":1.0},{"start":15.58,"end":19.24,"text":"I went to a lecture about the sea and new ways to clean it.","coverage":1.0},{"start":19.52,"end":21.04,"text":"It was quite interesting!","coverage":1.0},{"start":21.9,"end":24.97,"text":"Yesterday, I walked around a 3D art show.","coverage":1.0},{"start":25.32,"end":28.15,"text":"The entire room was covered in pictures.","coverage":1.0},{"start":28.44,"end":30.61,"text":"It was an exciting activity.","coverage":1.0},{"start":30.96,"end":34.36,"text":"It felt like flying over the trees and mountains.","coverage":1.0},{"start":34.68,"end":43.34,"text":"And tomorrow, I’m going to a talk on how food can help people live better lives, which I’m sure will really make me think!","coverage":1.0},{"start":43.72,"end":46.82,"text":"Reporter 1: Are there any things you don’t like about it?","coverage":0.833},{"start":47.47,"end":48.77,"text":"Are you ever bored?","coverage":1.0},{"start":49.59,"end":50.25,"text":"Olivia: Not really.","coverage":0.667},{"start":50.64,"end":52.94,"text":"The only problem is that it’s really crowded.","coverage":1.0}],"file":"5d770eb735a75b3b4954.js","track":2,"media":"../assets/media/cc078a79fcc63608dd76d92a8c7f38522f1c5e2302b1622e150171a019ec20d2.wav"}],"../assets/media/b950653b5da0aa28fdaae1b0b46f0bdc98850893b03426600bc1e3f8bb35b71e.mp3":[{"id":"B2_U02_T2.1_SHORT_S04_v01","audioId":"B2_U02_T2.1_SHORT_S04_v01","title":"Book 2 · Unit 2 · H2 · 听力材料 4","subtitle":"H2 · S04","duration":54.636168,"cues":[{"start":0.71,"end":6.09,"text":"Reporter 1: Olivia, like many others, is really enjoying the Vivid Sydney festival.","coverage":0.769},{"start":7.74,"end":15.07,"text":"Nowadays, around the world, there are many festivals, often based on nature, food or culture.","coverage":0.933},{"start":15.48,"end":19.61,"text":"Take the Cherry Blossom Festival in Japan, for example.","coverage":1.0},{"start":19.96,"end":26.23,"text":"In Tokyo, the capital of Japan, the Cherry Blossom Festival is held in early April.","coverage":1.0},{"start":26.96,"end":30.49,"text":"It is an important festival celebrating nature.","coverage":1.0},{"start":30.8,"end":37.98,"text":"The actual dates change every year because the celebration happens only when the trees have cherry blossoms.","coverage":0.941},{"start":39.0,"end":49.67,"text":"So, it is a little different from a festival that has the same date every year and it’s not organized in the same way as many other festivals.","coverage":1.0},{"start":50.04,"end":53.56,"text":"Our reporter Mike Pearce went to Tokyo to find out.","coverage":0.9}],"file":"5d770eb735a75b3b4954.js","track":3,"media":"../assets/media/b950653b5da0aa28fdaae1b0b46f0bdc98850893b03426600bc1e3f8bb35b71e.mp3"}],"../assets/media/6ff7235b7cb110754cda7d6fe39464fd3fcc10fc03108b7ab554476bb484f740.mp3":[{"id":"B2_U02_T2.1_SHORT_S05_v01","audioId":"B2_U02_T2.1_SHORT_S05_v01","title":"Book 2 · Unit 2 · H2 · 听力材料 5","subtitle":"H2 · S05","duration":86.296576,"cues":[{"start":0,"end":2.21,"text":"Reporter 2: Today, I am talking with Yuki.","coverage":0.625},{"start":3.2,"end":8.26,"text":"She sells food during the Cherry Blossom Festival in Ueno Park in Tokyo.","coverage":0.923},{"start":8.72,"end":8.96,"text":"Hi, Yuki.","coverage":0.5},{"start":10.04,"end":10.26,"text":"Yuki: Hi.","coverage":0.5},{"start":10.82,"end":14.22,"text":"Welcome to the Cherry Blossom Festival!","coverage":1.0},{"start":15.34,"end":15.78,"text":"Reporter 2: Thanks.","coverage":0.333},{"start":16.42,"end":18.28,"text":"So, what happens here?","coverage":1.0},{"start":18.6,"end":23.81,"text":"Yuki: Well, as you can see, it’s a cherry blossom festival.","coverage":0.917},{"start":24.25,"end":28.28,"text":"It is a celebration of spring and the cherry flowers.","coverage":1.0},{"start":28.55,"end":33.09,"text":"So, it doesn’t have specific activities that people do.","coverage":1.0},{"start":33.48,"end":40.93,"text":"Instead, people come to enjoy the cherry blossoms and have a picnic under the trees.","coverage":0.933},{"start":41.32,"end":47.53,"text":"We have about a thousand trees, full of beautiful flowers.","coverage":1.0},{"start":47.96,"end":51.32,"text":"Reporter 2: Do you have many people here from other countries?","coverage":0.818},{"start":51.6,"end":51.99,"text":"Yuki: Yes.","coverage":0.5},{"start":52.38,"end":56.67,"text":"Our visitors are from all over the world.","coverage":1.0},{"start":57.08,"end":66.43,"text":"In addition to the cherry blossoms, there are lots of food stalls and people can hire a boat to go around the lake too.","coverage":0.958},{"start":66.88,"end":70.83,"text":"There are many beautiful, natural places here.","coverage":1.0},{"start":71.2,"end":81.92,"text":"Some people prefer to visit some of the park’s many museums, but I think Tokyo is one of the best places to come for the Cherry Blossom Festival.","coverage":0.931},{"start":82.2,"end":85.48,"text":"Reporter 2: Well, I hope you enjoy the rest of the event!","coverage":0.833}],"file":"5d770eb735a75b3b4954.js","track":4,"media":"../assets/media/6ff7235b7cb110754cda7d6fe39464fd3fcc10fc03108b7ab554476bb484f740.mp3"}],"../assets/media/77e65fc55b01b68e49e0a5d1acc8559a2fb0d0bfd11198e9585cde39063775f9.mp3":[{"id":"B2_U02_T2.1_SHORT_S06_v01","audioId":"B2_U02_T2.1_SHORT_S06_v01","title":"Book 2 · Unit 2 · H2 · 听力材料 6","subtitle":"H2 · S06","duration":102.105556,"cues":[{"start":0.86,"end":11.71,"text":"Reporter 1: Visiting such festivals is not just for entertainment; it’s also a fantastic way to find out about the culture of a different country.","coverage":0.885},{"start":12.0,"end":17.52,"text":"I went to Oman in the Middle East recently to do just that.","coverage":1.0},{"start":18.0,"end":23.92,"text":"I’m here in Muscat at the festival of culture and heritage, talking to Nasrra.","coverage":0.867},{"start":25.0,"end":29.63,"text":"She is visiting the festival, Muscat Nights, with her family.","coverage":0.9},{"start":30.0,"end":39.68,"text":"The event is held in January and February each year in Oman, and Nasrra has been coming for the last couple of years.","coverage":0.957},{"start":40.0,"end":40.33,"text":"Hi, Nasrra.","coverage":0.5},{"start":42.0,"end":43.68,"text":"Are you enjoying the festival?","coverage":1.0},{"start":44.0,"end":44.5,"text":"Nasrra: Yes!","coverage":0.5},{"start":45.03,"end":47.3,"text":"It’s wonderful!","coverage":1.0},{"start":48.0,"end":50.59,"text":"Reporter 1: Can you tell us something about the festival?","coverage":0.8},{"start":51.0,"end":51.58,"text":"Nasrra: Of course.","coverage":0.667},{"start":51.82,"end":56.43,"text":"It’s a chance for people to learn about the heritage and culture of Oman.","coverage":1.0},{"start":57.0,"end":59.54,"text":"Reporter 1: So, why are you here?","coverage":0.714},{"start":60.0,"end":66.68,"text":"Nasrra: My mother and father want to watch some of the sports; there was basketball last year and also a car race.","coverage":0.955},{"start":67.0,"end":69.79,"text":"You can listen to traditional music.","coverage":1.0},{"start":70.0,"end":72.43,"text":"But I decided to go to the fashion show.","coverage":1.0},{"start":73.0,"end":74.65,"text":"Reporter 1: That sounds great.","coverage":0.6},{"start":75.57,"end":75.65,"text":"Nasrra: Yeah.","coverage":0.5},{"start":76.03,"end":81.59,"text":"And after we finish watching the races and shows, we’ll go and eat some traditional food.","coverage":1.0},{"start":82.69,"end":83.62,"text":"Reporter 1: Sounds amazing!","coverage":0.5},{"start":84.0,"end":86.6,"text":"I hope you all have a great time.","coverage":1.0},{"start":87.0,"end":96.68,"text":"So these international festivals, with lots of music, food and fashion, are providing a different type of experience for people.","coverage":1.0},{"start":97.0,"end":100.0,"text":"Next week, we’ll be looking at …","coverage":1.0}],"file":"5d770eb735a75b3b4954.js","track":5,"media":"../assets/media/77e65fc55b01b68e49e0a5d1acc8559a2fb0d0bfd11198e9585cde39063775f9.mp3"}],"../assets/media/6a9aa67cef0de9d5c10b0d8f56745a92ca7ac66f946cf2fbe2e4866e82e96d39.wav":[{"id":"B2_U01_T1.3_LONG_L01_v01","audioId":"B2_U01_T1.3_LONG_L01_v01","title":"Book 2 · Unit 1 · 课后听力材料","subtitle":"Homework listening material","duration":115.30555555555556,"cues":[{"start":0.2,"end":4.46,"text":"OK, everyone.","coverage":1.0},{"start":5.24,"end":8.79,"text":"Today we are talking about interesting places.","coverage":1.0},{"start":9.49,"end":16.03,"text":"I’d like to talk about the city of Vancouver, in British Columbia, Canada.","coverage":1.0},{"start":16.4,"end":20.8,"text":"It’s one of the most beautiful cities in the world.","coverage":1.0},{"start":21.88,"end":28.5,"text":"We often think cities are urban areas, with traffic and modern buildings.","coverage":1.0},{"start":29.03,"end":34.15,"text":"We don’t usually think cities have woods, lakes and fields.","coverage":1.0},{"start":34.86,"end":44.42,"text":"But Vancouver is a ‘green city’ – a place that’s good to live in because it has clean air, water and land.","coverage":1.0},{"start":45.08,"end":51.23,"text":"Vancouver has the best parts of green forests and city life.","coverage":1.0},{"start":51.72,"end":63.53,"text":"I would like to talk about some of the history of Vancouver as well as some of the advantages and disadvantages of this ‘green’ city.","coverage":1.0},{"start":64.07,"end":78.09,"text":"Vancouver originally was a place where the native people of the area lived and traded for thousands of years before Europeans came to live there in the 1800s.","coverage":1.0},{"start":78.63,"end":92.16,"text":"Then in 1886, at the first city meeting, the people of Vancouver asked the national government to give the city 1,000 acres to use as a park.","coverage":0.929},{"start":92.58,"end":99.27,"text":"They got the land from the government and started Stanley Park.","coverage":1.0},{"start":99.8,"end":108.02,"text":"This was the start of Vancouver becoming a green city with many parks and beautiful views.","coverage":1.0},{"start":108.64,"end":114.64,"text":"But being a green city with lots of parks has both advantages and disadvantages.","coverage":0.929}],"file":"5dd1b2bc9c7a14bbd832.js","track":0,"media":"../assets/media/6a9aa67cef0de9d5c10b0d8f56745a92ca7ac66f946cf2fbe2e4866e82e96d39.wav"}],"../assets/media/0f07dba2d0fe6120bc2da715b59530f03caee2ab992200463cb534e3e31c92b0.wav":[{"id":"B3_U06_T6.1_SHORT_S02_v01","audioId":"B3_U06_T6.1_SHORT_S02_v01","title":"Book 3 · Unit 6 · H2 · 听力材料 2","subtitle":"H2 · 6.1-S02","duration":30.28891156462585,"cues":[{"start":0,"end":4.86,"text":"In the same room, you’ll find early examples of glasses.","coverage":1.0},{"start":6.92,"end":10.62,"text":"Glasses were invented in Italy in the thirteenth century.","coverage":0.778},{"start":10.96,"end":13.51,"text":"No one knows who invented them.","coverage":1.0},{"start":13.88,"end":20.25,"text":"The first glasses were held in front of the eyes or balanced on the nose.","coverage":1.0},{"start":20.72,"end":25.36,"text":"They were developed to help people with bad vision to read.","coverage":1.0},{"start":25.72,"end":29.36,"text":"But let’s now move on to some other inventions.","coverage":1.0}],"file":"6267aca846456154d8d1.js","track":1,"media":"../assets/media/0f07dba2d0fe6120bc2da715b59530f03caee2ab992200463cb534e3e31c92b0.wav"}],"../assets/media/9790b567e8a2aa09553ab1f1398e788068c07338ab9f18b5dc0edae12b2b9f03.mp3":[{"id":"B3_U06_T6.1_SHORT_S03_v01","audioId":"B3_U06_T6.1_SHORT_S03_v01","title":"Book 3 · Unit 6 · H2 · 听力材料 3","subtitle":"H2 · 6.1-S03","duration":71.119433,"cues":[{"start":0.03,"end":8.29,"text":"In rooms 12A and 12B we have works by the great medieval engineer, al-Jazari.","coverage":0.941},{"start":10.03,"end":13.66,"text":"Al-Jazari lived in twelfth-century Turkey.","coverage":0.714},{"start":14.03,"end":28.63,"text":"His work The Book of Knowledge of Ingenious Mechanical Devices lists one hundred different machines with instructions and diagrams explaining how to build them.","coverage":0.875},{"start":29.03,"end":36.01,"text":"In this exhibition, you can see models of some of the devices which were designed by al-Jazari.","coverage":0.944},{"start":37.03,"end":40.64,"text":"Here, you can see his mechanical clocks.","coverage":1.0},{"start":41.62,"end":45.53,"text":"Water and weights make the clocks work.","coverage":1.0},{"start":46.62,"end":49.65,"text":"However, his most important invention was the crankshaft.","coverage":0.875},{"start":51.03,"end":58.55,"text":"The crankshaft is a long arm which allows machines to move in a straight line.","coverage":0.933},{"start":59.03,"end":64.6,"text":"It was first used for watering gardens and fields on farms.","coverage":1.0},{"start":65.03,"end":70.57,"text":"In more modern times, a crankshaft is used in car engines.","coverage":0.909}],"file":"6267aca846456154d8d1.js","track":2,"media":"../assets/media/9790b567e8a2aa09553ab1f1398e788068c07338ab9f18b5dc0edae12b2b9f03.mp3"}],"../assets/media/837bfc7840df969026c705bdbee8876006d2e7f1e7916f4358c4eb7558f238b2.mp3":[{"id":"B3_U06_T6.1_SHORT_S04_v01","audioId":"B3_U06_T6.1_SHORT_S04_v01","title":"Book 3 · Unit 6 · H2 · 听力材料 4","subtitle":"H2 · 6.1-S04","duration":86.450839,"cues":[{"start":0,"end":6.62,"text":"As we move along, you’ll find one of the most important inventions of medieval times.","coverage":1.0},{"start":7.52,"end":14.1,"text":"This invention has changed the history of the world in ways that we can’t even imagine.","coverage":1.0},{"start":14.56,"end":20.68,"text":"It’s one of the four great inventions of Chinese culture: gunpowder.","coverage":0.917},{"start":23.4,"end":34.06,"text":"Gunpowder was invented in the ninth century by Chinese scientists who were trying to create a powder which would make you live forever.","coverage":0.913},{"start":34.48,"end":43.68,"text":"They weren’t successful, of course, but their attempts led to the invention of fireworks and weapons.","coverage":1.0},{"start":44.28,"end":55.71,"text":"The first instructions on how to make gunpowder were written in the eleventh century by Zeng Gongliang, Ding Du and Yang Weide.","coverage":0.773},{"start":57.2,"end":62.71,"text":"The invention of gunpowder has changed the way we fight wars.","coverage":0.909},{"start":63.12,"end":71.24,"text":"It changed the outcome of many medieval battles and affected the history of the world.","coverage":1.0},{"start":71.64,"end":78.24,"text":"Many people think gunpowder is the most important invention in history.","coverage":0.909},{"start":78.64,"end":84.25,"text":"Now, let’s move to the next room, which is all about medieval medicine …","coverage":1.0}],"file":"6267aca846456154d8d1.js","track":3,"media":"../assets/media/837bfc7840df969026c705bdbee8876006d2e7f1e7916f4358c4eb7558f238b2.mp3"}],"../assets/media/d5716d75f821d420131837701f5f101eb075fc216aa32e0ebf87ac05186cb63f.mp3":[{"id":"B3_U06_T6.5_SHORT_S01_v01","audioId":"B3_U06_T6.5_SHORT_S01_v01","title":"Book 3 · Unit 6 · H2 · 听力材料 5","subtitle":"H2 · 6.5-S01","duration":92.004331,"cues":[{"start":0.17,"end":6.0,"text":"Woman: I’d like to start by talking a little bit about the first apps.","coverage":0.933},{"start":7.52,"end":10.01,"text":"These were included with each smartphone.","coverage":1.0},{"start":10.52,"end":18.84,"text":"These types of apps were placed in the phones to help users access the internet, check emails, send texts and so on.","coverage":1.0},{"start":19.48,"end":26.37,"text":"The first apps were designed to increase efficiency at work and allow people to access important information.","coverage":1.0},{"start":26.85,"end":32.94,"text":"However, it was the second generation of apps that really changed things.","coverage":1.0},{"start":33.56,"end":35.83,"text":"These were downloadable apps.","coverage":1.0},{"start":36.4,"end":41.26,"text":"Users simply downloaded apps from the internet and installed them on their phones.","coverage":1.0},{"start":41.88,"end":47.43,"text":"Since its introduction, the app market has grown far beyond anyone’s expectations.","coverage":1.0},{"start":48.04,"end":51.96,"text":"The first app store was opened in 2008.","coverage":1.0},{"start":52.47,"end":61.83,"text":"By 2011, it was reporting over 10 billion downloads and people were using apps more than internet browsers on their phones.","coverage":1.0},{"start":62.36,"end":68.47,"text":"And by 2017, an estimated 180 billion apps had been downloaded.","coverage":1.0},{"start":69.56,"end":78.87,"text":"These numbers have been growing ever since and they give us a good idea about how popular apps are and how quickly they’ve developed.","coverage":1.0},{"start":79.52,"end":85.34,"text":"People from all over the world use apps for entertainment, travel and communication.","coverage":1.0},{"start":85.9,"end":91.02,"text":"So, I’m going to briefly talk about how these apps have changed our lives.","coverage":1.0}],"file":"6267aca846456154d8d1.js","track":4,"media":"../assets/media/d5716d75f821d420131837701f5f101eb075fc216aa32e0ebf87ac05186cb63f.mp3"}],"../assets/media/0577b413743c66389a626a604a66c11554baa86a728f5cf4e1fc4d664c55be0e.mp3":[{"id":"B3_U06_T6.5_SHORT_S02_v01","audioId":"B3_U06_T6.5_SHORT_S02_v01","title":"Book 3 · Unit 6 · H2 · 听力材料 6","subtitle":"H2 · 6.5-S02","duration":85.042698,"cues":[{"start":0,"end":9.17,"text":"It’s hard to imagine life before smartphones and mobile phone apps – or, for those of us who are old enough, to remember it.","coverage":1.0},{"start":9.38,"end":12.72,"text":"But let’s go ahead and make an attempt anyway.","coverage":1.0},{"start":13.08,"end":19.14,"text":"So, imagine for a moment that you’re taking a road trip in the days before smartphones.","coverage":1.0},{"start":19.52,"end":26.99,"text":"Weeks before the trip, you go to the bookstore or library to get some guidebooks about the places you’re going to visit.","coverage":0.957},{"start":27.28,"end":33.65,"text":"A few days before you leave, you get some audio books to entertain you during the long trip.","coverage":0.889},{"start":34.24,"end":39.67,"text":"You go to a shop and buy some maps – yes, the paper kind.","coverage":1.0},{"start":40.16,"end":47.16,"text":"The day before the trip, you sit down at your computer and look up the directions and print them out.","coverage":1.0},{"start":47.52,"end":51.87,"text":"Then, you pack some of your favourite CDs to bring along.","coverage":0.909},{"start":52.2,"end":57.3,"text":"You also pack your camera – and your torch, in case your car breaks down.","coverage":1.0},{"start":57.68,"end":66.12,"text":"And you write down some phone numbers and addresses – of the friends you’ll be visiting and the hotels where you’ll be staying.","coverage":1.0},{"start":66.52,"end":72.2,"text":"While you’re driving, your passenger reads the directions to you and looks for street signs.","coverage":1.0},{"start":72.64,"end":77.36,"text":"If you get lost, you stop at a petrol station to ask for directions.","coverage":1.0},{"start":77.88,"end":80.7,"text":"You have to write them down on a piece of paper.","coverage":1.0},{"start":81.73,"end":84.35,"text":"OK, so I think you get the idea.","coverage":0.875}],"file":"6267aca846456154d8d1.js","track":5,"media":"../assets/media/0577b413743c66389a626a604a66c11554baa86a728f5cf4e1fc4d664c55be0e.mp3"}],"../assets/media/38b7eb07c916f8ce9596a36822904d696acde79de4073a9939bd30aa21e85507.mp3":[{"id":"B3_U06_T6.5_SHORT_S03_v01","audioId":"B3_U06_T6.5_SHORT_S03_v01","title":"Book 3 · Unit 6 · H2 · 听力材料 7","subtitle":"H2 · 6.5-S03","duration":64.588821,"cues":[{"start":0,"end":3.96,"text":"Now let’s make a comparison with the same trip today.","coverage":1.0},{"start":4.78,"end":15.56,"text":"No books, no maps, no CDs, no lists of phone numbers, no friend giving you directions – the smartphone does it all!","coverage":1.0},{"start":16.39,"end":19.38,"text":"Think of the apps you’d use just for that one trip.","coverage":1.0},{"start":19.72,"end":23.25,"text":"You’d read reviews and book your hotel with a travel app.","coverage":1.0},{"start":23.56,"end":29.02,"text":"The GPS would replace the directions and maps and your friend in the front seat.","coverage":1.0},{"start":29.44,"end":35.56,"text":"Of course, a music app would replace the CDs and you could listen to podcasts, as well as audio books.","coverage":0.9},{"start":37.24,"end":41.17,"text":"And, of course, you wouldn’t need to bring a camera or a torch.","coverage":1.0},{"start":41.6,"end":47.74,"text":"Yes, we’ve certainly made a lot of progress since the pre-smartphone days!","coverage":0.929},{"start":48.16,"end":53.62,"text":"So, now I’d like to mention another important effect of the invention of apps.","coverage":1.0},{"start":54.04,"end":57.94,"text":"It has created a whole new IT sector.","coverage":1.0},{"start":58.4,"end":63.99,"text":"It is one of the fastest-growing industries and there is a great need for skilled software engineers.","coverage":1.0}],"file":"6267aca846456154d8d1.js","track":6,"media":"../assets/media/38b7eb07c916f8ce9596a36822904d696acde79de4073a9939bd30aa21e85507.mp3"}],"../assets/media/575927737d790f185035ee0234a95d5d4051cdb8a72b234be47d3ed79de80ee1.mp3":[{"id":"B3_U06_T6.5_SHORT_S04_v01","audioId":"B3_U06_T6.5_SHORT_S04_v01","title":"Book 3 · Unit 6 · H2 · 听力材料 8","subtitle":"H2 · 6.5-S04","duration":43.876236,"cues":[{"start":0.25,"end":2.96,"text":"But apps have also had some negative effects.","coverage":1.0},{"start":3.53,"end":10.01,"text":"For one thing, people have become more helpless because they’re so dependent on their phones for information.","coverage":1.0},{"start":10.55,"end":18.26,"text":"For example, if they’re in a place with no phone signal, they’re not very good at asking for and following directions.","coverage":1.0},{"start":18.74,"end":24.05,"text":"And apps have made people less patient because they expect to have information immediately.","coverage":1.0},{"start":24.77,"end":34.02,"text":"In fact, a recent study found that 87 percent of smartphone users leave a web page if it doesn’t load in 2 two seconds.","coverage":0.84},{"start":35.9,"end":41.15,"text":"OK, in the next part of the lecture, I’ll discuss some of the most common apps in more detail …","coverage":0.9}],"file":"6267aca846456154d8d1.js","track":7,"media":"../assets/media/575927737d790f185035ee0234a95d5d4051cdb8a72b234be47d3ed79de80ee1.mp3"}],"../assets/media/d03378d2ce6264fc09340a9807bf5ddb3bdb18eab63cfbca14309bd008cc5b01.mp3":[{"id":"PPT_d03378d2ce6264fc","audioId":"PPT_d03378d2ce6264fc","title":"Book 2 · Unit 5 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 90","duration":293.8,"cues":[{"start":0.0,"end":1.0,"text":"five .five","coverage":1.0},{"start":3.44,"end":8.34,"text":"Andre, I know you played in a university football team in the US,","coverage":1.0},{"start":8.76,"end":11.74,"text":"so I'd like to ask your opinion about something.","coverage":1.0},{"start":12.7,"end":18.44,"text":"Do you think the Olympic athletes and other athletes, like football and tennis players,","coverage":1.0},{"start":18.96,"end":21.7,"text":"are too focused on getting money from companies?","coverage":1.0},{"start":22.34,"end":24.38,"text":"I went on holiday in","coverage":1.0},{"start":25.24,"end":28.02,"text":"and every time I turned on the TV,","coverage":1.0},{"start":28.44,"end":31.86,"text":"I saw a famous athlete in an advert for some product.","coverage":1.0},{"start":33.14,"end":37.46,"text":"Those athletes are getting paid a huge amount of money to be in adverts.","coverage":1.0},{"start":38.32,"end":44.1,"text":"It seems like the athletes are more interested in making money than in representing their countries.","coverage":1.0},{"start":45.32,"end":50.6,"text":"I think there is definitely more marketing and business in sport than ever before.","coverage":1.0},{"start":51.5,"end":52.56,"text":"As a long -time","coverage":1.0},{"start":53.12,"end":61.56,"text":"I really think all this money and advertising from big companies is taking something away from sports and competitions.","coverage":1.0},{"start":62.54,"end":64.96,"text":"Well, I would say that all athletes,","coverage":1.0},{"start":65.38,"end":69.66,"text":"even the rich and famous ones, are still very focused on the sport.","coverage":1.0},{"start":70.44,"end":71.42,"text":"Without the sport,","coverage":1.0},{"start":71.8,"end":72.22,"text":"they have","coverage":1.0},{"start":72.22,"end":72.44,"text":"no","coverage":1.0},{"start":72.44,"end":72.86,"text":"job.","coverage":1.0},{"start":73.78,"end":78.0,"text":"And athletes who aren't famous, or are only a little famous,","coverage":1.0},{"start":78.7,"end":80.66,"text":"deserve to make all the money they can.","coverage":1.0},{"start":81.36,"end":84.48,"text":"Many athletes devote their whole lives to training.","coverage":1.0},{"start":85.24,"end":89.18,"text":"How can they live, work, and pay for coaching all by themselves?","coverage":1.0},{"start":90.46,"end":91.44,"text":"Being an athlete,","coverage":1.0},{"start":91.98,"end":93.92,"text":"especially one who doesn't get paid,","coverage":1.0},{"start":94.34,"end":95.94,"text":"is extremely expensive.","coverage":1.0},{"start":96.8,"end":99.08,"text":"The cost of training is really high,","coverage":1.0},{"start":99.5,"end":103.58,"text":"and athletes need to spend a lot of time training to be good at a sport.","coverage":1.0},{"start":104.98,"end":111.08,"text":"So big companies might give money to sports teams and individual athletes to help them train.","coverage":1.0},{"start":111.78,"end":113.26,"text":"In some competitions,","coverage":1.0},{"start":113.64,"end":114.46,"text":"like the Olympics,","coverage":1.0},{"start":115.02,"end":118.06,"text":"there are both professional players and amateurs,","coverage":1.0},{"start":118.76,"end":123.32,"text":"you know, people who do the sport as a hobby and not as a job.","coverage":1.0},{"start":124.24,"end":127.2,"text":"I think both should be able to get support from companies.","coverage":1.0},{"start":128.22,"end":129.5,"text":"Look at Maria Sakary.","coverage":1.0},{"start":130.32,"end":137.7,"text":"She's a Greek tennis player who is paid money by a clothing company to wear their clothes and be in their adverts.","coverage":1.0},{"start":138.6,"end":140.24,"text":"Other companies support her too.","coverage":1.0},{"start":140.24,"end":142.74,"text":"Without all the help from companies,","coverage":1.0},{"start":143.18,"end":147.02,"text":"she might not have enough money to play tennis as her job.","coverage":1.0},{"start":147.92,"end":152.42,"text":"Having that time and money allows her to be such a good tennis player.","coverage":1.0},{"start":153.28,"end":156.38,"text":"But when a big company pays a team or an athlete,","coverage":1.0},{"start":156.92,"end":159.72,"text":"it makes them wear the company name and designs,","coverage":1.0},{"start":160.16,"end":162.06,"text":"and they sign contracts.","coverage":1.0},{"start":162.86,"end":166.44,"text":"Isn't that really like being an employee and working for a company?","coverage":1.0},{"start":167.14,"end":171.0,"text":"To me, these athletes work in advertising and marketing.","coverage":1.0},{"start":172.04,"end":173.04,"text":"You have a point,","coverage":1.0},{"start":173.7,"end":176.1,"text":"but if the athletes don't get good coaching,","coverage":1.0},{"start":176.64,"end":180.34,"text":"they might not score a lot of points and do well in competitions.","coverage":1.0},{"start":181.16,"end":182.18,"text":"If that happens,","coverage":1.0},{"start":182.6,"end":187.06,"text":"they can lose their chance to make a lot of money after the competitions are over.","coverage":1.0},{"start":187.82,"end":188.6,"text":"And actually,","coverage":1.0},{"start":189.1,"end":194.68,"text":"only about five % of Olympic athletes get money from companies to be in adverts.","coverage":1.0},{"start":195.74,"end":197.24,"text":"That doesn't sound fair.","coverage":1.0},{"start":198.02,"end":201.2,"text":"Shouldn't countries pay their own athletes a salary to train?","coverage":1.0},{"start":202.26,"end":204.68,"text":"After all, they do represent the countries.","coverage":1.0},{"start":205.66,"end":210.94,"text":"I read that in the UK, the government pays the country's Olympic athletes to train,","coverage":1.0},{"start":211.3,"end":214.32,"text":"so there is less pressure there to get money from a company.","coverage":1.0},{"start":215.44,"end":216.02,"text":"Also,","coverage":1.0},{"start":216.4,"end":221.44,"text":"there are prizes for all the competitions, and sometimes that gives them extra money.","coverage":1.0},{"start":222.38,"end":222.82,"text":"Well,","coverage":1.0},{"start":223.32,"end":226.76,"text":"a lot of countries can't pay the costs for training athletes.","coverage":1.0},{"start":227.56,"end":228.32,"text":"And of course,","coverage":1.0},{"start":228.74,"end":232.72,"text":"the countries with lots of money can train their athletes very well.","coverage":1.0},{"start":233.52,"end":235.86,"text":"If companies are supporting lots of athletes,","coverage":1.0},{"start":236.5,"end":239.04,"text":"more people can participate in competitions.","coverage":1.0},{"start":240.28,"end":245.78,"text":"Still, I think all this money takes something away from the Olympics and other sporting events.","coverage":1.0},{"start":246.96,"end":249.54,"text":"We see adverts almost everywhere.","coverage":1.0},{"start":250.34,"end":255.78,"text":"But being in an advert is a great opportunity for the athlete and the business.","coverage":1.0},{"start":256.56,"end":266.28,"text":"If an athlete lets his or her face be on a cereal box or wears some clothing with a company's name on it, people will probably buy the product.","coverage":1.0},{"start":266.88,"end":268.44,"text":"So it's good for the company,","coverage":1.0},{"start":268.92,"end":271.1,"text":"and the athlete gets more money to train.","coverage":1.0},{"start":272.1,"end":280.98,"text":"I also think that all the adverts at big competitions like the Olympics or the World Cup help lower the ticket prices for fans,","coverage":1.0},{"start":281.56,"end":284.12,"text":"so the competitions don't have to charge so much.","coverage":1.0},{"start":284.98,"end":286.18,"text":"It's good for everyone.","coverage":1.0},{"start":287.22,"end":287.74,"text":"Hmm,","coverage":1.0},{"start":288.56,"end":291.94,"text":"I'm not sure if I agree with you, but I understand your point.","coverage":1.0}],"file":"64ea1af6d6d04e42e0b1.js","track":0,"media":"../assets/media/d03378d2ce6264fc09340a9807bf5ddb3bdb18eab63cfbca14309bd008cc5b01.mp3"}],"../assets/media/979b6c25372554f2d7cb1e3ef5a1b49c9c451ced979b1288a5482b87483a1598.mp3":[{"id":"PPT_979b6c25372554f2","audioId":"PPT_979b6c25372554f2","title":"Book 3 · Unit 8 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 81","duration":43.81,"cues":[{"start":0.0,"end":1.5,"text":"eight .four","coverage":1.0},{"start":2.16,"end":3.08,"text":"Part one","coverage":1.0},{"start":3.92,"end":13.02,"text":"In today's programme we discuss the recent decision made by several universities to give students money in return for good grades.","coverage":1.0},{"start":13.84,"end":18.32,"text":"Students will be paid by the hour to take additional maths and science classes.","coverage":1.0},{"start":18.98,"end":25.86,"text":"The students who improve their grades and keep their grade average high will be given cash rewards at the end of each term.","coverage":1.0},{"start":25.86,"end":35.06,"text":"To discuss this new project we have invited education expert Dr Michael Burns and we welcome your calls during the programme.","coverage":1.0},{"start":35.96,"end":37.42,"text":"We'd like to hear your opinion.","coverage":1.0},{"start":37.98,"end":41.78,"text":"Do you think university students should be paid for good grades?","coverage":1.0}],"file":"675629a417a5b7ba0ca6.js","track":0,"media":"../assets/media/979b6c25372554f2d7cb1e3ef5a1b49c9c451ced979b1288a5482b87483a1598.mp3"}],"../assets/media/6df260469933fec0162dbb49200de0d6d8d2924c93468c5c499ff32edc7666d6.wav":[{"id":"B2_U01_T1.3_LONG_L03_v01","audioId":"B2_U01_T1.3_LONG_L03_v01","title":"Book 2 · Unit 1 · 课后听力材料","subtitle":"Homework listening material","duration":110.60303854875283,"cues":[{"start":0,"end":5.57,"text":"I’d also like to talk about some disadvantages of parks in Vancouver.","coverage":1.0},{"start":7.08,"end":9.9,"text":"Space in a city is very important.","coverage":1.0},{"start":10.19,"end":17.96,"text":"Having many parks means that people have less space to build houses and apartments.","coverage":1.0},{"start":18.48,"end":26.07,"text":"Because Vancouver is located between the mountains and the ocean, there’s not much room for new buildings.","coverage":1.0},{"start":26.39,"end":29.6,"text":"This makes Vancouver an expensive city.","coverage":1.0},{"start":30.73,"end":36.72,"text":"Also, when you have a beautiful place to live, a lot of people want to go there.","coverage":1.0},{"start":37.04,"end":39.48,"text":"This makes the city crowded.","coverage":1.0},{"start":39.94,"end":43.78,"text":"Actually, Vancouver has very bad traffic.","coverage":1.0},{"start":44.13,"end":52.47,"text":"Lastly, when you have a lot of parks, wild animals in the parks can sometimes be a problem.","coverage":1.0},{"start":52.78,"end":59.96,"text":"For example, Stanley Park gives information to people about what to do if they see a coyote.","coverage":0.941},{"start":61.04,"end":66.08,"text":"In my opinion, having coyotes in a city park is bad.","coverage":0.909},{"start":66.8,"end":79.57,"text":"Finally, while I think these disadvantages might mean that some people would not want to visit Vancouver, I personally feel that most people would enjoy Vancouver.","coverage":1.0},{"start":79.89,"end":88.99,"text":"In my opinion, being close to nature and having a healthy city are worth paying a little more money for.","coverage":1.0},{"start":89.6,"end":98.47,"text":"And a lot of people agree with this idea because Vancouver is a very popular place to visit and live in.","coverage":1.0},{"start":99.12,"end":108.02,"text":"So I would recommend that people visit Vancouver and enjoy the many parks, the clean, healthy city and the interesting sights.","coverage":0.952}],"file":"67e564ea4236bf80abf2.js","track":0,"media":"../assets/media/6df260469933fec0162dbb49200de0d6d8d2924c93468c5c499ff32edc7666d6.wav"}],"../assets/media/fe74950e306c8aee4fc4cdf2292bbfb13475c3405bcbcb4c61cdbbb4357f690d.mp3":[{"id":"PPT_fe74950e306c8aee","audioId":"PPT_fe74950e306c8aee","title":"Book 2 · Unit 4 · RW · READING 2","subtitle":"READING 2 · source slide 105","duration":208.77,"cues":[{"start":0.0,"end":6.36,"text":"Surviving the Sea of Sand How to stay alive in the Sahara Desert,","coverage":1.0},{"start":6.74,"end":13.32,"text":"Yuen Bar Can you imagine a sea of sand three times bigger than India?","coverage":1.0},{"start":14.36,"end":16.28,"text":"This is the Sahara Desert,","coverage":1.0},{"start":16.7,"end":19.4,"text":"the largest hot desert in the world.","coverage":1.0},{"start":20.04,"end":26.38,"text":"It covers 11 countries in North Africa and is over nine million square kilometers.","coverage":1.0},{"start":26.38,"end":30.28,"text":"That's more than 25 % of Africa.","coverage":1.0},{"start":31.3,"end":32.4,"text":"In the Sahara,","coverage":1.0},{"start":32.86,"end":36.02,"text":"temperatures are very different during the day and at night.","coverage":1.0},{"start":36.62,"end":39.72,"text":"It is much hotter during the day than at night.","coverage":1.0},{"start":40.46,"end":41.32,"text":"During the day,","coverage":1.0},{"start":41.74,"end":44.1,"text":"the hottest time is between two p .m.","coverage":1.0},{"start":44.22,"end":45.42,"text":"and four p .m.","coverage":1.0},{"start":45.44,"end":48.54,"text":"when temperatures rise to 33 degrees centigrade.","coverage":1.0},{"start":49.24,"end":51.64,"text":"But it is very cold at night.","coverage":1.0},{"start":51.64,"end":54.74,"text":"The coldest time is at four a .m.","coverage":1.0},{"start":55.0,"end":58.38,"text":"when temperatures fall to minus one degree centigrade.","coverage":1.0},{"start":59.66,"end":61.86,"text":"Though not the driest place in the world,","coverage":1.0},{"start":62.28,"end":64.3,"text":"the Sahara is very dry.","coverage":1.0},{"start":65.02,"end":69.06,"text":"The average precipitation in a year is only 70 millimeters.","coverage":1.0},{"start":70.46,"end":73.54,"text":"Because of the extreme temperatures in the desert,","coverage":1.0},{"start":74.14,"end":77.0,"text":"it is a very difficult place to survive.","coverage":1.0},{"start":78.08,"end":79.18,"text":"Marco Rivera,","coverage":1.0},{"start":79.56,"end":80.68,"text":"our survival expert,","coverage":1.0},{"start":81.0,"end":81.88,"text":"has some tips.","coverage":1.0},{"start":83.2,"end":85.3,"text":"Take warm clothes and a blanket.","coverage":1.0},{"start":86.08,"end":87.16,"text":"You will need a hat,","coverage":1.0},{"start":87.64,"end":88.42,"text":"long trousers,","coverage":1.0},{"start":88.82,"end":91.28,"text":"and a woolen jumper to keep you warm at night.","coverage":1.0},{"start":92.04,"end":95.66,"text":"During the day, cover your body, head, and face.","coverage":1.0},{"start":96.32,"end":100.28,"text":"Clothes protect you from the sun and keep water in your body.","coverage":1.0},{"start":100.98,"end":103.6,"text":"You will also need a warm blanket at night.","coverage":1.0},{"start":104.02,"end":106.18,"text":"It can get cold very quickly.","coverage":1.0},{"start":106.18,"end":108.2,"text":"When the temperature drops,","coverage":1.0},{"start":108.7,"end":111.78,"text":"it can be a shock and make you feel even colder.","coverage":1.0},{"start":113.38,"end":117.3,"text":"A car is easier to see than a person walking in the desert.","coverage":1.0},{"start":118.06,"end":123.26,"text":"You can also use the mirrors from your car to signal to planes and other cars.","coverage":1.0},{"start":124.18,"end":126.44,"text":"You can use your car tires to make a fire.","coverage":1.0},{"start":127.0,"end":128.76,"text":"A fire is easy to see.","coverage":1.0},{"start":129.36,"end":132.82,"text":"It will help people find you and it will keep you warm at night.","coverage":1.0},{"start":133.58,"end":137.08,"text":"Try to drink some water at least once every hour.","coverage":1.0},{"start":137.82,"end":141.24,"text":"You need your water to last as long as possible.","coverage":1.0},{"start":141.92,"end":143.72,"text":"Drink only what you need.","coverage":1.0},{"start":144.48,"end":147.66,"text":"When you talk, you lose water from your body.","coverage":1.0},{"start":148.42,"end":150.96,"text":"Keep your mouth closed and do not talk.","coverage":1.0},{"start":152.28,"end":156.86,"text":"If you eat, you will get thirsty and drink all of your water more quickly.","coverage":1.0},{"start":157.48,"end":162.2,"text":"You can eat a little but only to stop you from feeling very hungry.","coverage":1.0},{"start":162.82,"end":167.32,"text":"Eat very small amounts of food and eat very slowly.","coverage":1.0},{"start":168.3,"end":170.16,"text":"You can live for three weeks with","coverage":1.0},{"start":170.16,"end":170.46,"text":"no","coverage":1.0},{"start":170.46,"end":170.9,"text":"food,","coverage":1.0},{"start":171.42,"end":174.68,"text":"but you can only live for three days without water.","coverage":1.0},{"start":175.92,"end":179.78,"text":"It is very important to stay out of the sun during the day.","coverage":1.0},{"start":180.46,"end":183.48,"text":"Make a hole under your car and lie there.","coverage":1.0},{"start":184.16,"end":186.76,"text":"This will keep you cool and help you sleep.","coverage":1.0},{"start":187.84,"end":189.98,"text":"Find a warm place to sleep at night.","coverage":1.0},{"start":189.98,"end":193.8,"text":"A spot near a tree or a rock will be the warmest.","coverage":1.0},{"start":194.36,"end":196.94,"text":"But be careful before you decide where to sleep.","coverage":1.0},{"start":197.86,"end":202.82,"text":"Dangerous animals like snakes and scorpions also like to sleep in these places.","coverage":1.0},{"start":203.54,"end":206.92,"text":"Look carefully for animals before you lie down.","coverage":1.0}],"file":"6867df33a219fce03b80.js","track":0,"media":"../assets/media/fe74950e306c8aee4fc4cdf2292bbfb13475c3405bcbcb4c61cdbbb4357f690d.mp3"}],"../assets/media/7dc1db1d8054118db85ae59af07d4e5d3d99b5dd66943d16470b4a7c43462eda.wav":[{"id":"B2_U08_T8.4_LONG_L01_v01","audioId":"B2_U08_T8.4_LONG_L01_v01","title":"Book 2 · Unit 8 · H3 · 听力材料 1","subtitle":"H3 · L01","duration":117.60433106575964,"cues":[{"start":2.24,"end":5.54,"text":"Host: Why is space junk a problem?","coverage":0.857},{"start":6.37,"end":19.47,"text":"Well, the pieces of space junk travel at extremely fast speeds (over 25,000 kilometres per hour) and so they can cause very bad problems if they hit anything.","coverage":0.897},{"start":20.01,"end":26.02,"text":"NASA, the US space agency, watches where the space junk is.","coverage":1.0},{"start":26.65,"end":38.38,"text":"The International Space Station (the ISS) can move out of the way of the space junk if they get a message to move at least five hours before an accident.","coverage":1.0},{"start":38.97,"end":51.36,"text":"Because people continue to send so many things into space – and this first started in 1957 – there are now over 27,000 pieces of space junk.","coverage":1.0},{"start":51.97,"end":55.72,"text":"The smaller pieces might be as tiny as a bit of paint.","coverage":1.0},{"start":55.91,"end":60.74,"text":"But most of them are larger than 10 centimetres across.","coverage":0.9},{"start":61.41,"end":66.94,"text":"These are parts of old spacecraft, broken pieces of satellites and other things.","coverage":1.0},{"start":67.93,"end":75.63,"text":"Some of this happened because of accidents in space, which can create thousands of pieces of space junk.","coverage":1.0},{"start":76.45,"end":81.37,"text":"Many people would like to find a solution to space junk if they could.","coverage":1.0},{"start":81.97,"end":92.0,"text":"Scientists worry that if large pieces of space junk hit each other, they would break and there would be more and more broken pieces of space junk.","coverage":1.0},{"start":92.53,"end":98.52,"text":"When there is too much space junk, we won’t be able to use the space around the Earth for satellites.","coverage":1.0},{"start":100.24,"end":103.92,"text":"So, what options do we have to solve the problem?","coverage":1.0},{"start":104.49,"end":112.6,"text":"The British mission RemoveDEBRIS is trying to solve the problem by catching space junk and taking it away.","coverage":0.944},{"start":113.12,"end":116.53,"text":"If all the space junk was gone, there wouldn’t be a problem anymore.","coverage":1.0}],"file":"68d3ff3880338f831539.js","track":0,"media":"../assets/media/7dc1db1d8054118db85ae59af07d4e5d3d99b5dd66943d16470b4a7c43462eda.wav"}],"../assets/media/62379e101a018bd6ea46ca08760d0b3acbbbb5eddd645901e2f647ab676155bc.wav":[{"id":"B2_U08_T8.4_LONG_L02_v01","audioId":"B2_U08_T8.4_LONG_L02_v01","title":"Book 2 · Unit 8 · H3 · 听力材料 2","subtitle":"H3 · L02","duration":65.95555555555555,"cues":[{"start":0,"end":4.64,"text":"But what about space junk falling from space?","coverage":1.0},{"start":5.06,"end":6.9,"text":"What is the danger to people?","coverage":1.0},{"start":7.18,"end":13.49,"text":"There’s not much chance anything would hit you if you were outside on a normal day.","coverage":1.0},{"start":13.88,"end":17.47,"text":"That’s because most junk burns as it falls to Earth.","coverage":1.0},{"start":17.76,"end":26.85,"text":"In 1997, one person in the US was hit by a piece of space junk and she was not hurt at all.","coverage":1.0},{"start":27.6,"end":40.0,"text":"In 2022, a large piece of space junk from a SpaceX spacecraft fell to the surface of the Earth and landed on an Australian sheep farm.","coverage":1.0},{"start":40.44,"end":47.08,"text":"From time to time, other large pieces hit the ground, usually in rural areas.","coverage":1.0},{"start":47.48,"end":55.18,"text":"These days, most space agencies work to make their old spacecraft fall in the ocean if possible.","coverage":0.941},{"start":56.21,"end":63.94,"text":"However, with tens of thousands of pieces of space junk, there might be more than rain falling from the sky.","coverage":1.0}],"file":"68d3ff3880338f831539.js","track":1,"media":"../assets/media/62379e101a018bd6ea46ca08760d0b3acbbbb5eddd645901e2f647ab676155bc.wav"}],"../assets/media/f38f5acd0115544835b2ae43002350b8894194e7a261b159e930e575ab781635.mp3":[{"id":"PPT_f38f5acd01155448","audioId":"PPT_f38f5acd01155448","title":"Book 2 · Unit 2 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 79","duration":225.31,"cues":[{"start":0.0,"end":2.48,"text":"two .four","coverage":1.0},{"start":3.0,"end":3.7,"text":"Paul,","coverage":1.0},{"start":4.14,"end":6.6,"text":"you have cousins in the US, don't you?","coverage":1.0},{"start":7.34,"end":8.44,"text":"What's your opinion?","coverage":1.0},{"start":9.28,"end":12.72,"text":"Which is the best North American holiday or celebration?","coverage":1.0},{"start":13.74,"end":14.54,"text":"Hmm.","coverage":1.0},{"start":15.04,"end":15.56,"text":"Well,","coverage":1.0},{"start":16.08,"end":20.16,"text":"I like Independence Day in the US because of the fireworks,","coverage":1.0},{"start":20.66,"end":23.62,"text":"and New Year's Eve often has fireworks too.","coverage":1.0},{"start":24.36,"end":27.22,"text":"But I think the best holiday is Thanksgiving.","coverage":1.0},{"start":27.22,"end":29.54,"text":"Why do you like Thanksgiving?","coverage":1.0},{"start":31.0,"end":33.32,"text":"Everyone has something to be thankful for,","coverage":1.0},{"start":33.88,"end":35.96,"text":"so everyone can celebrate it.","coverage":1.0},{"start":36.6,"end":39.44,"text":"Both the US and Canada celebrate it.","coverage":1.0},{"start":39.94,"end":40.4,"text":"Really?","coverage":1.0},{"start":41.08,"end":42.86,"text":"How do people celebrate it?","coverage":1.0},{"start":43.78,"end":48.7,"text":"Well, most people get together with family and friends and have a big meal.","coverage":1.0},{"start":49.58,"end":50.74,"text":"What do they eat?","coverage":1.0},{"start":50.74,"end":53.66,"text":"They usually eat a traditional meal.","coverage":1.0},{"start":54.2,"end":58.56,"text":"This is usually a delicious turkey with stuffing for the main dish.","coverage":1.0},{"start":59.34,"end":60.6,"text":"You should try it.","coverage":1.0},{"start":61.4,"end":65.68,"text":"Most traditional Thanksgiving meals have food which is from the Americas,","coverage":1.0},{"start":66.48,"end":67.68,"text":"like potatoes,","coverage":1.0},{"start":68.02,"end":69.74,"text":"corn and cranberries.","coverage":1.0},{"start":71.06,"end":73.3,"text":"For dessert they eat pumpkin pie,","coverage":1.0},{"start":73.78,"end":76.36,"text":"but some people prefer different kinds of pie,","coverage":1.0},{"start":76.8,"end":77.64,"text":"like apple.","coverage":1.0},{"start":77.64,"end":81.06,"text":"Is the food the same in both countries?","coverage":1.0},{"start":82.28,"end":85.2,"text":"Actually, there are some differences in the food.","coverage":1.0},{"start":86.02,"end":89.72,"text":"In Canada, for example, the pumpkin pie is spicy,","coverage":1.0},{"start":90.1,"end":92.2,"text":"but in the US it's sweet.","coverage":1.0},{"start":93.32,"end":96.44,"text":"I like the American style with whipped cream.","coverage":1.0},{"start":96.94,"end":98.38,"text":"You have to try it.","coverage":1.0},{"start":98.38,"end":101.44,"text":"Another dish which is different is the stuffing.","coverage":1.0},{"start":102.24,"end":110.22,"text":"For instance, in Canada stuffing is often made from rice or bread, but in the southern US it could be made from cornbread.","coverage":1.0},{"start":111.24,"end":112.46,"text":"In the eastern US,","coverage":1.0},{"start":112.9,"end":114.8,"text":"sometimes oysters are used in the stuffing.","coverage":1.0},{"start":116.14,"end":118.0,"text":"That all sounds delicious.","coverage":1.0},{"start":118.8,"end":121.72,"text":"Are there any special decorations for Thanksgiving?","coverage":1.0},{"start":122.72,"end":123.2,"text":"Well,","coverage":1.0},{"start":123.62,"end":128.58,"text":"people often decorate their dinner tables and homes with things such as colourful leaves,","coverage":1.0},{"start":128.92,"end":130.66,"text":"autumn vegetables and candles.","coverage":1.0},{"start":131.48,"end":136.1,"text":"The decorations usually have autumn colours like red, yellow and orange.","coverage":1.0},{"start":137.2,"end":140.98,"text":"Do people give gifts or do some special activities?","coverage":1.0},{"start":141.98,"end":146.92,"text":"Well, people don't really give gifts, but there are some special activities.","coverage":1.0},{"start":147.44,"end":153.42,"text":"For example, both countries celebrate with parades, with marching bands and people in costumes.","coverage":1.0},{"start":154.32,"end":157.1,"text":"It's also traditional to watch sport on TV.","coverage":1.0},{"start":158.12,"end":162.12,"text":"It sounds like the celebration is almost the same in both countries.","coverage":1.0},{"start":163.2,"end":167.4,"text":"Well, there are some differences between Canadian and American Thanksgiving.","coverage":1.0},{"start":168.62,"end":169.24,"text":"Like what?","coverage":1.0},{"start":169.24,"end":175.3,"text":"Well, for instance, in Canada the holiday is celebrated on the second Monday in October,","coverage":1.0},{"start":175.9,"end":179.18,"text":"but in the US it's on the fourth Thursday in November.","coverage":1.0},{"start":180.36,"end":185.04,"text":"Another difference is that in Canada people enjoy small local parades.","coverage":1.0},{"start":185.88,"end":193.18,"text":"In the US they have a huge parade in New York City and people all over the US watch it on TV.","coverage":1.0},{"start":193.18,"end":197.42,"text":"People in the New York parade sometimes wear costumes.","coverage":1.0},{"start":198.14,"end":202.54,"text":"One last difference is that each country has different reasons for the holiday.","coverage":1.0},{"start":203.28,"end":206.98,"text":"In Canada the holiday celebrates the autumn harvest,","coverage":1.0},{"start":207.74,"end":215.98,"text":"but Americans celebrate the autumn harvest and remembering the Native Americans helping settlers hunt and learn to grow food.","coverage":1.0},{"start":216.64,"end":219.06,"text":"That sounds like a lot of fun.","coverage":1.0},{"start":219.74,"end":223.32,"text":"I want to go to a Thanksgiving celebration in both countries.","coverage":1.0}],"file":"6908e404109047bfafbb.js","track":0,"media":"../assets/media/f38f5acd0115544835b2ae43002350b8894194e7a261b159e930e575ab781635.mp3"}],"../assets/media/11b123e08f50257b0f946a9fc3c8442a281f45bfe4244961720cedb90cd7397c.mp3":[{"id":"PPT_11b123e08f50257b","audioId":"PPT_11b123e08f50257b","title":"Book 2 · Unit 3 · RW · READING 1","subtitle":"READING 1 · source slide 58","duration":230.24,"cues":[{"start":0.0,"end":5.2,"text":"Internet Cookies The fight for your personal information","coverage":1.0},{"start":5.99,"end":12.58,"text":"Do you know how websites remember your sign -in information or just give you a personal feel?","coverage":1.0},{"start":13.2,"end":15.94,"text":"The answer is Internet Cookies.","coverage":1.0},{"start":16.42,"end":21.84,"text":"A cookie is a small piece of information that a website puts on your computer.","coverage":1.0},{"start":22.58,"end":26.24,"text":"Some cookies are needed for websites to work properly.","coverage":1.0},{"start":26.24,"end":33.02,"text":"For example, they collect and remember things about you, like what language you prefer.","coverage":1.0},{"start":34.24,"end":38.54,"text":"Other cookies are used by companies to try to sell you things.","coverage":1.0},{"start":39.8,"end":44.24,"text":"The simple job of a cookie is to record your online activities.","coverage":1.0},{"start":45.08,"end":49.6,"text":"A website owner uses a cookie called a First Party Cookie.","coverage":1.0},{"start":49.6,"end":52.3,"text":"This is a necessary cookie.","coverage":1.0},{"start":52.84,"end":57.1,"text":"It keeps you signed in and follows you as you use the website.","coverage":1.0},{"start":57.86,"end":60.24,"text":"For example, if you shop online,","coverage":1.0},{"start":60.66,"end":64.36,"text":"a cookie remembers what you put into your shopping basket.","coverage":1.0},{"start":65.06,"end":67.02,"text":"When you visit the website again,","coverage":1.0},{"start":67.48,"end":69.82,"text":"it knows that you are the same person.","coverage":1.0},{"start":70.56,"end":80.1,"text":"The website feels more personal and is quicker to use because the cookie knows the changes you made to the website when you visited it before.","coverage":1.0},{"start":81.18,"end":85.18,"text":"Some cookies belong to someone other than the website owner,","coverage":1.0},{"start":85.7,"end":87.78,"text":"usually an advertising company.","coverage":1.0},{"start":88.4,"end":90.98,"text":"These are called Third Party Cookies.","coverage":1.0},{"start":91.58,"end":94.04,"text":"People want to use free websites,","coverage":1.0},{"start":94.5,"end":99.36,"text":"so website owners make money by renting website space to companies.","coverage":1.0},{"start":100.2,"end":106.26,"text":"Third Party Cookies can follow you between websites and record your browsing history.","coverage":1.0},{"start":106.26,"end":107.92,"text":"For example,","coverage":1.0},{"start":108.24,"end":111.96,"text":"you browsed the internet one day for a new smartphone.","coverage":1.0},{"start":112.46,"end":117.04,"text":"You looked at some different websites but decided not to buy a phone.","coverage":1.0},{"start":117.56,"end":118.68,"text":"A few days later,","coverage":1.0},{"start":119.02,"end":123.32,"text":"you see adverts for smartphones on many websites you visit.","coverage":1.0},{"start":124.0,"end":129.54,"text":"You see targeted adverts because a Third Party Cookie is on your computer.","coverage":1.0},{"start":130.54,"end":135.88,"text":"If you use websites that share information with a social media account,","coverage":1.0},{"start":136.3,"end":139.32,"text":"then you might receive a social media cookie.","coverage":1.0},{"start":140.12,"end":142.88,"text":"The main job of social media cookies,","coverage":1.0},{"start":143.36,"end":145.14,"text":"like Third Party Cookies,","coverage":1.0},{"start":145.54,"end":149.08,"text":"is to decide what adverts are best for you.","coverage":1.0},{"start":150.18,"end":161.16,"text":"Social media cookies can build a profile of you by collecting information about your habits and interests, even if you do not have a social media account.","coverage":1.0},{"start":161.78,"end":162.66,"text":"For example,","coverage":1.0},{"start":162.98,"end":168.6,"text":"if you go to a news website and click on a video link from a social media company.","coverage":1.0},{"start":169.64,"end":173.38,"text":"If you do not agree to receive social media cookies,","coverage":1.0},{"start":174.08,"end":177.84,"text":"then some parts of the website, like video sharing,","coverage":1.0},{"start":178.26,"end":179.38,"text":"may not work.","coverage":1.0},{"start":180.66,"end":185.58,"text":"Cookies cannot steal passwords, but there are security problems.","coverage":1.0},{"start":185.58,"end":187.42,"text":"For example,","coverage":1.0},{"start":187.74,"end":192.08,"text":"cookie scraping is when a hacker steals information from a cookie.","coverage":1.0},{"start":192.8,"end":197.34,"text":"This information gives the hacker your secret login information,","coverage":1.0},{"start":197.76,"end":201.34,"text":"and the hacker can sign into a website as you.","coverage":1.0},{"start":202.36,"end":210.02,"text":"You can, however, reduce the number of cookies on your computer and keep your personal information more private.","coverage":1.0},{"start":211.0,"end":216.36,"text":"Website owners must ask you to accept cookies when you use their website.","coverage":1.0},{"start":217.14,"end":223.4,"text":"So, you can choose not to accept advertising or other Third Party Cookies.","coverage":1.0},{"start":224.34,"end":228.32,"text":"You can also delete cookies saved in your browser history.","coverage":1.0}],"file":"69d69f39871764dcaddb.js","track":0,"media":"../assets/media/11b123e08f50257b0f946a9fc3c8442a281f45bfe4244961720cedb90cd7397c.mp3"}],"../assets/media/470d1a05bf0a818b539e89bfedd471b08f0cccc82ba3634e3e6485b4d15103ee.mp3":[{"id":"PPT_470d1a05bf0a818b","audioId":"PPT_470d1a05bf0a818b","title":"Book 2 · Unit 7 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 56","duration":361.27,"cues":[{"start":0.0,"end":1.9,"text":"Unit seven,","coverage":1.0},{"start":2.66,"end":3.6,"text":"seven .one","coverage":1.0},{"start":5.25,"end":5.535,"text":"Hello","coverage":1.0},{"start":5.535,"end":6.52,"text":"everyone.","coverage":1.0},{"start":6.98,"end":14.14,"text":"So in this presentation I'd like to discuss the designers of some everyday objects.","coverage":1.0},{"start":14.92,"end":16.38,"text":"Arnie Jakobson,","coverage":1.0},{"start":16.74,"end":20.68,"text":"Sir James Dyson and Sir Jonathan Ive.","coverage":1.0},{"start":21.68,"end":30.0,"text":"These people designed simple things that have changed our lives and how we do everyday things.","coverage":1.0},{"start":30.84,"end":34.98,"text":"Today we are going to think about these inventors and designers,","coverage":1.0},{"start":35.3,"end":40.28,"text":"their achievements and how their inventions and designs have helped us.","coverage":1.0},{"start":41.14,"end":47.9,"text":"I would like to start with Arnie Jakobson who was born in Denmark in 1902.","coverage":1.0},{"start":48.7,"end":56.78,"text":"When he was a child he loved to paint but his father thought being an artist wasn't a good career.","coverage":1.0},{"start":57.9,"end":64.46,"text":"So Jakobson became a designer of many things including buildings and furniture.","coverage":1.0},{"start":65.36,"end":66.2,"text":"For example,","coverage":1.0},{"start":66.9,"end":70.74,"text":"here is a chair he designed in 1958.","coverage":1.0},{"start":71.32,"end":73.84,"text":"It's called the egg chair.","coverage":1.0},{"start":74.58,"end":77.24,"text":"Have any of you seen this kind of chair before?","coverage":1.0},{"start":77.24,"end":78.6,"text":"I have.","coverage":1.0},{"start":79.38,"end":82.44,"text":"Did they call it the egg chair because of its shape?","coverage":1.0},{"start":83.06,"end":84.62,"text":"It's an interesting design.","coverage":1.0},{"start":85.22,"end":85.44,"text":"Yes,","coverage":1.0},{"start":85.84,"end":87.12,"text":"you have a good point.","coverage":1.0},{"start":87.84,"end":91.4,"text":"I think it was called that because of the egg -like shape.","coverage":1.0},{"start":92.2,"end":96.36,"text":"Nowadays we still see Jakobson's designs around us.","coverage":1.0},{"start":97.02,"end":98.96,"text":"When you look at the chair design,","coverage":1.0},{"start":99.4,"end":102.36,"text":"can you guess what Jakobson was like as a person?","coverage":1.0},{"start":102.36,"end":105.92,"text":"His chair looks like a simple neat design.","coverage":1.0},{"start":106.66,"end":111.96,"text":"So maybe he liked simple and neat things and not complicated things.","coverage":1.0},{"start":112.42,"end":112.8,"text":"Actually,","coverage":1.0},{"start":113.12,"end":113.82,"text":"that's right.","coverage":1.0},{"start":114.36,"end":114.96,"text":"He did.","coverage":1.0},{"start":115.76,"end":124.2,"text":"For example, when he was growing up he painted his room white because he didn't like all the flowers on the wallpaper he had.","coverage":1.0},{"start":124.78,"end":128.78,"text":"And as an adult he worked hard to make his designs perfect.","coverage":1.0},{"start":128.78,"end":130.46,"text":"In fact,","coverage":1.0},{"start":131.1,"end":136.08,"text":"he often kept his workers at work until late trying to make things better.","coverage":1.0},{"start":136.86,"end":138.98,"text":"But even though he worked hard,","coverage":1.0},{"start":139.62,"end":142.9,"text":"Jakobson liked to joke and do funny things.","coverage":1.0},{"start":143.42,"end":144.22,"text":"For instance,","coverage":1.0},{"start":144.9,"end":154.36,"text":"as a child he liked to play jokes on others and as an adult he once wore a melon for a hat when someone dared him to.","coverage":1.0},{"start":154.36,"end":161.84,"text":"He also liked working on his own projects in his free time and found painting to be relaxing.","coverage":1.0},{"start":162.9,"end":163.58,"text":"These days,","coverage":1.0},{"start":164.16,"end":167.5,"text":"Jakobson is famous for his modern, simple designs.","coverage":1.0},{"start":168.18,"end":173.66,"text":"His work showed that he thought about the purpose that his designs would serve for people.","coverage":1.0},{"start":174.64,"end":175.14,"text":"Next,","coverage":1.0},{"start":175.66,"end":177.62,"text":"I'd like to talk about an inventor,","coverage":1.0},{"start":178.26,"end":179.32,"text":"James Dyson.","coverage":1.0},{"start":179.32,"end":185.08,"text":"Can anyone think of something you often use that might have his last name,","coverage":1.0},{"start":185.4,"end":185.74,"text":"Dyson,","coverage":1.0},{"start":186.06,"end":186.64,"text":"on it?","coverage":1.0},{"start":186.9,"end":187.58,"text":"I know!","coverage":1.0},{"start":188.0,"end":189.24,"text":"A vacuum cleaner!","coverage":1.0},{"start":189.74,"end":190.74,"text":"Or a hand dryer.","coverage":1.0},{"start":191.16,"end":192.94,"text":"Both of those things are correct.","coverage":1.0},{"start":193.88,"end":198.4,"text":"Dyson's designs and inventions are made to solve problems.","coverage":1.0},{"start":199.16,"end":206.26,"text":"His ideas come because he sees things that could work better, like the vacuum cleaner and hand dryer.","coverage":1.0},{"start":206.26,"end":208.9,"text":"But how did he start?","coverage":1.0},{"start":209.74,"end":210.4,"text":"Well,","coverage":1.0},{"start":210.86,"end":214.38,"text":"Dyson was born in England in 1947.","coverage":1.0},{"start":215.28,"end":217.84,"text":"His father died when he was only nine.","coverage":1.0},{"start":218.34,"end":219.3,"text":"As a result,","coverage":1.0},{"start":219.92,"end":223.1,"text":"Dyson ended up becoming someone who never gave up.","coverage":1.0},{"start":223.88,"end":227.7,"text":"He studied art and design before he studied engineering.","coverage":1.0},{"start":228.86,"end":231.54,"text":"When he saw something that didn't work well,","coverage":1.0},{"start":231.84,"end":235.02,"text":"he got frustrated and worked to improve it.","coverage":1.0},{"start":235.02,"end":236.18,"text":"For example,","coverage":1.0},{"start":236.68,"end":241.16,"text":"his first invention was a wheelbarrow with a ball for a wheel.","coverage":1.0},{"start":241.8,"end":247.0,"text":"This made it easier to carry heavy things in the garden and over rough ground.","coverage":1.0},{"start":247.86,"end":250.58,"text":"It was an interesting new use for a ball.","coverage":1.0},{"start":251.42,"end":257.66,"text":"Also, even though he changed subjects, he was still interested in art as well as designing.","coverage":1.0},{"start":258.48,"end":259.8,"text":"Take a look at this photo.","coverage":1.0},{"start":260.38,"end":261.22,"text":"What do you see?","coverage":1.0},{"start":261.22,"end":264.74,"text":"It looks like a waterfall made from glass and water,","coverage":1.0},{"start":265.2,"end":267.74,"text":"with the water running up instead of falling down.","coverage":1.0},{"start":268.26,"end":269.14,"text":"That's surprising.","coverage":1.0},{"start":269.72,"end":270.28,"text":"That's right.","coverage":1.0},{"start":271.02,"end":277.24,"text":"This was a piece of art that Dyson made in 2003 called Wrong Garden.","coverage":1.0},{"start":278.04,"end":279.24,"text":"It tricks the eye.","coverage":1.0},{"start":279.9,"end":284.46,"text":"This shows Dyson's love of good design as well as being an inventor.","coverage":1.0},{"start":284.46,"end":288.34,"text":"Dyson is still inventing new things,","coverage":1.0},{"start":288.84,"end":299.26,"text":"but he is also interested in supporting education for students and gives money to schools to help students study so they might become inventors too.","coverage":1.0},{"start":299.88,"end":308.12,"text":"He has even donated money to the University of Cambridge to support students and research there with a focus on technology.","coverage":1.0},{"start":309.32,"end":312.56,"text":"Now I have one last picture to show you.","coverage":1.0},{"start":312.56,"end":315.86,"text":"It's a phone with a special design.","coverage":1.0},{"start":316.5,"end":318.3,"text":"It's called the iPhone.","coverage":1.0},{"start":319.16,"end":321.22,"text":"I think a lot of us know about this phone.","coverage":1.0},{"start":322.14,"end":325.36,"text":"It was designed by Sir Jonathan Ive for Apple.","coverage":1.0},{"start":326.02,"end":330.8,"text":"He is responsible for a lot of Apple's product designs, which are simple,","coverage":1.0},{"start":331.16,"end":332.64,"text":"clean and slim.","coverage":1.0},{"start":333.6,"end":337.0,"text":"Ive has won a lot of awards for his Apple designs,","coverage":1.0},{"start":337.32,"end":340.52,"text":"and you can see a lot of his work in museums too.","coverage":1.0},{"start":340.52,"end":348.54,"text":"He is from London and he was made a Knight Commander of the British Empire in 2012 for his design work.","coverage":1.0},{"start":349.62,"end":352.52,"text":"He is known as being hardworking and creative.","coverage":1.0},{"start":353.3,"end":359.38,"text":"I think that his designs will continue to influence the way we live and work for a long time.","coverage":1.0}],"file":"6b9567b9093e724cff2e.js","track":0,"media":"../assets/media/470d1a05bf0a818b539e89bfedd471b08f0cccc82ba3634e3e6485b4d15103ee.mp3"}],"../assets/media/15fa683526c2e07fbc15aa67ca4aed0d73499e4c356b6ac3d94103f1b3b8deac.wav":[{"id":"B3_U04_T4.2_LONG_L01_v01","audioId":"B3_U04_T4.2_LONG_L01_v01","title":"Book 3 · Unit 4 · 课后听力材料","subtitle":"Homework listening material","duration":99.97167800453515,"cues":[{"start":2.46,"end":4.53,"text":"Host: Welcome to this week’s book review.","coverage":0.875},{"start":5.28,"end":15.57,"text":"In the studio with me is Dr Kevin Lee, professor of Anthropology and author of the best-selling book Changing Traditions in the Modern World.","coverage":0.96},{"start":16.31,"end":21.89,"text":"First of all, could you tell us what anthropologists study and what your own area of interest is?","coverage":0.944},{"start":22.96,"end":23.97,"text":"Dr Lee: That’s a good question!","coverage":0.714},{"start":25.1,"end":28.69,"text":"Anthropology, in a general sense, is the study of humanity.","coverage":0.9},{"start":29.14,"end":30.71,"text":"I know that’s not very exact.","coverage":1.0},{"start":31.06,"end":38.11,"text":"That’s why we have many types of Anthropology, like Linguistic anthropology and Social anthropology.","coverage":1.0},{"start":39.56,"end":42.54,"text":"My speciality is Cultural anthropology.","coverage":0.8},{"start":42.87,"end":50.75,"text":"I study different cultures around the world and how social and political changes affect these cultures.","coverage":1.0},{"start":51.08,"end":55.19,"text":"Host: And when did you first become interested in Anthropology?","coverage":0.9},{"start":55.47,"end":57.91,"text":"Dr Lee: I grew up in a multicultural home.","coverage":0.778},{"start":58.18,"end":61.44,"text":"My mother is American and my father is Korean.","coverage":1.0},{"start":61.78,"end":65.82,"text":"They were both English teachers, so we travelled a lot.","coverage":1.0},{"start":66.2,"end":70.77,"text":"As a child, I lived in Japan, Thailand and Egypt.","coverage":1.0},{"start":71.05,"end":74.49,"text":"That’s why I decided to study Anthropology.","coverage":1.0},{"start":74.86,"end":82.36,"text":"Growing up in different cultures helps you realize that customs and traditions are often local.","coverage":0.933},{"start":82.68,"end":89.91,"text":"Things that are acceptable in one culture can be completely unacceptable in another.","coverage":1.0},{"start":90.2,"end":99.59,"text":"However, despite some differences between cultures, I have noticed that there are often more similarities than differences between people.","coverage":1.0}],"file":"6cddc046c7938fde5541.js","track":0,"media":"../assets/media/15fa683526c2e07fbc15aa67ca4aed0d73499e4c356b6ac3d94103f1b3b8deac.wav"}],"../assets/media/b65bbc3a60bf3e588888a1a919b12d210d68b4b793cc99acb6eef63b05ad5af5.mp3":[{"id":"PPT_b65bbc3a60bf3e58","audioId":"PPT_b65bbc3a60bf3e58","title":"Book 3 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 41","duration":40.25,"cues":[{"start":0.0,"end":1.84,"text":"Unit two,","coverage":1.0},{"start":2.46,"end":3.88,"text":"two .one","coverage":1.0},{"start":3.88,"end":5.1,"text":"one","coverage":1.0},{"start":5.92,"end":9.94,"text":"Today I want to explain some alternative solutions.","coverage":1.0},{"start":12.64,"end":13.36,"text":"two","coverage":1.0},{"start":14.12,"end":15.78,"text":"As we all know,","coverage":1.0},{"start":16.12,"end":19.38,"text":"in order to grow plants we need water and sunlight.","coverage":1.0},{"start":22.02,"end":22.74,"text":"three","coverage":1.0},{"start":23.52,"end":29.0,"text":"I think that desert farms might be a very interesting way to farm in the future.","coverage":1.0},{"start":31.6,"end":32.2,"text":"four","coverage":1.0},{"start":33.24,"end":35.48,"text":"If you add the nutrients to water,","coverage":1.0},{"start":36.08,"end":38.38,"text":"you can grow fruit and vegetables in water.","coverage":1.0}],"file":"6d384ab64a0a5bcc8047.js","track":0,"media":"../assets/media/b65bbc3a60bf3e588888a1a919b12d210d68b4b793cc99acb6eef63b05ad5af5.mp3"}],"../assets/media/48e699c6c5ce38ee19df0bae1b0428984fb711e79757fe92bf60785dcaa798de.wav":[{"id":"B2_U06_T6.3_LONG_L01_v01","audioId":"B2_U06_T6.3_LONG_L01_v01","title":"Book 2 · Unit 6 · 课后听力材料","subtitle":"Homework listening material","duration":98.508821,"cues":[{"start":0.0,"end":4.44,"text":"Narrator: 6.3 Professor Gould: OK, Alika."},{"start":5.02,"end":6.76,"text":"Should we look at your project now?","coverage":1.0},{"start":7.22,"end":7.42,"text":"Alika: Yes, OK.","coverage":0.333},{"start":9.18,"end":12.58,"text":"Professor Gould: You’ve done a lot of reading for this, which is great.","coverage":0.857},{"start":13.0,"end":15.73,"text":"I can see you wrote a lot of information down.","coverage":1.0},{"start":16.22,"end":20.43,"text":"Alika: Yes, but I haven’t finished yet – I ran out of time.","coverage":0.923},{"start":21.22,"end":26.67,"text":"But I read as much as I could – about 103 different reports.","coverage":1.0},{"start":27.09,"end":32.0,"text":"I took part in the discussions on this with students from my study group.","coverage":1.0},{"start":32.11,"end":34.64,"text":"I studied the way people work.","coverage":1.0},{"start":35.23,"end":36.09,"text":"Professor Gould: Good.","coverage":0.333},{"start":37.0,"end":38.75,"text":"Can you tell me what you learned?","coverage":1.0},{"start":39.22,"end":43.41,"text":"Alika: Well, I looked at how people spend time at work.","coverage":0.909},{"start":44.08,"end":55.54,"text":"I was interested in how people wasted time and why they didn’t work hard at their jobs; I mean, the reasons why they didn’t focus on their work.","coverage":1.0},{"start":56.1,"end":59.68,"text":"I found out a lot of interesting information.","coverage":1.0},{"start":60.22,"end":65.64,"text":"For example, almost half of the workers wasted time on the internet.","coverage":1.0},{"start":66.22,"end":70.41,"text":"They were surfing the internet or writing personal emails.","coverage":1.0},{"start":71.22,"end":74.59,"text":"It was 48% of workers, in fact.","coverage":1.0},{"start":75.23,"end":82.44,"text":"31.5% also said they spent time talking to colleagues instead of working.","coverage":1.0},{"start":83.22,"end":90.81,"text":"And a little under half that amount, 15%, said they took longer coffee and lunch breaks than they should.","coverage":1.0},{"start":91.22,"end":97.42,"text":"Only 5% said they spent time texting friends and making plans for after work.","coverage":1.0}],"file":"6dabcab9c16664faa391.js","track":0,"media":"../assets/media/48e699c6c5ce38ee19df0bae1b0428984fb711e79757fe92bf60785dcaa798de.wav"}],"../assets/media/9131fd9edb3606080fec38f33f408385d0770f7cbc8d8cd2e7f31aed63d53a6f.mp3":[{"id":"PPT_9131fd9edb360608","audioId":"PPT_9131fd9edb360608","title":"Book 3 · Unit 2 · RW · READING 2","subtitle":"READING 2 · source slide 118","duration":228.1,"cues":[{"start":0.0,"end":3.0,"text":"The Causes and Effects of Deforestation","coverage":1.0},{"start":4.04,"end":7.86,"text":"Forests, which cover almost one -third of the surface of the Earth,","coverage":1.0},{"start":8.32,"end":11.16,"text":"produce oxygen and provide homes to plants,","coverage":1.0},{"start":11.52,"end":12.66,"text":"animals, and humans.","coverage":1.0},{"start":13.36,"end":14.14,"text":"These days,","coverage":1.0},{"start":14.5,"end":18.48,"text":"many of the world's great forests are threatened by deforestation,","coverage":1.0},{"start":19.1,"end":22.62,"text":"the process of removing trees from large areas of land.","coverage":1.0},{"start":23.68,"end":27.0,"text":"The destruction of forests occurs for several reasons.","coverage":1.0},{"start":27.0,"end":30.38,"text":"Trees are used as fuel or for construction,","coverage":1.0},{"start":31.32,"end":36.04,"text":"and cleared land is used as pasture for animals or fields for planting food.","coverage":1.0},{"start":36.86,"end":43.28,"text":"The main harmful effects of deforestation are climate change and damage to animal habitats.","coverage":1.0},{"start":45.06,"end":51.88,"text":"The main causes of deforestation are commercial farming by big business and farming by local people.","coverage":1.0},{"start":51.88,"end":57.82,"text":"Huge commercial farms have taken over large areas of forest in many countries.","coverage":1.0},{"start":58.74,"end":60.36,"text":"In Indonesia, for example,","coverage":1.0},{"start":61.0,"end":66.36,"text":"industrial logging is carried out to clear huge areas for the production of palm oil,","coverage":1.0},{"start":66.86,"end":67.84,"text":"while in Brazil,","coverage":1.0},{"start":68.56,"end":74.72,"text":"large areas of the Amazon rainforest are cleared to grow soy and produce vegetable oil.","coverage":1.0},{"start":75.4,"end":78.52,"text":"Local farmers also cut down and burn trees,","coverage":1.0},{"start":78.96,"end":83.18,"text":"but they clear areas just big enough to graze cattle or grow crops.","coverage":1.0},{"start":83.88,"end":84.32,"text":"However,","coverage":1.0},{"start":84.88,"end":86.3,"text":"after two or three years,","coverage":1.0},{"start":86.66,"end":87.38,"text":"the land can","coverage":1.0},{"start":87.38,"end":87.66,"text":"no","coverage":1.0},{"start":87.66,"end":88.78,"text":"longer be used,","coverage":1.0},{"start":89.1,"end":91.72,"text":"so the farmer moves to another piece of land.","coverage":1.0},{"start":92.56,"end":98.44,"text":"Normally, it takes around ten years for cleared land to recover, but in populated areas,","coverage":1.0},{"start":98.84,"end":101.06,"text":"the land is never allowed to recover.","coverage":1.0},{"start":101.06,"end":105.48,"text":"This constant reuse of land leads to heavy erosion,","coverage":1.0},{"start":106.18,"end":110.1,"text":"the loss of the top layer of soil which protects the ground.","coverage":1.0},{"start":111.02,"end":112.4,"text":"Erosion, in turn,","coverage":1.0},{"start":112.84,"end":115.1,"text":"can cause flooding and heavy rain.","coverage":1.0},{"start":116.56,"end":120.48,"text":"One serious effect of deforestation is climate change.","coverage":1.0},{"start":121.44,"end":127.38,"text":"Normally, tropical rainforests help control the Earth's temperature by absorbing carbon dioxide.","coverage":1.0},{"start":127.38,"end":128.5,"text":"However,","coverage":1.0},{"start":128.9,"end":129.44,"text":"recently,","coverage":1.0},{"start":129.96,"end":133.64,"text":"the Amazon area, where much of the world's rainforests are found,","coverage":1.0},{"start":134.06,"end":137.62,"text":"has been releasing more carbon dioxide than it absorbs.","coverage":1.0},{"start":138.64,"end":139.3,"text":"In addition,","coverage":1.0},{"start":139.76,"end":142.52,"text":"in areas where deforestation has taken place,","coverage":1.0},{"start":142.94,"end":149.74,"text":"the carbon dioxide goes into the atmosphere and traps heat in a process called the greenhouse effect.","coverage":1.0},{"start":150.5,"end":152.78,"text":"The result is global warming.","coverage":1.0},{"start":153.54,"end":156.64,"text":"Increasing global temperatures result in less rain.","coverage":1.0},{"start":156.64,"end":161.6,"text":"This causes the rainforests to dry out and leads to fires,","coverage":1.0},{"start":162.14,"end":165.0,"text":"which cause more emissions of carbon dioxide.","coverage":1.0},{"start":165.98,"end":172.84,"text":"In this way, the rainforests actually contribute to global warming instead of helping to solve it.","coverage":1.0},{"start":174.58,"end":178.3,"text":"Forest destruction also has an effect on biodiversity.","coverage":1.0},{"start":179.3,"end":186.44,"text":"Deforestation causes the loss of habitats and damage to land where plants and animal species live,","coverage":1.0},{"start":186.84,"end":189.56,"text":"leading to the extinction of many species.","coverage":1.0},{"start":190.5,"end":198.4,"text":"A decrease in biodiversity threatens entire ecosystems and destroys future sources of food and medicine.","coverage":1.0},{"start":199.88,"end":200.74,"text":"In conclusion,","coverage":1.0},{"start":201.48,"end":208.2,"text":"damage to the world's forests is leading to changes in the natural environment and causing global warming.","coverage":1.0},{"start":208.3,"end":210.4,"text":"Looking to the future,","coverage":1.0},{"start":210.92,"end":217.9,"text":"governments should act to plant more trees which will absorb carbon dioxide and protect forests from illegal logging.","coverage":1.0},{"start":218.8,"end":219.44,"text":"Otherwise,","coverage":1.0},{"start":220.0,"end":226.14,"text":"deforestation on such a large scale is sure to have terrible effects on the environment.","coverage":1.0}],"file":"6ee776d3e4858327f732.js","track":0,"media":"../assets/media/9131fd9edb3606080fec38f33f408385d0770f7cbc8d8cd2e7f31aed63d53a6f.mp3"}],"../assets/media/3663f172862b4da610b9c85be278e9f80ee5725051d9f7dfc5c4f887c8b63065.mp3":[{"id":"PPT_3663f172862b4da6","audioId":"PPT_3663f172862b4da6","title":"Book 3 · Unit 6 · RW · READING 2","subtitle":"READING 2 · source slide 112","duration":266.53,"cues":[{"start":0.0,"end":1.12,"text":"Deep fakes,","coverage":1.0},{"start":1.6,"end":3.08,"text":"benefit or threat.","coverage":1.0},{"start":4.1,"end":7.6,"text":"You have probably already seen something like this online.","coverage":1.0},{"start":8.2,"end":12.62,"text":"The head of one actor on the body of a completely different actor.","coverage":1.0},{"start":13.46,"end":16.56,"text":"This type of image is created by a computer,","coverage":1.0},{"start":17.12,"end":19.1,"text":"and it is called a deep fake.","coverage":1.0},{"start":20.22,"end":30.0,"text":"Deep fakes use a form of artificial intelligence in which a computer model is trained to use information in the same way as the human brain.","coverage":1.0},{"start":30.7,"end":37.54,"text":"It can create images and voices that look and sound almost like real people,","coverage":1.0},{"start":38.22,"end":39.2,"text":"including actors,","coverage":1.0},{"start":39.74,"end":40.26,"text":"politicians,","coverage":1.0},{"start":40.74,"end":42.36,"text":"and other famous people.","coverage":1.0},{"start":42.94,"end":44.08,"text":"In the past,","coverage":1.0},{"start":44.4,"end":50.86,"text":"only experts were able to use this technology, but now anyone can create a deep fake.","coverage":1.0},{"start":50.86,"end":55.14,"text":"This is causing both excitement and worry.","coverage":1.0},{"start":56.78,"end":60.32,"text":"The most familiar use of deep fakes is in entertainment.","coverage":1.0},{"start":61.18,"end":61.94,"text":"For example,","coverage":1.0},{"start":62.34,"end":66.76,"text":"deep fake technology can make actors in films look much younger.","coverage":1.0},{"start":67.72,"end":69.68,"text":"It works much better than makeup.","coverage":1.0},{"start":71.0,"end":77.16,"text":"Directors can also use it to produce the image or voice of actors who are not available.","coverage":1.0},{"start":77.16,"end":83.56,"text":"For example, a director may discover a mistake and want to film a scene again,","coverage":1.0},{"start":84.1,"end":87.36,"text":"but the actors are already working on other projects.","coverage":1.0},{"start":88.12,"end":93.58,"text":"The scene can be recreated by artificial intelligence without the live actors.","coverage":1.0},{"start":94.46,"end":94.88,"text":"How?","coverage":1.0},{"start":95.84,"end":101.52,"text":"Deep fake technology uses the rest of the film to learn the actor's appearance,","coverage":1.0},{"start":101.84,"end":103.14,"text":"speech, and movement.","coverage":1.0},{"start":103.14,"end":107.14,"text":"It can even recreate actors who are dead.","coverage":1.0},{"start":108.52,"end":108.98,"text":"Clearly,","coverage":1.0},{"start":109.32,"end":112.45,"text":"this technology offers the film industry many benefits.","coverage":1.0},{"start":113.44,"end":113.94,"text":"However,","coverage":1.0},{"start":114.44,"end":117.2,"text":"this technology also creates problems.","coverage":1.0},{"start":118.1,"end":118.62,"text":"Today,","coverage":1.0},{"start":118.94,"end":121.06,"text":"so much of our lives are online.","coverage":1.0},{"start":122.02,"end":125.16,"text":"What if someone creates a deep fake of you?","coverage":1.0},{"start":125.86,"end":129.08,"text":"Could it be used to get access to your bank account,","coverage":1.0},{"start":129.76,"end":130.84,"text":"your health records?","coverage":1.0},{"start":130.84,"end":132.98,"text":"In 2020,","coverage":1.0},{"start":133.52,"end":138.94,"text":"thieves created a deep fake voice of a bank manager in the United Arab Emirates.","coverage":1.0},{"start":139.58,"end":143.12,"text":"They used it to steal $35 million.","coverage":1.0},{"start":143.98,"end":146.36,"text":"As the technology improves,","coverage":1.0},{"start":146.96,"end":150.4,"text":"these threats to security will definitely increase.","coverage":1.0},{"start":152.0,"end":154.58,"text":"Deep fakes can also threaten privacy.","coverage":1.0},{"start":154.58,"end":157.26,"text":"Our personal information,","coverage":1.0},{"start":157.58,"end":158.6,"text":"including photos,","coverage":1.0},{"start":159.12,"end":161.16,"text":"is often available on the internet.","coverage":1.0},{"start":162.24,"end":166.5,"text":"Someone could use your photo and put it on someone else's body.","coverage":1.0},{"start":167.42,"end":171.8,"text":"Some celebrities have already found their own images on the internet.","coverage":1.0},{"start":172.88,"end":178.3,"text":"They are doing things they never did and saying things they never said.","coverage":1.0},{"start":179.14,"end":182.22,"text":"This can be embarrassing or even dangerous.","coverage":1.0},{"start":182.22,"end":188.24,"text":"It is very difficult to control these images once they appear on the internet.","coverage":1.0},{"start":189.48,"end":190.08,"text":"Finally,","coverage":1.0},{"start":190.62,"end":194.18,"text":"deep fakes can be used to spread false information.","coverage":1.0},{"start":195.04,"end":198.98,"text":"Today, when we watch the news on television or online,","coverage":1.0},{"start":199.44,"end":202.1,"text":"we generally believe everything is real.","coverage":1.0},{"start":202.8,"end":209.1,"text":"We believe that the heads, bodies, and voices all belong to the same real people.","coverage":1.0},{"start":209.1,"end":212.36,"text":"As deep fake technology improves,","coverage":1.0},{"start":213.24,"end":215.04,"text":"that will probably change.","coverage":1.0},{"start":215.7,"end":220.96,"text":"We will not be able to trust what we see and hear because it could be fake.","coverage":1.0},{"start":221.92,"end":224.34,"text":"Deep fakes can change today's news,","coverage":1.0},{"start":225.02,"end":227.22,"text":"but they may also change history.","coverage":1.0},{"start":228.22,"end":229.14,"text":"For example,","coverage":1.0},{"start":229.46,"end":235.94,"text":"someone could discover a lost video of a famous person saying terrible things.","coverage":1.0},{"start":235.94,"end":241.44,"text":"Deep fakes may change how we view our world and our past.","coverage":1.0},{"start":243.1,"end":248.16,"text":"Although this technology offers important benefits to the entertainment industry,","coverage":1.0},{"start":248.78,"end":251.98,"text":"it also presents some frightening possibilities.","coverage":1.0},{"start":253.02,"end":255.96,"text":"Experts advise that we should use the same tool,","coverage":1.0},{"start":256.28,"end":257.58,"text":"artificial intelligence,","coverage":1.0},{"start":257.98,"end":264.61,"text":"to tackle these problems and make sure that this technology is used responsibly.","coverage":1.0}],"file":"6fe5654ce5f5ba6c543c.js","track":0,"media":"../assets/media/3663f172862b4da610b9c85be278e9f80ee5725051d9f7dfc5c4f887c8b63065.mp3"}],"../assets/media/b982961134d09cea4c0b5a19284da509dc7672a5cf36837b26c09e19ae4a7c9a.mp3":[{"id":"PPT_b982961134d09cea","audioId":"PPT_b982961134d09cea","title":"Book 3 · Unit 4 · RW · READING 2","subtitle":"READING 2 · source slide 160","duration":257.75,"cues":[{"start":0.0,"end":4.56,"text":"Protecting Our Intangible Cultural Heritage by Linda Barker","coverage":1.0},{"start":5.66,"end":8.34,"text":"In today's ever -changing global landscape,","coverage":1.0},{"start":8.78,"end":13.8,"text":"most of us recognize the importance of preserving our own unique cultural heritage.","coverage":1.0},{"start":14.46,"end":15.96,"text":"But what do we save?","coverage":1.0},{"start":16.56,"end":18.66,"text":"A magnificent building which is under threat?","coverage":1.0},{"start":19.38,"end":21.02,"text":"A historical part of a city?","coverage":1.0},{"start":21.76,"end":22.98,"text":"An important work of art?","coverage":1.0},{"start":23.7,"end":27.0,"text":"All of these are significant, but what about our songs,","coverage":1.0},{"start":27.34,"end":27.84,"text":"stories,","coverage":1.0},{"start":28.48,"end":30.3,"text":"ceremonies, and traditional practices?","coverage":1.0},{"start":30.96,"end":37.42,"text":"These intangible aspects of our culture can be just as meaningful as anything we build or create.","coverage":1.0},{"start":38.18,"end":43.2,"text":"Shouldn't they also be preserved for future generations to experience and enjoy?","coverage":1.0},{"start":44.08,"end":46.04,"text":"The answer, according to UNESCO,","coverage":1.0},{"start":46.7,"end":50.44,"text":"United Nations Educational, Scientific, and Cultural Organization,","coverage":1.0},{"start":50.94,"end":51.72,"text":"is yes.","coverage":1.0},{"start":52.4,"end":58.4,"text":"That is why in 2008 it published its first Intangible Cultural Heritage list.","coverage":1.0},{"start":59.06,"end":68.76,"text":"You may already know of UNESCO's famous list of World Heritage Sites, consisting of places selected for special protection because of their value to the world,","coverage":1.0},{"start":69.08,"end":74.38,"text":"such as the Pyramids of Giza in Egypt or the Great Barrier Reef in Australia.","coverage":1.0},{"start":75.06,"end":75.54,"text":"However,","coverage":1.0},{"start":76.08,"end":77.9,"text":"the ICH list is different.","coverage":1.0},{"start":78.62,"end":84.14,"text":"Its purpose is to record living customs and traditions which are endangered by globalization.","coverage":1.0},{"start":84.82,"end":87.62,"text":"These include languages and spoken traditions,","coverage":1.0},{"start":87.98,"end":89.78,"text":"such as storytelling and poetry,","coverage":1.0},{"start":90.36,"end":91.14,"text":"performing arts,","coverage":1.0},{"start":91.62,"end":92.44,"text":"traditional crafts,","coverage":1.0},{"start":92.86,"end":94.66,"text":"and local knowledge and beliefs.","coverage":1.0},{"start":95.56,"end":102.06,"text":"Today, there are more than 600 customs and traditions on the Intangible Cultural Heritage list.","coverage":1.0},{"start":102.94,"end":108.62,"text":"Two recent entries show us just how rich and varied are the practices selected for protection.","coverage":1.0},{"start":109.28,"end":111.5,"text":"The culture of the Jeju Henyo,","coverage":1.0},{"start":111.9,"end":114.7,"text":"the women divers of Jeju Island in South Korea,","coverage":1.0},{"start":115.14,"end":117.34,"text":"was added to the list in 2016.","coverage":1.0},{"start":118.28,"end":124.5,"text":"These amazing women dive ten meters under the sea to get food without the use of breathing equipment.","coverage":1.0},{"start":125.28,"end":127.9,"text":"They do this for up to seven hours a day,","coverage":1.0},{"start":128.24,"end":129.54,"text":"90 days of the year,","coverage":1.0},{"start":129.9,"end":133.02,"text":"holding their breath for about one minute every dive.","coverage":1.0},{"start":133.58,"end":139.72,"text":"Knowledge about diving practices is passed down from generation to generation within families.","coverage":1.0},{"start":140.4,"end":141.06,"text":"Yet today,","coverage":1.0},{"start":141.58,"end":145.9,"text":"most of the divers are in their 60s, 70s, or 80s.","coverage":1.0},{"start":145.9,"end":147.16,"text":"As they have become older,","coverage":1.0},{"start":147.74,"end":150.5,"text":"younger women have not stepped in to take their place,","coverage":1.0},{"start":150.84,"end":153.76,"text":"meaning the practice is in danger of disappearing.","coverage":1.0},{"start":155.28,"end":161.8,"text":"Another cultural practice added to the Intangible Cultural Heritage list in 2021 is falconry.","coverage":1.0},{"start":162.37,"end":166.48,"text":"This is the ancient custom of hunting with trained birds of prey,","coverage":1.0},{"start":166.8,"end":168.88,"text":"such as falcons and hawks.","coverage":1.0},{"start":169.18,"end":171.64,"text":"Regarded as both an art form and a sport,","coverage":1.0},{"start":172.1,"end":175.04,"text":"it requires years of training and discipline.","coverage":1.0},{"start":176.12,"end":182.2,"text":"Falconry is practiced around the world, from France to Mongolia to the United Arab Emirates,","coverage":1.0},{"start":182.52,"end":188.66,"text":"which is home to the world's first falcon hospital and each year hosts a falcon beauty contest.","coverage":1.0},{"start":188.66,"end":189.96,"text":"Sadly,","coverage":1.0},{"start":190.54,"end":195.38,"text":"falconry is now threatened by the growth of cities and the loss of natural habitats.","coverage":1.0},{"start":196.14,"end":201.72,"text":"There are fears that the practice may disappear unless efforts to preserve it are successful.","coverage":1.0},{"start":203.04,"end":213.02,"text":"Both Jeju -Henyo and falconry illustrate the tremendous range of cultural practices which the Intangible Cultural Heritage list was created to preserve.","coverage":1.0},{"start":213.54,"end":214.24,"text":"And yet,","coverage":1.0},{"start":214.62,"end":218.04,"text":"while most of us would agree that UNESCO's efforts are valuable,","coverage":1.0},{"start":218.72,"end":224.44,"text":"I find myself questioning the fairness and usefulness of the Intangible Cultural Heritage list.","coverage":1.0},{"start":225.26,"end":229.5,"text":"Why are some customs and practices included, while others are not?","coverage":1.0},{"start":230.1,"end":231.22,"text":"Who decides this?","coverage":1.0},{"start":231.94,"end":235.14,"text":"Does inclusion on the list make a difference in the long term?","coverage":1.0},{"start":235.82,"end":238.36,"text":"In this age of rapid globalization,","coverage":1.0},{"start":238.98,"end":243.22,"text":"when fewer young people are interested in learning about the customs of their ancestors,","coverage":1.0},{"start":243.82,"end":249.48,"text":"it may already be too late to preserve much of our diverse and precious cultural heritage.","coverage":1.0},{"start":250.38,"end":252.6,"text":"But for the benefit of future generations,","coverage":1.0},{"start":253.24,"end":255.84,"text":"I believe we must never stop trying.","coverage":1.0}],"file":"73f0101327a1606ecfaa.js","track":0,"media":"../assets/media/b982961134d09cea4c0b5a19284da509dc7672a5cf36837b26c09e19ae4a7c9a.mp3"}],"../assets/media/8b6f885fff8f106631459efc6bce687b7fc6c80b2d00bdda398625b3efb920d2.mp3":[{"id":"PPT_8b6f885fff8f1066","audioId":"PPT_8b6f885fff8f1066","title":"Book 2 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 66","duration":183.54,"cues":[{"start":0.0,"end":1.82,"text":"eight .four","coverage":1.0},{"start":3.41,"end":5.74,"text":"Why is space junk a problem?","coverage":1.0},{"start":6.86,"end":7.22,"text":"Well,","coverage":1.0},{"start":7.58,"end":11.54,"text":"the pieces of space junk travel at extremely fast speeds,","coverage":1.0},{"start":12.06,"end":14.8,"text":"over 25 ,000 km per hour,","coverage":1.0},{"start":15.26,"end":19.3,"text":"and so they can cause very bad problems if they hit anything.","coverage":1.0},{"start":20.34,"end":20.82,"text":"NASA,","coverage":1.0},{"start":21.26,"end":21.96,"text":"the U .S.","coverage":1.0},{"start":22.1,"end":22.98,"text":"space agency,","coverage":1.0},{"start":23.6,"end":25.76,"text":"watches where the space junk is.","coverage":1.0},{"start":26.2,"end":28.32,"text":"The International Space Station,","coverage":1.0},{"start":28.7,"end":29.5,"text":"the ISS,","coverage":1.0},{"start":30.18,"end":37.46,"text":"can move out of the way of the space junk if they get a message to move at least five hours before an accident.","coverage":1.0},{"start":38.36,"end":42.32,"text":"Because people continue to send so many things into space,","coverage":1.0},{"start":42.84,"end":45.48,"text":"and this first started in 1957,","coverage":1.0},{"start":46.28,"end":50.66,"text":"there are now over 27 ,000 pieces of space junk.","coverage":1.0},{"start":51.51,"end":55.34,"text":"The smaller pieces might be as tiny as a bit of paint,","coverage":1.0},{"start":56.04,"end":60.08,"text":"but most of them are larger than ten cm across.","coverage":1.0},{"start":60.88,"end":63.18,"text":"These are parts of old spacecraft,","coverage":1.0},{"start":63.9,"end":65.28,"text":"broken pieces of satellites,","coverage":1.0},{"start":65.8,"end":66.7,"text":"and other things.","coverage":1.0},{"start":67.48,"end":70.72,"text":"Some of this happened because of accidents in space,","coverage":1.0},{"start":71.34,"end":74.56,"text":"which can create thousands of pieces of space junk.","coverage":1.0},{"start":75.72,"end":79.94,"text":"Many people would like to find a solution to space junk if they could.","coverage":1.0},{"start":81.32,"end":85.9,"text":"Scientists worry that if large pieces of space junk hit each other,","coverage":1.0},{"start":86.28,"end":91.06,"text":"they would break and there would be more and more broken pieces of space junk.","coverage":1.0},{"start":92.14,"end":94.1,"text":"When there is too much space junk,","coverage":1.0},{"start":94.66,"end":98.38,"text":"we won't be able to use the space around the Earth for satellites.","coverage":1.0},{"start":99.86,"end":103.12,"text":"So what options do we have to solve the problem?","coverage":1.0},{"start":103.84,"end":105.5,"text":"The British mission,","coverage":1.0},{"start":105.94,"end":106.88,"text":"Remove Debris,","coverage":1.0},{"start":107.24,"end":112.08,"text":"is trying to solve the problem by catching space junk and taking it away.","coverage":1.0},{"start":112.88,"end":114.78,"text":"If all the space junk was gone,","coverage":1.0},{"start":115.18,"end":116.88,"text":"there wouldn't be a problem anymore.","coverage":1.0},{"start":118.26,"end":121.44,"text":"But what about space junk falling from space?","coverage":1.0},{"start":122.34,"end":124.3,"text":"What is the danger to people?","coverage":1.0},{"start":125.52,"end":130.32,"text":"There's not much chance anything would hit you if you were outside on a normal day.","coverage":1.0},{"start":130.84,"end":134.78,"text":"That's because most junk burns as it falls to Earth.","coverage":1.0},{"start":135.74,"end":136.96,"text":"In 1997,","coverage":1.0},{"start":137.68,"end":141.7,"text":"one person in the US was hit by a piece of space junk,","coverage":1.0},{"start":142.2,"end":143.9,"text":"and she was not hurt at all.","coverage":1.0},{"start":145.06,"end":146.22,"text":"In 2022,","coverage":1.0},{"start":147.04,"end":156.54,"text":"a large piece of space junk from a SpaceX spacecraft fell to the surface of the Earth and landed on an Australian sheep farm.","coverage":1.0},{"start":157.54,"end":159.08,"text":"From time to time,","coverage":1.0},{"start":159.52,"end":161.48,"text":"other large pieces hit the ground,","coverage":1.0},{"start":162.04,"end":163.72,"text":"usually in rural areas.","coverage":1.0},{"start":164.84,"end":165.58,"text":"These days,","coverage":1.0},{"start":165.98,"end":172.34,"text":"most space agencies work to make their old spacecraft fall in the ocean if possible.","coverage":1.0},{"start":173.26,"end":173.78,"text":"However,","coverage":1.0},{"start":174.16,"end":177.24,"text":"with tens of thousands of pieces of space junk,","coverage":1.0},{"start":177.96,"end":181.7,"text":"there might be more than rain falling from the sky.","coverage":1.0}],"file":"753e239c51dbf395ecfa.js","track":0,"media":"../assets/media/8b6f885fff8f106631459efc6bce687b7fc6c80b2d00bdda398625b3efb920d2.mp3"}],"../assets/media/555c70f0461311721dd998316826b579009b0648cdb3bdef9a150bb8ee5880cd.mp3":[{"id":"PPT_555c70f046131172","audioId":"PPT_555c70f046131172","title":"Book 2 · Unit 4 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 60","duration":81.4,"cues":[{"start":0.0,"end":2.0,"text":"four .three","coverage":1.0},{"start":3.48,"end":8.86,"text":"And so I put all the results into a spreadsheet on my laptop.","coverage":1.0},{"start":9.72,"end":12.68,"text":"Here are all the answers from the surveys I did.","coverage":1.0},{"start":13.06,"end":14.06,"text":"12 of them.","coverage":1.0},{"start":14.7,"end":17.72,"text":"Oh, and the three surveys that you did.","coverage":1.0},{"start":18.52,"end":18.98,"text":"Okay,","coverage":1.0},{"start":19.64,"end":21.2,"text":"let's see what they say.","coverage":1.0},{"start":21.96,"end":25.66,"text":"We asked how people felt when they woke up on a sunny day.","coverage":1.0},{"start":26.08,"end":26.44,"text":"And?","coverage":1.0},{"start":27.22,"end":35.06,"text":"14 out of 15 people said they feel better in sunny weather than when it is very wet or rainy.","coverage":1.0},{"start":35.8,"end":37.22,"text":"They prefer sunshine.","coverage":1.0},{"start":38.44,"end":43.54,"text":"And 13 of them said it made them feel they could get a lot done that day.","coverage":1.0},{"start":44.0,"end":49.34,"text":"Also, 12 out of 15 people said that they did more when the weather was good.","coverage":1.0},{"start":50.14,"end":52.34,"text":"What about when they feel most tired?","coverage":1.0},{"start":52.34,"end":53.2,"text":"Well,","coverage":1.0},{"start":53.62,"end":58.52,"text":"everyone said that they felt tired if the weather was cloudy and dark.","coverage":1.0},{"start":59.32,"end":64.62,"text":"And 14 said they had the most energy when there was lots of light.","coverage":1.0},{"start":65.28,"end":68.62,"text":"So good weather means that people have more energy.","coverage":1.0},{"start":69.04,"end":72.06,"text":"Yeah, that is what our survey seems to show.","coverage":1.0},{"start":72.78,"end":76.02,"text":"Of course, it might be different in another country.","coverage":1.0},{"start":76.8,"end":79.48,"text":"Maybe it depends on the place you live.","coverage":1.0}],"file":"7722c534de3924883498.js","track":0,"media":"../assets/media/555c70f0461311721dd998316826b579009b0648cdb3bdef9a150bb8ee5880cd.mp3"}],"../assets/media/4a301458009e7be8f26df25c38db13d9267a57db24e9729d28822f73c4127b46.wav":[{"id":"B3_U01_T1.1_SHORT_S02_v01","audioId":"B3_U01_T1.1_SHORT_S02_v01","title":"Book 3 · Unit 1 · 课后听力材料","subtitle":"Homework listening material","duration":64.42888888888889,"cues":[{"start":0.09,"end":2.78,"text":"Ms Johnson, would you like to begin?","coverage":1.0},{"start":4.02,"end":6.33,"text":"Ms Johnson: Thank you for inviting me to this debate.","coverage":0.8},{"start":6.64,"end":12.53,"text":"It’s well known that animals have worked side by side with humans for thousands of years.","coverage":1.0},{"start":12.84,"end":18.23,"text":"In fact, they helped us develop our civilization and helped humans survive.","coverage":1.0},{"start":18.98,"end":25.14,"text":"Animals, like elephants and horses, were used to build amazing structures, like the pyramids in Egypt.","coverage":0.938},{"start":26.24,"end":30.9,"text":"Yet their hard work and suffering are hardly ever recognized.","coverage":1.0},{"start":31.9,"end":41.94,"text":"For example, horses, camels and elephants were used to transport armies and soldiers during wars and many of these animals died in these wars.","coverage":0.958},{"start":43.5,"end":45.18,"text":"And there are other examples.","coverage":1.0},{"start":45.99,"end":52.7,"text":"Even now, dogs are used to pull sleds in cold climates and elephants are used for logging.","coverage":0.941},{"start":53.42,"end":57.15,"text":"These animals work long hours and live in difficult conditions.","coverage":1.0},{"start":58.26,"end":61.02,"text":"However, they get very little reward.","coverage":1.0},{"start":61.9,"end":63.93,"text":"Humans just use them to their advantage.","coverage":1.0}],"file":"777cdb92efe6a3e6ed99.js","track":0,"media":"../assets/media/4a301458009e7be8f26df25c38db13d9267a57db24e9729d28822f73c4127b46.wav"}],"../assets/media/16f2d3aeb9201c4b0efce51892cdf7bc9dc55da2fac40bddb7da8624c7429e83.mp3":[{"id":"B2_U03_T3.3_SHORT_S02_v01","audioId":"B2_U03_T3.3_SHORT_S02_v01","title":"Book 2 · Unit 3 · H1 · 听力材料 2","subtitle":"H1 · S02","duration":41.7578,"cues":[{"start":0.719,"end":1.699,"text":"Host: What kinds of ways?"},{"start":2.879,"end":15.2,"text":"Professor: Well, as you said, robots have been used in factories for years; Singapore and Korea are among the top five countries in the world with factory robots.","coverage":0.964},{"start":15.64,"end":19.57,"text":"And Japan has robots that serve food in some cafés.","coverage":0.818},{"start":20.48,"end":30.63,"text":"But now, in the US, some restaurants are testing robots which work in the kitchen and cook food, or which deliver pizza to homes.","coverage":0.958},{"start":31.04,"end":37.05,"text":"Also, robots are being developed to work on farms and help grow food.","coverage":1.0},{"start":37.44,"end":40.63,"text":"They can pick fruit, for example, or look at plant health.","coverage":1.0}],"file":"7e89d9e87b07e0b502ab.js","track":1,"media":"../assets/media/16f2d3aeb9201c4b0efce51892cdf7bc9dc55da2fac40bddb7da8624c7429e83.mp3"}],"../assets/media/5bc61b8ce2fd29d2e65c524d69eb64a6907641bdb2202d2722354ba1efed0669.wav":[{"id":"B2_U03_T3.3_SHORT_S03_v01","audioId":"B2_U03_T3.3_SHORT_S03_v01","title":"Book 2 · Unit 3 · H1 · 听力材料 3","subtitle":"H1 · S03","duration":37.75655328798186,"cues":[{"start":0.57,"end":1.39,"text":"Host: Interesting.","coverage":0.5},{"start":2.23,"end":5.66,"text":"But what about robots that look after or help people?","coverage":1.0},{"start":6.4,"end":7.58,"text":"Do we have those?","coverage":1.0},{"start":8.02,"end":20.26,"text":"Professor: Well, many companies are developing robots to help people who have a disability or people who can’t always do housework or care for themselves easily.","coverage":0.926},{"start":20.66,"end":28.69,"text":"They might need help from robots that can carry things around the house or deliver medicine on time.","coverage":1.0},{"start":29.07,"end":32.36,"text":"These types of robots are becoming less expensive.","coverage":1.0},{"start":32.66,"end":36.96,"text":"Having a robot means people are able to stay in their own homes.","coverage":1.0}],"file":"7e89d9e87b07e0b502ab.js","track":2,"media":"../assets/media/5bc61b8ce2fd29d2e65c524d69eb64a6907641bdb2202d2722354ba1efed0669.wav"}],"../assets/media/50ed2f90465c36e7232c450e6ee1d46300566036002ea5859bba35a4379833cf.wav":[{"id":"B2_U03_T3.3_SHORT_S04_v01","audioId":"B2_U03_T3.3_SHORT_S04_v01","title":"Book 2 · Unit 3 · H1 · 听力材料 4","subtitle":"H1 · S04","duration":39.99798185941043,"cues":[{"start":0,"end":5.55,"text":"Host: So do people have a much better quality of life thanks to these new types of robots?","coverage":0.944},{"start":6.36,"end":15.14,"text":"Professor: Yes, but at this time, it’s too expensive to have robots at home that can pick people up or feed them.","coverage":0.957},{"start":15.6,"end":23.45,"text":"Also, when robots were used in care homes, the nurses found that the robots didn’t save time.","coverage":1.0},{"start":24.62,"end":25.46,"text":"Host: Why is that?","coverage":0.75},{"start":25.88,"end":28.8,"text":"Professor: The robots had to be moved and watched.","coverage":0.889},{"start":29.12,"end":36.02,"text":"The nurses spent time looking after the robots and so they had less time to look after the people.","coverage":1.0},{"start":36.36,"end":39.19,"text":"They stopped using the robots due to the lost time.","coverage":1.0}],"file":"7e89d9e87b07e0b502ab.js","track":3,"media":"../assets/media/50ed2f90465c36e7232c450e6ee1d46300566036002ea5859bba35a4379833cf.wav"}],"../assets/media/b098f96b00a1b6f279b2e62363b6838ca9cd4abfb14b2c99ba61598739f65193.mp3":[{"id":"B2_U03_T3.3_SHORT_S05_v01","audioId":"B2_U03_T3.3_SHORT_S05_v01","title":"Book 2 · Unit 3 · H1 · 听力材料 5","subtitle":"H1 · S05","duration":37.9178,"cues":[{"start":0.5,"end":1.33,"text":"Host: I see.","coverage":0.667},{"start":2.52,"end":4.97,"text":"What are some other ways that robots are used?","coverage":1.0},{"start":6.04,"end":14.68,"text":"Professor: These days, people use robots for science research, to repair equipment in the ocean, and as assistants to doctors and librarians.","coverage":0.864},{"start":16.56,"end":16.64,"text":"Host: Really?","coverage":0.5},{"start":16.96,"end":19.64,"text":"What kind of science research?","coverage":1.0},{"start":20.0,"end":22.69,"text":"I know about robots on the planet Mars.","coverage":1.0},{"start":23.0,"end":29.5,"text":"Professor: Yes, robots go to places that we can’t go to collect information, like on Mars.","coverage":0.941},{"start":29.5,"end":37.23,"text":"They can prevent accidents by doing dangerous things and they can go into areas with bad pollution.","coverage":1.0}],"file":"7e89d9e87b07e0b502ab.js","track":4,"media":"../assets/media/b098f96b00a1b6f279b2e62363b6838ca9cd4abfb14b2c99ba61598739f65193.mp3"}],"../assets/media/e9ea5de0491118ff3b7a458b4ae5b44a8c096744b229483a2cd57100d75b3af8.mp3":[{"id":"B2_U03_T3.3_SHORT_S06_v01","audioId":"B2_U03_T3.3_SHORT_S06_v01","title":"Book 2 · Unit 3 · H1 · 听力材料 6","subtitle":"H1 · S06","duration":62.098095,"cues":[{"start":0,"end":3.3,"text":"Host: And you also said robots could be doctors or librarians.","coverage":0.818},{"start":4.74,"end":12.63,"text":"Does that mean I shouldn’t study for a degree in library studies because a robot is going to take all the librarians’ jobs?","coverage":0.958},{"start":13.51,"end":18.24,"text":"Professor: No, robots only help with the boring parts of being a librarian.","coverage":0.846},{"start":19.28,"end":25.5,"text":"They use bar codes to look for books on the shelves or put books in the right place.","coverage":1.0},{"start":26.71,"end":29.85,"text":"But what about a robot doctor?","coverage":1.0},{"start":30.42,"end":34.04,"text":"Am I going to see a robot when I go to the doctors?","coverage":1.0},{"start":34.4,"end":35.69,"text":"Professor: No, not yet.","coverage":0.75},{"start":35.94,"end":41.92,"text":"But doctors can use robotic arms to help them do surgery.","coverage":1.0},{"start":42.83,"end":46.55,"text":"People stay in hospital for a shorter time because of fewer problems.","coverage":1.0},{"start":47.34,"end":54.95,"text":"Host: Well, we’ve heard about robots that clean your house, cook food, do research, and even help your doctor, too.","coverage":0.952},{"start":56.22,"end":58.77,"text":"Host: OK, we have some questions coming in, so let’s hear the first one …","coverage":0.929}],"file":"7e89d9e87b07e0b502ab.js","track":5,"media":"../assets/media/e9ea5de0491118ff3b7a458b4ae5b44a8c096744b229483a2cd57100d75b3af8.mp3"}],"../assets/media/7e75148d824429ebf53940334cd91928b48dfcd1b2c8c05cef46fc67fe76ca47.mp3":[{"id":"PPT_7e75148d824429eb","audioId":"PPT_7e75148d824429eb","title":"Book 3 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 79","duration":239.49,"cues":[{"start":0.0,"end":2.22,"text":"one .two","coverage":1.0},{"start":2.22,"end":2.78,"text":"Hello,","coverage":1.0},{"start":3.2,"end":4.72,"text":"and thank you all for coming.","coverage":1.0},{"start":5.28,"end":9.56,"text":"I know you're all busy students, and I appreciate that you're here today.","coverage":1.0},{"start":10.2,"end":15.02,"text":"As we all know, there are many animals which are disappearing from our planet.","coverage":1.0},{"start":16.22,"end":17.5,"text":"Rhinos, orangutans,","coverage":1.0},{"start":17.82,"end":18.86,"text":"sea turtles...","coverage":1.0},{"start":18.86,"end":20.38,"text":"the list is shocking.","coverage":1.0},{"start":21.38,"end":25.52,"text":"Now, what do you think of when you hear African elephant?","coverage":1.0},{"start":25.52,"end":28.04,"text":"Perhaps something like intelligent,","coverage":1.0},{"start":28.5,"end":29.06,"text":"majestic,","coverage":1.0},{"start":29.72,"end":30.14,"text":"powerful.","coverage":1.0},{"start":30.98,"end":35.34,"text":"Now, even though these words describe these creatures perfectly,","coverage":1.0},{"start":35.84,"end":39.48,"text":"those three qualities may not be enough to save them.","coverage":1.0},{"start":40.08,"end":45.2,"text":"A century ago, there were around five million elephants across Africa.","coverage":1.0},{"start":45.82,"end":50.36,"text":"Today, it is believed that there are less than 500 ,000.","coverage":1.0},{"start":50.36,"end":55.46,"text":"In fact, both species of African elephants are endangered.","coverage":1.0},{"start":56.26,"end":60.4,"text":"While people are generally more familiar with the savanna elephant,","coverage":1.0},{"start":60.92,"end":64.7,"text":"I'm here today to talk about the African forest elephant,","coverage":1.0},{"start":65.32,"end":66.26,"text":"which is smaller,","coverage":1.0},{"start":66.6,"end":67.64,"text":"less well known,","coverage":1.0},{"start":67.96,"end":72.72,"text":"and it's critically endangered because of the threat that it faces from humans.","coverage":1.0},{"start":73.8,"end":81.72,"text":"The main human threat to forest elephants comes from poachers, who hunt them for their long, white, beautiful tusks.","coverage":1.0},{"start":82.16,"end":85.32,"text":"It's widely known that these tusks are made of ivory,","coverage":1.0},{"start":85.8,"end":91.36,"text":"a material that poachers sell to make a lot of money, even though it's illegal.","coverage":1.0},{"start":92.32,"end":96.3,"text":"The international trade of ivory was banned in 1989,","coverage":1.0},{"start":96.74,"end":102.84,"text":"yet several countries still allow ivory to be bought and sold across their borders.","coverage":1.0},{"start":103.3,"end":106.76,"text":"This has actually increased over recent years.","coverage":1.0},{"start":106.76,"end":111.08,"text":"The second threat is the loss of the elephant's habitat,","coverage":1.0},{"start":111.5,"end":117.36,"text":"which happens when humans destroy rainforest areas to make the land suitable for farming.","coverage":1.0},{"start":118.36,"end":126.56,"text":"This means the elephants have less space to live in, so the food they depend on for survival, such as fruit, grasses,","coverage":1.0},{"start":126.88,"end":127.64,"text":"and leaves,","coverage":1.0},{"start":128.06,"end":130.22,"text":"not only becomes less available,","coverage":1.0},{"start":130.52,"end":134.62,"text":"but also has to be shared between the same number of elephants.","coverage":1.0},{"start":134.62,"end":139.74,"text":"A third threat is contact between humans and elephants.","coverage":1.0},{"start":140.44,"end":145.96,"text":"Habitat loss sometimes forces elephants to leave the rainforest and go into villages,","coverage":1.0},{"start":146.44,"end":149.52,"text":"where they damage crops growing in farmers' fields.","coverage":1.0},{"start":150.12,"end":151.04,"text":"Because of this,","coverage":1.0},{"start":151.64,"end":154.34,"text":"local people sometimes kill the elephants.","coverage":1.0},{"start":155.0,"end":158.74,"text":"They see this as the only way to protect themselves,","coverage":1.0},{"start":159.22,"end":162.52,"text":"their families, their food, and their homes.","coverage":1.0},{"start":163.54,"end":164.22,"text":"However,","coverage":1.0},{"start":164.7,"end":165.9,"text":"there is good news.","coverage":1.0},{"start":166.26,"end":170.14,"text":"It may not be too late to save the African forest elephant.","coverage":1.0},{"start":170.94,"end":174.86,"text":"But there are several things that really ought to happen first.","coverage":1.0},{"start":175.76,"end":176.3,"text":"First,","coverage":1.0},{"start":176.62,"end":184.94,"text":"there needs to be an increase in the number of specially trained guards who work in the rainforests to catch the poachers.","coverage":1.0},{"start":184.94,"end":186.16,"text":"Second,","coverage":1.0},{"start":187.18,"end":194.26,"text":"governments must introduce an immediate and complete ban on anyone buying or selling ivory,","coverage":1.0},{"start":194.82,"end":197.16,"text":"even between countries sharing a border.","coverage":1.0},{"start":198.5,"end":198.94,"text":"Third,","coverage":1.0},{"start":199.48,"end":204.22,"text":"we have to find ways of reducing contact between humans and elephants.","coverage":1.0},{"start":204.76,"end":205.5,"text":"For instance,","coverage":1.0},{"start":206.02,"end":211.84,"text":"local communities should be helped to build suitable fences that can protect their land.","coverage":1.0},{"start":212.98,"end":213.72,"text":"So,","coverage":1.0},{"start":214.1,"end":215.06,"text":"to summarize,","coverage":1.0},{"start":215.74,"end":218.56,"text":"as well as habitat loss and human contact,","coverage":1.0},{"start":218.92,"end":222.0,"text":"the main threat to forest elephants comes from poaching.","coverage":1.0},{"start":222.54,"end":225.3,"text":"We've got to end the illegal trade of ivory.","coverage":1.0},{"start":225.86,"end":232.34,"text":"The governments and environmental organizations who can do this must not delay for a moment longer.","coverage":1.0},{"start":232.68,"end":233.58,"text":"Without a ban,","coverage":1.0},{"start":234.1,"end":237.6,"text":"the African forest elephant may soon become extinct.","coverage":1.0}],"file":"7ee99b6771e3d09a8a17.js","track":0,"media":"../assets/media/7e75148d824429ebf53940334cd91928b48dfcd1b2c8c05cef46fc67fe76ca47.mp3"}],"../assets/media/1bf0aeaf82e7968b7b33d2d67306101a68bfaebe042209f69de73e4a4c28873c.mp3":[{"id":"B3_U03_T3.3_SHORT_S02_v01","audioId":"B3_U03_T3.3_SHORT_S02_v01","title":"Book 3 · Unit 3 · 课后听力材料","subtitle":"Homework listening material","duration":35.828005,"cues":[{"start":0.0,"end":2.981,"text":"Mark, what’s happening in our cities?"},{"start":3.841,"end":10.78,"text":"Mark: It’s a fact that, in a great many cities, the traffic is more extreme than ever before.","coverage":0.947},{"start":11.12,"end":18.24,"text":"The primary cause is that there are so many private vehicles on the roads carrying only one or two people.","coverage":1.0},{"start":19.09,"end":29.61,"text":"Compare this to buses, which are by far the most efficient option for reducing traffic, as they can transport huge numbers of passengers at the same time.","coverage":1.0},{"start":29.96,"end":35.02,"text":"But people don’t seem to want to leave their expensive cars at home and take the bus instead.","coverage":1.0}],"file":"80b446eb529dbe388a9c.js","track":0,"media":"../assets/media/1bf0aeaf82e7968b7b33d2d67306101a68bfaebe042209f69de73e4a4c28873c.mp3"}],"../assets/media/9792dd26e61230623d241635ddff44e87e1022f5c759eb414afc3b86cf662d61.mp3":[{"id":"PPT_9792dd26e6123062","audioId":"PPT_9792dd26e6123062","title":"Book 2 · Unit 3 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 99","duration":148.43,"cues":[{"start":0.0,"end":1.84,"text":"three .five","coverage":1.0},{"start":3.02,"end":11.64,"text":"For a long time people have asked the same question Do computers stop us from learning and developing?","coverage":1.0},{"start":12.26,"end":13.84,"text":"Do they make us stupid?","coverage":1.0},{"start":14.64,"end":20.76,"text":"A recent study at Columbia University in New York looked at this question in","coverage":1.0},{"start":21.22,"end":30.64,"text":"particular how computers affect our memory They wanted to find out if computers have changed the way we remember information","coverage":1.0},{"start":32.1,"end":52.8,"text":"First the scientists did research on what happens when people are asked difficult questions They found that what we think when we hear difficult questions has changed because of websites like Google When people were asked difficult questions in the past","coverage":1.0},{"start":53.36,"end":69.02,"text":"Scientists believe they tried to think of the answer to the question However because of modern technology the first thing people think about now is how to find the answer They don't try to answer it themselves","coverage":1.0},{"start":69.58,"end":77.88,"text":"For example, they think about what they might put into Google, but in the past they thought about the question itself","coverage":1.0},{"start":79.16,"end":109.58,"text":"second Scientists found that computers have changed the type of information we remember there are advantages and disadvantages to these changes a Disadvantage is that it seems that people now forget facts Especially if they know the information will be saved in a file on the other hand an advantage Is that they remember the location of the fact in other words where to find it in?","coverage":1.0},{"start":109.58,"end":110.36,"text":"one test","coverage":1.0},{"start":110.94,"end":126.4,"text":"scientists told university students some facts and Also where the facts were saved in a file Most of the students couldn't remember the facts, but they were able to remember the files and the location of the facts","coverage":1.0},{"start":126.94,"end":134.76,"text":"In conclusion it seems that computers are not making us stupid, but they are making us lazy","coverage":1.0},{"start":135.76,"end":146.5,"text":"Scientists believe that we are spending time remembering where and how we can find things But we're not trying to remember the information itself anymore","coverage":1.0}],"file":"81bc7f645da58faab153.js","track":0,"media":"../assets/media/9792dd26e61230623d241635ddff44e87e1022f5c759eb414afc3b86cf662d61.mp3"}],"../assets/media/ca574807c562a97c6f449a634d4f8752d92a384c4a86c93398e68c6839c6ac2f.wav":[{"id":"B2_U02_T2.1_LONG_L02_v01","audioId":"B2_U02_T2.1_LONG_L02_v01","title":"Book 2 · Unit 2 · H3 · 听力材料 2","subtitle":"H3 · L02","duration":140.7880045351474,"cues":[{"start":0.71,"end":6.09,"text":"Reporter 1: Olivia, like many others, is really enjoying the Vivid Sydney festival.","coverage":0.769},{"start":7.74,"end":15.07,"text":"Nowadays, around the world, there are many festivals, often based on nature, food or culture.","coverage":0.933},{"start":15.48,"end":19.61,"text":"Take the Cherry Blossom Festival in Japan, for example.","coverage":1.0},{"start":19.96,"end":26.23,"text":"In Tokyo, the capital of Japan, the Cherry Blossom Festival is held in early April.","coverage":1.0},{"start":26.96,"end":30.49,"text":"It is an important festival celebrating nature.","coverage":1.0},{"start":30.8,"end":37.98,"text":"The actual dates change every year because the celebration happens only when the trees have cherry blossoms.","coverage":0.941},{"start":39.0,"end":49.67,"text":"So, it is a little different from a festival that has the same date every year and it’s not organized in the same way as many other festivals.","coverage":1.0},{"start":50.04,"end":53.94,"text":"Our reporter Mike Pearce went to Tokyo to find out.","coverage":0.9},{"start":54.95,"end":56.91,"text":"Reporter 2: Today, I am talking with Yuki.","coverage":0.625},{"start":57.88,"end":62.7,"text":"She sells food during the Cherry Blossom Festival in Ueno Park in Tokyo.","coverage":0.923},{"start":63.04,"end":63.3,"text":"Hi, Yuki.","coverage":0.5},{"start":64.48,"end":64.88,"text":"Yuki: Hi.","coverage":0.5},{"start":66.21,"end":69.01,"text":"Welcome to the Cherry Blossom Festival!","coverage":1.0},{"start":70.09,"end":70.4,"text":"Reporter 2: Thanks.","coverage":0.333},{"start":70.92,"end":72.54,"text":"So, what happens here?","coverage":1.0},{"start":72.84,"end":78.28,"text":"Yuki: Well, as you can see, it’s a cherry blossom festival.","coverage":0.917},{"start":78.72,"end":82.98,"text":"It is a celebration of spring and the cherry flowers.","coverage":1.0},{"start":83.32,"end":87.64,"text":"So, it doesn’t have specific activities that people do.","coverage":1.0},{"start":88.77,"end":95.38,"text":"Instead, people come to enjoy the cherry blossoms and have a picnic under the trees.","coverage":0.933},{"start":95.8,"end":101.88,"text":"We have about a thousand trees, full of beautiful flowers.","coverage":1.0},{"start":102.44,"end":105.8,"text":"Reporter 2: Do you have many people here from other countries?","coverage":0.818},{"start":106.81,"end":106.82,"text":"Yuki: Yes.","coverage":0.5},{"start":107.56,"end":111.19,"text":"Our visitors are from all over the world.","coverage":1.0},{"start":111.56,"end":120.96,"text":"In addition to the cherry blossoms, there are lots of food stalls and people can hire a boat to go around the lake too.","coverage":0.958},{"start":121.36,"end":125.37,"text":"There are many beautiful, natural places here.","coverage":1.0},{"start":125.72,"end":136.48,"text":"Some people prefer to visit some of the park’s many museums, but I think Tokyo is one of the best places to come for the Cherry Blossom Festival.","coverage":1.0},{"start":136.76,"end":139.35,"text":"Reporter 2: Well, I hope you enjoy the rest of the event!","coverage":0.833}],"file":"829e0da58e7f1f54295e.js","track":1,"media":"../assets/media/ca574807c562a97c6f449a634d4f8752d92a384c4a86c93398e68c6839c6ac2f.wav"}],"../assets/media/7fe3e7ea6da39fe91f3a39672de7968448a8071e749c2f0515c470ceafca37b0.mp3":[{"id":"PPT_7fe3e7ea6da39fe9","audioId":"PPT_7fe3e7ea6da39fe9","title":"Book 2 · Unit 2 · RW · READING 1","subtitle":"READING 1 · source slide 50","duration":185.39,"cues":[{"start":1.04,"end":1.84,"text":"celebrate","coverage":1.0},{"start":3.24,"end":4.04,"text":"Pinatas","coverage":1.0},{"start":4.58,"end":9.2,"text":"In Mexico, people often have pinatas at their parties.","coverage":1.0},{"start":9.9,"end":15.6,"text":"Parents put chocolates and other sweets inside the pinata and hang it on a tree.","coverage":1.0},{"start":16.36,"end":18.84,"text":"Children hit the pinata with a stick.","coverage":1.0},{"start":19.4,"end":23.22,"text":"It breaks and the sweets fall out onto the ground.","coverage":1.0},{"start":25.44,"end":26.0,"text":"Noodles","coverage":1.0},{"start":26.52,"end":27.86,"text":"In China,","coverage":1.0},{"start":28.24,"end":37.08,"text":"people celebrate weddings with an eight course meal, because the word eight in Chinese sounds like the word for good luck.","coverage":1.0},{"start":38.06,"end":41.46,"text":"The last dish of the meal is always noodles.","coverage":1.0},{"start":42.12,"end":44.46,"text":"The noodles are long and thin.","coverage":1.0},{"start":45.24,"end":47.52,"text":"You have to eat them in one piece.","coverage":1.0},{"start":47.84,"end":49.12,"text":"You can't cut them.","coverage":1.0},{"start":49.88,"end":51.32,"text":"In Chinese culture,","coverage":1.0},{"start":51.8,"end":53.44,"text":"long noodles are lucky.","coverage":1.0},{"start":53.44,"end":57.86,"text":"Long noodles mean you will have a long life.","coverage":1.0},{"start":60.24,"end":61.16,"text":"Mother's Day","coverage":1.0},{"start":61.68,"end":66.66,"text":"Many people around the world honor their mothers on Mother's Day.","coverage":1.0},{"start":67.2,"end":68.2,"text":"In the UK,","coverage":1.0},{"start":68.72,"end":72.3,"text":"Mother's Day is celebrated in March or April.","coverage":1.0},{"start":73.16,"end":77.2,"text":"Sons and daughters like to give their mother a day to rest,","coverage":1.0},{"start":77.52,"end":83.04,"text":"so they might surprise her by cleaning the house or cooking a nice meal for her.","coverage":1.0},{"start":83.04,"end":87.76,"text":"They also give her gifts such as flowers or jewelry.","coverage":1.0},{"start":88.78,"end":93.5,"text":"Many families take their mother to a restaurant for lunch or dinner.","coverage":1.0},{"start":95.42,"end":97.12,"text":"New Year's Eve","coverage":1.0},{"start":97.64,"end":101.66,"text":"London celebrates New Year's Eve in a big way.","coverage":1.0},{"start":102.3,"end":107.47,"text":"Thousands of people go to the River Thames and then when it is dark outside,","coverage":1.0},{"start":108.36,"end":114.36,"text":"fireworks light up the sky and Big Ben, the bell in London's famous clock tower,","coverage":1.0},{"start":114.68,"end":115.8,"text":"chimes at midnight.","coverage":1.0},{"start":116.78,"end":121.48,"text":"The next day, people eat a big meal with family and friends,","coverage":1.0},{"start":121.82,"end":125.34,"text":"go for a walk or just relax at home.","coverage":1.0},{"start":127.44,"end":128.72,"text":"Coming of Age Day","coverage":1.0},{"start":129.4,"end":130.44,"text":"In Japan,","coverage":1.0},{"start":130.78,"end":135.54,"text":"people celebrate Coming of Age Day or Seijin Nohi","coverage":1.0},{"start":135.94,"end":138.64,"text":"on the second Monday in January.","coverage":1.0},{"start":139.36,"end":140.88,"text":"On this holiday,","coverage":1.0},{"start":141.62,"end":154.08,"text":"Japan congratulates people who have turned or will turn 20 years old between the second of April of the past year and the first of April of the current year.","coverage":1.0},{"start":154.88,"end":163.92,"text":"In Japanese culture, this is the age when teenagers become adults and take on the responsibilities of being an adult.","coverage":1.0},{"start":164.72,"end":169.64,"text":"Young women usually wear a traditional furisode kimono,","coverage":1.0},{"start":170.24,"end":173.5,"text":"while young men often wear Western -style suits,","coverage":1.0},{"start":174.24,"end":177.54,"text":"and they attend a ceremony in their area.","coverage":1.0},{"start":178.26,"end":183.46,"text":"They receive small presents and celebrate with their friends after the ceremony.","coverage":1.0}],"file":"83a614c3701dbb982eab.js","track":0,"media":"../assets/media/7fe3e7ea6da39fe91f3a39672de7968448a8071e749c2f0515c470ceafca37b0.mp3"}],"../assets/media/ee4ee5dd52201715c930952f06342618453680e08e0ef1b1bea0607817429887.mp3":[{"id":"PPT_ee4ee5dd52201715","audioId":"PPT_ee4ee5dd52201715","title":"Book 2 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 51","duration":40.28,"cues":[{"start":0.0,"end":1.72,"text":"Unit three,","coverage":1.0},{"start":2.46,"end":3.44,"text":"three .one","coverage":1.0},{"start":5.2,"end":6.0,"text":"one","coverage":1.0},{"start":6.6,"end":7.74,"text":"sort","coverage":1.0},{"start":9.64,"end":10.48,"text":"two","coverage":1.0},{"start":11.16,"end":12.12,"text":"cheap","coverage":1.0},{"start":13.52,"end":14.92,"text":"three","coverage":1.0},{"start":15.6,"end":16.56,"text":"wash","coverage":1.0},{"start":18.24,"end":19.3,"text":"four","coverage":1.0},{"start":19.88,"end":20.74,"text":"see","coverage":1.0},{"start":22.32,"end":23.72,"text":"five","coverage":1.0},{"start":24.48,"end":25.34,"text":"sheet","coverage":1.0},{"start":26.74,"end":28.14,"text":"six","coverage":1.0},{"start":28.96,"end":29.68,"text":"chair","coverage":1.0},{"start":31.18,"end":32.0,"text":"seven","coverage":1.0},{"start":32.58,"end":34.2,"text":"catch","coverage":1.0},{"start":36.0,"end":36.78,"text":"eight","coverage":1.0},{"start":37.6,"end":38.3,"text":"shoes","coverage":1.0}],"file":"84c27e162a613701dc46.js","track":0,"media":"../assets/media/ee4ee5dd52201715c930952f06342618453680e08e0ef1b1bea0607817429887.mp3"}],"../assets/media/13931e0478548952ada0e43bc1577f5467d6cc09cb16bef0a78d5df249236686.mp3":[{"id":"B3_U03_T3.3_SHORT_S04_v01","audioId":"B3_U03_T3.3_SHORT_S04_v01","title":"Book 3 · Unit 3 · H1 · 听力材料 4","subtitle":"H1 · 3.3-S04","duration":40.37229,"cues":[{"start":0.33,"end":3.08,"text":"Host: Should we blame car drivers for all this, then?","coverage":0.9},{"start":3.4,"end":5.4,"text":"Mark: It’s not always their fault.","coverage":0.857},{"start":6.13,"end":10.7,"text":"Traditional traffic signals in so many of our cities are years old now.","coverage":1.0},{"start":11.39,"end":14.19,"text":"They always change colour after a certain number of seconds.","coverage":0.9},{"start":15.23,"end":20.04,"text":"That’s not a sensible idea, when we consider the number of vehicles driving today.","coverage":1.0},{"start":20.85,"end":29.09,"text":"For instance, a driver might see a green light and continue, but immediately join a long queue of vehicles that isn’t moving.","coverage":0.957},{"start":29.72,"end":34.53,"text":"Then, when the lights turn back to red, they are parked across a busy junction.","coverage":1.0},{"start":35.5,"end":38.53,"text":"That usually leads to all sorts of delays over the day.","coverage":1.0}],"file":"84c4ea8b226ac0c635aa.js","track":3,"media":"../assets/media/13931e0478548952ada0e43bc1577f5467d6cc09cb16bef0a78d5df249236686.mp3"}],"../assets/media/5e525336622a5f012a098dcdba732e6d054b1b1ff94061d295453fcee93739cb.mp3":[{"id":"B3_U03_T3.4_SHORT_S01_v01","audioId":"B3_U03_T3.4_SHORT_S01_v01","title":"Book 3 · Unit 3 · H1 · 听力材料 5","subtitle":"H1 · 3.4-S01","duration":57.496576,"cues":[{"start":2.23,"end":4.7,"text":"Host: And how can we solve these problems?","coverage":0.875},{"start":5.27,"end":8.0,"text":"Mark: Let’s think again about traffic lights.","coverage":0.875},{"start":8.33,"end":21.36,"text":"Because of improvements in technology, modern traffic signals can measure how quickly the vehicles are moving along the roads, or see whether there’s been a crash, and send this information back to a control centre.","coverage":0.972},{"start":22.09,"end":23.38,"text":"Host: I’ve heard about this.","coverage":0.833},{"start":24.18,"end":37.69,"text":"It means that the traffic controllers – either human or computer – can check for changes in traffic throughout the day and figure out the best way to organise the signals to keep everything moving.","coverage":0.939},{"start":38.33,"end":38.57,"text":"Mark: Yes.","coverage":0.5},{"start":39.05,"end":45.7,"text":"They don’t have to follow the same, fixed timings for the lights all day long, like signals used to do.","coverage":0.952},{"start":46.22,"end":52.68,"text":"And, although it’s expensive to put in these signals across a whole city, it’s far better than doing nothing.","coverage":1.0},{"start":53.33,"end":55.71,"text":"Host: Technology – where would we be without it?","coverage":0.875},{"start":56.33,"end":56.89,"text":"Mark: Exactly.","coverage":0.5}],"file":"84c4ea8b226ac0c635aa.js","track":4,"media":"../assets/media/5e525336622a5f012a098dcdba732e6d054b1b1ff94061d295453fcee93739cb.mp3"}],"../assets/media/4c422808cca55644103e5716ece2c674ba120ee736964914af24d86da1e02a6e.mp3":[{"id":"B3_U03_T3.4_SHORT_S02_v01","audioId":"B3_U03_T3.4_SHORT_S02_v01","title":"Book 3 · Unit 3 · H1 · 听力材料 6","subtitle":"H1 · 3.4-S02","duration":48.001066,"cues":[{"start":0.48,"end":7.0,"text":"Which reminds me of another way to reduce traffic – businesses replacing their vehicles with drones.","coverage":0.933},{"start":7.84,"end":7.97,"text":"Host: Okay.","coverage":0.5},{"start":8.52,"end":9.65,"text":"Tell me more.","coverage":1.0},{"start":10.0,"end":20.73,"text":"Mark: Some tasks city governments need to do, such as checking electricity lines, don’t necessarily need to be carried out by a single person arriving in a big vehicle.","coverage":0.967},{"start":21.0,"end":28.67,"text":"A drone with a camera could send this information to engineers, who only need to go out if there is a problem.","coverage":1.0},{"start":29.0,"end":33.0,"text":"Think of how many work vans this could take off the roads every day ...","coverage":0.929},{"start":33.0,"end":35.07,"text":"Host: And delivery vans ...","coverage":0.75},{"start":35.5,"end":37.7,"text":"Mark: That’s another good example.","coverage":0.833},{"start":38.0,"end":44.7,"text":"In some cities, businesses can use drones to deliver small parcels, which is fantastic.","coverage":1.0},{"start":45.0,"end":47.67,"text":"It means even fewer vehicles on the roads.","coverage":1.0}],"file":"84c4ea8b226ac0c635aa.js","track":5,"media":"../assets/media/4c422808cca55644103e5716ece2c674ba120ee736964914af24d86da1e02a6e.mp3"}],"../assets/media/49731926a1aa4ed2e5c8c98b7ee02957739c17c269f2782d1994034c260aabf9.mp3":[{"id":"B3_U03_T3.4_SHORT_S03_v01","audioId":"B3_U03_T3.4_SHORT_S03_v01","title":"Book 3 · Unit 3 · H1 · 听力材料 7","subtitle":"H1 · 3.4-S03","duration":70.773719,"cues":[{"start":0.26,"end":4.59,"text":"Host: What would you say to people who refuse to give up driving their cars, ever?","coverage":0.875},{"start":5.0,"end":9.66,"text":"Mark: I honestly think people should try to avoid driving as much as possible.","coverage":0.929},{"start":10.24,"end":13.07,"text":"But, if they can’t, they should consider their behaviour.","coverage":0.9},{"start":14.0,"end":16.74,"text":"It’s not just bad parking that causes traffic issues.","coverage":1.0},{"start":17.26,"end":20.63,"text":"Everyone needs to be a lot more responsible as drivers.","coverage":1.0},{"start":21.26,"end":22.45,"text":"Host: In what way?","coverage":0.75},{"start":23.22,"end":27.64,"text":"Mark: When people get behind the steering wheel, they often become less helpful than normal.","coverage":0.933},{"start":28.26,"end":36.75,"text":"Like when someone is turning into a side street – that often means driving across the other lane, past vehicles going in the opposite direction.","coverage":1.0},{"start":37.16,"end":43.84,"text":"If no one slows down to let in the person who wants to turn, the traffic gets worse and worse behind them.","coverage":1.0},{"start":44.26,"end":51.75,"text":"Even more so if someone stops in traffic with their car across the side street that person wants to turn into.","coverage":1.0},{"start":52.845,"end":53.165,"text":"Host: Agh!"},{"start":53.745,"end":57.63,"text":"Listeners, if that doesn’t annoy you as well, you’re a better person than me!","coverage":1.0},{"start":58.26,"end":59.24,"text":"Mark: Me too.","coverage":0.667},{"start":60.11,"end":64.72,"text":"Please, everyone, stop and give people enough space to turn into side streets!","coverage":1.0},{"start":65.26,"end":67.64,"text":"Host: Mark, thanks for joining me.","coverage":0.833},{"start":68.26,"end":68.9,"text":"Mark: Thank you.","coverage":0.667}],"file":"84c4ea8b226ac0c635aa.js","track":6,"media":"../assets/media/49731926a1aa4ed2e5c8c98b7ee02957739c17c269f2782d1994034c260aabf9.mp3"}],"../assets/media/25963803e9972d24d154cffc2107819ca2ea9ba091f7369f008f57609f04a9ec.mp3":[{"id":"B3_U03_T3.6_SHORT_S02_v01","audioId":"B3_U03_T3.6_SHORT_S02_v01","title":"Book 3 · Unit 3 · H1 · 听力材料 8","subtitle":"H1 · 3.6-S02","duration":45.754535,"cues":[{"start":0.02,"end":2.98,"text":"So, the biggest issue is safety.","coverage":1.0},{"start":3.96,"end":11.7,"text":"A lot of people would love to cycle to work, but they’re scared – they feel that it’s just too dangerous.","coverage":1.0},{"start":12.02,"end":21.41,"text":"This is because there’s a lot of traffic during rush hour, when most people drive to or from work, and there’s very little space for cyclists.","coverage":1.0},{"start":21.78,"end":29.31,"text":"Many of the cycle lanes we have are too narrow and some of the busiest streets don’t even have cycle lanes.","coverage":1.0},{"start":29.78,"end":34.13,"text":"What’s more, many drivers don’t have respect for cyclists.","coverage":1.0},{"start":34.54,"end":38.98,"text":"Cars sometimes even drive in the cycle lanes to pass other cars.","coverage":1.0},{"start":39.46,"end":44.94,"text":"Of course, if a car hits a bicycle, it’s going to injure or even kill the cyclist.","coverage":1.0}],"file":"84c4ea8b226ac0c635aa.js","track":7,"media":"../assets/media/25963803e9972d24d154cffc2107819ca2ea9ba091f7369f008f57609f04a9ec.mp3"}],"../assets/media/c11e6c936a55ae2a33bb4c64b77810c0c48d2c04e701f906ea93068e532c2804.mp3":[{"id":"B3_U03_T3.6_SHORT_S03_v01","audioId":"B3_U03_T3.6_SHORT_S03_v01","title":"Book 3 · Unit 3 · H1 · 听力材料 9","subtitle":"H1 · 3.6-S03","duration":19.188005,"cues":[{"start":0,"end":2.48,"text":"A second issue is storage.","coverage":1.0},{"start":3.16,"end":8.45,"text":"Many people don’t have a safe place to put their bicycles while they’re at work.","coverage":1.0},{"start":8.8,"end":13.47,"text":"They worry that if they leave their bicycle outside, it’ll get stolen.","coverage":1.0},{"start":13.76,"end":18.24,"text":"Also, it’ll get wet when it rains and might get damaged over time.","coverage":1.0}],"file":"84c4ea8b226ac0c635aa.js","track":8,"media":"../assets/media/c11e6c936a55ae2a33bb4c64b77810c0c48d2c04e701f906ea93068e532c2804.mp3"}],"../assets/media/8a6910e8ce90b369ad07493d4ff3ddfb76b1543d9c8836b4c4e78f600091aa0b.mp3":[{"id":"B3_U03_T3.7_SHORT_S01_v01","audioId":"B3_U03_T3.7_SHORT_S01_v01","title":"Book 3 · Unit 3 · H1 · 听力材料 10","subtitle":"H1 · 3.7-S01","duration":37.094943,"cues":[{"start":0.27,"end":5.54,"text":"Woman: Now I’d like to share some possible solutions.","coverage":0.9},{"start":6.27,"end":15.93,"text":"First, to improve safety, I’d suggest that police officers give big fines to drivers who break the law by driving in a cycle lane.","coverage":1.0},{"start":16.27,"end":23.49,"text":"Also, I’d like to see wider cycle lanes to allow more bicycles to pass at the same time.","coverage":1.0},{"start":24.18,"end":29.55,"text":"We should also add cycle lanes to busy streets which don’t have them yet.","coverage":1.0},{"start":30.27,"end":36.62,"text":"These proposals would prevent cars from hitting cyclists and would save lives.","coverage":1.0}],"file":"84c4ea8b226ac0c635aa.js","track":9,"media":"../assets/media/8a6910e8ce90b369ad07493d4ff3ddfb76b1543d9c8836b4c4e78f600091aa0b.mp3"}],"../assets/media/24b7807cbca5fddb66b075a85c38feae0657103155574771fd37aa9b813f69b3.mp3":[{"id":"B3_U03_T3.7_SHORT_S03_v01","audioId":"B3_U03_T3.7_SHORT_S03_v01","title":"Book 3 · Unit 3 · H1 · 听力材料 11","subtitle":"H1 · 3.7-S03","duration":41.420658,"cues":[{"start":0.67,"end":2.0,"text":"Finally, convenience.","coverage":1.0},{"start":3.04,"end":8.21,"text":"In my opinion, we should make it easier to take bicycles on public transport.","coverage":1.0},{"start":8.67,"end":12.74,"text":"For example, we could put cycle racks on the outside of buses.","coverage":1.0},{"start":13.08,"end":17.46,"text":"That way, people wouldn’t have to cycle at night or in bad weather.","coverage":1.0},{"start":17.76,"end":24.7,"text":"And people who live far from work could cycle part of the way to work and take public transport the rest of the way.","coverage":1.0},{"start":25.26,"end":29.02,"text":"As a result, more people could cycle to work.","coverage":1.0},{"start":29.56,"end":32.5,"text":"Well, thank you again for listening to my ideas.","coverage":1.0},{"start":32.88,"end":39.33,"text":"I hope this is the beginning of a conversation about how we can make this a great city for cyclists!","coverage":1.0}],"file":"84c4ea8b226ac0c635aa.js","track":10,"media":"../assets/media/24b7807cbca5fddb66b075a85c38feae0657103155574771fd37aa9b813f69b3.mp3"}],"../assets/media/8726839751e843456891ce8f6b228331f751c355685639988a1182b863dc928f.mp3":[{"id":"PPT_8726839751e84345","audioId":"PPT_8726839751e84345","title":"Book 3 · Unit 7 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 98","duration":249.97,"cues":[{"start":0.0,"end":1.66,"text":"seven .seven","coverage":1.0},{"start":1.66,"end":8.38,"text":"In today's show we'll be interviewing the talented fashion designer Aisha Al -Husseini.","coverage":1.0},{"start":8.84,"end":11.18,"text":"Hot on the heels of her Fashion Week show,","coverage":1.0},{"start":11.48,"end":14.5,"text":"Aisha's new collection is very popular in Doha.","coverage":1.0},{"start":15.14,"end":18.68,"text":"She got the attention of the fashion world with her unique designs,","coverage":1.0},{"start":19.22,"end":22.84,"text":"which combine traditional Muslim fashion with French chic.","coverage":1.0},{"start":23.46,"end":25.56,"text":"Aisha, thank you for coming to the studio.","coverage":1.0},{"start":25.78,"end":26.88,"text":"Thank you for having me.","coverage":1.0},{"start":26.88,"end":28.12,"text":"First of all,","coverage":1.0},{"start":28.46,"end":30.92,"text":"can you tell me where you get your ideas from?","coverage":1.0},{"start":31.64,"end":33.44,"text":"Well, I come from a Muslim family.","coverage":1.0},{"start":33.98,"end":35.94,"text":"My parents are both from Qatar.","coverage":1.0},{"start":36.52,"end":39.1,"text":"I was born there but then we travelled a lot.","coverage":1.0},{"start":39.64,"end":43.26,"text":"I went to school in New York and I went to a design school there.","coverage":1.0},{"start":43.88,"end":48.36,"text":"These days I spend my time travelling between Qatar and the United States.","coverage":1.0},{"start":48.84,"end":51.8,"text":"How did you feel about growing up in New York?","coverage":1.0},{"start":51.8,"end":57.82,"text":"Well, as a teenager in New York, I had a lot of problems trying to dress in a modest way.","coverage":1.0},{"start":58.34,"end":59.12,"text":"For example,","coverage":1.0},{"start":59.58,"end":61.62,"text":"when you look at summer fashion in New York,","coverage":1.0},{"start":62.0,"end":63.92,"text":"the trend is always to wear skirts,","coverage":1.0},{"start":64.36,"end":66.54,"text":"shorts and sleeveless shirts.","coverage":1.0},{"start":67.26,"end":70.88,"text":"I didn't feel comfortable wearing them but at the same time,","coverage":1.0},{"start":71.18,"end":75.32,"text":"my friends thought it was strange to wear long sleeves and jeans in the summer.","coverage":1.0},{"start":75.84,"end":79.12,"text":"So I've always tried to combine my culture with fashion.","coverage":1.0},{"start":79.66,"end":82.38,"text":"As a teenager, I would make my own clothes,","coverage":1.0},{"start":82.84,"end":85.92,"text":"like colourful skirts and scarves.","coverage":1.0},{"start":85.96,"end":88.44,"text":"I wanted my designs to be individual.","coverage":1.0},{"start":89.08,"end":94.06,"text":"They were unique and eventually people admired my clothes rather than laughed at me.","coverage":1.0},{"start":94.4,"end":94.88,"text":"I see.","coverage":1.0},{"start":95.32,"end":99.2,"text":"So do you know what ideas most people have about Muslim clothes?","coverage":1.0},{"start":99.82,"end":100.42,"text":"Well,","coverage":1.0},{"start":101.14,"end":104.62,"text":"I think there's a lot of misunderstanding about Muslim clothes.","coverage":1.0},{"start":105.28,"end":107.98,"text":"The thing is that when you say Muslim fashion,","coverage":1.0},{"start":108.42,"end":115.58,"text":"people in New York think of a burqa, you know, like the blue or black cloaks which cover women from head to toe.","coverage":1.0},{"start":115.92,"end":119.22,"text":"And could you explain what you think Muslim fashion is?","coverage":1.0},{"start":119.62,"end":121.04,"text":"Let me give you an example.","coverage":1.0},{"start":121.48,"end":123.58,"text":"When I first started at design school,","coverage":1.0},{"start":124.08,"end":133.66,"text":"my teachers would ask me strange questions such as how I was going to stay in the fashion business if I'm not going to design miniskirts or sleeveless shirts.","coverage":1.0},{"start":134.1,"end":135.64,"text":"But as far as I'm concerned,","coverage":1.0},{"start":136.02,"end":138.98,"text":"there is much more to fashion than showing your body.","coverage":1.0},{"start":139.72,"end":146.36,"text":"There are millions of Muslim women who live in the United States and Europe who want to wear fashionable clothes.","coverage":1.0},{"start":146.92,"end":150.46,"text":"There are also women who simply like to dress in a modest way.","coverage":1.0},{"start":150.46,"end":155.1,"text":"So are you saying that there is a need for fashionable clothes for Muslim women?","coverage":1.0},{"start":155.82,"end":155.96,"text":"Absolutely.","coverage":1.0},{"start":156.52,"end":159.78,"text":"We want to be fashionable and be ourselves at the same time.","coverage":1.0},{"start":160.34,"end":161.52,"text":"My feeling is this.","coverage":1.0},{"start":161.88,"end":167.32,"text":"I want to create clothes which are modest but at the same time give women confidence,","coverage":1.0},{"start":167.68,"end":170.14,"text":"clothes which allow women to be themselves.","coverage":1.0},{"start":170.68,"end":171.58,"text":"I see what you mean.","coverage":1.0},{"start":171.92,"end":174.36,"text":"So how would you describe your style?","coverage":1.0},{"start":174.36,"end":175.08,"text":"Well,","coverage":1.0},{"start":175.52,"end":181.16,"text":"many reviewers have described my style as traditional chic and I guess I'd agree with them.","coverage":1.0},{"start":181.68,"end":187.4,"text":"What I think is that combining traditional with chic is a huge area in fashion.","coverage":1.0},{"start":188.06,"end":190.92,"text":"I keep my eye on the fashion trends in other countries.","coverage":1.0},{"start":191.48,"end":200.34,"text":"When you look at the works of other designers in China and India, you can see that many traditional styles are being reused by young designers.","coverage":1.0},{"start":200.34,"end":201.92,"text":"Above all,","coverage":1.0},{"start":202.24,"end":205.84,"text":"people like to be individuals and show their cultural roots.","coverage":1.0},{"start":206.3,"end":208.36,"text":"They like to show where they come from.","coverage":1.0},{"start":208.66,"end":210.06,"text":"As I understand it,","coverage":1.0},{"start":210.38,"end":215.1,"text":"your designs are must -haves for Muslim women outside the United States as well.","coverage":1.0},{"start":215.56,"end":217.06,"text":"Could you tell me more about that?","coverage":1.0},{"start":217.4,"end":217.94,"text":"Yes.","coverage":1.0},{"start":218.4,"end":220.52,"text":"In addition to New York and Paris,","coverage":1.0},{"start":220.92,"end":225.56,"text":"I sell my collection in big cities like Doha, Dubai and Abu Dhabi.","coverage":1.0},{"start":225.56,"end":231.44,"text":"Another thing is that I also receive requests for my clothes from women in Pakistan,","coverage":1.0},{"start":231.88,"end":232.36,"text":"Indonesia,","coverage":1.0},{"start":233.08,"end":234.22,"text":"Singapore and Malaysia.","coverage":1.0},{"start":234.54,"end":236.78,"text":"So someday I might open stores there.","coverage":1.0},{"start":237.1,"end":239.02,"text":"Well, I hope you decide to go for it.","coverage":1.0},{"start":239.18,"end":242.26,"text":"That would make a lot of women around the world very happy.","coverage":1.0},{"start":242.88,"end":243.58,"text":"So Aisha,","coverage":1.0},{"start":244.0,"end":245.88,"text":"thank you for coming to the studio today.","coverage":1.0},{"start":246.1,"end":247.12,"text":"It was my pleasure.","coverage":1.0},{"start":247.48,"end":247.94,"text":"Anytime.","coverage":1.0}],"file":"865d80893c48c17b1034.js","track":0,"media":"../assets/media/8726839751e843456891ce8f6b228331f751c355685639988a1182b863dc928f.mp3"}],"../assets/media/fd97f00863036b1cde7b2f95a2505a5a253a90dd2702c90720afb1370c645421.mp3":[{"id":"PPT_fd97f00863036b1c","audioId":"PPT_fd97f00863036b1c","title":"Book 2 · Unit 5 · RW · READING 1","subtitle":"READING 1 · source slide 43","duration":189.65,"cues":[{"start":0.0,"end":3.22,"text":"Sporting news Home","coverage":1.0},{"start":4.0,"end":4.9,"text":"About","coverage":1.0},{"start":6.0,"end":6.54,"text":"News","coverage":1.0},{"start":7.94,"end":8.44,"text":"Contact","coverage":1.0},{"start":9.82,"end":13.12,"text":"More Five unusual sports","coverage":1.0},{"start":13.64,"end":17.28,"text":"The most unusual sports from around the world.","coverage":1.0},{"start":18.44,"end":20.66,"text":"Every country has a national sport,","coverage":1.0},{"start":21.2,"end":25.0,"text":"and most popular sports are now played across the world.","coverage":1.0},{"start":25.0,"end":28.86,"text":"Most people have heard of sports like football,","coverage":1.0},{"start":29.34,"end":29.74,"text":"basketball,","coverage":1.0},{"start":30.08,"end":30.42,"text":"baseball,","coverage":1.0},{"start":30.74,"end":31.34,"text":"and cricket.","coverage":1.0},{"start":31.96,"end":32.48,"text":"However,","coverage":1.0},{"start":32.82,"end":39.78,"text":"in most countries, people also play unusual sports with strange and interesting rules.","coverage":1.0},{"start":40.56,"end":45.34,"text":"Here are our top five unusual sports from around the world.","coverage":1.0},{"start":47.34,"end":54.1,"text":"Coney Island Polar Bear Plunge People go swimming in the Atlantic Ocean in the winter.","coverage":1.0},{"start":54.1,"end":64.42,"text":"They go swimming at the beach on Coney Island in New York City every Sunday from October to April and also on New Year's Day.","coverage":1.0},{"start":65.1,"end":69.6,"text":"The water temperature can drop to as low as zero degrees Centigrade.","coverage":1.0},{"start":70.28,"end":73.46,"text":"Sometimes there is snow and cold wind,","coverage":1.0},{"start":73.92,"end":74.0,"text":"too.","coverage":1.0},{"start":74.9,"end":79.26,"text":"People believe that swimming in the cold water is good for their health.","coverage":1.0},{"start":79.26,"end":83.26,"text":"The club started in 1903.","coverage":1.0},{"start":85.54,"end":89.52,"text":"Dragon Boat Racing Every year in Singapore,","coverage":1.0},{"start":90.24,"end":93.38,"text":"thousands of people come to watch the Dragon Boat Race.","coverage":1.0},{"start":94.3,"end":100.26,"text":"A dragon boat is a traditional Chinese boat with a painted dragon's head on one end.","coverage":1.0},{"start":100.94,"end":105.58,"text":"There are 22 people in each boat, and they race in the water.","coverage":1.0},{"start":105.58,"end":110.08,"text":"Dragon Boat Racing is also popular in China,","coverage":1.0},{"start":110.44,"end":110.94,"text":"Malaysia,","coverage":1.0},{"start":111.3,"end":112.52,"text":"and Indonesia.","coverage":1.0},{"start":114.44,"end":122.96,"text":"Caber Toss In this sport, people compete by throwing a large piece of wood called a caber as far as they can.","coverage":1.0},{"start":123.56,"end":126.5,"text":"The caber toss is an ancient Scottish sport.","coverage":1.0},{"start":127.1,"end":128.02,"text":"The caber has","coverage":1.0},{"start":128.02,"end":128.48,"text":"no","coverage":1.0},{"start":128.48,"end":133.28,"text":"official size or shape, but it is usually the size of a small tree.","coverage":1.0},{"start":136.02,"end":142.28,"text":"Fireball Football Students in Indonesia play this game to welcome the month of Ramadan.","coverage":1.0},{"start":142.96,"end":144.52,"text":"It is similar to football.","coverage":1.0},{"start":145.14,"end":147.46,"text":"The ball is made from coconut shells.","coverage":1.0},{"start":148.24,"end":154.64,"text":"Before starting the game, players pour salt on themselves and then set the ball on fire.","coverage":1.0},{"start":155.4,"end":158.2,"text":"The ball is on fire throughout the game,","coverage":1.0},{"start":158.54,"end":161.22,"text":"and the players play with their bare feet.","coverage":1.0},{"start":163.12,"end":165.84,"text":"Toe Wrestling In England,","coverage":1.0},{"start":166.18,"end":169.04,"text":"toe wrestling started in the 1970s.","coverage":1.0},{"start":169.48,"end":174.9,"text":"The World Toe Wrestling Competition takes place every year in Wetland, Derbyshire.","coverage":1.0},{"start":175.52,"end":183.36,"text":"In the sport, two people fight with their bare feet, each player trying to push the other player's foot flat on the floor.","coverage":1.0},{"start":183.92,"end":187.76,"text":"Players must keep both hands on the floor during the fight.","coverage":1.0}],"file":"87ad122513dbcaaf5061.js","track":0,"media":"../assets/media/fd97f00863036b1cde7b2f95a2505a5a253a90dd2702c90720afb1370c645421.mp3"}],"../assets/media/863d883603a445809d3bb35ce4a38a4fe3c3cd19811d44f021742caaf5d25ca9.mp3":[{"id":"PPT_863d883603a44580","audioId":"PPT_863d883603a44580","title":"Book 2 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 184","duration":10.14,"cues":[{"start":3.14,"end":8.22,"text":"I'd like to talk about the city of Vancouver in British Columbia, Canada.","coverage":1.0}],"file":"8b6bc96cbed45f6a80a3.js","track":0,"media":"../assets/media/863d883603a445809d3bb35ce4a38a4fe3c3cd19811d44f021742caaf5d25ca9.mp3"}],"../assets/media/b8632be10dde55d72d6e5b910f089156fcf9cac79d718a0a83d2658bfeabd66f.mp3":[{"id":"PPT_b8632be10dde55d7","audioId":"PPT_b8632be10dde55d7","title":"Book 3 · Unit 5 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 228","duration":41.77,"cues":[{"start":0.0,"end":1.76,"text":"Unit five,","coverage":1.0},{"start":2.3,"end":3.74,"text":"five .one","coverage":1.0},{"start":3.74,"end":7.86,"text":"Today we're talking about the key to a long and happy life.","coverage":1.0},{"start":8.54,"end":15.98,"text":"Recent studies of people who live to be a hundred years old have shown that a healthy diet and exercise may not be enough.","coverage":1.0},{"start":16.58,"end":24.62,"text":"In fact many of the people who celebrate their hundreds birthday have not eaten a healthy diet and have never exercised regularly.","coverage":1.0},{"start":25.38,"end":29.94,"text":"This has led many people to believe that our lifestyles are not important.","coverage":1.0},{"start":30.54,"end":33.58,"text":"What's most important is that we have good genes.","coverage":1.0},{"start":34.28,"end":39.86,"text":"It seems that if you have the right genes then you'll live for a long time whatever you do.","coverage":1.0}],"file":"8bde007efb7b78fae97f.js","track":0,"media":"../assets/media/b8632be10dde55d72d6e5b910f089156fcf9cac79d718a0a83d2658bfeabd66f.mp3"}],"../assets/media/2e84c5c9b2841201456eb37cadb6944a6192acacbc78a821b8768d8280735279.wav":[{"id":"B2_U08_T8.4_SHORT_S01_v01","audioId":"B2_U08_T8.4_SHORT_S01_v01","title":"Book 2 · Unit 8 · H2 · 听力材料 1","subtitle":"H2 · S01","duration":51.13628117913832,"cues":[{"start":2.24,"end":5.54,"text":"Host: Why is space junk a problem?","coverage":0.857},{"start":6.37,"end":19.47,"text":"Well, the pieces of space junk travel at extremely fast speeds (over 25,000 kilometres per hour) and so they can cause very bad problems if they hit anything.","coverage":0.897},{"start":20.01,"end":26.03,"text":"NASA, the US space agency, watches where the space junk is.","coverage":0.909},{"start":26.65,"end":38.39,"text":"The International Space Station (the ISS) can move out of the way of the space junk if they get a message to move at least five hours before an accident.","coverage":0.967},{"start":38.97,"end":50.58,"text":"Because people continue to send so many things into space - and this first started in 1957 - there are now over 27,000 pieces of space junk.","coverage":1.0}],"file":"8d03fdadd2deea7c7f8e.js","track":0,"media":"../assets/media/2e84c5c9b2841201456eb37cadb6944a6192acacbc78a821b8768d8280735279.wav"}],"../assets/media/3ff24da26cfb5548d307b2e8dfdbf510fd52379c3f7ceca407dd43c28512a235.wav":[{"id":"B2_U08_T8.4_SHORT_S02_v01","audioId":"B2_U08_T8.4_SHORT_S02_v01","title":"Book 2 · Unit 8 · H2 · 听力材料 2","subtitle":"H2 · S02","duration":24.201927437641725,"cues":[{"start":0,"end":3.97,"text":"Host: The smaller pieces might be as tiny as a bit of paint.","coverage":0.923},{"start":5.26,"end":9.38,"text":"But most of them are larger than 10 centimetres across.","coverage":0.9},{"start":10.48,"end":16.11,"text":"These are parts of old spacecraft, broken pieces of satellites and other things.","coverage":1.0},{"start":16.54,"end":23.18,"text":"Some of this happened because of accidents in space, which can create thousands of pieces of space junk.","coverage":1.0}],"file":"8d03fdadd2deea7c7f8e.js","track":1,"media":"../assets/media/3ff24da26cfb5548d307b2e8dfdbf510fd52379c3f7ceca407dd43c28512a235.wav"}],"../assets/media/f47f7bbfc3a0ed8fd198869d4228192d4ca3900f9c9ca38b84187b99cf7abeb5.mp3":[{"id":"B2_U08_T8.4_SHORT_S03_v01","audioId":"B2_U08_T8.4_SHORT_S03_v01","title":"Book 2 · Unit 8 · H2 · 听力材料 3","subtitle":"H2 · S03","duration":42.410862,"cues":[{"start":0,"end":4.52,"text":"Host: Many people would like to find a solution to space junk if they could.","coverage":0.933},{"start":6.9,"end":16.82,"text":"Scientists worry that if large pieces of space junk hit each other, they would break and there would be more and more broken pieces of space junk.","coverage":1.0},{"start":17.14,"end":24.35,"text":"When there is too much space junk, we won’t be able to use the space around the Earth for satellites.","coverage":1.0},{"start":24.86,"end":28.73,"text":"So, what options do we have to solve the problem?","coverage":1.0},{"start":29.1,"end":37.39,"text":"The British mission RemoveDEBRIS is trying to solve the problem by catching space junk and taking it away.","coverage":0.944},{"start":37.82,"end":41.35,"text":"If all the space junk was gone, there wouldn’t be a problem anymore.","coverage":1.0}],"file":"8d03fdadd2deea7c7f8e.js","track":2,"media":"../assets/media/f47f7bbfc3a0ed8fd198869d4228192d4ca3900f9c9ca38b84187b99cf7abeb5.mp3"}],"../assets/media/54ba0e01ca832d7b1556d5a6dade414be4a886d9dc979ba55d6f00d731bbfea2.mp3":[{"id":"B2_U08_T8.4_SHORT_S04_v01","audioId":"B2_U08_T8.4_SHORT_S04_v01","title":"Book 2 · Unit 8 · H2 · 听力材料 4","subtitle":"H2 · S04","duration":65.955556,"cues":[{"start":0,"end":4.64,"text":"Host: But what about space junk falling from space?","coverage":0.889},{"start":5.06,"end":6.9,"text":"What is the danger to people?","coverage":1.0},{"start":7.18,"end":13.49,"text":"There’s not much chance anything would hit you if you were outside on a normal day.","coverage":1.0},{"start":13.88,"end":17.47,"text":"That’s because most junk burns as it falls to Earth.","coverage":1.0},{"start":17.76,"end":26.85,"text":"In 1997, one person in the US was hit by a piece of space junk and she was not hurt at all.","coverage":1.0},{"start":27.6,"end":40.0,"text":"In 2022, a large piece of space junk from a SpaceX spacecraft fell to the surface of the Earth and landed on an Australian sheep farm.","coverage":1.0},{"start":40.44,"end":47.08,"text":"From time to time, other large pieces hit the ground, usually in rural areas.","coverage":1.0},{"start":47.48,"end":55.18,"text":"These days, most space agencies work to make their old spacecraft fall in the ocean if possible.","coverage":0.941},{"start":56.21,"end":63.94,"text":"However, with tens of thousands of pieces of space junk, there might be more than rain falling from the sky.","coverage":1.0}],"file":"8d03fdadd2deea7c7f8e.js","track":3,"media":"../assets/media/54ba0e01ca832d7b1556d5a6dade414be4a886d9dc979ba55d6f00d731bbfea2.mp3"}],"../assets/media/07daab4eca709c419816d8996fedd4722e28a38003b14dc573e5b3fe3cfb21a4.mp3":[{"id":"B2_U06_T6.3_SHORT_S02_v01","audioId":"B2_U06_T6.3_SHORT_S02_v01","title":"Book 2 · Unit 6 · H2 · 听力材料 2","subtitle":"H2 · S02","duration":61.584739,"cues":[{"start":0,"end":1.82,"text":"Professor Gould: Can you tell me what you learned?","coverage":0.778},{"start":3.26,"end":7.12,"text":"Alika: Well, I looked at how people spend time at work.","coverage":0.909},{"start":7.48,"end":19.06,"text":"I was interested in how people wasted time and why they didn’t work hard at their jobs; I mean, the reasons why they didn’t focus on their work.","coverage":1.0},{"start":19.44,"end":22.74,"text":"I found out a lot of interesting information.","coverage":1.0},{"start":23.44,"end":28.94,"text":"For example, almost half of the workers wasted time on the internet.","coverage":1.0},{"start":29.76,"end":33.72,"text":"They were surfing the internet or writing personal emails.","coverage":1.0},{"start":34.08,"end":38.1,"text":"It was 48% of workers, in fact.","coverage":1.0},{"start":39.02,"end":45.59,"text":"31.5% also said they spent time talking to colleagues instead of working.","coverage":1.0},{"start":46.2,"end":54.43,"text":"And a little under half that amount, 15%, said they took longer coffee and lunch breaks than they should.","coverage":1.0},{"start":55.16,"end":60.65,"text":"Only 5% said they spent time texting friends and making plans for after work.","coverage":1.0}],"file":"8f2a0959a8b70fbc584a.js","track":1,"media":"../assets/media/07daab4eca709c419816d8996fedd4722e28a38003b14dc573e5b3fe3cfb21a4.mp3"}],"../assets/media/bc774370ec46f08104effb1f75b3cb49e11f562a087fb0b10769353cd1fd1eba.mp3":[{"id":"B2_U06_T6.3_SHORT_S03_v01","audioId":"B2_U06_T6.3_SHORT_S03_v01","title":"Book 2 · Unit 6 · H2 · 听力材料 3","subtitle":"H2 · S03","duration":41.156983999999994,"cues":[{"start":0.55,"end":1.0,"text":"Professor Gould: Good.","coverage":0.333},{"start":1.03,"end":4.15,"text":"And did you find out the reasons why?","coverage":1.0},{"start":5.31,"end":5.38,"text":"Alika: Yes.","coverage":0.5},{"start":6.93,"end":12.0,"text":"Approximately half said they didn’t work hard because they weren’t happy in their jobs.","coverage":1.0},{"start":12.44,"end":13.32,"text":"Professor Gould: I see.","coverage":0.5},{"start":14.43,"end":21.4,"text":"Alika: And about a third, 33.5%, thought they didn’t earn a good enough salary.","coverage":0.938},{"start":21.88,"end":27.12,"text":"They said they didn’t have enough money for holidays or nice clothes.","coverage":1.0},{"start":27.96,"end":34.21,"text":"They had just enough money to get by, so they didn’t work as hard as they could.","coverage":1.0},{"start":35.12,"end":40.7,"text":"Some people, about 19%, said they had to work too many hours.","coverage":1.0}],"file":"8f2a0959a8b70fbc584a.js","track":2,"media":"../assets/media/bc774370ec46f08104effb1f75b3cb49e11f562a087fb0b10769353cd1fd1eba.mp3"}],"../assets/media/51a07f77c7077e853e84476a250e84ee0d3644f9336c87a0a058e5343a03bc9c.mp3":[{"id":"B2_U06_T6.3_SHORT_S04_v01","audioId":"B2_U06_T6.3_SHORT_S04_v01","title":"Book 2 · Unit 6 · H2 · 听力材料 4","subtitle":"H2 · S04","duration":39.211701000000005,"cues":[{"start":0,"end":4.3,"text":"Professor Gould: So, what are some effects of people not working very hard?","coverage":0.846},{"start":5.48,"end":13.42,"text":"Alika: Hmm … if people aren’t working hard, companies don’t get what they are paying for.","coverage":0.941},{"start":13.6,"end":15.49,"text":"Professor Gould: Can you give me some examples?","coverage":0.75},{"start":16.27,"end":21.46,"text":"Alika: Well, when people don’t work hard, productivity goes down.","coverage":0.909},{"start":22.28,"end":33.32,"text":"Because productivity depends on how fast workers make things or provide services, if workers are not working hard, the company doesn’t make a profit.","coverage":1.0},{"start":34.1,"end":36.97,"text":"Then they can’t pay higher salaries.","coverage":1.0}],"file":"8f2a0959a8b70fbc584a.js","track":3,"media":"../assets/media/51a07f77c7077e853e84476a250e84ee0d3644f9336c87a0a058e5343a03bc9c.mp3"}],"../assets/media/66d3b4a03f7cbe0567827c7b7c33023d58411f416ccf2ad68d6d2e0da63720c2.mp3":[{"id":"PPT_66d3b4a03f7cbe05","audioId":"PPT_66d3b4a03f7cbe05","title":"Book 2 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 185","duration":8.41,"cues":[{"start":0.0,"end":1.74,"text":"one .seven","coverage":1.0},{"start":3.26,"end":6.42,"text":"First of all, let's look at some of the positives.","coverage":1.0}],"file":"91a4b4d47a4ce7b2518f.js","track":0,"media":"../assets/media/66d3b4a03f7cbe0567827c7b7c33023d58411f416ccf2ad68d6d2e0da63720c2.mp3"}],"../assets/media/e7bd3f3a9ac95e5d43dbd66c610282916b1156577d9a67d28175e5134135ad3a.mp3":[{"id":"PPT_e7bd3f3a9ac95e5d","audioId":"PPT_e7bd3f3a9ac95e5d","title":"Book 3 · Unit 7 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 91","duration":203.68,"cues":[{"start":0.0,"end":1.74,"text":"seven .six","coverage":1.0},{"start":2.48,"end":5.72,"text":"How did you feel about growing up in New York?","coverage":1.0},{"start":6.02,"end":11.72,"text":"Well, as a teenager in New York, I had a lot of problems trying to dress in a modest way.","coverage":1.0},{"start":12.22,"end":13.02,"text":"For example,","coverage":1.0},{"start":13.42,"end":15.52,"text":"when you look at summer fashion in New York,","coverage":1.0},{"start":15.84,"end":17.76,"text":"the trend is always to wear skirts,","coverage":1.0},{"start":18.24,"end":20.44,"text":"shorts and sleeveless shirts.","coverage":1.0},{"start":21.08,"end":24.74,"text":"I didn't feel comfortable wearing them, but at the same time,","coverage":1.0},{"start":25.08,"end":29.24,"text":"my friends thought it was strange to wear long sleeves and jeans in the summer.","coverage":1.0},{"start":29.24,"end":33.02,"text":"So I've always tried to combine my culture with fashion.","coverage":1.0},{"start":33.6,"end":36.28,"text":"As a teenager, I would make my own clothes,","coverage":1.0},{"start":36.7,"end":39.44,"text":"like colourful skirts and scarves.","coverage":1.0},{"start":39.9,"end":42.34,"text":"I wanted my designs to be individual.","coverage":1.0},{"start":42.96,"end":47.96,"text":"They were unique and eventually people admired my clothes rather than laughed at me.","coverage":1.0},{"start":48.3,"end":48.82,"text":"I see.","coverage":1.0},{"start":49.22,"end":53.12,"text":"So do you know what ideas most people have about Muslim clothes?","coverage":1.0},{"start":53.82,"end":54.46,"text":"Well,","coverage":1.0},{"start":54.9,"end":58.52,"text":"I think there's a lot of misunderstanding about Muslim clothes.","coverage":1.0},{"start":58.52,"end":61.9,"text":"The thing is that when you say Muslim fashion,","coverage":1.0},{"start":62.36,"end":69.5,"text":"people in New York think of a burqa, you know, like the blue or black cloaks which cover women from head to toe.","coverage":1.0},{"start":69.8,"end":73.16,"text":"And could you explain what you think Muslim fashion is?","coverage":1.0},{"start":73.58,"end":74.94,"text":"Let me give you an example.","coverage":1.0},{"start":75.34,"end":77.46,"text":"When I first started at design school,","coverage":1.0},{"start":78.0,"end":80.56,"text":"my teachers would ask me strange questions,","coverage":1.0},{"start":80.92,"end":87.56,"text":"such as how I was going to stay in the fashion business if I'm not going to design miniskirts or sleeveless shirts.","coverage":1.0},{"start":87.56,"end":89.56,"text":"But as far as I'm concerned,","coverage":1.0},{"start":89.98,"end":92.9,"text":"there is much more to fashion than showing your body.","coverage":1.0},{"start":93.7,"end":100.24,"text":"There are millions of Muslim women who live in the United States and Europe who want to wear fashionable clothes.","coverage":1.0},{"start":100.82,"end":104.42,"text":"There are also women who simply like to dress in a modest way.","coverage":1.0},{"start":104.8,"end":108.96,"text":"So are you saying that there is a need for fashionable clothes for Muslim women?","coverage":1.0},{"start":109.36,"end":109.88,"text":"Absolutely.","coverage":1.0},{"start":110.4,"end":113.64,"text":"We want to be fashionable and be ourselves at the same time.","coverage":1.0},{"start":114.18,"end":115.44,"text":"My feeling is this.","coverage":1.0},{"start":115.44,"end":118.44,"text":"I want to create clothes which are modest,","coverage":1.0},{"start":118.86,"end":121.24,"text":"but at the same time give women confidence,","coverage":1.0},{"start":121.58,"end":124.12,"text":"clothes which allow women to be themselves.","coverage":1.0},{"start":124.58,"end":125.48,"text":"I see what you mean.","coverage":1.0},{"start":125.82,"end":128.24,"text":"So how would you describe your style?","coverage":1.0},{"start":128.74,"end":129.12,"text":"Well,","coverage":1.0},{"start":129.46,"end":134.98,"text":"many reviewers have described my style as traditional chic, and I guess I'd agree with them.","coverage":1.0},{"start":135.56,"end":141.3,"text":"What I think is that combining traditional with chic is a huge area in fashion.","coverage":1.0},{"start":141.88,"end":144.84,"text":"I keep my eye on the fashion trends in other countries.","coverage":1.0},{"start":144.84,"end":149.14,"text":"When you look at the works of other designers in China and India,","coverage":1.0},{"start":149.44,"end":154.26,"text":"you can see that many traditional styles are being reused by young designers.","coverage":1.0},{"start":154.86,"end":155.66,"text":"Above all,","coverage":1.0},{"start":156.12,"end":159.74,"text":"people like to be individuals and show their cultural roots.","coverage":1.0},{"start":160.22,"end":162.22,"text":"They like to show where they come from.","coverage":1.0},{"start":162.56,"end":163.72,"text":"As I understand it,","coverage":1.0},{"start":164.26,"end":168.98,"text":"your designs are must -haves for Muslim women outside the United States as well.","coverage":1.0},{"start":169.42,"end":170.92,"text":"Could you tell me more about that?","coverage":1.0},{"start":171.3,"end":171.9,"text":"Yes.","coverage":1.0},{"start":171.9,"end":174.4,"text":"In addition to New York and Paris,","coverage":1.0},{"start":174.86,"end":179.92,"text":"I sell my collection in big cities like Doha, Dubai and Abu Dhabi.","coverage":1.0},{"start":180.2,"end":185.36,"text":"Another thing is that I also receive requests for my clothes from women in Pakistan,","coverage":1.0},{"start":185.76,"end":186.24,"text":"Indonesia,","coverage":1.0},{"start":186.88,"end":188.14,"text":"Singapore and Malaysia.","coverage":1.0},{"start":188.42,"end":190.68,"text":"So someday I might open stores there.","coverage":1.0},{"start":191.0,"end":192.9,"text":"Well, I hope you decide to go for it.","coverage":1.0},{"start":193.04,"end":196.16,"text":"That would make a lot of women around the world very happy.","coverage":1.0},{"start":196.76,"end":197.48,"text":"So Aisha,","coverage":1.0},{"start":197.88,"end":199.8,"text":"thank you for coming to the studio today.","coverage":1.0},{"start":199.8,"end":201.12,"text":"It was my pleasure.","coverage":1.0},{"start":201.38,"end":201.94,"text":"Any time.","coverage":1.0}],"file":"9218ecb8e39f17dffc9d.js","track":0,"media":"../assets/media/e7bd3f3a9ac95e5d43dbd66c610282916b1156577d9a67d28175e5134135ad3a.mp3"}],"../assets/media/4409f13af249a81880eea49c63923251ebd25834f7e573c656a669dcbce3a082.mp3":[{"id":"PPT_4409f13af249a818","audioId":"PPT_4409f13af249a818","title":"Book 2 · Unit 3 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 66","duration":280.32,"cues":[{"start":0.0,"end":2.3,"text":"three .three","coverage":1.0},{"start":3.4,"end":9.14,"text":"Welcome to University Podcasts, programs made by students for students.","coverage":1.0},{"start":9.84,"end":10.88,"text":"I'm Chen Hu,","coverage":1.0},{"start":11.32,"end":13.78,"text":"and this is Science with a Professor.","coverage":1.0},{"start":14.6,"end":20.64,"text":"Our subject is technology development, and our guest is Professor Joanne Kent,","coverage":1.0},{"start":21.26,"end":22.34,"text":"expert in robotics.","coverage":1.0},{"start":23.14,"end":24.28,"text":"Thanks for coming, Professor.","coverage":1.0},{"start":25.28,"end":27.18,"text":"When we think of robots,","coverage":1.0},{"start":27.72,"end":33.86,"text":"we generally think of simple robots that clean the floor in our home or build a car in a factory.","coverage":1.0},{"start":34.62,"end":38.48,"text":"But how close are we to having robots that are like people?","coverage":1.0},{"start":39.38,"end":43.62,"text":"Well, we already have some robots that look like people,","coverage":1.0},{"start":44.08,"end":47.36,"text":"and technology is developing more every day.","coverage":1.0},{"start":48.0,"end":54.16,"text":"Robots weren't used very much in the past, since they were always really expensive.","coverage":1.0},{"start":54.64,"end":60.58,"text":"But because they're cheaper now, they're being used in new and interesting ways.","coverage":1.0},{"start":61.78,"end":62.76,"text":"What kinds of ways?","coverage":1.0},{"start":63.94,"end":65.48,"text":"Well, as you said,","coverage":1.0},{"start":66.1,"end":69.22,"text":"robots have been used in factories for years.","coverage":1.0},{"start":69.78,"end":75.8,"text":"Singapore and Korea are among the top five countries in the world with factory robots,","coverage":1.0},{"start":76.32,"end":80.66,"text":"and Japan has robots that serve food in some cafes.","coverage":1.0},{"start":81.42,"end":83.24,"text":"But now in the US,","coverage":1.0},{"start":83.62,"end":88.74,"text":"some restaurants are testing robots which work in the kitchen and cook food,","coverage":1.0},{"start":89.06,"end":91.66,"text":"or which deliver pizza to homes.","coverage":1.0},{"start":92.48,"end":92.88,"text":"Also,","coverage":1.0},{"start":93.28,"end":97.82,"text":"robots are being developed to work on farms and help grow food.","coverage":1.0},{"start":98.4,"end":102.24,"text":"They can pick fruit, for example, or look at plant health.","coverage":1.0},{"start":103.28,"end":104.04,"text":"Interesting.","coverage":1.0},{"start":104.66,"end":108.48,"text":"But what about robots that look after or help people?","coverage":1.0},{"start":109.06,"end":110.22,"text":"Do we have those?","coverage":1.0},{"start":111.1,"end":122.44,"text":"Well, many companies are developing robots to help people who have a disability or people who can't always do housework or care for themselves easily.","coverage":1.0},{"start":123.18,"end":130.64,"text":"They might need help from robots that can carry things around the house or deliver medicine on time.","coverage":1.0},{"start":131.36,"end":135.08,"text":"These types of robots are becoming less expensive.","coverage":1.0},{"start":135.58,"end":139.92,"text":"Having a robot means people are able to stay in their own homes.","coverage":1.0},{"start":141.06,"end":145.94,"text":"So do people have a much better quality of life thanks to these new types of robots?","coverage":1.0},{"start":147.2,"end":155.68,"text":"Yes, but at this time, it's too expensive to have robots at home that can pick people up or feed them.","coverage":1.0},{"start":155.68,"end":159.48,"text":"Also, when robots were used in care homes,","coverage":1.0},{"start":159.92,"end":163.54,"text":"the nurses found that the robots didn't save time.","coverage":1.0},{"start":164.48,"end":165.32,"text":"Why is that?","coverage":1.0},{"start":166.08,"end":169.06,"text":"The robots had to be moved and watched.","coverage":1.0},{"start":169.46,"end":176.1,"text":"The nurses spent time looking after the robots, and so they had less time to look after the people.","coverage":1.0},{"start":176.58,"end":179.86,"text":"They stopped using the robots due to the lost time.","coverage":1.0},{"start":181.0,"end":181.74,"text":"I see.","coverage":1.0},{"start":182.58,"end":185.5,"text":"What are some other ways that robots are used?","coverage":1.0},{"start":186.62,"end":192.38,"text":"These days, people use robots for science research, to repair equipment in the ocean,","coverage":1.0},{"start":192.8,"end":195.86,"text":"and as assistance to doctors and librarians.","coverage":1.0},{"start":197.22,"end":197.6,"text":"Really?","coverage":1.0},{"start":198.12,"end":199.66,"text":"What kind of science research?","coverage":1.0},{"start":200.56,"end":202.8,"text":"I know about robots on the planet Mars.","coverage":1.0},{"start":203.9,"end":210.04,"text":"Yes, robots go to places that we can't go to collect information, like on Mars.","coverage":1.0},{"start":210.4,"end":217.68,"text":"They can prevent accidents by doing dangerous things, and they can go into areas with bad pollution.","coverage":1.0},{"start":218.76,"end":222.3,"text":"And you also said robots could be doctors or librarians.","coverage":1.0},{"start":222.88,"end":230.26,"text":"Does that mean I shouldn't study for a degree in library studies because a robot is going to take all the librarian's jobs?","coverage":1.0},{"start":231.7,"end":232.38,"text":"No,","coverage":1.0},{"start":232.86,"end":236.78,"text":"robots only help with the boring parts of being a librarian.","coverage":1.0},{"start":237.21,"end":243.48,"text":"They use barcodes to look for books on the shelves or put books in the right place.","coverage":1.0},{"start":245.88,"end":247.7,"text":"But what about a robot doctor?","coverage":1.0},{"start":248.58,"end":251.52,"text":"Am I going to see a robot when I go to the doctors?","coverage":1.0},{"start":252.82,"end":259.24,"text":"No, not yet, but doctors can use robotic arms to help them do surgery.","coverage":1.0},{"start":260.26,"end":264.8,"text":"People stay in hospital for a shorter time because of fewer problems.","coverage":1.0},{"start":265.62,"end":266.14,"text":"Well,","coverage":1.0},{"start":266.8,"end":269.88,"text":"we've heard about robots that clean your house, cook food,","coverage":1.0},{"start":270.22,"end":270.9,"text":"do research,","coverage":1.0},{"start":271.3,"end":272.92,"text":"and even help your doctor too.","coverage":1.0},{"start":273.68,"end":274.0,"text":"Okay,","coverage":1.0},{"start":274.4,"end":276.98,"text":"we have some questions coming in, so let's hear the first one.","coverage":1.0}],"file":"92513126d5ed9a3e984b.js","track":0,"media":"../assets/media/4409f13af249a81880eea49c63923251ebd25834f7e573c656a669dcbce3a082.mp3"}],"../assets/media/dde4ab54795112d5498bd7c861a4b878b3f8bae52388857c38a55387363bc630.mp3":[{"id":"B3_U02_T2.2_SHORT_S01_v01","audioId":"B3_U02_T2.2_SHORT_S01_v01","title":"Book 3 · Unit 2 · H2 · 听力材料 1","subtitle":"H2 · 2.2-S01","duration":32.601882,"cues":[{"start":0.22,"end":2.35,"text":"Man: Good morning.","coverage":0.667},{"start":3.48,"end":11.91,"text":"Today I want to explain some alternative solutions which may help reduce some of the problems related to climate change.","coverage":1.0},{"start":12.24,"end":17.38,"text":"The first solution uses solar energy to grow food in the desert.","coverage":1.0},{"start":17.84,"end":20.9,"text":"First of all, I’ll explain how farming in the desert works.","coverage":1.0},{"start":21.32,"end":28.61,"text":"Then, we’ll briefly discuss how this type of farming could solve some of the environmental problems we are now facing.","coverage":1.0},{"start":28.84,"end":32.0,"text":"We’ll discuss some possible problems with this system.","coverage":1.0}],"file":"9353b08594bf995b1777.js","track":0,"media":"../assets/media/dde4ab54795112d5498bd7c861a4b878b3f8bae52388857c38a55387363bc630.mp3"}],"../assets/media/b6273addc85d68319df226f34305fba42225478602b1ef5ab1097031f2460c9a.mp3":[{"id":"B3_U02_T2.2_SHORT_S02_v01","audioId":"B3_U02_T2.2_SHORT_S02_v01","title":"Book 3 · Unit 2 · H2 · 听力材料 2","subtitle":"H2 · 2.2-S02","duration":64.771678,"cues":[{"start":0.04,"end":2.72,"text":"So, how does it work?","coverage":1.0},{"start":4.01,"end":8.74,"text":"As we all know, in order to grow plants we need water and sunlight.","coverage":1.0},{"start":9.52,"end":13.59,"text":"There’s a lot of sunlight in the desert, but very little water.","coverage":1.0},{"start":14.45,"end":18.02,"text":"Scientists have combined solar energy with a farming technology called hydroponics.","coverage":0.909},{"start":21.98,"end":24.14,"text":"Hydroponics means growing plants in water.","coverage":0.833},{"start":25.25,"end":30.52,"text":"Plants don’t need to grow in the ground, but they do need nutrients to help them grow.","coverage":0.944},{"start":31.63,"end":33.41,"text":"Nutrients are like food for the plants.","coverage":0.857},{"start":33.75,"end":40.15,"text":"So, if you add the nutrients to water, you can grow fruit and vegetables in water.","coverage":1.0},{"start":40.49,"end":54.03,"text":"NASA scientists have been developing this method of growing food because it could allow us to grow food in any climate – in Antarctica, the Sahara desert or even on Mars.","coverage":0.933},{"start":54.45,"end":59.18,"text":"You might ask how this method of growing plants helps with the problem of climate change.","coverage":1.0},{"start":59.49,"end":63.84,"text":"I mean, after all, it uses fresh water, which is a limited resource.","coverage":1.0}],"file":"9353b08594bf995b1777.js","track":1,"media":"../assets/media/b6273addc85d68319df226f34305fba42225478602b1ef5ab1097031f2460c9a.mp3"}],"../assets/media/88b9e7699a07fd2296e348a12897fe6d2c9a5c00a0688fc41957d540736702ac.mp3":[{"id":"B3_U02_T2.2_SHORT_S03_v01","audioId":"B3_U02_T2.2_SHORT_S03_v01","title":"Book 3 · Unit 2 · H2 · 听力材料 3","subtitle":"H2 · 2.2-S03","duration":127.5178,"cues":[{"start":0.04,"end":6.62,"text":"An Australian company, Sundrop Farms, combined hydroponics with solar energy.","coverage":0.8},{"start":8.13,"end":12.77,"text":"Traditional farming uses between 60 and 80 percent of our planet’s fresh water.","coverage":0.929},{"start":13.97,"end":17.55,"text":"However, Sundrop Farms doesn’t use fresh water.","coverage":0.875},{"start":17.8,"end":18.61,"text":"It uses seawater.","coverage":0.667},{"start":21.04,"end":24.76,"text":"Sundrop Farms is only 100 metres from the shore.","coverage":0.778},{"start":25.15,"end":31.48,"text":"A line of mirrors reflects heat from the sun onto a pipe which has oil inside.","coverage":1.0},{"start":31.96,"end":38.43,"text":"The hot oil in the pipe heats up seawater, which is kept in special containers.","coverage":0.933},{"start":38.84,"end":45.35,"text":"When the seawater reaches 160 degrees Celsius, the steam provides electricity.","coverage":0.909},{"start":45.72,"end":50.87,"text":"Some of the hot water is used to heat the greenhouse during the cold desert nights.","coverage":1.0},{"start":51.24,"end":57.21,"text":"The plants grow in the greenhouse – a building with glass walls and a glass ceiling.","coverage":1.0},{"start":57.6,"end":62.13,"text":"The rest of the heated water goes to a desalination plant.","coverage":0.909},{"start":63.73,"end":73.86,"text":"Desalination is when we remove the salt from seawater to create drinkable water – that is, water which is clean and safe to drink.","coverage":0.87},{"start":74.32,"end":81.61,"text":"The desalination plant can produce up to 10,000 litres of fresh water every day.","coverage":0.933},{"start":82.04,"end":88.12,"text":"The farmer adds nutrients to this fresh water and then grows fruit and vegetables.","coverage":1.0},{"start":88.47,"end":99.69,"text":"To summarize, solar energy removes the salt from the seawater and the fresh water is then used inside the greenhouse, where the plants are growing.","coverage":0.92},{"start":100.12,"end":104.32,"text":"Many people around the world are really excited about this technology.","coverage":1.0},{"start":104.64,"end":111.86,"text":"So far, Australian farms have grown tomatoes, peppers and cucumbers using hydroponics.","coverage":0.833},{"start":113.56,"end":121.22,"text":"Many supermarkets are interested in buying these vegetables because they’re grown without pesticides or other chemicals.","coverage":0.941},{"start":122.16,"end":127.518,"text":"Some people think hydroponics is the perfect solution to the world food crisis.","coverage":0.923}],"file":"9353b08594bf995b1777.js","track":2,"media":"../assets/media/88b9e7699a07fd2296e348a12897fe6d2c9a5c00a0688fc41957d540736702ac.mp3"}],"../assets/media/782fc1bd4a09715dca6daa1188e6fb5f029407ddce5c7e0f933b787f5ee55e23.mp3":[{"id":"B3_U02_T2.2_SHORT_S04_v01","audioId":"B3_U02_T2.2_SHORT_S04_v01","title":"Book 3 · Unit 2 · H2 · 听力材料 4","subtitle":"H2 · 2.2-S04","duration":26.599501,"cues":[{"start":0.63,"end":11.15,"text":"Finally, the desert farms use solar energy and not fossil fuels, thus their negative effect on the environment is minimal.","coverage":1.0},{"start":11.48,"end":15.15,"text":"Now, of course, the future of hydroponics is unknown.","coverage":0.889},{"start":15.32,"end":21.59,"text":"But I think that desert farms might be a very interesting way to farm in the future.","coverage":0.941},{"start":21.96,"end":24.49,"text":"Now let’s discuss some of the problems …","coverage":1.0}],"file":"9353b08594bf995b1777.js","track":3,"media":"../assets/media/782fc1bd4a09715dca6daa1188e6fb5f029407ddce5c7e0f933b787f5ee55e23.mp3"}],"../assets/media/b17fe627f900849585ef57a0f97bb8c3129df8de2b7c8069948ee581afa3a489.mp3":[{"id":"B3_U02_T2.4_SHORT_S02_v01","audioId":"B3_U02_T2.4_SHORT_S02_v01","title":"Book 3 · Unit 2 · H2 · 听力材料 5","subtitle":"H2 · 2.4-S02","duration":62.107188,"cues":[{"start":0.75,"end":1.35,"text":"Emma: Thank you.","coverage":0.667},{"start":2.32,"end":6.72,"text":"I want to argue that there are many problems with nuclear power.","coverage":1.0},{"start":7.04,"end":18.19,"text":"It may be true that there are very few accidents caused by nuclear plants, but if there is an accident, then it will be huge and it will have long-term effects on the environment.","coverage":1.0},{"start":18.64,"end":29.56,"text":"For example, after the Fukushima nuclear disaster in Japan, the government had to tell people to leave their homes because of the possibility of radiation.","coverage":1.0},{"start":29.72,"end":37.85,"text":"The radioactive material spread to water and food, such as tea, milk, beef and fish.","coverage":1.0},{"start":38.32,"end":42.81,"text":"For months after the accident, the Fukushima plant was dangerous.","coverage":1.0},{"start":43.72,"end":48.43,"text":"People will not be able to live in the nearby area for the next 20 years.","coverage":1.0},{"start":48.92,"end":52.42,"text":"This is the big risk of building a nuclear power plant.","coverage":1.0},{"start":52.72,"end":59.68,"text":"In my opinion, it’s irresponsible for governments to allow nuclear power plants to be built near cities.","coverage":1.0},{"start":60.02,"end":61.29,"text":"They’re just too dangerous.","coverage":1.0}],"file":"9353b08594bf995b1777.js","track":4,"media":"../assets/media/b17fe627f900849585ef57a0f97bb8c3129df8de2b7c8069948ee581afa3a489.mp3"}],"../assets/media/c4bfca4960d85a2c7e4cb87e4f7c15f53277bf86bb62cd46c82177f0cf25fa42.mp3":[{"id":"B3_U02_T2.4_SHORT_S03_v01","audioId":"B3_U02_T2.4_SHORT_S03_v01","title":"Book 3 · Unit 2 · H2 · 听力材料 6","subtitle":"H2 · 2.4-S03","duration":58.241066,"cues":[{"start":0,"end":1.74,"text":"Jack: I have to disagree.","coverage":0.8},{"start":2.07,"end":4.6,"text":"I think we should look at the bigger picture.","coverage":1.0},{"start":6.05,"end":9.84,"text":"Some people are worried that nuclear power is a big risk.","coverage":1.0},{"start":10.12,"end":20.55,"text":"And yet there are hundreds of nuclear power plants all over the world and there have only been three major nuclear accidents in the last 30 years.","coverage":1.0},{"start":20.88,"end":31.99,"text":"In fact, research shows that many more people die while working with coal, natural gas and hydropower – that is, electricity powered by water.","coverage":0.957},{"start":32.32,"end":39.69,"text":"On top of that, nuclear power is the most environmentally friendly and the most sustainable source of energy.","coverage":1.0},{"start":40.0,"end":45.42,"text":"In other words, it doesn’t damage the environment and there will always be enough of it.","coverage":1.0},{"start":45.76,"end":55.0,"text":"A nuclear power plant does not pollute the air, it’s relatively cheap and it can provide a huge amount of electricity to our cities.","coverage":0.96},{"start":55.4,"end":57.92,"text":"And of course, our cities are growing …","coverage":1.0}],"file":"9353b08594bf995b1777.js","track":5,"media":"../assets/media/c4bfca4960d85a2c7e4cb87e4f7c15f53277bf86bb62cd46c82177f0cf25fa42.mp3"}],"../assets/media/1ba73ede57daf7de72038a98dd73dcf3f563a26606d84ef17a56f6ec676e27ea.mp3":[{"id":"B3_U02_T2.4_SHORT_S04_v01","audioId":"B3_U02_T2.4_SHORT_S04_v01","title":"Book 3 · Unit 2 · H2 · 听力材料 7","subtitle":"H2 · 2.4-S04","duration":46.041882,"cues":[{"start":0,"end":2.02,"text":"Emma: I’m sorry, can I interrupt?","coverage":0.857},{"start":3.16,"end":8.93,"text":"Some people say that nuclear energy doesn’t pollute the air, but that’s not completely true.","coverage":0.941},{"start":9.58,"end":13.12,"text":"It takes many years to build a nuclear power plant.","coverage":1.0},{"start":13.84,"end":18.94,"text":"During this time, hundreds of machines work day and night and pollute the air in the area.","coverage":0.941},{"start":19.34,"end":30.78,"text":"I don’t think it’s necessary to build nuclear power plants when we have safer and more environmentally friendly energy sources, such as solar and wind energy.","coverage":1.0},{"start":31.39,"end":34.6,"text":"They’re cheaper and they’re unlimited sources of energy.","coverage":1.0},{"start":35.18,"end":40.13,"text":"Also they’re more affordable for most countries, when compared with nuclear power.","coverage":1.0},{"start":40.78,"end":45.4,"text":"Building a nuclear power plant is not a solution for low-income countries.","coverage":1.0}],"file":"9353b08594bf995b1777.js","track":6,"media":"../assets/media/1ba73ede57daf7de72038a98dd73dcf3f563a26606d84ef17a56f6ec676e27ea.mp3"}],"../assets/media/103f34c92e18d3910a90c428e1e9f52910c82fcc25f50173220404ec42c2de2a.mp3":[{"id":"B3_U02_T2.4_SHORT_S05_v01","audioId":"B3_U02_T2.4_SHORT_S05_v01","title":"Book 3 · Unit 2 · H2 · 听力材料 8","subtitle":"H2 · 2.4-S05","duration":84.694036,"cues":[{"start":0,"end":1.83,"text":"Jack: I’m not sure about that.","coverage":0.857},{"start":2.6,"end":9.23,"text":"I think that building nuclear power plants is the perfect solution for many low-income countries.","coverage":1.0},{"start":9.76,"end":20.5,"text":"Yes, it might be expensive to build the plant, but once the nuclear plant is there, the cost of the production of energy is very low.","coverage":1.0},{"start":21.16,"end":26.73,"text":"Plus, the country can sell the electricity to its neighbours and improve its economy.","coverage":0.929},{"start":27.26,"end":28.87,"text":"It’s a long-term solution.","coverage":1.0},{"start":29.73,"end":34.37,"text":"And it makes a country less dependent on oil and gas.","coverage":1.0},{"start":34.95,"end":43.21,"text":"At the moment, whenever oil or gas prices go up, it’s low-income countries and the people who live in them that suffer.","coverage":0.917},{"start":43.86,"end":48.69,"text":"Some people think that solar and wind energy are greener than nuclear energy.","coverage":0.923},{"start":48.9,"end":51.47,"text":"But I don’t think that’s accurate.","coverage":1.0},{"start":52.43,"end":60.99,"text":"Wind turbines are not exactly friendly for birds, not to mention that solar panels and wind turbines take up a lot of space.","coverage":0.957},{"start":61.62,"end":67.56,"text":"They’re also very expensive and don’t last as long as a nuclear power plant.","coverage":1.0},{"start":68.13,"end":78.21,"text":"In short, wind and solar energy can’t solve the problem of climate change and they aren’t a good solution for low-income countries.","coverage":1.0},{"start":78.84,"end":80.21,"text":"Host: Thank you both very much.","coverage":0.833},{"start":80.66,"end":82.25,"text":"Let’s take some questions from the audience …","coverage":1.0}],"file":"9353b08594bf995b1777.js","track":7,"media":"../assets/media/103f34c92e18d3910a90c428e1e9f52910c82fcc25f50173220404ec42c2de2a.mp3"}],"../assets/media/e0392ecab36b7ddca04789419fd861926ddab03b5ed124fe6c89c4fb4098516a.mp3":[{"id":"PPT_e0392ecab36b7ddc","audioId":"PPT_e0392ecab36b7ddc","title":"Book 2 · Unit 4 · RW · READING 1","subtitle":"READING 1 · source slide 68","duration":243.96,"cues":[{"start":0.0,"end":12.92,"text":"Living in the Wettest Place on Earth Every year, the people living in the state of Meghalaya in northeast India spend many months preparing for heavy rain.","coverage":1.0},{"start":13.52,"end":16.1,"text":"The rains, called the summer monsoon,","coverage":1.0},{"start":16.42,"end":19.9,"text":"can last for days or weeks without stopping.","coverage":1.0},{"start":20.72,"end":30.08,"text":"The Guinness Book of World Records says that Meghalaya, which means abode of clouds, is one of the wettest places on Earth.","coverage":1.0},{"start":30.58,"end":33.92,"text":"It gets almost 12 ,000 millimeters,","coverage":1.0},{"start":34.36,"end":38.76,"text":"about 470 inches of rain each year.","coverage":1.0},{"start":39.7,"end":41.9,"text":"Compare this to the Sahara Desert,","coverage":1.0},{"start":42.26,"end":51.04,"text":"the world's largest hot desert, which gets between 100 and 250 millimeters, four to ten inches.","coverage":1.0},{"start":52.1,"end":56.3,"text":"Summer monsoons usually last from April until October.","coverage":1.0},{"start":56.84,"end":61.22,"text":"They can change the lives of a fifth of the world's population.","coverage":1.0},{"start":62.34,"end":70.32,"text":"Some people in the town of Masinram in Meghalaya prepare for the rain by covering their homes with dried grass.","coverage":1.0},{"start":71.2,"end":75.46,"text":"They do this so that the noise from the rain falling on their roof,","coverage":1.0},{"start":75.9,"end":78.54,"text":"windows, and walls is not as loud.","coverage":1.0},{"start":79.52,"end":82.22,"text":"Although rain may not get into the home,","coverage":1.0},{"start":82.62,"end":89.68,"text":"the walls inside can feel a bit wet because the fog from outside comes into the house.","coverage":1.0},{"start":90.34,"end":98.9,"text":"Sometimes the rain is so loud that the schools have to close because the children cannot hear what the teacher says in the lesson.","coverage":1.0},{"start":100.36,"end":103.64,"text":"The monsoon storms can leave people in the dark.","coverage":1.0},{"start":104.08,"end":109.08,"text":"Thunder and lightning can damage electricity cables and stop the power supply.","coverage":1.0},{"start":110.16,"end":114.6,"text":"Homes and businesses can be without electricity for many days.","coverage":1.0},{"start":114.6,"end":117.44,"text":"If people do not have electricity,","coverage":1.0},{"start":117.84,"end":121.12,"text":"they cannot turn on their lights or cook their food.","coverage":1.0},{"start":121.7,"end":129.3,"text":"It also means it is very dark inside because even during the day the sun is behind the clouds.","coverage":1.0},{"start":130.18,"end":132.32,"text":"In addition, because there is often","coverage":1.0},{"start":132.32,"end":132.7,"text":"no","coverage":1.0},{"start":132.7,"end":133.96,"text":"sun for weeks,","coverage":1.0},{"start":134.36,"end":139.4,"text":"clothes do not dry very well and can have a strange, bad smell.","coverage":1.0},{"start":140.54,"end":143.9,"text":"Heavy monsoon rains can cause landslides.","coverage":1.0},{"start":143.9,"end":150.88,"text":"Landslides are dangerous because they can badly damage buildings or even whole villages.","coverage":1.0},{"start":151.64,"end":155.46,"text":"They can also damage roads and stop access to water.","coverage":1.0},{"start":156.32,"end":160.38,"text":"This means there is not enough clean water for people to drink.","coverage":1.0},{"start":161.18,"end":165.52,"text":"In 2021, there was a landslide in Mumbai, India.","coverage":1.0},{"start":166.02,"end":170.68,"text":"It fell on people's homes as they were sleeping and several people died.","coverage":1.0},{"start":171.68,"end":175.64,"text":"People can spend a lot of time indoors during the monsoon,","coverage":1.0},{"start":176.0,"end":177.72,"text":"but life does not stop.","coverage":1.0},{"start":178.32,"end":180.94,"text":"They still go to work and shops open.","coverage":1.0},{"start":181.78,"end":182.84,"text":"In Mausinram,","coverage":1.0},{"start":183.28,"end":187.9,"text":"people make things called nups using bamboo and grass.","coverage":1.0},{"start":188.8,"end":194.54,"text":"Nups are like umbrellas, but they are a bit bigger and shaped like a tortoise.","coverage":1.0},{"start":194.74,"end":197.46,"text":"One nup takes about an hour to make.","coverage":1.0},{"start":197.46,"end":202.22,"text":"A nup can keep someone dry from their head to their knees.","coverage":1.0},{"start":202.94,"end":207.98,"text":"Some people who work in their homes use the monsoon as a business opportunity.","coverage":1.0},{"start":208.76,"end":214.78,"text":"For example, they make nups for the six -month monsoon season and sell them to visitors.","coverage":1.0},{"start":216.22,"end":221.18,"text":"Summer monsoons are not a new phenomenon, but experts are worried.","coverage":1.0},{"start":221.18,"end":226.54,"text":"Research suggests that climate change caused by human activity,","coverage":1.0},{"start":227.06,"end":229.34,"text":"such as industry and agriculture,","coverage":1.0},{"start":229.7,"end":230.8,"text":"will make a difference.","coverage":1.0},{"start":231.52,"end":233.3,"text":"In India, for example,","coverage":1.0},{"start":233.7,"end":242.06,"text":"the monsoon season is likely to get wetter and more dangerous because extreme rainfall events will happen more often.","coverage":1.0}],"file":"96e4e3e555ccc83f346b.js","track":0,"media":"../assets/media/e0392ecab36b7ddca04789419fd861926ddab03b5ed124fe6c89c4fb4098516a.mp3"}],"../assets/media/5ee60d396e1da4c773d36a2274f98cae1b0b31037bc50d15c9e08337f42b5ffa.mp3":[{"id":"PPT_5ee60d396e1da4c7","audioId":"PPT_5ee60d396e1da4c7","title":"Book 3 · Unit 4 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 81","duration":126.54,"cues":[{"start":0.0,"end":1.52,"text":"four .seven","coverage":1.0},{"start":1.52,"end":3.36,"text":"Hold on.","coverage":1.0},{"start":3.6,"end":4.54,"text":"Too commercial.","coverage":1.0},{"start":5.08,"end":5.9,"text":"I disagree.","coverage":1.0},{"start":6.7,"end":7.94,"text":"I like giving gifts.","coverage":1.0},{"start":8.72,"end":12.04,"text":"I think that it shows that you were thinking of someone.","coverage":1.0},{"start":12.52,"end":19.7,"text":"Because you went out and got someone some chocolate or jewellery or a scarf or something at the last minute.","coverage":1.0},{"start":20.44,"end":24.4,"text":"Everyone knows that people usually buy gifts because it's an obligation,","coverage":1.0},{"start":24.82,"end":26.62,"text":"not because they really want to.","coverage":1.0},{"start":26.62,"end":34.36,"text":"Well, you have to spend time thinking about the gift and get something thoughtful, you know, personal.","coverage":1.0},{"start":35.14,"end":38.72,"text":"Like maybe the new book by their favourite author.","coverage":1.0},{"start":39.1,"end":40.3,"text":"I see your point.","coverage":1.0},{"start":40.82,"end":45.08,"text":"But I'm not convinced because then you have to spend money.","coverage":1.0},{"start":45.6,"end":49.24,"text":"Money which could be spent on more important things.","coverage":1.0},{"start":49.98,"end":50.52,"text":"Also,","coverage":1.0},{"start":50.98,"end":56.8,"text":"all that time you spent shopping you could have instead spent with the person you're shopping for.","coverage":1.0},{"start":57.04,"end":58.5,"text":"I couldn't agree more.","coverage":1.0},{"start":58.94,"end":61.66,"text":"And it's not just holidays which are a problem.","coverage":1.0},{"start":62.28,"end":66.92,"text":"Personally, I think we give too many gifts for other special occasions too.","coverage":1.0},{"start":67.5,"end":71.66,"text":"Like when my sister graduated from university last year,","coverage":1.0},{"start":72.02,"end":75.48,"text":"she got lots of gifts and money too.","coverage":1.0},{"start":76.08,"end":77.58,"text":"The focus was all on","coverage":1.0},{"start":79.02,"end":82.84,"text":"I've heard that when people receive more than a few gifts,","coverage":1.0},{"start":83.26,"end":87.24,"text":"they usually can't even remember who gave them which gift.","coverage":1.0},{"start":87.96,"end":88.62,"text":"Instead,","coverage":1.0},{"start":89.24,"end":91.88,"text":"why not write letters of advice for the future?","coverage":1.0},{"start":92.24,"end":93.72,"text":"That would be more special.","coverage":1.0},{"start":94.18,"end":95.64,"text":"That's a great idea.","coverage":1.0},{"start":96.24,"end":96.68,"text":"Sorry,","coverage":1.0},{"start":97.12,"end":98.14,"text":"I don't agree.","coverage":1.0},{"start":98.5,"end":101.96,"text":"I doubt that graduates will be happy if we change that custom.","coverage":1.0},{"start":105.68,"end":110.88,"text":"I people need some gifts and money for starting their new life.","coverage":1.0},{"start":111.88,"end":117.54,"text":"And they can always look at the gift and think of the person who gave it to them.","coverage":1.0},{"start":118.12,"end":120.14,"text":"I think it's a nice custom.","coverage":1.0},{"start":121.04,"end":123.54,"text":"I'm still really not convinced.","coverage":1.0},{"start":123.76,"end":124.4,"text":"I mean...","coverage":1.0}],"file":"9717aa5b312a6f42769f.js","track":0,"media":"../assets/media/5ee60d396e1da4c773d36a2274f98cae1b0b31037bc50d15c9e08337f42b5ffa.mp3"}],"../assets/media/0d4a099bcc07297d3a8b385b2511ffb07987b5acd35fa2c37f1960e257512c19.mp3":[{"id":"PPT_0d4a099bcc07297d","audioId":"PPT_0d4a099bcc07297d","title":"Book 2 · Unit 4 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 190","duration":35.06,"cues":[{"start":0.0,"end":2.24,"text":"four .five","coverage":1.0},{"start":2.24,"end":7.06,"text":"one It is more difficult to work in high humidity,","coverage":1.0},{"start":7.6,"end":9.72,"text":"so our concentration drops.","coverage":1.0},{"start":12.48,"end":13.2,"text":"two","coverage":1.0},{"start":14.0,"end":16.72,"text":"People have more energy in sunny weather,","coverage":1.0},{"start":17.38,"end":20.66,"text":"therefore they can get a lot done if the sun is shining.","coverage":1.0},{"start":23.36,"end":24.08,"text":"three","coverage":1.0},{"start":24.8,"end":28.88,"text":"Some countries are really hot and don't get much rain.","coverage":1.0},{"start":29.6,"end":30.42,"text":"As a result,","coverage":1.0},{"start":30.98,"end":33.12,"text":"there isn't enough water for people to drink.","coverage":1.0}],"file":"977afede915f011aee8e.js","track":0,"media":"../assets/media/0d4a099bcc07297d3a8b385b2511ffb07987b5acd35fa2c37f1960e257512c19.mp3"}],"../assets/media/7b4c9f14270f17ea7853fb25408094d2c571dc15998a195cced28f7747eccd72.wav":[{"id":"B2_U06_T6.3_LONG_L02_v01","audioId":"B2_U06_T6.3_LONG_L02_v01","title":"Book 2 · Unit 6 · H3 · 听力材料 2","subtitle":"H3 · L02","duration":80.330952,"cues":[{"start":0.55,"end":1.0,"text":"Professor Gould: Good.","coverage":0.333},{"start":1.03,"end":4.15,"text":"And did you find out the reasons why?","coverage":1.0},{"start":5.31,"end":5.38,"text":"Alika: Yes.","coverage":0.5},{"start":6.93,"end":12.05,"text":"Approximately half said they didn’t work hard because they weren’t happy in their jobs.","coverage":1.0},{"start":12.48,"end":13.5,"text":"Professor Gould: I see.","coverage":0.5},{"start":14.48,"end":21.79,"text":"Alika: And about a third, 33.5%, thought they didn’t earn a good enough salary.","coverage":0.938},{"start":22.2,"end":27.15,"text":"They said they didn’t have enough money for holidays or nice clothes.","coverage":1.0},{"start":27.98,"end":34.07,"text":"They had just enough money to get by, so they didn’t work as hard as they could.","coverage":0.944},{"start":35.04,"end":40.45,"text":"Some people, about 19%, said they had to work too many hours.","coverage":1.0},{"start":40.92,"end":45.96,"text":"Professor Gould: So, what are some effects of people not working very hard?","coverage":0.846},{"start":46.87,"end":54.37,"text":"Alika: Hmm … if people aren’t working hard, companies don’t get what they are paying for.","coverage":0.941},{"start":55.27,"end":59.94,"text":"Professor Gould: Can you give me some examples?","coverage":0.75},{"start":60.8,"end":61.88,"text":"Alika: Well, when people don’t work hard, productivity goes down.","coverage":0.909},{"start":62.18,"end":74.75,"text":"Because productivity depends on how fast workers make things or provide services, if workers are not working hard, the company doesn’t make a profit.","coverage":1.0},{"start":74.9,"end":78.25,"text":"Then they can’t pay higher salaries.","coverage":1.0}],"file":"97acb69fcf6f6bbf9d6e.js","track":1,"media":"../assets/media/7b4c9f14270f17ea7853fb25408094d2c571dc15998a195cced28f7747eccd72.wav"}],"../assets/media/8071bb8bb33c484be3ac8cac48856516092018bee709db831f85dc24305e73da.mp3":[{"id":"PPT_8071bb8bb33c484b","audioId":"PPT_8071bb8bb33c484b","title":"Book 2 · Unit 8 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 96","duration":332.49,"cues":[{"start":0.0,"end":2.0,"text":"eight .six","coverage":1.0},{"start":3.48,"end":16.58,"text":"Part two Let me ask Dr Wu to start us off by giving us a little information about the impact of space exploration and the importance of spending money on it.","coverage":1.0},{"start":17.18,"end":18.58,"text":"Thanks for having me.","coverage":1.0},{"start":19.04,"end":21.18,"text":"Well, to answer your question,","coverage":1.0},{"start":22.04,"end":29.56,"text":"space exploration is important because we do research and get information about many things.","coverage":1.0},{"start":30.3,"end":31.06,"text":"For example,","coverage":1.0},{"start":31.7,"end":33.9,"text":"as scientists explore space,","coverage":1.0},{"start":34.48,"end":39.0,"text":"we learn about biology and about physics as well as space.","coverage":1.0},{"start":39.86,"end":40.98,"text":"So for me,","coverage":1.0},{"start":41.42,"end":47.32,"text":"the most important thing is that governments give enough money for future exploration.","coverage":1.0},{"start":47.92,"end":54.84,"text":"You have a point that space exploration is used for a lot of scientific study,","coverage":1.0},{"start":55.4,"end":62.22,"text":"but it is very expensive and there is less public money to pay for it nowadays.","coverage":1.0},{"start":63.08,"end":69.1,"text":"Is having the government pay really the only option for paying for space exploration?","coverage":1.0},{"start":70.02,"end":72.02,"text":"I hear what you're saying, Dorota.","coverage":1.0},{"start":72.48,"end":75.4,"text":"It isn't cheap to run space programs,","coverage":1.0},{"start":76.06,"end":79.72,"text":"but the money we spend is certainly worth it.","coverage":1.0},{"start":80.36,"end":83.3,"text":"Government and public money must be included.","coverage":1.0},{"start":84.42,"end":85.24,"text":"So far,","coverage":1.0},{"start":85.78,"end":90.7,"text":"space exploration has shown us many things about how space works,","coverage":1.0},{"start":91.22,"end":92.58,"text":"what stars do,","coverage":1.0},{"start":93.18,"end":98.34,"text":"the effects on people who stay in space for a long time and so on.","coverage":1.0},{"start":99.0,"end":106.86,"text":"We must continue to do this work so that we can explore places in space farther away and...","coverage":1.0},{"start":106.86,"end":108.84,"text":"Can I just say something here?","coverage":1.0},{"start":109.12,"end":109.78,"text":"Yes, Raj.","coverage":1.0},{"start":110.12,"end":115.92,"text":"I agree 100 % with Dr Wu that we need space exploration,","coverage":1.0},{"start":116.34,"end":119.8,"text":"but even he says it is very expensive.","coverage":1.0},{"start":120.54,"end":124.98,"text":"I know that we have to spend money to develop our space programs","coverage":1.0},{"start":125.49,"end":128.9,"text":"and we need more money than governments have.","coverage":1.0},{"start":129.66,"end":130.94,"text":"So for me,","coverage":1.0},{"start":131.54,"end":139.0,"text":"an alternative would be to bring in thinkers from different industries to discuss different ways to pay.","coverage":1.0},{"start":139.72,"end":141.9,"text":"If we are exploring space,","coverage":1.0},{"start":142.46,"end":145.6,"text":"we could have private companies pay for it.","coverage":1.0},{"start":145.86,"end":148.98,"text":"For me, this is the main reason we...","coverage":1.0},{"start":148.98,"end":149.42,"text":"But Raj,","coverage":1.0},{"start":149.94,"end":152.62,"text":"space exploration is so important.","coverage":1.0},{"start":153.1,"end":154.18,"text":"Governments must...","coverage":1.0},{"start":154.18,"end":156.98,"text":"Sorry, Dr Wu, can I finish my point?","coverage":1.0},{"start":157.7,"end":161.56,"text":"If so much money is spent on space exploration,","coverage":1.0},{"start":162.14,"end":167.48,"text":"the most important thing should be finding money from places other than the government.","coverage":1.0},{"start":168.22,"end":171.42,"text":"It shouldn't be just taxpayers paying for it.","coverage":1.0},{"start":172.2,"end":177.78,"text":"Private companies make lots of money from the discoveries made in space exploration,","coverage":1.0},{"start":178.16,"end":180.5,"text":"so they should pay for the costs.","coverage":1.0},{"start":180.5,"end":181.28,"text":"Dorota,","coverage":1.0},{"start":182.06,"end":183.64,"text":"you haven't said much so far.","coverage":1.0},{"start":183.86,"end":184.58,"text":"Any thoughts?","coverage":1.0},{"start":185.1,"end":188.44,"text":"Well, I personally don't see a problem.","coverage":1.0},{"start":189.12,"end":193.54,"text":"Dr Wu has a good point about public government money,","coverage":1.0},{"start":193.86,"end":198.82,"text":"and I feel exactly the same as Raj about private money.","coverage":1.0},{"start":199.42,"end":202.14,"text":"But we can do both of these things.","coverage":1.0},{"start":202.14,"end":210.52,"text":"Public or government money helps us keep the people who know the most, like those at NASA,","coverage":1.0},{"start":211.48,"end":212.86,"text":"focused on the research,","coverage":1.0},{"start":213.54,"end":221.72,"text":"and private money helps bring in other talent from companies that would also like to explore space,","coverage":1.0},{"start":222.34,"end":226.22,"text":"such as Virgin Galactic or SpaceX.","coverage":1.0},{"start":227.02,"end":233.44,"text":"Companies like these have already spent a lot of money on this important type of travel.","coverage":1.0},{"start":233.76,"end":234.02,"text":"Yeah,","coverage":1.0},{"start":234.56,"end":237.64,"text":"important space travel that governments should...","coverage":1.0},{"start":237.64,"end":239.8,"text":"Please, allow me to finish.","coverage":1.0},{"start":241.0,"end":246.12,"text":"There are also other choices that neither of you have talked about yet.","coverage":1.0},{"start":246.92,"end":249.94,"text":"Space exploration benefits the world.","coverage":1.0},{"start":250.7,"end":253.58,"text":"What about money from private individuals?","coverage":1.0},{"start":253.58,"end":261.46,"text":"There are wealthy people around the world that might be interested in giving money for these projects.","coverage":1.0},{"start":262.66,"end":263.06,"text":"Also,","coverage":1.0},{"start":263.5,"end":264.58,"text":"with the internet,","coverage":1.0},{"start":265.24,"end":269.12,"text":"people from around the world could give money for these projects.","coverage":1.0},{"start":269.78,"end":274.66,"text":"Lots of people could make donations directly to their favourite projects.","coverage":1.0},{"start":275.6,"end":281.94,"text":"I think in the future we can get money for space exploration from more than one place.","coverage":1.0},{"start":282.46,"end":287.16,"text":"We should study these different ways and use the best solution.","coverage":1.0},{"start":288.58,"end":290.14,"text":"Dr Wu, Raj Paddow,","coverage":1.0},{"start":290.44,"end":292.26,"text":"let's get your thoughts on this.","coverage":1.0},{"start":292.72,"end":296.94,"text":"Do you agree with these ideas for paying for space exploration?","coverage":1.0},{"start":297.94,"end":298.5,"text":"Yes,","coverage":1.0},{"start":299.0,"end":300.3,"text":"Dorotta could be right.","coverage":1.0},{"start":300.98,"end":304.96,"text":"Space exploration needs money to come from many places,","coverage":1.0},{"start":305.46,"end":310.38,"text":"as long as the government is still a part of this important area of exploration.","coverage":1.0},{"start":310.38,"end":313.5,"text":"And I think she might be right too,","coverage":1.0},{"start":313.82,"end":315.06,"text":"but as I said,","coverage":1.0},{"start":315.48,"end":318.6,"text":"only if there is money from private companies too.","coverage":1.0},{"start":319.0,"end":321.66,"text":"Okay, so you have some agreement here then.","coverage":1.0},{"start":322.32,"end":328.2,"text":"Let's go back to the benefits of space exploration and think about that a little more.","coverage":1.0},{"start":329.04,"end":330.88,"text":"So does anybody want to...","coverage":1.0}],"file":"9daa3b8da515483b081b.js","track":0,"media":"../assets/media/8071bb8bb33c484be3ac8cac48856516092018bee709db831f85dc24305e73da.mp3"}],"../assets/media/8b16f1befa2453facf29d5ac265cf845aa9552c4d201741418c2ff8680aa91ec.mp3":[{"id":"B2_U07_T7.1_SHORT_S01_v01","audioId":"B2_U07_T7.1_SHORT_S01_v01","title":"Book 2 · Unit 7 · 课后听力材料","subtitle":"Homework listening material","duration":91.769229,"cues":[{"start":0.23,"end":3.96,"text":"Unit 7, 7.1","coverage":1.0},{"start":5.24,"end":6.43,"text":"Student presenter: Hello, everyone.","coverage":0.5},{"start":7.0,"end":19.0,"text":"So, in this presentation I’d like to discuss the designers of some everyday objects: Arne Jacobsen, Sir James Dyson and Sir Jonathan Ive.","coverage":0.833},{"start":21.48,"end":29.37,"text":"These people designed simple things that have changed our lives and how we do everyday things.","coverage":1.0},{"start":30.36,"end":40.4,"text":"Today we are going to think about these inventors and designers, their achievements and how their inventions and designs have helped us.","coverage":0.955},{"start":40.96,"end":48.18,"text":"I would like to start with Arne Jacobsen, who was born in Denmark in 1902.","coverage":0.867},{"start":48.6,"end":56.88,"text":"When he was a child, he loved to paint, but his father thought being an artist wasn’t a good career.","coverage":1.0},{"start":57.41,"end":64.28,"text":"So, Jacobsen became a designer of many things, including buildings and furniture.","coverage":0.917},{"start":65.0,"end":70.99,"text":"For example, here is a chair he designed in 1958.","coverage":1.0},{"start":71.17,"end":73.38,"text":"It’s called the ‘Egg Chair’.","coverage":1.0},{"start":74.16,"end":76.92,"text":"Have any of you seen this kind of chair before?","coverage":1.0},{"start":77.29,"end":77.58,"text":"Razia: I have.","coverage":0.667},{"start":78.98,"end":81.89,"text":"Did they call it the Egg Chair because of its shape?","coverage":1.0},{"start":82.2,"end":84.4,"text":"It’s an interesting design.","coverage":1.0},{"start":84.95,"end":87.32,"text":"Student presenter: Yes, you have a good point.","coverage":0.75},{"start":87.55,"end":91.08,"text":"I think it was called that because of the egg-like shape.","coverage":1.0}],"file":"a2782dbf52c883193de6.js","track":0,"media":"../assets/media/8b16f1befa2453facf29d5ac265cf845aa9552c4d201741418c2ff8680aa91ec.mp3"}],"../assets/media/e49dd86b1bec25f8ac9b493c2a3b6481775f967ca53fe994b2852cc3e4d61bab.mp3":[{"id":"B3_U08_T8.2_SHORT_S01_v01","audioId":"B3_U08_T8.2_SHORT_S01_v01","title":"Book 3 · Unit 8 · 课后听力材料","subtitle":"Homework listening material","duration":71.132494,"cues":[{"start":2.38,"end":2.56,"text":"Part 2","coverage":0.5},{"start":4.95,"end":9.11,"text":"Woman: When you think of someone who is very rich, what comes to mind?","coverage":0.929},{"start":9.52,"end":24.28,"text":"Most people think that rich people live lavish lifestyles – that is, they drive very expensive cars, eat in expensive restaurants, own a yacht or live in big houses.","coverage":1.0},{"start":24.76,"end":30.94,"text":"But, as John Holm discovered, people who have money don’t actually do these things.","coverage":0.933},{"start":32.34,"end":36.06,"text":"Most millionaires actually seem to have ordinary lifestyles.","coverage":1.0},{"start":37.19,"end":43.17,"text":"In other words, they have normal cars, average houses and so on.","coverage":1.0},{"start":43.67,"end":54.13,"text":"On the other hand, people who look rich – the people who drive the latest Ferrari or only wear designer clothes – may not actually be rich at all.","coverage":1.0},{"start":54.73,"end":63.8,"text":"Instead, they have spent all their money trying to show off – showing other people that they might be wealthy.","coverage":1.0},{"start":64.16,"end":70.2,"text":"In other words, having expensive things is not always a sign that someone is rich.","coverage":1.0}],"file":"a4c172e936ca41228f94.js","track":0,"media":"../assets/media/e49dd86b1bec25f8ac9b493c2a3b6481775f967ca53fe994b2852cc3e4d61bab.mp3"}],"../assets/media/84a3bb0e3d6ecb9691d9ee819f65cd49e6465baa55d41913fc0161f751bf018c.mp3":[{"id":"PPT_84a3bb0e3d6ecb96","audioId":"PPT_84a3bb0e3d6ecb96","title":"Book 3 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 171","duration":83.51,"cues":[{"start":0.0,"end":1.44,"text":"one .seven","coverage":1.0},{"start":1.44,"end":6.08,"text":"It's often said that it's cruel to use animals for entertainment.","coverage":1.0},{"start":6.72,"end":9.7,"text":"However, I would like to argue against this idea.","coverage":1.0},{"start":10.54,"end":13.68,"text":"I know that many animal lovers would disagree with me,","coverage":1.0},{"start":13.98,"end":16.34,"text":"but let me explain my point of view.","coverage":1.0},{"start":17.32,"end":21.54,"text":"First of all, keeping animals in zoos helps protect them.","coverage":1.0},{"start":22.0,"end":22.92,"text":"For example,","coverage":1.0},{"start":23.3,"end":24.3,"text":"many species,","coverage":1.0},{"start":24.68,"end":27.58,"text":"such as the giant panda and the snow leopard,","coverage":1.0},{"start":28.12,"end":29.68,"text":"are endangered in the wild,","coverage":1.0},{"start":30.02,"end":32.58,"text":"so they are safer in zoos.","coverage":1.0},{"start":33.02,"end":37.18,"text":"Another point is that zoos have an important educational role.","coverage":1.0},{"start":37.8,"end":38.5,"text":"For instance,","coverage":1.0},{"start":38.84,"end":41.02,"text":"children can see animals up close.","coverage":1.0},{"start":41.6,"end":44.38,"text":"When I was a child, my father took me to the zoo.","coverage":1.0},{"start":44.92,"end":47.16,"text":"I learned about exotic animals,","coverage":1.0},{"start":47.52,"end":50.6,"text":"and I also learned to care about animals.","coverage":1.0},{"start":51.88,"end":54.28,"text":"Modern zoos have improved their conditions.","coverage":1.0},{"start":54.9,"end":55.54,"text":"Animals are","coverage":1.0},{"start":55.54,"end":55.72,"text":"no","coverage":1.0},{"start":55.72,"end":57.56,"text":"longer kept in small cages,","coverage":1.0},{"start":58.34,"end":63.38,"text":"and zoos have large areas where animals can feel as if they are in their natural habitat.","coverage":1.0},{"start":64.2,"end":65.34,"text":"To summarise,","coverage":1.0},{"start":65.7,"end":68.6,"text":"zoos help protect animals and educate us.","coverage":1.0},{"start":69.16,"end":69.74,"text":"In short,","coverage":1.0},{"start":70.56,"end":74.58,"text":"modern zoos are comfortable, safe places for wild animals.","coverage":1.0},{"start":74.58,"end":76.02,"text":"In conclusion,","coverage":1.0},{"start":76.82,"end":81.58,"text":"I believe that we should help zoos by visiting them and donating money.","coverage":1.0}],"file":"a5b7ee1b8445a5d21bc6.js","track":0,"media":"../assets/media/84a3bb0e3d6ecb9691d9ee819f65cd49e6465baa55d41913fc0161f751bf018c.mp3"}],"../assets/media/961cad02c552a02243944781c465b7d4fa53f7f8ce3970f29db022f8d4928f3a.mp3":[{"id":"PPT_961cad02c552a022","audioId":"PPT_961cad02c552a022","title":"Book 3 · Unit 8 · RW · READING 2","subtitle":"READING 2 · source slide 98","duration":215.82,"cues":[{"start":0.0,"end":3.46,"text":"What has happened to the dream of a better life?","coverage":1.0},{"start":5.08,"end":7.68,"text":"In almost every country and every culture,","coverage":1.0},{"start":8.02,"end":12.26,"text":"parents work hard to try to give their children a better life than they had.","coverage":1.0},{"start":13.0,"end":15.3,"text":"For decades following the Second World War,","coverage":1.0},{"start":15.76,"end":19.22,"text":"this dream became a reality in many countries around the world.","coverage":1.0},{"start":19.8,"end":23.86,"text":"Possibly the best example is the Japanese economic miracle.","coverage":1.0},{"start":24.66,"end":32.82,"text":"Thanks to a high rate of economic growth from the 1960s to the 1980s, it developed into one of the world's strongest economies.","coverage":1.0},{"start":33.72,"end":34.7,"text":"Yet in Japan,","coverage":1.0},{"start":35.02,"end":36.64,"text":"as in other developed countries,","coverage":1.0},{"start":37.22,"end":43.84,"text":"many people today are not able to enjoy a higher or even the same standard of living as their parents did.","coverage":1.0},{"start":44.52,"end":45.48,"text":"What has happened?","coverage":1.0},{"start":46.16,"end":50.32,"text":"Why do many people feel poorer than they were ten or 20 years ago?","coverage":1.0},{"start":51.1,"end":52.98,"text":"The answer is complicated,","coverage":1.0},{"start":53.5,"end":55.66,"text":"and every country tells a different story.","coverage":1.0},{"start":55.66,"end":59.26,"text":"The world's largest economy, the United States,","coverage":1.0},{"start":59.62,"end":60.82,"text":"provides a good example.","coverage":1.0},{"start":61.76,"end":65.72,"text":"One key factor which influences the standard of living is expenditure,","coverage":1.0},{"start":66.2,"end":68.9,"text":"which is the money you spend on the things that you need.","coverage":1.0},{"start":69.54,"end":72.0,"text":"From 2000 until 2015,","coverage":1.0},{"start":72.84,"end":76.74,"text":"Americans spent approximately 20 % of their incomes on housing,","coverage":1.0},{"start":77.22,"end":78.82,"text":"about ten % on food,","coverage":1.0},{"start":79.28,"end":81.08,"text":"about eight % on transport,","coverage":1.0},{"start":81.42,"end":84.7,"text":"and around three % each on entertainment and health.","coverage":1.0},{"start":84.7,"end":87.74,"text":"But these costs have been rising steadily.","coverage":1.0},{"start":88.5,"end":94.14,"text":"They now must spend about 34 % on housing and 13 % on food.","coverage":1.0},{"start":95.0,"end":97.84,"text":"In the United States, as in many other countries,","coverage":1.0},{"start":98.34,"end":102.8,"text":"the expenditures that are rising the fastest are housing and healthcare.","coverage":1.0},{"start":103.78,"end":105.38,"text":"In many cities worldwide,","coverage":1.0},{"start":105.78,"end":110.36,"text":"there is a serious shortage of houses and apartments to buy or rent.","coverage":1.0},{"start":111.04,"end":117.84,"text":"Healthcare costs also continue to rise as medicine and hospital care have become more expensive.","coverage":1.0},{"start":118.78,"end":119.68,"text":"Most recently,","coverage":1.0},{"start":120.12,"end":123.54,"text":"there have also been significant increases in food prices.","coverage":1.0},{"start":124.66,"end":125.08,"text":"However,","coverage":1.0},{"start":125.66,"end":127.52,"text":"expenditures are only half the picture.","coverage":1.0},{"start":128.24,"end":130.48,"text":"The other half is the money people earn,","coverage":1.0},{"start":130.98,"end":131.82,"text":"their income.","coverage":1.0},{"start":132.62,"end":134.56,"text":"In the United States, in general,","coverage":1.0},{"start":134.88,"end":136.56,"text":"incomes have also gone up.","coverage":1.0},{"start":136.84,"end":137.92,"text":"See figure one.","coverage":1.0},{"start":138.44,"end":141.96,"text":"Yet not all incomes are increasing at the same rate.","coverage":1.0},{"start":142.68,"end":146.26,"text":"For many people, they have not increased as much as expenditures.","coverage":1.0},{"start":147.16,"end":150.44,"text":"This means that their buying power has decreased.","coverage":1.0},{"start":151.34,"end":154.0,"text":"Figure two shows this increase in inequality.","coverage":1.0},{"start":154.82,"end":160.36,"text":"It shows change in income by group from the bottom 20 % to the top 20%.","coverage":1.0},{"start":161.26,"end":163.7,"text":"The top line shows the highest five%.","coverage":1.0},{"start":164.46,"end":170.08,"text":"It is clear that the incomes of the higher income groups are rising the fastest.","coverage":1.0},{"start":170.96,"end":174.32,"text":"The incomes of the lower groups are rising more slowly.","coverage":1.0},{"start":175.08,"end":180.38,"text":"It is not surprising that they do not have a higher standard of living than their parents.","coverage":1.0},{"start":181.72,"end":182.48,"text":"In conclusion,","coverage":1.0},{"start":182.98,"end":186.62,"text":"the impact of economic forces is not the same for everyone.","coverage":1.0},{"start":187.38,"end":188.74,"text":"In the United States,","coverage":1.0},{"start":189.24,"end":193.08,"text":"rising prices have had the greatest impact on the people with lower incomes.","coverage":1.0},{"start":193.08,"end":196.52,"text":"They must pay more for necessities like food,","coverage":1.0},{"start":196.88,"end":198.96,"text":"health care, and especially housing.","coverage":1.0},{"start":199.4,"end":200.36,"text":"And as a result,","coverage":1.0},{"start":200.74,"end":202.64,"text":"they have less money for education,","coverage":1.0},{"start":203.1,"end":203.56,"text":"investment,","coverage":1.0},{"start":203.98,"end":204.58,"text":"and savings.","coverage":1.0},{"start":205.4,"end":209.98,"text":"This makes it harder for the next generation to move up the economic ladder.","coverage":1.0},{"start":210.78,"end":215.76,"text":"For them, the dream of a better life than their parents is still only a dream.","coverage":1.0}],"file":"a5c7b49ef80d866be9b2.js","track":0,"media":"../assets/media/961cad02c552a02243944781c465b7d4fa53f7f8ce3970f29db022f8d4928f3a.mp3"}],"../assets/media/ae0b0565008796a3f745915aa4987ac2be0c0c4b9a13fd21bc9b3ea0566f6825.mp3":[{"id":"PPT_ae0b0565008796a3","audioId":"PPT_ae0b0565008796a3","title":"Book 3 · Unit 8 · RW · READING 1","subtitle":"READING 1 · source slide 42","duration":253.02,"cues":[{"start":0.0,"end":2.38,"text":"How should you invest your money?","coverage":1.0},{"start":3.3,"end":7.1,"text":"Many people put their money in a bank because it is safe.","coverage":1.0},{"start":7.62,"end":8.1,"text":"However,","coverage":1.0},{"start":8.54,"end":11.54,"text":"the interest rate at most banks is quite low.","coverage":1.0},{"start":12.28,"end":13.1,"text":"As a result,","coverage":1.0},{"start":13.56,"end":17.76,"text":"some people choose to invest their money in stocks and shares instead,","coverage":1.0},{"start":18.38,"end":22.08,"text":"because they hope their money will grow faster that way.","coverage":1.0},{"start":22.46,"end":22.9,"text":"Yet,","coverage":1.0},{"start":23.26,"end":25.64,"text":"investing in stocks can be risky.","coverage":1.0},{"start":25.64,"end":28.72,"text":"If the value of the stocks goes down,","coverage":1.0},{"start":29.12,"end":31.08,"text":"you could lose a lot of money.","coverage":1.0},{"start":31.94,"end":37.0,"text":"Many experts say you should invest only what you can afford to lose.","coverage":1.0},{"start":37.96,"end":38.22,"text":"So,","coverage":1.0},{"start":38.72,"end":44.34,"text":"what are some alternative investments for people who can afford to take big risks?","coverage":1.0},{"start":45.24,"end":49.82,"text":"Gold and classic cars are both popular investments.","coverage":1.0},{"start":51.44,"end":55.06,"text":"Over time, gold has been a very good investment.","coverage":1.0},{"start":55.06,"end":58.94,"text":"Though the price has fluctuated in recent years.","coverage":1.0},{"start":59.86,"end":63.54,"text":"Between 2017 and 2020, for example,","coverage":1.0},{"start":64.3,"end":72.7,"text":"the price rose from $one ,200 an ounce to a peak of $two ,800 an ounce.","coverage":1.0},{"start":73.54,"end":75.88,"text":"Then, by the end of 2022,","coverage":1.0},{"start":76.54,"end":79.4,"text":"it had fallen to $one ,800.","coverage":1.0},{"start":80.28,"end":81.86,"text":"By 2023,","coverage":1.0},{"start":82.38,"end":85.46,"text":"it rose again to $one ,900.","coverage":1.0},{"start":86.66,"end":89.38,"text":"If you are thinking about investing in gold,","coverage":1.0},{"start":89.94,"end":93.56,"text":"you may want to consider one famous investor's advice.","coverage":1.0},{"start":94.74,"end":95.64,"text":"Warren Buffett,","coverage":1.0},{"start":95.98,"end":98.12,"text":"one of the richest men in the world,","coverage":1.0},{"start":98.74,"end":100.76,"text":"dislikes gold as an investment.","coverage":1.0},{"start":101.74,"end":109.04,"text":"He points out that, historically, the stock market has brought in significantly higher returns than gold.","coverage":1.0},{"start":109.98,"end":118.6,"text":"He also says it is better for society if you use your money for something productive rather than have it sitting in a bank.","coverage":1.0},{"start":119.88,"end":124.34,"text":"While gold and stocks are both investment options in the long term,","coverage":1.0},{"start":124.9,"end":129.44,"text":"some people prefer investments that they can use and enjoy now.","coverage":1.0},{"start":129.92,"end":136.54,"text":"For these people, classic cars are one way to have fun and make lots of money.","coverage":1.0},{"start":137.28,"end":137.86,"text":"In fact,","coverage":1.0},{"start":138.28,"end":140.68,"text":"over the last 30 or 40 years,","coverage":1.0},{"start":141.1,"end":148.6,"text":"the value of some classic cars has risen far more than that of gold or other investments like houses.","coverage":1.0},{"start":149.86,"end":150.84,"text":"As an example,","coverage":1.0},{"start":151.34,"end":166.88,"text":"a 1972 Ferrari Dino 246 GT cost around $13 ,000 in 1980, but was worth as much as $370 ,000 in 2023.","coverage":1.0},{"start":168.18,"end":175.82,"text":"A man in Tennessee bought the Aston Martin DB5, which was used in two of the James Bond films.","coverage":1.0},{"start":176.76,"end":181.64,"text":"This car cost just $seven ,000 in 1980,","coverage":1.0},{"start":182.46,"end":187.56,"text":"but sold in 2010 for an incredible $four .one","coverage":1.0},{"start":187.56,"end":188.32,"text":"million.","coverage":1.0},{"start":189.34,"end":193.84,"text":"That is an incredible 20 ,000 % increase.","coverage":1.0},{"start":194.92,"end":200.88,"text":"But neither of these cars compares to what is perhaps the best investment ever.","coverage":1.0},{"start":202.04,"end":210.86,"text":"A 1955 Mercedes -Benz 300 SL cost about $36 ,000 in 1980,","coverage":1.0},{"start":211.6,"end":212.64,"text":"but is worth about $three ,000 in 2013.","coverage":1.0},{"start":212.66,"end":216.92,"text":"About $143 million now.","coverage":1.0},{"start":218.28,"end":218.94,"text":"In sum,","coverage":1.0},{"start":219.46,"end":224.04,"text":"the prospect of making lots of money through investing is very exciting.","coverage":1.0},{"start":224.76,"end":229.08,"text":"But one must never forget that investing is a risky business.","coverage":1.0},{"start":230.02,"end":233.2,"text":"Gold prices rise, but they also fall.","coverage":1.0},{"start":233.92,"end":236.68,"text":"The classic car market also fluctuates,","coverage":1.0},{"start":237.1,"end":241.6,"text":"and it is expensive to keep these cars in excellent condition.","coverage":1.0},{"start":242.66,"end":244.92,"text":"If you are clever and lucky,","coverage":1.0},{"start":245.42,"end":247.18,"text":"you may make a big profit.","coverage":1.0},{"start":247.94,"end":248.66,"text":"But remember,","coverage":1.0},{"start":249.28,"end":249.82,"text":"there are","coverage":1.0},{"start":249.82,"end":250.22,"text":"no","coverage":1.0},{"start":250.22,"end":250.98,"text":"guarantees.","coverage":1.0}],"file":"a67b53fb96d5e111739b.js","track":0,"media":"../assets/media/ae0b0565008796a3f745915aa4987ac2be0c0c4b9a13fd21bc9b3ea0566f6825.mp3"}],"../assets/media/a13a54da9ef687969d3b7027d30ba52a6b195a21be7c362d0ec1f0c503c846e0.mp3":[{"id":"PPT_a13a54da9ef68796","audioId":"PPT_a13a54da9ef68796","title":"Book 2 · Unit 7 · RW · READING 1","subtitle":"READING 1 · source slide 39","duration":223.06,"cues":[{"start":0.0,"end":1.98,"text":"Real life superheroes.","coverage":1.0},{"start":3.28,"end":4.34,"text":"About me.","coverage":1.0},{"start":4.88,"end":7.02,"text":"My name is Juliet Selby.","coverage":1.0},{"start":7.78,"end":10.0,"text":"I write about people that I admire.","coverage":1.0},{"start":10.84,"end":13.74,"text":"I write about a different person every week.","coverage":1.0},{"start":14.54,"end":17.74,"text":"Read about the real life superheroes here.","coverage":1.0},{"start":19.84,"end":20.76,"text":"2023,","coverage":1.0},{"start":21.72,"end":22.76,"text":"Ben Underwood.","coverage":1.0},{"start":23.8,"end":26.82,"text":"Ben Underwood was a normal teenage boy.","coverage":1.0},{"start":26.82,"end":29.22,"text":"He loved playing basketball,","coverage":1.0},{"start":29.66,"end":30.66,"text":"riding his bike,","coverage":1.0},{"start":31.12,"end":35.14,"text":"listening to music with his friends, and playing video games.","coverage":1.0},{"start":35.96,"end":37.38,"text":"But in one way,","coverage":1.0},{"start":37.74,"end":40.32,"text":"Ben was different from most other teenagers.","coverage":1.0},{"start":41.14,"end":42.28,"text":"He was blind.","coverage":1.0},{"start":43.24,"end":43.8,"text":"However,","coverage":1.0},{"start":44.4,"end":46.2,"text":"Ben had a special talent.","coverage":1.0},{"start":46.82,"end":48.46,"text":"He didn't have eyes,","coverage":1.0},{"start":48.82,"end":51.04,"text":"but he could still see.","coverage":1.0},{"start":51.88,"end":55.68,"text":"Ben was born on the 26th of January,","coverage":1.0},{"start":56.06,"end":57.4,"text":"1992.","coverage":1.0},{"start":58.3,"end":60.9,"text":"For the first two years of his life,","coverage":1.0},{"start":61.36,"end":63.76,"text":"Ben was a happy and healthy baby.","coverage":1.0},{"start":64.56,"end":66.3,"text":"He had a normal life,","coverage":1.0},{"start":66.82,"end":71.1,"text":"living with his mother and two older brothers in California.","coverage":1.0},{"start":72.34,"end":72.92,"text":"However,","coverage":1.0},{"start":73.46,"end":75.58,"text":"when Ben was two years old,","coverage":1.0},{"start":75.94,"end":77.34,"text":"his life changed.","coverage":1.0},{"start":78.02,"end":79.68,"text":"In 1994,","coverage":1.0},{"start":80.36,"end":85.36,"text":"he was taken to the hospital because he had problems with his eyes.","coverage":1.0},{"start":86.36,"end":91.32,"text":"The doctors looked at his eyes and told his mother the bad news.","coverage":1.0},{"start":91.94,"end":93.4,"text":"Ben had cancer.","coverage":1.0},{"start":94.38,"end":95.8,"text":"After a few months,","coverage":1.0},{"start":96.12,"end":99.34,"text":"he had an operation to remove the cancer.","coverage":1.0},{"start":100.34,"end":102.44,"text":"The operation was successful,","coverage":1.0},{"start":102.86,"end":104.54,"text":"and Ben was fine.","coverage":1.0},{"start":105.34,"end":105.8,"text":"However,","coverage":1.0},{"start":106.42,"end":108.82,"text":"the doctors had to remove his eyes,","coverage":1.0},{"start":109.34,"end":111.34,"text":"and Ben became blind.","coverage":1.0},{"start":112.72,"end":114.4,"text":"After his operation,","coverage":1.0},{"start":115.02,"end":118.96,"text":"Ben developed an incredible talent like a superhero.","coverage":1.0},{"start":119.94,"end":121.34,"text":"When he was three,","coverage":1.0},{"start":121.84,"end":125.38,"text":"he learned how to see buildings with his ears.","coverage":1.0},{"start":126.3,"end":128.36,"text":"He listened very carefully,","coverage":1.0},{"start":128.68,"end":132.48,"text":"and he could hear noises bounce off buildings.","coverage":1.0},{"start":133.2,"end":136.78,"text":"The noises told him where the buildings were.","coverage":1.0},{"start":137.8,"end":138.24,"text":"Then,","coverage":1.0},{"start":138.68,"end":140.08,"text":"when Ben was seven,","coverage":1.0},{"start":140.54,"end":142.0,"text":"he learned to click.","coverage":1.0},{"start":142.86,"end":145.74,"text":"He made clicking noises with his mouth,","coverage":1.0},{"start":146.4,"end":150.36,"text":"and listened for the noises that bounced back from things.","coverage":1.0},{"start":151.3,"end":152.5,"text":"In this way,","coverage":1.0},{"start":152.9,"end":157.42,"text":"Ben could see where he was and what was around him.","coverage":1.0},{"start":158.2,"end":162.16,"text":"This is the same way dolphins see things underwater,","coverage":1.0},{"start":162.88,"end":165.04,"text":"and bats see in the dark.","coverage":1.0},{"start":166.52,"end":170.72,"text":"Scientists and doctors were amazed by Ben's talent.","coverage":1.0},{"start":171.52,"end":176.78,"text":"There are only a few blind people in the world who can see like Ben.","coverage":1.0},{"start":177.86,"end":180.34,"text":"People respected him because of this.","coverage":1.0},{"start":180.9,"end":182.24,"text":"He became famous.","coverage":1.0},{"start":182.7,"end":184.48,"text":"He was on TV,","coverage":1.0},{"start":185.02,"end":190.52,"text":"and he traveled to different countries and talked to people about his life.","coverage":1.0},{"start":191.54,"end":192.22,"text":"Sadly,","coverage":1.0},{"start":192.68,"end":194.12,"text":"when Ben was 16,","coverage":1.0},{"start":194.62,"end":196.28,"text":"his cancer came back.","coverage":1.0},{"start":196.88,"end":198.84,"text":"He died soon after.","coverage":1.0},{"start":199.58,"end":200.08,"text":"However,","coverage":1.0},{"start":200.62,"end":201.94,"text":"during Ben's life,","coverage":1.0},{"start":202.34,"end":205.84,"text":"he taught people that anything is possible.","coverage":1.0},{"start":206.64,"end":212.84,"text":"Many people admired him because he inspired them and helped them feel strong.","coverage":1.0},{"start":213.94,"end":216.62,"text":"When he died in 2009,","coverage":1.0},{"start":217.42,"end":221.1,"text":"over two ,000 people went to his funeral.","coverage":1.0}],"file":"a8035a548638c393bc19.js","track":0,"media":"../assets/media/a13a54da9ef687969d3b7027d30ba52a6b195a21be7c362d0ec1f0c503c846e0.mp3"}],"../assets/media/91c2d6e131422bd80badd663f3864731f37172b73aef2c380d0cec1a6cf488bc.mp3":[{"id":"PPT_91c2d6e131422bd8","audioId":"PPT_91c2d6e131422bd8","title":"Book 2 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 85","duration":299.15,"cues":[{"start":0.0,"end":1.52,"text":"one .three","coverage":1.0},{"start":2.82,"end":4.5,"text":"OK, everyone.","coverage":1.0},{"start":5.22,"end":8.76,"text":"Today we are talking about interesting places.","coverage":1.0},{"start":9.4,"end":15.12,"text":"I'd like to talk about the city of Vancouver in British Columbia,","coverage":1.0},{"start":15.42,"end":15.74,"text":"Canada.","coverage":1.0},{"start":16.72,"end":20.28,"text":"It's one of the most beautiful cities in the world.","coverage":1.0},{"start":21.44,"end":24.52,"text":"We often think cities are urban areas,","coverage":1.0},{"start":25.12,"end":27.64,"text":"with traffic and modern buildings.","coverage":1.0},{"start":28.46,"end":33.42,"text":"We don't usually think cities have woods, lakes and fields,","coverage":1.0},{"start":34.18,"end":37.08,"text":"but Vancouver is a green city,","coverage":1.0},{"start":37.74,"end":41.8,"text":"a place that's good to live in because it has clean air,","coverage":1.0},{"start":42.16,"end":43.9,"text":"water and land.","coverage":1.0},{"start":45.0,"end":50.52,"text":"Vancouver has the best parts of green forests and city life.","coverage":1.0},{"start":51.36,"end":55.76,"text":"I would like to talk about some of the history of Vancouver,","coverage":1.0},{"start":56.7,"end":62.26,"text":"as well as some of the advantages and disadvantages of this green city.","coverage":1.0},{"start":63.56,"end":64.16,"text":"Vancouver,","coverage":1.0},{"start":64.56,"end":65.2,"text":"originally,","coverage":1.0},{"start":65.76,"end":77.36,"text":"was a place where the native people of the area lived and traded for thousands of years before Europeans came to live there in the 1800s.","coverage":1.0},{"start":78.2,"end":78.7,"text":"Then,","coverage":1.0},{"start":79.16,"end":80.6,"text":"in 1886,","coverage":1.0},{"start":81.1,"end":82.78,"text":"at the first city meeting,","coverage":1.0},{"start":83.62,"end":92.54,"text":"the people of Vancouver asked the national government to give the city one thousand acres to use as a park.","coverage":1.0},{"start":93.94,"end":98.58,"text":"They got the land from the government and started Stanley Park.","coverage":1.0},{"start":98.58,"end":107.1,"text":"This was the start of Vancouver becoming a green city with many parks and beautiful views.","coverage":1.0},{"start":108.32,"end":114.54,"text":"But being a green city with lots of parks has both advantages and disadvantages.","coverage":1.0},{"start":115.84,"end":118.8,"text":"First of all, let's look at some of the positives.","coverage":1.0},{"start":119.98,"end":120.66,"text":"Obviously,","coverage":1.0},{"start":121.24,"end":123.26,"text":"Stanley Park is a large park.","coverage":1.0},{"start":123.26,"end":127.22,"text":"In fact, because it is located in the city of Vancouver,","coverage":1.0},{"start":127.88,"end":131.86,"text":"it is the third largest urban park in North America.","coverage":1.0},{"start":132.98,"end":134.66,"text":"It has many gardens,","coverage":1.0},{"start":135.24,"end":136.24,"text":"walking paths,","coverage":1.0},{"start":136.72,"end":141.24,"text":"trees and even animals such as bald eagles,","coverage":1.0},{"start":141.6,"end":143.48,"text":"coyotes and seals.","coverage":1.0},{"start":144.82,"end":149.54,"text":"As we know, lots of trees help clean the city air.","coverage":1.0},{"start":149.54,"end":150.96,"text":"Also,","coverage":1.0},{"start":151.54,"end":156.52,"text":"lots of parks give people many places to walk so they're healthier.","coverage":1.0},{"start":157.68,"end":161.16,"text":"Since Vancouver is near the mountains and the ocean,","coverage":1.0},{"start":161.8,"end":167.2,"text":"people can enjoy the outdoors easily during the warm, sunny summers.","coverage":1.0},{"start":168.4,"end":170.72,"text":"When people go to Stanley Park,","coverage":1.0},{"start":171.22,"end":175.64,"text":"they can enjoy ancient trees as they walk near the ocean.","coverage":1.0},{"start":175.64,"end":179.52,"text":"Or they can have fun by Beaver Lake,","coverage":1.0},{"start":179.84,"end":181.54,"text":"which, like Stanley Park,","coverage":1.0},{"start":182.12,"end":187.94,"text":"helps make Vancouver one of the healthiest and cleanest cities in the world.","coverage":1.0},{"start":189.38,"end":194.12,"text":"I'd also like to talk about some disadvantages of parks in Vancouver.","coverage":1.0},{"start":195.34,"end":198.36,"text":"Space in a city is very important.","coverage":1.0},{"start":198.36,"end":205.52,"text":"Having many parks means that people have less space to build houses and apartments.","coverage":1.0},{"start":206.82,"end":211.1,"text":"Because Vancouver is located between the mountains and the ocean,","coverage":1.0},{"start":211.82,"end":214.18,"text":"there's not much room for new buildings.","coverage":1.0},{"start":215.02,"end":217.92,"text":"This makes Vancouver an expensive city.","coverage":1.0},{"start":218.96,"end":219.52,"text":"Also,","coverage":1.0},{"start":219.84,"end":222.18,"text":"when you have a beautiful place to live,","coverage":1.0},{"start":222.9,"end":225.06,"text":"a lot of people want to go there.","coverage":1.0},{"start":225.06,"end":227.9,"text":"This makes the city crowded.","coverage":1.0},{"start":229.16,"end":229.5,"text":"Actually,","coverage":1.0},{"start":229.96,"end":232.4,"text":"Vancouver has very bad traffic.","coverage":1.0},{"start":233.72,"end":234.24,"text":"Lastly,","coverage":1.0},{"start":234.62,"end":236.18,"text":"when you have a lot of parks,","coverage":1.0},{"start":236.98,"end":240.76,"text":"wild animals in the parks can sometimes be a problem.","coverage":1.0},{"start":241.7,"end":242.62,"text":"For example,","coverage":1.0},{"start":243.46,"end":249.12,"text":"Stanley Park gives information to people about what to do if they see a coyote.","coverage":1.0},{"start":249.98,"end":251.02,"text":"In my opinion,","coverage":1.0},{"start":251.48,"end":254.06,"text":"having coyotes in a city park is bad.","coverage":1.0},{"start":254.06,"end":255.56,"text":"Finally,","coverage":1.0},{"start":256.14,"end":262.5,"text":"while I think these disadvantages might mean that some people would not want to visit Vancouver,","coverage":1.0},{"start":263.46,"end":268.12,"text":"I personally feel that most people would enjoy Vancouver.","coverage":1.0},{"start":268.68,"end":277.08,"text":"In my opinion, being close to nature and having a healthy city are worth paying a little more money for.","coverage":1.0},{"start":277.08,"end":280.42,"text":"And a lot of people agree with this idea,","coverage":1.0},{"start":281.22,"end":286.28,"text":"because Vancouver is a very popular place to visit and live in.","coverage":1.0},{"start":287.56,"end":292.84,"text":"So I would recommend that people visit Vancouver and enjoy the many parks,","coverage":1.0},{"start":293.38,"end":294.0,"text":"the clean,","coverage":1.0},{"start":294.44,"end":297.24,"text":"healthy city and the interesting sights.","coverage":1.0}],"file":"a82c2f1f77fc5312f206.js","track":0,"media":"../assets/media/91c2d6e131422bd80badd663f3864731f37172b73aef2c380d0cec1a6cf488bc.mp3"}],"../assets/media/c4248e7c6ce61ce13b0573a685194626ef4e31ea017ff9f17501d97a65a3ead1.mp3":[{"id":"PPT_c4248e7c6ce61ce1","audioId":"PPT_c4248e7c6ce61ce1","title":"Book 3 · Unit 3 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 98","duration":149.84,"cues":[{"start":2.1,"end":2.44,"text":"Hello","coverage":1.0},{"start":2.44,"end":3.46,"text":"everyone.","coverage":1.0},{"start":3.94,"end":5.68,"text":"Thank you for being here today.","coverage":1.0},{"start":6.24,"end":9.58,"text":"Welcome to the first meeting of Wheels to Work.","coverage":1.0},{"start":10.18,"end":15.42,"text":"As you know, the goal of this group is to make our city more bicycle -friendly.","coverage":1.0},{"start":16.12,"end":16.8,"text":"Specifically,","coverage":1.0},{"start":17.24,"end":21.16,"text":"we'd like to make it easier for people to cycle to work.","coverage":1.0},{"start":21.78,"end":26.96,"text":"Cycling to work is good for the environment and it provides great exercise.","coverage":1.0},{"start":27.62,"end":28.72,"text":"And personally,","coverage":1.0},{"start":29.06,"end":30.52,"text":"I think it's a lot of fun.","coverage":1.0},{"start":31.36,"end":39.0,"text":"I'm hoping that we can work together to solve the problems which can make it difficult for city residents to cycle to work.","coverage":1.0},{"start":39.74,"end":45.94,"text":"Today, I'm going to talk about a few of those problems and share some ideas for solving them.","coverage":1.0},{"start":46.7,"end":49.28,"text":"So, the biggest issue is safety.","coverage":1.0},{"start":50.16,"end":54.32,"text":"A lot of people would love to cycle to work, but they're scared.","coverage":1.0},{"start":54.84,"end":57.22,"text":"They feel that it's just too dangerous.","coverage":1.0},{"start":58.08,"end":67.56,"text":"This is because there's a lot of traffic during rush hour when most people drive to or from work and there's very little space for cyclists.","coverage":1.0},{"start":67.8,"end":74.8,"text":"Many of the cycle lanes we have are too narrow and some of the busiest streets don't even have cycle lanes.","coverage":1.0},{"start":75.84,"end":80.16,"text":"What's more, many drivers don't have respect for cyclists.","coverage":1.0},{"start":80.42,"end":84.8,"text":"Cars sometimes even drive in the cycle lanes to pass other cars.","coverage":1.0},{"start":85.58,"end":88.02,"text":"Of course, if a car hits a bicycle,","coverage":1.0},{"start":88.44,"end":91.64,"text":"it's going to injure or even kill the cyclist.","coverage":1.0},{"start":92.3,"end":94.3,"text":"A second issue is storage.","coverage":1.0},{"start":94.82,"end":99.82,"text":"Many people don't have a safe place to put their bicycles while they're at work.","coverage":1.0},{"start":100.52,"end":103.76,"text":"They worry that if they leave their bicycle outside,","coverage":1.0},{"start":104.08,"end":105.0,"text":"it'll get stolen.","coverage":1.0},{"start":105.78,"end":110.6,"text":"Also, it'll get wet when it rains and get damaged over time.","coverage":1.0},{"start":111.44,"end":116.98,"text":"A third problem is that for some people, cycling to work isn't convenient.","coverage":1.0},{"start":117.5,"end":124.78,"text":"Maybe they live far from their job or maybe they sometimes work late and don't want to cycle home in the dark.","coverage":1.0},{"start":125.58,"end":129.24,"text":"And a lot of people don't like to cycle in the rain.","coverage":1.0},{"start":130.0,"end":133.88,"text":"What if you cycle to work and then later it starts raining?","coverage":1.0},{"start":134.76,"end":136.16,"text":"From my own experience,","coverage":1.0},{"start":136.52,"end":140.46,"text":"I can tell you that it's pretty terrible to ride home during a storm.","coverage":1.0},{"start":141.36,"end":141.78,"text":"So,","coverage":1.0},{"start":142.24,"end":144.4,"text":"those are three of the biggest issues,","coverage":1.0},{"start":144.86,"end":145.38,"text":"safety,","coverage":1.0},{"start":145.96,"end":147.86,"text":"storage and convenience.","coverage":1.0}],"file":"a942701ddb54264556fb.js","track":0,"media":"../assets/media/c4248e7c6ce61ce13b0573a685194626ef4e31ea017ff9f17501d97a65a3ead1.mp3"}],"../assets/media/e45f3d81628c7550ae54fff71133ad0f7c8163e3683bc5c6dc7c315f026f7bdd.mp3":[{"id":"B3_U03_T3.6_SHORT_S04_v01","audioId":"B3_U03_T3.6_SHORT_S04_v01","title":"Book 3 · Unit 3 · H2 · 听力材料 9","subtitle":"H2 · 3.6-S04","duration":38.829569,"cues":[{"start":0,"end":6.03,"text":"A third problem is that, for some people, cycling to work isn’t convenient.","coverage":1.0},{"start":6.8,"end":14.43,"text":"Maybe they live far from their job or maybe they sometimes work late and don’t want to cycle home in the dark.","coverage":1.0},{"start":14.92,"end":18.92,"text":"And a lot of people don’t like to cycle in the rain.","coverage":1.0},{"start":19.24,"end":23.61,"text":"What if you cycle to work and then later it starts raining?","coverage":1.0},{"start":23.96,"end":29.91,"text":"From my own experience, I can tell you that it’s pretty terrible to ride home during a storm.","coverage":1.0},{"start":30.48,"end":36.51,"text":"So, those are three of the biggest issues: safety, storage and convenience.","coverage":1.0}],"file":"a96b93aa72453f7d9638.js","track":8,"media":"../assets/media/e45f3d81628c7550ae54fff71133ad0f7c8163e3683bc5c6dc7c315f026f7bdd.mp3"}],"../assets/media/cec5d849a4760914957f122745b8d61cf9fd5b939e06224f63f82733ecf2f8c0.mp3":[{"id":"B3_U03_T3.7_SHORT_S02_v01","audioId":"B3_U03_T3.7_SHORT_S02_v01","title":"Book 3 · Unit 3 · H2 · 听力材料 11","subtitle":"H2 · 3.7-S02","duration":14.773311,"cues":[{"start":0.03,"end":9.53,"text":"As for the issue of storage, I think that city parking garages ought to create special parking sections for bicycles.","coverage":0.95},{"start":9.95,"end":14.04,"text":"This would keep bicycles safe and dry while people are working.","coverage":1.0}],"file":"a96b93aa72453f7d9638.js","track":10,"media":"../assets/media/cec5d849a4760914957f122745b8d61cf9fd5b939e06224f63f82733ecf2f8c0.mp3"}],"../assets/media/c7e6818264df7e3b267fd0544aca9b31457fc11439e74189978e23c9de2676d4.mp3":[{"id":"PPT_c7e6818264df7e3b","audioId":"PPT_c7e6818264df7e3b","title":"Book 3 · Unit 1 · RW · READING 2","subtitle":"READING 2 · source slide 91","duration":246.86,"cues":[{"start":0.0,"end":5.94,"text":"Invasive species are plants and animals which arrive in an area where they are not native,","coverage":1.0},{"start":6.36,"end":7.92,"text":"usually due to human activity.","coverage":1.0},{"start":8.56,"end":9.22,"text":"For example,","coverage":1.0},{"start":9.64,"end":17.94,"text":"a species of shellfish might attach itself to the outside of a ship traveling between countries and enter a new environment in this way.","coverage":1.0},{"start":18.96,"end":23.82,"text":"Invasive species are often able to grow quickly in their new homes because they have","coverage":1.0},{"start":23.82,"end":24.06,"text":"no","coverage":1.0},{"start":24.06,"end":25.0,"text":"natural enemies.","coverage":1.0},{"start":25.44,"end":26.32,"text":"As a result,","coverage":1.0},{"start":26.74,"end":31.54,"text":"they may replace or damage native plants and animals which live in the same environment.","coverage":1.0},{"start":32.44,"end":36.92,"text":"One example is the case of gray and red squirrels in the United Kingdom.","coverage":1.0},{"start":37.92,"end":42.44,"text":"Red squirrels used to be a common sight in British forests and countryside.","coverage":1.0},{"start":43.18,"end":53.74,"text":"Then, in the 1870s, the gray squirrel was introduced from North America because rich people thought the squirrels looked fashionable in the gardens of their large homes.","coverage":1.0},{"start":54.3,"end":54.98,"text":"Today,","coverage":1.0},{"start":55.62,"end":59.4,"text":"only about 140 ,000 red squirrels remain,","coverage":1.0},{"start":59.76,"end":60.96,"text":"mostly in Scotland.","coverage":1.0},{"start":61.68,"end":62.5,"text":"In contrast,","coverage":1.0},{"start":63.1,"end":70.62,"text":"gray squirrels are now extremely common and seen as major pests due to the damage they cause to plants and houses.","coverage":1.0},{"start":71.56,"end":73.2,"text":"While red squirrels are protected,","coverage":1.0},{"start":73.7,"end":76.42,"text":"gray squirrels can be legally trapped and destroyed.","coverage":1.0},{"start":77.46,"end":78.4,"text":"At first sight,","coverage":1.0},{"start":78.8,"end":80.9,"text":"the two species of squirrel are similar.","coverage":1.0},{"start":81.24,"end":86.3,"text":"They both have a long tail which helps them balance when jumping from tree to tree,","coverage":1.0},{"start":86.7,"end":88.42,"text":"and the same large eyes,","coverage":1.0},{"start":88.78,"end":89.54,"text":"small ears,","coverage":1.0},{"start":89.86,"end":91.46,"text":"and powerful back legs.","coverage":1.0},{"start":92.24,"end":93.08,"text":"In contrast,","coverage":1.0},{"start":93.44,"end":97.08,"text":"the two types of squirrel are different in body size and weight.","coverage":1.0},{"start":97.88,"end":107.88,"text":"The red squirrel has a typical head and body length of approximately 19 to 23 centimeters, a tail length of 15 to 20 centimeters,","coverage":1.0},{"start":108.48,"end":113.2,"text":"and a body weight of 250 to 340 grams.","coverage":1.0},{"start":114.12,"end":116.94,"text":"The gray squirrel is larger than the red squirrel.","coverage":1.0},{"start":117.66,"end":121.64,"text":"The head and body measure between 23 and 30 centimeters,","coverage":1.0},{"start":122.14,"end":126.18,"text":"and the tail is between 19 and 25 centimeters long.","coverage":1.0},{"start":127.18,"end":129.6,"text":"Adult gray squirrels are also heavier,","coverage":1.0},{"start":130.26,"end":133.34,"text":"weighing between 400 and 600 grams.","coverage":1.0},{"start":134.14,"end":139.44,"text":"This size allows them to store more fat and helps them to survive hard winters,","coverage":1.0},{"start":139.78,"end":142.38,"text":"which can be fatal to their smaller cousins.","coverage":1.0},{"start":144.02,"end":149.82,"text":"Three more differences explain why red squirrels have lost out in the competition with gray squirrels.","coverage":1.0},{"start":150.86,"end":151.28,"text":"First,","coverage":1.0},{"start":151.76,"end":154.08,"text":"red squirrels live high up in the trees,","coverage":1.0},{"start":154.62,"end":158.12,"text":"whereas gray squirrels spend most of their time on the ground.","coverage":1.0},{"start":159.0,"end":165.22,"text":"This means that any loss of forest habitat greatly affects the red squirrel population.","coverage":1.0},{"start":166.44,"end":173.9,"text":"Another reason is that gray squirrels are more intelligent and can adapt to new situations more easily than red squirrels.","coverage":1.0},{"start":174.72,"end":175.52,"text":"For example,","coverage":1.0},{"start":175.96,"end":182.1,"text":"they can survive in an urban environment because of their ability to use food provided by humans.","coverage":1.0},{"start":183.26,"end":186.18,"text":"A third problem for the red squirrel is disease.","coverage":1.0},{"start":186.98,"end":189.64,"text":"Both squirrels carry Parapox virus.","coverage":1.0},{"start":190.38,"end":195.3,"text":"The virus does not seem to affect gray squirrels, but it is fatal to reds.","coverage":1.0},{"start":196.84,"end":197.74,"text":"In conclusion,","coverage":1.0},{"start":198.06,"end":203.42,"text":"there does not seem to be much that scientists can do to help red squirrels survive in Britain.","coverage":1.0},{"start":204.4,"end":211.64,"text":"Some politicians support destroying populations of gray squirrels, but many British people would contend that this is cruel.","coverage":1.0},{"start":212.44,"end":216.5,"text":"Red squirrels have been successfully reintroduced from other countries,","coverage":1.0},{"start":216.98,"end":219.26,"text":"and they could be protected in places where there are","coverage":1.0},{"start":219.26,"end":219.46,"text":"no","coverage":1.0},{"start":219.46,"end":222.22,"text":"gray squirrels, such as the Isle of Wight.","coverage":1.0},{"start":223.1,"end":223.46,"text":"However,","coverage":1.0},{"start":224.08,"end":227.82,"text":"some people question whether Britain should protect red squirrels at all.","coverage":1.0},{"start":228.68,"end":229.36,"text":"Worldwide,","coverage":1.0},{"start":229.7,"end":231.66,"text":"they are not an endangered species.","coverage":1.0},{"start":232.46,"end":233.64,"text":"Considering the evidence,","coverage":1.0},{"start":234.06,"end":238.38,"text":"saving the red squirrel may be a waste of British government money.","coverage":1.0},{"start":238.38,"end":244.9,"text":"Government conservation funding should instead be spent on other endangered animals.","coverage":1.0}],"file":"a9ecbde90b9c985b8090.js","track":0,"media":"../assets/media/c7e6818264df7e3b267fd0544aca9b31457fc11439e74189978e23c9de2676d4.mp3"}],"../assets/media/4ef34c52618f71d8774ddb0d029ef28c999545da7ab22472c5463db1b1c90251.mp3":[{"id":"PPT_4ef34c52618f71d8","audioId":"PPT_4ef34c52618f71d8","title":"Book 3 · Unit 6 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 106","duration":285.26,"cues":[{"start":0.0,"end":1.56,"text":"six .five","coverage":1.0},{"start":1.56,"end":6.36,"text":"I'd like to start by talking a little bit about the first apps.","coverage":1.0},{"start":6.98,"end":9.44,"text":"These were included with each smartphone.","coverage":1.0},{"start":10.12,"end":15.06,"text":"These types of apps were placed in the phones to help users access the internet,","coverage":1.0},{"start":15.46,"end":16.24,"text":"check emails,","coverage":1.0},{"start":16.64,"end":18.42,"text":"send texts, and so on.","coverage":1.0},{"start":19.12,"end":26.5,"text":"The first apps were designed to increase efficiency at work and allow people to access important information.","coverage":1.0},{"start":26.5,"end":27.74,"text":"However,","coverage":1.0},{"start":28.18,"end":32.48,"text":"it was the second generation of apps that really changed things.","coverage":1.0},{"start":33.1,"end":35.14,"text":"These were downloadable apps.","coverage":1.0},{"start":35.76,"end":40.72,"text":"Users simply downloaded apps from the internet and installed them on their phones.","coverage":1.0},{"start":41.42,"end":46.94,"text":"Since its introduction, the app market has grown far beyond anyone's expectations.","coverage":1.0},{"start":47.72,"end":51.6,"text":"The first app store was opened in 2008.","coverage":1.0},{"start":51.6,"end":53.26,"text":"By 2011,","coverage":1.0},{"start":53.56,"end":56.88,"text":"it was reporting over ten billion downloads,","coverage":1.0},{"start":57.26,"end":61.3,"text":"and people were using apps more than internet browsers on their phones.","coverage":1.0},{"start":61.94,"end":63.44,"text":"And by 2017,","coverage":1.0},{"start":63.82,"end":68.6,"text":"an estimated 180 billion apps had been downloaded.","coverage":1.0},{"start":69.12,"end":71.82,"text":"These numbers have been growing ever since,","coverage":1.0},{"start":72.14,"end":78.2,"text":"and they give us a good idea about how popular apps are and how quickly they've developed.","coverage":1.0},{"start":78.2,"end":85.04,"text":"People from all over the world use apps for entertainment, travel, and communication.","coverage":1.0},{"start":85.7,"end":91.36,"text":"So I'm going to briefly talk about how these apps have changed our lives.","coverage":1.0},{"start":92.18,"end":96.8,"text":"It's hard to imagine life before smartphones and mobile phone apps,","coverage":1.0},{"start":97.24,"end":103.98,"text":"or for those of us who are old enough to remember it, but let's go ahead and make an attempt anyway.","coverage":1.0},{"start":103.98,"end":109.99,"text":"So imagine for a moment that you're taking a road trip in the days before smartphones.","coverage":1.0},{"start":111.3,"end":112.52,"text":"Weeks before the trip,","coverage":1.0},{"start":112.86,"end":118.54,"text":"you go to the bookstore or library to get some guidebooks about the places you're going to visit.","coverage":1.0},{"start":119.24,"end":121.08,"text":"A few days before you leave,","coverage":1.0},{"start":121.5,"end":125.38,"text":"you get some audiobooks to entertain you during the long trip.","coverage":1.0},{"start":126.02,"end":128.54,"text":"You go to a shop and buy some maps.","coverage":1.0},{"start":129.2,"end":129.7,"text":"Yes,","coverage":1.0},{"start":130.1,"end":131.2,"text":"the paper kind.","coverage":1.0},{"start":131.2,"end":139.06,"text":"The day before the trip, you sit down at your computer and look up the directions and print them out.","coverage":1.0},{"start":139.62,"end":143.46,"text":"Then you pack some of your favorite CDs to bring along.","coverage":1.0},{"start":144.02,"end":148.82,"text":"You also pack your camera and your torch in case your car breaks down.","coverage":1.0},{"start":149.24,"end":156.84,"text":"And you write down some phone numbers and addresses of the friends you'll be visiting and the hotels where you'll be staying.","coverage":1.0},{"start":157.82,"end":159.22,"text":"While you're driving,","coverage":1.0},{"start":159.54,"end":163.74,"text":"your passenger reads the directions to you and looks for street signs.","coverage":1.0},{"start":164.36,"end":169.04,"text":"If you get lost, you stop at a petrol station to ask for directions.","coverage":1.0},{"start":169.52,"end":172.22,"text":"You have to write them down on a piece of paper.","coverage":1.0},{"start":173.02,"end":173.62,"text":"Okay,","coverage":1.0},{"start":174.0,"end":176.44,"text":"so I think you get the idea.","coverage":1.0},{"start":177.32,"end":180.84,"text":"Now, let's make a comparison with the same trip today.","coverage":1.0},{"start":180.84,"end":181.3,"text":"No","coverage":1.0},{"start":181.3,"end":182.22,"text":"books,","coverage":1.0},{"start":182.8,"end":182.91,"text":"no","coverage":1.0},{"start":182.91,"end":183.56,"text":"maps,","coverage":1.0},{"start":183.94,"end":184.07,"text":"no","coverage":1.0},{"start":184.07,"end":184.84,"text":"CDs,","coverage":1.0},{"start":185.34,"end":185.46,"text":"no","coverage":1.0},{"start":185.46,"end":186.88,"text":"lists of phone numbers,","coverage":1.0},{"start":187.18,"end":187.31,"text":"no","coverage":1.0},{"start":187.31,"end":189.02,"text":"friend giving you directions.","coverage":1.0},{"start":189.58,"end":191.7,"text":"The smartphone does it all.","coverage":1.0},{"start":192.54,"end":195.92,"text":"Think of the apps you'd use just for that one trip.","coverage":1.0},{"start":196.4,"end":199.92,"text":"You'd read reviews and book your hotel with a travel app.","coverage":1.0},{"start":200.38,"end":205.6,"text":"The GPS would replace the directions and maps and your friend in the front seat.","coverage":1.0},{"start":205.6,"end":213.74,"text":"Of course, a music app would replace the CDs and you could listen to podcasts as well as audiobooks.","coverage":1.0},{"start":213.84,"end":217.96,"text":"And of course, you wouldn't need to bring a camera or a torch.","coverage":1.0},{"start":218.66,"end":223.98,"text":"Yes, we've certainly made a lot of progress since the pre -smartphone days.","coverage":1.0},{"start":224.84,"end":225.22,"text":"So,","coverage":1.0},{"start":225.6,"end":229.84,"text":"now I'd like to mention another important effect of the invention of apps.","coverage":1.0},{"start":230.6,"end":234.32,"text":"It has created a whole new IT sector.","coverage":1.0},{"start":234.32,"end":240.6,"text":"It is one of the fastest growing industries and there is a great need for skilled software engineers.","coverage":1.0},{"start":241.64,"end":244.28,"text":"But apps have also had some negative effects.","coverage":1.0},{"start":244.88,"end":251.06,"text":"For one thing, people have become more helpless because they're so dependent on their phones for information.","coverage":1.0},{"start":251.84,"end":254.06,"text":"For example, if they're in a place with","coverage":1.0},{"start":254.06,"end":254.42,"text":"no","coverage":1.0},{"start":254.42,"end":259.48,"text":"phone signal, they're not very good at asking for and following directions.","coverage":1.0},{"start":259.48,"end":265.18,"text":"And apps have made people less patient because they expect to have information immediately.","coverage":1.0},{"start":266.28,"end":266.86,"text":"In fact,","coverage":1.0},{"start":267.16,"end":275.6,"text":"a recent study found that 87 % of smartphone users leave a web page if it doesn't load in two seconds.","coverage":1.0},{"start":276.72,"end":277.18,"text":"Okay,","coverage":1.0},{"start":277.62,"end":279.18,"text":"in the next part of the lecture,","coverage":1.0},{"start":279.62,"end":283.38,"text":"I'll discuss some of the most common apps in more details.","coverage":1.0}],"file":"af907f48532db4c9fb5c.js","track":0,"media":"../assets/media/4ef34c52618f71d8774ddb0d029ef28c999545da7ab22472c5463db1b1c90251.mp3"}],"../assets/media/10b01c336ee5d00db87c0179556888bf72d8b76d6ab9913a27ed2e277576ff12.mp3":[{"id":"PPT_10b01c336ee5d00d","audioId":"PPT_10b01c336ee5d00d","title":"Book 2 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 48","duration":69.17,"cues":[{"start":0.0,"end":1.56,"text":"Unit six,","coverage":1.0},{"start":2.0,"end":3.24,"text":"six .one","coverage":1.0},{"start":4.78,"end":8.46,"text":"one 48 %","coverage":1.0},{"start":11.8,"end":14.86,"text":"two one half","coverage":1.0},{"start":16.9,"end":18.18,"text":"one half","coverage":1.0},{"start":20.6,"end":22.0,"text":"three","coverage":1.0},{"start":22.68,"end":23.86,"text":"one fifth","coverage":1.0},{"start":26.08,"end":27.36,"text":"one fifth","coverage":1.0},{"start":30.0,"end":31.26,"text":"four","coverage":1.0},{"start":31.96,"end":33.96,"text":"31 .five","coverage":1.0},{"start":36.74,"end":39.92,"text":"five 103","coverage":1.0},{"start":47.6,"end":49.0,"text":"six","coverage":1.0},{"start":55.84,"end":57.24,"text":"seven","coverage":1.0},{"start":63.46,"end":67.24,"text":"eight zero .01","coverage":1.0}],"file":"b10d98cc5ae3be75c819.js","track":0,"media":"../assets/media/10b01c336ee5d00db87c0179556888bf72d8b76d6ab9913a27ed2e277576ff12.mp3"}],"../assets/media/aa2336ec3808cdae8d48abbd5210b855f4fc6a45dbf20f23e558b0fc825980bf.mp3":[{"id":"B2_U07_T7.1_SHORT_S02_v01","audioId":"B2_U07_T7.1_SHORT_S02_v01","title":"Book 2 · Unit 7 · H2 · 听力材料 2","subtitle":"H2 · S02","duration":82.508821,"cues":[{"start":1.1,"end":4.84,"text":"Student presenter: Nowadays, we still see Jacobsen’s designs around us.","coverage":0.636},{"start":5.37,"end":10.67,"text":"When you look at the chair design, can you guess what Jacobsen was like as a person?","coverage":0.941},{"start":11.32,"end":14.64,"text":"Razia: His chair looks like a simple, neat design.","coverage":0.889},{"start":15.03,"end":19.61,"text":"So maybe he liked simple and neat things and not complicated things.","coverage":1.0},{"start":20.41,"end":21.72,"text":"Student presenter: Actually, that’s right.","coverage":0.667},{"start":22.0,"end":23.23,"text":"He did.","coverage":1.0},{"start":24.3,"end":33.0,"text":"For example, when he was growing up, he painted his room white because he didn’t like all the flowers on the wallpaper he had.","coverage":1.0},{"start":33.03,"end":37.58,"text":"And as an adult, he worked hard to make his designs perfect.","coverage":1.0},{"start":38.03,"end":44.62,"text":"In fact, he often kept his workers at work until late, trying to make things better.","coverage":1.0},{"start":45.03,"end":51.5,"text":"But even though he worked hard, Jacobsen liked to joke and do funny things.","coverage":0.929},{"start":52.3,"end":62.73,"text":"For instance, as a child he liked to play jokes on others and as an adult he once wore a melon for a hat when someone dared him to.","coverage":0.966},{"start":63.03,"end":70.03,"text":"He also liked working on his own projects in his free time and found painting to be relaxing.","coverage":1.0},{"start":71.41,"end":75.6,"text":"These days, Jacobsen is famous for his modern, simple designs.","coverage":0.9},{"start":76.03,"end":81.68,"text":"His work showed that he thought about the purpose that his designs would serve for people.","coverage":1.0}],"file":"b57b2ca0de040e59b130.js","track":1,"media":"../assets/media/aa2336ec3808cdae8d48abbd5210b855f4fc6a45dbf20f23e558b0fc825980bf.mp3"}],"../assets/media/2eee1c965bcffde997cb83b60effa72d9a31048495347a2f1c18e8f905e12dc2.mp3":[{"id":"B2_U07_T7.1_SHORT_S03_v01","audioId":"B2_U07_T7.1_SHORT_S03_v01","title":"Book 2 · Unit 7 · H2 · 听力材料 3","subtitle":"H2 · S03","duration":76.996984,"cues":[{"start":0.5,"end":5.11,"text":"Student presenter: Next, I’d like to talk about an inventor, James Dyson.","coverage":0.769},{"start":6.16,"end":12.42,"text":"Can anyone think of something you often use that might have his last name, Dyson, on it?","coverage":0.941},{"start":12.87,"end":15.25,"text":"Razia: I know, a vacuum cleaner!","coverage":0.833},{"start":15.51,"end":15.85,"text":"Ebru: Or a hand dryer?","coverage":0.4},{"start":17.1,"end":19.57,"text":"Student presenter: Both of those things are correct.","coverage":0.75},{"start":20.25,"end":24.62,"text":"Dyson’s designs and inventions are made to solve problems.","coverage":0.9},{"start":25.26,"end":31.92,"text":"His ideas come because he sees things that could work better, like the vacuum cleaner and hand dryer.","coverage":0.944},{"start":32.71,"end":34.96,"text":"But how did he start?","coverage":1.0},{"start":35.51,"end":40.19,"text":"Well, Dyson was born in England in 1947.","coverage":0.875},{"start":40.51,"end":43.95,"text":"His father died when he was only nine.","coverage":1.0},{"start":44.48,"end":49.43,"text":"As a result, Dyson ended up becoming someone who never gave up.","coverage":0.917},{"start":49.94,"end":53.91,"text":"He studied Art and Design before he studied Engineering.","coverage":1.0},{"start":54.26,"end":61.03,"text":"When he saw something that didn’t work well, he got frustrated and worked to improve it.","coverage":1.0},{"start":61.4,"end":67.06,"text":"For example, his first invention was a wheelbarrow with a ball for a wheel.","coverage":0.929},{"start":67.3,"end":73.02,"text":"This made it easier to carry heavy things in the garden and over rough ground.","coverage":1.0},{"start":73.35,"end":76.07,"text":"It was an interesting new use for a ball.","coverage":1.0}],"file":"b57b2ca0de040e59b130.js","track":2,"media":"../assets/media/2eee1c965bcffde997cb83b60effa72d9a31048495347a2f1c18e8f905e12dc2.mp3"}],"../assets/media/5b99c5be0ff02dc0b432d1e178b1da4d22bd997409f66e46ed4f21e3c5acf131.mp3":[{"id":"B2_U07_T7.1_SHORT_S04_v01","audioId":"B2_U07_T7.1_SHORT_S04_v01","title":"Book 2 · Unit 7 · H2 · 听力材料 4","subtitle":"H2 · S04","duration":58.032086,"cues":[{"start":0.4,"end":6.66,"text":"Student presenter: Also, even though he changed subjects, he was still interested in art as well as designing.","coverage":0.889},{"start":8.06,"end":9.41,"text":"Take a look at this photo.","coverage":1.0},{"start":9.71,"end":10.52,"text":"What do you see?","coverage":1.0},{"start":10.87,"end":17.2,"text":"Ebru: It looks like a waterfall made from glass and water, with the water running up instead of falling down.","coverage":0.95},{"start":17.55,"end":18.37,"text":"That’s surprising.","coverage":1.0},{"start":19.25,"end":19.68,"text":"Student presenter: That’s right.","coverage":0.6},{"start":20.69,"end":26.68,"text":"This was a piece of art that Dyson made in 2003, called Wrong Garden.","coverage":0.929},{"start":27.19,"end":28.79,"text":"It tricks the eye.","coverage":1.0},{"start":29.53,"end":34.38,"text":"This shows Dyson’s love of good design as well as being an inventor.","coverage":0.929},{"start":35.16,"end":37.14,"text":"Dyson is still inventing new things.","coverage":0.667},{"start":37.36,"end":48.63,"text":"But he is also interested in supporting education for students and gives money to schools to help students study so they might become inventors, too.","coverage":0.96},{"start":49.09,"end":57.56,"text":"He has even donated money to the University of Cambridge to support students and research there, with a focus on technology.","coverage":1.0}],"file":"b57b2ca0de040e59b130.js","track":3,"media":"../assets/media/5b99c5be0ff02dc0b432d1e178b1da4d22bd997409f66e46ed4f21e3c5acf131.mp3"}],"../assets/media/a2417acfbc5c06eb04b6fa622d101ae0cac93e42ba9032498bad6920648b787b.mp3":[{"id":"B2_U07_T7.1_SHORT_S05_v01","audioId":"B2_U07_T7.1_SHORT_S05_v01","title":"Book 2 · Unit 7 · H2 · 听力材料 5","subtitle":"H2 · S05","duration":52.356644,"cues":[{"start":0.34,"end":3.45,"text":"Student presenter: Now, I have one last picture to show you.","coverage":0.818},{"start":3.8,"end":6.82,"text":"It’s a phone with a special design.","coverage":1.0},{"start":7.48,"end":9.65,"text":"It’s called the iPhone.","coverage":1.0},{"start":10.0,"end":12.26,"text":"I think a lot of us know about this phone.","coverage":1.0},{"start":12.6,"end":16.07,"text":"It was designed by Sir Jonathan Ive for Apple.","coverage":0.889},{"start":16.8,"end":23.82,"text":"He is responsible for a lot of Apple’s product designs, which are simple, clean and slim.","coverage":1.0},{"start":24.55,"end":31.65,"text":"Ive has won a lot of awards for his Apple designs, and you can see a lot of his work in museums, too.","coverage":0.957},{"start":32.0,"end":40.26,"text":"He is from London, and he was made a Knight Commander of the British Empire in 2012 for his design work.","coverage":1.0},{"start":40.6,"end":43.88,"text":"He is known as being hard-working and creative.","coverage":1.0},{"start":44.2,"end":50.65,"text":"I think that his designs will continue to influence the way we live and work for a long time!","coverage":1.0}],"file":"b57b2ca0de040e59b130.js","track":4,"media":"../assets/media/a2417acfbc5c06eb04b6fa622d101ae0cac93e42ba9032498bad6920648b787b.mp3"}],"../assets/media/0da373d4cde023d0f3c19991183443788b58f9b1ee93691020bc1bfa067c9ceb.mp3":[{"id":"B3_U07_T7.7_SHORT_S03_v01","audioId":"B3_U07_T7.7_SHORT_S03_v01","title":"Book 3 · Unit 7 · H1 · 听力材料 11","subtitle":"H1 · 7.7-S03","duration":56.673719,"cues":[{"start":0.03,"end":0.66,"text":"Host: I see.","coverage":0.667},{"start":1.19,"end":5.22,"text":"So, do you know what ideas most people have about Muslim clothes?","coverage":1.0},{"start":6.02,"end":10.92,"text":"Aysha: Well, I think there’s a lot of misunderstanding about Muslim clothes.","coverage":0.923},{"start":11.44,"end":16.28,"text":"The thing is that when you say Muslim fashion, people in New York think of a burka.","coverage":0.941},{"start":17.08,"end":21.78,"text":"You know, like the blue or black cloaks which cover women from head to toe.","coverage":0.933},{"start":22.31,"end":25.49,"text":"Host: And could you explain what you think Muslim fashion is?","coverage":0.909},{"start":25.98,"end":27.32,"text":"Aysha: Let me give you an example.","coverage":0.857},{"start":27.54,"end":39.84,"text":"When I first started at design school, my teachers would ask me strange questions, such as how I was going to stay in the fashion business if I’m not going to design miniskirts or sleeveless shirts.","coverage":0.946},{"start":40.15,"end":45.45,"text":"But as far as I’m concerned, there is much more to fashion than showing your body.","coverage":1.0},{"start":46.06,"end":52.49,"text":"There are millions of Muslim women who live in the United States and Europe who want to wear fashionable clothes.","coverage":1.0},{"start":52.74,"end":56.16,"text":"There are also women who simply like to dress in a modest way.","coverage":1.0}],"file":"b5a7c01baf739bf6d821.js","track":10,"media":"../assets/media/0da373d4cde023d0f3c19991183443788b58f9b1ee93691020bc1bfa067c9ceb.mp3"}],"../assets/media/8ace1e13194f0009c939ff6937559cbd9eaeab6f9742ac50474092f7af7b3d64.mp3":[{"id":"PPT_8ace1e13194f0009","audioId":"PPT_8ace1e13194f0009","title":"Book 2 · Unit 7 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 89","duration":307.8,"cues":[{"start":0.0,"end":1.84,"text":"seven .two","coverage":1.0},{"start":8.06,"end":9.06,"text":"Hello","coverage":1.0},{"start":9.72,"end":10.01,"text":"Hi","coverage":1.0},{"start":10.01,"end":10.92,"text":"Yasmin,","coverage":1.0},{"start":11.5,"end":12.58,"text":"it's Louisa","coverage":1.0},{"start":12.58,"end":13.18,"text":"Hi","coverage":1.0},{"start":13.18,"end":13.98,"text":"Louisa,","coverage":1.0},{"start":14.3,"end":15.42,"text":"how are you?","coverage":1.0},{"start":16.06,"end":17.36,"text":"Okay, I guess","coverage":1.0},{"start":18.3,"end":19.12,"text":"Actually","coverage":1.0},{"start":20.0,"end":21.78,"text":"I'm not that great","coverage":1.0},{"start":21.78,"end":22.36,"text":"Oh","coverage":1.0},{"start":22.36,"end":22.72,"text":"no?","coverage":1.0},{"start":23.28,"end":24.24,"text":"What's up?","coverage":1.0},{"start":24.72,"end":25.56,"text":"Something wrong?","coverage":1.0},{"start":25.82,"end":28.48,"text":"It's the presentation for our course","coverage":1.0},{"start":29.04,"end":29.92,"text":"You know,","coverage":1.0},{"start":30.32,"end":35.7,"text":"the one on remarkable people who have done something really interesting or unusual","coverage":1.0},{"start":36.48,"end":40.88,"text":"I'm having trouble doing it Have you finished it yet?","coverage":1.0},{"start":41.62,"end":57.84,"text":"Yes, almost I just have to write a conclusion Good for you I bet it's really good Thanks, Louisa I'm pretty happy with it but the introduction's not great It needs a little more work","coverage":1.0},{"start":58.48,"end":60.08,"text":"How much have you done?","coverage":1.0},{"start":60.54,"end":60.98,"text":"Well","coverage":1.0},{"start":61.9,"end":65.16,"text":"I haven't done all of it All?","coverage":1.0},{"start":65.98,"end":67.16,"text":"Or any of it?","coverage":1.0},{"start":67.38,"end":70.92,"text":"I'm not very good at finding things to present","coverage":1.0},{"start":71.62,"end":74.34,"text":"I'm having trouble thinking of ideas","coverage":1.0},{"start":75.3,"end":77.26,"text":"Who did you do yours on?","coverage":1.0},{"start":77.76,"end":84.0,"text":"I chose Seema Najjar She's a remarkable woman Who's she?","coverage":1.0},{"start":84.8,"end":87.02,"text":"Why are you interested in her?","coverage":1.0},{"start":87.02,"end":88.32,"text":"Well,","coverage":1.0},{"start":88.78,"end":121.96,"text":"she's from Jordan She was working in fashion She used to be the head of a modelling company before and she worked with female Arab clothing designers So she has had a lot of success But she is famous because she started a website with videos in Arabic showing people how to do things And without even marketing the videos they started getting one million views a month How did she do that?","coverage":1.0},{"start":122.28,"end":122.8,"text":"Well,","coverage":1.0},{"start":123.2,"end":130.7,"text":"the videos are based on what people are searching for the most online They are often about fashion,","coverage":1.0},{"start":131.14,"end":131.58,"text":"food,","coverage":1.0},{"start":132.06,"end":132.48,"text":"health,","coverage":1.0},{"start":132.92,"end":163.02,"text":"parenting and art Many of the people who view her videos are Saudi Arabian women Another interesting thing is that she is a mother who is working full time Some of her videos help other mothers to have better health after they have their babies That's great that she has become really successful Is there anything else about her life or her company that's amazing?","coverage":1.0},{"start":163.42,"end":165.18,"text":"When her company started,","coverage":1.0},{"start":165.6,"end":175.24,"text":"most of the videos were made by people in their 20s Nowadays she has three full time workers making videos","coverage":1.0},{"start":175.98,"end":179.5,"text":"She says that as her company gets bigger,","coverage":1.0},{"start":180.04,"end":194.14,"text":"she wants to start hiring others to make videos too This will help more people get jobs That's important because a lot of young people in her area don't have enough work","coverage":1.0},{"start":194.94,"end":197.68,"text":"So she's an entrepreneur,","coverage":1.0},{"start":198.26,"end":203.4,"text":"a company leader and a working mother That's amazing","coverage":1.0},{"start":204.34,"end":213.26,"text":"Wow, I need to find someone like that Why don't you do something on Yoshiro Nakamatsu?","coverage":1.0},{"start":213.92,"end":215.58,"text":"Do you know about him?","coverage":1.0},{"start":215.58,"end":216.54,"text":"Um,","coverage":1.0},{"start":217.7,"end":222.72,"text":"I don't know a lot about Yoshiro...","coverage":1.0},{"start":222.72,"end":223.34,"text":"who?","coverage":1.0},{"start":224.42,"end":225.24,"text":"Nakamatsu","coverage":1.0},{"start":225.77,"end":228.0,"text":"Well, he was born in Japan","coverage":1.0},{"start":228.31,"end":235.34,"text":"He is now over 90 years old and he is still an inventor Um,","coverage":1.0},{"start":236.44,"end":239.64,"text":"his life doesn't sound that extraordinary","coverage":1.0},{"start":240.21,"end":262.26,"text":"He has created more than three ,000 inventions Including a chair that is supposed to help you think better Some of his inventions are a bit odd Like a pair of shoes made for jumping And glasses in the shape of eyes so that other people can't see them","coverage":1.0},{"start":262.78,"end":285.18,"text":"He even made fake hair that can help keep you safe from others I think Nakamatsu's situation is a little different from some inventors Because not everyone agrees that he has that many real inventions But he does have a lot Also,","coverage":1.0},{"start":285.62,"end":295.9,"text":"he didn't retire even after he reached the age of 80 You might want to look up more information about him online Okay,","coverage":1.0},{"start":296.82,"end":301.68,"text":"I'll check him out Do you know what the teacher wants us to present?","coverage":1.0},{"start":302.2,"end":302.6,"text":"Well,","coverage":1.0},{"start":303.36,"end":305.92,"text":"I'm not sure I understand everything","coverage":1.0}],"file":"b7a6482767a5f31c8068.js","track":0,"media":"../assets/media/8ace1e13194f0009c939ff6937559cbd9eaeab6f9742ac50474092f7af7b3d64.mp3"}],"../assets/media/d3135b5ab7a9d0399b3f2599dba8858621fe03b5b9fea8c1e0efa733a8b76f9b.mp3":[{"id":"B3_U04_T4.2_SHORT_S01_v01","audioId":"B3_U04_T4.2_SHORT_S01_v01","title":"Book 3 · Unit 4 · 课后听力材料","subtitle":"Homework listening material","duration":99.971678,"cues":[{"start":2.46,"end":4.53,"text":"Host: Welcome to this week’s book review.","coverage":0.875},{"start":5.28,"end":15.57,"text":"In the studio with me is Dr Kevin Lee, professor of Anthropology and author of the best-selling book Changing Traditions in the Modern World.","coverage":0.96},{"start":16.31,"end":21.89,"text":"First of all, could you tell us what anthropologists study and what your own area of interest is?","coverage":0.944},{"start":22.96,"end":23.97,"text":"Dr Lee: That’s a good question!","coverage":0.714},{"start":25.1,"end":28.69,"text":"Anthropology, in a general sense, is the study of humanity.","coverage":0.9},{"start":29.14,"end":30.71,"text":"I know that’s not very exact.","coverage":1.0},{"start":31.06,"end":38.11,"text":"That’s why we have many types of Anthropology, like Linguistic anthropology and Social anthropology.","coverage":1.0},{"start":39.56,"end":42.54,"text":"My speciality is Cultural anthropology.","coverage":0.8},{"start":42.87,"end":50.75,"text":"I study different cultures around the world and how social and political changes affect these cultures.","coverage":1.0},{"start":51.08,"end":55.19,"text":"Host: And when did you first become interested in Anthropology?","coverage":0.9},{"start":55.47,"end":57.91,"text":"Dr Lee: I grew up in a multicultural home.","coverage":0.778},{"start":58.18,"end":61.53,"text":"My mother is American and my father is Korean.","coverage":1.0},{"start":62.03,"end":66.44,"text":"They were both English teachers, so we travelled a lot.","coverage":1.0},{"start":66.73,"end":70.77,"text":"As a child, I lived in Japan, Thailand and Egypt.","coverage":1.0},{"start":71.05,"end":74.49,"text":"That’s why I decided to study Anthropology.","coverage":1.0},{"start":74.86,"end":82.36,"text":"Growing up in different cultures helps you realize that customs and traditions are often local.","coverage":0.933},{"start":82.68,"end":89.91,"text":"Things that are acceptable in one culture can be completely unacceptable in another.","coverage":1.0},{"start":90.2,"end":99.59,"text":"However, despite some differences between cultures, I have noticed that there are often more similarities than differences between people.","coverage":1.0}],"file":"b844ace32420d55a5b98.js","track":0,"media":"../assets/media/d3135b5ab7a9d0399b3f2599dba8858621fe03b5b9fea8c1e0efa733a8b76f9b.mp3"}],"../assets/media/93af01949e3ad24fa576dd8e26c317a356ab5550ba1ebba9790ad4689d231952.mp3":[{"id":"PPT_93af01949e3ad24f","audioId":"PPT_93af01949e3ad24f","title":"Book 3 · Unit 5 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 239","duration":16.09,"cues":[{"start":0.0,"end":1.7,"text":"five .three","coverage":1.0},{"start":1.7,"end":4.48,"text":"I'm really surprised about that.","coverage":1.0}],"file":"bb62f5a783a31729e347.js","track":0,"media":"../assets/media/93af01949e3ad24fa576dd8e26c317a356ab5550ba1ebba9790ad4689d231952.mp3"}],"../assets/media/78ce7aa0bfc645a53adb12ce95cceb66c80a58afd48df8ec3bb472662748bfbe.mp3":[{"id":"PPT_78ce7aa0bfc645a5","audioId":"PPT_78ce7aa0bfc645a5","title":"Book 3 · Unit 7 · RW · READING 1","subtitle":"READING 1 · source slide 41","duration":256.63,"cues":[{"start":0.0,"end":1.84,"text":"Thrifting goes global.","coverage":1.0},{"start":3.14,"end":5.14,"text":"In January 2023,","coverage":1.0},{"start":5.66,"end":11.76,"text":"19 -year -old Jacqueline Wells posted the results of her latest shopping trip on TikTok,","coverage":1.0},{"start":12.38,"end":15.3,"text":"where she has more than 400 ,000 followers.","coverage":1.0},{"start":16.3,"end":17.32,"text":"Two months later,","coverage":1.0},{"start":17.72,"end":24.42,"text":"more than six million people had viewed her post, and quite a few of them were very angry.","coverage":1.0},{"start":25.12,"end":29.38,"text":"Why were so many people interested in her shopping trip?","coverage":1.0},{"start":30.14,"end":33.04,"text":"And why were some of them upset about it?","coverage":1.0},{"start":33.8,"end":36.52,"text":"Wells is a thrifter and a reseller,","coverage":1.0},{"start":36.96,"end":39.24,"text":"and both have become controversial.","coverage":1.0},{"start":40.12,"end":44.22,"text":"Thrifting means shopping in stores that sell second hand,","coverage":1.0},{"start":44.68,"end":46.24,"text":"already used clothing,","coverage":1.0},{"start":46.56,"end":47.46,"text":"and other items.","coverage":1.0},{"start":48.28,"end":49.06,"text":"In general,","coverage":1.0},{"start":49.48,"end":51.56,"text":"this clothing is inexpensive.","coverage":1.0},{"start":52.66,"end":57.16,"text":"Resellers buy second hand clothes and then sell them online,","coverage":1.0},{"start":57.72,"end":60.88,"text":"on sites such as Depop and Poshmark,","coverage":1.0},{"start":61.58,"end":64.04,"text":"usually at a much higher price.","coverage":1.0},{"start":65.48,"end":69.32,"text":"Buying second hand clothing has not always been in fashion.","coverage":1.0},{"start":70.26,"end":74.26,"text":"Used clothing stores first appeared in the 19th century,","coverage":1.0},{"start":74.64,"end":76.78,"text":"and they were mostly for poor people.","coverage":1.0},{"start":77.64,"end":81.62,"text":"People who had to shop in these stores often felt ashamed.","coverage":1.0},{"start":82.8,"end":83.88,"text":"Recently, however,","coverage":1.0},{"start":84.42,"end":89.22,"text":"internet influencers like Wells have made thrifting very popular,","coverage":1.0},{"start":89.98,"end":92.76,"text":"and this trend is expected to continue.","coverage":1.0},{"start":93.76,"end":100.6,"text":"The global second hand clothing market is growing three times faster than the general clothing market.","coverage":1.0},{"start":101.26,"end":107.74,"text":"It is expected to reach $300 billion per year by 2026,","coverage":1.0},{"start":108.4,"end":111.72,"text":"and about half of those sales will be online.","coverage":1.0},{"start":112.9,"end":115.52,"text":"Today, many thrifters are not poor,","coverage":1.0},{"start":115.98,"end":118.86,"text":"and they don't need to buy second hand clothing.","coverage":1.0},{"start":119.6,"end":120.38,"text":"For them,","coverage":1.0},{"start":120.68,"end":122.0,"text":"thrifting is a hobby,","coverage":1.0},{"start":122.4,"end":124.38,"text":"and sometimes a business.","coverage":1.0},{"start":125.24,"end":131.14,"text":"They enjoy the challenge of finding unusual and attractive items at low prices.","coverage":1.0},{"start":132.14,"end":135.8,"text":"Then they share the results online with their followers,","coverage":1.0},{"start":136.4,"end":137.68,"text":"and like Wells,","coverage":1.0},{"start":138.02,"end":139.86,"text":"they often resell them.","coverage":1.0},{"start":140.82,"end":143.4,"text":"Some people are upset about this trend.","coverage":1.0},{"start":144.1,"end":152.04,"text":"They say that new thrifters are taking items away from people who don't have enough money to buy new clothes.","coverage":1.0},{"start":152.86,"end":153.6,"text":"In addition,","coverage":1.0},{"start":153.98,"end":158.72,"text":"the popularity of thrifting has led to higher prices for everyone.","coverage":1.0},{"start":159.82,"end":165.76,"text":"Although it is true that new thrifters often buy the most expensive brands of clothing,","coverage":1.0},{"start":166.48,"end":170.04,"text":"this probably makes very little difference in the market.","coverage":1.0},{"start":170.96,"end":179.58,"text":"The volume of second hand clothing is so high that only about 20 % is sold online or in shops.","coverage":1.0},{"start":180.46,"end":184.86,"text":"The rest is shipped to developing countries or thrown away.","coverage":1.0},{"start":185.88,"end":190.66,"text":"Many consumers also choose second hand clothes instead of new,","coverage":1.0},{"start":191.18,"end":194.66,"text":"because they believe it is a more sustainable option.","coverage":1.0},{"start":195.56,"end":202.5,"text":"Giving old clothes a second life saves resources compared to manufacturing new clothes.","coverage":1.0},{"start":203.34,"end":206.78,"text":"Thrifting can be a good sustainability strategy.","coverage":1.0},{"start":207.36,"end":207.92,"text":"However,","coverage":1.0},{"start":208.26,"end":208.64,"text":"it is","coverage":1.0},{"start":208.64,"end":208.9,"text":"no","coverage":1.0},{"start":208.9,"end":213.0,"text":"longer a good strategy when it becomes a reason to waste.","coverage":1.0},{"start":213.72,"end":219.22,"text":"A shopper may hesitate before spending $200 on a new jacket,","coverage":1.0},{"start":219.7,"end":225.68,"text":"but it's much easier to buy five second hand jackets at the same price.","coverage":1.0},{"start":226.56,"end":227.5,"text":"As a result,","coverage":1.0},{"start":228.06,"end":232.06,"text":"thrifting may encourage people to buy much more than they need,","coverage":1.0},{"start":232.72,"end":235.5,"text":"especially if they think they are helping the planet.","coverage":1.0},{"start":236.62,"end":243.94,"text":"Both economic and sustainability experts say the best strategy is to buy only what you need,","coverage":1.0},{"start":244.4,"end":246.18,"text":"new or second hand.","coverage":1.0},{"start":247.06,"end":248.18,"text":"Before you go shopping,","coverage":1.0},{"start":248.6,"end":250.36,"text":"first look in your wardrobe.","coverage":1.0},{"start":251.04,"end":254.7,"text":"The best option is to wear what you already own.","coverage":1.0}],"file":"bbd99555f6d846300379.js","track":0,"media":"../assets/media/78ce7aa0bfc645a53adb12ce95cceb66c80a58afd48df8ec3bb472662748bfbe.mp3"}],"../assets/media/36fd4510a427a250c47f5604411c688caa974f579de5d74812d6c14ad40a10ee.wav":[{"id":"B2_U04_T4.4_LONG_L02_v01","audioId":"B2_U04_T4.4_LONG_L02_v01","title":"Book 2 · Unit 4 · 课后听力材料","subtitle":"Homework listening material","duration":93.39149659863945,"cues":[{"start":0,"end":3.95,"text":"This is where the purple frog becomes important.","coverage":1.0},{"start":5.06,"end":9.16,"text":"A report tells us that the frog is in danger of disappearing forever.","coverage":1.0},{"start":10.38,"end":19.81,"text":"The frog can run very fast, makes a noise like a small chicken and is one of the most unusual animals in the world.","coverage":1.0},{"start":20.24,"end":26.35,"text":"Of course, for some people, the end of one type of frog is not important.","coverage":1.0},{"start":27.25,"end":35.62,"text":"But it is for Sathyabhama Das Biju, a researcher from Delhi University who discovered it in 2003.","coverage":0.824},{"start":35.82,"end":42.51,"text":"For him, the problems of the purple frog show what global warming is doing to the Indian rainforests.","coverage":0.944},{"start":44.46,"end":52.24,"text":"He explains that this interesting animal won’t be around much longer if we don’t look after the forests.","coverage":1.0},{"start":53.28,"end":57.75,"text":"Biju is going to present information about the forests next week.","coverage":0.909},{"start":58.1,"end":63.73,"text":"He hopes to get people interested in saving this frog and other animals that live in rainforests.","coverage":0.941},{"start":66.32,"end":71.86,"text":"During the next week, many people are meeting to talk about the climate and saving the rainforests.","coverage":0.941},{"start":74.04,"end":80.96,"text":"According to Biju, we need to plan now or we will probably lose some species completely.","coverage":0.938},{"start":81.3,"end":89.45,"text":"If we don’t think carefully about the climate of the forests, the purple frog possibly won’t be around for much longer.","coverage":1.0},{"start":90.35,"end":91.49,"text":"On to the weather report now …","coverage":0.667}],"file":"bc2ed3f72b505c3cb7b1.js","track":0,"media":"../assets/media/36fd4510a427a250c47f5604411c688caa974f579de5d74812d6c14ad40a10ee.wav"}],"../assets/media/868d5ca24bd0165d34b0b00151b07d603ddb24e5772fd02ac56395255f978e56.mp3":[{"id":"PPT_868d5ca24bd0165d","audioId":"PPT_868d5ca24bd0165d","title":"Book 2 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 36","duration":53.94,"cues":[{"start":0.0,"end":2.0,"text":"eight .two","coverage":1.0},{"start":3.74,"end":4.56,"text":"one.","coverage":1.0},{"start":4.56,"end":8.08,"text":"When the sun is out, we can't see the stars.","coverage":1.0},{"start":10.02,"end":10.84,"text":"two.","coverage":1.0},{"start":11.78,"end":16.52,"text":"Another name for Mars is the red planet because of its colour.","coverage":1.0},{"start":18.48,"end":19.3,"text":"three.","coverage":1.0},{"start":20.3,"end":21.98,"text":"Whether or not we like it,","coverage":1.0},{"start":22.38,"end":25.72,"text":"governments spend lots of money on space exploration.","coverage":1.0},{"start":27.7,"end":28.4,"text":"four.","coverage":1.0},{"start":29.54,"end":35.22,"text":"People who first travelled in space ate dried food that they added water to.","coverage":1.0},{"start":37.16,"end":37.86,"text":"five.","coverage":1.0},{"start":38.76,"end":43.08,"text":"When there are many bright lights at night, it's hard to see the stars.","coverage":1.0},{"start":45.28,"end":45.98,"text":"six.","coverage":1.0},{"start":46.96,"end":51.98,"text":"It takes more than an hour for light from the sun to reach the planet Saturn.","coverage":1.0}],"file":"bc7093eab0a06a3c9e54.js","track":0,"media":"../assets/media/868d5ca24bd0165d34b0b00151b07d603ddb24e5772fd02ac56395255f978e56.mp3"}],"../assets/media/794f23af8c052c3c25b881a9068d4d602ab67d68dabdcd866f29b77ae38110cb.mp3":[{"id":"PPT_794f23af8c052c3c","audioId":"PPT_794f23af8c052c3c","title":"Book 3 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 58","duration":47.36,"cues":[{"start":0.0,"end":1.8,"text":"six .two","coverage":1.0},{"start":2.84,"end":7.3,"text":"one Inventions and technology from India,","coverage":1.0},{"start":7.72,"end":8.22,"text":"China,","coverage":1.0},{"start":8.88,"end":13.04,"text":"North Africa and the Middle East were brought to Europe.","coverage":1.0},{"start":15.1,"end":16.1,"text":"two","coverage":1.0},{"start":16.92,"end":23.08,"text":"The first glasses were held in front of the eyes or balanced on the nose.","coverage":1.0},{"start":25.42,"end":26.42,"text":"three","coverage":1.0},{"start":27.38,"end":34.66,"text":"The crankshaft is a long arm which allows machines to move in a straight line.","coverage":1.0},{"start":36.98,"end":37.52,"text":"four","coverage":1.0},{"start":38.54,"end":40.04,"text":"As we move along,","coverage":1.0},{"start":40.42,"end":45.4,"text":"you'll find one of the most important inventions of medieval times.","coverage":1.0}],"file":"bdff2ed6f667e54b9584.js","track":0,"media":"../assets/media/794f23af8c052c3c25b881a9068d4d602ab67d68dabdcd866f29b77ae38110cb.mp3"}],"../assets/media/fc7a0b7e619332e88744250f9a73a6b266cc67564a77637d0d649bedc591046f.mp3":[{"id":"PPT_fc7a0b7e619332e8","audioId":"PPT_fc7a0b7e619332e8","title":"Book 3 · Unit 5 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 242","duration":42.32,"cues":[{"start":0.0,"end":2.22,"text":"five .four","coverage":1.0},{"start":3.3,"end":6.76,"text":"one I'm really happy about this new research.","coverage":1.0},{"start":9.1,"end":10.02,"text":"two","coverage":1.0},{"start":10.76,"end":11.48,"text":"There's","coverage":1.0},{"start":11.48,"end":11.8,"text":"no","coverage":1.0},{"start":11.8,"end":14.26,"text":"question that happy people live longer.","coverage":1.0},{"start":16.74,"end":17.54,"text":"three","coverage":1.0},{"start":18.4,"end":23.64,"text":"It's ridiculous to get too worried about healthy eating and exercise.","coverage":1.0},{"start":25.94,"end":26.86,"text":"four","coverage":1.0},{"start":28.2,"end":31.42,"text":"He certainly never went to a gym.","coverage":1.0},{"start":34.44,"end":34.46,"text":"five","coverage":1.0},{"start":35.44,"end":36.08,"text":"There's","coverage":1.0},{"start":36.08,"end":36.38,"text":"no","coverage":1.0},{"start":36.38,"end":40.36,"text":"doubt that bad health habits increase the chances of getting a serious illness.","coverage":1.0}],"file":"be8a3fa3bfc3bb9fa32b.js","track":0,"media":"../assets/media/fc7a0b7e619332e88744250f9a73a6b266cc67564a77637d0d649bedc591046f.mp3"}],"../assets/media/733412a4e1bac5e430136f74bf1cf57e9bfce39ed9af39b6666cada848567f0e.mp3":[{"id":"PPT_733412a4e1bac5e4","audioId":"PPT_733412a4e1bac5e4","title":"Book 2 · Unit 1 · RW · READING 2","subtitle":"READING 2 · source slide 81","duration":182.52,"cues":[{"start":0.0,"end":1.86,"text":"Home stay holidays,","coverage":1.0},{"start":2.3,"end":4.28,"text":"a home away from home.","coverage":1.0},{"start":5.2,"end":7.26,"text":"Places to stay.","coverage":1.0},{"start":8.12,"end":8.9,"text":"Location.","coverage":1.0},{"start":9.32,"end":10.32,"text":"Check -in.","coverage":1.0},{"start":10.72,"end":11.42,"text":"Checkout.","coverage":1.0},{"start":12.52,"end":13.3,"text":"Guests.","coverage":1.0},{"start":14.02,"end":16.92,"text":"Home stays are becoming more and more popular,","coverage":1.0},{"start":17.56,"end":22.22,"text":"and people around the world are offering their homes as places to stay.","coverage":1.0},{"start":23.32,"end":30.12,"text":"Home stays offer cheap places to stay and the chance for guests to see the area like local people.","coverage":1.0},{"start":30.92,"end":36.1,"text":"They're very popular with students who want to stay in another country and learn a language.","coverage":1.0},{"start":37.06,"end":42.04,"text":"We asked three families who run home stays to tell us about where they live.","coverage":1.0},{"start":44.26,"end":45.64,"text":"Stay in the mountains.","coverage":1.0},{"start":46.56,"end":47.68,"text":"The Atal family.","coverage":1.0},{"start":48.76,"end":55.78,"text":"Our family home is in the north of Nepal, in the Himalayan mountains, in the village of Manang.","coverage":1.0},{"start":56.52,"end":59.38,"text":"The village is small and very quiet.","coverage":1.0},{"start":59.82,"end":61.92,"text":"It is a very friendly place.","coverage":1.0},{"start":62.72,"end":65.22,"text":"The mountains are extremely beautiful.","coverage":1.0},{"start":65.9,"end":70.88,"text":"You can go for long walks and swim in the rivers, but there are","coverage":1.0},{"start":70.88,"end":71.28,"text":"no","coverage":1.0},{"start":71.28,"end":71.82,"text":"shops,","coverage":1.0},{"start":72.3,"end":73.84,"text":"cinemas or cafes.","coverage":1.0},{"start":75.22,"end":77.64,"text":"A house by the sea.","coverage":1.0},{"start":78.24,"end":79.94,"text":"Kate and Julian Foxton.","coverage":1.0},{"start":81.2,"end":86.02,"text":"Our two -bedroom house is by the sea in the southwest of England.","coverage":1.0},{"start":86.6,"end":91.48,"text":"It is 15 minutes drive to the nearest village of Port Reith.","coverage":1.0},{"start":92.28,"end":97.74,"text":"There are lots of beaches, rivers and forests and it is very quiet.","coverage":1.0},{"start":98.22,"end":104.28,"text":"We spend a lot of time reading books, watching films and going for walks.","coverage":1.0},{"start":104.94,"end":108.64,"text":"Our area is great for sports like surfing,","coverage":1.0},{"start":109.0,"end":110.88,"text":"kayaking and mountain biking.","coverage":1.0},{"start":111.52,"end":112.12,"text":"However,","coverage":1.0},{"start":112.48,"end":115.0,"text":"the houses here are expensive,","coverage":1.0},{"start":115.32,"end":118.26,"text":"which can be a problem for local people.","coverage":1.0},{"start":118.78,"end":119.36,"text":"There are","coverage":1.0},{"start":119.36,"end":119.82,"text":"no","coverage":1.0},{"start":119.82,"end":126.14,"text":"buses or trains here, so it can be difficult to get around without a car.","coverage":1.0},{"start":128.02,"end":129.62,"text":"City Holiday.","coverage":1.0},{"start":130.28,"end":132.18,"text":"Shafik and Asma Halwani.","coverage":1.0},{"start":133.26,"end":138.52,"text":"Our home is near the historic city center of Beirut, Lebanon,","coverage":1.0},{"start":139.14,"end":141.28,"text":"a large city in the Middle East.","coverage":1.0},{"start":141.98,"end":144.64,"text":"There are lots of cafes and restaurants,","coverage":1.0},{"start":145.04,"end":146.92,"text":"which are open late at night.","coverage":1.0},{"start":147.56,"end":153.78,"text":"We love it here because it's so friendly and you can always find what you need.","coverage":1.0},{"start":154.56,"end":158.32,"text":"Lots of people come here to learn Arabic and French.","coverage":1.0},{"start":159.2,"end":162.76,"text":"There are also a lot of jobs and businesses here.","coverage":1.0},{"start":163.5,"end":164.06,"text":"However,","coverage":1.0},{"start":164.44,"end":170.3,"text":"it can be noisy at night and there is a lot of traffic during the day.","coverage":1.0},{"start":171.14,"end":173.94,"text":"The best thing about Beirut is the weather.","coverage":1.0},{"start":174.5,"end":176.66,"text":"It is nice all year round.","coverage":1.0},{"start":177.2,"end":178.62,"text":"It rains in the winter,","coverage":1.0},{"start":179.04,"end":179.82,"text":"but there is","coverage":1.0},{"start":179.82,"end":180.12,"text":"no","coverage":1.0},{"start":180.12,"end":180.58,"text":"snow.","coverage":1.0}],"file":"bea913810b2ee7f065ec.js","track":0,"media":"../assets/media/733412a4e1bac5e430136f74bf1cf57e9bfce39ed9af39b6666cada848567f0e.mp3"}],"../assets/media/af681c1edf1e4b787caa9b8c17c6f4373076892dc63796f17b1b6a0df8e2cfe9.mp3":[{"id":"B3_U04_T4.2_SHORT_S02_v01","audioId":"B3_U04_T4.2_SHORT_S02_v01","title":"Book 3 · Unit 4 · 课后听力材料","subtitle":"Homework listening material","duration":63.099841,"cues":[{"start":0.31,"end":1.95,"text":"Host: And do traditions change?","coverage":0.8},{"start":2.49,"end":3.24,"text":"Dr Lee: Absolutely!","coverage":0.333},{"start":3.69,"end":6.61,"text":"Customs and traditions change all the time.","coverage":1.0},{"start":7.67,"end":13.81,"text":"Some traditions die out because our way of life changes, but most traditions adapt.","coverage":1.0},{"start":14.16,"end":18.66,"text":"Host: As I understand it, that’s one of the main points of your latest book.","coverage":0.938},{"start":18.96,"end":19.04,"text":"Dr Lee: Yes.","coverage":0.333},{"start":19.14,"end":25.27,"text":"My book is about the effect of modern technology on traditions around the world.","coverage":1.0},{"start":25.64,"end":34.85,"text":"It’s well known that things such as electricity, the telephone and television have changed our lives significantly.","coverage":1.0},{"start":35.45,"end":41.66,"text":"The introduction of these inventions into our lives has changed many of our customs.","coverage":1.0},{"start":42.28,"end":50.32,"text":"For example, in the past, families spent time playing board games or listening to the radio in the evening.","coverage":1.0},{"start":50.95,"end":54.44,"text":"These activities would deepen family relationships.","coverage":1.0},{"start":54.99,"end":62.58,"text":"Now, due to developments in technology, people spend more time interacting with other people over the internet.","coverage":1.0}],"file":"beddfe909071c4e46962.js","track":0,"media":"../assets/media/af681c1edf1e4b787caa9b8c17c6f4373076892dc63796f17b1b6a0df8e2cfe9.mp3"}],"../assets/media/eb5a0bc4476d3290d8ec1040431aff895a1e883d9580d72805a58a55a3477658.wav":[{"id":"B3_U01_T1.1_LONG_L01_v01","audioId":"B3_U01_T1.1_LONG_L01_v01","title":"Book 3 · Unit 1 · 课后听力材料","subtitle":"Homework listening material","duration":113.04596371882086,"cues":[{"start":0.09,"end":2.78,"text":"Ms Johnson, would you like to begin?","coverage":1.0},{"start":4.04,"end":6.35,"text":"Ms Johnson: Thank you for inviting me to this debate.","coverage":0.8},{"start":6.64,"end":12.58,"text":"It’s well known that animals have worked side by side with humans for thousands of years.","coverage":1.0},{"start":12.88,"end":18.29,"text":"In fact, they helped us develop our civilization and helped humans survive.","coverage":1.0},{"start":19.04,"end":25.05,"text":"Animals, like elephants and horses, were used to build amazing structures, like the pyramids in Egypt.","coverage":0.938},{"start":26.24,"end":30.95,"text":"Yet their hard work and suffering are hardly ever recognized.","coverage":1.0},{"start":31.92,"end":41.96,"text":"For example, horses, camels and elephants were used to transport armies and soldiers during wars and many of these animals died in these wars.","coverage":0.958},{"start":43.52,"end":45.2,"text":"And there are other examples.","coverage":1.0},{"start":46.01,"end":52.72,"text":"Even now, dogs are used to pull sleds in cold climates and elephants are used for logging.","coverage":0.941},{"start":53.44,"end":57.17,"text":"These animals work long hours and live in difficult conditions.","coverage":1.0},{"start":58.28,"end":61.04,"text":"However, they get very little reward.","coverage":1.0},{"start":61.88,"end":64.21,"text":"Humans just use them to their advantage.","coverage":1.0},{"start":64.88,"end":72.19,"text":"My main argument is that in the modern world, there is no longer any need to use animals for work.","coverage":1.0},{"start":72.56,"end":75.32,"text":"We have technology that can replace them.","coverage":1.0},{"start":75.64,"end":79.64,"text":"It’s similar to using children to work in factories.","coverage":1.0},{"start":80.79,"end":84.73,"text":"Two hundred years ago, factory owners got rich by using children.","coverage":0.818},{"start":85.83,"end":90.44,"text":"Nowadays, people still get rich by using animals to do work for them.","coverage":0.923},{"start":90.8,"end":95.97,"text":"The problem is that the animals have no one to represent them and protect their rights.","coverage":1.0},{"start":96.56,"end":102.73,"text":"Even though animals work hard for us, they are often abandoned when they get sick or too old to work.","coverage":1.0},{"start":103.72,"end":104.5,"text":"They suffer.","coverage":1.0},{"start":104.92,"end":112.21,"text":"In short, I strongly believe that using animals for work is an old-fashioned and cruel practice.","coverage":1.0}],"file":"c061ef154f27485c39e6.js","track":0,"media":"../assets/media/eb5a0bc4476d3290d8ec1040431aff895a1e883d9580d72805a58a55a3477658.wav"}],"../assets/media/2437fdee63bf7e2a3b8b6ddb0a404f5bb896afbb7988ad65f475696609eaff66.mp3":[{"id":"PPT_2437fdee63bf7e2a","audioId":"PPT_2437fdee63bf7e2a","title":"Book 3 · Unit 5 · RW · READING 2","subtitle":"READING 2 · source slide 117","duration":243.75,"cues":[{"start":0.0,"end":3.8,"text":"World Health Organization Warns About the Increase in Obesity","coverage":1.0},{"start":5.38,"end":9.02,"text":"Obesity has become a major problem in many parts of the world.","coverage":1.0},{"start":9.94,"end":11.88,"text":"According to the World Health Organization,","coverage":1.0},{"start":12.46,"end":13.28,"text":"in 2016,","coverage":1.0},{"start":13.72,"end":15.2,"text":"about 13 % of adults,","coverage":1.0},{"start":15.54,"end":17.8,"text":"both male and female, were obese.","coverage":1.0},{"start":18.48,"end":19.0,"text":"Moreover,","coverage":1.0},{"start":19.46,"end":25.78,"text":"the percentage of obese people increased by 300 % between 1975 and 2016.","coverage":1.0},{"start":26.58,"end":30.2,"text":"Obesity can cause major health problems like heart disease,","coverage":1.0},{"start":30.72,"end":30.98,"text":"diabetes,","coverage":1.0},{"start":31.48,"end":31.8,"text":"stroke,","coverage":1.0},{"start":32.26,"end":33.44,"text":"and breathing problems.","coverage":1.0},{"start":34.08,"end":36.4,"text":"Tackling obesity is a big task.","coverage":1.0},{"start":37.06,"end":38.9,"text":"Whose responsibility should it be?","coverage":1.0},{"start":39.56,"end":43.44,"text":"Although some people say it is up to individuals to manage their own weight,","coverage":1.0},{"start":44.18,"end":50.16,"text":"others believe governments should take the lead by making laws designed to help reduce the obesity problem.","coverage":1.0},{"start":51.08,"end":52.46,"text":"On the one hand,","coverage":1.0},{"start":52.9,"end":59.48,"text":"many people insist that individuals are the ones who need to take the major responsibility for controlling their own weight.","coverage":1.0},{"start":60.18,"end":63.32,"text":"Supporters of this position have explained how we can do this.","coverage":1.0},{"start":63.84,"end":64.28,"text":"First,","coverage":1.0},{"start":64.7,"end":67.22,"text":"we can control the size of the portions we eat.","coverage":1.0},{"start":67.8,"end":71.7,"text":"An average man needs around two ,500 calories per day,","coverage":1.0},{"start":72.12,"end":75.22,"text":"while an average woman requires around two ,000.","coverage":1.0},{"start":75.98,"end":83.34,"text":"Moreover, we should learn how to eat a balanced diet consisting of a variety of foods in order to maintain a healthy weight.","coverage":1.0},{"start":84.04,"end":86.04,"text":"In many Western countries, for example,","coverage":1.0},{"start":86.5,"end":91.02,"text":"a typical healthy diet might include approximately 50 % fruit and vegetables,","coverage":1.0},{"start":91.54,"end":93.04,"text":"30 % carbohydrates,","coverage":1.0},{"start":93.42,"end":96.06,"text":"such as bread, rice, potatoes, and pasta,","coverage":1.0},{"start":96.68,"end":106.7,"text":"15 % proteins, for example, meat, fish, eggs, and beans, and around five % dairy products, for example, milk and cheese.","coverage":1.0},{"start":107.48,"end":107.94,"text":"Next,","coverage":1.0},{"start":108.26,"end":111.96,"text":"we all need to read the nutritional information on food packaging.","coverage":1.0},{"start":112.7,"end":116.6,"text":"This would help us to control our intake of unhealthy ingredients,","coverage":1.0},{"start":116.98,"end":118.9,"text":"like sugar and saturated fats,","coverage":1.0},{"start":119.22,"end":121.06,"text":"and make intelligent food choices.","coverage":1.0},{"start":121.78,"end":122.54,"text":"And finally,","coverage":1.0},{"start":122.98,"end":126.7,"text":"each of us should make time to exercise because, as we all know,","coverage":1.0},{"start":127.22,"end":128.74,"text":"exercise burns calories.","coverage":1.0},{"start":129.58,"end":130.96,"text":"On the other hand,","coverage":1.0},{"start":131.42,"end":136.54,"text":"some people insist that individual efforts to control obesity often end in failure.","coverage":1.0},{"start":137.32,"end":140.7,"text":"They argue that governments should take the lead in fighting obesity.","coverage":1.0},{"start":141.38,"end":143.22,"text":"They propose a number of measures.","coverage":1.0},{"start":143.98,"end":144.36,"text":"First,","coverage":1.0},{"start":144.96,"end":150.26,"text":"many countries already have laws requiring nutritional information on packaged foods.","coverage":1.0},{"start":151.04,"end":155.88,"text":"Supporters of this law think large restaurant chains should also list calorie counts,","coverage":1.0},{"start":156.22,"end":157.78,"text":"as well as the amount of cholesterol,","coverage":1.0},{"start":158.16,"end":159.12,"text":"on their menus.","coverage":1.0},{"start":160.14,"end":166.44,"text":"This information can help customers choose low -calorie nutritious food even when they are not cooking at home.","coverage":1.0},{"start":167.36,"end":167.76,"text":"Next,","coverage":1.0},{"start":168.14,"end":172.36,"text":"many people support attacks on foods which are high in fat and sugar,","coverage":1.0},{"start":172.7,"end":173.62,"text":"such as pizza,","coverage":1.0},{"start":174.36,"end":176.28,"text":"crisps, chocolate, and sweets.","coverage":1.0},{"start":177.12,"end":182.82,"text":"Such attacks would make junk food too expensive for people to buy in large quantities.","coverage":1.0},{"start":184.02,"end":184.24,"text":"Finally,","coverage":1.0},{"start":184.72,"end":193.16,"text":"many people strongly believe that governments should support educational campaigns to encourage people to eat a low -calorie, balanced diet.","coverage":1.0},{"start":193.96,"end":201.4,"text":"Such campaigns would be similar to the anti -smoking campaigns that have helped reduce the number of smokers all over the world.","coverage":1.0},{"start":202.24,"end":203.36,"text":"In conclusion,","coverage":1.0},{"start":203.96,"end":211.18,"text":"there are strong arguments for governments and individuals taking increased responsibility for tackling the obesity crisis.","coverage":1.0},{"start":211.78,"end":212.7,"text":"In my opinion,","coverage":1.0},{"start":213.1,"end":217.1,"text":"both parties have a role to play in dealing with this global problem.","coverage":1.0},{"start":217.84,"end":223.44,"text":"Governments should pass new laws and provide education to encourage people to choose healthier lifestyles.","coverage":1.0},{"start":224.26,"end":225.7,"text":"At the same time,","coverage":1.0},{"start":226.26,"end":232.66,"text":"individuals have to take more responsibility for their meal choices and choose healthier foods and smaller portions.","coverage":1.0},{"start":233.54,"end":237.4,"text":"If we really wish to see an end to the problem of obesity in the future,","coverage":1.0},{"start":238.38,"end":241.86,"text":"individuals and governments must both take action.","coverage":1.0}],"file":"c1b48ea91bbd7ebe4007.js","track":0,"media":"../assets/media/2437fdee63bf7e2a3b8b6ddb0a404f5bb896afbb7988ad65f475696609eaff66.mp3"}],"../assets/media/408cdfa1e67955fb9c42a6a12498e9497e5ba1a7ed59cc230bec379eef2def04.mp3":[{"id":"PPT_408cdfa1e67955fb","audioId":"PPT_408cdfa1e67955fb","title":"Book 3 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 183","duration":37.85,"cues":[{"start":0.0,"end":1.32,"text":"one .eight.","coverage":1.0},{"start":1.88,"end":2.76,"text":"one.","coverage":1.0},{"start":3.88,"end":7.64,"text":"First of all, keeping animals in zoos helps protect them.","coverage":1.0},{"start":9.82,"end":10.7,"text":"two.","coverage":1.0},{"start":11.76,"end":12.58,"text":"For example,","coverage":1.0},{"start":13.1,"end":18.68,"text":"many species such as the giant panda and the snow leopard are endangered in the wild.","coverage":1.0},{"start":21.08,"end":21.96,"text":"three.","coverage":1.0},{"start":23.2,"end":27.42,"text":"Another point is that zoos have an important educational role.","coverage":1.0},{"start":29.56,"end":30.5,"text":"four.","coverage":1.0},{"start":32.08,"end":32.98,"text":"To summarise,","coverage":1.0},{"start":33.28,"end":36.04,"text":"zoos help protect animals and educate us.","coverage":1.0}],"file":"c2b2b9e89dfcbc798295.js","track":0,"media":"../assets/media/408cdfa1e67955fb9c42a6a12498e9497e5ba1a7ed59cc230bec379eef2def04.mp3"}],"../assets/media/ee5fd8cc38d8e476b202c7b228e21e5c3d9e843e3bf2dddce82cec04aa5ba32d.mp3":[{"id":"PPT_ee5fd8cc38d8e476","audioId":"PPT_ee5fd8cc38d8e476","title":"Book 3 · Unit 4 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 79","duration":74.03,"cues":[{"start":0.0,"end":1.58,"text":"four .six","coverage":1.0},{"start":1.58,"end":8.2,"text":"So our assignment is to discuss customs which have been changing recently.","coverage":1.0},{"start":8.74,"end":12.76,"text":"You know, how modern lifestyles have changed people's behaviour.","coverage":1.0},{"start":13.66,"end":14.5,"text":"Any ideas?","coverage":1.0},{"start":15.26,"end":15.76,"text":"Hmm,","coverage":1.0},{"start":16.1,"end":17.02,"text":"let me think.","coverage":1.0},{"start":18.76,"end":20.64,"text":"holidays are one kind of custom.","coverage":1.0},{"start":21.36,"end":24.16,"text":"Can you think of any holidays which have changed?","coverage":1.0},{"start":24.16,"end":26.28,"text":"Oh, don't talk about holidays.","coverage":1.0},{"start":26.8,"end":31.78,"text":"It reminds me that Mother's Day is in two days and I haven't bought a gift for my mum yet.","coverage":1.0},{"start":32.18,"end":32.66,"text":"Yeah,","coverage":1.0},{"start":32.98,"end":34.28,"text":"I haven't either.","coverage":1.0},{"start":34.86,"end":38.52,"text":"Who has time for shopping when we have so much work to do?","coverage":1.0},{"start":38.74,"end":39.46,"text":"I agree.","coverage":1.0},{"start":40.0,"end":42.18,"text":"I get tired of shopping for gifts.","coverage":1.0},{"start":42.46,"end":47.18,"text":"I actually don't know why we have to get gifts for every little holiday.","coverage":1.0},{"start":47.18,"end":52.0,"text":"Wouldn't our mothers be just as happy if we just spent time with them?","coverage":1.0},{"start":52.42,"end":54.54,"text":"You know, made it a special event,","coverage":1.0},{"start":54.84,"end":57.88,"text":"like taking them out to lunch at a nice restaurant.","coverage":1.0},{"start":58.56,"end":63.76,"text":"How did this whole gift -giving -for -every -holiday tradition get started anyway?","coverage":1.0},{"start":64.34,"end":65.9,"text":"It seems silly to me.","coverage":1.0},{"start":66.3,"end":67.2,"text":"That's it!","coverage":1.0},{"start":67.54,"end":68.86,"text":"There's our topic,","coverage":1.0},{"start":69.4,"end":72.06,"text":"how holidays have become too commercial.","coverage":1.0}],"file":"c2c5a1a019d42c1dc4ae.js","track":0,"media":"../assets/media/ee5fd8cc38d8e476b202c7b228e21e5c3d9e843e3bf2dddce82cec04aa5ba32d.mp3"}],"../assets/media/209560db93648036e8e5392a33a2ef5986d9a5e23deef31f35f3779085d29541.mp3":[{"id":"PPT_209560db93648036","audioId":"PPT_209560db93648036","title":"Book 2 · Unit 3 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 177","duration":64.47,"cues":[{"start":0.0,"end":2.3,"text":"three .six","coverage":1.0},{"start":4.32,"end":5.0,"text":"one.","coverage":1.0},{"start":5.4,"end":8.5,"text":"When people were asked difficult questions in the past,","coverage":1.0},{"start":9.3,"end":12.68,"text":"scientists believe they tried to think of the answer to the question.","coverage":1.0},{"start":13.4,"end":13.8,"text":"However,","coverage":1.0},{"start":14.3,"end":15.92,"text":"because of modern technology,","coverage":1.0},{"start":16.56,"end":20.32,"text":"the first thing people think about now is how to find the answer.","coverage":1.0},{"start":22.3,"end":22.98,"text":"two.","coverage":1.0},{"start":23.84,"end":24.68,"text":"For example,","coverage":1.0},{"start":25.12,"end":31.46,"text":"they think about what they might put into Google, but in the past they thought about the question itself.","coverage":1.0},{"start":33.92,"end":34.46,"text":"three.","coverage":1.0},{"start":35.54,"end":37.96,"text":"It seems that people now forget facts,","coverage":1.0},{"start":38.52,"end":42.32,"text":"especially if they know the information will be saved in a file.","coverage":1.0},{"start":42.76,"end":44.28,"text":"On the other hand,","coverage":1.0},{"start":44.76,"end":48.06,"text":"an advantage is they remember the location of the fact.","coverage":1.0},{"start":48.58,"end":49.6,"text":"In other words,","coverage":1.0},{"start":50.04,"end":51.72,"text":"where to find it.","coverage":1.0},{"start":53.18,"end":53.86,"text":"four.","coverage":1.0},{"start":54.88,"end":59.46,"text":"In conclusion, it seems that computers are not making us stupid,","coverage":1.0},{"start":60.24,"end":62.5,"text":"but they are making us lazy.","coverage":1.0}],"file":"c2ca4aab6e21b5cb6deb.js","track":0,"media":"../assets/media/209560db93648036e8e5392a33a2ef5986d9a5e23deef31f35f3779085d29541.mp3"}],"../assets/media/0387157f77ff515c0e23ffeb38010c49dc878b8a5ca1788df852ff5d80b629d9.mp3":[{"id":"PPT_0387157f77ff515c","audioId":"PPT_0387157f77ff515c","title":"Book 2 · Unit 4 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 101","duration":182.44,"cues":[{"start":0.0,"end":2.0,"text":"four .four","coverage":1.0},{"start":3.02,"end":7.94,"text":"Global warming is an important issue around the world.","coverage":1.0},{"start":8.82,"end":14.1,"text":"Recently it has created problems in the western Gatts rainforests of India.","coverage":1.0},{"start":14.94,"end":21.54,"text":"Forests are important for slowing down global warming because of the work that trees do for us.","coverage":1.0},{"start":22.1,"end":24.37,"text":"Trees are global cleaners.","coverage":1.0},{"start":24.37,"end":27.19,"text":"They take in carbon dioxide,","coverage":1.0},{"start":27.59,"end":28.37,"text":"CO2,","coverage":1.0},{"start":28.75,"end":30.69,"text":"the gas that heats the atmosphere.","coverage":1.0},{"start":31.43,"end":36.85,"text":"So we keep making global warming worse every time we cut down trees.","coverage":1.0},{"start":37.67,"end":41.61,"text":"Then global warming continues to damage the forest.","coverage":1.0},{"start":42.27,"end":48.85,"text":"More trees disappear because the changes in temperature stop the normal growth of the forest.","coverage":1.0},{"start":50.09,"end":55.85,"text":"Nowadays rainforests get less rain and this is changing the way they work.","coverage":1.0},{"start":56.81,"end":60.23,"text":"Governments around the world are beginning to work on the problem.","coverage":1.0},{"start":61.09,"end":65.09,"text":"Although governments say they will stop people damaging the forests,","coverage":1.0},{"start":65.83,"end":69.15,"text":"scientists don't think the work is happening quickly enough.","coverage":1.0},{"start":70.19,"end":73.13,"text":"The scientists say the forests are changing.","coverage":1.0},{"start":74.05,"end":78.27,"text":"The animals and the plants that animals need are changing.","coverage":1.0},{"start":78.27,"end":79.47,"text":"In fact,","coverage":1.0},{"start":80.07,"end":88.63,"text":"scientists believe 45 % of the forest areas are going to change completely in the next 80 years.","coverage":1.0},{"start":89.67,"end":93.13,"text":"This is where the purple frog becomes important.","coverage":1.0},{"start":94.07,"end":98.59,"text":"A report tells us that the frog is in danger of disappearing forever.","coverage":1.0},{"start":99.33,"end":101.69,"text":"The frog can run very fast,","coverage":1.0},{"start":102.19,"end":108.35,"text":"makes a noise like a small chicken, and is one of the most unusual animals in the world.","coverage":1.0},{"start":109.27,"end":109.81,"text":"Of course,","coverage":1.0},{"start":110.25,"end":115.11,"text":"for some people the end of one type of frog is not important.","coverage":1.0},{"start":115.39,"end":118.41,"text":"But it is for Satyabhama Das Bijou,","coverage":1.0},{"start":118.79,"end":121.07,"text":"a researcher from Delhi University,","coverage":1.0},{"start":121.57,"end":124.29,"text":"who discovered it in 2003.","coverage":1.0},{"start":125.01,"end":125.71,"text":"For him,","coverage":1.0},{"start":126.25,"end":133.03,"text":"the problems of the purple frog show what global warming is doing to the Indian rainforests.","coverage":1.0},{"start":133.03,"end":140.87,"text":"He explains that this interesting animal won't be around much longer if we don't look after the forests.","coverage":1.0},{"start":141.93,"end":146.45,"text":"Bijou is going to present information about the forests next week.","coverage":1.0},{"start":147.03,"end":154.03,"text":"He hopes to get people interested in saving this frog and other animals that live in rainforests.","coverage":1.0},{"start":154.73,"end":155.89,"text":"During the next week,","coverage":1.0},{"start":156.41,"end":162.31,"text":"many people are meeting to talk about the climate and saving the rainforests.","coverage":1.0},{"start":162.31,"end":163.95,"text":"According to Bijou,","coverage":1.0},{"start":164.25,"end":169.25,"text":"we need to plan now, or we will probably lose some species completely.","coverage":1.0},{"start":170.29,"end":173.89,"text":"If we don't think carefully about the climate of the forests,","coverage":1.0},{"start":174.49,"end":177.87,"text":"the purple frog possibly won't be around for much longer.","coverage":1.0},{"start":178.83,"end":180.61,"text":"On to the weather report now.","coverage":1.0}],"file":"c569fde0107d3257be43.js","track":0,"media":"../assets/media/0387157f77ff515c0e23ffeb38010c49dc878b8a5ca1788df852ff5d80b629d9.mp3"}],"../assets/media/21beb822b411d43d71e0e07203911d90b58a3cfd4b1f02c7b505f511d2f420b3.mp3":[{"id":"PPT_21beb822b411d43d","audioId":"PPT_21beb822b411d43d","title":"Book 3 · Unit 4 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 234","duration":67.58,"cues":[{"start":0.0,"end":2.26,"text":"four .three","coverage":1.0},{"start":2.26,"end":3.48,"text":"one","coverage":1.0},{"start":4.58,"end":8.38,"text":"Anthropology in a general sense is the study of humanity.","coverage":1.0},{"start":9.16,"end":18.1,"text":"I know that's not very exact That's why we have many types of anthropology like linguistic anthropology and social anthropology","coverage":1.0},{"start":20.56,"end":21.32,"text":"two","coverage":1.0},{"start":22.16,"end":26.18,"text":"Some traditions die out because our way of life changes","coverage":1.0},{"start":28.4,"end":29.14,"text":"three","coverage":1.0},{"start":30.26,"end":33.32,"text":"Now, due to developments in technology,","coverage":1.0},{"start":33.82,"end":37.9,"text":"people spend more time interacting with other people over the internet","coverage":1.0},{"start":40.4,"end":44.76,"text":"four But now we don't have to work so hard.","coverage":1.0},{"start":45.24,"end":49.56,"text":"This is because we have modern kitchens and supermarket food","coverage":1.0},{"start":51.92,"end":52.66,"text":"five","coverage":1.0},{"start":53.46,"end":56.18,"text":"In the United States at Thanksgiving,","coverage":1.0},{"start":56.84,"end":65.68,"text":"which is one of the biggest celebrations Many families go to restaurants because they don't want to spend their holiday working in the kitchen","coverage":1.0},{"start":66.76,"end":67.52,"text":"six","coverage":1.0}],"file":"c5ad1ea9cf0a13e9eb10.js","track":0,"media":"../assets/media/21beb822b411d43d71e0e07203911d90b58a3cfd4b1f02c7b505f511d2f420b3.mp3"}],"../assets/media/70b2fc007af5e3fba9d55ee3b69df04e899bb7b9e58b68398ed1a8217b2916a1.mp3":[{"id":"PPT_70b2fc007af5e3fb","audioId":"PPT_70b2fc007af5e3fb","title":"Book 2 · Unit 4 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 53","duration":250.88,"cues":[{"start":0.0,"end":2.3,"text":"four .two","coverage":1.0},{"start":3.46,"end":8.98,"text":"So we need to think of some questions for this survey about the weather,","coverage":1.0},{"start":9.34,"end":9.8,"text":"Murat.","coverage":1.0},{"start":10.26,"end":11.9,"text":"Should we make a list of them?","coverage":1.0},{"start":12.68,"end":16.02,"text":"I think we should decide what we want to find out.","coverage":1.0},{"start":17.32,"end":22.5,"text":"Professor Hadland told us we should look at all the different things we could survey,","coverage":1.0},{"start":23.16,"end":27.6,"text":"group them and then try to choose the most important ones.","coverage":1.0},{"start":27.6,"end":28.88,"text":"Right.","coverage":1.0},{"start":29.48,"end":31.82,"text":"Effects of weather on mood.","coverage":1.0},{"start":32.5,"end":32.9,"text":"Well,","coverage":1.0},{"start":33.38,"end":39.06,"text":"we're looking at weather in Northern Europe where it is often cold and wet.","coverage":1.0},{"start":39.86,"end":44.6,"text":"Generally in Northern Europe people see sunshine as positive,","coverage":1.0},{"start":45.26,"end":47.22,"text":"which I find strange.","coverage":1.0},{"start":48.08,"end":49.04,"text":"In my country,","coverage":1.0},{"start":49.42,"end":51.26,"text":"it's hot all the time.","coverage":1.0},{"start":51.26,"end":53.44,"text":"So we like cool days.","coverage":1.0},{"start":53.96,"end":55.18,"text":"But anyway,","coverage":1.0},{"start":55.72,"end":59.52,"text":"I read some research about weather and moods in Sweden.","coverage":1.0},{"start":60.14,"end":65.06,"text":"I really enjoyed reading it, but it had so many different answers.","coverage":1.0},{"start":65.44,"end":69.04,"text":"It wasn't clear that weather changes people's mood.","coverage":1.0},{"start":69.16,"end":70.02,"text":"Oh,","coverage":1.0},{"start":70.78,"end":71.16,"text":"great.","coverage":1.0},{"start":71.94,"end":74.98,"text":"But they did find some specific results.","coverage":1.0},{"start":75.78,"end":81.6,"text":"They noticed that good dry sunny weather didn't make people happier.","coverage":1.0},{"start":82.52,"end":88.38,"text":"But bad weather made people more upset if they were already unhappy.","coverage":1.0},{"start":89.54,"end":89.7,"text":"And?","coverage":1.0},{"start":90.02,"end":95.9,"text":"And therefore unhappy people felt even worse when it was wet and windy.","coverage":1.0},{"start":96.5,"end":97.3,"text":"Oh, OK.","coverage":1.0},{"start":98.08,"end":100.18,"text":"So for the good weather category,","coverage":1.0},{"start":100.62,"end":100.69,"text":"no","coverage":1.0},{"start":100.69,"end":101.06,"text":"link.","coverage":1.0},{"start":101.5,"end":102.84,"text":"But for the bad weather part,","coverage":1.0},{"start":103.3,"end":105.96,"text":"it causes unhappy people to feel worse.","coverage":1.0},{"start":106.58,"end":106.9,"text":"Yes.","coverage":1.0},{"start":106.9,"end":111.58,"text":"And the amount of sunlight seems to be linked to feeling tired.","coverage":1.0},{"start":112.12,"end":113.5,"text":"When it is sunny,","coverage":1.0},{"start":114.04,"end":117.54,"text":"people have more energy and are less tired.","coverage":1.0},{"start":118.4,"end":121.68,"text":"So they like doing more things outside.","coverage":1.0},{"start":122.32,"end":122.62,"text":"OK,","coverage":1.0},{"start":123.06,"end":124.4,"text":"I've added that.","coverage":1.0},{"start":124.88,"end":127.48,"text":"Also, I read something about humid weather.","coverage":1.0},{"start":128.36,"end":133.74,"text":"Another experiment showed that really humid weather changes how people work.","coverage":1.0},{"start":134.6,"end":135.84,"text":"When it is humid,","coverage":1.0},{"start":136.32,"end":139.26,"text":"they might plan to study at a different time,","coverage":1.0},{"start":139.78,"end":145.64,"text":"or maybe they might stop studying and take a break when they begin having difficulties.","coverage":1.0},{"start":146.82,"end":147.64,"text":"As a result,","coverage":1.0},{"start":148.22,"end":152.64,"text":"it is more difficult to work and it's hard to pay attention.","coverage":1.0},{"start":153.8,"end":157.18,"text":"And there was something about heat and anger.","coverage":1.0},{"start":157.92,"end":161.18,"text":"Really hot weather can make people angrier, I think.","coverage":1.0},{"start":161.68,"end":162.56,"text":"Are you sure?","coverage":1.0},{"start":162.9,"end":163.88,"text":"Should I add it?","coverage":1.0},{"start":164.36,"end":166.28,"text":"Well, write it down anyway.","coverage":1.0},{"start":166.28,"end":167.24,"text":"OK.","coverage":1.0},{"start":168.38,"end":171.08,"text":"Which area do you think we should look at then?","coverage":1.0},{"start":172.1,"end":175.08,"text":"I think the humid one is important,","coverage":1.0},{"start":175.54,"end":177.08,"text":"especially for students.","coverage":1.0},{"start":177.74,"end":182.64,"text":"But the one on bad weather making people feel worse could be interesting too.","coverage":1.0},{"start":183.36,"end":186.4,"text":"It sounds like there are more useful facts with that topic.","coverage":1.0},{"start":186.92,"end":188.18,"text":"Yes, true.","coverage":1.0},{"start":189.2,"end":193.6,"text":"I'm not sure about the really hot weather and being angry.","coverage":1.0},{"start":194.08,"end":196.16,"text":"I can't remember if that's true.","coverage":1.0},{"start":196.84,"end":197.34,"text":"So,","coverage":1.0},{"start":197.86,"end":199.34,"text":"let's leave that out.","coverage":1.0},{"start":200.3,"end":202.74,"text":"That leaves three possible topics.","coverage":1.0},{"start":203.96,"end":205.72,"text":"Humid weather stops us working,","coverage":1.0},{"start":206.5,"end":208.78,"text":"sunny weather makes us less tired,","coverage":1.0},{"start":209.4,"end":212.36,"text":"or bad weather makes people feel worse.","coverage":1.0},{"start":213.84,"end":217.68,"text":"The one about humid weather looks at how people study.","coverage":1.0},{"start":218.4,"end":220.88,"text":"It isn't really about how people feel,","coverage":1.0},{"start":221.34,"end":223.42,"text":"so it isn't useful for us.","coverage":1.0},{"start":223.98,"end":226.64,"text":"I'd go with bad weather or sunny weather.","coverage":1.0},{"start":227.38,"end":228.42,"text":"I see what you mean.","coverage":1.0},{"start":229.16,"end":230.92,"text":"We could choose either of those.","coverage":1.0},{"start":231.8,"end":234.2,"text":"I'm not sure about the bad weather one.","coverage":1.0},{"start":234.72,"end":236.66,"text":"It's a bit depressing, isn't it?","coverage":1.0},{"start":237.56,"end":238.58,"text":"Which do you prefer?","coverage":1.0},{"start":239.44,"end":240.98,"text":"I don't really care.","coverage":1.0},{"start":241.64,"end":243.56,"text":"Well, if you don't care,","coverage":1.0},{"start":243.86,"end":247.24,"text":"let's do the one about sunshine and having energy.","coverage":1.0},{"start":247.74,"end":248.94,"text":"It's more positive.","coverage":1.0}],"file":"c7d7cd205c6baa18fbab.js","track":0,"media":"../assets/media/70b2fc007af5e3fba9d55ee3b69df04e899bb7b9e58b68398ed1a8217b2916a1.mp3"}],"../assets/media/8d1527e16bed1cd7c728b661b7ae3af6ac344e72237a9b8cc768a8e0fba1276b.mp3":[{"id":"B3_U04_T4.2_SHORT_S03_v01","audioId":"B3_U04_T4.2_SHORT_S03_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 3","subtitle":"H1 · 4.2-S03","duration":19.005147,"cues":[{"start":0.03,"end":1.65,"text":"Host: Is that a bad thing?","coverage":0.833},{"start":2.03,"end":3.6,"text":"Dr Lee: I don’t think so.","coverage":0.714},{"start":4.03,"end":8.93,"text":"There are people who complain about the changes that technology has brought to our lives.","coverage":1.0},{"start":9.55,"end":12.3,"text":"Personally, I think these changes are fine.","coverage":1.0},{"start":13.03,"end":18.68,"text":"We still spend time interacting with other people, but it’s not always face to-face.","coverage":1.0}],"file":"ca310d0180311b762f1f.js","track":2,"media":"../assets/media/8d1527e16bed1cd7c728b661b7ae3af6ac344e72237a9b8cc768a8e0fba1276b.mp3"}],"../assets/media/9dd06189ed78946987bfa3ed2ddd556c33b69f55adb775618ca7038ddf16c16d.mp3":[{"id":"B3_U04_T4.2_SHORT_S04_v01","audioId":"B3_U04_T4.2_SHORT_S04_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 4","subtitle":"H1 · 4.2-S04","duration":65.11127,"cues":[{"start":0.03,"end":5.77,"text":"Host: In your book, you discuss how technology has changed the way we celebrate important holidays.","coverage":0.938},{"start":6.28,"end":6.77,"text":"Dr Lee: That’s right.","coverage":0.6},{"start":7.03,"end":11.0,"text":"A simple example is sending cards or messages.","coverage":1.0},{"start":11.32,"end":20.0,"text":"In the past, people sent each other cards to celebrate important events, like an anniversary or a new baby.","coverage":1.0},{"start":20.25,"end":27.99,"text":"But now, more people send messages through social networking sites or by text or email.","coverage":1.0},{"start":28.34,"end":32.65,"text":"Another example of changing customs is holiday food.","coverage":1.0},{"start":33.03,"end":40.75,"text":"A few generations ago, people spent a lot of time and effort preparing special meals for celebrations.","coverage":1.0},{"start":41.03,"end":43.7,"text":"It was usually the women who did this.","coverage":1.0},{"start":44.33,"end":48.0,"text":"Some dishes could take up to a week to prepare.","coverage":1.0},{"start":48.26,"end":50.67,"text":"But now we don’t have to work so hard.","coverage":1.0},{"start":51.32,"end":55.66,"text":"This is because we have modern kitchens and supermarket food.","coverage":1.0},{"start":56.04,"end":61.0,"text":"We don’t have to spend endless hours making our own butter or bread any more.","coverage":0.875},{"start":62.33,"end":64.7,"text":"Everything is quicker and easier now.","coverage":1.0}],"file":"ca310d0180311b762f1f.js","track":3,"media":"../assets/media/9dd06189ed78946987bfa3ed2ddd556c33b69f55adb775618ca7038ddf16c16d.mp3"}],"../assets/media/b0c7f3931e8ebe744dfb0db765809510a8e39bc0f6f49b5c8a2ab3db7668992b.mp3":[{"id":"B3_U04_T4.2_SHORT_S05_v01","audioId":"B3_U04_T4.2_SHORT_S05_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 5","subtitle":"H1 · 4.2-S05","duration":54.583923,"cues":[{"start":0.21,"end":4.34,"text":"Host: Hmm … I remember my grandmother working for days to make food.","coverage":0.917},{"start":5.01,"end":9.01,"text":"She had a huge cookery book which she got from her grandmother.","coverage":0.917},{"start":9.49,"end":13.45,"text":"Everything had to be exactly as it was when she was a little girl.","coverage":1.0},{"start":13.97,"end":18.67,"text":"Dr Lee: That’s a good example of a tradition which has been replaced by technology.","coverage":0.875},{"start":19.17,"end":22.35,"text":"You can find any recipe you want on the internet.","coverage":1.0},{"start":22.85,"end":26.36,"text":"This means that many people don’t need cookery books any more.","coverage":0.75},{"start":27.49,"end":33.03,"text":"Another thing is that many families now go out instead of cooking at home.","coverage":1.0},{"start":33.55,"end":41.91,"text":"In India, for example, families hire catering companies to provide food for weddings or special occasions.","coverage":1.0},{"start":42.39,"end":54.584,"text":"In the United States, at Thanksgiving, which is one of the biggest celebrations, many families go to restaurants because they don’t want to spend their holiday working in the kitchen.","coverage":1.0}],"file":"ca310d0180311b762f1f.js","track":4,"media":"../assets/media/b0c7f3931e8ebe744dfb0db765809510a8e39bc0f6f49b5c8a2ab3db7668992b.mp3"}],"../assets/media/f8c984212f3c228a3673a1d569d2e947ec2dfcc3c0a957fe8b83b217e6a35c85.mp3":[{"id":"B3_U04_T4.2_SHORT_S06_v01","audioId":"B3_U04_T4.2_SHORT_S06_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 6","subtitle":"H1 · 4.2-S06","duration":17.67254,"cues":[{"start":0.14,"end":6.02,"text":"Host: So people do continue their tradition of eating a special meal – they just do it in a different way.","coverage":0.95},{"start":6.54,"end":6.66,"text":"Dr Lee: Yes.","coverage":0.333},{"start":6.91,"end":15.79,"text":"Traditions don’t always die out – but customs and traditions do change and adapt to the modern world.","coverage":1.0}],"file":"ca310d0180311b762f1f.js","track":5,"media":"../assets/media/f8c984212f3c228a3673a1d569d2e947ec2dfcc3c0a957fe8b83b217e6a35c85.mp3"}],"../assets/media/4a7c1427836b88d01118eaea9d91e0f85eb641d409e942855ef353a907e393b6.mp3":[{"id":"B3_U04_T4.6_SHORT_S01_v01","audioId":"B3_U04_T4.6_SHORT_S01_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 7","subtitle":"H1 · 4.6-S01","duration":73.999252,"cues":[{"start":2.25,"end":13.47,"text":"Gabriela: So, our assignment is to discuss customs which have been changing recently – you know, how modern lifestyles have changed people’s behaviour.","coverage":0.957},{"start":13.76,"end":14.39,"text":"Any ideas?","coverage":1.0},{"start":14.84,"end":16.84,"text":"Yildiz: Hmm … Let me think.","coverage":0.8},{"start":17.28,"end":20.57,"text":"Well, holidays are one kind of custom.","coverage":1.0},{"start":21.64,"end":24.1,"text":"Can you think of any holidays which have changed?","coverage":1.0},{"start":24.49,"end":26.55,"text":"David: Oh, don’t talk about holidays!","coverage":0.857},{"start":26.84,"end":31.82,"text":"It reminds me that Mother’s Day is in two days and I haven’t bought a gift for my mum yet.","coverage":0.955},{"start":32.38,"end":33.48,"text":"Gabriela: Yeah, I haven’t either.","coverage":0.833},{"start":34.04,"end":38.32,"text":"Who has time for shopping when we have so much work to do?","coverage":1.0},{"start":38.77,"end":39.23,"text":"David: I agree.","coverage":0.667},{"start":39.53,"end":42.1,"text":"I get tired of shopping for gifts.","coverage":1.0},{"start":42.44,"end":46.86,"text":"I actually don’t know why we have to get gifts for every little holiday.","coverage":1.0},{"start":47.23,"end":57.89,"text":"Wouldn’t our mothers be just as happy if we just spent time with them – you know, made it a special event, like taking them out to lunch at a nice restaurant?","coverage":1.0},{"start":58.56,"end":64.1,"text":"How did this whole gift giving for every holiday tradition get started, anyway?","coverage":1.0},{"start":64.68,"end":65.92,"text":"It seems silly to me.","coverage":1.0},{"start":66.76,"end":67.28,"text":"Gabriela: That’s it!","coverage":0.75},{"start":67.68,"end":69.17,"text":"There’s our topic!","coverage":1.0},{"start":69.52,"end":72.08,"text":"How holidays have become too commercial.","coverage":1.0}],"file":"ca310d0180311b762f1f.js","track":6,"media":"../assets/media/4a7c1427836b88d01118eaea9d91e0f85eb641d409e942855ef353a907e393b6.mp3"}],"../assets/media/f65fb3867c6de16dc68899ecb41a1afbcd7cb1361720947b8fc4e820fad7f69b.mp3":[{"id":"B3_U04_T4.7_SHORT_S01_v01","audioId":"B3_U04_T4.7_SHORT_S01_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 8","subtitle":"H1 · 4.7-S01","duration":57.000249,"cues":[{"start":2.49,"end":4.58,"text":"Yildiz: Hold on, too commercial?","coverage":0.8},{"start":5.14,"end":5.92,"text":"I disagree.","coverage":1.0},{"start":6.2,"end":7.61,"text":"I like giving gifts.","coverage":1.0},{"start":8.83,"end":12.46,"text":"I think that it shows that you were thinking of someone.","coverage":0.909},{"start":12.95,"end":19.38,"text":"David: Because you went out and got someone some chocolate or jewellery or a scarf or something at the last minute?","coverage":0.905},{"start":19.64,"end":26.51,"text":"Everyone knows that people usually buy gifts because it’s an obligation, not because they really want to.","coverage":1.0},{"start":27.17,"end":34.36,"text":"Yildiz: Well, you have to spend time thinking about the gift and get something thoughtful, you know, personal.","coverage":0.944},{"start":35.53,"end":38.66,"text":"Like maybe the new book by their favourite author.","coverage":1.0},{"start":39.13,"end":40.26,"text":"Gabriela: I see your point.","coverage":0.8},{"start":40.74,"end":49.51,"text":"But I’m not convinced because then you have to spend money … money which could be spent on more important things.","coverage":1.0},{"start":49.84,"end":56.8,"text":"Also, all that time you spent shopping you could have instead spent with the person you’re shopping for.","coverage":1.0}],"file":"ca310d0180311b762f1f.js","track":7,"media":"../assets/media/f65fb3867c6de16dc68899ecb41a1afbcd7cb1361720947b8fc4e820fad7f69b.mp3"}],"../assets/media/77467bacc8f61a0069a664bea37722477bb46cff2f436d5aa0a1e46b4eb7ffb4.mp3":[{"id":"B3_U04_T4.7_SHORT_S02_v01","audioId":"B3_U04_T4.7_SHORT_S02_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 9","subtitle":"H1 · 4.7-S02","duration":39.145556,"cues":[{"start":0.1,"end":1.59,"text":"David: I couldn’t agree more.","coverage":0.833},{"start":2.14,"end":10.17,"text":"And it’s not just holidays which are a problem – personally, I think we give too many gifts for other special occasions, too.","coverage":1.0},{"start":10.45,"end":16.7,"text":"Like when my sister graduated from university last year, she got lots of gifts.","coverage":1.0},{"start":16.7,"end":17.88,"text":"And money, too.","coverage":1.0},{"start":18.2,"end":21.21,"text":"The focus was all on opening gifts.","coverage":1.0},{"start":21.68,"end":30.08,"text":"I’ve heard that when people receive more than a few gifts, they usually can’t even remember who gave them which gift.","coverage":1.0},{"start":30.37,"end":34.5,"text":"Instead, why not write letters of advice for the future?","coverage":1.0},{"start":35.01,"end":36.69,"text":"That would be more special.","coverage":1.0},{"start":37.3,"end":38.7,"text":"Gabriela: That’s a great idea!","coverage":0.833}],"file":"ca310d0180311b762f1f.js","track":8,"media":"../assets/media/77467bacc8f61a0069a664bea37722477bb46cff2f436d5aa0a1e46b4eb7ffb4.mp3"}],"../assets/media/d312f9858d359d0ead0f56465c6322cd6ee513dd53fa6294750c25121cf92b60.mp3":[{"id":"B3_U04_T4.7_SHORT_S03_v01","audioId":"B3_U04_T4.7_SHORT_S03_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 10","subtitle":"H1 · 4.7-S03","duration":30.562041,"cues":[{"start":0.35,"end":2.12,"text":"Yildiz: Sorry, I don’t agree.","coverage":0.833},{"start":2.47,"end":6.0,"text":"I doubt that graduates would be happy if we changed that custom!","coverage":0.833},{"start":6.47,"end":9.23,"text":"I think that graduation gifts are practical.","coverage":1.0},{"start":9.68,"end":15.26,"text":"Don’t young people need some gifts and money for starting their new life?","coverage":1.0},{"start":15.8,"end":21.56,"text":"And they can always look at the gift and think of the person who gave it to them.","coverage":1.0},{"start":22.02,"end":24.02,"text":"I think it’s a nice custom.","coverage":1.0},{"start":24.9,"end":27.37,"text":"Gabriela: I’m still really not convinced.","coverage":0.857},{"start":27.7,"end":27.97,"text":"I mean …","coverage":1.0}],"file":"ca310d0180311b762f1f.js","track":9,"media":"../assets/media/d312f9858d359d0ead0f56465c6322cd6ee513dd53fa6294750c25121cf92b60.mp3"}],"../assets/media/9eb36a79ac557ce780a9e6ce111382aea56ad83c306f7e360e90b1200c875457.mp3":[{"id":"B3_U04_T4.1_SHORT_S01_v01","audioId":"B3_U04_T4.1_SHORT_S01_v01","title":"Book 3 · Unit 4 · H1 · 听力材料 11","subtitle":"H1 · 4.1-S01","duration":23.41,"cues":[{"start":0.0,"end":1.48,"text":"Unit four,","coverage":1.0},{"start":2.1,"end":3.22,"text":"four .one","coverage":1.0},{"start":4.0,"end":8.36,"text":"This Sunday on Book of the Week we interview Dr Kevin Lee,","coverage":1.0},{"start":8.84,"end":11.24,"text":"the well -known anthropologist and author.","coverage":1.0},{"start":11.8,"end":16.22,"text":"In this podcast he will tell us of his love for cultural anthropology,","coverage":1.0},{"start":16.74,"end":21.54,"text":"and we'll discuss whether traditions are adapting to the modern world or dying out.","coverage":1.0}],"file":"ca310d0180311b762f1f.js","track":10,"media":"../assets/media/9eb36a79ac557ce780a9e6ce111382aea56ad83c306f7e360e90b1200c875457.mp3"}],"../assets/media/fd35f29335a7295adf34b3bc8ac90d93556ff2d513ca30f629bc998e74845ff8.mp3":[{"id":"PPT_fd35f29335a7295a","audioId":"PPT_fd35f29335a7295a","title":"Book 2 · Unit 2 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 57","duration":23.35,"cues":[{"start":0.0,"end":2.26,"text":"two .three","coverage":1.0},{"start":3.4,"end":8.94,"text":"one So what kinds of things do people learn and do here?","coverage":1.0},{"start":10.8,"end":14.92,"text":"two Are there any things you don't like about it?","coverage":1.0},{"start":16.84,"end":17.64,"text":"three","coverage":1.0},{"start":18.2,"end":21.38,"text":"Do you have many people here from other countries?","coverage":1.0}],"file":"cadd00414008e66837d9.js","track":0,"media":"../assets/media/fd35f29335a7295adf34b3bc8ac90d93556ff2d513ca30f629bc998e74845ff8.mp3"}],"../assets/media/2f21d8680df4c211b38c026d22076138246dfbdfcd0f421f4f2adb819fd5fce9.mp3":[{"id":"PPT_2f21d8680df4c211","audioId":"PPT_2f21d8680df4c211","title":"Book 3 · Unit 1 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 49","duration":297.04,"cues":[{"start":0.0,"end":1.38,"text":"Unit one,","coverage":1.0},{"start":2.18,"end":3.58,"text":"one .one","coverage":1.0},{"start":3.58,"end":4.16,"text":"Hello","coverage":1.0},{"start":4.16,"end":5.98,"text":"and welcome!","coverage":1.0},{"start":6.4,"end":9.72,"text":"Today's debate is on using animals for work.","coverage":1.0},{"start":10.36,"end":14.48,"text":"The first animal that was domesticated by humans is the dog.","coverage":1.0},{"start":14.9,"end":20.08,"text":"Even now, dogs are still used to protect our houses and keep us safe.","coverage":1.0},{"start":20.74,"end":25.14,"text":"Other domesticated animals used for food include sheep,","coverage":1.0},{"start":25.54,"end":26.84,"text":"cows, and goats.","coverage":1.0},{"start":26.84,"end":33.74,"text":"The first donkeys were used by humans approximately six ,000 years ago in Egypt.","coverage":1.0},{"start":34.28,"end":38.84,"text":"Horses were domesticated five ,000 years ago in Europe and Asia.","coverage":1.0},{"start":39.76,"end":44.12,"text":"All these animals have been used to help human beings survive,","coverage":1.0},{"start":44.64,"end":48.26,"text":"either by providing food or by working for us.","coverage":1.0},{"start":49.06,"end":50.6,"text":"Horses, camels,","coverage":1.0},{"start":50.98,"end":58.58,"text":"elephants – they have all helped humans explore their land and transport goods from one place to another.","coverage":1.0},{"start":59.18,"end":60.7,"text":"But is this fair?","coverage":1.0},{"start":61.0,"end":62.48,"text":"What about animal rights?","coverage":1.0},{"start":63.04,"end":66.52,"text":"To argue for this issue today, we have Amy Johnson,","coverage":1.0},{"start":67.08,"end":69.32,"text":"an animal rights activist and writer.","coverage":1.0},{"start":69.88,"end":72.52,"text":"To argue against the issue is Dr.","coverage":1.0},{"start":72.66,"end":73.58,"text":"Jacob Korean.","coverage":1.0},{"start":74.42,"end":74.88,"text":"Dr.","coverage":1.0},{"start":75.14,"end":77.7,"text":"Korean is a professor of zoology,","coverage":1.0},{"start":78.08,"end":84.28,"text":"which is the scientific study of animals, and a writer of several books on animal welfare.","coverage":1.0},{"start":84.9,"end":88.88,"text":"You both have two minutes to introduce your point of view.","coverage":1.0},{"start":89.52,"end":89.7,"text":"Ms.","coverage":1.0},{"start":89.9,"end":90.18,"text":"Johnson,","coverage":1.0},{"start":90.66,"end":91.78,"text":"would you like to begin?","coverage":1.0},{"start":92.52,"end":94.82,"text":"Thank you for inviting me to this debate.","coverage":1.0},{"start":95.6,"end":101.22,"text":"It's well known that animals have worked side by side with humans for thousands of years.","coverage":1.0},{"start":101.78,"end":106.7,"text":"In fact, they helped us develop our civilization and helped humans survive.","coverage":1.0},{"start":107.68,"end":112.44,"text":"Animals like elephants and horses were used to build amazing structures,","coverage":1.0},{"start":112.84,"end":114.14,"text":"like the pyramids in Egypt.","coverage":1.0},{"start":114.9,"end":119.9,"text":"Yet their hard work and suffering are hardly ever recognized.","coverage":1.0},{"start":120.94,"end":121.7,"text":"For example,","coverage":1.0},{"start":122.36,"end":127.72,"text":"horses, camels, and elephants were used to transport armies and soldiers during wars,","coverage":1.0},{"start":128.32,"end":131.02,"text":"and many of these animals died in these wars.","coverage":1.0},{"start":132.44,"end":133.9,"text":"And there are other examples.","coverage":1.0},{"start":134.54,"end":138.92,"text":"Even now, dogs are used to pull sleds in cold climates,","coverage":1.0},{"start":139.26,"end":141.04,"text":"and elephants are used for logging.","coverage":1.0},{"start":141.76,"end":146.28,"text":"These animals work long hours and live in difficult conditions.","coverage":1.0},{"start":147.36,"end":149.74,"text":"However, they get very little reward.","coverage":1.0},{"start":150.48,"end":152.92,"text":"Humans just use them to their advantage.","coverage":1.0},{"start":153.86,"end":157.12,"text":"My main argument is that in the modern world, there is","coverage":1.0},{"start":157.12,"end":157.42,"text":"no","coverage":1.0},{"start":157.42,"end":160.7,"text":"longer any need to use animals for work.","coverage":1.0},{"start":161.46,"end":163.92,"text":"We have technology that can replace them.","coverage":1.0},{"start":164.6,"end":168.0,"text":"It's similar to using children to work in factories.","coverage":1.0},{"start":168.92,"end":170.46,"text":"200 years ago,","coverage":1.0},{"start":170.94,"end":173.56,"text":"factory owners got rich by using children.","coverage":1.0},{"start":174.28,"end":178.84,"text":"Nowadays, people still get rich by using animals to do work for them.","coverage":1.0},{"start":179.74,"end":181.7,"text":"The problem is that the animals have","coverage":1.0},{"start":181.7,"end":181.98,"text":"no","coverage":1.0},{"start":181.98,"end":184.7,"text":"one to represent them and protect their rights.","coverage":1.0},{"start":185.5,"end":191.76,"text":"Even though animals work hard for us, they are often abandoned when they get sick or too old to work.","coverage":1.0},{"start":192.2,"end":193.0,"text":"They suffer.","coverage":1.0},{"start":193.68,"end":194.48,"text":"In short,","coverage":1.0},{"start":194.96,"end":201.4,"text":"I strongly believe that using animals for work is an old -fashioned and cruel practice.","coverage":1.0},{"start":202.58,"end":203.4,"text":"Thank you, Ms.","coverage":1.0},{"start":203.74,"end":203.96,"text":"Johnson.","coverage":1.0},{"start":204.66,"end":204.96,"text":"Dr.","coverage":1.0},{"start":205.24,"end":205.52,"text":"Kurian,","coverage":1.0},{"start":206.06,"end":207.62,"text":"your introduction, please.","coverage":1.0},{"start":208.32,"end":209.04,"text":"Thank you.","coverage":1.0},{"start":209.72,"end":213.76,"text":"It's true that animals have helped our civilization develop.","coverage":1.0},{"start":214.66,"end":218.86,"text":"Camels and horses helped us carry goods across huge distances.","coverage":1.0},{"start":219.5,"end":223.26,"text":"Dogs helped us hunt and protected us from wild animals.","coverage":1.0},{"start":224.16,"end":227.58,"text":"Humans don't have the skills or strength to do these jobs.","coverage":1.0},{"start":228.84,"end":231.92,"text":"I want to argue that in many low -income countries,","coverage":1.0},{"start":232.26,"end":234.16,"text":"people still need animals to survive.","coverage":1.0},{"start":234.94,"end":237.14,"text":"These are people who can't afford cars,","coverage":1.0},{"start":237.5,"end":239.76,"text":"house alarms or expensive machines.","coverage":1.0},{"start":240.86,"end":244.82,"text":"Another point is that not all animal use is abuse.","coverage":1.0},{"start":245.32,"end":246.34,"text":"On the contrary,","coverage":1.0},{"start":246.8,"end":247.56,"text":"without humans,","coverage":1.0},{"start":248.04,"end":251.3,"text":"these domesticated animals would not have been able to survive.","coverage":1.0},{"start":251.86,"end":253.66,"text":"They need us to take care of them.","coverage":1.0},{"start":254.68,"end":259.88,"text":"There are many animal lovers around the world who work in animal shelters and help animals.","coverage":1.0},{"start":260.54,"end":262.96,"text":"There are laws that stop animal suffering.","coverage":1.0},{"start":263.58,"end":269.88,"text":"And people give a lot of money to animal charities and organizations that help save wildlife.","coverage":1.0},{"start":270.82,"end":272.1,"text":"At the same time,","coverage":1.0},{"start":272.46,"end":277.1,"text":"there are still millions of children in the world who don't get this kind of treatment.","coverage":1.0},{"start":277.8,"end":279.82,"text":"They go without food or clothing.","coverage":1.0},{"start":280.78,"end":284.08,"text":"I strongly believe that in a modern society,","coverage":1.0},{"start":284.38,"end":289.34,"text":"people often care more about animals than they do about people in low -income countries.","coverage":1.0},{"start":290.38,"end":292.24,"text":"Thank you both for your arguments.","coverage":1.0},{"start":292.8,"end":295.04,"text":"Now let's hear from our listeners.","coverage":1.0}],"file":"cb86f0b0a696970a72b1.js","track":0,"media":"../assets/media/2f21d8680df4c211b38c026d22076138246dfbdfcd0f421f4f2adb819fd5fce9.mp3"}],"../assets/media/a94aaadefc0d40573c2e177d54d7110de501db7b7309c1e10fbfd6c3364540d6.mp3":[{"id":"PPT_a94aaadefc0d4057","audioId":"PPT_a94aaadefc0d4057","title":"Book 2 · Unit 8 · RW · READING 1","subtitle":"READING 1 · source slide 48","duration":259.89,"cues":[{"start":0.0,"end":2.7,"text":"the rise of commercial space travel,","coverage":1.0},{"start":3.78,"end":4.22,"text":"news,","coverage":1.0},{"start":5.42,"end":6.08,"text":"science,","coverage":1.0},{"start":7.26,"end":7.84,"text":"discoveries,","coverage":1.0},{"start":9.06,"end":9.76,"text":"technology,","coverage":1.0},{"start":10.94,"end":11.78,"text":"education,","coverage":1.0},{"start":12.92,"end":13.38,"text":"blogs,","coverage":1.0},{"start":14.62,"end":15.18,"text":"community.","coverage":1.0},{"start":16.18,"end":17.72,"text":"In 1957,","coverage":1.0},{"start":18.12,"end":22.04,"text":"the Soviet Union sent Sputnik one into space.","coverage":1.0},{"start":22.6,"end":26.76,"text":"It was the first successful spacecraft to orbit Earth,","coverage":1.0},{"start":27.34,"end":31.08,"text":"and it started the time period known as the Space Age.","coverage":1.0},{"start":31.88,"end":34.8,"text":"A short time later in the United States,","coverage":1.0},{"start":35.22,"end":38.18,"text":"the National Aeronautics and Space Administration,","coverage":1.0},{"start":38.5,"end":39.0,"text":"NASA,","coverage":1.0},{"start":39.68,"end":41.96,"text":"successfully sent another spacecraft,","coverage":1.0},{"start":42.58,"end":43.48,"text":"Explorer one,","coverage":1.0},{"start":43.88,"end":44.86,"text":"into space.","coverage":1.0},{"start":45.6,"end":47.04,"text":"In the years that followed,","coverage":1.0},{"start":47.88,"end":49.54,"text":"incredible advances were made.","coverage":1.0},{"start":50.32,"end":52.06,"text":"Astronauts orbited Earth,","coverage":1.0},{"start":52.46,"end":54.34,"text":"and men walked on the moon.","coverage":1.0},{"start":55.14,"end":56.54,"text":"The world, it seemed,","coverage":1.0},{"start":57.0,"end":59.84,"text":"wanted to learn what was beyond Earth.","coverage":1.0},{"start":60.9,"end":61.42,"text":"Today,","coverage":1.0},{"start":62.08,"end":63.94,"text":"space exploration continues,","coverage":1.0},{"start":64.54,"end":69.54,"text":"and governments still compete with one another to make new discoveries.","coverage":1.0},{"start":70.86,"end":72.0,"text":"In 2012,","coverage":1.0},{"start":72.68,"end":75.38,"text":"NASA landed its unmanned spacecraft,","coverage":1.0},{"start":75.68,"end":76.62,"text":"Curiosity,","coverage":1.0},{"start":77.08,"end":77.68,"text":"on Mars,","coverage":1.0},{"start":78.38,"end":81.42,"text":"in order to collect information about the planet.","coverage":1.0},{"start":82.5,"end":83.9,"text":"In 2016,","coverage":1.0},{"start":84.42,"end":89.36,"text":"Europe and Russia worked together and sent a spacecraft to Mars.","coverage":1.0},{"start":90.46,"end":94.6,"text":"China and India are also working on similar projects.","coverage":1.0},{"start":95.7,"end":96.16,"text":"However,","coverage":1.0},{"start":96.7,"end":99.22,"text":"there has been one big change.","coverage":1.0},{"start":99.9,"end":101.08,"text":"Private companies,","coverage":1.0},{"start":101.4,"end":104.0,"text":"instead of public government organizations,","coverage":1.0},{"start":104.54,"end":106.8,"text":"are entering the space race.","coverage":1.0},{"start":107.72,"end":112.44,"text":"SpaceX has been very successful in commercial space travel.","coverage":1.0},{"start":113.22,"end":120.66,"text":"They designed the spacecraft Dragon in order to deliver supplies to the International Space Station,","coverage":1.0},{"start":121.2,"end":121.78,"text":"ISS.","coverage":1.0},{"start":122.88,"end":123.94,"text":"In 2012,","coverage":1.0},{"start":124.62,"end":129.5,"text":"Dragon was the first commercial spacecraft in history to do that.","coverage":1.0},{"start":130.54,"end":131.28,"text":"Elon Musk,","coverage":1.0},{"start":131.64,"end":137.5,"text":"the man who started the company, has dreams that go beyond making deliveries.","coverage":1.0},{"start":138.4,"end":142.34,"text":"He hopes to build a base on Mars by 2028,","coverage":1.0},{"start":143.02,"end":148.74,"text":"and a one million person city there in the next 50 to 100 years.","coverage":1.0},{"start":150.32,"end":156.08,"text":"Another entrepreneur who supports commercial space travel is Sir Richard Branson.","coverage":1.0},{"start":156.96,"end":160.86,"text":"He started a private company called Virgin Galactic.","coverage":1.0},{"start":161.74,"end":165.3,"text":"Their goal is to open space travel to everyone.","coverage":1.0},{"start":166.3,"end":171.02,"text":"The company has sold about 700 future trips to space,","coverage":1.0},{"start":171.48,"end":177.14,"text":"some at the high cost of $450 ,000 per person.","coverage":1.0},{"start":178.32,"end":185.5,"text":"Those future space tourists come from countries all over the world and are all different ages.","coverage":1.0},{"start":186.42,"end":189.88,"text":"Private companies are lucky in one way.","coverage":1.0},{"start":190.48,"end":194.86,"text":"They don't have to wait for money from the government like NASA does.","coverage":1.0},{"start":195.66,"end":196.14,"text":"However,","coverage":1.0},{"start":196.56,"end":200.74,"text":"that doesn't mean that setbacks and accidents don't happen.","coverage":1.0},{"start":201.72,"end":203.06,"text":"In 2014,","coverage":1.0},{"start":203.68,"end":211.7,"text":"Virgin Galactic's VSS Enterprise crashed in the Mojave Desert in the United States during a test flight.","coverage":1.0},{"start":212.5,"end":214.6,"text":"The 39 -year -old pilot,","coverage":1.0},{"start":215.06,"end":216.9,"text":"Michael Alsbury, was killed.","coverage":1.0},{"start":217.8,"end":219.06,"text":"In 2023,","coverage":1.0},{"start":219.62,"end":226.98,"text":"the SpaceX spacecraft Starship exploded on its first flight after around two or three minutes.","coverage":1.0},{"start":227.86,"end":228.01,"text":"No","coverage":1.0},{"start":228.01,"end":233.5,"text":"one was hurt, and Elon Musk said they were going to try again in a few months.","coverage":1.0},{"start":234.4,"end":237.92,"text":"The race to explore the universe continues,","coverage":1.0},{"start":238.56,"end":241.02,"text":"and many private companies are competing.","coverage":1.0},{"start":241.88,"end":246.44,"text":"Some of those companies want to take people to the moon and back someday.","coverage":1.0},{"start":247.28,"end":249.78,"text":"Others want to take people to Mars.","coverage":1.0},{"start":250.68,"end":252.82,"text":"The possibilities are endless.","coverage":1.0},{"start":253.76,"end":255.1,"text":"Maybe in our lifetime,","coverage":1.0},{"start":255.74,"end":257.98,"text":"those dreams will come true.","coverage":1.0}],"file":"d00e9eea166dace87da9.js","track":0,"media":"../assets/media/a94aaadefc0d40573c2e177d54d7110de501db7b7309c1e10fbfd6c3364540d6.mp3"}],"../assets/media/a5448c7ab9134941a3c4074def61321f3542345d16240438cdbb018cd56dd37c.mp3":[{"id":"PPT_a5448c7ab9134941","audioId":"PPT_a5448c7ab9134941","title":"Book 2 · Unit 5 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 67","duration":94.93,"cues":[{"start":0.0,"end":2.28,"text":"five .three","coverage":1.0},{"start":3.72,"end":4.68,"text":"one","coverage":1.0},{"start":5.22,"end":6.12,"text":"Now,","coverage":1.0},{"start":6.66,"end":13.18,"text":"chess boxing is a new type of sport where the players do both activities.","coverage":1.0},{"start":14.12,"end":15.6,"text":"They start with boxing,","coverage":1.0},{"start":15.96,"end":16.38,"text":"sorry,","coverage":1.0},{"start":16.9,"end":18.34,"text":"I mean chess,","coverage":1.0},{"start":18.8,"end":20.72,"text":"and then do some boxing,","coverage":1.0},{"start":21.22,"end":26.44,"text":"and they continue doing each activity back and forth, alternating.","coverage":1.0},{"start":28.54,"end":29.5,"text":"two","coverage":1.0},{"start":30.7,"end":31.66,"text":"Next,","coverage":1.0},{"start":32.16,"end":35.66,"text":"I'd like to talk about the Moroccan desert foot race,","coverage":1.0},{"start":36.14,"end":40.1,"text":"which is also called the marathon des Sables,","coverage":1.0},{"start":40.68,"end":43.12,"text":"or the Tahara marathon.","coverage":1.0},{"start":44.18,"end":48.14,"text":"This race is held every year over a week,","coverage":1.0},{"start":48.66,"end":49.5,"text":"or rather,","coverage":1.0},{"start":50.12,"end":51.26,"text":"over six days.","coverage":1.0},{"start":53.44,"end":54.4,"text":"three","coverage":1.0},{"start":55.46,"end":56.16,"text":"Finally,","coverage":1.0},{"start":56.86,"end":60.16,"text":"I'd like to look at Sepak Takraw.","coverage":1.0},{"start":61.06,"end":67.12,"text":"This is a type of volleyball and is very popular in Southeast Asia.","coverage":1.0},{"start":68.06,"end":70.86,"text":"The players use a different kind of ball,","coverage":1.0},{"start":71.52,"end":73.96,"text":"and they can use their feet to kick the ball,","coverage":1.0},{"start":74.38,"end":76.94,"text":"or hit it with their knees, chest,","coverage":1.0},{"start":77.28,"end":77.82,"text":"or head.","coverage":1.0},{"start":77.82,"end":81.22,"text":"The sport began in Indonesia,","coverage":1.0},{"start":81.96,"end":82.52,"text":"and it,","coverage":1.0},{"start":82.94,"end":83.48,"text":"no,","coverage":1.0},{"start":83.9,"end":84.7,"text":"not Indonesia,","coverage":1.0},{"start":85.38,"end":87.54,"text":"it began in Malaysia,","coverage":1.0},{"start":88.58,"end":92.96,"text":"although it is also very popular in Thailand and Indonesia.","coverage":1.0}],"file":"d1e9d8578758a26a18ea.js","track":0,"media":"../assets/media/a5448c7ab9134941a3c4074def61321f3542345d16240438cdbb018cd56dd37c.mp3"}],"../assets/media/f51ce3559a84e154b685e75b49f60f6078c7d11187149d232635f88a03adba3b.mp3":[{"id":"PPT_f51ce3559a84e154","audioId":"PPT_f51ce3559a84e154","title":"Book 2 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 56","duration":56.48,"cues":[{"start":0.0,"end":2.3,"text":"six .two","coverage":1.0},{"start":3.34,"end":3.68,"text":"Hello","coverage":1.0},{"start":3.68,"end":6.18,"text":"Hi, Professor Gould.","coverage":1.0},{"start":6.7,"end":7.8,"text":"This is Alika.","coverage":1.0},{"start":8.54,"end":11.04,"text":"Could I make an appointment to see you?","coverage":1.0},{"start":11.32,"end":14.52,"text":"I wanted to talk about my research project.","coverage":1.0},{"start":14.84,"end":16.36,"text":"I'm not done yet.","coverage":1.0},{"start":17.18,"end":21.9,"text":"Also, I'm not sure what I should write about for the business solution.","coverage":1.0},{"start":22.76,"end":23.78,"text":"Yes, of course.","coverage":1.0},{"start":24.42,"end":26.36,"text":"Can you tell me what you were able to finish?","coverage":1.0},{"start":27.28,"end":29.74,"text":"Well, I chose a problem.","coverage":1.0},{"start":30.44,"end":33.16,"text":"Then I found and read lots of articles.","coverage":1.0},{"start":33.66,"end":37.0,"text":"I have notes on information from my research.","coverage":1.0},{"start":37.54,"end":40.16,"text":"I met with my group for topic discussions,","coverage":1.0},{"start":40.68,"end":40.7,"text":"too.","coverage":1.0},{"start":41.58,"end":42.4,"text":"I see.","coverage":1.0},{"start":43.04,"end":44.56,"text":"Let's meet tomorrow then.","coverage":1.0},{"start":45.24,"end":46.9,"text":"Please bring your research notes.","coverage":1.0},{"start":47.54,"end":51.14,"text":"Let's discuss some causes and effects of the problem you researched.","coverage":1.0},{"start":52.02,"end":53.94,"text":"Can you meet at ten a .m.,","coverage":1.0},{"start":53.94,"end":54.56,"text":"Student Union?","coverage":1.0}],"file":"d40d4c40f7c435582371.js","track":0,"media":"../assets/media/f51ce3559a84e154b685e75b49f60f6078c7d11187149d232635f88a03adba3b.mp3"}],"../assets/media/4f4cd9cbf244d67ae9dda224ff7f38a8061d984e9fec4dd27afeb6ac9116771c.mp3":[{"id":"PPT_4f4cd9cbf244d67a","audioId":"PPT_4f4cd9cbf244d67a","title":"Book 3 · Unit 4 · RW · READING 1","subtitle":"READING 1 · source slide 48","duration":305.48,"cues":[{"start":0.0,"end":3.56,"text":"Customs Around the World by Andy Schmidt.","coverage":1.0},{"start":5.0,"end":6.12,"text":"In recent decades,","coverage":1.0},{"start":6.56,"end":10.46,"text":"foreign travel has become a multi -billion dollar industry.","coverage":1.0},{"start":11.4,"end":13.9,"text":"International travel has many benefits,","coverage":1.0},{"start":14.38,"end":21.24,"text":"but visitors can run into trouble if they don't know some basic rules about the cultures they're visiting.","coverage":1.0},{"start":22.0,"end":34.86,"text":"It is very important for travelers to take the time to learn about the cultures they plan to visit so that they know what to expect and how to avoid cultural misunderstandings.","coverage":1.0},{"start":35.66,"end":40.02,"text":"That is why we are presenting this Customs Around the World series,","coverage":1.0},{"start":40.44,"end":47.12,"text":"where we will look at three different cultures every month to help you become a well -informed traveler.","coverage":1.0},{"start":48.08,"end":51.4,"text":"This month's exciting destinations are Brazil,","coverage":1.0},{"start":51.82,"end":52.38,"text":"Japan,","coverage":1.0},{"start":53.02,"end":54.32,"text":"and Saudi Arabia.","coverage":1.0},{"start":55.44,"end":56.28,"text":"Brazil.","coverage":1.0},{"start":57.66,"end":58.46,"text":"In general,","coverage":1.0},{"start":58.92,"end":60.86,"text":"Brazilian culture is informal.","coverage":1.0},{"start":61.66,"end":66.5,"text":"Most Brazilians are very friendly people, so it is important to say","coverage":1.0},{"start":66.5,"end":67.0,"text":"hello","coverage":1.0},{"start":67.0,"end":69.5,"text":"and goodbye to the people you meet.","coverage":1.0},{"start":70.56,"end":71.12,"text":"Normally,","coverage":1.0},{"start":71.46,"end":74.44,"text":"women kiss men and each other on the cheek,","coverage":1.0},{"start":75.02,"end":77.9,"text":"but men usually just shake hands.","coverage":1.0},{"start":78.96,"end":84.58,"text":"Brazilians typically stand very close to each other and touch each other's arms,","coverage":1.0},{"start":84.98,"end":88.02,"text":"elbows, and back regularly while speaking.","coverage":1.0},{"start":89.06,"end":91.66,"text":"Even if this is unusual in your culture,","coverage":1.0},{"start":92.08,"end":94.78,"text":"try not to move away if this happens.","coverage":1.0},{"start":95.76,"end":97.56,"text":"If you go to a business meeting,","coverage":1.0},{"start":97.96,"end":100.36,"text":"you are not expected to take a gift.","coverage":1.0},{"start":101.1,"end":101.74,"text":"In fact,","coverage":1.0},{"start":102.18,"end":105.72,"text":"an expensive gift can be seen as suspicious.","coverage":1.0},{"start":106.64,"end":108.48,"text":"On the other hand,","coverage":1.0},{"start":108.8,"end":112.9,"text":"if you are invited to someone's house, you should take a gift,","coverage":1.0},{"start":113.48,"end":114.3,"text":"for example,","coverage":1.0},{"start":114.66,"end":116.18,"text":"flowers or chocolate.","coverage":1.0},{"start":117.24,"end":117.76,"text":"However,","coverage":1.0},{"start":118.2,"end":120.58,"text":"avoid anything purple or black,","coverage":1.0},{"start":120.94,"end":123.52,"text":"as these colors are related to death.","coverage":1.0},{"start":124.48,"end":126.72,"text":"If you are invited to dinner,","coverage":1.0},{"start":127.14,"end":129.26,"text":"arrive at least 30 minutes late,","coverage":1.0},{"start":129.8,"end":135.62,"text":"but always dress well, because a person's appearance can be very important to Brazilians.","coverage":1.0},{"start":138.14,"end":142.22,"text":"The Japanese are quite different from the Brazilians.","coverage":1.0},{"start":142.84,"end":144.64,"text":"They tend to be quite formal,","coverage":1.0},{"start":144.96,"end":147.14,"text":"so don't stand too close.","coverage":1.0},{"start":147.82,"end":151.08,"text":"Kissing or touching in public is not common.","coverage":1.0},{"start":151.08,"end":154.24,"text":"When you meet Japanese people socially,","coverage":1.0},{"start":154.66,"end":156.38,"text":"they may shake your hand.","coverage":1.0},{"start":156.78,"end":157.3,"text":"However,","coverage":1.0},{"start":157.8,"end":160.78,"text":"bowing, bending forwards to show respect,","coverage":1.0},{"start":161.34,"end":162.62,"text":"is the traditional greeting.","coverage":1.0},{"start":164.2,"end":165.36,"text":"In a business meeting,","coverage":1.0},{"start":165.72,"end":172.22,"text":"the Japanese often like to know what your position is in your company before they talk to you.","coverage":1.0},{"start":172.22,"end":176.54,"text":"You should hand over a business card using both hands,","coverage":1.0},{"start":177.14,"end":179.08,"text":"and when you receive a business card,","coverage":1.0},{"start":179.52,"end":181.72,"text":"you should immediately read it carefully.","coverage":1.0},{"start":182.72,"end":184.76,"text":"It is important to be punctual.","coverage":1.0},{"start":185.46,"end":188.4,"text":"You should arrive early and dress formally.","coverage":1.0},{"start":189.36,"end":190.86,"text":"Gifts are often exchanged,","coverage":1.0},{"start":191.32,"end":196.52,"text":"but the recipient may refuse the gift at least once before accepting it.","coverage":1.0},{"start":197.32,"end":200.76,"text":"You should remember to do the same if you receive a gift.","coverage":1.0},{"start":200.76,"end":203.04,"text":"When you present your gift,","coverage":1.0},{"start":203.36,"end":206.72,"text":"you should say that it is a token of your appreciation.","coverage":1.0},{"start":208.54,"end":213.09,"text":"Saudi Arabia is a very traditional country.","coverage":1.0},{"start":214.1,"end":215.46,"text":"In business situations,","coverage":1.0},{"start":215.92,"end":219.96,"text":"you should know that hierarchy is important to Saudis.","coverage":1.0},{"start":220.18,"end":220.74,"text":"Therefore,","coverage":1.0},{"start":221.16,"end":225.76,"text":"it is important to greet the oldest or the most senior person first.","coverage":1.0},{"start":226.76,"end":230.4,"text":"Men may shake hands with men and women with women,","coverage":1.0},{"start":230.74,"end":232.8,"text":"always using the right hand.","coverage":1.0},{"start":233.58,"end":237.62,"text":"Men and women do not touch or shake hands in public.","coverage":1.0},{"start":239.12,"end":243.06,"text":"Personal relationships are very important in Saudi Arabia.","coverage":1.0},{"start":244.0,"end":245.06,"text":"In a business meeting,","coverage":1.0},{"start":245.5,"end":248.16,"text":"do not start with business matters immediately.","coverage":1.0},{"start":249.02,"end":249.58,"text":"Instead,","coverage":1.0},{"start":249.92,"end":253.18,"text":"start by asking about people's family or health.","coverage":1.0},{"start":253.18,"end":256.48,"text":"Arrive on time for business meetings,","coverage":1.0},{"start":257.0,"end":260.04,"text":"but do not be surprised if others are late.","coverage":1.0},{"start":261.0,"end":267.36,"text":"Punctuality is less important in Saudi Arabia than it is in Japan or the United States.","coverage":1.0},{"start":268.06,"end":269.64,"text":"Business dress is formal.","coverage":1.0},{"start":270.24,"end":272.58,"text":"Men should wear dark suits and ties,","coverage":1.0},{"start":273.1,"end":275.34,"text":"and women should wear modest clothes.","coverage":1.0},{"start":275.34,"end":283.9,"text":"Gifts are not expected at business meetings until those involved have formed a strong relationship.","coverage":1.0},{"start":284.96,"end":288.16,"text":"If you are invited to a Saudi home or office,","coverage":1.0},{"start":288.84,"end":291.52,"text":"acceptable gifts are good quality chocolate,","coverage":1.0},{"start":292.14,"end":292.46,"text":"coffee,","coverage":1.0},{"start":292.88,"end":293.56,"text":"or dates.","coverage":1.0},{"start":294.54,"end":298.1,"text":"Be careful not to admire the things the host owns,","coverage":1.0},{"start":298.6,"end":303.58,"text":"because he or she will feel obliged to give an item to you as a gift.","coverage":1.0}],"file":"d4bf0f643758dde200fc.js","track":0,"media":"../assets/media/4f4cd9cbf244d67ae9dda224ff7f38a8061d984e9fec4dd27afeb6ac9116771c.mp3"}],"../assets/media/06fbfee20dd35b6c663b68a1cdeef537adf55b863826bef206976f19ef9e9ab8.mp3":[{"id":"PPT_06fbfee20dd35b6c","audioId":"PPT_06fbfee20dd35b6c","title":"Book 3 · Unit 5 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 43","duration":176.67,"cues":[{"start":0.0,"end":1.0,"text":"five .two","coverage":1.0},{"start":1.98,"end":2.64,"text":"So,","coverage":1.0},{"start":3.02,"end":9.34,"text":"new research shows that having a healthy lifestyle is not the most important thing if you want to live a long life.","coverage":1.0},{"start":9.84,"end":14.08,"text":"We asked four people on the street for their reactions to this news.","coverage":1.0},{"start":14.82,"end":16.36,"text":"I think it's great news.","coverage":1.0},{"start":16.96,"end":22.04,"text":"Most people think that if they eat healthy food and exercise a lot they'll live forever.","coverage":1.0},{"start":22.76,"end":26.24,"text":"These people never drink coffee or sugary drinks.","coverage":1.0},{"start":26.64,"end":34.0,"text":"They spend hours working out in the gym or doing yoga and none of this matters if you have the wrong genes.","coverage":1.0},{"start":34.76,"end":38.4,"text":"I think that the key to a healthy life is to enjoy yourself.","coverage":1.0},{"start":38.86,"end":42.84,"text":"If you focus all your energy on what to do and what not to do,","coverage":1.0},{"start":43.28,"end":44.82,"text":"you'll be unhappy eventually.","coverage":1.0},{"start":45.38,"end":45.6,"text":"There's","coverage":1.0},{"start":45.6,"end":45.88,"text":"no","coverage":1.0},{"start":45.88,"end":48.36,"text":"question that happy people live longer.","coverage":1.0},{"start":49.18,"end":53.74,"text":"I'd much rather go out and have a pizza with friends than spend time in the gym.","coverage":1.0},{"start":54.36,"end":56.46,"text":"I'm really happy about this new research.","coverage":1.0},{"start":58.38,"end":61.9,"text":"This research proves what I've known for a long time.","coverage":1.0},{"start":62.38,"end":67.12,"text":"It's ridiculous to get too worried about healthy eating and exercise.","coverage":1.0},{"start":67.78,"end":73.74,"text":"My grandfather lived until he was 95 even though he never exercised.","coverage":1.0},{"start":74.2,"end":77.94,"text":"He ate lots of sugar and never ate vegetables.","coverage":1.0},{"start":78.68,"end":80.92,"text":"He was brought up in a different world.","coverage":1.0},{"start":81.44,"end":82.98,"text":"He had different habits.","coverage":1.0},{"start":83.42,"end":85.64,"text":"He certainly never went to a gym.","coverage":1.0},{"start":86.46,"end":90.52,"text":"Yes, I'm sure that genes are more important than our lifestyle.","coverage":1.0},{"start":91.32,"end":97.1,"text":"Of course, I'm not going to give up exercising or start eating fast food every day.","coverage":1.0},{"start":97.64,"end":105.64,"text":"The research shows I should stay in shape because it makes me feel better but I won't allow fitness to take over my whole life.","coverage":1.0},{"start":105.64,"end":110.3,"text":"Well, first of all, I prefer to exercise and eat well.","coverage":1.0},{"start":110.94,"end":112.68,"text":"What's wrong with being healthy?","coverage":1.0},{"start":113.36,"end":118.4,"text":"I also think that you won't know whether or not you have the right genes until you get sick.","coverage":1.0},{"start":119.02,"end":121.64,"text":"So why take the risk and be unhealthy?","coverage":1.0},{"start":122.64,"end":130.06,"text":"Also, don't forget that you might get the flu or a cold much more easily when you don't eat healthy food or exercise.","coverage":1.0},{"start":130.88,"end":134.72,"text":"I'd say that it's always better to have a healthy lifestyle.","coverage":1.0},{"start":135.8,"end":136.0,"text":"There's","coverage":1.0},{"start":136.0,"end":136.26,"text":"no","coverage":1.0},{"start":136.26,"end":140.28,"text":"doubt that bad health habits increase the chances of getting a serious illness.","coverage":1.0},{"start":140.74,"end":141.76,"text":"Oh, that's great.","coverage":1.0},{"start":142.12,"end":145.4,"text":"So now we should all eat fast food and stop exercising?","coverage":1.0},{"start":146.36,"end":150.12,"text":"I mean, I look around and I see overweight children everywhere.","coverage":1.0},{"start":150.78,"end":150.84,"text":"No","coverage":1.0},{"start":150.84,"end":159.62,"text":"matter how good their genes are, I'm sure that these children won't be able to enjoy a long and healthy life unless they give up crisps,","coverage":1.0},{"start":160.02,"end":160.66,"text":"chocolate bars,","coverage":1.0},{"start":161.18,"end":161.98,"text":"sugary drinks.","coverage":1.0},{"start":162.8,"end":174.66,"text":"Well it's great that some people can live to be a hundred and do whatever they want in their lives but I prefer to be careful and take care of myself because I don't know if I have good genes.","coverage":1.0}],"file":"d5c45894aeaadc9ac912.js","track":0,"media":"../assets/media/06fbfee20dd35b6c663b68a1cdeef537adf55b863826bef206976f19ef9e9ab8.mp3"}],"../assets/media/1e6f9af13fc0d19be75c4314c3e1da9b7985c93080526558527bf4021e7be53e.mp3":[{"id":"PPT_1e6f9af13fc0d19b","audioId":"PPT_1e6f9af13fc0d19b","title":"Book 2 · Unit 3 · RW · READING 2","subtitle":"READING 2 · source slide 128","duration":195.11,"cues":[{"start":0.0,"end":3.3,"text":"Do video games affect our children negatively?","coverage":1.0},{"start":4.36,"end":7.74,"text":"Today, our children spend more and more time online.","coverage":1.0},{"start":8.62,"end":13.44,"text":"Many children spend a lot of their free time playing games on the internet,","coverage":1.0},{"start":13.82,"end":15.16,"text":"on video game systems,","coverage":1.0},{"start":15.66,"end":17.26,"text":"or on their mobile devices.","coverage":1.0},{"start":18.0,"end":18.82,"text":"In the UK,","coverage":1.0},{"start":19.58,"end":24.68,"text":"99 % of kids aged eight to 15 play video games every week,","coverage":1.0},{"start":25.28,"end":28.78,"text":"and children as young as five play video games regularly.","coverage":1.0},{"start":29.58,"end":36.1,"text":"This information tells us that the benefits and dangers of video games must be carefully considered.","coverage":1.0},{"start":37.32,"end":38.26,"text":"For many people,","coverage":1.0},{"start":38.86,"end":41.06,"text":"video games are fun and educational.","coverage":1.0},{"start":41.7,"end":44.02,"text":"They have bright lights, funny cartoons,","coverage":1.0},{"start":44.46,"end":45.8,"text":"and exciting stories.","coverage":1.0},{"start":46.66,"end":50.38,"text":"Everywhere you look, you can see children playing these games.","coverage":1.0},{"start":50.92,"end":53.22,"text":"They play on buses and trains,","coverage":1.0},{"start":53.62,"end":55.76,"text":"in restaurants, and even at school.","coverage":1.0},{"start":56.52,"end":60.04,"text":"Video games also make you think in a creative way,","coverage":1.0},{"start":60.5,"end":63.2,"text":"and you have to move your hands and eyes quickly.","coverage":1.0},{"start":64.08,"end":67.04,"text":"This can improve the way that a child's brain works.","coverage":1.0},{"start":68.16,"end":71.64,"text":"Video games also make children use their imagination.","coverage":1.0},{"start":72.54,"end":75.16,"text":"The player has to do many creative things,","coverage":1.0},{"start":75.5,"end":77.14,"text":"like draw, tell stories,","coverage":1.0},{"start":77.52,"end":78.62,"text":"and build things.","coverage":1.0},{"start":79.58,"end":84.26,"text":"Video games are also a good way to teach children about technology,","coverage":1.0},{"start":84.72,"end":89.8,"text":"because they can learn how computers and other devices work while they play.","coverage":1.0},{"start":90.92,"end":91.38,"text":"However,","coverage":1.0},{"start":92.16,"end":96.98,"text":"a recent study suggests that video games can also be bad for children.","coverage":1.0},{"start":97.8,"end":98.36,"text":"First,","coverage":1.0},{"start":98.74,"end":101.32,"text":"children can download many games for free.","coverage":1.0},{"start":101.84,"end":103.06,"text":"They don't need money,","coverage":1.0},{"start":103.38,"end":106.76,"text":"so they don't need to ask their parents if they can download the games.","coverage":1.0},{"start":107.44,"end":113.64,"text":"This means that parents often don't know if their children are playing violent or scary games.","coverage":1.0},{"start":114.66,"end":115.02,"text":"Second,","coverage":1.0},{"start":115.52,"end":119.64,"text":"many children spend too much time playing games on computers,","coverage":1.0},{"start":120.14,"end":121.56,"text":"smartphones, and tablets,","coverage":1.0},{"start":122.04,"end":123.98,"text":"and this can lead to health problems.","coverage":1.0},{"start":124.88,"end":130.26,"text":"Children who spend too much time on the computer and don't exercise can become overweight.","coverage":1.0},{"start":131.34,"end":132.0,"text":"Third,","coverage":1.0},{"start":132.36,"end":136.38,"text":"if children spend too much time playing games instead of doing homework,","coverage":1.0},{"start":136.94,"end":140.08,"text":"they can have problems at school and get bad grades.","coverage":1.0},{"start":141.08,"end":141.74,"text":"Finally,","coverage":1.0},{"start":142.4,"end":145.14,"text":"video games can affect children's social skills.","coverage":1.0},{"start":145.9,"end":149.64,"text":"Playing and working with friends is very important for children,","coverage":1.0},{"start":150.1,"end":152.72,"text":"and it teaches them how to talk to other people.","coverage":1.0},{"start":153.44,"end":157.28,"text":"If children spend too much time playing video games by themselves,","coverage":1.0},{"start":157.78,"end":160.58,"text":"they might not learn how to play with their friends.","coverage":1.0},{"start":161.92,"end":162.78,"text":"In conclusion,","coverage":1.0},{"start":163.32,"end":167.74,"text":"it seems clear that video games have some advantages and some disadvantages.","coverage":1.0},{"start":168.56,"end":169.54,"text":"On the one hand,","coverage":1.0},{"start":169.88,"end":173.42,"text":"they are fun and have many educational benefits for children.","coverage":1.0},{"start":174.04,"end":179.12,"text":"On the other hand, they can cause problems with children's health and social skills.","coverage":1.0},{"start":179.8,"end":185.54,"text":"It is up to parents to know what games their children are playing and how much time they spend on them.","coverage":1.0},{"start":186.3,"end":193.2,"text":"Parents should also make sure their children get enough exercise and spend time with other children.","coverage":1.0}],"file":"d834fd4fe96467dc2449.js","track":0,"media":"../assets/media/1e6f9af13fc0d19be75c4314c3e1da9b7985c93080526558527bf4021e7be53e.mp3"}],"../assets/media/e9f8810528edddc12461d4334482a365c222653fd5cfc7885a6c46d8f1f01b57.wav":[{"id":"B3_U01_T1.1_SHORT_S03_v01","audioId":"B3_U01_T1.1_SHORT_S03_v01","title":"Book 3 · Unit 1 · H1 · 听力材料 3","subtitle":"H1 · 1.1-S03","duration":48.61707482993197,"cues":[{"start":0,"end":7.0,"text":"My main argument is that in the modern world, there is no longer any need to use animals for work.","coverage":1.0},{"start":7.7,"end":10.6,"text":"We have technology that can replace them.","coverage":1.0},{"start":10.9,"end":14.78,"text":"It’s similar to using children to work in factories.","coverage":1.0},{"start":15.1,"end":20.06,"text":"Two hundred years ago, factory owners got rich by using children.","coverage":1.0},{"start":21.3,"end":25.54,"text":"Nowadays, people still get rich by using animals to do work for them.","coverage":0.923},{"start":25.9,"end":31.39,"text":"The problem is that the animals have no one to represent them and protect their rights.","coverage":1.0},{"start":32.02,"end":38.09,"text":"Even though animals work hard for us, they are often abandoned when they get sick or too old to work.","coverage":1.0},{"start":38.83,"end":39.55,"text":"They suffer.","coverage":1.0},{"start":39.9,"end":48.05,"text":"In short, I strongly believe that using animals for work is an old-fashioned and cruel practice.","coverage":1.0}],"file":"d8a69fec3de32951e841.js","track":2,"media":"../assets/media/e9f8810528edddc12461d4334482a365c222653fd5cfc7885a6c46d8f1f01b57.wav"}],"../assets/media/ab5d64ae7d88f64804d8a5821e981128f408a0676f346fdf15e1b52ce81e6070.wav":[{"id":"B3_U01_T1.1_SHORT_S04_v01","audioId":"B3_U01_T1.1_SHORT_S04_v01","title":"Book 3 · Unit 1 · H1 · 听力材料 4","subtitle":"H1 · 1.1-S04","duration":38.37421768707483,"cues":[{"start":0.44,"end":1.92,"text":"Host: Thank you, Ms Johnson.","coverage":0.8},{"start":2.54,"end":5.38,"text":"Dr Kuryan – your introduction, please.","coverage":0.8},{"start":6.41,"end":6.99,"text":"Dr Kuryan: Thank you.","coverage":0.5},{"start":7.44,"end":12.27,"text":"It’s true that animals have helped our civilization develop.","coverage":1.0},{"start":13.29,"end":17.3,"text":"Camels and horses helped us carry goods across huge distances.","coverage":0.9},{"start":17.66,"end":21.92,"text":"Dogs helped us hunt and protected us from wild animals.","coverage":1.0},{"start":22.5,"end":26.34,"text":"Humans don’t have the skills or strength to do these jobs.","coverage":1.0},{"start":26.88,"end":32.41,"text":"I want to argue that, in many low-income countries, people still need animals to survive.","coverage":1.0},{"start":33.08,"end":37.62,"text":"These are people who can’t afford cars, house alarms or expensive machines.","coverage":1.0}],"file":"d8a69fec3de32951e841.js","track":3,"media":"../assets/media/ab5d64ae7d88f64804d8a5821e981128f408a0676f346fdf15e1b52ce81e6070.wav"}],"../assets/media/6a79903b93ab49f74a34a589fc4818085b93be28a769e53ef785751fd99feef5.wav":[{"id":"B3_U01_T1.1_SHORT_S05_v01","audioId":"B3_U01_T1.1_SHORT_S05_v01","title":"Book 3 · Unit 1 · H1 · 听力材料 5","subtitle":"H1 · 1.1-S05","duration":56.68469387755102,"cues":[{"start":0.5,"end":4.54,"text":"Another point is that not all animal use is abuse.","coverage":1.0},{"start":5.28,"end":11.08,"text":"On the contrary, without humans, these domesticated animals would not have been able to survive.","coverage":0.933},{"start":12.1,"end":14.19,"text":"They need us to take care of them.","coverage":1.0},{"start":14.85,"end":19.99,"text":"There are many animal lovers around the world who work in animal shelters and help animals.","coverage":1.0},{"start":20.72,"end":23.13,"text":"There are laws that stop animal suffering.","coverage":1.0},{"start":23.29,"end":30.4,"text":"And people give a lot of money to animal charities and organizations that help save wildlife.","coverage":1.0},{"start":30.76,"end":36.9,"text":"At the same time, there are still millions of children in the world who don’t get this kind of treatment.","coverage":1.0},{"start":37.94,"end":40.06,"text":"They go without food or clothing.","coverage":1.0},{"start":40.44,"end":49.66,"text":"I strongly believe that, in a modern society, people often care more about animals than they do about people in low-income countries.","coverage":1.0},{"start":50.38,"end":52.32,"text":"Host: Thank you both for your arguments!","coverage":0.857},{"start":52.6,"end":54.57,"text":"Now, let’s hear from our listeners …","coverage":1.0}],"file":"d8a69fec3de32951e841.js","track":4,"media":"../assets/media/6a79903b93ab49f74a34a589fc4818085b93be28a769e53ef785751fd99feef5.wav"}],"../assets/media/28c02255c3dc65cd5d85c2569e7c12f0f146647b92d28d4700abba829e5adf50.mp3":[{"id":"B3_U01_T1.2_SHORT_S01_v01","audioId":"B3_U01_T1.2_SHORT_S01_v01","title":"Book 3 · Unit 1 · H1 · 听力材料 6","subtitle":"H1 · 1.2-S01","duration":73.379025,"cues":[{"start":2.24,"end":4.9,"text":"Woman: Hello, and thank you all for coming.","coverage":0.875},{"start":5.0,"end":9.68,"text":"I know you’re all busy students and I appreciate that you’re here today.","coverage":1.0},{"start":10.15,"end":18.68,"text":"As we all know, there are many animals which are disappearing from our planet: rhinos, orangutans, sea turtles ...","coverage":0.889},{"start":19.0,"end":20.69,"text":"the list is shocking.","coverage":1.0},{"start":21.22,"end":25.64,"text":"Now, what do you think of when you hear ‘African elephant’?","coverage":1.0},{"start":26.24,"end":30.65,"text":"Perhaps something like: intelligent, majestic, powerful.","coverage":1.0},{"start":31.22,"end":39.71,"text":"Now, even though these words describe these creatures perfectly, those three qualities may not be enough to save them.","coverage":1.0},{"start":40.09,"end":45.67,"text":"A century ago, there were around five million elephants across Africa.","coverage":0.909},{"start":46.22,"end":50.68,"text":"Today, it is believed that there are less than 500,000.","coverage":1.0},{"start":51.18,"end":55.65,"text":"In fact, both species of African elephants are endangered.","coverage":1.0},{"start":56.22,"end":72.69,"text":"While people are generally more familiar with the Savanna elephant, I’m here today to talk about the African forest elephant, which is smaller, less well-known, and it’s critically endangered because of the threat that it faces from humans.","coverage":0.976}],"file":"d8a69fec3de32951e841.js","track":5,"media":"../assets/media/28c02255c3dc65cd5d85c2569e7c12f0f146647b92d28d4700abba829e5adf50.mp3"}],"../assets/media/1b8508c894923b15166d37a94350ada5ef0381e00eb5f37a15b585f89826a32e.mp3":[{"id":"B3_U01_T1.2_SHORT_S02_v01","audioId":"B3_U01_T1.2_SHORT_S02_v01","title":"Book 3 · Unit 1 · H1 · 听力材料 7","subtitle":"H1 · 1.2-S02","duration":34.025556,"cues":[{"start":0,"end":7.78,"text":"The main human threat to forest elephants comes from poachers, who hunt them for their long, white, beautiful tusks.","coverage":0.895},{"start":8.52,"end":18.69,"text":"It’s widely known that these tusks are made of ivory, a material that poachers sell to make a lot of money, even though it’s illegal.","coverage":0.926},{"start":19.08,"end":29.95,"text":"The international trade of ivory was banned in 1989, yet several countries still allow ivory to be bought and sold across their borders.","coverage":1.0},{"start":30.32,"end":33.29,"text":"This has actually increased over recent years.","coverage":1.0}],"file":"d8a69fec3de32951e841.js","track":6,"media":"../assets/media/1b8508c894923b15166d37a94350ada5ef0381e00eb5f37a15b585f89826a32e.mp3"}],"../assets/media/4ecff69745ad9779d6795800f698d858f6c96506fb318ffbccfefa5b7d8401a8.mp3":[{"id":"B3_U01_T1.2_SHORT_S03_v01","audioId":"B3_U01_T1.2_SHORT_S03_v01","title":"Book 3 · Unit 1 · H1 · 听力材料 8","subtitle":"H1 · 1.2-S03","duration":28.148005,"cues":[{"start":0,"end":10.63,"text":"The second threat is the loss of the elephants’ habitat, which happens when humans destroy rainforest areas to make the land suitable for farming.","coverage":0.917},{"start":11.0,"end":27.7,"text":"This means the elephants have less space to live in, so the food they depend on for survival, such as fruit, grasses and leaves, not only becomes less available, but also has to be shared between the same number of elephants.","coverage":0.976}],"file":"d8a69fec3de32951e841.js","track":7,"media":"../assets/media/4ecff69745ad9779d6795800f698d858f6c96506fb318ffbccfefa5b7d8401a8.mp3"}],"../assets/media/b0d36f47e36c160d8aa3f36f7353f5e0a775b16b7a27ddf08ce9e5bb12bb0833.mp3":[{"id":"B3_U01_T1.2_SHORT_S04_v01","audioId":"B3_U01_T1.2_SHORT_S04_v01","title":"Book 3 · Unit 1 · H1 · 听力材料 9","subtitle":"H1 · 1.2-S04","duration":28.069637,"cues":[{"start":0,"end":4.48,"text":"A third threat is contact between humans and elephants.","coverage":1.0},{"start":5.59,"end":14.69,"text":"Habitat loss sometimes forces elephants to leave the rainforest and go into villages, where they damage crops growing in farmers’ fields.","coverage":0.905},{"start":15.46,"end":19.53,"text":"Because of this, local people sometimes kill the elephants ...","coverage":1.0},{"start":20.0,"end":27.65,"text":"they see this as the only way to protect themselves, their families, their food and their homes.","coverage":1.0}],"file":"d8a69fec3de32951e841.js","track":8,"media":"../assets/media/b0d36f47e36c160d8aa3f36f7353f5e0a775b16b7a27ddf08ce9e5bb12bb0833.mp3"}],"../assets/media/627bce8d56ff9958757a17b0e2720005ab540f2ca000be3ddf753d4834d86508.mp3":[{"id":"B3_U01_T1.2_SHORT_S05_v01","audioId":"B3_U01_T1.2_SHORT_S05_v01","title":"Book 3 · Unit 1 · H1 · 听力材料 10","subtitle":"H1 · 1.2-S05","duration":76.303515,"cues":[{"start":0.63,"end":12.0,"text":"However, there is good news: it may not be too late to save the African forest elephant, but there are several things that really ought to happen first.","coverage":1.0},{"start":12.4,"end":21.13,"text":"First, there needs to be an increase in the number of specially trained guards who work in the rainforests to catch the poachers.","coverage":0.913},{"start":22.89,"end":34.4,"text":"Second, governments must introduce an immediate and complete ban on anyone buying or selling ivory, even between countries sharing a border.","coverage":1.0},{"start":35.23,"end":41.36,"text":"Third, we have to find ways of reducing contact between humans and elephants.","coverage":1.0},{"start":41.76,"end":49.1,"text":"For instance, local communities should be helped to build suitable fences that can protect their land.","coverage":1.0},{"start":49.8,"end":62.22,"text":"So, to summarize, as well as habitat loss and human contact, the main threat to forest elephants comes from poaching – we’ve got to end the illegal trade of ivory.","coverage":1.0},{"start":62.72,"end":69.38,"text":"The governments and environmental organizations who can do this must not delay for a moment longer.","coverage":1.0},{"start":70.27,"end":74.2,"text":"Without a ban, the African forest elephant may soon become extinct.","coverage":1.0}],"file":"d8a69fec3de32951e841.js","track":9,"media":"../assets/media/627bce8d56ff9958757a17b0e2720005ab540f2ca000be3ddf753d4834d86508.mp3"}],"../assets/media/37eaca29781030439a91c68e131c4debf8e175b1ac89438ded60d26382fe1769.mp3":[{"id":"B3_U08_T8.2_SHORT_S02_v01","audioId":"B3_U08_T8.2_SHORT_S02_v01","title":"Book 3 · Unit 8 · H2 · 听力材料 3","subtitle":"H2 · 8.2-S02","duration":58.450045,"cues":[{"start":0.03,"end":4.49,"text":"So, what do millionaires do and what can we learn from them?","coverage":1.0},{"start":5.23,"end":9.42,"text":"Well, millionaires are often financially savvy.","coverage":1.0},{"start":9.79,"end":15.52,"text":"To put it another way, they’re smart about how to save and spend money.","coverage":1.0},{"start":16.03,"end":22.72,"text":"The first important thing is that millionaires always have a good handle on their budget.","coverage":1.0},{"start":23.11,"end":27.14,"text":"In other words, they know how much they’re spending.","coverage":1.0},{"start":28.08,"end":41.58,"text":"According to Holm, around 75 percent of millionaires know exactly how much money they have and they know exactly how much they spend on food, bills, clothes, etc.","coverage":0.964},{"start":42.03,"end":47.52,"text":"As a result, they don’t spend too much and they don’t get into debt.","coverage":1.0},{"start":47.95,"end":51.85,"text":"They can plan for the future and save their money.","coverage":1.0},{"start":52.31,"end":57.27,"text":"To sum up, the lesson here is that you should never spend more money than you have!","coverage":1.0}],"file":"d9275138665f91979dd6.js","track":2,"media":"../assets/media/37eaca29781030439a91c68e131c4debf8e175b1ac89438ded60d26382fe1769.mp3"}],"../assets/media/894e5b22972d7c2bbd8cb48a6856f36e029bbbc0e161e59915315703fabf02b8.mp3":[{"id":"B3_U08_T8.2_SHORT_S03_v01","audioId":"B3_U08_T8.2_SHORT_S03_v01","title":"Book 3 · Unit 8 · H2 · 听力材料 4","subtitle":"H2 · 8.2-S03","duration":77.362698,"cues":[{"start":0.8,"end":6.0,"text":"Another surprising fact is that millionaires usually have simple lifestyles.","coverage":1.0},{"start":6.76,"end":13.9,"text":"They have nice houses and nice cars, but they don’t spend all their money on these things.","coverage":1.0},{"start":14.32,"end":22.7,"text":"In fact, most rich people stay in the same place for a very long time and don’t live in big, expensive palaces.","coverage":0.957},{"start":23.88,"end":31.96,"text":"Indeed, according to John Holm, half of millionaires have lived in the same house for 20 years.","coverage":0.882},{"start":32.36,"end":39.33,"text":"Also, around 65 percent of millionaires live in homes which cost around the national average.","coverage":0.933},{"start":40.06,"end":49.14,"text":"Again, the important lesson here is to live within your means – that is, don’t spend more money than you have.","coverage":1.0},{"start":49.56,"end":57.67,"text":"If you spend all your savings on a luxury BMW, then you probably aren’t rich – you just want to look rich.","coverage":1.0},{"start":58.44,"end":66.02,"text":"In fact, the study reveals that 86 percent of luxury cars are bought by people who can’t afford them.","coverage":0.95},{"start":66.5,"end":76.25,"text":"Most rich people don’t have bank loans – they only spend a small percentage of what they have and they save or invest the rest.","coverage":1.0}],"file":"d9275138665f91979dd6.js","track":3,"media":"../assets/media/894e5b22972d7c2bbd8cb48a6856f36e029bbbc0e161e59915315703fabf02b8.mp3"}],"../assets/media/c7da16863e8cfac22f3baf14fb7170dedf4ce4519f7470832b012205867e1859.mp3":[{"id":"B3_U08_T8.2_SHORT_S04_v01","audioId":"B3_U08_T8.2_SHORT_S04_v01","title":"Book 3 · Unit 8 · H2 · 听力材料 5","subtitle":"H2 · 8.2-S04","duration":64.7978,"cues":[{"start":0,"end":2.6,"text":"Now here is an interesting fact.","coverage":1.0},{"start":3.28,"end":8.49,"text":"The study shows that most millionaires have very happy relationships.","coverage":1.0},{"start":8.92,"end":13.75,"text":"Not only are they married, but they stay married for a long time.","coverage":1.0},{"start":14.21,"end":21.18,"text":"In John Holm’s opinion, this is very important because of the golden rule about saving money.","coverage":0.882},{"start":21.52,"end":26.52,"text":"There is no doubt that it’s more difficult to save money if you are single.","coverage":1.0},{"start":26.88,"end":31.69,"text":"One effect of being a couple is that it’s easier to save money.","coverage":1.0},{"start":32.08,"end":39.32,"text":"If there are two of you, it’s easier to pay attention to what money you have and what you’re spending.","coverage":1.0},{"start":39.7,"end":45.98,"text":"And of course, people who don’t have huge bank loans and debts are happier.","coverage":1.0},{"start":46.4,"end":54.72,"text":"If you don’t have to worry about the monthly credit card payments, you’re less likely to buy things to make you feel better.","coverage":1.0},{"start":55.16,"end":63.86,"text":"People with debt often spend more time shopping, just to make themselves feel happier, but real millionaires don’t need to do this.","coverage":1.0}],"file":"d9275138665f91979dd6.js","track":4,"media":"../assets/media/c7da16863e8cfac22f3baf14fb7170dedf4ce4519f7470832b012205867e1859.mp3"}],"../assets/media/fe3e3bda3e09373a647b3dc462e514d5deeaa877da9f65b7cd5e6269436c613c.mp3":[{"id":"B3_U08_T8.4_SHORT_S01_v01","audioId":"B3_U08_T8.4_SHORT_S01_v01","title":"Book 3 · Unit 8 · H2 · 听力材料 6","subtitle":"H2 · 8.4-S01","duration":43.767596,"cues":[{"start":0.23,"end":13.88,"text":"Host: In today’s programme, we discuss the recent decision made by several universities to give students money in return for good grades.","coverage":0.87},{"start":14.49,"end":17.87,"text":"Students will be paid by the hour to take additional Maths and Science classes.","coverage":1.0},{"start":18.33,"end":26.31,"text":"The students who improve their grades and keep their grade average high will be given cash rewards at the end of each term.","coverage":1.0},{"start":26.64,"end":34.74,"text":"To discuss this new project, we have invited education expert Dr Michael Burns and we welcome your calls during the programme.","coverage":0.952},{"start":36.0,"end":41.69,"text":"We’d like to hear your opinion: Do you think university students should be paid for good grades?","coverage":1.0}],"file":"d9275138665f91979dd6.js","track":5,"media":"../assets/media/fe3e3bda3e09373a647b3dc462e514d5deeaa877da9f65b7cd5e6269436c613c.mp3"}],"../assets/media/8e94ceefe8cd71d674bf10f3b09ffd1685f70d84b2af234b0738672260d9b07e.mp3":[{"id":"B3_U08_T8.5_SHORT_S01_v01","audioId":"B3_U08_T8.5_SHORT_S01_v01","title":"Book 3 · Unit 8 · H2 · 听力材料 7","subtitle":"H2 · 8.5-S01","duration":36.990454,"cues":[{"start":2.38,"end":4.91,"text":"Host: Dr Burns, thank you for coming today.","coverage":0.875},{"start":5.8,"end":7.48,"text":"Can you tell us more about the project?","coverage":1.0},{"start":8.03,"end":9.49,"text":"Where does this idea come from?","coverage":1.0},{"start":10.25,"end":10.74,"text":"Dr Burns: Thank you.","coverage":0.5},{"start":11.04,"end":16.01,"text":"Well, the idea of paying students for their work isn’t new.","coverage":1.0},{"start":16.4,"end":23.43,"text":"For example, students in Denmark are paid about €760 a month to attend university.","coverage":1.0},{"start":23.8,"end":29.38,"text":"They receive the payments for a maximum of six years, starting at the age of 18.","coverage":0.938},{"start":29.74,"end":36.46,"text":"The goal of paying students is to encourage them to finish their education and be able to get a good job in the future.","coverage":1.0}],"file":"d9275138665f91979dd6.js","track":6,"media":"../assets/media/8e94ceefe8cd71d674bf10f3b09ffd1685f70d84b2af234b0738672260d9b07e.mp3"}],"../assets/media/9c1fd1b9e410f1dd2e7f48cff464dfc6e92ed36bfb5e7d0e67630404d0adc621.mp3":[{"id":"B3_U08_T8.5_SHORT_S02_v01","audioId":"B3_U08_T8.5_SHORT_S02_v01","title":"Book 3 · Unit 8 · H2 · 听力材料 8","subtitle":"H2 · 8.5-S02","duration":68.036984,"cues":[{"start":0.21,"end":0.79,"text":"Host: I see.","coverage":0.667},{"start":1.31,"end":3.4,"text":"Let’s hear from our first caller.","coverage":1.0},{"start":4.34,"end":8.4,"text":"Mariam Hassan is the president of a medium-sized university.","coverage":0.9},{"start":8.6,"end":10.0,"text":"Dr Hassan?","coverage":1.0},{"start":10.54,"end":10.82,"text":"Dr Hassan: Hello.","coverage":0.333},{"start":11.02,"end":16.82,"text":"Yes, I recently read about this new programme and I really don’t think it’s a good idea.","coverage":0.947},{"start":17.27,"end":23.0,"text":"I understand that many students drop out of university because of financial problems.","coverage":1.0},{"start":23.16,"end":27.67,"text":"At my university alone, the dropout rate is over 25 percent.","coverage":0.818},{"start":28.38,"end":32.35,"text":"However, will paying students really encourage them to continue?","coverage":1.0},{"start":32.78,"end":34.71,"text":"In my experience, it won’t.","coverage":1.0},{"start":35.18,"end":44.22,"text":"Of course, the statistics are terrible, but I’m not confident that this programme will solve the real problems – it may just cover them up.","coverage":0.96},{"start":44.67,"end":52.21,"text":"I think the money would be better spent on student services, like hiring additional professors and advisors.","coverage":1.0},{"start":52.69,"end":57.42,"text":"Two of the reasons why students drop out are stress and poor time management.","coverage":1.0},{"start":58.33,"end":61.85,"text":"Advisors can help students learn to manage their time better.","coverage":0.9},{"start":62.3,"end":67.71,"text":"As a consequence, students will do better at university and will be more likely to graduate.","coverage":1.0}],"file":"d9275138665f91979dd6.js","track":7,"media":"../assets/media/9c1fd1b9e410f1dd2e7f48cff464dfc6e92ed36bfb5e7d0e67630404d0adc621.mp3"}],"../assets/media/4d35b7c0d6ba425a30b69b66ec5150394aa0a153684355924755467de57ca4c1.mp3":[{"id":"B3_U08_T8.5_SHORT_S03_v01","audioId":"B3_U08_T8.5_SHORT_S03_v01","title":"Book 3 · Unit 8 · H2 · 听力材料 9","subtitle":"H2 · 8.5-S03","duration":39.171678,"cues":[{"start":0.03,"end":5.0,"text":"Dr Burns: I can see your point, but we have already spent a lot on student services.","coverage":0.882},{"start":5.73,"end":10.66,"text":"I think that paying students to study will show them that we treat them like adults.","coverage":1.0},{"start":11.01,"end":14.03,"text":"It will give them a sense of responsibility.","coverage":1.0},{"start":14.61,"end":25.13,"text":"University students are young adults and so, when they have a choice between staying at university and studying or going to work and making money, they often make the wrong choice.","coverage":1.0},{"start":25.85,"end":28.92,"text":"They want to have money so that they can buy things for themselves.","coverage":1.0},{"start":29.5,"end":31.79,"text":"Besides, we don’t want to pay them a lot.","coverage":1.0},{"start":32.0,"end":38.43,"text":"I think we’re simply giving them an option: stay at university and be paid or get a minimum wage job.","coverage":1.0}],"file":"d9275138665f91979dd6.js","track":8,"media":"../assets/media/4d35b7c0d6ba425a30b69b66ec5150394aa0a153684355924755467de57ca4c1.mp3"}],"../assets/media/0489d0bab972d1f0a6da858773a2702620853d8f0507453565029e930bb11a7e.mp3":[{"id":"B3_U08_T8.5_SHORT_S05_v01","audioId":"B3_U08_T8.5_SHORT_S05_v01","title":"Book 3 · Unit 8 · H2 · 听力材料 10","subtitle":"H2 · 8.5-S05","duration":30.21839,"cues":[{"start":0.28,"end":5.57,"text":"Dr Burns: These are all good points, but I don’t think that this view applies to all students.","coverage":0.895},{"start":6.24,"end":9.71,"text":"Not all parents are educated or interested in studying.","coverage":1.0},{"start":10.28,"end":13.66,"text":"They pass this bad attitude on to their own children.","coverage":1.0},{"start":14.25,"end":16.78,"text":"Then the children don’t see the benefits of learning.","coverage":1.0},{"start":17.21,"end":21.73,"text":"To change this image, we need to show them a good reason for studying.","coverage":1.0},{"start":22.28,"end":23.3,"text":"Host: Thank you.","coverage":0.667},{"start":24.01,"end":27.77,"text":"Let’s have a look now at some of the comments we’ve received during the programme.","coverage":0.941}],"file":"d9275138665f91979dd6.js","track":9,"media":"../assets/media/0489d0bab972d1f0a6da858773a2702620853d8f0507453565029e930bb11a7e.mp3"}],"../assets/media/2eee55d68d2335b8c2a38da0f3fe7608bdbd4ace96a2ce76213cff026d4629a4.mp3":[{"id":"PPT_2eee55d68d2335b8","audioId":"PPT_2eee55d68d2335b8","title":"Book 2 · Unit 5 · RW · READING 2","subtitle":"READING 2 · source slide 129","duration":146.39,"cues":[{"start":0.0,"end":5.12,"text":"Tough Guy – A Race to the Limit What is Tough Guy?","coverage":1.0},{"start":6.22,"end":12.64,"text":"Every January, more than three ,000 people take part in one of the most difficult races on Earth,","coverage":1.0},{"start":13.26,"end":15.82,"text":"the Tough Guy competition in the UK.","coverage":1.0},{"start":16.86,"end":17.94,"text":"Participants run,","coverage":1.0},{"start":18.3,"end":18.68,"text":"swim,","coverage":1.0},{"start":19.04,"end":22.06,"text":"and climb across the 15 -kilometer course.","coverage":1.0},{"start":22.6,"end":23.66,"text":"But this is","coverage":1.0},{"start":23.66,"end":23.98,"text":"no","coverage":1.0},{"start":23.98,"end":24.84,"text":"normal race.","coverage":1.0},{"start":25.64,"end":28.0,"text":"These runners have to crawl through tunnels,","coverage":1.0},{"start":28.46,"end":30.08,"text":"run across a field of nettles,","coverage":1.0},{"start":30.5,"end":32.02,"text":"and jump over fire.","coverage":1.0},{"start":32.72,"end":33.44,"text":"What's more,","coverage":1.0},{"start":33.78,"end":35.92,"text":"the competition takes place in January,","coverage":1.0},{"start":36.3,"end":38.06,"text":"so temperatures are freezing,","coverage":1.0},{"start":38.58,"end":42.02,"text":"sometimes as low as minus six degrees centigrade.","coverage":1.0},{"start":43.08,"end":49.46,"text":"People travel from all over the world to take part, with participants from the United States, Australia,","coverage":1.0},{"start":49.8,"end":50.5,"text":"and China.","coverage":1.0},{"start":52.0,"end":53.98,"text":"Why do people take part?","coverage":1.0},{"start":55.12,"end":57.2,"text":"The competition is very dangerous,","coverage":1.0},{"start":57.56,"end":59.64,"text":"and every year there are accidents.","coverage":1.0},{"start":60.42,"end":63.44,"text":"Injuries like broken bones and cuts are common.","coverage":1.0},{"start":64.26,"end":65.96,"text":"The race is very hard.","coverage":1.0},{"start":66.54,"end":69.62,"text":"One third of participants do not finish it.","coverage":1.0},{"start":70.34,"end":72.38,"text":"Runners have to be fit and healthy.","coverage":1.0},{"start":73.14,"end":76.12,"text":"Most people train all year to prepare for the event.","coverage":1.0},{"start":76.12,"end":80.0,"text":"It is also the first race like it in the world.","coverage":1.0},{"start":80.84,"end":84.34,"text":"Many people take part in the competition because it is so famous.","coverage":1.0},{"start":85.1,"end":89.22,"text":"Every year the organizers change the event and add new things.","coverage":1.0},{"start":89.82,"end":93.74,"text":"This means that the competition stays exciting and challenging,","coverage":1.0},{"start":94.2,"end":96.84,"text":"so people go back year after year.","coverage":1.0},{"start":98.56,"end":99.52,"text":"The Course","coverage":1.0},{"start":100.36,"end":104.4,"text":"The diagram shows an example of the Tough Guy course.","coverage":1.0},{"start":105.12,"end":105.74,"text":"First,","coverage":1.0},{"start":106.5,"end":109.66,"text":"participants run for one kilometer along a muddy road.","coverage":1.0},{"start":110.48,"end":113.98,"text":"Next, they crawl under low nets on the ground.","coverage":1.0},{"start":114.88,"end":115.78,"text":"After the nets,","coverage":1.0},{"start":116.18,"end":121.6,"text":"the runners jump off a high platform into a lake and swim for another kilometer.","coverage":1.0},{"start":122.46,"end":124.88,"text":"Then they reach the field of fire.","coverage":1.0},{"start":125.8,"end":130.46,"text":"Here the runners run across a field and jump over small bonfires.","coverage":1.0},{"start":131.1,"end":131.64,"text":"Next,","coverage":1.0},{"start":132.48,"end":134.52,"text":"participants must crawl through a long tunnel.","coverage":1.0},{"start":135.32,"end":137.14,"text":"The tunnel is partly underwater.","coverage":1.0},{"start":138.22,"end":138.66,"text":"Finally,","coverage":1.0},{"start":139.14,"end":144.56,"text":"the runners run two kilometers through nettles before they reach the finish line.","coverage":1.0}],"file":"dae10e2335a57ea83a2a.js","track":0,"media":"../assets/media/2eee55d68d2335b8c2a38da0f3fe7608bdbd4ace96a2ce76213cff026d4629a4.mp3"}],"../assets/media/7401b6f3eb4703a4136579d0274cc6632d512a66a3b2fc0c25412baf2a411e5b.mp3":[{"id":"PPT_7401b6f3eb4703a4","audioId":"PPT_7401b6f3eb4703a4","title":"Book 3 · Unit 7 · RW · READING 2","subtitle":"READING 2 · source slide 87","duration":227.13,"cues":[{"start":0.0,"end":1.78,"text":"Offshore Production","coverage":1.0},{"start":2.82,"end":5.64,"text":"The world's consumption of fashion is huge.","coverage":1.0},{"start":6.16,"end":7.56,"text":"To give just one example,","coverage":1.0},{"start":8.06,"end":13.86,"text":"the European Union imported more than 29 billion euros worth of clothing in 2020.","coverage":1.0},{"start":14.74,"end":16.22,"text":"As consumption has risen,","coverage":1.0},{"start":16.58,"end":17.7,"text":"prices have fallen.","coverage":1.0},{"start":18.44,"end":18.86,"text":"Today,","coverage":1.0},{"start":19.2,"end":22.6,"text":"a hand -finished shirt may cost as little as five euros.","coverage":1.0},{"start":23.2,"end":25.32,"text":"To make clothes at these low prices,","coverage":1.0},{"start":25.86,"end":27.94,"text":"companies have to keep costs down.","coverage":1.0},{"start":27.94,"end":31.82,"text":"One way they do this is by using offshore production.","coverage":1.0},{"start":32.62,"end":38.8,"text":"Large multinational companies outsource their production to developing countries like Egypt or Cambodia,","coverage":1.0},{"start":39.24,"end":42.6,"text":"where workers are paid much less than in developed countries.","coverage":1.0},{"start":43.32,"end":50.32,"text":"Supporters of outsourcing claim that it helps local economies, but I believe it is harmful for two main reasons.","coverage":1.0},{"start":52.02,"end":54.9,"text":"Some experts, like the economist David Schneider,","coverage":1.0},{"start":55.46,"end":63.2,"text":"say that outsourcing benefits local economies by providing jobs at higher wages than local workers can make by working in agriculture.","coverage":1.0},{"start":64.22,"end":70.98,"text":"Supporters also point out that people in developing countries often line up to take jobs in multinational factories.","coverage":1.0},{"start":71.78,"end":73.04,"text":"While this is true,","coverage":1.0},{"start":73.38,"end":76.42,"text":"these workers, many of them women and children,","coverage":1.0},{"start":77.02,"end":81.84,"text":"often work 14 hours a day and earn less than 100 euros a month.","coverage":1.0},{"start":82.46,"end":90.88,"text":"One study of 15 countries found that textile workers earned less than 40 % of the money they needed to live on each month.","coverage":1.0},{"start":91.56,"end":92.56,"text":"In some countries,","coverage":1.0},{"start":93.04,"end":94.72,"text":"this figure is even lower.","coverage":1.0},{"start":95.66,"end":96.14,"text":"Also,","coverage":1.0},{"start":96.52,"end":98.7,"text":"most workers are paid by the piece.","coverage":1.0},{"start":99.3,"end":105.84,"text":"This means they might earn only a few cents for making a dress which sells for hundreds of euros in Europe.","coverage":1.0},{"start":106.62,"end":109.5,"text":"Such low wages are wrong and unfair.","coverage":1.0},{"start":109.5,"end":111.4,"text":"As Priya Kapoor,","coverage":1.0},{"start":111.84,"end":114.5,"text":"a human rights researcher in Delhi says,","coverage":1.0},{"start":130.16,"end":137.42,"text":"Supporters of outsourcing also claim that overseas factories have become safer and more ethical in recent years.","coverage":1.0},{"start":137.42,"end":142.4,"text":"Some factories in China now provide centers for their workers, for instance.","coverage":1.0},{"start":143.6,"end":148.82,"text":"But working conditions in many offshore factories remain uncomfortable and unsafe.","coverage":1.0},{"start":149.72,"end":152.52,"text":"Worker protection laws, like those in developed nations,","coverage":1.0},{"start":153.0,"end":155.46,"text":"often don't exist or are not followed.","coverage":1.0},{"start":156.18,"end":156.96,"text":"As a result,","coverage":1.0},{"start":157.46,"end":159.54,"text":"workers are exposed to chemicals,","coverage":1.0},{"start":159.94,"end":160.3,"text":"dust,","coverage":1.0},{"start":160.64,"end":163.42,"text":"and unsafe levels of noise from sewing machines.","coverage":1.0},{"start":164.22,"end":169.28,"text":"I saw this myself when I visited a clothing factory in Bangladesh in 2020.","coverage":1.0},{"start":170.28,"end":173.68,"text":"The noise was so loud that I had to cover my ears.","coverage":1.0},{"start":174.42,"end":175.1,"text":"Moreover,","coverage":1.0},{"start":175.66,"end":179.64,"text":"factory buildings are often unsafe and horrible accidents happen.","coverage":1.0},{"start":180.38,"end":181.1,"text":"For example,","coverage":1.0},{"start":181.46,"end":188.34,"text":"the whole world was shocked in 2012 when a fire broke out at a garment factory in Dhaka, Bangladesh,","coverage":1.0},{"start":188.76,"end":192.64,"text":"killing 117 people and injuring 200.","coverage":1.0},{"start":193.8,"end":194.7,"text":"In conclusion,","coverage":1.0},{"start":195.24,"end":199.12,"text":"although supporters of outsourcing provide a number of convincing arguments,","coverage":1.0},{"start":199.6,"end":207.12,"text":"in my opinion, these do not justify the low wages and dangerous conditions found in many overseas factories.","coverage":1.0},{"start":207.78,"end":214.28,"text":"If multinationals are going to continue to benefit from low production costs by using overseas suppliers,","coverage":1.0},{"start":214.66,"end":225.2,"text":"I believe they should contribute a much larger share of their massive profits to correcting these problems and improving social conditions in the countries where they are located.","coverage":1.0}],"file":"dc20285683f6a8791c35.js","track":0,"media":"../assets/media/7401b6f3eb4703a4136579d0274cc6632d512a66a3b2fc0c25412baf2a411e5b.mp3"}],"../assets/media/29189f22a5fca65b8fe5d20d22fb2a4cb498020520091f4cd316451425ae7259.mp3":[{"id":"PPT_29189f22a5fca65b","audioId":"PPT_29189f22a5fca65b","title":"Book 3 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 48","duration":291.37,"cues":[{"start":0.0,"end":1.3,"text":"Unit six,","coverage":1.0},{"start":1.72,"end":3.4,"text":"six .one","coverage":1.0},{"start":3.4,"end":6.68,"text":"Welcome to the Museum of Science.","coverage":1.0},{"start":7.36,"end":13.42,"text":"The exhibition that we're about to see is called Discovering Medieval Science.","coverage":1.0},{"start":14.14,"end":20.06,"text":"As some of you may know, the Middle Ages have often been called the Dark Ages.","coverage":1.0},{"start":20.92,"end":22.26,"text":"During this tour,","coverage":1.0},{"start":22.62,"end":25.56,"text":"you will find out that they were not.","coverage":1.0},{"start":25.56,"end":33.52,"text":"The Middle Ages were an interesting time and they were full of scientific discoveries.","coverage":1.0},{"start":34.92,"end":36.02,"text":"During this time,","coverage":1.0},{"start":36.68,"end":39.52,"text":"inventions and technology from India,","coverage":1.0},{"start":40.04,"end":40.56,"text":"China,","coverage":1.0},{"start":41.32,"end":45.62,"text":"North Africa and the Middle East were brought to Europe.","coverage":1.0},{"start":46.94,"end":58.02,"text":"Inventions and machines designed by medieval scholars made a great contribution to society and many are still in use today.","coverage":1.0},{"start":58.8,"end":62.42,"text":"And some of these inventions are very common.","coverage":1.0},{"start":63.22,"end":70.6,"text":"For example, the first fountain pen was made in 953 in Africa.","coverage":1.0},{"start":71.66,"end":76.86,"text":"Before then, people used bird feathers and ink to write with.","coverage":1.0},{"start":77.8,"end":83.78,"text":"This method would often leave your fingers and clothes covered with black ink.","coverage":1.0},{"start":83.78,"end":97.14,"text":"So the first fountain pen had a small container with ink inside and did not stain people's clothes or fingers while the user was writing.","coverage":1.0},{"start":98.46,"end":103.8,"text":"You can see a model of this fountain pen in room 11b.","coverage":1.0},{"start":104.16,"end":108.5,"text":"In the same room, you'll find early examples of glasses.","coverage":1.0},{"start":108.5,"end":113.8,"text":"Glasses were invented in Italy in the 13th century.","coverage":1.0},{"start":114.62,"end":114.71,"text":"No","coverage":1.0},{"start":114.71,"end":117.04,"text":"one knows who invented them.","coverage":1.0},{"start":117.58,"end":123.26,"text":"The first glasses were held in front of the eyes or balanced on the nose.","coverage":1.0},{"start":124.3,"end":128.28,"text":"They were developed to help people with bad vision to read.","coverage":1.0},{"start":129.26,"end":133.18,"text":"But let's now move on to some other inventions.","coverage":1.0},{"start":134.06,"end":137.5,"text":"In rooms 12a and 12b,","coverage":1.0},{"start":137.84,"end":143.0,"text":"we have works by the great medieval engineer Al -Jazari.","coverage":1.0},{"start":143.98,"end":147.66,"text":"Al -Jazari lived in 12th century Turkey.","coverage":1.0},{"start":148.42,"end":162.48,"text":"His work, The Book of Knowledge of Ingenious Mechanical Devices, lists 100 different machines with instructions and diagrams explaining how to build them.","coverage":1.0},{"start":163.54,"end":164.48,"text":"In this exhibition,","coverage":1.0},{"start":164.88,"end":170.14,"text":"you can see models of some of the devices which were designed by Al -Jazari.","coverage":1.0},{"start":171.14,"end":174.36,"text":"Here you can see his mechanical clocks.","coverage":1.0},{"start":175.5,"end":179.28,"text":"Water and weights make the clocks work.","coverage":1.0},{"start":179.28,"end":184.78,"text":"However, his most important invention was the crankshaft.","coverage":1.0},{"start":185.74,"end":192.1,"text":"The crankshaft is a long arm which allows machines to move in a straight line.","coverage":1.0},{"start":193.02,"end":198.12,"text":"It was first used for watering gardens and fields on farms.","coverage":1.0},{"start":199.12,"end":200.56,"text":"In more modern times,","coverage":1.0},{"start":200.92,"end":203.94,"text":"a crankshaft is used in car engines.","coverage":1.0},{"start":205.02,"end":211.48,"text":"As we move along, you'll find one of the most important inventions of medieval times.","coverage":1.0},{"start":212.42,"end":219.1,"text":"This invention has changed the history of the world in ways that we can't even imagine.","coverage":1.0},{"start":220.18,"end":224.44,"text":"It's one of the four great inventions of Chinese culture,","coverage":1.0},{"start":225.24,"end":226.38,"text":"gunpowder.","coverage":1.0},{"start":226.38,"end":238.28,"text":"Gunpowder was invented in the 9th century by Chinese scientists who were trying to create a powder which would make you live forever.","coverage":1.0},{"start":239.36,"end":242.16,"text":"They weren't successful, of course,","coverage":1.0},{"start":242.5,"end":247.88,"text":"but their attempts led to the invention of fireworks and weapons.","coverage":1.0},{"start":248.82,"end":257.84,"text":"The first instructions on how to make gunpowder were written in the 11th century by Zeng Gongliang,","coverage":1.0},{"start":258.22,"end":260.84,"text":"Ding Du and Yang Wei De.","coverage":1.0},{"start":262.04,"end":266.96,"text":"The invention of gunpowder has changed the way we fight wars.","coverage":1.0},{"start":267.9,"end":275.22,"text":"It changed the outcome of many medieval battles and affected the history of the world.","coverage":1.0},{"start":275.22,"end":282.68,"text":"Many people think gunpowder is the most important invention in history.","coverage":1.0},{"start":284.28,"end":289.4,"text":"Now, let's move to the next room, which is all about medieval medicine.","coverage":1.0}],"file":"defa4479b8b5e4663a14.js","track":0,"media":"../assets/media/29189f22a5fca65b8fe5d20d22fb2a4cb498020520091f4cd316451425ae7259.mp3"}],"../assets/media/eff208e63dc6420e0c81a1901276835098012c6c69d4b46a182dfa35ebc163c0.mp3":[{"id":"B3_U02_T2.4_SHORT_S01_v01","audioId":"B3_U02_T2.4_SHORT_S01_v01","title":"Book 3 · Unit 2 · H1 · 听力材料 5","subtitle":"H1 · 2.4-S01","duration":33.881882,"cues":[{"start":2.61,"end":8.47,"text":"Host: Welcome to today’s debate on the advantages and disadvantages of nuclear energy.","coverage":0.929},{"start":9.09,"end":17.88,"text":"Some people think that nuclear power is an environmentally friendly source of energy because it creates less pollution than traditional power plants.","coverage":1.0},{"start":18.37,"end":24.59,"text":"However, the opponents of nuclear energy believe that it has more dangers than benefits.","coverage":1.0},{"start":25.55,"end":28.92,"text":"Debating this issue today are Emma Martinez and Jack Sullivan.","coverage":0.9},{"start":29.53,"end":33.24,"text":"Thank you for joining us today to share your opinions about this important issue.","coverage":1.0}],"file":"e11b06ddb357f500aeaf.js","track":4,"media":"../assets/media/eff208e63dc6420e0c81a1901276835098012c6c69d4b46a182dfa35ebc163c0.mp3"}],"../assets/media/0b0a0f7cb6c818009fb1e42514698d0eb59bc8088517ec94f08e5174e501ac56.mp3":[{"id":"PPT_0b0a0f7cb6c81800","audioId":"PPT_0b0a0f7cb6c81800","title":"Book 2 · Unit 5 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 175","duration":34.17,"cues":[{"start":0.0,"end":1.92,"text":"five .six","coverage":1.0},{"start":3.54,"end":4.38,"text":"one.","coverage":1.0},{"start":5.52,"end":11.6,"text":"I think there is definitely more marketing and business in sport than ever before.","coverage":1.0},{"start":13.9,"end":14.74,"text":"two.","coverage":1.0},{"start":15.92,"end":16.54,"text":"And actually,","coverage":1.0},{"start":16.92,"end":22.8,"text":"only about five % of Olympic athletes get money from big companies to be in adverts.","coverage":1.0},{"start":25.16,"end":25.88,"text":"three.","coverage":1.0},{"start":27.26,"end":32.34,"text":"And of course, the countries with lots of money can train their athletes very well.","coverage":1.0}],"file":"e35974f9fc4cda6f3950.js","track":0,"media":"../assets/media/0b0a0f7cb6c818009fb1e42514698d0eb59bc8088517ec94f08e5174e501ac56.mp3"}],"../assets/media/49f917b8d58a04c81c32253d0517fe3e284930b277e6f04e2cc9eb85451c7a59.wav":[{"id":"B3_U03_T3.3_LONG_L02_v01","audioId":"B3_U03_T3.3_LONG_L02_v01","title":"Book 3 · Unit 3 · H3 · 听力材料 2","subtitle":"H3 · 3.3-L02","duration":74.6735827664399,"cues":[{"start":0.37,"end":3.9,"text":"Host: What other factors influence how well traffic flows?","coverage":0.889},{"start":4.77,"end":12.07,"text":"Mark: Well, a crash on a busy city centre road can have a huge impact on all the other roads close by.","coverage":0.909},{"start":12.58,"end":24.13,"text":"Or someone parking their vehicle so that it blocks the traffic, even if only for a minute or so – a delivery driver, for example – can cause trouble for everyone behind them.","coverage":1.0},{"start":24.72,"end":30.47,"text":"Even something small like that means everyone’s journey suddenly becomes more difficult than they expected.","coverage":1.0},{"start":30.68,"end":34.44,"text":"It’s the most annoying thing in the world!","coverage":1.0},{"start":35.25,"end":37.83,"text":"Host: Should we blame car drivers for all this, then?","coverage":0.9},{"start":38.16,"end":40.35,"text":"Mark: It’s not always their fault.","coverage":0.857},{"start":41.07,"end":45.4,"text":"Traditional traffic signals in so many of our cities are years old now.","coverage":1.0},{"start":46.0,"end":49.05,"text":"They always change colour after a certain number of seconds.","coverage":0.9},{"start":49.7,"end":55.03,"text":"That’s not a sensible idea, when we consider the number of vehicles driving today.","coverage":1.0},{"start":55.36,"end":63.4,"text":"For instance, a driver might see a green light and continue, but immediately join a long queue of vehicles that isn’t moving.","coverage":0.957},{"start":64.12,"end":69.7,"text":"Then, when the lights turn back to red, they are parked across a busy junction.","coverage":1.0},{"start":70.0,"end":72.63,"text":"That usually leads to all sorts of delays over the day.","coverage":1.0}],"file":"e3cb6571ef08ad217eba.js","track":1,"media":"../assets/media/49f917b8d58a04c81c32253d0517fe3e284930b277e6f04e2cc9eb85451c7a59.wav"}],"../assets/media/b0f9ac43d4f5a27556fcdff240f8c322ef7001be352da17302a5872da0c867f5.wav":[{"id":"B3_U03_T3.4_LONG_L01_v01","audioId":"B3_U03_T3.4_LONG_L01_v01","title":"Book 3 · Unit 3 · H3 · 听力材料 3","subtitle":"H3 · 3.4-L01","duration":118.71092970521542,"cues":[{"start":0.48,"end":7.0,"text":"Which reminds me of another way to reduce traffic – businesses replacing their vehicles with drones.","coverage":0.933},{"start":7.84,"end":7.97,"text":"Host: Okay.","coverage":0.5},{"start":8.52,"end":9.65,"text":"Tell me more.","coverage":1.0},{"start":10.0,"end":20.73,"text":"Mark: Some tasks city governments need to do, such as checking electricity lines, don’t necessarily need to be carried out by a single person arriving in a big vehicle.","coverage":0.967},{"start":21.0,"end":28.67,"text":"A drone with a camera could send this information to engineers, who only need to go out if there is a problem.","coverage":1.0},{"start":29.0,"end":33.0,"text":"Think of how many work vans this could take off the roads every day ...","coverage":0.929},{"start":33.0,"end":35.07,"text":"Host: And delivery vans ...","coverage":0.75},{"start":35.5,"end":37.7,"text":"Mark: That’s another good example.","coverage":0.833},{"start":38.0,"end":44.7,"text":"In some cities, businesses can use drones to deliver small parcels, which is fantastic.","coverage":1.0},{"start":45.0,"end":47.67,"text":"It means even fewer vehicles on the roads.","coverage":1.0},{"start":48.0,"end":52.62,"text":"Host: What would you say to people who refuse to give up driving their cars, ever?","coverage":0.938},{"start":53.0,"end":58.0,"text":"Mark: I honestly think people should try to avoid driving as much as possible.","coverage":0.929},{"start":58.0,"end":61.08,"text":"But, if they can’t, they should consider their behaviour.","coverage":0.9},{"start":62.0,"end":64.76,"text":"It’s not just bad parking that causes traffic issues.","coverage":1.0},{"start":65.54,"end":68.36,"text":"Everyone needs to be a lot more responsible as drivers.","coverage":1.0},{"start":69.0,"end":70.49,"text":"Host: In what way?","coverage":0.75},{"start":71.0,"end":75.73,"text":"Mark: When people get behind the steering wheel, they often become less helpful than normal.","coverage":0.933},{"start":76.0,"end":84.71,"text":"Like when someone is turning into a side street – that often means driving across the other lane, past vehicles going in the opposite direction.","coverage":1.0},{"start":85.0,"end":91.74,"text":"If no one slows down to let in the person who wants to turn, the traffic gets worse and worse behind them.","coverage":1.0},{"start":92.0,"end":99.75,"text":"Even more so if someone stops in traffic with their car across the side street that person wants to turn into.","coverage":1.0},{"start":100.782,"end":101.102,"text":"Host: Agh!"},{"start":101.682,"end":105.71,"text":"Listeners, if that doesn’t annoy you as well, you’re a better person than me!","coverage":1.0},{"start":106.5,"end":107.25,"text":"Mark: Me too.","coverage":0.667},{"start":108.0,"end":112.73,"text":"Please, everyone, stop and give people enough space to turn into side streets!","coverage":1.0},{"start":113.44,"end":115.64,"text":"Host: Mark, thanks for joining me.","coverage":0.833},{"start":116.45,"end":116.72,"text":"Mark: Thank you.","coverage":0.667}],"file":"e3cb6571ef08ad217eba.js","track":2,"media":"../assets/media/b0f9ac43d4f5a27556fcdff240f8c322ef7001be352da17302a5872da0c867f5.wav"}],"../assets/media/6ea4033e912e01a5c91006e8e561869675b25722bef2e3a5ea61654bddeee4b3.mp3":[{"id":"PPT_6ea4033e912e01a5","audioId":"PPT_6ea4033e912e01a5","title":"Book 2 · Unit 4 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 30","duration":47.73,"cues":[{"start":0.0,"end":1.28,"text":"Unit four,","coverage":1.0},{"start":1.8,"end":3.0,"text":"four .one","coverage":1.0},{"start":4.58,"end":5.46,"text":"one.","coverage":1.0},{"start":6.64,"end":9.7,"text":"Did you know the number of trees in the world is increasing?","coverage":1.0},{"start":10.5,"end":11.36,"text":"Is it?","coverage":1.0},{"start":12.9,"end":13.78,"text":"two.","coverage":1.0},{"start":14.8,"end":17.06,"text":"I got a better job last week.","coverage":1.0},{"start":17.94,"end":18.46,"text":"Really?","coverage":1.0},{"start":18.94,"end":19.82,"text":"Congratulations!","coverage":1.0},{"start":22.12,"end":23.0,"text":"three.","coverage":1.0},{"start":23.92,"end":26.54,"text":"The weather got really cold, didn't it?","coverage":1.0},{"start":27.3,"end":28.52,"text":"I suppose so.","coverage":1.0},{"start":30.28,"end":31.08,"text":"four.","coverage":1.0},{"start":32.46,"end":34.4,"text":"Thanks for inviting me to your party.","coverage":1.0},{"start":35.46,"end":36.24,"text":"You're welcome.","coverage":1.0},{"start":36.76,"end":38.96,"text":"It'll be nice to see you.","coverage":1.0},{"start":40.34,"end":41.14,"text":"five.","coverage":1.0},{"start":42.12,"end":43.28,"text":"Dinner was great.","coverage":1.0},{"start":44.14,"end":44.56,"text":"Good.","coverage":1.0},{"start":44.78,"end":46.0,"text":"Glad you liked it.","coverage":1.0}],"file":"e5b58a3dd1f7f04a9141.js","track":0,"media":"../assets/media/6ea4033e912e01a5c91006e8e561869675b25722bef2e3a5ea61654bddeee4b3.mp3"}],"../assets/media/8f834fa463c45d4ba2c5a0b599f5bffec002992c41ebff9faa68aa6f7db6954d.mp3":[{"id":"PPT_8f834fa463c45d4b","audioId":"PPT_8f834fa463c45d4b","title":"Book 3 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 58","duration":72.25,"cues":[{"start":0.0,"end":2.06,"text":"eight .three","coverage":1.0},{"start":2.06,"end":3.16,"text":"one","coverage":1.0},{"start":4.0,"end":8.56,"text":"Most people think that rich people live lavish lifestyles,","coverage":1.0},{"start":8.96,"end":11.9,"text":"that is, they drive very expensive cars,","coverage":1.0},{"start":12.28,"end":14.1,"text":"eat in expensive restaurants,","coverage":1.0},{"start":14.76,"end":17.24,"text":"own a yacht or live in big houses.","coverage":1.0},{"start":19.72,"end":22.78,"text":"two In other words,","coverage":1.0},{"start":23.1,"end":27.9,"text":"having expensive things is not always a sign that someone is rich.","coverage":1.0},{"start":30.26,"end":30.96,"text":"three","coverage":1.0},{"start":31.98,"end":33.58,"text":"On the other hand,","coverage":1.0},{"start":33.98,"end":35.2,"text":"people who look rich,","coverage":1.0},{"start":35.52,"end":39.96,"text":"the people who drive the latest Ferrari or only wear designer clothes,","coverage":1.0},{"start":40.28,"end":43.02,"text":"may not actually be rich at all.","coverage":1.0},{"start":45.5,"end":48.06,"text":"four As a result,","coverage":1.0},{"start":48.38,"end":51.74,"text":"they don't spend too much and they don't get into debt.","coverage":1.0},{"start":54.26,"end":54.96,"text":"five","coverage":1.0},{"start":56.02,"end":56.92,"text":"There is","coverage":1.0},{"start":56.92,"end":57.2,"text":"no","coverage":1.0},{"start":57.2,"end":61.56,"text":"doubt that it's more difficult to save money if you are single.","coverage":1.0},{"start":65.14,"end":67.52,"text":"So what can we learn from the wealthy?","coverage":1.0},{"start":68.24,"end":70.36,"text":"The answer is surprisingly simple.","coverage":1.0}],"file":"e71594adc477ee6468af.js","track":0,"media":"../assets/media/8f834fa463c45d4ba2c5a0b599f5bffec002992c41ebff9faa68aa6f7db6954d.mp3"}],"../assets/media/9396657b71b0a1db602840cb5a11c71ef4e0b698c6efe7d9820cf3803e22647c.mp3":[{"id":"PPT_9396657b71b0a1db","audioId":"PPT_9396657b71b0a1db","title":"Book 3 · Unit 2 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 87","duration":284.58,"cues":[{"start":0.0,"end":1.44,"text":"two .four","coverage":1.0},{"start":1.44,"end":7.82,"text":"Welcome to today's debate on the advantages and disadvantages of nuclear energy.","coverage":1.0},{"start":8.78,"end":17.34,"text":"Some people think that nuclear power is an environmentally friendly source of energy because it creates less pollution than traditional power plants.","coverage":1.0},{"start":18.2,"end":18.66,"text":"However,","coverage":1.0},{"start":19.18,"end":24.14,"text":"the opponents of nuclear energy believe that it has more dangers than benefits.","coverage":1.0},{"start":24.84,"end":28.56,"text":"Debating this issue today are Emma Martinez and Jack Sullivan.","coverage":1.0},{"start":28.56,"end":33.34,"text":"Thank you for joining us today to share your opinions about this important issue.","coverage":1.0},{"start":34.6,"end":35.5,"text":"Thank you.","coverage":1.0},{"start":36.08,"end":40.2,"text":"I want to argue that there are many problems with nuclear power.","coverage":1.0},{"start":40.74,"end":51.66,"text":"It may be true that there are very few accidents caused by nuclear plants, but if there is an accident, then it will be huge and it will have long -term effects on the environment.","coverage":1.0},{"start":52.2,"end":53.16,"text":"For example,","coverage":1.0},{"start":53.62,"end":63.16,"text":"after the Fukushima nuclear disaster in Japan, the government had to tell people to leave their homes because of the possibility of radiation.","coverage":1.0},{"start":63.9,"end":68.84,"text":"The radioactive material spread to water and food, such as tea,","coverage":1.0},{"start":69.2,"end":69.6,"text":"milk,","coverage":1.0},{"start":70.06,"end":70.38,"text":"beef,","coverage":1.0},{"start":70.7,"end":71.4,"text":"and fish.","coverage":1.0},{"start":71.96,"end":76.28,"text":"For months after the accident, the Fukushima plant was dangerous.","coverage":1.0},{"start":76.72,"end":81.78,"text":"People will not be able to live in the nearby area for the next 20 years.","coverage":1.0},{"start":82.4,"end":85.98,"text":"This is the big risk of building a nuclear power plant.","coverage":1.0},{"start":85.98,"end":87.5,"text":"In my opinion,","coverage":1.0},{"start":87.84,"end":93.1,"text":"it's irresponsible for governments to allow nuclear power plants to be built near cities.","coverage":1.0},{"start":93.44,"end":95.38,"text":"They're just too dangerous.","coverage":1.0},{"start":96.18,"end":97.54,"text":"I have to disagree.","coverage":1.0},{"start":97.74,"end":100.46,"text":"I think we should look at the bigger picture.","coverage":1.0},{"start":101.26,"end":105.1,"text":"Some people are worried that nuclear power is a big risk.","coverage":1.0},{"start":105.7,"end":106.3,"text":"And yet,","coverage":1.0},{"start":106.62,"end":115.94,"text":"there are hundreds of nuclear power plants all over the world, and there have only been three major nuclear accidents in the last 30 years.","coverage":1.0},{"start":116.62,"end":117.12,"text":"In fact,","coverage":1.0},{"start":117.7,"end":121.56,"text":"research shows that many more people die while working with coal,","coverage":1.0},{"start":122.0,"end":122.86,"text":"natural gas,","coverage":1.0},{"start":123.34,"end":124.46,"text":"and hydropower,","coverage":1.0},{"start":124.84,"end":125.32,"text":"that is,","coverage":1.0},{"start":125.66,"end":127.06,"text":"electricity powered by water.","coverage":1.0},{"start":128.0,"end":128.96,"text":"On top of that,","coverage":1.0},{"start":129.52,"end":135.1,"text":"nuclear power is the most environmentally friendly and the most sustainable source of energy.","coverage":1.0},{"start":135.1,"end":136.5,"text":"In other words,","coverage":1.0},{"start":136.86,"end":138.6,"text":"it doesn't damage the environment,","coverage":1.0},{"start":139.0,"end":140.82,"text":"and there will always be enough of it.","coverage":1.0},{"start":141.58,"end":144.32,"text":"A nuclear power plant does not pollute the air,","coverage":1.0},{"start":144.72,"end":146.08,"text":"it's relatively cheap,","coverage":1.0},{"start":146.44,"end":150.36,"text":"and it can provide a huge amount of electricity to our cities.","coverage":1.0},{"start":151.06,"end":151.76,"text":"And of course,","coverage":1.0},{"start":152.2,"end":153.58,"text":"our cities are growing.","coverage":1.0},{"start":154.2,"end":155.94,"text":"I'm sorry, can I interrupt?","coverage":1.0},{"start":156.54,"end":162.64,"text":"Some people say that nuclear energy doesn't pollute the air, but that's not completely true.","coverage":1.0},{"start":162.64,"end":166.76,"text":"It takes many years to build a nuclear power plant.","coverage":1.0},{"start":167.18,"end":168.16,"text":"During this time,","coverage":1.0},{"start":168.58,"end":173.1,"text":"hundreds of machines work day and night and pollute the air in the area.","coverage":1.0},{"start":173.66,"end":184.5,"text":"I don't think it's necessary to build nuclear power plants when we have safer and more environmentally friendly energy sources, such as solar and wind energy.","coverage":1.0},{"start":184.88,"end":185.68,"text":"They're cheaper,","coverage":1.0},{"start":186.1,"end":188.28,"text":"and they're unlimited sources of energy.","coverage":1.0},{"start":188.28,"end":193.7,"text":"Also, they're more affordable for most countries when compared with nuclear power.","coverage":1.0},{"start":194.3,"end":199.5,"text":"Building a nuclear power plant is not a solution for low -income countries.","coverage":1.0},{"start":200.16,"end":201.86,"text":"I'm not sure about that.","coverage":1.0},{"start":202.52,"end":208.94,"text":"I think that building nuclear power plants is the perfect solution for many low -income countries.","coverage":1.0},{"start":209.8,"end":220.16,"text":"Yes, it might be expensive to build the plant, but once the nuclear plant is there, the cost of the production of energy is very low.","coverage":1.0},{"start":220.94,"end":221.32,"text":"Plus,","coverage":1.0},{"start":221.76,"end":226.32,"text":"the country can sell the electricity to its neighbors and improve its economy.","coverage":1.0},{"start":227.16,"end":229.3,"text":"It's a long -term solution,","coverage":1.0},{"start":229.76,"end":233.82,"text":"and it makes a country less dependent on oil and gas.","coverage":1.0},{"start":234.56,"end":235.32,"text":"At the moment,","coverage":1.0},{"start":235.76,"end":238.1,"text":"whenever oil or gas prices go up,","coverage":1.0},{"start":238.52,"end":242.08,"text":"it's low -income countries and the people who live in them that suffer.","coverage":1.0},{"start":242.08,"end":248.3,"text":"Some people think that solar and wind energy are greener than nuclear energy,","coverage":1.0},{"start":248.84,"end":250.7,"text":"but I don't think that's accurate.","coverage":1.0},{"start":251.8,"end":254.98,"text":"Wind turbines are not exactly friendly for birds,","coverage":1.0},{"start":255.54,"end":260.26,"text":"not to mention that solar panels and wind turbines take up a lot of space.","coverage":1.0},{"start":260.98,"end":266.7,"text":"They're also very expensive and don't last as long as a nuclear power plant.","coverage":1.0},{"start":266.7,"end":268.36,"text":"In short,","coverage":1.0},{"start":268.96,"end":273.26,"text":"wind and solar energy can't solve the problem of climate change,","coverage":1.0},{"start":273.64,"end":276.86,"text":"and they aren't a good solution for low -income countries.","coverage":1.0},{"start":278.22,"end":280.0,"text":"Thank you both very much.","coverage":1.0},{"start":280.52,"end":282.62,"text":"Let's take some questions from the audience.","coverage":1.0}],"file":"e96d750f38f72eac9be6.js","track":0,"media":"../assets/media/9396657b71b0a1db602840cb5a11c71ef4e0b698c6efe7d9820cf3803e22647c.mp3"}],"../assets/media/cc9cbac62bc4c7af63c45bb53501af61bec2e808d5436d4785d9c568568f4813.wav":[{"id":"B3_U04_T4.2_LONG_L02_v01","audioId":"B3_U04_T4.2_LONG_L02_v01","title":"Book 3 · Unit 4 · H3 · 听力材料 2","subtitle":"H3 · 4.2-L02","duration":81.96024943310658,"cues":[{"start":0.28,"end":1.95,"text":"Host: And do traditions change?","coverage":0.8},{"start":2.55,"end":3.22,"text":"Dr Lee: Absolutely!","coverage":0.333},{"start":3.83,"end":6.76,"text":"Customs and traditions change all the time.","coverage":1.0},{"start":7.51,"end":13.43,"text":"Some traditions die out because our way of life changes, but most traditions adapt.","coverage":1.0},{"start":14.04,"end":18.32,"text":"Host: As I understand it, that’s one of the main points of your latest book.","coverage":0.938},{"start":18.89,"end":18.97,"text":"Dr Lee: Yes.","coverage":0.333},{"start":19.08,"end":25.21,"text":"My book is about the effect of modern technology on traditions around the world.","coverage":1.0},{"start":25.52,"end":34.81,"text":"It’s well known that things such as electricity, the telephone and television have changed our lives significantly.","coverage":1.0},{"start":35.37,"end":41.57,"text":"The introduction of these inventions into our lives has changed many of our customs.","coverage":1.0},{"start":42.22,"end":50.23,"text":"For example, in the past, families spent time playing board games or listening to the radio in the evening.","coverage":1.0},{"start":50.83,"end":54.42,"text":"These activities would deepen family relationships.","coverage":1.0},{"start":55.02,"end":63.03,"text":"Now, due to developments in technology, people spend more time interacting with other people over the internet.","coverage":1.0},{"start":63.54,"end":64.97,"text":"Host: Is that a bad thing?","coverage":0.833},{"start":65.32,"end":66.6,"text":"Dr Lee: I don’t think so.","coverage":0.714},{"start":67.23,"end":72.52,"text":"There are people who complain about the changes that technology has brought to our lives.","coverage":1.0},{"start":72.83,"end":75.62,"text":"Personally, I think these changes are fine.","coverage":1.0},{"start":75.92,"end":81.61,"text":"We still spend time interacting with other people, but it’s not always face to-face.","coverage":1.0}],"file":"e9c74ace1b712fb2a365.js","track":1,"media":"../assets/media/cc9cbac62bc4c7af63c45bb53501af61bec2e808d5436d4785d9c568568f4813.wav"}],"../assets/media/24311c6098a95fb6da5decf9f51cf4132a6e8935c5213a1fe12da298d8018f4f.wav":[{"id":"B3_U04_T4.2_LONG_L03_v01","audioId":"B3_U04_T4.2_LONG_L03_v01","title":"Book 3 · Unit 4 · H3 · 听力材料 3","subtitle":"H3 · 4.2-L03","duration":137.15913832199547,"cues":[{"start":0,"end":5.77,"text":"Host: In your book, you discuss how technology has changed the way we celebrate important holidays.","coverage":0.938},{"start":6.28,"end":6.77,"text":"Dr Lee: That’s right.","coverage":0.6},{"start":7.0,"end":11.0,"text":"A simple example is sending cards or messages.","coverage":1.0},{"start":11.32,"end":20.0,"text":"In the past, people sent each other cards to celebrate important events, like an anniversary or a new baby.","coverage":1.0},{"start":20.25,"end":27.99,"text":"But now, more people send messages through social networking sites or by text or email.","coverage":1.0},{"start":28.34,"end":32.65,"text":"Another example of changing customs is holiday food.","coverage":1.0},{"start":33.0,"end":40.75,"text":"A few generations ago, people spent a lot of time and effort preparing special meals for celebrations.","coverage":1.0},{"start":41.0,"end":43.7,"text":"It was usually the women who did this.","coverage":1.0},{"start":44.33,"end":48.0,"text":"Some dishes could take up to a week to prepare.","coverage":1.0},{"start":48.26,"end":50.67,"text":"But now we don’t have to work so hard.","coverage":1.0},{"start":51.32,"end":55.66,"text":"This is because we have modern kitchens and supermarket food.","coverage":1.0},{"start":56.0,"end":61.0,"text":"We don’t have to spend endless hours making our own butter or bread any more.","coverage":0.875},{"start":62.33,"end":64.7,"text":"Everything is quicker and easier now.","coverage":1.0},{"start":65.0,"end":69.64,"text":"Host: Hmm … I remember my grandmother working for days to make food.","coverage":0.833},{"start":70.21,"end":73.71,"text":"She had a huge cookery book which she got from her grandmother.","coverage":0.917},{"start":74.34,"end":77.7,"text":"Everything had to be exactly as it was when she was a little girl.","coverage":1.0},{"start":78.32,"end":83.6,"text":"Dr Lee: That’s a good example of a tradition which has been replaced by technology.","coverage":0.875},{"start":84.21,"end":86.74,"text":"You can find any recipe you want on the internet.","coverage":1.0},{"start":87.32,"end":91.04,"text":"This means that many people don’t need cookery books any more.","coverage":0.75},{"start":92.34,"end":97.74,"text":"Another thing is that many families now go out instead of cooking at home.","coverage":1.0},{"start":98.0,"end":106.69,"text":"In India, for example, families hire catering companies to provide food for weddings or special occasions.","coverage":1.0},{"start":107.0,"end":119.71,"text":"In the United States, at Thanksgiving, which is one of the biggest celebrations, many families go to restaurants because they don’t want to spend their holiday working in the kitchen.","coverage":1.0},{"start":120.0,"end":125.76,"text":"Host: So people do continue their tradition of eating a special meal – they just do it in a different way.","coverage":0.95},{"start":126.32,"end":126.37,"text":"Dr Lee: Yes.","coverage":0.333},{"start":126.61,"end":135.6,"text":"Traditions don’t always die out – but customs and traditions do change and adapt to the modern world.","coverage":1.0}],"file":"e9c74ace1b712fb2a365.js","track":2,"media":"../assets/media/24311c6098a95fb6da5decf9f51cf4132a6e8935c5213a1fe12da298d8018f4f.wav"}],"../assets/media/b7ed356f35ab91c75f4452b177dc42ea66fa5370cf4b3a2f987f862e5da699f2.mp3":[{"id":"PPT_b7ed356f35ab91c7","audioId":"PPT_b7ed356f35ab91c7","title":"Book 3 · Unit 3 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 193","duration":115.67,"cues":[{"start":0.0,"end":1.52,"text":"three .eight","coverage":1.0},{"start":1.52,"end":4.98,"text":"I'm really surprised by these statistics.","coverage":1.0},{"start":5.54,"end":8.64,"text":"I didn't know that eating while driving is dangerous.","coverage":1.0},{"start":9.46,"end":12.32,"text":"I don't think the government should do anything about it.","coverage":1.0},{"start":12.76,"end":13.18,"text":"Personally,","coverage":1.0},{"start":13.64,"end":18.84,"text":"I eat fast food in my car a few times a week and I've never had an accident.","coverage":1.0},{"start":19.54,"end":23.26,"text":"And I'm not convinced that driving while eating is a big problem.","coverage":1.0},{"start":23.98,"end":25.74,"text":"Have you ever eaten while driving?","coverage":1.0},{"start":25.74,"end":27.5,"text":"No, I haven't.","coverage":1.0},{"start":27.88,"end":30.18,"text":"We should take this really seriously.","coverage":1.0},{"start":30.94,"end":34.48,"text":"I think it would be better if they closed drive -through restaurants.","coverage":1.0},{"start":35.0,"end":40.1,"text":"This is because they only encourage drivers to buy food and eat it while they drive.","coverage":1.0},{"start":40.64,"end":44.84,"text":"How can you focus on the road if you're holding a big burger in your hand?","coverage":1.0},{"start":45.36,"end":47.14,"text":"It seems dangerous to me.","coverage":1.0},{"start":47.6,"end":48.56,"text":"What do you think?","coverage":1.0},{"start":48.88,"end":50.26,"text":"I completely agree.","coverage":1.0},{"start":50.26,"end":55.92,"text":"I think it would be much better if drivers weren't allowed to eat or drink while they drive.","coverage":1.0},{"start":56.52,"end":57.94,"text":"From my own experience,","coverage":1.0},{"start":58.26,"end":60.64,"text":"I can tell you that it can be very dangerous.","coverage":1.0},{"start":61.5,"end":62.16,"text":"Last week,","coverage":1.0},{"start":62.54,"end":65.82,"text":"I bought some coffee and something to eat on the way to work.","coverage":1.0},{"start":66.38,"end":67.28,"text":"As I was driving,","coverage":1.0},{"start":67.6,"end":71.88,"text":"I had to brake suddenly and I spilled hot coffee over my legs.","coverage":1.0},{"start":72.5,"end":74.42,"text":"I almost lost control of the car.","coverage":1.0},{"start":75.06,"end":79.38,"text":"I think the police should give heavy fines if they see someone doing it.","coverage":1.0},{"start":79.38,"end":81.6,"text":"Okay, I understand.","coverage":1.0},{"start":82.28,"end":86.28,"text":"But it might be very difficult for the police to see drivers eating,","coverage":1.0},{"start":86.78,"end":88.76,"text":"especially if they're driving fast.","coverage":1.0},{"start":89.58,"end":94.82,"text":"The best thing would be to have more cameras on the roads to record what drivers are doing.","coverage":1.0},{"start":95.66,"end":100.52,"text":"The reason for this is the police can check the videos to see who's eating,","coverage":1.0},{"start":101.02,"end":102.86,"text":"who's texting and so on.","coverage":1.0},{"start":103.48,"end":110.56,"text":"Then I'd suggest that the police give the drivers points on their licence If the driver has a lot of points,","coverage":1.0},{"start":111.24,"end":113.7,"text":"the police should take their car away for a few months.","coverage":1.0}],"file":"e9ecf81cc0aefefa86ba.js","track":0,"media":"../assets/media/b7ed356f35ab91c75f4452b177dc42ea66fa5370cf4b3a2f987f862e5da699f2.mp3"}],"../assets/media/3bd46e4cfc5b3992c41c0d5c030c4f9dbcd8a71b095b61a30881d7bd6bd0cea1.mp3":[{"id":"PPT_3bd46e4cfc5b3992","audioId":"PPT_3bd46e4cfc5b3992","title":"Book 3 · Unit 6 · RW · READING 1","subtitle":"READING 1 · source slide 36","duration":249.52,"cues":[{"start":0.0,"end":2.3,"text":"The magic of mimicry.","coverage":1.0},{"start":3.6,"end":8.18,"text":"To mimic people means to copy their speech, dress, or behavior.","coverage":1.0},{"start":8.88,"end":9.8,"text":"In contrast,","coverage":1.0},{"start":10.2,"end":11.08,"text":"in science,","coverage":1.0},{"start":11.44,"end":21.1,"text":"mimic means copying ideas from nature or natural processes to prevent or solve problems or to create helpful products.","coverage":1.0},{"start":21.94,"end":28.34,"text":"The influence of this so -called biomimicry can be seen in a huge range of everyday products,","coverage":1.0},{"start":28.76,"end":30.4,"text":"from clothing to cars.","coverage":1.0},{"start":31.84,"end":35.94,"text":"Perhaps the best known example of biomimicry is Velcro.","coverage":1.0},{"start":36.7,"end":42.24,"text":"It was invented in 1941 by a Swiss engineer called George de Mestral.","coverage":1.0},{"start":43.1,"end":43.78,"text":"One day,","coverage":1.0},{"start":44.12,"end":48.22,"text":"Mestral noticed the burdock seeds that stuck to his dog's hair.","coverage":1.0},{"start":49.0,"end":50.18,"text":"Under the microscope,","coverage":1.0},{"start":50.58,"end":57.28,"text":"he discovered that these seeds had hooks on them, so they stuck to loops on clothing or hair.","coverage":1.0},{"start":58.22,"end":62.6,"text":"Mestral copied this idea and created two strips of material,","coverage":1.0},{"start":63.18,"end":67.0,"text":"one with tiny hooks and the other with loose loops.","coverage":1.0},{"start":67.78,"end":69.66,"text":"When he put both strips together,","coverage":1.0},{"start":70.08,"end":71.42,"text":"they stuck like glue.","coverage":1.0},{"start":72.22,"end":72.66,"text":"However,","coverage":1.0},{"start":73.14,"end":74.28,"text":"unlike with glue,","coverage":1.0},{"start":74.7,"end":78.24,"text":"he could peel the strips apart and reattach them.","coverage":1.0},{"start":79.28,"end":88.26,"text":"Velcro was initially unpopular with fashion companies, but after it was used by NASA to stop items from floating in space,","coverage":1.0},{"start":88.72,"end":91.92,"text":"it became popular with children's clothing companies.","coverage":1.0},{"start":92.82,"end":97.64,"text":"Today, it is used to fasten everything from lunch bags to shoes.","coverage":1.0},{"start":99.34,"end":101.76,"text":"Another example comes from the ocean,","coverage":1.0},{"start":102.14,"end":108.16,"text":"where mussels can stick to surfaces even when the water is moving very fast around them.","coverage":1.0},{"start":108.88,"end":114.22,"text":"Mussels produce a very strong adhesive that works in wet conditions.","coverage":1.0},{"start":115.18,"end":123.96,"text":"Scientists were able to copy this material and found that it was three times stronger than other underwater adhesives.","coverage":1.0},{"start":124.74,"end":128.4,"text":"Another advantage is that it will not hurt the environment.","coverage":1.0},{"start":129.82,"end":130.54,"text":"For NASA,","coverage":1.0},{"start":130.96,"end":132.18,"text":"protecting astronauts'","coverage":1.0},{"start":132.64,"end":135.34,"text":"eyes from the sun's rays is very important,","coverage":1.0},{"start":135.73,"end":140.82,"text":"but protecting their eyes from other dangerous radiation is also essential.","coverage":1.0},{"start":141.86,"end":147.32,"text":"Scientists studied how eagles and falcons clearly recognize their prey.","coverage":1.0},{"start":148.04,"end":152.86,"text":"Scientists discovered that the birds have yellow oil in their eyes,","coverage":1.0},{"start":153.38,"end":158.38,"text":"which filters out harmful radiation and allows them to see very clearly.","coverage":1.0},{"start":159.1,"end":160.94,"text":"NASA copied this oil,","coverage":1.0},{"start":161.5,"end":166.28,"text":"and it is now used by astronauts and pilots in eagle -eyes glasses.","coverage":1.0},{"start":167.36,"end":170.34,"text":"In addition to protecting eyes from dangerous rays,","coverage":1.0},{"start":170.88,"end":175.24,"text":"these sunglasses also improve vision in different weather conditions,","coverage":1.0},{"start":175.86,"end":176.74,"text":"such as fog,","coverage":1.0},{"start":177.3,"end":177.64,"text":"sunlight,","coverage":1.0},{"start":178.16,"end":179.86,"text":"or just normal light.","coverage":1.0},{"start":181.24,"end":182.06,"text":"For birds,","coverage":1.0},{"start":182.62,"end":186.02,"text":"cities full of tall glass buildings are a problem.","coverage":1.0},{"start":187.02,"end":189.68,"text":"Spider's webs may be the solution.","coverage":1.0},{"start":190.58,"end":192.58,"text":"Birds cannot see the glass,","coverage":1.0},{"start":193.0,"end":198.0,"text":"so more than a billion of them fly into buildings and die every year.","coverage":1.0},{"start":198.68,"end":199.22,"text":"However,","coverage":1.0},{"start":199.66,"end":201.72,"text":"they can see spider's webs,","coverage":1.0},{"start":202.06,"end":203.76,"text":"and they try to avoid them.","coverage":1.0},{"start":204.54,"end":205.0,"text":"So,","coverage":1.0},{"start":205.4,"end":210.02,"text":"engineers have used this idea in the invention of a new kind of window.","coverage":1.0},{"start":210.88,"end":215.64,"text":"These windows have tiny lines on them that look like spider's webs,","coverage":1.0},{"start":216.44,"end":222.5,"text":"birds can see them, but the lines are so thin that humans cannot see them easily.","coverage":1.0},{"start":223.26,"end":228.7,"text":"It is likely that we will see these bird -friendly windows on more buildings in the future,","coverage":1.0},{"start":229.18,"end":230.26,"text":"and as a result,","coverage":1.0},{"start":230.64,"end":233.14,"text":"a significant drop in bird deaths.","coverage":1.0},{"start":234.6,"end":236.48,"text":"As these examples illustrate,","coverage":1.0},{"start":237.18,"end":241.18,"text":"biomimicry appears to have an unlimited number of applications.","coverage":1.0},{"start":241.18,"end":247.54,"text":"It will be interesting to see which problems nature helps us solve in the future.","coverage":1.0}],"file":"ed4136eba0e349885021.js","track":0,"media":"../assets/media/3bd46e4cfc5b3992c41c0d5c030c4f9dbcd8a71b095b61a30881d7bd6bd0cea1.mp3"}],"../assets/media/bd0a1d9c4a09802bcdc5960cfed17349adecb6e638161613131f7d617b9a3094.mp3":[{"id":"PPT_bd0a1d9c4a09802b","audioId":"PPT_bd0a1d9c4a09802b","title":"Book 2 · Unit 6 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 109","duration":334.52,"cues":[{"start":0.0,"end":2.0,"text":"six .five","coverage":1.0},{"start":2.86,"end":3.26,"text":"Hi","coverage":1.0},{"start":3.26,"end":4.2,"text":"Sam,","coverage":1.0},{"start":4.7,"end":6.0,"text":"good to see you again.","coverage":1.0},{"start":6.26,"end":6.33,"text":"Hello","coverage":1.0},{"start":6.33,"end":7.1,"text":"Joe.","coverage":1.0},{"start":8.04,"end":8.3,"text":"So,","coverage":1.0},{"start":8.94,"end":13.26,"text":"last time we met we talked about your business goals.","coverage":1.0},{"start":13.92,"end":14.9,"text":"Was it useful?","coverage":1.0},{"start":15.58,"end":16.36,"text":"Useful?","coverage":1.0},{"start":16.78,"end":17.98,"text":"Yeah, it was.","coverage":1.0},{"start":18.72,"end":20.52,"text":"You really made me think.","coverage":1.0},{"start":21.18,"end":25.12,"text":"But now I have a lot of stress about losing money.","coverage":1.0},{"start":25.82,"end":25.98,"text":"Oh","coverage":1.0},{"start":25.98,"end":26.46,"text":"yes?","coverage":1.0},{"start":27.04,"end":29.28,"text":"What is making you stressed about that?","coverage":1.0},{"start":29.28,"end":34.26,"text":"Well, I realised how many weaknesses a business can have.","coverage":1.0},{"start":34.92,"end":38.76,"text":"One careless mistake and I could lose a lot of money.","coverage":1.0},{"start":39.62,"end":40.08,"text":"Exactly.","coverage":1.0},{"start":41.06,"end":44.62,"text":"But there are things you think will cause you to lose money?","coverage":1.0},{"start":45.38,"end":49.6,"text":"Well, when we looked at the company's strengths and weaknesses,","coverage":1.0},{"start":50.26,"end":60.6,"text":"we talked about the quality and happiness of my workers, the costs of running the business and reaching new customers to help grow the business.","coverage":1.0},{"start":61.52,"end":65.5,"text":"Each of these areas could be a way to help make money,","coverage":1.0},{"start":65.98,"end":69.94,"text":"or a way to lose money if you don't have a good plan.","coverage":1.0},{"start":70.7,"end":71.12,"text":"Wow,","coverage":1.0},{"start":71.52,"end":72.34,"text":"that's great.","coverage":1.0},{"start":72.94,"end":75.38,"text":"Those are all important to think about.","coverage":1.0},{"start":76.28,"end":77.8,"text":"Is there anything else?","coverage":1.0},{"start":78.44,"end":80.46,"text":"And what else was there?","coverage":1.0},{"start":80.76,"end":81.98,"text":"Oh, of course,","coverage":1.0},{"start":82.68,"end":83.2,"text":"customers.","coverage":1.0},{"start":83.2,"end":84.34,"text":"Well,","coverage":1.0},{"start":84.68,"end":87.22,"text":"that gives us plenty to talk about today.","coverage":1.0},{"start":88.1,"end":88.58,"text":"So,","coverage":1.0},{"start":89.08,"end":92.74,"text":"let's think about what you can do for your employees.","coverage":1.0},{"start":94.3,"end":99.58,"text":"You said that your workers were unhappy and not working hard enough.","coverage":1.0},{"start":100.8,"end":107.04,"text":"Keeping your employees happy will make them more likely to work hard for the business.","coverage":1.0},{"start":107.04,"end":113.78,"text":"Try organising some social events once a month during work hours.","coverage":1.0},{"start":114.4,"end":116.46,"text":"That could be a good first step.","coverage":1.0},{"start":117.8,"end":118.26,"text":"Also,","coverage":1.0},{"start":118.9,"end":122.08,"text":"maybe you should paint the walls a brighter colour.","coverage":1.0},{"start":122.9,"end":128.0,"text":"The office is really dark and people feel like they're in a cave.","coverage":1.0},{"start":128.0,"end":132.5,"text":"Brighter colours can help make people happier,","coverage":1.0},{"start":133.7,"end":137.34,"text":"and happier employees will also work harder.","coverage":1.0},{"start":137.78,"end":138.88,"text":"Oh, okay.","coverage":1.0},{"start":139.4,"end":140.92,"text":"Well, that's good to know.","coverage":1.0},{"start":141.94,"end":144.28,"text":"You also have to cut costs.","coverage":1.0},{"start":145.14,"end":149.5,"text":"You spend far too much money on electricity every month.","coverage":1.0},{"start":149.5,"end":154.98,"text":"Turn off the lights and computers at the end of the workday.","coverage":1.0},{"start":156.32,"end":162.74,"text":"You should also find some cheaper parts for your products, which are still well made.","coverage":1.0},{"start":163.76,"end":165.12,"text":"It's a tough job,","coverage":1.0},{"start":165.46,"end":167.56,"text":"but I can help you find them.","coverage":1.0},{"start":167.94,"end":168.54,"text":"I see.","coverage":1.0},{"start":168.9,"end":170.2,"text":"That would be great.","coverage":1.0},{"start":170.64,"end":174.4,"text":"If you spend less money, you can make a better profit.","coverage":1.0},{"start":174.4,"end":183.8,"text":"You have some excellent adverts, but you mentioned that you are having trouble reaching new customers,","coverage":1.0},{"start":184.84,"end":190.24,"text":"and growing your number of customers is really important for a successful business.","coverage":1.0},{"start":191.26,"end":193.24,"text":"So, if I were you,","coverage":1.0},{"start":193.62,"end":198.08,"text":"I would try adding online sales to get more customers.","coverage":1.0},{"start":198.08,"end":200.66,"text":"Yeah, I like that idea.","coverage":1.0},{"start":201.4,"end":206.1,"text":"I have a website already, but it looks pretty old and messy.","coverage":1.0},{"start":206.92,"end":209.2,"text":"But there are things we can work on.","coverage":1.0},{"start":210.08,"end":212.08,"text":"If you want to sell online,","coverage":1.0},{"start":212.74,"end":217.64,"text":"you should start by making sure that the website doesn't look messy.","coverage":1.0},{"start":218.72,"end":222.0,"text":"If you don't have the skills to make it look neat,","coverage":1.0},{"start":222.68,"end":225.08,"text":"hire a professional web designer.","coverage":1.0},{"start":225.08,"end":227.46,"text":"You want a neat,","coverage":1.0},{"start":227.88,"end":228.76,"text":"clean website.","coverage":1.0},{"start":229.56,"end":232.44,"text":"It isn't something you want to be careless with.","coverage":1.0},{"start":232.78,"end":233.36,"text":"I see.","coverage":1.0},{"start":234.22,"end":238.28,"text":"Well, I would like to have a lot of black on the website.","coverage":1.0},{"start":239.02,"end":243.18,"text":"I think that colour is professional and serious looking.","coverage":1.0},{"start":244.1,"end":245.22,"text":"I understand,","coverage":1.0},{"start":245.96,"end":249.78,"text":"but I think if you want to make the website attractive,","coverage":1.0},{"start":250.14,"end":251.46,"text":"it needs more colour.","coverage":1.0},{"start":251.46,"end":261.52,"text":"More colour could help the design pop out a bit more and prevent customers from leaving the website before buying anything.","coverage":1.0},{"start":262.1,"end":262.5,"text":"Aha,","coverage":1.0},{"start":262.86,"end":264.2,"text":"that's a good idea.","coverage":1.0},{"start":264.96,"end":267.26,"text":"I actually like blue too.","coverage":1.0},{"start":267.78,"end":271.68,"text":"I think someone else told me about colours people prefer,","coverage":1.0},{"start":272.26,"end":273.32,"text":"but I forgot.","coverage":1.0},{"start":273.32,"end":278.76,"text":"Yes, it's easy to forget to think about something as simple as colour.","coverage":1.0},{"start":280.04,"end":285.8,"text":"The web designer you hire might have some good ideas about which colours to use.","coverage":1.0},{"start":286.98,"end":287.38,"text":"So,","coverage":1.0},{"start":288.0,"end":289.42,"text":"for our next meeting,","coverage":1.0},{"start":290.2,"end":294.14,"text":"you should create your website design and bring a plan.","coverage":1.0},{"start":294.86,"end":299.2,"text":"You could think about how it looks as well as what it says.","coverage":1.0},{"start":300.5,"end":302.86,"text":"You don't want it to look...","coverage":1.0},{"start":302.86,"end":303.3,"text":"well,","coverage":1.0},{"start":303.88,"end":308.88,"text":"you would want to be sure it looks well organised and the best it can be.","coverage":1.0},{"start":309.74,"end":312.8,"text":"It should also be really easy to use.","coverage":1.0},{"start":314.1,"end":318.8,"text":"Next time we'll go over your design and see how to make it better.","coverage":1.0},{"start":319.78,"end":328.04,"text":"We will also think about hiring a good web designer to make your website look great and be easy to use.","coverage":1.0},{"start":328.7,"end":329.56,"text":"Okay, great.","coverage":1.0},{"start":330.08,"end":332.58,"text":"I'll do that and bring it in next week.","coverage":1.0}],"file":"ee972a2ae24e6d5c9a27.js","track":0,"media":"../assets/media/bd0a1d9c4a09802bcdc5960cfed17349adecb6e638161613131f7d617b9a3094.mp3"}],"../assets/media/88e42fe186792f3ab40eda3dfb791dc2019d89a8cf7a1f3314ebf7ce7bd0aff7.mp3":[{"id":"PPT_88e42fe186792f3a","audioId":"PPT_88e42fe186792f3a","title":"Book 2 · Unit 2 · RW · READING 2","subtitle":"READING 2 · source slide 78","duration":118.88,"cues":[{"start":0.0,"end":7.04,"text":"Muscat Nights One of the most important festivals in Oman is Muscat Nights.","coverage":1.0},{"start":7.56,"end":12.34,"text":"The festival lasts for about one month and takes place in February every year.","coverage":1.0},{"start":13.1,"end":14.12,"text":"During the festival,","coverage":1.0},{"start":14.5,"end":18.18,"text":"many activities are available for people to take part in.","coverage":1.0},{"start":18.96,"end":20.24,"text":"Large numbers of people,","coverage":1.0},{"start":20.58,"end":23.56,"text":"including local Omanis and visitors to Oman,","coverage":1.0},{"start":24.04,"end":25.3,"text":"go to the different events.","coverage":1.0},{"start":25.3,"end":31.78,"text":"The events are a celebration of both Omani and international history and traditions.","coverage":1.0},{"start":32.82,"end":35.64,"text":"The events happen in different places across the country.","coverage":1.0},{"start":36.44,"end":40.64,"text":"Many businesses show their products for people to look at and buy.","coverage":1.0},{"start":42.1,"end":48.54,"text":"Muscat Nights also includes the very popular Six -Day Tour of Oman Cycle Race.","coverage":1.0},{"start":49.52,"end":52.96,"text":"Professional cyclists from around the world take part in the race.","coverage":1.0},{"start":52.96,"end":61.3,"text":"The race is one ,000 kilometers long and it takes the cyclists up the beautiful Jabal al -Aqdar, the Green Mountain.","coverage":1.0},{"start":62.58,"end":68.06,"text":"Other highlights of Muscat Nights include the chance to experience different food and music.","coverage":1.0},{"start":68.76,"end":69.52,"text":"For example,","coverage":1.0},{"start":69.88,"end":73.66,"text":"you can taste traditional types of food at the Oman Food Festival.","coverage":1.0},{"start":74.62,"end":79.86,"text":"The Muscat Art Festival also offers Arabic music, concerts and plays,","coverage":1.0},{"start":80.38,"end":82.72,"text":"and other entertainment for the whole family.","coverage":1.0},{"start":82.72,"end":88.66,"text":"The Festival of Lights is one of the most popular events at Muscat Nights.","coverage":1.0},{"start":90.08,"end":92.56,"text":"Muscat Nights is an international event,","coverage":1.0},{"start":93.0,"end":97.36,"text":"with people visiting from countries as far away as Brazil and Cuba.","coverage":1.0},{"start":98.46,"end":100.5,"text":"Visitors also arrive from Italy,","coverage":1.0},{"start":100.82,"end":101.3,"text":"India,","coverage":1.0},{"start":101.72,"end":102.12,"text":"Russia,","coverage":1.0},{"start":102.54,"end":103.24,"text":"South Korea,","coverage":1.0},{"start":103.62,"end":104.02,"text":"Spain,","coverage":1.0},{"start":104.5,"end":106.1,"text":"Tunisia and Turkey,","coverage":1.0},{"start":106.46,"end":108.2,"text":"as well as many other countries.","coverage":1.0},{"start":108.2,"end":110.94,"text":"They enjoy the amazing clothes,","coverage":1.0},{"start":111.32,"end":112.78,"text":"food and music.","coverage":1.0},{"start":113.7,"end":116.94,"text":"Some people just enjoy the mix of different cultures.","coverage":1.0}],"file":"f0d09209130e6d846381.js","track":0,"media":"../assets/media/88e42fe186792f3ab40eda3dfb791dc2019d89a8cf7a1f3314ebf7ce7bd0aff7.mp3"}],"../assets/media/37e834aa38c05336da30a1d5f5e94d7f14b7621c1904069ce4ce19c635be06d4.mp3":[{"id":"PPT_37e834aa38c05336","audioId":"PPT_37e834aa38c05336","title":"Book 3 · Unit 5 · RW · READING 1","subtitle":"READING 1 · source slide 50","duration":223.71,"cues":[{"start":0.0,"end":3.64,"text":"How much physical activity do you do in a week?","coverage":1.0},{"start":4.38,"end":6.14,"text":"Are you getting enough exercise?","coverage":1.0},{"start":7.18,"end":10.56,"text":"Regular activity benefits your health in many ways.","coverage":1.0},{"start":11.26,"end":11.98,"text":"For example,","coverage":1.0},{"start":12.52,"end":19.44,"text":"people who exercise regularly are less likely to suffer from many chronic diseases such as heart disease,","coverage":1.0},{"start":19.88,"end":20.96,"text":"type two diabetes,","coverage":1.0},{"start":21.48,"end":21.86,"text":"stroke,","coverage":1.0},{"start":22.28,"end":23.36,"text":"and some cancers.","coverage":1.0},{"start":23.36,"end":33.36,"text":"Experts say adults who exercise for just 150 minutes a week can reduce their risk of serious illness by 50%.","coverage":1.0},{"start":34.22,"end":35.02,"text":"In addition,","coverage":1.0},{"start":35.66,"end":42.36,"text":"regular exercise increases life expectancy and reduces the risk of early death by 30%.","coverage":1.0},{"start":42.94,"end":44.78,"text":"It also improves your mood,","coverage":1.0},{"start":45.16,"end":45.7,"text":"self -esteem,","coverage":1.0},{"start":46.14,"end":47.2,"text":"and sleep quality.","coverage":1.0},{"start":47.98,"end":48.7,"text":"Today,","coverage":1.0},{"start":49.04,"end":57.54,"text":"most adults are much less active than in the past because our jobs are far less physical than the work our grandparents used to do.","coverage":1.0},{"start":58.22,"end":64.6,"text":"In fact, many of us spend seven hours or more just sitting in a chair each day.","coverage":1.0},{"start":65.42,"end":76.78,"text":"This lack of regular physical activity means that people burn fewer calories than in the past, so we need to make an extra effort to use up excess energy.","coverage":1.0},{"start":77.84,"end":79.04,"text":"According to experts,","coverage":1.0},{"start":79.44,"end":84.72,"text":"adults need to do two and a half hours of moderate exercise per week.","coverage":1.0},{"start":85.46,"end":89.08,"text":"This could be fast walking or cycling on a flat road.","coverage":1.0},{"start":89.94,"end":90.58,"text":"In addition,","coverage":1.0},{"start":90.96,"end":96.66,"text":"it is important to do exercises to strengthen muscles two or three times a week.","coverage":1.0},{"start":98.04,"end":100.22,"text":"Exercise can be expensive,","coverage":1.0},{"start":100.62,"end":102.64,"text":"but it doesn't have to be.","coverage":1.0},{"start":102.84,"end":105.9,"text":"Team sports, such as football or basketball,","coverage":1.0},{"start":106.36,"end":111.32,"text":"can be cheap because all the players share the cost of the field or court.","coverage":1.0},{"start":112.34,"end":120.18,"text":"Joining a recreational sports league is usually an inexpensive way of getting exercise and can be very social,","coverage":1.0},{"start":120.78,"end":120.84,"text":"too.","coverage":1.0},{"start":121.42,"end":133.02,"text":"Local leisure centers usually offer squash and badminton at low rates if you book a court at off -peak times, and you may be able to get a reduced -price gym membership,","coverage":1.0},{"start":133.48,"end":133.64,"text":"too.","coverage":1.0},{"start":134.96,"end":139.66,"text":"If you don't want to spend any money at all, try one of the following activities.","coverage":1.0},{"start":140.6,"end":141.6,"text":"Go for a run.","coverage":1.0},{"start":142.08,"end":145.06,"text":"The only equipment you need is a pair of running shoes.","coverage":1.0},{"start":145.06,"end":151.08,"text":"If you take the bus, try getting off one stop early and walking the extra distance.","coverage":1.0},{"start":151.88,"end":152.8,"text":"Go to the park.","coverage":1.0},{"start":153.44,"end":157.68,"text":"Try getting a group of friends or family together for a game of football,","coverage":1.0},{"start":158.28,"end":162.38,"text":"or play the kinds of running games you haven't played since you were a child.","coverage":1.0},{"start":163.22,"end":168.76,"text":"This is a great way to involve the whole family and also help you keep fit.","coverage":1.0},{"start":169.94,"end":170.58,"text":"Alternatively,","coverage":1.0},{"start":171.14,"end":172.7,"text":"if you want to stay at home,","coverage":1.0},{"start":173.02,"end":176.34,"text":"gardening or doing housework are great ways to keep fit,","coverage":1.0},{"start":176.9,"end":181.3,"text":"and you can enjoy the benefit of a nice garden and a tidy house,","coverage":1.0},{"start":183.86,"end":187.76,"text":"Although adults should do two and a half hours of exercise a week,","coverage":1.0},{"start":188.2,"end":191.02,"text":"you don't have to do it all at one time.","coverage":1.0},{"start":191.48,"end":193.86,"text":"Split the time into ten -minute chunks.","coverage":1.0},{"start":193.86,"end":196.84,"text":"If you do ten minutes before work,","coverage":1.0},{"start":197.22,"end":202.44,"text":"ten minutes during your lunch break, and ten minutes after work, five days a week,","coverage":1.0},{"start":202.9,"end":204.3,"text":"you've achieved the target.","coverage":1.0},{"start":205.36,"end":210.7,"text":"You could also go swimming during your lunch hour two or three times a week, and you've done it.","coverage":1.0},{"start":211.46,"end":212.04,"text":"In brief,","coverage":1.0},{"start":212.38,"end":215.08,"text":"there are many easy ways of keeping fit.","coverage":1.0},{"start":215.54,"end":218.5,"text":"If we all recognize the value of doing this,","coverage":1.0},{"start":218.86,"end":221.78,"text":"we will live longer and be healthier.","coverage":1.0}],"file":"f1c2dc279571ba86626c.js","track":0,"media":"../assets/media/37e834aa38c05336da30a1d5f5e94d7f14b7621c1904069ce4ce19c635be06d4.mp3"}],"../assets/media/bb88fe22b873053cb8f2e2143b052134759d5076da825b790651044537abee76.mp3":[{"id":"PPT_bb88fe22b873053c","audioId":"PPT_bb88fe22b873053c","title":"Book 3 · Unit 4 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 51","duration":318.88,"cues":[{"start":0.0,"end":2.22,"text":"four .two","coverage":1.0},{"start":2.22,"end":4.64,"text":"Welcome to this week's book review.","coverage":1.0},{"start":5.28,"end":7.2,"text":"In the studio with me is Dr.","coverage":1.0},{"start":7.34,"end":7.9,"text":"Kevin Lee,","coverage":1.0},{"start":8.3,"end":12.18,"text":"Professor of Anthropology and author of the best -selling book,","coverage":1.0},{"start":12.58,"end":14.84,"text":"Changing Traditions in the Modern World.","coverage":1.0},{"start":15.72,"end":16.38,"text":"First of all,","coverage":1.0},{"start":16.7,"end":21.86,"text":"could you tell us what anthropologists study and what your own area of interest is?","coverage":1.0},{"start":22.34,"end":23.64,"text":"That's a good question.","coverage":1.0},{"start":24.48,"end":28.38,"text":"Anthropology in a general sense is the study of humanity.","coverage":1.0},{"start":29.02,"end":30.9,"text":"I know that's not very exact.","coverage":1.0},{"start":31.44,"end":38.72,"text":"That's why we have many types of anthropology like linguistic anthropology and social anthropology.","coverage":1.0},{"start":39.58,"end":42.6,"text":"My specialty is cultural anthropology.","coverage":1.0},{"start":43.34,"end":50.6,"text":"I study different cultures around the world and how social and political changes affect these cultures.","coverage":1.0},{"start":51.3,"end":54.42,"text":"And when did you first become interested in anthropology?","coverage":1.0},{"start":55.44,"end":57.88,"text":"I grew up in a multicultural home.","coverage":1.0},{"start":58.46,"end":62.14,"text":"My mother is American and my father is Korean.","coverage":1.0},{"start":62.94,"end":66.44,"text":"They were both English teachers, so we traveled a lot.","coverage":1.0},{"start":67.2,"end":69.54,"text":"As a child, I lived in Japan,","coverage":1.0},{"start":69.96,"end":71.44,"text":"Thailand and Egypt.","coverage":1.0},{"start":72.2,"end":75.0,"text":"That's why I decided to study anthropology.","coverage":1.0},{"start":75.84,"end":82.88,"text":"Growing up in different cultures helps you realize that customs and traditions are often local.","coverage":1.0},{"start":83.6,"end":89.32,"text":"Things that are acceptable in one culture can be completely unacceptable in another.","coverage":1.0},{"start":90.38,"end":90.82,"text":"However,","coverage":1.0},{"start":91.44,"end":93.96,"text":"despite some differences between cultures,","coverage":1.0},{"start":94.56,"end":99.74,"text":"I have noticed that there are often more similarities than differences between people.","coverage":1.0},{"start":100.2,"end":101.9,"text":"And do traditions change?","coverage":1.0},{"start":101.9,"end":103.04,"text":"Absolutely.","coverage":1.0},{"start":103.8,"end":106.6,"text":"Customs and traditions change all the time.","coverage":1.0},{"start":107.4,"end":111.0,"text":"Some traditions die out because our way of life changes,","coverage":1.0},{"start":111.52,"end":113.52,"text":"but most traditions adapt.","coverage":1.0},{"start":114.16,"end":118.02,"text":"As I understand it, that's one of the main points of your latest book.","coverage":1.0},{"start":118.78,"end":119.18,"text":"Yes,","coverage":1.0},{"start":119.7,"end":124.86,"text":"my book is about the effect of modern technology on traditions around the world.","coverage":1.0},{"start":125.5,"end":128.96,"text":"It's well known that things such as electricity,","coverage":1.0},{"start":129.58,"end":134.3,"text":"the telephone and television have changed our lives significantly.","coverage":1.0},{"start":135.34,"end":141.02,"text":"The introduction of these inventions into our lives has changed many of our customs.","coverage":1.0},{"start":142.04,"end":142.82,"text":"For example,","coverage":1.0},{"start":143.24,"end":144.2,"text":"in the past,","coverage":1.0},{"start":144.96,"end":149.82,"text":"families spent time playing board games or listening to the radio in the evening.","coverage":1.0},{"start":150.68,"end":153.94,"text":"These activities would deepen family relationships.","coverage":1.0},{"start":153.94,"end":155.06,"text":"Now,","coverage":1.0},{"start":155.46,"end":157.48,"text":"due to developments in technology,","coverage":1.0},{"start":158.14,"end":162.44,"text":"people spend more time interacting with other people over the internet.","coverage":1.0},{"start":163.44,"end":164.5,"text":"Is that a bad thing?","coverage":1.0},{"start":165.22,"end":166.2,"text":"I don't think so.","coverage":1.0},{"start":166.86,"end":171.86,"text":"There are people who complain about the changes that technology has brought to our lives.","coverage":1.0},{"start":172.68,"end":175.12,"text":"Personally, I think these changes are fine.","coverage":1.0},{"start":175.86,"end":181.48,"text":"We still spend time interacting with other people, but it's not always face -to -face.","coverage":1.0},{"start":181.48,"end":187.42,"text":"In your book, you discuss how technology has changed the way we celebrate important holidays.","coverage":1.0},{"start":188.1,"end":188.64,"text":"That's right.","coverage":1.0},{"start":189.22,"end":192.56,"text":"A simple example is sending cards or messages.","coverage":1.0},{"start":193.42,"end":194.24,"text":"In the past,","coverage":1.0},{"start":194.7,"end":201.06,"text":"people sent each other cards to celebrate important events like an anniversary or a new baby.","coverage":1.0},{"start":201.7,"end":202.54,"text":"But now,","coverage":1.0},{"start":202.88,"end":208.88,"text":"more people send messages through social networking sites or by text or email.","coverage":1.0},{"start":209.56,"end":213.86,"text":"Another example of changing customs is holiday food.","coverage":1.0},{"start":214.92,"end":216.66,"text":"A few generations ago,","coverage":1.0},{"start":217.0,"end":222.34,"text":"people spent a lot of time and effort preparing special meals for celebrations.","coverage":1.0},{"start":223.2,"end":225.76,"text":"It was usually the women who did this.","coverage":1.0},{"start":226.44,"end":229.3,"text":"Some dishes could take up to a week to prepare.","coverage":1.0},{"start":229.98,"end":232.76,"text":"But now, we don't have to work so hard.","coverage":1.0},{"start":233.36,"end":237.58,"text":"This is because we have modern kitchens and supermarket food.","coverage":1.0},{"start":238.16,"end":243.24,"text":"We don't have to spend endless hours making our own butter or bread anymore.","coverage":1.0},{"start":244.1,"end":246.64,"text":"Everything is quicker and easier now.","coverage":1.0},{"start":247.22,"end":251.0,"text":"I remember my grandmother working for days to make food.","coverage":1.0},{"start":251.54,"end":255.24,"text":"She had a huge cookery book, which she got from her grandmother.","coverage":1.0},{"start":256.14,"end":259.64,"text":"Everything had to be exactly as it was when she was a little girl.","coverage":1.0},{"start":260.5,"end":264.84,"text":"That's a good example of a tradition which has been replaced by technology.","coverage":1.0},{"start":265.47,"end":268.68,"text":"You can find any recipe you want on the internet.","coverage":1.0},{"start":269.42,"end":273.2,"text":"This means that many people don't need cookery books anymore.","coverage":1.0},{"start":274.2,"end":279.24,"text":"Another thing is that many families now go out instead of cooking at home.","coverage":1.0},{"start":280.16,"end":281.74,"text":"In India, for example,","coverage":1.0},{"start":282.26,"end":288.04,"text":"families hire catering companies to provide food for weddings or special occasions.","coverage":1.0},{"start":288.98,"end":291.26,"text":"In the United States, at Thanksgiving,","coverage":1.0},{"start":291.72,"end":300.9,"text":"which is one of the biggest celebrations, many families go to restaurants because they don't want to spend their holiday working in the kitchen.","coverage":1.0},{"start":301.72,"end":305.04,"text":"So people do continue their tradition of eating a special meal.","coverage":1.0},{"start":305.34,"end":307.38,"text":"They just do it in a different way.","coverage":1.0},{"start":308.1,"end":308.56,"text":"Yes.","coverage":1.0},{"start":309.22,"end":311.28,"text":"Traditions don't always die out.","coverage":1.0},{"start":311.92,"end":316.98,"text":"But customs and traditions do change and adapt to the modern world.","coverage":1.0}],"file":"f3514653106be1256670.js","track":0,"media":"../assets/media/bb88fe22b873053cb8f2e2143b052134759d5076da825b790651044537abee76.mp3"}],"../assets/media/671d4089a6a072f7355440feca30a57ffe5df849d9dd4ef8dfa1da761c33172b.mp3":[{"id":"PPT_671d4089a6a072f7","audioId":"PPT_671d4089a6a072f7","title":"Book 3 · Unit 7 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 61","duration":35.03,"cues":[{"start":0.0,"end":2.26,"text":"seven .four.","coverage":1.0},{"start":2.36,"end":3.04,"text":"one.","coverage":1.0},{"start":4.12,"end":7.86,"text":"She creates interesting, unusual designs of animals.","coverage":1.0},{"start":9.8,"end":10.5,"text":"two.","coverage":1.0},{"start":11.4,"end":13.36,"text":"It's plagiarism, basically.","coverage":1.0},{"start":15.3,"end":16.26,"text":"three.","coverage":1.0},{"start":17.1,"end":20.82,"text":"The companies lifted her works several times since then.","coverage":1.0},{"start":22.42,"end":23.18,"text":"four.","coverage":1.0},{"start":23.54,"end":26.04,"text":"She tried a different approach.","coverage":1.0},{"start":28.1,"end":28.78,"text":"five.","coverage":1.0},{"start":30.04,"end":33.12,"text":"Finally, the company wrote to her offering an apology.","coverage":1.0}],"file":"f368efdcbea6a10f7e1b.js","track":0,"media":"../assets/media/671d4089a6a072f7355440feca30a57ffe5df849d9dd4ef8dfa1da761c33172b.mp3"}],"../assets/media/db30ca02e3e72a3c12b154cf351b6fc7245ec25f58c31301a3f94b2c003d0d01.mp3":[{"id":"B3_U08_T8.2_SHORT_S05_v01","audioId":"B3_U08_T8.2_SHORT_S05_v01","title":"Book 3 · Unit 8 · H1 · 听力材料 6","subtitle":"H1 · 8.2-S05","duration":35.655556,"cues":[{"start":0,"end":2.77,"text":"So, what can we learn from the wealthy?","coverage":1.0},{"start":3.82,"end":6.28,"text":"The answer is surprisingly simple.","coverage":1.0},{"start":6.71,"end":9.33,"text":"Don’t spend more money than you have.","coverage":1.0},{"start":9.56,"end":12.72,"text":"Don’t get into debt or take out bank loans.","coverage":1.0},{"start":12.91,"end":21.07,"text":"Pay close attention to your money and don’t spend time trying to show other people that you’re rich.","coverage":1.0},{"start":21.42,"end":25.38,"text":"In John Holm’s opinion, being ‘wealthy’ is a feeling.","coverage":0.8},{"start":25.62,"end":29.97,"text":"That is, it doesn’t mean being rich or having millions.","coverage":1.0},{"start":30.18,"end":33.61,"text":"It means being happy with what you have.","coverage":1.0}],"file":"f37e08d229688a2f1d9d.js","track":5,"media":"../assets/media/db30ca02e3e72a3c12b154cf351b6fc7245ec25f58c31301a3f94b2c003d0d01.mp3"}],"../assets/media/fa3bf95edfbe6dfe84b819189499765240409b608784eb9b8fd96ae2b421aac7.mp3":[{"id":"B3_U08_T8.5_SHORT_S04_v01","audioId":"B3_U08_T8.5_SHORT_S04_v01","title":"Book 3 · Unit 8 · H1 · 听力材料 10","subtitle":"H1 · 8.5-S04","duration":50.116984,"cues":[{"start":0.4,"end":4.45,"text":"Host: Christine Thorne is a parent with two children at university.","coverage":0.818},{"start":5.4,"end":5.61,"text":"Mrs Thorne: Hello.","coverage":0.333},{"start":6.02,"end":9.53,"text":"I was very worried when I heard about this new programme.","coverage":1.0},{"start":10.0,"end":17.57,"text":"I realize that students need encouragement to stay at university, but are we going in the right direction?","coverage":0.944},{"start":18.4,"end":22.53,"text":"First of all, I feel that we’re sending the students the wrong message.","coverage":1.0},{"start":23.4,"end":27.44,"text":"Learning should be about studying new things and being responsible.","coverage":1.0},{"start":28.4,"end":39.61,"text":"Personally, I think the students who aren’t interested in studying will simply take the easy courses to keep their average grade high and get the cash.","coverage":1.0},{"start":40.0,"end":49.59,"text":"I believe that we should focus more on rewarding excellent universities and teachers and not on students who might be lazy.","coverage":1.0}],"file":"f37e08d229688a2f1d9d.js","track":9,"media":"../assets/media/fa3bf95edfbe6dfe84b819189499765240409b608784eb9b8fd96ae2b421aac7.mp3"}],"../assets/media/b79dcf3754cc48196125e60d31cc6d00ec2ee773f81f37b78bc50c90d625cd24.mp3":[{"id":"PPT_b79dcf3754cc4819","audioId":"PPT_b79dcf3754cc4819","title":"Book 2 · Unit 7 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 108","duration":26.8,"cues":[{"start":0.0,"end":2.32,"text":"seven .three","coverage":1.0},{"start":3.56,"end":4.44,"text":"one","coverage":1.0},{"start":5.04,"end":7.3,"text":"I'm pretty happy with it.","coverage":1.0},{"start":9.44,"end":10.14,"text":"two","coverage":1.0},{"start":11.02,"end":13.14,"text":"She's a remarkable woman.","coverage":1.0},{"start":15.44,"end":16.38,"text":"three","coverage":1.0},{"start":17.46,"end":18.96,"text":"That's amazing.","coverage":1.0},{"start":21.6,"end":22.46,"text":"four","coverage":1.0},{"start":23.34,"end":24.96,"text":"I'll check him out.","coverage":1.0}],"file":"f49e4045e560ffe3eae2.js","track":0,"media":"../assets/media/b79dcf3754cc48196125e60d31cc6d00ec2ee773f81f37b78bc50c90d625cd24.mp3"}],"../assets/media/980d94837392db9ba02c0b190f2b981a0b13f802fc3245a39e2bfe944e22f717.wav":[{"id":"B3_U01_T1.1_LONG_L02_v01","audioId":"B3_U01_T1.1_LONG_L02_v01","title":"Book 3 · Unit 1 · H3 · 听力材料 2","subtitle":"H3 · 1.1-L02","duration":95.05891156462584,"cues":[{"start":0.44,"end":1.92,"text":"Host: Thank you, Ms Johnson.","coverage":0.8},{"start":2.54,"end":5.38,"text":"Dr Kuryan – your introduction, please.","coverage":0.8},{"start":6.41,"end":6.99,"text":"Dr Kuryan: Thank you.","coverage":0.5},{"start":7.44,"end":12.27,"text":"It’s true that animals have helped our civilization develop.","coverage":1.0},{"start":13.29,"end":17.3,"text":"Camels and horses helped us carry goods across huge distances.","coverage":0.9},{"start":17.66,"end":21.92,"text":"Dogs helped us hunt and protected us from wild animals.","coverage":1.0},{"start":22.5,"end":26.34,"text":"Humans don’t have the skills or strength to do these jobs.","coverage":1.0},{"start":26.88,"end":32.44,"text":"I want to argue that, in many low-income countries, people still need animals to survive.","coverage":1.0},{"start":33.24,"end":38.62,"text":"These are people who can’t afford cars, house alarms or expensive machines.","coverage":1.0},{"start":39.69,"end":43.32,"text":"Another point is that not all animal use is abuse.","coverage":1.0},{"start":43.68,"end":49.66,"text":"On the contrary, without humans, these domesticated animals would not have been able to survive.","coverage":0.933},{"start":50.18,"end":51.69,"text":"They need us to take care of them.","coverage":1.0},{"start":51.95,"end":58.11,"text":"There are many animal lovers around the world who work in animal shelters and help animals.","coverage":1.0},{"start":58.38,"end":61.52,"text":"There are laws that stop animal suffering.","coverage":1.0},{"start":61.8,"end":68.54,"text":"And people give a lot of money to animal charities and organizations that help save wildlife.","coverage":1.0},{"start":69.34,"end":75.59,"text":"At the same time, there are still millions of children in the world who don’t get this kind of treatment.","coverage":1.0},{"start":75.96,"end":78.59,"text":"They go without food or clothing.","coverage":1.0},{"start":78.88,"end":88.1,"text":"I strongly believe that, in a modern society, people often care more about animals than they do about people in low-income countries.","coverage":1.0},{"start":88.44,"end":90.51,"text":"Host: Thank you both for your arguments!","coverage":0.857},{"start":91.06,"end":92.96,"text":"Now, let’s hear from our listeners …","coverage":1.0}],"file":"fb3a2666601f1cc1f0cc.js","track":1,"media":"../assets/media/980d94837392db9ba02c0b190f2b981a0b13f802fc3245a39e2bfe944e22f717.wav"}],"../assets/media/bb2ee972602fba192ba71e0f223ca93908f793cf6c384478ff18589eda695410.mp3":[{"id":"PPT_bb2ee972602fba19","audioId":"PPT_bb2ee972602fba19","title":"Book 3 · Unit 7 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 253","duration":50.23,"cues":[{"start":0.0,"end":1.84,"text":"seven .five","coverage":1.0},{"start":1.84,"end":8.42,"text":"In today's show we'll be interviewing the talented fashion designer Aisha Al -Husseini.","coverage":1.0},{"start":8.92,"end":11.22,"text":"Hot on the heels of her Fashion Week show,","coverage":1.0},{"start":11.56,"end":14.58,"text":"Aisha's new collection is very popular in Doha.","coverage":1.0},{"start":15.22,"end":18.76,"text":"She got the attention of the fashion world with her unique designs,","coverage":1.0},{"start":19.3,"end":22.92,"text":"which combine traditional Muslim fashion with French chic.","coverage":1.0},{"start":23.52,"end":25.64,"text":"Aisha, thank you for coming to the studio.","coverage":1.0},{"start":25.82,"end":26.94,"text":"Thank you for having me.","coverage":1.0},{"start":26.94,"end":28.18,"text":"First of all,","coverage":1.0},{"start":28.54,"end":30.98,"text":"can you tell me where you get your ideas from?","coverage":1.0},{"start":31.48,"end":33.52,"text":"Well, I come from a Muslim family.","coverage":1.0},{"start":34.04,"end":36.02,"text":"My parents are both from Qatar.","coverage":1.0},{"start":36.54,"end":39.18,"text":"I was born there but then we travelled a lot.","coverage":1.0},{"start":39.72,"end":43.32,"text":"I went to school in New York and I went to a design school there.","coverage":1.0},{"start":43.96,"end":48.34,"text":"These days I spend my time travelling between Qatar and the United States.","coverage":1.0}],"file":"fbc1aef906a890d9c8d8.js","track":0,"media":"../assets/media/bb2ee972602fba192ba71e0f223ca93908f793cf6c384478ff18589eda695410.mp3"}],"../assets/media/e5869727902f1de10d6c2d9a82884b6b9a00cc0090f97628a3a2d3eceffcdd29.mp3":[{"id":"PPT_e5869727902f1de1","audioId":"PPT_e5869727902f1de1","title":"Book 3 · Unit 3 · LS · LANGUAGE DEVELOPMENT","subtitle":"LANGUAGE DEVELOPMENT · source slide 154","duration":70.03,"cues":[{"start":0.0,"end":2.22,"text":"three .five","coverage":1.0},{"start":2.22,"end":3.24,"text":"one","coverage":1.0},{"start":4.0,"end":7.46,"text":"The course was a lot more challenging than I expected.","coverage":1.0},{"start":10.12,"end":10.84,"text":"two","coverage":1.0},{"start":11.76,"end":16.3,"text":"We can see that by far the most affordable form of transport is walking.","coverage":1.0},{"start":18.94,"end":19.66,"text":"three","coverage":1.0},{"start":20.76,"end":26.24,"text":"The risks of driving a car are considerably more significant than those of flying.","coverage":1.0},{"start":28.52,"end":29.36,"text":"four","coverage":1.0},{"start":30.22,"end":35.16,"text":"For me, flying is much more comfortable than travelling by train.","coverage":1.0},{"start":38.06,"end":43.18,"text":"five Taking a train is definitely more relaxing than driving.","coverage":1.0},{"start":46.02,"end":52.54,"text":"six Using the underground is a lot faster than travelling by bus at rush hour.","coverage":1.0},{"start":54.4,"end":60.2,"text":"seven Driving is considerably more expensive than walking.","coverage":1.0},{"start":63.14,"end":63.7,"text":"eight","coverage":1.0},{"start":64.26,"end":68.14,"text":"Cycling is absolutely the healthiest form of transport.","coverage":1.0}],"file":"fbde63a26aa690b8fb5e.js","track":0,"media":"../assets/media/e5869727902f1de10d6c2d9a82884b6b9a00cc0090f97628a3a2d3eceffcdd29.mp3"}],"../assets/media/ccf2abc25213cfa81ccf12dc76d9364893dc326313217535f5dd0ebfdf4a3b22.mp3":[{"id":"PPT_ccf2abc25213cfa8","audioId":"PPT_ccf2abc25213cfa8","title":"Book 3 · Unit 3 · RW · READING 1","subtitle":"READING 1 · source slide 43","duration":271.52,"cues":[{"start":0.0,"end":3.36,"text":"Urban Transport – Problems and Solutions","coverage":1.0},{"start":4.46,"end":8.52,"text":"Getting around today's cities can be a challenge.","coverage":1.0},{"start":9.14,"end":12.52,"text":"Many modern cities have terrible traffic congestion.","coverage":1.0},{"start":13.32,"end":18.6,"text":"It can take hours to cross the city because there are simply too many cars.","coverage":1.0},{"start":19.64,"end":25.8,"text":"Governments and businesses around the world are finding creative ways to solve these problems.","coverage":1.0},{"start":26.72,"end":29.9,"text":"In cities like Jakarta, Indonesia,","coverage":1.0},{"start":30.3,"end":34.22,"text":"commuters may spend four hours in their cars every day.","coverage":1.0},{"start":34.82,"end":35.46,"text":"The solution?","coverage":1.0},{"start":36.2,"end":39.12,"text":"Add modern technology to the familiar motorcycle.","coverage":1.0},{"start":40.38,"end":41.64,"text":"Because they are small,","coverage":1.0},{"start":42.26,"end":48.12,"text":"motorcycles can fit into small spaces and move around cars that are stopped in traffic.","coverage":1.0},{"start":49.06,"end":53.9,"text":"Motorcycle owners can earn money by taking passengers to their destinations.","coverage":1.0},{"start":54.61,"end":55.74,"text":"In 2010,","coverage":1.0},{"start":56.22,"end":62.48,"text":"a new company began to offer motorcycle rides as an online service using an app.","coverage":1.0},{"start":63.26,"end":67.8,"text":"Now, Jakarta residents can use their phones to call a motorcycle.","coverage":1.0},{"start":68.56,"end":69.9,"text":"It's cheap, safe,","coverage":1.0},{"start":70.38,"end":70.82,"text":"reliable,","coverage":1.0},{"start":71.3,"end":72.68,"text":"and most importantly,","coverage":1.0},{"start":73.3,"end":73.7,"text":"fast.","coverage":1.0},{"start":75.32,"end":79.78,"text":"Congestion is not the only transport problem in big cities, however.","coverage":1.0},{"start":80.34,"end":82.64,"text":"Building roads is expensive.","coverage":1.0},{"start":83.16,"end":87.48,"text":"Building a public transport system is even more expensive.","coverage":1.0},{"start":88.4,"end":89.3,"text":"As a result,","coverage":1.0},{"start":90.04,"end":94.8,"text":"communities on the outskirts of major cities often have few roads.","coverage":1.0},{"start":95.68,"end":100.76,"text":"The challenge is even greater when these communities are high up in the mountains.","coverage":1.0},{"start":101.56,"end":103.12,"text":"Without public transport,","coverage":1.0},{"start":103.52,"end":106.78,"text":"it is difficult for residents to reach the city center.","coverage":1.0},{"start":107.14,"end":109.56,"text":"They don't have access to jobs,","coverage":1.0},{"start":109.96,"end":110.62,"text":"education,","coverage":1.0},{"start":111.1,"end":112.06,"text":"or health care.","coverage":1.0},{"start":113.62,"end":119.52,"text":"A good way to connect mountain communities to the city center is a cable car system,","coverage":1.0},{"start":120.14,"end":122.6,"text":"which operates high above traffic.","coverage":1.0},{"start":123.4,"end":125.24,"text":"Because they use electricity,","coverage":1.0},{"start":125.9,"end":130.2,"text":"cable cars are cleaner than cars and buses that use petrol.","coverage":1.0},{"start":130.9,"end":135.4,"text":"They are also less expensive to build than buses or trains.","coverage":1.0},{"start":136.16,"end":138.88,"text":"The cars don't go very fast,","coverage":1.0},{"start":139.24,"end":142.1,"text":"only about 20 kilometers per hour,","coverage":1.0},{"start":142.46,"end":146.74,"text":"but that is often faster than the traffic on the roads below.","coverage":1.0},{"start":148.4,"end":152.08,"text":"For people who live in mountain communities with few roads,","coverage":1.0},{"start":152.6,"end":154.72,"text":"cable cars make a big difference.","coverage":1.0},{"start":155.64,"end":164.0,"text":"One teacher in Bogota, Colombia reported that it used to take him more than two hours to get to work,","coverage":1.0},{"start":164.46,"end":168.5,"text":"often arriving at the school after his students.","coverage":1.0},{"start":169.46,"end":173.32,"text":"With the cable car, he can be there in 40 minutes.","coverage":1.0},{"start":174.18,"end":177.76,"text":"Cable cars can also bring unexpected changes.","coverage":1.0},{"start":178.76,"end":180.58,"text":"Although they are built for residents,","coverage":1.0},{"start":181.2,"end":183.4,"text":"tourists love cable cars.","coverage":1.0},{"start":184.24,"end":186.54,"text":"In cities like Medellin, Colombia,","coverage":1.0},{"start":186.98,"end":193.5,"text":"and La Paz, Bolivia, they are bringing tourists to areas of the city that were too far away,","coverage":1.0},{"start":193.8,"end":194.98,"text":"or in some cases,","coverage":1.0},{"start":195.58,"end":197.9,"text":"considered too dangerous for visitors.","coverage":1.0},{"start":198.7,"end":201.08,"text":"Now tourists visit these areas,","coverage":1.0},{"start":201.48,"end":204.46,"text":"where they spend money in shops and restaurants.","coverage":1.0},{"start":206.14,"end":206.64,"text":"Finally,","coverage":1.0},{"start":207.08,"end":211.96,"text":"the best way to get around a city with bad traffic is often walking.","coverage":1.0},{"start":212.88,"end":216.6,"text":"But walking in a city on a mountain is hard work.","coverage":1.0},{"start":217.46,"end":221.42,"text":"Another creative solution is the outdoor escalator.","coverage":1.0},{"start":222.44,"end":223.44,"text":"In Medellin,","coverage":1.0},{"start":223.96,"end":227.28,"text":"residents once had to climb uphill for half an hour,","coverage":1.0},{"start":227.8,"end":231.38,"text":"an equivalent of 28 stories, to their homes.","coverage":1.0},{"start":232.24,"end":232.7,"text":"Today,","coverage":1.0},{"start":233.04,"end":236.34,"text":"the escalator ride takes just six minutes.","coverage":1.0},{"start":237.38,"end":241.44,"text":"The world's longest outdoor elevator is in Hong Kong.","coverage":1.0},{"start":242.22,"end":250.66,"text":"It is 800 meters and serves almost 80 ,000 people every day, including many tourists.","coverage":1.0},{"start":252.22,"end":256.5,"text":"Traffic congestion will continue to be a problem in big cities.","coverage":1.0},{"start":257.16,"end":257.64,"text":"However,","coverage":1.0},{"start":258.26,"end":263.52,"text":"creative solutions like these can help people get around cities more easily.","coverage":1.0},{"start":264.26,"end":269.54,"text":"They can also reduce pollution and traffic and attract tourists.","coverage":1.0}],"file":"fc11dc754d56cd7188dd.js","track":0,"media":"../assets/media/ccf2abc25213cfa81ccf12dc76d9364893dc326313217535f5dd0ebfdf4a3b22.mp3"}]};